.dashboard-kpis { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); border-top:1px solid var(--line); }.dashboard-kpi { min-height:84px; padding:12px 18px 0; display:flex; flex-direction:column; justify-content:center; border-right:1px solid var(--line); }.dashboard-kpi:first-child { padding-left:0; }.dashboard-kpi:last-child { border-right:0; }.dashboard-kpi span { color:var(--muted); font-size:8px; }.dashboard-kpi strong { margin:4px 0 2px; font:700 22px var(--font-display); letter-spacing:-.03em; }.dashboard-kpi small { color:var(--muted); font-size:8px; }.dashboard-kpi.good strong { color:#1e7b57; }
.dashboard-board { overflow:hidden; border:1px solid var(--line); background:#fff; box-shadow:0 12px 30px rgba(27,35,31,.04); }.dashboard-toolbar { min-height:67px; padding:12px 16px 12px 19px; display:flex; align-items:center; justify-content:space-between; gap:18px; border-bottom:1px solid var(--line); }.dashboard-toolbar > div:first-child { display:flex; flex-direction:column; gap:3px; }.dashboard-toolbar > div:first-child strong { font:700 14px var(--font-display); text-transform:none; }.dashboard-toolbar > div:first-child span { color:var(--muted); font-size:8px; }.dashboard-tools { display:flex; align-items:center; gap:8px; }
.dashboard-operation-tabs { min-height:72px; padding:0 18px; display:grid; grid-auto-flow:column; grid-auto-columns:minmax(170px,1fr); overflow-x:auto; border-bottom:1px solid var(--line); background:#fafbf9; }.dashboard-operation-tabs button { position:relative; padding:13px 16px 11px; display:grid; grid-template-columns:1fr auto; gap:3px 10px; align-content:center; border:0; border-bottom:3px solid transparent; background:transparent; color:#68736d; text-align:left; cursor:pointer; }.dashboard-operation-tabs button + button { border-left:1px solid #e7ebe7; }.dashboard-operation-tabs button span { font:700 11px var(--font-display); }.dashboard-operation-tabs button small { color:var(--muted); font-size:7px; }.dashboard-operation-tabs button b { grid-column:2; grid-row:1 / span 2; align-self:center; color:#4d5b54; font-size:9px; }.dashboard-operation-tabs button.active { border-bottom-color:#315c9b; background:#eef3fa; color:#284e86; }.dashboard-operation-tabs button.active b { color:#315c9b; }
.dashboard-search { width:225px; min-height:34px; padding:0 9px; display:flex; align-items:center; gap:7px; border:1px solid var(--line); border-radius:7px; background:#fafbf8; color:var(--muted); }.dashboard-search input { width:100%; border:0; outline:0; background:transparent; font-size:9px; }
.dashboard-export { min-height:34px; padding:0 10px; display:inline-flex; align-items:center; gap:6px; border:1px solid #b9cbe4; border-radius:7px; background:#f3f7fc; color:#315c9b; font-size:8px; font-weight:750; cursor:pointer; white-space:nowrap; }.dashboard-export:disabled { opacity:.55; cursor:wait; }.dashboard-export-error { min-height:42px; padding:8px 14px; display:flex; align-items:center; gap:8px; border-bottom:1px solid #efc8c3; background:#fff2f0; color:#a3433d; font-size:8px; }.dashboard-export-error button { margin-left:auto; border:0; background:transparent; color:inherit; font-size:7px; font-weight:750; cursor:pointer; }
.dashboard-filters { display:flex; gap:3px; }.dashboard-filters button { min-height:32px; padding:0 10px; border:0; border-radius:6px; background:transparent; color:var(--muted); font-size:8px; font-weight:700; cursor:pointer; }.dashboard-filters button.active { background:#e8eef7; color:#284e86; }
.machine-dashboard-grid { padding:14px; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; background:#f2f4f1; }.machine-dashboard-card { min-width:0; border:1px solid #cfd6d1; border-top:3px solid #315c9b; background:#fff; }.machine-dashboard-card.passive { border-top-color:#aeb5b0; opacity:.78; }
.machine-dashboard-card header button { width:100%; min-height:47px; padding:8px 11px; display:flex; align-items:center; justify-content:space-between; border:0; background:#315c9b; color:#fff; text-align:left; cursor:pointer; }.machine-dashboard-card.passive header button { background:#6f7772; }.machine-dashboard-card header button > span:first-child { display:flex; align-items:baseline; gap:8px; }.machine-dashboard-card header b { color:#c9d8ee; font-size:8px; letter-spacing:.08em; }.machine-dashboard-card header strong { font:700 12px var(--font-display); }.machine-dashboard-card header button > span:last-child { display:flex; align-items:center; gap:5px; color:#dbe5f4; font-size:8px; font-weight:700; }
.operation-resource-card header > div { width:100%; min-height:47px; padding:8px 11px; display:flex; align-items:center; justify-content:space-between; gap:10px; background:#315c9b; color:#fff; }.operation-resource-card header > div > span { display:flex; align-items:baseline; gap:8px; }.operation-resource-card header em { padding:4px 6px; border-radius:4px; background:rgba(255,255,255,.14); color:#e8eef7; font-size:7px; font-style:normal; font-weight:750; }.operation-resource-card.drilling { border-top-color:#c56936; }.operation-resource-card.drilling header > div { background:#a9552b; }.operation-resource-card.deburring { border-top-color:#218166; }.operation-resource-card.deburring header > div { background:#257359; }.operation-resource-card.gkm { border-top-color:#49729a; }.operation-resource-card.gkm header > div { background:#456985; }
.machine-dashboard-table { overflow:auto; }.machine-dashboard-row { min-width:620px; min-height:35px; padding:0 10px; display:grid; grid-template-columns:58px 1.15fr .65fr .75fr .72fr 1fr; align-items:center; border-bottom:1px solid #e6e9e5; font-size:8px; font-variant-numeric:tabular-nums; }.machine-dashboard-row > * { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }.machine-dashboard-row.head { min-height:29px; background:#f1d0bc; color:#56301e; font-size:7px; font-weight:800; text-transform:uppercase; letter-spacing:.035em; }.machine-dashboard-row.current { background:#e4f5e4; }.machine-dashboard-row.planned:nth-child(odd) { background:#f7f8f6; }.machine-dashboard-row strong { font-size:8px; }.machine-dashboard-row i { padding:3px 5px; border-radius:4px; background:#23835d; color:#fff; font-size:7px; font-style:normal; font-weight:800; }.trace-ready { color:#285c48; font-weight:750; }
.machine-dashboard-row.operation { grid-template-columns:58px 1fr 1.05fr .65fr .85fr .85fr; }.machine-dashboard-row.operation.current { background:#e4f5e4; }.operation-resource-empty { min-height:112px; padding:20px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px; background:#fafbf9; text-align:center; }.operation-resource-empty strong { font-size:9px; }.operation-resource-empty span { color:var(--muted); font-size:8px; }
.machine-dashboard-empty { width:100%; min-height:112px; padding:20px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px; border:0; background:#fafbf9; color:var(--muted); cursor:pointer; }.machine-dashboard-empty span { color:var(--ink); font-size:9px; font-weight:700; }.machine-dashboard-empty small { font-size:8px; }.machine-dashboard-empty svg { margin-top:5px; }
.machine-dashboard-empty small { max-width:430px; line-height:1.45; text-align:center; }.machine-dashboard-empty.critical,.machine-dashboard-diagnostic.critical { background:#fff5f3; }.machine-dashboard-empty.warning,.machine-dashboard-diagnostic.warning { background:#fff9ee; }.machine-dashboard-diagnostic { width:100%; min-height:48px; padding:8px 11px; display:flex; align-items:center; justify-content:space-between; gap:10px; border:0; border-top:1px solid var(--line); background:#f5f7f4; text-align:left; cursor:pointer; }.machine-dashboard-diagnostic > span { display:flex; flex-direction:column; gap:2px; }.machine-dashboard-diagnostic strong { font-size:8px; }.machine-dashboard-diagnostic small { color:var(--muted); font-size:7px; line-height:1.4; }
.machine-dashboard-card footer { min-height:34px; padding:0 11px; display:flex; align-items:center; justify-content:space-between; border-top:1px solid #dfe4df; background:#fbfcfa; color:var(--muted); font-size:8px; }.machine-dashboard-card footer strong { color:var(--ink); font-size:8px; }
.dashboard-no-results { min-height:330px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:6px; color:var(--muted); }.dashboard-no-results strong { color:var(--ink); font-size:10px; }.dashboard-no-results span { font-size:8px; }
.dashboard-audit { border:1px solid var(--line); background:#fff; }.dashboard-audit summary { min-height:68px; padding:13px 17px; display:flex; align-items:center; justify-content:space-between; gap:20px; cursor:pointer; list-style:none; }.dashboard-audit summary::-webkit-details-marker { display:none; }.dashboard-audit summary > span:first-child { display:grid; grid-template-columns:22px 1fr; gap:2px 8px; align-items:center; }.dashboard-audit summary > span:first-child svg { grid-row:1/3; color:#b9652f; }.dashboard-audit summary strong { font:700 12px var(--font-display); }.dashboard-audit summary small { color:var(--muted); font-size:8px; }
.dashboard-audit-counts { display:flex; align-items:center; gap:6px; }.dashboard-audit-counts b,.dashboard-audit-counts i,.dashboard-audit-counts em { padding:5px 8px; border-radius:99px; font-size:7px; font-style:normal; }.dashboard-audit-counts b { background:#ffebe8; color:#a9433d; }.dashboard-audit-counts i { background:#fff3df; color:#96631e; }.dashboard-audit-counts em { background:#edf3f5; color:#33717c; }
.dashboard-audit-body { border-top:1px solid var(--line); }.dashboard-audit-body > p { margin:0; padding:11px 16px; border-bottom:1px solid var(--line); background:#fafbf9; color:var(--muted); font-size:8px; }.dashboard-finding-list { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }.dashboard-finding { min-height:92px; padding:14px 15px; display:grid; grid-template-columns:19px minmax(0,1fr) auto; gap:9px; align-items:start; border-right:1px solid #edf0eb; border-bottom:1px solid #edf0eb; }.dashboard-finding:nth-child(2n) { border-right:0; }.dashboard-finding > svg { color:#33717c; }.dashboard-finding.critical > svg { color:#c84c43; }.dashboard-finding.warning > svg { color:#aa6d24; }.dashboard-finding strong { font-size:9px; }.dashboard-finding p { margin:4px 0 0; color:var(--muted); font-size:8px; line-height:1.45; }.dashboard-finding > button { align-self:center; min-height:29px; padding:0 8px; display:flex; align-items:center; gap:5px; border:1px solid var(--line); border-radius:6px; background:#fff; color:#53605a; font-size:7px; font-weight:700; cursor:pointer; }.dashboard-audit-clear { padding:22px; display:flex; align-items:center; gap:7px; color:#1e7b57; font-size:9px; }
@media (max-width:1280px) { .machine-dashboard-grid { grid-template-columns:1fr; }.dashboard-toolbar { align-items:flex-start; flex-direction:column; }.dashboard-tools { width:100%; flex-wrap:wrap; }.dashboard-search { flex:1; }.dashboard-operation-tabs { overflow-x:auto; } }

/* Product tour */
.tour-overlay { position:fixed; inset:0; z-index:80; padding:22px; display:flex; align-items:flex-end; justify-content:flex-end; pointer-events:none; background:transparent; }
.tour-card { width:410px; min-height:268px; padding:25px 26px 22px; display:flex; flex-direction:column; pointer-events:auto; background:#fff; border:1px solid #cfdad6; border-top:4px solid #087a78; box-shadow:0 18px 50px rgba(14,23,19,.22); animation:tour-rise .22s ease-out; }.tour-progress { margin-bottom:23px; display:grid; grid-template-columns:repeat(7,1fr); gap:5px; }.tour-progress i { height:3px; border-radius:2px; background:#e3e8e4; }.tour-progress i.active { background:#087a78; }.tour-card > span { color:#087a78; font-size:8px; font-weight:800; letter-spacing:.14em; }.tour-card h2 { margin:7px 0 8px; font:700 24px var(--font-display); letter-spacing:-.035em; }.tour-card p { margin:0; color:#59635e; font-size:11px; line-height:1.65; }.tour-actions { margin-top:auto; padding-top:24px; display:flex; justify-content:flex-end; gap:7px; }.tour-actions button { min-height:35px; padding:0 11px; display:flex; align-items:center; justify-content:center; gap:6px; border-radius:7px; font-size:9px; font-weight:700; cursor:pointer; }.tour-skip { margin-right:auto; border:0; background:transparent; color:var(--muted); }.tour-back { border:1px solid var(--line); background:#fff; color:var(--muted); }.tour-next { min-width:90px; border:0; background:#087a78; color:#fff; }

/* Shift record editing */
