.capacity-bar { height:9px; display:flex; overflow:hidden; border-radius:2px; background:#e8ece8; }.capacity-bar i { height:100%; display:block; }.capacity-bar i.normal { background:#315c79; }.capacity-bar i.overtime { background:#d36b22; }
