.process-filter-tabs { min-height:50px; border-bottom:1px solid var(--line); }
.process-filter-tabs button { min-height:31px; padding:0 10px; display:flex; align-items:center; gap:6px; border-bottom:2px solid transparent; color:#6b766f; font-size:8px; font-weight:750; }
