.journey-calendar-scale { min-width:610px; display:grid; grid-template-rows:21px 27px; }.journey-week-scale,.journey-day-scale { display:grid; grid-template-columns:repeat(var(--journey-days),minmax(0,1fr)); }.journey-week-scale { border-bottom:1px solid #dce3de; }.journey-week-scale b { min-width:0; padding:5px 5px 0; overflow:hidden; border-left:1px solid #d4dcd6; color:#087a78; font-size:6px; letter-spacing:.05em; text-overflow:ellipsis; white-space:nowrap; }.journey-day-scale small { position:relative; display:grid; place-items:center; border-left:1px solid #e1e7e2; color:#68746d; font-size:6.5px; white-space:nowrap; }.journey-day-scale small.sunday { background:#eef1ee; color:#ad5b4b; }.journey-day-scale small.today { background:#e2f2ee; color:#087a78; font-weight:900; }.journey-day-scale small.today:after { content:"BUGÜN"; position:absolute; top:100%; left:50%; z-index:5; padding:1px 3px; background:#087a78; color:#fff; font-size:5px; letter-spacing:.04em; transform:translateX(-50%); }
