.process-gantt-batch.gtm,.process-gantt-batch.diameter-grinding,.process-gantt-batch.form-grinding,.process-gantt-batch.measuring,.process-gantt-batch.milling,.process-gantt-batch.final-inspection,.process-gantt-batch.filter-visual{background:#d9e9ed;border-color:#517880;color:#203c48}
