.flow-settings-fields td small { display: block; color: var(--muted); font-size: 10px; margin-top: 5px; }
.flow-settings-fields table { min-width: 1040px; font-size: 12px; }
.flow-settings-fields .settings-disclosure table { min-width: 640px; }
.flow-settings-fields th { font-size: 10px; letter-spacing: .045em; }
.flow-activation-status { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px 20px; margin-bottom: 20px; padding: 16px 18px; border: 1px solid #cfe1d9; border-left: 3px solid #087a78; border-radius: 8px; background: #f3f9f6; font-size: 12px; line-height: 1.6; }
.flow-activation-status strong { font-size: 13px; color: #075f5c; }
.flow-activation-status span:last-child { flex-basis: 100%; color: var(--muted); }
.settings-disclosure { border: 1px solid var(--line); border-radius: 8px; margin: 18px 0; overflow: hidden; }
.settings-disclosure > summary { padding: 14px 16px; background: #f7f9f6; cursor: pointer; font-size: 13px; font-weight: 650; }
.settings-disclosure > .settings-help { margin: 16px 20px 0; }
.settings-toggle { display: flex; align-items: center; gap: 10px; margin: 24px 0 12px; font-size: 13px; font-weight: 650; }
.settings-field { display: grid; width: min(320px, 100%); gap: 8px; font-size: 12px; font-weight: 650; }
.flow-calendar-row { display: flex; gap: 10px; flex-wrap: wrap; margin: 12px 0; }
.flow-setup-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 18px; margin: 22px 0 26px; }
.flow-setup-grid label { display: grid; align-content: start; gap: 8px; font-size: 12px; font-weight: 600; }
.flow-setup-grid small { color: var(--muted); font-size: 10px; font-weight: 400; }
.settings-save-actions { padding-top: 20px; margin-top: 24px; border-top: 1px solid var(--line); justify-content: flex-end; }
.flow-review { padding: 18px 20px; border: 1px solid #cfe1d9; border-radius: 8px; margin-top: 20px; background: #f5faf7; }
.flow-review h3 { margin: 0 0 10px; font-size: 15px; }
.settings-message { padding: 12px 16px; border-radius: 7px; background: #f3f8f5; font-size: 13px; line-height: 1.6; }
.settings-message.error { background: #fff1ed; color: #9e3524; }
.settings-fallback { margin: 20px 0; background: #fff; }
.piston-settings-page .process-wait-settings { padding: 20px; border: 0; box-shadow: none; margin: 0; border-radius: 0; }
.piston-settings-page .process-wait-settings h3 { margin: 0 0 10px; font-size: 16px; }
.piston-settings-page .process-wait-settings p { font-size: 13px; color: var(--muted); line-height: 1.65; }
.piston-settings-page .process-wait-settings th, .piston-settings-page .process-wait-settings td { padding: 13px 16px; }
.piston-settings-page .process-wait-settings table { min-width: 520px; font-size: 12px; margin: 18px 0; }
.piston-settings-page .process-wait-settings .table-scroll { overflow-x: auto; }
@media (max-width: 760px) {
  .flow-settings-panel { padding: 16px; }
  .flow-settings-panel .settings-panel-heading { flex-direction: column; gap: 16px; }
  .flow-setup-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .settings-save-actions { flex-wrap: wrap; }
  .settings-save-actions button { flex: 1; }
  .piston-settings-page .settings-tabs > button { padding: 12px; }
}
@media (prefers-reduced-motion: reduce) { .flow-settings-panel button, .piston-settings-page .process-wait-settings button { transition: none; } }


.parameter-gap-action { cursor: pointer; font: inherit; text-align: left; }
.parameter-gap-action:hover { text-decoration: underline; }
.parameter-gap-dialog { width: min(660px, calc(100vw - 32px)); }
