/* Çubuk Filtre · Sevkiyat Planı (günlük Sipariş / Teslimat / Açık) */
.dispatch-plan-state { padding:4px 9px; border-radius:999px; font-size:10px; font-weight:700; }
.dispatch-plan-state.preview { background:var(--accent-soft); color:#a8431c; }
.dispatch-plan-state.saved { background:#eaf5ef; color:var(--green); }
