.dispatch-plan-note { margin:0; padding:10px 16px; border-bottom:1px solid var(--line); color:var(--muted); font-size:11px; line-height:1.5; }
.dispatch-plan-error { margin:16px; padding:11px 13px; display:flex; align-items:center; gap:8px; border-left:2px solid var(--red); background:#fdf1ef; color:#8f3029; font-size:12px; }
.dispatch-plan-metrics { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); padding:18px 16px; border-bottom:1px solid var(--line); }
.dispatch-plan-metrics > div { display:flex; flex-direction:column; gap:5px; padding:0 18px; border-left:1px solid var(--line); }
