.dispatch-plan-metrics strong { font:700 22px var(--font-display); letter-spacing:-.03em; font-variant-numeric:tabular-nums; }
.dispatch-plan-metrics span { color:var(--muted); font-size:10px; }
.dispatch-plan-metrics .open strong { color:#b04c3f; }
.dispatch-plan-table-wrap { max-height:620px; overflow:auto; }
.dispatch-plan-table { width:100%; border-collapse:separate; border-spacing:0; font-size:12px; font-variant-numeric:tabular-nums; }
.dispatch-plan-table th,.dispatch-plan-table td { padding:7px 10px; border-bottom:1px solid #edf0ec; text-align:right; white-space:nowrap; }
.dispatch-plan-table thead th { position:sticky; z-index:2; background:#f8faf7; color:#66716b; font-size:10px; font-weight:700; }
