.dispatch-plan-table tr.today td,.dispatch-plan-table tr.today th.day { background:var(--accent-soft); }
.dispatch-plan-table tbody tr:not(.week):hover td { background:#f3faf7; }
.dispatch-plan-table tfoot td,.dispatch-plan-table tfoot th { position:sticky; bottom:0; border-top:1px solid var(--line); border-bottom:0; background:#f8faf7; font-weight:700; }
