.dispatch-plan-apply { padding:14px 16px 16px; border-top:1px solid var(--line); background:#fbfcfa; }
.dispatch-plan-apply summary { cursor:pointer; color:#53615a; font-size:11px; font-weight:700; }
.dispatch-plan-apply ul { margin:10px 0 0; padding:0; list-style:none; display:grid; grid-template-columns:repeat(auto-fill,minmax(250px,1fr)); gap:6px 18px; }
.dispatch-plan-apply li { display:flex; align-items:center; gap:8px; font-size:11px; }
.dispatch-plan-apply li code { padding:2px 6px; border-radius:4px; background:#eef1ec; font-size:10px; }
.dispatch-plan-apply li span { color:var(--muted); }
.dispatch-plan-apply li b { margin-left:auto; font-weight:650; }
.dispatch-plan-apply > p { margin:12px 0; color:var(--muted); font-size:11px; line-height:1.5; }
.dispatch-plan-apply .drawer-actions { justify-content:flex-end; }
.dispatch-plan-table td.planned { color:#187057; font-weight:650; }
.dispatch-plan-table td.surplus { color:#187057; }
.monthly-plan .dispatch-plan-table-wrap { max-height:none; }
.monthly-plan .dispatch-plan-table thead tr:first-child th { height:38px; }
