.stock-view-actions button.active { border-color:var(--accent); color:#a8431c; }
.stock-view-status { margin:0; padding:10px 16px; border-bottom:1px solid var(--line); border-left:2px solid #b68532; background:#fff8ec; color:#79531e; font-size:11px; line-height:1.5; }
.stock-view-status.ok { border-left-color:var(--green); background:#eef7f2; color:#1c5f45; }
.stock-view-issues { padding:10px 16px; border-bottom:1px solid var(--line); font-size:11px; color:var(--muted); }
.stock-view-issues summary { cursor:pointer; color:#53615a; font-weight:700; }
.stock-view-issues ul { margin:8px 0; padding-left:18px; line-height:1.6; }
.stock-view-issues p { margin:6px 0 0; line-height:1.5; }
.process-stock-group { border-bottom:1px solid var(--line); }
.process-stock-group > header { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:10px 24px; padding:14px 16px 12px; background:#fbfcfa; border-bottom:1px solid var(--line); }
.process-stock-group h3 { margin:0; font:700 13px var(--font-display); }
.process-stock-group dl { margin:0; display:flex; gap:8px; }
