.process-stock-group dt { color:var(--muted); font-size:10px; }
.process-stock-group dd { margin:0; font-size:12px; font-weight:700; font-variant-numeric:tabular-nums; }
.process-stock-group dl .low { border-color:#ecc4be; background:#fdf1ef; } .process-stock-group dl .low dd { color:#b04c3f; }
.process-stock-group dl .high { border-color:#ecd9b0; background:#fff8ec; } .process-stock-group dl .high dd { color:#8a611c; }
.process-stock-group dl .ok { border-color:#cfe1d8; background:#eef7f2; } .process-stock-group dl .ok dd { color:#1c5f45; }
.process-stock-view .dispatch-plan-table-wrap { max-height:none; }
.process-stock-view .dispatch-plan-table th.day { min-width:170px; }
.process-stock-view .dispatch-plan-table th.day small,.process-stock-view .dispatch-plan-table thead th small,.process-stock-view .dispatch-plan-table td small { display:block; margin:2px 0 0; color:var(--muted); font-size:9px; font-weight:500; }
.process-stock-view .dispatch-plan-table thead tr:first-child th { height:44px; }
.stock-total-row td,.stock-total-row th.day { background:#f8faf7; }
.stock-total-row td strong { font-size:13px; }
.stock-total-row td.low strong,.stock-total-row td.low small { color:#b04c3f; }
.stock-total-row td.high strong,.stock-total-row td.high small { color:#8a611c; }
