.process-stock-settings h2 { margin:0 0 10px; font:700 14px var(--font-display); }
.stock-settings-note { margin:0 0 8px; max-width:900px; color:var(--muted); font-size:11px; line-height:1.55; }
.process-stock-settings > .field { max-width:190px; margin:12px 0; }
