.filter-data-card .filter-data-toolbar .field { font-size:10px; }
.filter-data-card .filter-data-toolbar input,.filter-data-card .filter-data-toolbar select { min-width:200px; min-height:35px; font-size:12px; border:1px solid #d7dcd6; border-radius:6px; background:#fff; }
.filter-data-card table { width:100%; border-collapse:collapse; font-size:12px; }
.filter-data-card table th { padding:9px 10px; border-bottom:1px solid var(--line); background:#f8faf7; color:#66716b; font-size:10px; font-weight:700; text-align:left; white-space:nowrap; }
.filter-data-card table td { padding:6px 10px; border-bottom:1px solid #edf0ec; }
.filter-data-card table td:first-child { font-weight:650; }
.filter-data-card table tbody tr:hover td { background:#f3faf7; }
