.filter-data-card td.filter-data-missing { color:#8a611c; font-size:11px; line-height:1.5; }
.filter-data-card td.filter-data-complete { color:#1c5f45; font-size:11px; }
.shift-report .dispatch-plan-table thead th.day { vertical-align:bottom; }
.dispatch-plan-dialog { width:min(1180px,calc(100vw - 32px)); max-height:calc(100vh - 32px); overflow:auto; display:grid; gap:14px; border-radius:13px; }
