.dispatch-plan-dialog .surface-toolbar > div:first-child { margin-right:auto; }

/* Monthly customer review and physical stock reconciliation. */
.monthly-plan .dispatch-plan-table { font-size:13px; }
.monthly-plan .dispatch-plan-table tbody th { text-align:left; font-size:13px; letter-spacing:0; text-transform:none; font-weight:650; }
.monthly-plan .dispatch-plan-table small { display:block; margin-top:5px; color:var(--muted); font-size:11px; font-weight:400; }
.monthly-plan .dispatch-plan-table td,.monthly-plan .dispatch-plan-table tbody th { padding:12px 16px; }
