.monthly-plan > .drawer-actions { padding:16px; }
.monthly-plan label.dispatch-plan-note { display:flex; gap:10px; align-items:flex-start; }
.monthly-plan label.dispatch-plan-note input { margin-top:5px; flex-shrink:0; }

