import type { Metadata } from "next";
import { ClerkProvider } from "@clerk/nextjs";
import { trTR } from "@clerk/localizations/tr-TR";
import { ClerkApiProvider } from "@/lib/api";
import "./globals.css";
import "./styles/tokens.css";
import "./styles/ui.css";
import "./styles/shell.css";
import "./styles/planning.css";
import "./styles/journey.css";
import "./styles/orders.css";
import "./styles/overview.css";
import "./styles/stocks.css";
import "./styles/machines.css";
import "./styles/parameters.css";
import "./styles/settings.css";
import "./styles/scenarios.css";
import "./styles/feedback.css";
import "./styles/dialogs.css";
import "./styles/overlays.css";

const clerkLocalization = {
  ...trTR,
  signIn: {
    ...trTR.signIn,
    start: {
      ...trTR.signIn?.start,
      titleCombined: "{{applicationName}} hesabına giriş yapın",
      subtitleCombined: "Devam etmek için şirket e-posta adresinizi kullanın",
    },
  },
};

export const metadata: Metadata = {
  title: "Selsa Planlama",
  description: "Sonlu kapasite üretim planlama çalışma alanı",
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="tr">
      <body><ClerkProvider localization={clerkLocalization}><ClerkApiProvider>{children}</ClerkApiProvider></ClerkProvider></body>
    </html>
  );
}

