/* Şarj Yolculuğu (UI overhaul, Sade). Main object: the selected charge's journey,
   with the charge list on the left. Counts live in the page title row. */

/* Frame */
.process-workspace { margin: 0 20px 20px; padding: 0; border: 1px solid var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); box-shadow: none; }
.process-workspace-head { min-height: 52px; padding: 8px 14px; gap: 12px; border-bottom: 1px solid var(--ui-line); }
.process-mode-tabs { padding: 0; gap: 2px; border: 0; background: transparent; }
.process-mode-tabs button { min-height: 36px; padding: 0 12px; border-bottom: 2px solid transparent; border-radius: 0; color: var(--ui-ink-2); font: 500 var(--ui-text-sm) var(--ui-font); }
.process-mode-tabs button:hover { color: var(--ui-ink); }
.process-mode-tabs button.active { border-bottom-color: var(--ui-ink); background: transparent; color: var(--ui-ink); font-weight: 650; box-shadow: none; }
.process-mode-tabs button small, .process-mode-tabs button b { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }

/* Counts in the title row */
.page-bar-slot .journey-kpis { min-height: 0; display: flex; flex-wrap: wrap; align-items: center; row-gap: 8px; border: 0; }
.page-bar-slot .journey-kpis .metric.compact { padding: 0 14px; border-right: 1px solid var(--ui-line); }
.page-bar-slot .journey-kpis .metric.compact:first-child { padding-left: 0; }
.page-bar-slot .journey-kpis .metric.compact:last-child { border-right: 0; }
.page-bar-slot .journey-kpis .metric.compact strong { font-size: var(--ui-text-md); }

/* Status line + gap explanations */
.process-workspace > .ui-status-line { margin: 12px 14px 0; }
.journey-gap-toggle { min-height: 28px; font-size: var(--ui-text-xs); }
.journey-gap-list { margin: 8px 14px 0; padding: 8px 12px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius-sm); background: var(--ui-surface-2); }
.journey-gap-list p { margin: 0; padding: 6px 0; display: flex; flex-wrap: wrap; gap: 2px 10px; border-bottom: 1px solid var(--ui-line); font-size: var(--ui-text-xs); }
.journey-gap-list p:last-child { border-bottom: 0; }
.journey-gap-list strong { color: var(--ui-ink); }
.journey-gap-list span { color: var(--ui-ink-2); }
.process-inline-notice { min-height: 36px; margin: 12px 14px 0; padding: 7px 12px; border: 1px solid var(--ui-line); border-left: 3px solid var(--ui-warn); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-xs); }
.process-inline-notice.danger { border-left-color: var(--ui-danger); background: var(--ui-surface); color: var(--ui-ink); }
.process-inline-notice svg { color: var(--ui-warn); flex: 0 0 auto; }
.process-inline-notice.danger svg { color: var(--ui-danger); }
.journey-canvas .process-inline-notice { margin: 12px 0 0; }

/* Layout: list | journey */
.journey-layout { margin: 12px 0 0; min-height: 0; grid-template-columns: 280px minmax(0, 1fr); border: 0; border-top: 1px solid var(--ui-line); }
.journey-index { border-right-color: var(--ui-line); background: var(--ui-surface-2); }
.journey-index-head { min-height: 44px; padding: 0 14px; border-bottom-color: var(--ui-line); }
.journey-index-head span { color: var(--ui-ink-3); font: 600 var(--ui-text-xs) var(--ui-font); letter-spacing: 0; }
.journey-index-head strong { color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 500; }
.journey-filters { padding: 10px 12px; gap: 8px; border-bottom: 1px solid var(--ui-line); }
.journey-filters label, .journey-filters span { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.journey-filters select, .journey-filters input { min-height: var(--ui-control-h); border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-sm); }
.journey-filters button { border-radius: var(--ui-radius-sm); font-size: var(--ui-text-xs); }
.journey-job-list { max-height: calc(100vh - 330px); min-height: 360px; padding: 0 0 10px; }
.journey-job-list > button { min-height: 60px; padding: 10px 12px 9px 14px; border-bottom-color: var(--ui-line); }
.journey-job-list > button:hover { background: var(--ui-surface); }
.journey-job-list > button.active { background: var(--ui-surface); box-shadow: inset 3px 0 var(--ui-ink); }
.journey-job-list > button strong { font-size: var(--ui-text-sm); }
.journey-job-list > button small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); line-height: 1.35; }

/* Status chips in the list: outline, colour only for state */
.journey-job-list em,
.journey-job-list em.wip,
.journey-job-list em.current-turning,
.journey-job-list em.journey-status-planned,
.journey-job-list em.journey-status-running,
.journey-job-list em.journey-status-finishing,
.journey-job-list em.journey-status-delivered { max-width: 150px; padding: 2px 7px; border: 1px solid var(--ui-line-strong); border-radius: 999px; background: transparent; color: var(--ui-ink-2); font-size: 10px; font-weight: 600; letter-spacing: 0; text-transform: none; }
.journey-job-list em.journey-status-waiting { border-color: color-mix(in srgb, var(--ui-warn) 45%, transparent); color: var(--ui-warn); background: transparent; }
.journey-job-list em.journey-status-attention { border-color: color-mix(in srgb, var(--ui-danger) 45%, transparent); background: var(--ui-danger-soft); color: var(--ui-danger); }

/* Selected charge heading */
.journey-canvas { padding: 16px 18px; }
.journey-heading { min-width: 0; flex-wrap: wrap; align-items: flex-start; gap: 14px 24px; padding-bottom: 14px; border-bottom-color: var(--ui-line); }
.journey-heading > div:first-child > span,
.journey-ready span,
.journey-detail-panel > div:first-child > span { color: var(--ui-ink-3); font: 600 var(--ui-text-xs) var(--ui-font); letter-spacing: 0; }
.journey-title-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; }
.journey-heading h3 { margin: 4px 0 4px; font: 650 22px/1.2 var(--ui-font-display); letter-spacing: -0.01em; }
.journey-heading p { color: var(--ui-ink-2); font-size: var(--ui-text-sm); }
.journey-heading .process-family { padding: 1px 7px; border: 1px solid var(--ui-line-strong); border-radius: 999px; background: transparent; color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 600; }
.journey-heading-actions { flex-wrap: wrap; align-items: center; gap: 8px; }
.journey-heading-actions > .journey-complete-action { min-width: 0; align-self: center; }
.journey-complete-hint { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.journey-manual-actions { display: flex; flex-wrap: wrap; gap: 6px; }
.journey-ready { padding: 6px 0 6px 14px; border-left: 1px solid var(--ui-line); background: transparent; text-align: left; }
.journey-ready strong { color: var(--ui-ink); font: 650 var(--ui-text-md) var(--ui-font); }
.journey-ready small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }

/* Readiness strip: neutral steps, the waiting/ready mark keeps meaning */
.journey-readiness-strip { margin: 14px 0 0; border: 1px solid var(--ui-line); border-radius: var(--ui-radius-sm); background: var(--ui-surface); }
.journey-readiness-step { min-height: 76px; padding: 10px; border-right-color: var(--ui-line); }
.journey-readiness-step > span { color: var(--ui-ink-2); }
.journey-readiness-step small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.journey-readiness-step strong { color: var(--ui-ink); font-size: var(--ui-text-sm); }
.journey-readiness-step em { color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-style: normal; }
.journey-readiness-step b { font-size: 10px; }
.journey-history-notice { margin: 12px 0 0; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }

/* Timeline controls and legend */
.journey-gantt-controls { margin-top: 14px; flex-wrap: wrap; gap: 6px; }
.journey-gantt-controls > button,
.journey-gantt-controls > label,
.journey-zoom-control { min-height: var(--ui-control-h); border-color: var(--ui-line); border-radius: var(--ui-radius-sm); color: var(--ui-ink-2); }
.journey-gantt-controls input { font-size: var(--ui-text-sm); }
.journey-zoom-control small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.journey-legend-menu .ui-menu-panel { min-width: 260px; padding: 10px 12px; }
.journey-legend-menu .journey-color-legend { margin: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 14px; font-size: var(--ui-text-xs); }

/* Timeline readable */
.journey-gantt { border-color: var(--ui-line); border-radius: var(--ui-radius-sm); }
.journey-axis { background: var(--ui-surface-2); border-bottom-color: var(--ui-line); }
.journey-axis > span { color: var(--ui-ink-3); font-size: 10px; letter-spacing: 0; }
.journey-gantt-row > button, .journey-row-label { background: var(--ui-surface-2); }
.journey-gantt-row > button:hover, .journey-gantt-row > button.active { background: var(--ui-surface-hover); box-shadow: inset 3px 0 var(--ui-ink); }
.journey-gantt-row > button strong, .journey-row-label strong { font-size: var(--ui-text-xs); }
.journey-gantt-row > button small, .journey-row-label small { font-size: 10px; }
.journey-bar strong, .journey-buffer-bar strong { font-size: 10px; }
.journey-bar small, .journey-buffer-bar small { font-size: 10px; }
.journey-today-line { background: var(--ui-ink); opacity: .5; }
.journey-detail-panel { border-left-color: var(--ui-line-strong); background: var(--ui-surface-2); }
.journey-detail-panel > div:first-child strong { font-size: var(--ui-text-sm); }
.journey-detail-panel > div:first-child small { font-size: var(--ui-text-xs); }

/* Yarı mamül tab */
.process-parameter-toolbar.wip-toolbar { padding: 10px 14px; flex-wrap: wrap; gap: 10px; border-bottom: 1px solid var(--ui-line); }
.wip-toolbar > div strong { display: flex; align-items: center; font-size: var(--ui-text-sm); }
.wip-stage-filter { flex-direction: row; align-items: center; gap: 8px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.wip-stage-filter select { height: var(--ui-control-h); border-color: var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); font-size: var(--ui-text-sm); }
.wip-layout { border: 0; border-top: 1px solid var(--ui-line); }
.wip-table-wrap { border-right-color: var(--ui-line); }
.wip-correction > span, .wip-audit > span { color: var(--ui-ink-3); font-size: var(--ui-text-xs); letter-spacing: 0; }

/* Search fields in this screen */
.process-workspace .process-search { min-height: var(--ui-control-h); border-color: var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); }
.process-workspace .process-search input { font-size: var(--ui-text-sm); }

/* Üretim iptalleri (above the workspace) */
.journey-cancellations { margin: 0 20px 12px; }
.journey-cancellations > summary { min-height: 40px; padding: 0 14px; display: flex; align-items: center; color: var(--ui-ink-2); font-size: var(--ui-text-sm); font-weight: 600; cursor: pointer; }

/* Narrow windows */
.process-summary-line { flex-wrap: wrap; row-gap: 8px; }
.process-summary-line > span { min-width: 120px; }
@media (max-width: 1100px) {
  .journey-layout { grid-template-columns: 1fr; }
  .journey-index { border-right: 0; border-bottom: 1px solid var(--ui-line); }
  .journey-job-list { max-height: 320px; min-height: 0; }
  .wip-layout { grid-template-columns: 1fr; }
}
@media (max-width: 600px) {
  .process-workspace { margin: 0 12px 16px; }
  .journey-canvas { padding: 12px; }
  .journey-ready { padding-left: 0; border-left: 0; }
}

/* ---- Leaner layout (second pass) ---- */
/* Mode tabs live in the title row */
.page-bar-slot .process-mode-tabs { padding: 2px; gap: 2px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface-2); }
.page-bar-slot .process-mode-tabs button { min-height: 28px; padding: 0 12px; border: 0; border-radius: var(--ui-radius-sm); color: var(--ui-ink-2); font: 500 var(--ui-text-sm) var(--ui-font); }
.page-bar-slot .process-mode-tabs button.active { background: var(--ui-surface); color: var(--ui-ink); font-weight: 650; box-shadow: 0 0 0 1px var(--ui-line); }
.page-bar-slot .journey-kpis { margin-left: 8px; }
.process-workspace > .journey-layout:first-child,
.process-workspace > .ui-status-line:first-child { margin-top: 0; }
.process-workspace > .ui-status-line { margin: 12px 14px; }
.journey-layout { margin-top: 0; border-top: 0; }
.process-workspace > .ui-status-line + .journey-layout,
.process-workspace > .journey-gap-list + .journey-layout { border-top: 1px solid var(--ui-line); }

/* List column: search, Aktif/Arşiv, filter menu, list */
.journey-index { display: flex; flex-direction: column; }
.journey-index > .journey-search { margin: 12px 12px 8px; }
.journey-list-tabs { margin: 0 12px; padding: 2px; display: flex; gap: 2px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); }
.journey-list-tabs button { flex: 1 1 0; min-height: 28px; border: 0; border-radius: var(--ui-radius-sm); background: transparent; color: var(--ui-ink-2); font: 500 var(--ui-text-sm) var(--ui-font); cursor: pointer; }
.journey-list-tabs button.active { background: var(--ui-surface-hover); color: var(--ui-ink); font-weight: 650; }
.journey-list-tabs button b { margin-left: 4px; color: var(--ui-ink-3); font-weight: 500; }
.journey-filters { margin: 0; padding: 8px 12px; display: flex; align-items: center; gap: 10px; border-bottom: 1px solid var(--ui-line); }
.journey-filter-menu > summary { min-height: 28px; padding: 0 10px; font-size: var(--ui-text-xs); }
.journey-filter-fields { padding: 6px; display: grid; gap: 10px; }
.journey-filter-fields label { display: grid; gap: 4px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.journey-filter-count { min-width: 0; margin-left: auto; text-align: right; }
.journey-filter-count strong { display: block; color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 500; }
.journey-filter-count small { display: none; }

/* List items: product + status, one meta line */
.journey-job-list > button { min-height: 0; padding: 10px 12px 10px 14px; grid-template-columns: minmax(0, 1fr) auto; align-items: center; }
.journey-job-list > button > span small { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Heading: no eyebrow, title + badge, ready date as quiet text */
.journey-heading { align-items: center; }
.journey-heading h3 { margin: 0 0 4px; }
.journey-ready { border-left: 0; padding: 0; }
.journey-ready span { display: none; }
.journey-ready strong { font-size: var(--ui-text-sm); }
.journey-ready strong::before { content: "Teslimata hazır: "; color: var(--ui-ink-2); font-weight: 400; }
.journey-ready small { display: none; }

/* Readiness: one compact line of steps */
.journey-readiness-strip { display: flex; overflow-x: auto; border: 0; border-bottom: 1px solid var(--ui-line); border-radius: 0; }
.journey-readiness-step { min-width: 0; min-height: 0; flex: 1 1 0; padding: 8px 12px 8px 0; display: flex; align-items: center; gap: 8px; border-right: 0; white-space: nowrap; }
.journey-readiness-step + .journey-readiness-step { padding-left: 12px; border-left: 1px solid var(--ui-line); }
.journey-readiness-step > div { display: flex; flex-direction: column; gap: 1px; }
.journey-readiness-step em { display: none; }
.journey-readiness-step b { align-self: flex-start; }
.journey-readiness-step.skipped { opacity: .55; }

/* Gantt: plan/actual lane labels once (in the legend), not on every row */
.journey-comparison-row .journey-side-lanes { display: none; }
.journey-gantt-controls { margin-top: 12px; }
.journey-gantt-controls > button:not(.ui-btn) { width: var(--ui-control-h); background: var(--ui-surface); }

/* Selected step facts: quieter */
.journey-detail-panel { margin-top: 12px; padding: 12px 14px; border-left: 0; border-top: 1px solid var(--ui-line); background: transparent; grid-template-columns: 200px minmax(0, 1fr); }
.journey-detail-panel dt { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.journey-detail-panel dd { color: var(--ui-ink); font-size: var(--ui-text-sm); }
@media (max-width: 900px) { .journey-detail-panel { grid-template-columns: 1fr; } }

/* Stronger overrides for legacy journey rules */
.journey-gantt .journey-gantt-row .journey-side-lanes { display: none; }
.journey-gantt .journey-axis > span::after { content: "üst: plan · alt: gerçekleşen"; display: block; margin-top: 3px; color: var(--ui-ink-3); font-size: 10px; font-weight: 400; text-transform: none; }
.journey-readiness-strip .journey-readiness-step { background: transparent; }
.journey-readiness-strip .journey-readiness-step > span { width: 22px; height: 22px; flex: 0 0 22px; display: grid; place-items: center; border-radius: 50%; background: var(--ui-surface-2); color: var(--ui-ink-2); font-size: 10px; }
.journey-readiness-step small { text-transform: none; letter-spacing: 0; }
.journey-gantt .journey-gantt-row > button,
.journey-gantt .journey-row-label { background: var(--ui-surface); }
.journey-gantt .journey-gantt-row > button.active { background: var(--ui-surface-hover); }
.journey-issue-line span { overflow: hidden; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; }
.journey-comparison-gantt .journey-gantt-row > button > .journey-side-lanes,
.journey-comparison-gantt .journey-row-label > .journey-side-lanes { display: none; }
.journey-gantt .journey-all-flow-label { background: var(--ui-surface-2); box-shadow: none; }
.journey-gantt .journey-all-flow-label > i { background: var(--ui-ink); color: var(--ui-surface); }
.journey-gantt .journey-all-flow-label strong { color: var(--ui-ink); }
.journey-gantt-controls > .journey-text-control { width: auto; padding: 0 10px; font: 500 var(--ui-text-sm) var(--ui-font); color: var(--ui-ink); }
.journey-list-tabs button b,
.journey-job-list em,
.journey-readiness-step b,
.journey-readiness-strip .journey-readiness-step > span { font-size: var(--ui-text-xs); }

/* Charge list: Planlama diameter dot, status beside the product, details full width */
.journey-job-list > button { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "main status" "meta meta"; row-gap: 3px; align-items: center; }
.journey-job-main { grid-area: main; min-width: 0; display: flex !important; flex-direction: row !important; align-items: center; gap: 8px !important; }
.journey-job-main strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.journey-dot { width: 9px; height: 9px; flex: 0 0 9px; border-radius: 50%; box-shadow: 0 0 0 1px rgba(0, 0, 0, .08); }
.journey-job-list > button > em { grid-area: status; }
.journey-job-list > button > .journey-job-meta { grid-area: meta; grid-column: 1 / -1; padding-left: 17px; overflow: hidden; color: var(--ui-ink-2); font-size: var(--ui-text-xs); text-overflow: ellipsis; white-space: nowrap; }

/* Left column stays in view; its list scrolls on its own (no clipped items, no empty space) */
.journey-layout { align-items: start; }
.journey-index { position: sticky; top: 56px; height: calc(100vh - 72px); min-height: 420px; }
.journey-job-list { flex: 1 1 auto; min-height: 0; max-height: none; overflow: auto; }
@media (max-width: 1100px) {
  .journey-index { position: static; height: auto; min-height: 0; }
  .journey-job-list { max-height: 360px; }
}

frontend/app/styles/machines.css.source:
/* machines — UI overhaul screen styles. Use only --ui-* tokens (app/styles/tokens.css).
   Tezgahlar: compact process tabs, machine list + selected machine, neutral current-job
   panel, read-only queue rows with per-row edit mode. Legacy rules in globals.css are
   overridden with .machines-screen scoping (ProductionProcessTabs is shared with Parametreler). */

/* Title-row numbers (PageBarSlot) */
.machines-kpis { min-width: 0; padding: 0; display: flex; flex-wrap: wrap; align-items: center; row-gap: 8px; }

/* Process tabs: one underline tab row joined to the workspace below */
.machines-screen .machines-process-tabs {
  margin: 0 20px;
  overflow: visible;
  border: 1px solid var(--ui-line);
  border-bottom: 0;
  border-radius: var(--ui-radius) var(--ui-radius) 0 0;
  background: var(--ui-surface);
  box-shadow: none;
}
.machines-screen .production-process-tabs {
  min-height: 44px;
  padding: 0 12px;
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 2px;
  border-bottom: 1px solid var(--ui-line);
  background: var(--ui-surface);
}
.machines-screen .production-process-tabs button {
  min-height: 43px;
  padding: 0 12px;
  flex: 0 0 auto;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
  color: var(--ui-ink-2);
  box-shadow: none;
}
.machines-screen .production-process-tabs button strong { display: flex; align-items: center; gap: 6px; font: var(--ui-label-weight) var(--ui-text-sm) var(--ui-font-label); white-space: nowrap; }
.machines-screen .production-process-tabs button small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); white-space: nowrap; }
.machines-screen .production-process-tabs button:hover { background: transparent; color: var(--ui-ink); }
.machines-screen .production-process-tabs button.active { border-bottom-color: var(--ui-ink); background: transparent; color: var(--ui-ink); box-shadow: none; }
.machines-screen .production-process-tabs button.active strong { font-weight: 650; }

/* Workspace frame */
.machines-screen .split-surface {
  margin: 0 20px 20px;
  min-height: 0;
  grid-template-columns: 210px minmax(0, 1fr);
  border-color: var(--ui-line);
  border-radius: 0 0 var(--ui-radius) var(--ui-radius);
  background: var(--ui-surface);
  box-shadow: none;
  overflow: visible;
}

/* Machine list */
.machines-screen .machine-list { max-height: calc(100vh - 170px); border-right-color: var(--ui-line); background: var(--ui-surface-2); }
.machines-screen .machine-list button { min-height: 46px; padding: 6px 12px; grid-template-columns: 8px minmax(0, 1fr) auto; gap: 9px; border-bottom: 1px solid var(--ui-line); color: var(--ui-ink); }
.machines-screen .machine-list button:hover { background: var(--ui-surface-hover); }
.machines-screen .machine-list button.selected { background: var(--ui-surface); box-shadow: inset 2px 0 var(--ui-ink); }
.machines-screen .machine-list strong { font-size: var(--ui-text-sm); font-weight: 650; }
.machines-screen .machine-list small { overflow: hidden; color: var(--ui-ink-3); font-size: var(--ui-text-xs); text-overflow: ellipsis; white-space: nowrap; }
.machines-screen .machine-list em { width: auto; min-width: 22px; height: auto; padding: 0; background: transparent; color: var(--ui-ink-2); font: 500 var(--ui-text-xs) var(--ui-font-num); font-style: normal; font-variant-numeric: tabular-nums; text-align: right; }
.machines-screen .machine-list .status { width: 7px; height: 7px; border-radius: 50%; background: var(--ui-line-strong); box-shadow: none; }
.machines-screen .machine-list .status.on { background: var(--ui-ok); }

/* Detail */
.machines-screen .machine-detail { max-height: none; padding: 16px 20px 20px; overflow: visible; display: grid; align-content: start; gap: 12px; }
.machines-screen .detail-heading { padding: 0; flex-wrap: wrap; gap: 10px 16px; border-bottom: 0; }
.machines-screen .detail-heading > div:first-child { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.machines-screen .detail-heading h2 { margin: 0; color: var(--ui-ink); font: 650 var(--ui-text-lg)/1.2 var(--ui-font-display); }
.machines-screen .detail-heading span { color: var(--ui-ink-2); font-size: var(--ui-text-sm); }
.machines-screen .machine-heading-actions { flex-wrap: wrap; gap: 8px; }
.machines-screen .switch-label { margin-right: 6px; color: var(--ui-ink-2); font-size: var(--ui-text-sm); white-space: nowrap; }
.machines-screen .switch-label input:checked + .switch { background: var(--ui-ink); }
.machines-screen .machine-actions-menu .ui-menu-panel { min-width: 240px; }

/* Settings: read-only line, inline edit on purpose */
.machines-screen .machine-settings { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 16px; padding: 8px 0; border-top: 1px solid var(--ui-line); border-bottom: 1px solid var(--ui-line); }
.machines-screen .machine-settings dl { margin: 0; display: flex; flex-wrap: wrap; gap: 6px 24px; flex: 1 1 auto; }
.machines-screen .machine-settings dl > div { display: flex; align-items: baseline; gap: 6px; }
.machines-screen .machine-settings dt { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.machines-screen .machine-settings dd { margin: 0; color: var(--ui-ink); font-size: var(--ui-text-sm); font-weight: 600; font-variant-numeric: tabular-nums; }
.machines-screen .machine-settings > .ui-btn { margin-left: auto; }
.machines-screen .machine-settings .form-grid { flex: 1 1 420px; padding: 0; gap: 10px; grid-template-columns: repeat(3, minmax(0, 1fr)); }
.machines-screen .machine-settings .field { gap: 4px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.machines-screen .machine-settings .field :is(input, select) { min-height: var(--ui-control-h); border-color: var(--ui-line-strong); border-radius: var(--ui-radius-sm); font-size: var(--ui-text-sm); }

/* Current job: neutral panel, one primary action + menu */
.machines-screen .machine-current-block { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 16px; padding: 12px 14px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); }
.machines-screen .current-job { min-width: 0; flex: 1 1 520px; padding: 0; display: flex; flex-wrap: wrap; gap: 8px 0; border-radius: 0; background: transparent; color: var(--ui-ink); }
.machines-screen .current-job div { min-width: 0; padding: 0 16px; gap: 2px; border-right: 1px solid var(--ui-line); }
.machines-screen .current-job div:first-child { padding-left: 0; flex: 1 1 180px; }
.machines-screen .current-job div:last-child { border-right: 0; }
.machines-screen .current-job span { color: var(--ui-ink-3); font-size: var(--ui-text-xs); letter-spacing: 0; }
.machines-screen .current-job strong { gap: 2px; color: var(--ui-ink); font-size: var(--ui-text-md); font-weight: 650; font-variant-numeric: tabular-nums; }
.machines-screen .current-job strong small { margin-top: 0; color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 500; }
.machines-screen .machine-current-actions { margin-left: auto; flex-direction: row; align-items: center; gap: 6px; }
.machines-screen .current-job-menu .ui-menu-panel { min-width: 230px; }

/* Notes: neutral lines, colour only on the icon / left rule */
.machines-screen .machine-overtime-panel,
.machines-screen .machine-diagnostic-panel,
.machines-screen .manual-order-note,
.machines-screen .process-start-blocker,
.machines-screen .process-queue-feedback {
  margin: 0;
  min-height: 0;
  padding: 8px 12px;
  border: 1px solid var(--ui-line);
  border-left: 3px solid var(--ui-line-strong);
  border-radius: var(--ui-radius-sm);
  background: var(--ui-surface);
  color: var(--ui-ink);
  font-size: var(--ui-text-sm);
}
.machines-screen .machine-overtime-panel { grid-template-columns: 18px minmax(0, 1fr) auto; }
.machines-screen .machine-overtime-panel svg { color: var(--ui-warn); }
.machines-screen .machine-overtime-panel strong,
.machines-screen .machine-diagnostic-panel strong,
.machines-screen .process-start-blocker strong { font-size: var(--ui-text-sm); font-weight: 600; }
.machines-screen .machine-overtime-panel span,
.machines-screen .machine-diagnostic-panel span,
.machines-screen .process-start-blocker p,
.machines-screen .process-start-blocker small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.machines-screen .machine-overtime-panel em { color: var(--ui-ink); font-size: var(--ui-text-sm); font-style: normal; font-weight: 600; }
.machines-screen .machine-diagnostic-panel.warning,
.machines-screen .process-start-blocker,
.machines-screen .manual-order-note { border-left-color: var(--ui-warn); }
.machines-screen .machine-diagnostic-panel.critical,
.machines-screen .process-queue-feedback.error { border-left-color: var(--ui-danger); }
.machines-screen .process-start-blocker > svg,
.machines-screen .manual-order-note > svg { color: var(--ui-warn); }
.machines-screen .process-queue-feedback.success { border-left-color: var(--ui-ok); }
.machines-screen .process-queue-feedback.success > svg { color: var(--ui-ok); }
.machines-screen .process-queue-feedback.error > svg { color: var(--ui-danger); }
.machines-screen .process-start-help { margin: 0; color: var(--ui-ink-2); font-size: var(--ui-text-sm); }
.machines-screen .unscheduled-queue-row { margin: 0 0 6px; }

/* Queue: the main object */
.machines-screen .machine-queue-panel { min-width: 0; }
.machines-screen .queue-heading { margin: 4px 0 8px; flex-wrap: wrap; justify-content: flex-start; gap: 8px 12px; }
.machines-screen .machine-detail .queue-heading h3 { margin: 0; display: flex; align-items: center; color: var(--ui-ink); font: 650 var(--ui-text-md)/1.3 var(--ui-font); }
.machines-screen .process-queue-search { margin-left: auto; min-width: 0; flex: 0 1 240px; min-height: var(--ui-control-h); border-color: var(--ui-line-strong); border-radius: var(--ui-radius); color: var(--ui-ink-3); }
.machines-screen .process-queue-search input { font-size: var(--ui-text-sm); }

.machines-screen .queue-columns,
.machines-screen .queue-list > .machine-queue-row {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) minmax(120px, 200px) auto;
  gap: 10px;
  align-items: center;
}
.machines-screen .queue-columns { padding: 7px 8px; border: 1px solid var(--ui-line); border-bottom: 0; border-radius: var(--ui-radius-sm) var(--ui-radius-sm) 0 0; background: var(--ui-surface-2); color: var(--ui-ink-2); font: 600 var(--ui-text-xs)/1.3 var(--ui-font); }
.machines-screen .queue-list { border: 1px solid var(--ui-line); border-radius: 0 0 var(--ui-radius-sm) var(--ui-radius-sm); }
.machines-screen .queue-list:has(> .empty-copy) { border-radius: var(--ui-radius-sm); }
.machines-screen .queue-list > .machine-queue-row { padding: 7px 8px; border-bottom: 1px solid var(--ui-line); font-size: var(--ui-text-sm); }
.machines-screen .queue-list > .machine-queue-row:last-child { border-bottom: 0; }
.machines-screen .queue-list > .machine-queue-row:hover,
.machines-screen .queue-list > .machine-queue-row.locked,
.machines-screen .queue-list > .machine-queue-row.editing { background: var(--ui-surface-2); }
.machines-screen .queue-list strong { min-width: 0; gap: 2px; color: var(--ui-ink); font-size: var(--ui-text-sm); font-weight: 600; }
.machines-screen .queue-list strong small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 400; font-variant-numeric: tabular-nums; }
.machines-screen .queue-drag-handle,
.machines-screen .queue-index { width: auto; height: 28px; padding: 0 6px; display: inline-flex; align-items: center; gap: 3px; border: 1px solid transparent; border-radius: var(--ui-radius-sm); background: transparent; color: var(--ui-ink-3); }
.machines-screen .queue-drag-handle:hover { border-color: var(--ui-line); background: var(--ui-surface); color: var(--ui-ink); cursor: grab; }
.machines-screen .queue-drag-handle b,
.machines-screen .queue-index b { color: var(--ui-ink); font: 600 var(--ui-text-sm) var(--ui-font-num); font-variant-numeric: tabular-nums; }
.machines-screen .queue-list .locked .queue-index { background: transparent; color: var(--ui-ink-2); }
.machines-screen .queue-work-order-value { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.machines-screen .queue-work-order-value b { overflow: hidden; color: var(--ui-ink); font: 600 var(--ui-text-sm) var(--ui-font-num); font-variant-numeric: tabular-nums; text-overflow: ellipsis; white-space: nowrap; }
.machines-screen .queue-work-order-value em { color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-style: normal; }
.machines-screen .process-queue-work-order { display: flex; flex-direction: column; gap: 1px; padding: 0; border: 0; background: transparent; }
.machines-screen .queue-cell-label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.machines-screen .process-queue-charge { padding: 0; border: 0; background: transparent; color: var(--ui-ink-2); font: 500 var(--ui-text-xs) var(--ui-font-num); }
.machines-screen .interrupted-label { color: var(--ui-warn); font-size: var(--ui-text-xs); font-weight: 500; }
.machines-screen .queue-row-actions,
.machines-screen .process-queue-row-actions { display: flex; align-items: center; justify-content: flex-end; gap: 0; }
.machines-screen .queue-row-actions .ui-icon-btn { width: 28px; height: 28px; flex-basis: 28px; padding: 0; border: 1px solid transparent; background: transparent; color: var(--ui-ink-2); }
.machines-screen .queue-row-actions .ui-icon-btn:hover:not(:disabled) { border-color: var(--ui-line); background: var(--ui-surface); color: var(--ui-ink); }
.machines-screen .queue-row-actions .ui-icon-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.machines-screen .queue-row-actions .queue-edit-toggle[aria-expanded="true"] { border-color: var(--ui-line-strong); background: var(--ui-surface); color: var(--ui-ink); }
.machines-screen .process-queue-row-actions .complete-queued-process:not(:disabled) { border-color: transparent; background: transparent; color: var(--ui-ink-2); }

/* Per-row edit mode */
.machines-screen .queue-row-editor { grid-column: 1 / -1; padding: 8px 0 4px 58px; display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px 16px; }
.machines-screen .queue-row-editor label { min-width: 0; display: grid; gap: 4px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.machines-screen .queue-row-editor label > span:last-child { display: flex; gap: 6px; }
.machines-screen .queue-row-editor :is(input, select) { min-width: 0; width: 200px; max-width: 100%; min-height: var(--ui-control-h); padding: 0 9px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font: 400 var(--ui-text-sm) var(--ui-font) !important; letter-spacing: 0; }
.machines-screen .queue-row-editor-actions { margin-left: auto; display: flex; flex-wrap: wrap; gap: 6px; }
.machines-screen .queue-row-editor .ui-btn.remove { color: var(--ui-danger); }

/* History */
.machines-screen .machine-history { margin-top: 4px; border-top: 1px solid var(--ui-line); }
.machines-screen .machine-history summary { padding: 10px 2px; color: var(--ui-ink-2); font-size: var(--ui-text-sm); font-weight: 600; }
.machines-screen .machine-history article strong { font-size: var(--ui-text-sm); font-weight: 600; }
.machines-screen .machine-history article small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.machines-screen .machine-history article > svg { color: var(--ui-ink-3); }
.machines-screen .empty-copy { padding: 14px 12px; color: var(--ui-ink-2); font-size: var(--ui-text-sm); }

/* Çubuk Filtre · Form Taşlama vardiya görünümü (below the queue) */
.machines-screen .form-grinding-shift-report { margin: 0 20px 20px; border-color: var(--ui-line); border-radius: var(--ui-radius); box-shadow: none; }
.machines-screen .form-grinding-shift-report .surface-toolbar { flex-wrap: wrap; gap: 8px 16px; }
.machines-screen .form-grinding-shift-report .surface-toolbar strong { font-size: var(--ui-text-md); }
.machines-screen .form-grinding-shift-report .surface-toolbar span { display: inline-flex; align-items: center; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.machines-screen .form-grinding-shift-report .dispatch-plan-table-wrap { overflow: auto; }
.machines-screen .form-grinding-shift-report :is(th, td) { font-size: var(--ui-text-xs); }

/* Dialogs owned by Tezgahlar: neutral heads, readable sizes */
.machine-dialog { border-top: 1px solid var(--ui-line); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow-pop); }
.current-job-drawer.machine-dialog { border-radius: 0; }
.machine-dialog .dialog-icon { background: var(--ui-surface-2); color: var(--ui-ink-2); }
.machine-dialog .operational-dialog-head > div > span,
.machine-dialog .revision-head > div > span,
.machine-dialog.completion-dialog > span { color: var(--ui-ink-3); font-size: var(--ui-text-xs); letter-spacing: 0.04em; }
.machine-dialog.completion-dialog > svg { color: var(--ui-ink-2); }
.machine-dialog :is(.operational-dialog-head, .revision-head) h2 { font-size: var(--ui-text-lg); }
.machine-dialog :is(.operational-dialog-head, .revision-head) p,
.machine-dialog.completion-dialog > p { color: var(--ui-ink-2); font-size: var(--ui-text-sm); }
.machine-dialog .field { font-size: var(--ui-text-xs); }
.machine-dialog .field :is(input, select, textarea),
.machine-dialog .current-job-form select,
.machine-dialog .machine-catalog-list input,
.machine-dialog .machine-catalog-add input,
.machine-dialog .process-resource-catalog-list :is(input, select) { min-height: var(--ui-control-h); font-size: var(--ui-text-sm) !important; font-weight: 400; }
.machine-dialog .machine-catalog-list strong,
.machine-dialog .process-resource-catalog-list strong { font-size: var(--ui-text-sm); }
.machine-dialog .process-resource-catalog-list > .process-resource-catalog-head { color: var(--ui-ink-3); font-size: var(--ui-text-xs); letter-spacing: 0; text-transform: none; }
.machine-dialog .calendar-impact-note,
.machine-dialog .current-job-preview,
.machine-dialog .machine-delete-panel { border-left-color: var(--ui-line-strong); background: var(--ui-surface-2); }
.machine-dialog .machine-delete-panel.blocked { border-left-color: var(--ui-danger); }
.machine-dialog .calendar-impact-note :is(span, small),
.machine-dialog.completion-dialog .field small,
.machine-dialog .quantity-current small,
.machine-dialog .machine-delete-panel > div:first-child > span { font-size: var(--ui-text-xs); }
.machine-dialog .calendar-impact-note strong,
.machine-dialog .quantity-current strong { font-size: var(--ui-text-sm); }

/* Narrow windows: wrap rows, stack the list, never scroll the page sideways */
@media (max-width: 1100px) {
  .machines-screen .split-surface { grid-template-columns: 180px minmax(0, 1fr); }
}
@media (max-width: 900px) {
  .machines-screen .machines-process-tabs,
  .machines-screen .split-surface,
  .machines-screen .form-grinding-shift-report { margin-right: 12px; margin-left: 12px; }
  .machines-screen .production-process-tabs { overflow-x: auto; flex-wrap: nowrap; }
  .machines-screen .split-surface { grid-template-columns: minmax(0, 1fr); }
  .machines-screen .machine-list { max-height: none; display: flex; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--ui-line); }
  .machines-screen .machine-list button { width: auto; min-width: 150px; flex: 0 0 auto; border-right: 1px solid var(--ui-line); border-bottom: 0; }
  .machines-screen .machine-list button.selected { box-shadow: inset 0 -2px var(--ui-ink); }
  .machines-screen .machine-detail { padding: 14px 12px 16px; }
  .machines-screen .machine-current-actions { margin-left: 0; }
}
@media (max-width: 600px) {
  .machines-screen .queue-columns { display: none; }
  .machines-screen .queue-list { border-radius: var(--ui-radius-sm); }
  .machines-screen .queue-list > .machine-queue-row { grid-template-columns: 44px minmax(0, 1fr); }
  .machines-screen .queue-work-order-value { grid-column: 2; }
  .machines-screen .queue-row-actions { grid-column: 1 / -1; justify-content: flex-start; }
  .machines-screen .queue-row-editor { padding-left: 0; }
  .machines-screen .queue-row-editor label > span:last-child { flex-wrap: wrap; }
  .machines-screen .current-job div { padding: 0 10px; }
  .machines-screen .machine-settings .form-grid { grid-template-columns: minmax(0, 1fr); }
  .machines-screen .process-queue-search { margin-left: 0; flex-basis: 100%; }
}

/* Planlama diameter dot (same colours as the Gantt and Şarj Yolculuğu) */
.machine-queue-row .queue-dot { width: 9px; height: 9px; margin-right: 8px; display: inline-block; flex: 0 0 9px; border-radius: 50%; vertical-align: 1px; box-shadow: 0 0 0 1px rgba(0, 0, 0, .08); }

/* Row editor buttons readable */
.queue-row-editor .ui-btn,
.queue-row-editor button { min-height: var(--ui-control-h); font: 500 var(--ui-text-sm) var(--ui-font); }
.machine-queue-row:not(.process-machine-queue-row) > strong { display: grid; grid-template-columns: 9px minmax(0, 1fr); align-items: center; column-gap: 8px; }
.machine-queue-row:not(.process-machine-queue-row) > strong > .queue-dot { margin: 0; grid-column: 1; }
.machine-queue-row:not(.process-machine-queue-row) > strong > :not(.queue-dot) { grid-column: 2; }
.machine-queue-row:not(.process-machine-queue-row) > strong > small { padding-left: 0; }

frontend/app/styles/orders.css.source:
/* orders — UI overhaul screen styles. Use only --ui-* tokens (app/styles/tokens.css).
   Siparişler: Teslimat Planı numbers + Tip ekle + İçe / dışa aktar menu in the title row,
   one scope row, one status line, one filter row, then the order table. */

.orders-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* Title row (PageBarSlot) */
.page-bar-slot > .delivery-report-metrics.compact { order: 0; }
.page-bar-slot > .orders-page-actions { order: 1; margin-left: auto; }
.delivery-report-metrics.compact { min-width: 0; margin: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 0; }
.delivery-report-metrics.compact > .metric.compact { padding: 0 14px; }
.delivery-report-metrics.compact > .metric.compact:first-child { padding-left: 0; }
.orders-page-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.orders-page-actions .new-order-type-wrap { display: inline-flex; align-items: center; }
.orders-page-actions .ui-btn.primary.new-order-type-action { min-height: var(--ui-control-h); margin: 0; padding: 0 12px; border-radius: var(--ui-radius); box-shadow: none; font-size: var(--ui-text-sm); }
.orders-io-menu .ui-menu-panel { min-width: 250px; }
.orders-io-menu .order-file-action { position: relative; cursor: pointer; }
.orders-io-menu .order-file-action input { position: absolute; width: 1px; height: 1px; overflow: hidden; opacity: 0; pointer-events: none; }
.orders-io-menu .order-file-action.loading { opacity: 0.55; cursor: wait; }
.orders-io-menu .ui-menu-item.delivery-export-action { border: 0; background: transparent; color: var(--ui-ink); font-size: var(--ui-text-sm); }
.orders-io-menu .ui-menu-item.delivery-export-action:hover:not(:disabled) { background: var(--ui-surface-hover); }
.orders-io-menu .orders-menu-danger, .orders-io-menu .orders-menu-danger svg { color: var(--ui-danger); }

/* Surface */
.data-surface.orders-surface { margin: 0 20px 20px; border-color: var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); box-shadow: none; overflow: visible; }

/* Teslimat Planı scope row + status line */
.orders-surface > .delivery-summary.sade { margin: 0; padding: 0; border: 0; border-bottom: 1px solid var(--ui-line); border-radius: 0; background: transparent; }
.delivery-summary.sade .delivery-report-scope { min-height: 52px; padding: 8px 14px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
.delivery-summary.sade .delivery-report-scope > .delivery-report-title { margin: 0; display: inline-flex; align-items: center; }
.delivery-summary.sade .delivery-report-title strong { color: var(--ui-ink); font: 650 var(--ui-text-md)/1.3 var(--ui-font); }
.delivery-summary.sade .delivery-report-scope label { display: inline-flex; align-items: center; gap: 6px; color: var(--ui-ink-2); font: 500 var(--ui-text-xs) var(--ui-font); }
.delivery-summary.sade .delivery-report-scope input { height: var(--ui-control-h); width: 136px; padding: 0 8px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-sm); }
.delivery-summary.sade .delivery-report-scope small.delivery-report-order-date { margin: 0; display: inline; color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.delivery-summary.sade .delivery-report-aside { margin-left: auto; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; }
.delivery-summary.sade .ui-status-line { margin: 0 14px 10px; }
.delivery-summary.sade > p.form-error { margin: 0 14px 10px; padding: 8px 12px; border: 1px solid var(--ui-line); border-left: 3px solid var(--ui-danger); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-danger); font-size: var(--ui-text-sm); }
.delivery-summary.sade > .planning-identity-notice { margin: 0 14px 10px; }
.delivery-undated-details summary { color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 600; cursor: pointer; }
.delivery-undated-details ul { margin: 6px 0 0; padding-left: 16px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); line-height: 1.5; }

/* Source menu + Genel termin tarihi */
.order-source-menu > summary { max-width: 280px; }
.order-source-chip-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.order-source-menu .order-context-summary { min-width: 0; margin: 0; padding: 6px 9px; display: grid; gap: 8px; }
.order-source-menu .order-context-summary dt { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.order-source-menu .order-context-summary dd { margin: 2px 0 0; color: var(--ui-ink); font-size: var(--ui-text-sm); font-weight: 600; overflow-wrap: anywhere; }
.orders-bulk-due { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; }
.orders-bulk-due-title { display: inline-flex; align-items: center; }
.orders-bulk-due-title strong { color: var(--ui-ink); font-size: var(--ui-text-sm); font-weight: 600; }
.orders-bulk-due label { display: inline-flex; align-items: center; gap: 6px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.orders-bulk-due input { height: var(--ui-control-h); padding: 0 8px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-sm); }

/* Filter row */
.orders-filter-bar { min-height: 48px; padding: 8px 14px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; border-bottom: 1px solid var(--ui-line); }
.orders-filter-bar .search { width: 200px; height: var(--ui-control-h); padding: 0 9px; border-color: var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink-3); }
.orders-filter-bar .search input { font-size: var(--ui-text-sm); color: var(--ui-ink); }
.orders-filter-bar .order-family-filter { height: var(--ui-control-h); padding: 0 8px; display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.orders-filter-bar .order-family-filter.active { border-color: var(--ui-ink-2); }
.orders-filter-bar .order-family-filter select { border: 0; outline: 0; background: transparent; color: var(--ui-ink); font-size: var(--ui-text-sm); }
.orders-filter-bar .order-filter-rail { min-width: 0; min-height: 0; flex: 1 1 520px; padding: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 4px; overflow: visible; border: 0; background: transparent; }
.orders-filter-bar .order-filter-rail > span { margin-right: 4px; color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-weight: 500; letter-spacing: 0; text-transform: none; }
.orders-filter-bar .order-filter-rail button { min-height: 28px; padding: 0 8px; gap: 6px; border: 1px solid transparent; border-radius: var(--ui-radius-sm); background: transparent; color: var(--ui-ink-2); font-size: var(--ui-text-sm); font-weight: 500; }
.orders-filter-bar .order-filter-rail button:hover:not(:disabled) { background: var(--ui-surface-hover); }
.orders-filter-bar .order-filter-rail button.active { border-color: var(--ui-line-strong); background: var(--ui-surface-2); color: var(--ui-ink); font-weight: 650; }
.orders-filter-bar .order-filter-rail button:disabled { opacity: 0.45; cursor: not-allowed; }
.orders-filter-bar .order-filter-rail button small { min-width: 0; height: auto; padding: 0; background: transparent; color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-variant-numeric: tabular-nums; }
.orders-filter-bar .order-filter-rail button.active small { background: transparent; color: var(--ui-ink-2); }
.orders-filter-bar .order-filter-rail em { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }

/* Order table (ui-table look) */
.orders-surface .order-entry-table { max-height: calc(100vh - 120px); overflow: auto; }
.orders-surface .order-entry-table th { padding: 9px 12px; background: var(--ui-surface-2); border-bottom: 1px solid var(--ui-line); color: var(--ui-ink-2); font: 600 var(--ui-text-xs)/1.3 var(--ui-font); letter-spacing: 0; text-transform: none; }
.orders-surface .order-entry-table td { padding: 8px 12px; border-bottom: 1px solid var(--ui-line); color: var(--ui-ink); font-size: var(--ui-text-sm); }
.orders-surface .order-entry-table td strong { font-size: var(--ui-text-sm); font-weight: 600; }
.orders-surface .order-entry-table tbody tr.empty-order-row { background: var(--ui-surface); }
.orders-surface .order-entry-table tbody tr.active-order-row { box-shadow: none; }
.orders-surface .order-entry-table tbody tr:hover td { background: var(--ui-surface-2); }
.orders-surface .order-entry-table tbody tr.focused-row td { background: var(--ui-accent-soft); }
.orders-surface .order-entry-table .stacked-note,
.orders-surface .order-date-input small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-weight: 400; }
.orders-surface .order-source.override { color: var(--ui-warn); font-weight: 600; }
.orders-surface .order-source.excel, .orders-surface .order-source.manual { color: var(--ui-ink-3); }
.orders-surface .delivery-late strong, .orders-surface .delivery-late .stacked-note { color: var(--ui-danger); }
.orders-surface .variance.negative { color: var(--ui-danger); }
.orders-surface .variance.positive { color: var(--ui-ink); }
.orders-surface .order-entry-input { height: 30px; border-radius: var(--ui-radius-sm); color: var(--ui-ink); font-size: var(--ui-text-sm); }
.orders-surface .order-entry-input:hover, .orders-surface .order-entry-input:focus { border-color: var(--ui-line-strong); background: var(--ui-surface); box-shadow: none; }
.orders-surface .order-entry-input.invalid { border-color: var(--ui-danger); background: var(--ui-danger-soft); }
.orders-surface .order-column-help { color: var(--ui-ink-3); }
.orders-surface .order-column-help:hover, .orders-surface .order-column-help:focus-visible { background: var(--ui-surface-hover); color: var(--ui-ink); }
.orders-surface .order-column-help [role="tooltip"] { background: var(--ui-ink); font-size: var(--ui-text-xs); font-weight: 400; text-transform: none; letter-spacing: 0; }
.orders-surface :is(.order-save-action, .order-detail-action, .order-manual-action, .order-reset-action) { min-height: 28px; padding: 0 8px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-xs); font-weight: 600; }
.orders-surface .order-reset-action { border-color: transparent; color: var(--ui-ink-2); }
.orders-surface .order-save-action.remove { border-color: color-mix(in srgb, var(--ui-danger) 45%, transparent); background: var(--ui-surface); color: var(--ui-danger); }
.orders-surface :is(.order-save-action, .order-manual-action):disabled { border-color: var(--ui-line); background: var(--ui-surface); color: var(--ui-ink-3); }
.orders-surface .badge { padding: 1px 7px; border: 1px solid var(--ui-line-strong); background: transparent; color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 600; }
.orders-surface .badge.short { border-color: color-mix(in srgb, var(--ui-danger) 45%, transparent); background: var(--ui-danger-soft); color: var(--ui-danger); }
.orders-surface .badge.over { border-color: color-mix(in srgb, var(--ui-warn) 45%, transparent); color: var(--ui-warn); }
.orders-surface .order-advice-status { color: var(--ui-warn); }

/* Çubuk Filtre panels (dialogs and the stock reconciliation panel) */
.orders-panel .dispatch-plan-state.preview { background: var(--ui-accent-soft); color: var(--ui-accent-hover); }
.orders-panel .dispatch-plan-state.saved { border: 1px solid var(--ui-line-strong); background: transparent; color: var(--ui-ink-2); }
.orders-panel .surface-toolbar strong { display: inline-flex; align-items: center; }
.orders-panel .dispatch-plan-table tr.calculated-row th, .orders-panel .dispatch-plan-table tr.calculated-row td { background: var(--ui-surface-2); color: var(--ui-ink-2); }
.data-surface.orders-panel#ravi-filter-stock-reconciliation { margin: 0 20px 12px; border-color: var(--ui-line); border-radius: var(--ui-radius); box-shadow: none; }
.orders-stock-done .surface-toolbar { min-height: 44px; padding: 6px 14px; border-bottom: 0; }

@media (max-width: 900px) {
  .data-surface.orders-surface, .data-surface.orders-panel#ravi-filter-stock-reconciliation { margin-inline: 12px; }
  .delivery-summary.sade .delivery-report-aside { margin-left: 0; }
  .page-bar-slot > .orders-page-actions { margin-left: 0; }
}
@media (max-width: 600px) {
  .orders-filter-bar .search { width: 100%; }
  .delivery-summary.sade .delivery-report-scope input { width: 128px; }
  .order-source-menu > summary { max-width: 220px; }
}

/* Family chip on order rows: outline instead of a green tint. */
.order-entry-table .setup-family-badge { border: 1px solid var(--ui-line-strong); background: transparent; color: var(--ui-ink-2); font-size: 10px; font-weight: 600; }

frontend/app/styles/overview.css.source:
/* Genel Bakış (UI overhaul, Sade). Main object: each machine's current job and queue.
   Summary numbers live in the page title row; cards are neutral, colour only for state. */

.dashboard-layout { margin: 0 20px 24px; gap: 14px; }

/* Title-row summary */
.page-bar-slot .overview-kpis { display: flex; flex-wrap: wrap; align-items: center; row-gap: 8px; padding: 0; border: 0; }
.page-bar-slot .dashboard-plan-state { margin-left: auto; padding: 0; display: inline-flex; align-items: center; gap: 6px; border-radius: 0; background: transparent; color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 500; }
.page-bar-slot .dashboard-plan-state.ready svg { color: var(--ui-ok); }
.page-bar-slot .dashboard-plan-state.stale { color: var(--ui-warn); font-weight: 600; }
.page-bar-slot .dashboard-plan-state.empty { color: var(--ui-ink-3); }

/* Board frame */
.dashboard-board { border-color: var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); box-shadow: none; }

/* Process tabs like Planlama's */
.dashboard-operation-tabs { min-height: 48px; padding: 0 14px; display: flex; gap: 2px; background: var(--ui-surface); border-bottom-color: var(--ui-line); }
.dashboard-operation-tabs button { padding: 0 12px; display: flex; align-items: center; gap: 8px; border: 0; border-bottom: 2px solid transparent; border-radius: 0; background: transparent; color: var(--ui-ink-2); }
.dashboard-operation-tabs button + button { border-left: 0; }
.dashboard-operation-tabs button span { display: flex; align-items: center; gap: 6px; font: 500 var(--ui-text-sm) var(--ui-font); }
.dashboard-operation-tabs button small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.dashboard-operation-tabs button b { color: var(--ui-ink-3); font: 500 var(--ui-text-xs) var(--ui-font); }
.dashboard-operation-tabs button:hover { color: var(--ui-ink); }
.dashboard-operation-tabs button.active { border-bottom-color: var(--ui-ink); background: transparent; color: var(--ui-ink); box-shadow: none; }
.dashboard-operation-tabs button.active span { font-weight: 650; }

/* One toolbar row */
.dashboard-toolbar { min-height: 52px; padding: 9px 14px; flex-wrap: wrap; justify-content: flex-start; gap: 10px; border-bottom-color: var(--ui-line); }
.dashboard-toolbar-title { min-width: 0; margin-right: auto; display: flex; align-items: baseline; flex-wrap: wrap; gap: 2px 10px; }
.dashboard-toolbar-title strong { font: 650 var(--ui-text-md) var(--ui-font); }
.dashboard-toolbar-title span { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.dashboard-search { width: 240px; min-height: var(--ui-control-h); border-color: var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); }
.dashboard-search input { font-size: var(--ui-text-sm); }
.dashboard-filters { padding: 2px; gap: 2px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius); }
.dashboard-filters button { min-height: 28px; padding: 0 10px; border-radius: var(--ui-radius-sm); color: var(--ui-ink-2); font: 500 var(--ui-text-sm) var(--ui-font); }
.dashboard-filters button.active { background: var(--ui-surface-hover); color: var(--ui-ink); font-weight: 650; }
.dashboard-toolbar .dashboard-export { min-height: var(--ui-control-h); border-color: var(--ui-line-strong); background: var(--ui-surface); color: var(--ui-ink); font: 500 var(--ui-text-sm) var(--ui-font); }
.dashboard-export-error { border-bottom-color: var(--ui-line); border-left: 3px solid var(--ui-danger); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-xs); }

/* Machine / station cards: neutral header, readable table */
.machine-dashboard-grid { padding: 14px; gap: 12px; background: var(--ui-surface-2); }
.machine-dashboard-card { border: 1px solid var(--ui-line); border-top: 1px solid var(--ui-line); border-radius: var(--ui-radius); overflow: hidden; background: var(--ui-surface); }
.machine-dashboard-card.passive { border-top-color: var(--ui-line); opacity: .7; }
.machine-dashboard-card header button,
.operation-resource-card header > div { min-height: 44px; padding: 8px 12px; border-bottom: 1px solid var(--ui-line); background: var(--ui-surface); color: var(--ui-ink); }
.machine-dashboard-card.passive header button { background: var(--ui-surface-2); }
.machine-dashboard-card header button:hover { background: var(--ui-surface-hover); }
.machine-dashboard-card header b { color: var(--ui-ink-3); font: 600 var(--ui-text-xs) var(--ui-font); letter-spacing: 0; }
.machine-dashboard-card header strong { color: var(--ui-ink); font: 650 var(--ui-text-md) var(--ui-font); }
.machine-dashboard-card header button > span:last-child { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.operation-resource-card.drilling, .operation-resource-card.deburring, .operation-resource-card.gkm { border-top-color: var(--ui-line); }
.operation-resource-card.drilling header > div, .operation-resource-card.deburring header > div, .operation-resource-card.gkm header > div { background: var(--ui-surface); }

.machine-dashboard-row { min-height: 36px; padding: 0 12px; border-bottom-color: var(--ui-line); font-size: var(--ui-text-sm); }
.machine-dashboard-row.head { min-height: 32px; background: var(--ui-surface-2); color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-weight: 600; letter-spacing: 0; text-transform: none; }
.machine-dashboard-row.current, .machine-dashboard-row.operation.current { background: var(--ui-surface); box-shadow: inset 3px 0 var(--ui-ok); font-weight: 600; }
.machine-dashboard-row.planned:nth-child(odd) { background: var(--ui-surface); }
.machine-dashboard-row strong { font-size: var(--ui-text-sm); }
.machine-dashboard-row i { padding: 1px 7px; border: 1px solid color-mix(in srgb, var(--ui-ok) 45%, transparent); border-radius: 999px; background: transparent; color: var(--ui-ok); font-size: var(--ui-text-xs); }
.machine-dashboard-table .trace-ready { font-size: var(--ui-text-sm) !important; font-weight: 600 !important; letter-spacing: 0; }
.machine-dashboard-card footer { min-height: 36px; padding: 0 12px; border-top-color: var(--ui-line); background: var(--ui-surface); color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.machine-dashboard-card footer strong { font-size: var(--ui-text-sm); }

.machine-dashboard-empty, .operation-resource-empty { background: var(--ui-surface); }
.machine-dashboard-empty span, .operation-resource-empty strong { font-size: var(--ui-text-sm); }
.machine-dashboard-empty small, .operation-resource-empty span { font-size: var(--ui-text-xs); }
.machine-dashboard-empty.critical, .machine-dashboard-diagnostic.critical { background: var(--ui-surface); box-shadow: inset 3px 0 var(--ui-danger); }
.machine-dashboard-empty.warning, .machine-dashboard-diagnostic.warning { background: var(--ui-surface); box-shadow: inset 3px 0 var(--ui-warn); }
.machine-dashboard-diagnostic { border-top-color: var(--ui-line); background: var(--ui-surface); }
.machine-dashboard-diagnostic strong { font-size: var(--ui-text-sm); }
.machine-dashboard-diagnostic small { font-size: var(--ui-text-xs); }

/* Plan kontrolü */
.dashboard-audit { border-color: var(--ui-line); border-radius: var(--ui-radius); }
.dashboard-audit summary { min-height: 52px; padding: 10px 16px; }
.dashboard-audit-title { display: flex; align-items: center; flex-wrap: wrap; gap: 2px 10px; }
.dashboard-audit summary strong { font: 650 var(--ui-text-md) var(--ui-font); }
.dashboard-audit summary small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.dashboard-audit-body { border-top-color: var(--ui-line); }
.dashboard-finding { border-color: var(--ui-line); }
.dashboard-finding strong { font-size: var(--ui-text-sm); }
.dashboard-finding p { font-size: var(--ui-text-xs); }
.dashboard-finding > svg { color: var(--ui-ink-3); }
.dashboard-finding.critical > svg { color: var(--ui-danger); }
.dashboard-finding.warning > svg { color: var(--ui-warn); }
.dashboard-no-results strong { font-size: var(--ui-text-sm); }
.dashboard-no-results span { font-size: var(--ui-text-xs); }

@media (max-width: 900px) {
  .dashboard-layout { margin: 0 12px 16px; }
  .dashboard-finding-list { grid-template-columns: 1fr; }
  .dashboard-search { width: 100%; }
}
.machine-dashboard-row { grid-template-columns: 86px 1.15fr .65fr .75fr .72fr 1fr; }
.machine-dashboard-row.operation { grid-template-columns: 86px 1fr 1.05fr .65fr .85fr .85fr; }
.machine-dashboard-row > :first-child { overflow: visible; }
.dashboard-audit summary > span.dashboard-audit-title { display: flex; grid-template-columns: none; align-items: center; flex-wrap: wrap; gap: 2px 10px; }
.dashboard-finding { min-height: 0; padding: 12px 14px; }
.dashboard-finding > button { min-height: 28px; padding: 0 10px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font: 500 var(--ui-text-xs) var(--ui-font); }
.dashboard-operation-tabs button { flex: 0 0 auto; white-space: nowrap; }
.dashboard-operation-tabs { overflow-x: auto; }

frontend/app/styles/parameters.css.source:
/* Parametreler (UI overhaul, Sade). View first: a read-only product table;
   editing opens per product in a drawer that keeps the same save logic. */

.params-page { margin: 0 20px 24px; }
.params-surface,
.params-filter-page { border: 1px solid var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); }
.params-filter-page { margin: 0 20px 24px; }

/* Title row */
.params-bar-metrics { min-width: 0; margin-right: auto; display: flex; flex-wrap: wrap; align-items: center; row-gap: 8px; }

/* Process tabs like Planlama's */
.params-tabs { margin: 0; padding: 0 14px; border-bottom: 1px solid var(--ui-line); background: transparent; }
.params-tabs .production-process-tabs,
.params-subtabs .production-process-tabs { margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 2px; border: 0; background: transparent; box-shadow: none; }
.params-tabs .production-process-tabs button,
.params-subtabs .production-process-tabs button { min-width: 0; min-height: 46px; padding: 0 12px; display: flex; align-items: center; gap: 8px; border: 0; border-bottom: 2px solid transparent; border-radius: 0; background: transparent; color: var(--ui-ink-2); font: 500 var(--ui-text-sm) var(--ui-font); box-shadow: none; }
.params-tabs .production-process-tabs button span,
.params-subtabs .production-process-tabs button span { font: inherit; }
.params-tabs .production-process-tabs button small,
.params-subtabs .production-process-tabs button small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.params-tabs .production-process-tabs button.active,
.params-subtabs .production-process-tabs button.active { border-bottom-color: var(--ui-ink); background: transparent; color: var(--ui-ink); font-weight: 650; box-shadow: none; }
.params-subtabs { padding: 0 14px; border-bottom: 1px solid var(--ui-line); }

/* One toolbar row */
.params-toolbar { min-height: 52px; padding: 9px 14px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; border-bottom: 1px solid var(--ui-line); }
.params-count { display: inline-flex; align-items: center; margin-right: auto; }
.params-count strong { font: 650 var(--ui-text-md) var(--ui-font); }
.params-search { width: 220px; min-height: var(--ui-control-h); padding: 0 9px; display: flex; align-items: center; gap: 7px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink-3); }
.params-search input { width: 100%; border: 0; outline: 0; background: transparent; color: var(--ui-ink); font-size: var(--ui-text-sm); }
.params-filter { min-height: var(--ui-control-h); padding: 0 8px; display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.params-filter select { max-width: 150px; border: 0; outline: 0; background: transparent; color: var(--ui-ink); font-size: var(--ui-text-sm); }
.params-filter.active { border-color: var(--ui-ink); }
.params-excel .ui-menu-panel { min-width: 260px; }
.params-excel .ui-menu-panel button,
.params-excel .ui-menu-panel label { width: 100%; min-height: 34px; padding: 6px 9px; display: flex; align-items: center; gap: 9px; border: 0; border-radius: var(--ui-radius-sm); background: transparent; color: var(--ui-ink); font: 500 var(--ui-text-sm) var(--ui-font); text-align: left; cursor: pointer; }
.params-excel .ui-menu-panel button:hover,
.params-excel .ui-menu-panel label:hover { background: var(--ui-surface-hover); }

.params-surface > .ui-status-line,
.params-process-body > .ui-status-line,
.params-filter-page > .ui-status-line { margin: 12px 14px; }

/* Read-only table */
.params-table-scroll { max-height: calc(100vh - 230px); overflow: auto; }
.params-table { min-width: 980px; }
.params-table th { position: sticky; top: 0; z-index: 2; }
.params-table .params-row { cursor: pointer; }
.params-table td strong { font-size: var(--ui-text-sm); font-weight: 650; }
.params-muted { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.params-unit { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.params-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.params-edit-cell { width: 44px; padding: 0 8px !important; text-align: right; }
.params-priority-summary { margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px 12px; list-style: none; }
.params-priority-summary li { display: inline-flex; align-items: baseline; gap: 5px; white-space: nowrap; }
.params-priority-summary li b { color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-weight: 500; }
.params-priority-summary li span { color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-variant-numeric: tabular-nums; }
.params-priority-summary li.passive { color: var(--ui-ink-3); text-decoration: line-through; }
.parameter-empty-row td { padding: 32px 12px; text-align: center; }
.parameter-empty-row strong { display: block; }
.parameter-empty-row span { display: block; margin: 4px 0 10px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }

/* Edit drawer */
.params-drawer .parameter-row.params-form { display: grid; gap: 16px; padding: 0; border: 0; background: transparent; }
.params-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.params-field-label { color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 500; }
.params-drawer input, .params-drawer select { min-height: var(--ui-control-h); padding: 0 9px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-sm); }
.params-drawer input[type="checkbox"] { min-height: 0; }
.params-drawer .machine-priority-list { display: grid; gap: 6px; }
.params-drawer .machine-priority-item { padding: 8px 10px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius-sm); background: var(--ui-surface); font-size: var(--ui-text-sm); }
.params-drawer .machine-priority-item small, .params-drawer .machine-priority-item span { font-size: var(--ui-text-xs); }
.params-priority-moves { display: inline-flex; gap: 2px; }
.params-feedback { margin: 0; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.params-feedback .error, .params-feedback.error { color: var(--ui-danger); font-weight: 600; }
.params-feedback .warning { color: var(--ui-warn); font-weight: 600; }
.params-feedback .success { color: var(--ui-ok); font-weight: 600; }
.params-ok-note { margin: 12px 14px; color: var(--ui-ok); font-size: var(--ui-text-xs); }
.params-inline-error { margin: 12px 14px; color: var(--ui-danger); font-size: var(--ui-text-xs); }
.params-review { margin: 12px 14px; padding: 12px 14px; border: 1px solid var(--ui-line); border-left: 3px solid var(--ui-warn); border-radius: var(--ui-radius-sm); background: var(--ui-surface); font-size: var(--ui-text-sm); }
.params-source { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.params-process-body { min-width: 0; }

@media (max-width: 900px) {
  .params-page, .params-filter-page { margin: 0 12px 16px; }
  .params-count { flex-basis: 100%; }
  .params-search { flex: 1 1 100%; width: auto; }
  .params-form-grid { grid-template-columns: 1fr; }
}

/* Drawer: machine rows in two lines (identity + order, then status + rate) */
.params-drawer .machine-priority-cell { min-width: 0; display: grid; gap: 8px; background: transparent; box-shadow: none; }
.params-drawer .machine-priority-cell.invalid .machine-priority-list { outline: 1px solid var(--ui-danger); outline-offset: 2px; border-radius: var(--ui-radius-sm); }
.params-drawer .machine-priority-item { min-height: 0; padding: 10px 12px; display: grid; grid-template-columns: 40px minmax(0, 1fr) auto auto; grid-template-areas: "handle identity role moves" "status status rate rate"; gap: 8px 10px; align-items: center; }
.params-drawer .machine-priority-item.passive { background: var(--ui-surface-2); }
.params-drawer .machine-priority-item > span.priority-drag-handle { grid-area: handle; width: auto; min-width: 0; height: 24px; padding: 0 6px; display: inline-flex; align-items: center; justify-content: center; gap: 3px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.params-drawer .machine-priority-item > span.priority-drag-handle b { font-weight: 600; }
.params-drawer .machine-priority-identity { grid-area: identity; }
.params-drawer .machine-priority-identity strong { font-size: var(--ui-text-sm); }
.params-drawer .machine-priority-identity small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.params-drawer .machine-priority-role { grid-area: role; color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.params-drawer .machine-priority-item > span.params-priority-moves { grid-area: moves; width: auto; height: auto; display: inline-flex; gap: 2px; border-radius: 0; background: transparent; color: var(--ui-ink-2); }
.params-drawer .machine-priority-item button { width: 26px; height: 26px; color: var(--ui-ink-2); }
.params-drawer .machine-priority-item button:hover:not(:disabled) { background: var(--ui-surface-hover); color: var(--ui-ink); }
.params-drawer .machine-priority-item button.remove:hover { background: var(--ui-danger-soft); color: var(--ui-danger); }
.params-drawer .parameter-assignment-status { grid-area: status; flex-direction: row; align-items: center; gap: 8px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.params-drawer .parameter-assignment-status select { min-height: 30px; padding: 0 8px; border-color: var(--ui-line-strong); border-radius: var(--ui-radius-sm); color: var(--ui-ink); font-size: var(--ui-text-sm); font-weight: 500; }
.params-drawer .machine-daily-rate { grid-area: rate; min-width: 0; display: flex; align-items: center; justify-content: flex-end; gap: 8px; }
.params-drawer .machine-daily-rate > small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); text-transform: none; letter-spacing: 0; font-weight: 500; }
.params-drawer .machine-daily-rate > span { display: inline-flex; align-items: center; gap: 6px; }
.params-drawer .machine-daily-rate b { color: var(--ui-ink); font-size: var(--ui-text-sm); font-variant-numeric: tabular-nums; }
.params-drawer .machine-daily-rate em { color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-style: normal; }
.params-drawer .machine-daily-rate input { width: 84px; min-height: 30px; text-align: right; }
.params-drawer .machine-daily-rate .ui-btn,
.params-drawer .default-daily-rate .ui-btn { width: auto; height: auto; min-width: 0; min-height: 28px; padding: 0 10px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font: 500 var(--ui-text-xs) var(--ui-font); }

/* Default rate */
.params-drawer .default-daily-rate-cell { background: transparent; box-shadow: none; }
.params-drawer .default-daily-rate { justify-content: flex-start; gap: 8px; }
.params-drawer .default-daily-rate strong { color: var(--ui-ink); font-size: var(--ui-text-md); }
.params-drawer .default-daily-rate > span { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.params-drawer .default-daily-rate input { width: 100px; min-height: 30px; border-color: var(--ui-line-strong); font-size: var(--ui-text-sm); }
.params-drawer .default-daily-rate.editing .ui-btn { background: var(--ui-surface); color: var(--ui-ink); }

/* Field inputs fill their cell */
.params-drawer .ui-field input, .params-drawer .ui-field select { width: 100%; text-align: left; }

/* Machine picker */
.params-drawer .machine-priority-picker summary { min-height: 30px; padding: 0 10px; border-color: var(--ui-line-strong); background: var(--ui-surface); color: var(--ui-ink); font-size: var(--ui-text-xs); }
.params-drawer .machine-priority-picker[open] summary { background: var(--ui-surface-hover); color: var(--ui-ink); }
.params-drawer .machine-priority-picker > div { padding: 10px 0 0; border-left: 0; background: transparent; }
.params-drawer .machine-priority-picker p { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.params-drawer .machine-option-grid button { border-color: var(--ui-line); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); }
.params-drawer .machine-option-grid button strong { font-size: var(--ui-text-sm); }
.params-drawer .machine-option-grid button small { font-size: var(--ui-text-xs); }
.params-drawer .machine-option-grid button span { background: var(--ui-surface-hover); color: var(--ui-ink-2); font-size: var(--ui-text-xs); }

/* Tabs: label and count on one line */
.params-tabs .production-process-tabs button,
.params-subtabs .production-process-tabs button { grid-template-columns: none; flex-direction: row; white-space: nowrap; }
@media (max-width: 560px) {
  .params-drawer .machine-priority-item { grid-template-columns: 40px minmax(0, 1fr) auto; grid-template-areas: "handle identity moves" "role role role" "status status status" "rate rate rate"; }
  .params-drawer .machine-daily-rate { justify-content: flex-start; }
}

/* Wide tables scroll inside their own box, never the page */
.params-surface, .params-filter-page, .params-process-body { min-width: 0; max-width: 100%; }
.params-table-scroll, .params-filter-page .table-scroll { max-width: 100%; overflow: auto; }
.params-table td small { font-size: var(--ui-text-xs); }

frontend/app/styles/planning.css.source:
/* Planlama (UI overhaul phase 1): one summary bar, one board header, one toolbar,
   then the Gantt. Gantt bar colours keep their meaning (diameter / product). */

/* Summary bar: title + KPIs + shortage rule on one row */
.planning-bar {
  min-height: 56px;
  padding: 10px 20px;
  display: flex;
  align-items: center;
  gap: 28px;
}
.planning-bar h1 { flex: 0 0 auto; font: 650 var(--ui-text-lg)/1.2 var(--ui-font-display); letter-spacing: -0.01em; }
.planning-bar .kpi-strip { min-width: 0; padding: 0; display: flex; align-items: center; gap: 0; }
.metric.compact {
  min-height: 0;
  padding: 0 16px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  border-right: 1px solid var(--ui-line);
}
.metric.compact:first-child { padding-left: 0; }
.metric.compact:last-child { border-right: 0; }
.metric.compact > span {
  color: var(--ui-ink-3);
  font: var(--ui-label-weight) var(--ui-text-xs) var(--ui-font-label);
  letter-spacing: var(--ui-label-tracking);
  text-transform: var(--ui-label-case);
  white-space: nowrap;
}
.metric.compact strong {
  color: var(--ui-ink);
  font: var(--ui-num-weight) var(--ui-text-lg)/1.2 var(--ui-font-num);
  letter-spacing: var(--ui-num-tracking);
  font-variant-numeric: tabular-nums;
}
.metric.compact.good strong { color: var(--ui-ink); }
.metric.compact.warning strong { color: var(--ui-warn); }
.metric.compact.danger strong { color: var(--ui-danger); }
.metric.compact .number-help-trigger { background: transparent; color: var(--ui-ink-3); }
.metric.compact .number-help-trigger [role="tooltip"] { font-size: var(--ui-text-xs); }

.plan-policy-chip {
  margin-left: auto;
  padding: 5px 10px;
  display: inline-flex;
  border: 1px solid var(--ui-line);
  border-radius: var(--ui-radius);
  background: var(--ui-surface);
  white-space: nowrap;
}
.plan-policy-chip .number-with-help > span:first-child { display: flex; align-items: baseline; gap: 7px; }
.plan-policy-chip small { color: var(--ui-ink-3); font: var(--ui-label-weight) var(--ui-text-xs) var(--ui-font-label); letter-spacing: var(--ui-label-tracking); text-transform: var(--ui-label-case); }
.plan-policy-chip strong { color: var(--ui-ink); font-size: var(--ui-text-sm); font-weight: 600; }
.plan-policy-chip .number-help-trigger { background: transparent; color: var(--ui-ink-3); }
.plan-policy-chip .number-help-trigger [role="tooltip"] { left: auto; right: -8px; transform: translate(0, 3px); font-size: var(--ui-text-xs); }
.plan-policy-chip .number-help-trigger:hover [role="tooltip"] { transform: translate(0, 0); }
.plan-policy-chip .number-help-trigger [role="tooltip"]:after { left: auto; right: 10px; }
.plan-policy-chip.disabled strong { color: var(--ui-ink-2); }

.planning-bar + .plan-sequence-bar { margin: 0 20px 12px; }

/* Board frame */
.workspace {
  margin: 0 20px 20px;
  border-color: var(--ui-line);
  border-radius: var(--ui-radius);
  background: var(--ui-surface);
  box-shadow: none;
}

/* Board header: process tabs left, workload right */
.gantt-process-tabs {
  min-height: 48px;
  padding: 0 14px;
  align-items: stretch;
  gap: 2px;
  background: var(--ui-surface);
  border-bottom-color: var(--ui-line);
}
.gantt-process-tabs > button {
  min-width: 0;
  min-height: 0;
  padding: 0 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: transparent;
  color: var(--ui-ink-2);
  box-shadow: none;
}
.gantt-process-tabs > button span { display: flex; align-items: center; gap: 6px; font: var(--ui-label-weight) var(--ui-text-sm) var(--ui-font-label); letter-spacing: var(--ui-label-tracking); text-transform: var(--ui-label-case); }
.gantt-process-tabs > button small { display: none; }
.gantt-process-tabs > button b { min-width: 0; padding: 0; border-radius: 0; background: transparent; color: var(--ui-ink-3); font: 500 var(--ui-text-xs) var(--ui-font-num); }
.gantt-process-tabs > button:hover { color: var(--ui-ink); }
.gantt-process-tabs > button.active { border-color: transparent; border-bottom-color: var(--ui-ink); background: transparent; color: var(--ui-ink); box-shadow: none; }
.gantt-process-tabs > button.active span { font-weight: 650; }
.gantt-process-tabs > button.active b { background: transparent; color: var(--ui-ink-2); }

.gantt-process-tabs .operation-workload-summary {
  min-height: 0;
  margin-left: auto;
  padding: 0;
  display: flex;
  align-items: center;
  gap: 0;
  border: 0;
  background: transparent;
}
.gantt-process-tabs .operation-workload-summary > span {
  min-width: 0;
  padding: 0 14px;
  display: flex;
  align-items: baseline;
  gap: 6px;
  border-right: 1px solid var(--ui-line);
}
.gantt-process-tabs .operation-workload-summary > span:last-child { padding-right: 0; border-right: 0; }
.gantt-process-tabs .operation-workload-summary small { color: var(--ui-ink-3); font: var(--ui-label-weight) var(--ui-text-xs) var(--ui-font-label); letter-spacing: var(--ui-label-tracking); text-transform: var(--ui-label-case); white-space: nowrap; }
.gantt-process-tabs .operation-workload-summary strong { color: var(--ui-ink); font: 600 var(--ui-text-sm) var(--ui-font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }
.gantt-process-tabs .operation-workload-summary > span.total strong { color: var(--ui-ink); }
.gantt-process-tabs .operation-workload-summary em { color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-style: normal; white-space: nowrap; }
.gantt-process-tabs .operation-workload-summary .number-help-trigger { background: transparent; color: var(--ui-ink-3); }
.gantt-process-tabs .operation-workload-summary .number-help-trigger [role="tooltip"] { left: auto; right: -8px; transform: translate(0, 3px); font-size: var(--ui-text-xs); }
.gantt-process-tabs .operation-workload-summary .number-help-trigger:hover [role="tooltip"] { transform: translate(0, 0); }
.gantt-process-tabs .operation-workload-summary .number-help-trigger [role="tooltip"]:after { left: auto; right: 10px; }

/* Toolbar: search · time · legend ……… actions */
.board-tools { min-height: 52px; padding: 9px 14px; gap: 8px; border-bottom-color: var(--ui-line); }
.board-tools .search { width: 220px; height: var(--ui-control-h); border-color: var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); }
.board-tools .search input { font-size: var(--ui-text-sm); }
.gantt-time-controls > button,
.gantt-time-controls label,
.zoom-control { height: var(--ui-control-h); border-color: var(--ui-line); border-radius: var(--ui-radius); color: var(--ui-ink-2); }
.gantt-time-controls > button { width: var(--ui-control-h); }
.gantt-time-controls input,
.gantt-month-filter select { font-size: var(--ui-text-sm); }
.gantt-month-filter > span,
.zoom-control small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.gantt-time-controls .text-control { font: var(--ui-label-weight) var(--ui-text-sm) var(--ui-font-label); letter-spacing: var(--ui-label-tracking); text-transform: var(--ui-label-case); color: var(--ui-ink); }

.legend-menu .ui-menu-panel { min-width: 260px; padding: 10px 12px; }
.legend-menu .legend { margin: 0; display: grid; gap: 9px; color: var(--ui-ink-2); font-size: var(--ui-text-sm); }
.board-actions { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.planning-tools-menu .ui-menu-panel { min-width: 260px; }
.planning-tools-menu .plan-sequence-bar { margin: 0 0 6px; grid-template-columns: 1fr; }

/* Gantt: let it use the screen */
.turning-timeline { max-height: calc(100vh - 290px); min-height: 420px; }
.timeline-head { background: var(--ui-surface-2); border-bottom-color: var(--ui-line); }
.machine-title { background: var(--ui-surface-2); color: var(--ui-ink-3); font: var(--ui-label-weight) var(--ui-text-xs) var(--ui-font-label); letter-spacing: var(--ui-label-tracking); }
.month-scale { background: var(--ui-surface-2); border-bottom-color: var(--ui-line); }
.month-scale span { color: var(--ui-ink); font-size: var(--ui-text-xs); font-weight: 650; }
.week-scale { background: var(--ui-surface-2); border-bottom-color: var(--ui-line); }
.week-scale span { color: var(--ui-ink-2); font-size: 10px; font-weight: 600; }
.day-scale span { color: var(--ui-ink-2); font-size: 10px; font-weight: 500; }

/* Collapsed inspector rail: neutral instead of teal */
.inspector-rail { border-left-color: var(--ui-line); background: var(--ui-surface-2); color: var(--ui-ink-2); box-shadow: none; }
.inspector-rail > svg { background: var(--ui-ink); box-shadow: none; }
.inspector-rail:hover { background: var(--ui-surface-hover); color: var(--ui-ink); box-shadow: inset 2px 0 var(--ui-ink); }
.inspector-rail span { font-size: var(--ui-text-xs); }

/* Operation summary now sits under the Gantt */
.gantt-operational-details { border-top: 1px solid var(--ui-line); border-bottom: 0; background: var(--ui-surface-2); }
.gantt-operational-details > summary strong,
.gantt-operational-details > summary small { font-size: var(--ui-text-xs); }

/* Compact Gantt head: month / week / day in 60px instead of 74px */
.turning-timeline .timeline-head { height: 60px; }
.turning-timeline .calendar-scale { grid-template-rows: 20px 18px 22px; background: var(--ui-surface-2); }
.turning-timeline .month-scale span { padding-top: 4px; }
.turning-timeline .week-scale span { padding-top: 3px; }
.day-scale span.today { background: var(--ui-ink); color: var(--ui-surface); }

/* Machine labels readable */
.machine-label strong { color: var(--ui-ink); font-size: var(--ui-text-sm); }
.machine-label small { color: var(--ui-ink-3); font-size: 10px; }

/* Weekly demand ribbon: same neutral language, readable text */
.weekly-demand-ribbon { min-height: 0; padding: 8px 14px; background: var(--ui-surface); border-bottom: 1px solid var(--ui-line); }
.weekly-demand-ribbon.empty { min-height: 0; }
.weekly-demand-empty-state { flex-direction: row; align-items: baseline; gap: 10px; }
.weekly-demand-empty-state > span,
.weekly-demand-context > span { color: var(--ui-ink-3); font: var(--ui-label-weight) var(--ui-text-xs) var(--ui-font-label); letter-spacing: var(--ui-label-tracking); text-transform: var(--ui-label-case); }
.weekly-demand-empty-state > strong,
.weekly-demand-context > strong { color: var(--ui-ink); font: 600 var(--ui-text-sm) var(--ui-font); }
.weekly-demand-empty-state > small,
.weekly-demand-context > small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.weekly-demand-context > em { font-size: var(--ui-text-xs); }
.weekly-demand-weeks > button { border-color: var(--ui-line); border-radius: var(--ui-radius-sm); background: var(--ui-surface); }
.weekly-demand-weeks > button > span { color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.weekly-demand-weeks > button > span small { font-size: 10px; }
.weekly-demand-weeks > button strong { font-size: var(--ui-text-sm); }
.weekly-demand-weeks > button em { font-size: 10px; }
.weekly-demand-weeks > button.risk { border-left-color: var(--ui-danger); background: var(--ui-danger-soft); }
.weekly-demand-weeks > button.ready { border-left-color: var(--ui-ok); }
.weekly-demand-weeks > button.selected { border-color: var(--ui-ink); box-shadow: inset 0 0 0 1px var(--ui-ink); }

.gantt-process-tabs > button span,
.gantt-time-controls .text-control { white-space: nowrap; }
.gantt-process-tabs > button b { white-space: nowrap; }

/* Narrower screens: wrap instead of overlapping */
.gantt-process-tabs { flex-wrap: wrap; row-gap: 0; }
.gantt-process-tabs > button { flex-shrink: 0; min-height: 46px; }
.gantt-process-tabs .operation-workload-summary { min-height: 46px; }
.board-tools { flex-wrap: wrap; row-gap: 8px; }
.board-tools .search { flex: 0 1 220px; min-width: 170px; }
@media (max-width: 1400px) {
  .planning-bar { gap: 18px; }
  .metric.compact { padding: 0 12px; }
  .gantt-process-tabs > button { padding: 0 9px; }
  .gantt-process-tabs .operation-workload-summary > span { padding: 0 10px; }
  .gantt-process-tabs .operation-workload-summary em { display: none; }
  .board-tools .search { flex-basis: 170px; min-width: 150px; }
  .board-tools .ui-btn { padding: 0 9px; }
}

@media (max-width: 1366px) {
  .gantt-month-filter > span { display: none; }
}

/* Narrow windows: wrap rows instead of squeezing; numbers never break. */
.planning-bar { flex-wrap: wrap; row-gap: 10px; }
.planning-bar .metrics.kpi-strip { display: flex; flex-wrap: wrap; row-gap: 10px; padding: 0; }
.metric.compact { flex: 0 0 auto; min-width: 0; }
.metric.compact > span,
.metric.compact strong { white-space: nowrap; }
.gantt-process-tabs .operation-workload-summary { flex-wrap: wrap; }
.gantt-time-controls { flex-wrap: wrap; row-gap: 6px; }
@media (max-width: 900px) {
  .planning-bar { padding: 10px 12px; }
  .planning-bar h1 { flex-basis: 100%; }
  .plan-policy-chip { margin-left: 0; white-space: normal; }
  .workspace { margin: 0 12px 16px; }
  .gantt-process-tabs .operation-workload-summary { margin-left: 0; flex-basis: 100%; padding: 6px 0; border-top: 1px solid var(--ui-line); }
  .gantt-process-tabs .operation-workload-summary > span:first-child { padding-left: 0; }
  .board-actions { margin-left: 0; flex-wrap: wrap; }
}
@media (max-width: 600px) {
  .metric.compact { padding: 0 10px 0 0; margin-right: 10px; }
  .board-tools .search { flex: 1 0 100%; }
  .gantt-process-tabs .operation-workload-summary > span { flex-basis: 100%; padding: 1px 0; border-right: 0; }
}
.legend-menu .filter-product-legend { margin-top: 10px; padding: 10px 0 0; border-top: 1px solid var(--ui-line); border-bottom: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 14px; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.legend-menu:has(.filter-product-legend) .ui-menu-panel { min-width: 360px; }

frontend/app/styles/shell.css.source:
/* App shell (UI overhaul phase 1): one header row with grouped navigation,
   the global plan controls and a single overflow menu. */

.topbar.app-header {
  height: 56px;
  min-height: 0;
  padding: 0 16px 0 20px;
  display: flex;
  align-items: center;
  gap: 14px;
  border-bottom: 1px solid var(--ui-line);
  background: var(--ui-surface);
  backdrop-filter: none;
}
.app-header .brand-area { display: flex; align-items: center; gap: 12px; flex: 0 0 auto; }
.app-header .brand { width: auto; }
.app-header .selsa-logo-frame { border-radius: var(--ui-radius-sm); }
.app-header .production-area-selector { min-width: 0; display: block; }
.app-header .production-area-selector > span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.app-header .production-area-selector select {
  height: var(--ui-control-h);
  padding: 0 8px;
  border: 1px solid var(--ui-line);
  border-radius: var(--ui-radius);
  background: var(--ui-surface);
  color: var(--ui-ink);
  font: 600 var(--ui-text-sm) var(--ui-font);
}

.app-header > nav.app-nav {
  height: 100%;
  min-width: 0;
  flex: 1 1 auto;
  display: flex;
  align-items: stretch;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.app-nav-group { display: flex; align-items: stretch; }
.app-nav-group + .app-nav-group { margin-left: 6px; padding-left: 6px; position: relative; }
.app-nav-group + .app-nav-group::before { content: ""; position: absolute; left: 0; top: 18px; bottom: 18px; width: 1px; background: var(--ui-line-strong); }
.app-header .nav-item {
  padding: 0 9px;
  flex-shrink: 0;
  border-bottom: 2px solid transparent;
  color: var(--ui-ink-2);
  font: var(--ui-label-weight) var(--ui-text-sm) var(--ui-font-label);
  letter-spacing: var(--ui-label-tracking);
  text-transform: var(--ui-label-case);
}
.app-header .nav-item:hover { background: transparent; color: var(--ui-ink); }
.app-header .nav-item.active { border-bottom-color: var(--ui-ink); color: var(--ui-ink); font-weight: 650; }

.plan-controls { display: flex; align-items: center; gap: 10px; flex: 0 0 auto; }
.plan-status {
  max-width: 230px;
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--ui-ink-2);
  font-size: var(--ui-text-xs);
}
.plan-status > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.plan-status > i { width: 7px; height: 7px; flex: 0 0 7px; border-radius: 50%; background: var(--ui-line-strong); }
.plan-status.dirty { color: var(--ui-ink); font-weight: 600; }
.plan-status.dirty > i { background: var(--ui-accent); box-shadow: 0 0 0 3px var(--ui-accent-soft); }
.app-header .ui-btn.primary.attention { box-shadow: none; }

.app-header .top-actions { margin-left: 0; display: flex; align-items: center; gap: 2px; flex: 0 0 auto; }
.app-header .advice-launch { min-height: 0; padding: 0; border: 1px solid transparent; background: transparent; color: var(--ui-ink-2); }
.app-header .advice-launch.active { border-color: transparent; background: transparent; color: var(--ui-ink); }
.app-header .advice-launch b {
  position: absolute;
  top: 1px;
  right: -2px;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  display: grid;
  place-items: center;
  border: 2px solid var(--ui-surface);
  border-radius: 9px;
  background: var(--ui-accent);
  color: var(--ui-accent-ink);
  font: 700 10px/1 var(--ui-font);
}
.app-header .updates-launch,
.app-header .feedback-header-launch {
  width: var(--ui-control-h);
  height: var(--ui-control-h);
  flex-basis: var(--ui-control-h);
  border-color: transparent;
  border-radius: var(--ui-radius);
  background: transparent;
  color: var(--ui-ink-2);
}
.app-header .updates-launch:hover,
.app-header .feedback-header-launch:hover,
.app-header .feedback-header-launch:focus-visible { border-color: transparent; background: var(--ui-surface-hover); color: var(--ui-ink); transform: none; }
.app-header .updates-launch.active { border-color: transparent; background: transparent; color: var(--ui-ink); }
.app-header .updates-launch b { border-color: var(--ui-surface); background: var(--ui-accent); color: var(--ui-accent-ink); font-size: 10px; }
.app-header .feedback-header-slot { width: auto; height: auto; flex: 0 0 auto; }
.app-header .account-control { margin-left: 6px; }
.app-header .account-copy { display: none; }

/* Shared page title row: title + guide toggle, then the screen's own slot
   (summary numbers, primary actions) via <PageBarSlot>. */
.page-bar { min-height: 56px; padding: 10px 20px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 24px; }
.page-bar-title { display: flex; align-items: center; gap: 4px; flex: 0 0 auto; }
.page-bar h1 { font: 650 var(--ui-text-lg)/1.2 var(--ui-font-display); letter-spacing: -0.01em; }
.page-bar-slot { min-width: 0; flex: 1 1 auto; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; }
.page-bar-slot:empty { display: none; }

@media (max-width: 1380px) {
  .plan-status { display: none; }
}
@media (max-width: 1180px) {
  .app-header .nav-item { padding: 0 7px; }
  .app-header .production-area-selector select { max-width: 110px; }
}

@media (max-width: 1366px) {
  .topbar.app-header { gap: 10px; padding-left: 12px; padding-right: 10px; }
  .app-header .brand-area { gap: 8px; }
  .app-header .production-area-selector select { max-width: 96px; }
  .app-header .nav-item { padding: 0 6px; }
  .app-nav-group + .app-nav-group { margin-left: 3px; padding-left: 3px; }
}


/* Narrow windows: navigation moves to its own scrollable row; nothing overlaps. */
@media (max-width: 1100px) {
  .topbar.app-header { height: auto; flex-wrap: wrap; row-gap: 0; padding-top: 8px; }
  .app-header .brand-area,
  .app-header .plan-controls,
  .app-header .top-actions { height: 40px; }
  .app-header .plan-controls { margin-left: auto; }
  .app-header > nav.app-nav { order: 10; flex: 1 0 100%; height: 40px; margin: 6px -10px 0 -12px; padding: 0 6px; border-top: 1px solid var(--ui-line); }
  .app-header .nav-item { padding: 0 10px; }
  .app-nav-group + .app-nav-group::before { top: 12px; bottom: 12px; }
}
@media (max-width: 600px) {
  .topbar.app-header { gap: 6px; padding-left: 8px; padding-right: 8px; }
  .app-header .plan-run-label { display: none; }
  .app-header .ui-split-button > .ui-btn { padding: 0 10px; }
  .app-header .top-actions { gap: 0; }
  .app-header .account-control { margin-left: 2px; }
  .app-header > nav.app-nav { margin: 6px -8px 0; }
  .page-bar { padding: 10px 12px; }
}
@media (max-width: 440px) {
  .app-header .brand { display: none; }
}
.plan-status { max-width: 200px; }
@media (max-width: 1500px) { .plan-status { max-width: 120px; } }

frontend/app/styles/stocks.css.source:
/* Stoklar (UI overhaul, Sade). Main object: the stock table per group.
   Week count and settings live in the title row; one row per product. */

.process-stock-view { margin: 0 20px 24px; border-radius: var(--ui-radius); border-color: var(--ui-line); box-shadow: none; }
.process-stock-view > .ui-status-line { margin: 12px 14px; }

/* Title row */
.stock-view-subtitle { display: inline-flex; align-items: center; color: var(--ui-ink-2); font-size: var(--ui-text-sm); }
.page-bar-slot .stock-view-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.stock-weeks-field { display: flex; align-items: center; gap: 8px; }
.stock-weeks-field input { width: 64px; }
.stock-view-actions button.active { border-color: var(--ui-ink); }

/* Group header */
.process-stock-group { border-bottom-color: var(--ui-line); }
.process-stock-group > header { padding: 12px 16px; background: var(--ui-surface); border-bottom-color: var(--ui-line); }
.process-stock-group h3 { font: 650 var(--ui-text-md) var(--ui-font); }
.process-stock-group dl div { padding: 2px 10px; border-color: var(--ui-line); background: var(--ui-surface); }
.process-stock-group dt { color: var(--ui-ink-3); font-size: var(--ui-text-xs); }
.process-stock-group dd { font-size: var(--ui-text-sm); }
.process-stock-group dl .low { border-color: color-mix(in srgb, var(--ui-danger) 40%, transparent); background: var(--ui-surface); }
.process-stock-group dl .low dd { color: var(--ui-danger); }
.process-stock-group dl .high { border-color: color-mix(in srgb, var(--ui-warn) 40%, transparent); background: var(--ui-surface); }
.process-stock-group dl .high dd { color: var(--ui-warn); }
.stock-view-issues { position: relative; margin-left: auto; padding: 0; border: 0; color: var(--ui-ink-2); font-size: var(--ui-text-xs); }
.stock-view-issues summary { color: var(--ui-ink-2); font-weight: 500; }
.stock-view-issues[open] .stock-view-issues-pop { position: absolute; right: 0; top: calc(100% + 6px); z-index: 30; width: min(520px, calc(100vw - 32px)); max-height: 360px; overflow: auto; padding: 12px 14px; border: 1px solid var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); box-shadow: var(--ui-shadow-pop); }

/* Table */
.process-stock-view .dispatch-plan-table { font-size: var(--ui-text-sm); }
.process-stock-view .dispatch-plan-table th,
.process-stock-view .dispatch-plan-table td { padding: 8px 12px; border-bottom-color: var(--ui-line); }
.process-stock-view .dispatch-plan-table thead th { background: var(--ui-surface-2); color: var(--ui-ink-2); font-size: var(--ui-text-xs); font-weight: 600; letter-spacing: 0; text-transform: none; }
.process-stock-view .dispatch-plan-table thead th small { display: block; margin-top: 2px; color: var(--ui-ink-3); font-size: 10px; font-weight: 400; text-transform: none; }
.process-stock-view .dispatch-plan-table thead th.day { background: var(--ui-surface-2); }
.process-stock-view .dispatch-plan-table th.day { min-width: 170px; box-shadow: 1px 0 0 var(--ui-line); }
.process-stock-view .dispatch-plan-table th.day b { font-size: var(--ui-text-sm); }
.process-stock-view .dispatch-plan-table th.day small { color: var(--ui-ink-3); font-size: var(--ui-text-xs); text-transform: none; letter-spacing: 0; }
.process-stock-view .dispatch-plan-table td.empty { color: var(--ui-ink-3); opacity: .55; }
.process-stock-view .dispatch-plan-table td.open { color: var(--ui-danger); }
.process-stock-view .dispatch-plan-table tbody tr:not(.week):hover td { background: var(--ui-surface-2); }

/* Group total: quiet unless out of range */
.process-stock-view .stock-total-row th.day,
.process-stock-view .stock-total-row td { background: var(--ui-surface-2); }
.process-stock-view .stock-total-row td strong { display: block; font-size: var(--ui-text-sm); }
.process-stock-view .stock-total-row td small { display: block; font-size: 10px; font-weight: 400; }
.process-stock-view .stock-total-row td.ok { color: var(--ui-ink-2); }
.process-stock-view .stock-total-row td.low { color: var(--ui-danger); }
.process-stock-view .stock-total-row td.high { color: var(--ui-warn); }

/* Production row at the end */
.stock-view-production { padding: 12px 16px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; border-top: 1px solid var(--ui-line); }
.stock-view-production strong { display: inline-flex; align-items: center; margin-right: auto; font-size: var(--ui-text-sm); }
.stock-view-production select { min-height: var(--ui-control-h); border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); font-size: var(--ui-text-sm); }

@media (max-width: 900px) {
  .process-stock-view { margin: 0 12px 16px; }
  .page-bar-slot .stock-view-actions { margin-left: 0; }
  .stock-view-issues { margin-left: 0; }
}
.process-stock-view .stock-quantity-row th.day b { display: block; }
.process-stock-view .stock-quantity-row th.day small { margin: 2px 0 0 !important; }
.process-stock-view .stock-quantity-row td, .process-stock-view .stock-quantity-row th.day { padding-top: 8px; }
.stock-settings-drawer .process-stock-settings { margin: 0; padding: 0; border: 0; background: transparent; box-shadow: none; }
.stock-settings-drawer .process-stock-settings > h2:first-child { display: none; }
.stock-settings-drawer .process-stock-settings p { color: var(--ui-ink-2); font-size: var(--ui-text-xs); line-height: 1.5; }
.stock-settings-drawer .process-stock-settings details { border-radius: var(--ui-radius-sm); border-color: var(--ui-line); }

frontend/app/styles/tokens.css.source:
/* Design tokens (UI overhaul, "Sade" direction).
   New CSS uses only --ui-* tokens. The legacy variables at the bottom are
   remapped so older screens follow the tokens until they are migrated. */

:root {
  --ui-bg: #f4f5f3;
  --ui-surface: #ffffff;
  --ui-surface-2: #f8f9f7;
  --ui-surface-hover: #f1f3f0;
  --ui-line: #e2e5e1;
  --ui-line-strong: #c8cdc8;
  --ui-ink: #17201c;
  --ui-ink-2: #59645e;
  --ui-ink-3: #89928d;
  --ui-accent: #e2572a;
  --ui-accent-hover: #cc4a20;
  --ui-accent-ink: #ffffff;
  --ui-accent-soft: #fdeee8;
  --ui-ok: #23704f;
  --ui-warn: #a0621a;
  --ui-danger: #be4338;
  --ui-danger-soft: #fbeceb;
  --ui-focus: #2f6fde;

  --ui-font: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --ui-font-display: Manrope, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --ui-font-label: var(--ui-font);
  --ui-font-num: var(--ui-font);
  --ui-label-case: none;
  --ui-label-tracking: 0;
  --ui-label-weight: 500;
  --ui-num-weight: 650;
  --ui-num-tracking: -0.02em;

  --ui-text-xs: 11px;
  --ui-text-sm: 12px;
  --ui-text-md: 14px;
  --ui-text-lg: 18px;
  --ui-text-xl: 28px;

  --ui-radius: 7px;
  --ui-radius-sm: 5px;
  --ui-control-h: 32px;
  --ui-shadow-pop: 0 12px 32px rgba(20, 28, 24, 0.14);
}

/* Legacy variables used across globals.css. */
:root {
  --ink: var(--ui-ink);
  --muted: var(--ui-ink-2);
  --line: var(--ui-line);
  --paper: var(--ui-bg);
  --white: var(--ui-surface);
  --accent: var(--ui-accent);
  --accent-soft: var(--ui-accent-soft);
  --green: var(--ui-ok);
  --red: var(--ui-danger);
  --font-sans: var(--ui-font);
  --font-display: var(--ui-font-display);
}

html, body { background: var(--ui-bg); color: var(--ui-ink); }
:focus-visible { outline-color: var(--ui-focus); }

frontend/app/styles/ui.css.source:
/* Shared primitives (UI overhaul phase 0): buttons, icon buttons, menus. */

.ui-btn {
  min-height: var(--ui-control-h);
  padding: 0 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--ui-line-strong);
  border-radius: var(--ui-radius);
  background: var(--ui-surface);
  color: var(--ui-ink);
  font: var(--ui-label-weight) var(--ui-text-sm) var(--ui-font-label);
  letter-spacing: var(--ui-label-tracking);
  text-transform: var(--ui-label-case);
  white-space: nowrap;
  cursor: pointer;
  list-style: none;
}
.ui-btn::-webkit-details-marker { display: none; }
.ui-btn:hover:not(:disabled) { background: var(--ui-surface-hover); }
.ui-btn:disabled { opacity: 0.45; cursor: not-allowed; }
.ui-btn.primary { border-color: var(--ui-accent); background: var(--ui-accent); color: var(--ui-accent-ink); }
.ui-btn.primary:hover:not(:disabled) { border-color: var(--ui-accent-hover); background: var(--ui-accent-hover); }

.ui-icon-btn {
  position: relative;
  width: var(--ui-control-h);
  height: var(--ui-control-h);
  flex: 0 0 var(--ui-control-h);
  display: inline-grid;
  place-items: center;
  border: 1px solid transparent;
  border-radius: var(--ui-radius);
  background: transparent;
  color: var(--ui-ink-2);
  cursor: pointer;
  list-style: none;
}
.ui-icon-btn::-webkit-details-marker { display: none; }
.ui-icon-btn:hover { background: var(--ui-surface-hover); color: var(--ui-ink); }

.ui-menu { position: relative; }
.ui-menu[open] > summary { background: var(--ui-surface-hover); color: var(--ui-ink); }
.ui-menu-panel {
  position: absolute;
  top: calc(100% + 6px);
  z-index: 40;
  min-width: 220px;
  max-width: min(420px, calc(100vw - 32px));
  padding: 5px;
  display: grid;
  gap: 1px;
  border: 1px solid var(--ui-line);
  border-radius: var(--ui-radius);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-pop);
}
.ui-menu-panel.end { right: 0; }
.ui-menu-panel.start { left: 0; }
.ui-menu-item {
  min-height: 34px;
  padding: 6px 9px;
  display: flex;
  align-items: center;
  gap: 9px;
  border: 0;
  border-radius: var(--ui-radius-sm);
  background: transparent;
  color: var(--ui-ink);
  font: 500 var(--ui-text-sm) var(--ui-font);
  text-align: left;
  cursor: pointer;
}
.ui-menu-item > span { display: flex; flex-direction: column; gap: 2px; }
.ui-menu-item svg { flex: 0 0 auto; color: var(--ui-ink-2); }
.ui-menu-item:hover:not(:disabled) { background: var(--ui-surface-hover); }
.ui-menu-item:disabled { opacity: 0.4; cursor: default; }
.ui-menu-item.active { font-weight: 650; }
.ui-menu-item.active::after { content: ""; width: 6px; height: 6px; margin-left: auto; border-radius: 50%; background: var(--ui-accent); }
.ui-menu-hint { color: var(--ui-ink-3); font-size: var(--ui-text-xs); font-weight: 400; }
.ui-menu-label {
  padding: 8px 9px 3px;
  color: var(--ui-ink-3);
  font: var(--ui-label-weight) var(--ui-text-xs) var(--ui-font-label);
  letter-spacing: var(--ui-label-tracking);
  text-transform: var(--ui-label-case);
}
.ui-menu-divider { height: 1px; margin: 4px 2px; background: var(--ui-line); }

.ui-split-button { display: inline-flex; align-items: stretch; }
.ui-split-button > .ui-btn { border-top-right-radius: 0; border-bottom-right-radius: 0; }
.ui-split-button > .ui-menu > summary {
  height: 100%;
  width: 28px;
  flex-basis: 28px;
  border: 1px solid var(--ui-accent);
  border-left-color: rgba(255, 255, 255, 0.35);
  border-radius: 0 var(--ui-radius) var(--ui-radius) 0;
  background: var(--ui-accent);
  color: var(--ui-accent-ink);
}
.ui-split-button > .ui-menu > summary:hover,
.ui-split-button > .ui-menu[open] > summary { background: var(--ui-accent-hover); color: var(--ui-accent-ink); }

/* Badge */
.ui-badge {
  min-height: 20px;
  padding: 1px 7px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1px solid var(--ui-line-strong);
  border-radius: 999px;
  background: transparent;
  color: var(--ui-ink-2);
  font: 600 var(--ui-text-xs)/1.2 var(--ui-font);
  white-space: nowrap;
}
.ui-badge.ok { border-color: color-mix(in srgb, var(--ui-ok) 45%, transparent); color: var(--ui-ok); }
.ui-badge.warn { border-color: color-mix(in srgb, var(--ui-warn) 45%, transparent); color: var(--ui-warn); }
.ui-badge.danger { border-color: color-mix(in srgb, var(--ui-danger) 45%, transparent); background: var(--ui-danger-soft); color: var(--ui-danger); }
.ui-badge.accent { border-color: var(--ui-accent); background: var(--ui-accent-soft); color: var(--ui-accent-hover); }

/* Help tip */
.ui-help {
  position: relative;
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  display: inline-grid;
  place-items: center;
  margin-left: 4px;
  border-radius: 50%;
  color: var(--ui-ink-3);
  vertical-align: middle;
  cursor: help;
  outline: none;
}
.ui-help:hover, .ui-help:focus-visible { background: var(--ui-surface-hover); color: var(--ui-ink); }
.ui-help [role="tooltip"] {
  position: absolute;
  z-index: 60;
  bottom: calc(100% + 7px);
  left: 50%;
  width: max-content;
  max-width: min(300px, calc(100vw - 32px));
  padding: 8px 10px;
  border-radius: var(--ui-radius-sm);
  background: var(--ui-ink);
  color: #fff;
  font: 400 var(--ui-text-xs)/1.45 var(--ui-font);
  text-align: left;
  text-transform: none;
  letter-spacing: 0;
  white-space: normal;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 3px);
  transition: opacity .14s ease, transform .14s ease, visibility .14s;
}
.ui-help.start [role="tooltip"] { left: -6px; transform: translate(0, 3px); }
.ui-help.end [role="tooltip"] { left: auto; right: -6px; transform: translate(0, 3px); }
.ui-help:hover [role="tooltip"], .ui-help:focus-visible [role="tooltip"] { visibility: visible; opacity: 1; transform: translate(-50%, 0); }
.ui-help.start:hover [role="tooltip"], .ui-help.start:focus-visible [role="tooltip"],
.ui-help.end:hover [role="tooltip"], .ui-help.end:focus-visible [role="tooltip"] { transform: translate(0, 0); }

/* Panel */
.ui-panel { min-width: 0; border: 1px solid var(--ui-line); border-radius: var(--ui-radius); background: var(--ui-surface); }
.ui-panel-head { min-height: 48px; padding: 10px 16px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; border-bottom: 1px solid var(--ui-line); }
.ui-panel-head h2 { margin: 0; display: flex; align-items: center; color: var(--ui-ink); font: 650 var(--ui-text-md)/1.3 var(--ui-font); }
.ui-panel-actions { margin-left: auto; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }

/* Status line */
.ui-status-line { border: 1px solid var(--ui-line); border-left-width: 3px; border-radius: var(--ui-radius-sm); background: var(--ui-surface); }
.ui-status-line.danger { border-left-color: var(--ui-danger); }
.ui-status-line.warn { border-left-color: var(--ui-warn); }
.ui-status-line.info, .ui-status-line.ok { border-left-color: var(--ui-line-strong); }
.ui-status-main, .ui-status-list li { min-height: 40px; padding: 7px 12px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; }
.ui-status-main > svg, .ui-status-list li > svg { flex: 0 0 auto; }
.ui-status-line .danger > svg, .ui-status-line.danger .ui-status-main > svg { color: var(--ui-danger); }
.ui-status-line .warn > svg, .ui-status-line.warn .ui-status-main > svg { color: var(--ui-warn); }
.ui-status-line .info > svg, .ui-status-line.info .ui-status-main > svg, .ui-status-line .ok > svg { color: var(--ui-ink-3); }
.ui-status-text { min-width: 0; flex: 1 1 260px; display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; }
.ui-status-text strong { color: var(--ui-ink); font-size: var(--ui-text-sm); font-weight: 600; }
.ui-status-text small { color: var(--ui-ink-2); font-size: var(--ui-text-xs); line-height: 1.45; }
.ui-status-more { margin-left: auto; min-height: 28px; padding: 0 8px; display: inline-flex; align-items: center; gap: 5px; border: 0; border-radius: var(--ui-radius-sm); background: transparent; color: var(--ui-ink-2); font: 600 var(--ui-text-xs) var(--ui-font); cursor: pointer; }
.ui-status-more:hover { background: var(--ui-surface-hover); color: var(--ui-ink); }
.ui-status-list { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--ui-line); }
.ui-status-list li + li { border-top: 1px solid var(--ui-line); }

/* Drawer */
.ui-drawer-backdrop { position: fixed; inset: 0; z-index: 70; display: flex; justify-content: flex-end; background: rgba(20, 28, 24, 0.28); }
.ui-drawer { height: 100%; display: flex; flex-direction: column; border-left: 1px solid var(--ui-line); background: var(--ui-surface); box-shadow: var(--ui-shadow-pop); }
.ui-drawer-head { padding: 16px 16px 14px 20px; display: flex; align-items: flex-start; gap: 12px; border-bottom: 1px solid var(--ui-line); }
.ui-drawer-head > div { min-width: 0; flex: 1 1 auto; }
.ui-drawer-head h2 { margin: 0; font: 650 var(--ui-text-lg)/1.25 var(--ui-font-display); }
.ui-drawer-head p { margin: 4px 0 0; color: var(--ui-ink-2); font-size: var(--ui-text-sm); line-height: 1.4; }
.ui-drawer-body { min-height: 0; flex: 1 1 auto; overflow: auto; padding: 16px 20px; }
.ui-drawer-foot { padding: 12px 20px; display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; border-top: 1px solid var(--ui-line); }

/* Generic data table look for redesigned screens: add .ui-table to a <table>. */
.ui-table { width: 100%; border-collapse: collapse; }
.ui-table th { padding: 10px 12px; border-bottom: 1px solid var(--ui-line); background: var(--ui-surface-2); color: var(--ui-ink-2); font: 600 var(--ui-text-xs)/1.3 var(--ui-font); letter-spacing: 0; text-align: left; text-transform: none; }
.ui-table td { padding: 10px 12px; border-bottom: 1px solid var(--ui-line); color: var(--ui-ink); font-size: var(--ui-text-sm); vertical-align: middle; }
.ui-table tbody tr:hover td { background: var(--ui-surface-2); }
.ui-table .numeric { text-align: right; font-variant-numeric: tabular-nums; }

/* Form fields for redesigned screens: add .ui-field to a <label>. */
.ui-field { display: grid; gap: 5px; color: var(--ui-ink-2); font: 500 var(--ui-text-xs) var(--ui-font); }
.ui-field :is(input, select, textarea),
.ui-input { min-height: var(--ui-control-h); padding: 0 9px; border: 1px solid var(--ui-line-strong); border-radius: var(--ui-radius-sm); background: var(--ui-surface); color: var(--ui-ink); font: 400 var(--ui-text-sm) var(--ui-font); }
.ui-field textarea { min-height: 80px; padding: 8px 9px; }
.ui-field :is(input, select, textarea):focus-visible,
.ui-input:focus-visible { outline: 2px solid var(--ui-focus); outline-offset: 1px; }

/* Hidden tooltips must not widen the page on narrow screens. */
.ui-help [role="tooltip"],
.number-help-trigger [role="tooltip"] { display: none; }
.ui-help:hover [role="tooltip"], .ui-help:focus-visible [role="tooltip"],
.number-help-trigger:hover [role="tooltip"], .number-help-trigger:focus-visible [role="tooltip"] { display: block; }
.number-help-trigger [role="tooltip"] { max-width: min(260px, calc(100vw - 32px)); }

frontend/components/AppUpdates.tsx.source:
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Bell, Check, EyeSlash, MegaphoneSimple, PencilSimple, Plus, Trash, X } from "@phosphor-icons/react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { useApiFetch } from "@/lib/api";
import { normalizeUpdateBullets, unreadUpdateCount, visibleAppUpdates, type AppUpdate } from "@/lib/app-updates";
import { formatInteger } from "@/lib/number-format";

export function AppUpdates({ canManage = false }: { canManage?: boolean }) {
  const apiFetch = useApiFetch();
  const [updates, setUpdates] = useState<AppUpdate[]>([]);
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [hideSeen, setHideSeen] = useState(false);
  const [editing, setEditing] = useState<AppUpdate | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);
  const loadVersion = useRef(0);
  const unreadCount = unreadUpdateCount(updates);
  const seenCount = updates.length - unreadCount;
  const filteredUpdates = visibleAppUpdates(updates, hideSeen);
  useRaviScreenContext("app-updates", { open, hideSeen, unreadCount, editingId: editing?.id, deletingId, deleting, error, visibleUpdates: filteredUpdates.slice(0, 20) });

  const reload = useCallback(async () => {
    const version = ++loadVersion.current;
    try {
      const response = await apiFetch("/app-updates");
      if (!response.ok) throw new Error("Güncellemeler yüklenemedi");
      const loaded = await response.json() as AppUpdate[];
      if (version !== loadVersion.current) return;
      setUpdates(loaded);
      setError("");
    } catch (caught) {
      if (version !== loadVersion.current) return;
      setError(caught instanceof Error ? caught.message : "Güncellemeler yüklenemedi");
    } finally {
      if (version === loadVersion.current) setLoading(false);
    }
  }, [apiFetch]);

  useEffect(() => {
    void reload();
    const interval = window.setInterval(() => void reload(), 60_000);
    const refreshWhenVisible = () => { if (document.visibilityState === "visible") void reload(); };
    document.addEventListener("visibilitychange", refreshWhenVisible);
    return () => {
      window.clearInterval(interval);
      document.removeEventListener("visibilitychange", refreshWhenVisible);
    };
  }, [reload]);

  useEffect(() => {
    if (!open) return;
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") setOpen(false); };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [open]);

  async function markSeen(update: AppUpdate) {
    if (update.seen_at) return;
    setError("");
    try {
      const response = await apiFetch(`/app-updates/${update.id}/seen`, { method: "POST" });
      if (!response.ok) throw new Error("Görüldü bilgisi kaydedilemedi");
      const changed = await response.json() as AppUpdate;
      ++loadVersion.current;
      setUpdates((current) => current.map((item) => item.id === changed.id ? { ...item, seen_at: changed.seen_at } : item));
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Görüldü bilgisi kaydedilemedi");
    }
  }

  async function publish(title: string, bullets: string[]) {
    setError("");
    const response = await apiFetch("/app-updates", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, bullets }),
    });
    if (!response.ok) {
      const payload = await response.json().catch(() => null) as { detail?: string } | null;
      throw new Error(payload?.detail || (response.status === 403 ? "Bu hesap güncelleme yayınlama yetkisine sahip değil." : "Güncelleme yayınlanamadı"));
    }
    const created = await response.json() as AppUpdate;
    ++loadVersion.current;
    setUpdates((current) => [created, ...current]);
  }

  async function edit(update: AppUpdate, title: string, bullets: string[]) {
    const response = await apiFetch(`/app-updates/${update.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ title, bullets }) });
    if (!response.ok) {
      const payload = await response.json().catch(() => null) as { detail?: string } | null;
      throw new Error(payload?.detail || "Güncelleme düzenlenemedi");
    }
    const changed = await response.json() as AppUpdate;
    ++loadVersion.current;
    setUpdates(current => current.map(item => item.id === changed.id ? changed : item));
    setEditing(null);
  }

  async function remove(update: AppUpdate) {
    setDeleting(true); setError("");
    try {
      const response = await apiFetch(`/app-updates/${update.id}`, { method: "DELETE" });
      if (!response.ok) {
        const payload = await response.json().catch(() => null) as { detail?: string } | null;
        throw new Error(payload?.detail || "Güncelleme silinemedi");
      }
      ++loadVersion.current;
      setUpdates(current => current.filter(item => item.id !== update.id));
      setDeletingId(null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Güncelleme silinemedi");
    } finally { setDeleting(false); }
  }

  return <>
    <button
      className={`updates-launch ${unreadCount ? "active" : ""}`}
      onClick={() => setOpen(true)}
      aria-label={unreadCount ? `${unreadCount} görülmemiş uygulama güncellemesi` : "Uygulama güncellemeleri"}
      title="Uygulama güncellemeleri"
    >
      <Bell size={17} weight={unreadCount ? "fill" : "regular"} />
      {unreadCount > 0 && <b>{unreadCount > 99 ? "99+" : unreadCount}</b>}
    </button>
    {open && createPortal(<div className="updates-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setOpen(false); }}>
      <aside className="updates-drawer" role="dialog" aria-modal="true" aria-labelledby="updates-title">
        <header className="updates-head">
          <span className="updates-head-icon"><Bell size={19} weight={unreadCount ? "fill" : "regular"} /></span>
          <div><span>UYGULAMA GÜNCELLEMELERİ</span><h2 id="updates-title">Neler değişti?</h2><p>{unreadCount ? `${formatInteger(unreadCount)} güncelleme görülmeyi bekliyor.` : "Tüm güncellemeler görüldü."}</p></div>
          <button onClick={() => setOpen(false)} aria-label="Güncellemeleri kapat"><X size={17} /></button>
        </header>
        {canManage && <UpdateComposer onPublish={publish} />}
        <div className="updates-controls">
          <button className={hideSeen ? "active" : ""} aria-pressed={hideSeen} onClick={() => setHideSeen((current) => !current)}><EyeSlash size={14} weight={hideSeen ? "fill" : "regular"} /> Görülenleri gizle <b>{formatInteger(seenCount)}</b></button>
          <span>{formatInteger(filteredUpdates.length)} / {formatInteger(updates.length)} gösteriliyor</span>
        </div>
        {error && <p className="updates-error" role="alert">{error}</p>}
        <div className="updates-list" aria-live="polite">
          {loading ? <UpdateEmpty title="Güncellemeler yükleniyor…" detail="Kısa bir süre içinde burada görünecek." /> : updates.length === 0 ? <UpdateEmpty title="Henüz güncelleme yok" detail={canManage ? "İlk sürüm notunu yukarıdaki alandan yayınlayabilirsiniz." : "Yayınlanan sürüm notları burada görünecek."} /> : filteredUpdates.length === 0 ? <UpdateEmpty title="Görülmemiş güncelleme yok" detail="Görülen güncellemeleri yeniden göstermek için filtreyi kapatabilirsiniz." /> : filteredUpdates.map((update) => (
            <article key={update.id} className={update.seen_at ? "seen" : "unread"}>
              <div className="update-meta"><span>{update.seen_at ? "GÖRÜLDÜ" : "YENİ"}</span><time dateTime={update.created_at}>{formatUpdateDate(update.created_at)}</time></div>
              {editing?.id === update.id && canManage ? <UpdateComposer key={update.id} initialUpdate={editing} onCancel={() => setEditing(null)} onPublish={(title, bullets) => edit(update, title, bullets)} /> : <><h3>{update.title}</h3>
              <ul>{update.bullets.map((bullet, index) => <li key={`${update.id}-${index}`}>{bullet}</li>)}</ul></>}
              <footer>
                {update.seen_at ? <span><Check size={13} weight="bold" /> {formatSeenDate(update.seen_at)} görüldü</span> : <button onClick={() => void markSeen(update)}><Check size={14} weight="bold" /> Görüldü</button>}
                {canManage && !editing && <div className="update-manage-actions"><button disabled={deleting} onClick={() => { setEditing(update); setDeletingId(null); setError(""); }}><PencilSimple size={14} /> Düzenle</button><button disabled={deleting} onClick={() => { setDeletingId(update.id); setError(""); }}><Trash size={14} /> Sil</button></div>}
              </footer>
              {canManage && deletingId === update.id && <div className="update-delete-confirm" role="alertdialog" aria-label="Güncellemeyi sil"><strong>“{update.title}” silinsin mi?</strong><p>Bu güncelleme tüm kullanıcıların listesinden kaldırılacak. Bu işlem geri alınamaz.</p><div><button disabled={deleting} onClick={() => setDeletingId(null)}>Vazgeç</button><button disabled={deleting} onClick={() => void remove(update)}>{deleting ? "Siliniyor…" : "Güncellemeyi sil"}</button></div></div>}
            </article>
          ))}
        </div>
      </aside>
    </div>, document.body)}
  </>;
}

function UpdateComposer({ onPublish, initialUpdate, onCancel }: { onPublish: (title: string, bullets: string[]) => Promise<void>; initialUpdate?: AppUpdate; onCancel?: () => void }) {
  const [open, setOpen] = useState(Boolean(initialUpdate));
  const [title, setTitle] = useState(initialUpdate?.title ?? "");
  const [body, setBody] = useState(initialUpdate?.bullets.join("\n") ?? "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const bullets = normalizeUpdateBullets(body);
  useRaviScreenContext(initialUpdate ? "app-update-editor" : "app-update-composer", { open, updateId: initialUpdate?.id, title, bullets, saving, error });

  async function submit() {
    if (!title.trim() || bullets.length === 0) {
      setError("Bir başlık ve en az bir değişiklik maddesi yazın.");
      return;
    }
    setSaving(true); setError("");
    try {
      await onPublish(title.trim(), bullets);
      setTitle(""); setBody(""); setOpen(false);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Güncelleme yayınlanamadı");
    } finally {
      setSaving(false);
    }
  }

  if (!open) return <button className="update-compose-launch" onClick={() => setOpen(true)}><Plus size={15} weight="bold" /> Yeni güncelleme yayınla</button>;

  return <section className="update-composer" aria-label={initialUpdate ? "Uygulama güncellemesini düzenle" : "Yeni uygulama güncellemesi"}>
    <div className="update-composer-title"><span><MegaphoneSimple size={16} /><strong>{initialUpdate ? "Güncellemeyi düzenle" : "Yeni güncelleme"}</strong></span><button disabled={saving} onClick={() => { setOpen(false); setError(""); onCancel?.(); }} aria-label="Güncelleme formunu kapat"><X size={14} /></button></div>
    <label>Başlık<input autoFocus value={title} maxLength={180} onChange={(event) => setTitle(event.target.value)} placeholder="Örn. Plan görünümü iyileştirildi" /></label>
    <label>Değişiklikler<textarea value={body} onChange={(event) => setBody(event.target.value)} placeholder={"Her satıra bir madde yazın\nTermin filtresi eklendi\nTezgah satırları hızlandırıldı"} /></label>
    <div className="update-composer-foot"><span>{bullets.length}/12 madde</span><button disabled={saving || !title.trim() || bullets.length === 0 || bullets.length > 12 || bullets.some(bullet => bullet.length > 500)} onClick={() => void submit()}>{saving ? "Kaydediliyor…" : initialUpdate ? "Değişiklikleri kaydet" : "Yayınla"}</button></div>
    {error && <p role="alert">{error}</p>}
  </section>;
}

function UpdateEmpty({ title, detail }: { title: string; detail: string }) {
  return <div className="updates-empty"><Bell size={24} /><strong>{title}</strong><span>{detail}</span></div>;
}

function formatUpdateDate(value: string): string {
  return new Intl.DateTimeFormat("tr-TR", { day: "numeric", month: "long", year: "numeric" }).format(new Date(value));
}

function formatSeenDate(value: string): string {
  return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }).format(new Date(value));
}

frontend/components/DeliveryAllocationFo.source:
"use client";

import type { ReactNode } from "react";
import { CheckCircle } from "@phosphor-icons/react";
import { Field } from "@/features/planning/shared/controls";
import { formatInteger as formatNumber } from "@/lib/number-format";

export type DeliveryAllocationDraft = {
  actualQuantity: number;
  completedDate: string;
  deliveredQuantity: number;
  deliveryDate: string;
  remainderAction: "keep" | "scrap";
};

export function DeliveryAllocationForm({ product, draft, onChange, error, onClose, onSave, children }: {
  product: string; draft: DeliveryAllocationDraft; onChange: (draft: DeliveryAllocationDraft) => void;
  error: string; onClose: () => void; onSave: () => void; children?: ReactNode;
}) {
  const remainder = Math.max(0, draft.actualQuantity - draft.deliveredQuantity);
  return <section className="completion-dialog archive-action-dialog archive-allocation-dialog" role="dialog" aria-modal="true" aria-label={`${product} teslimat ve ıskarta ayrımı`}>
    <CheckCircle size={24} />
    <span>FİİLİ ÜRETİM VE TESLİMAT</span>
    <h2>{product}</h2>
    <p>Gerçek tamamlanan adedi girin. Teslim edilen kısmı ayırın; kalan miktarı yarı mamulde tutun veya ıskartaya çevirin.</p>
    <div className="archive-allocation-grid">
      <Field label="Fiili tamamlanan adet">
        <input type="number" min="1" step="1" value={draft.actualQuantity || ""} onChange={(event) => onChange({ ...draft, actualQuantity: Number(event.target.value), deliveredQuantity: Math.min(draft.deliveredQuantity, Number(event.target.value)) })} />
      </Field>
      <Field label="Gerçek tamamlanma tarihi">
        <input type="date" value={draft.completedDate} onChange={(event) => onChange({ ...draft, completedDate: event.target.value })} />
      </Field>
      <Field label="Teslim edilen adet">
        <input type="number" min="0" max={draft.actualQuantity} step="1" value={draft.deliveredQuantity} onChange={(event) => onChange({ ...draft, deliveredQuantity: Number(event.target.value) })} />
      </Field>
      <Field label="Teslim tarihi ve saati">
        <input type="datetime-local" disabled={draft.deliveredQuantity === 0} value={draft.deliveryDate} onChange={(event) => onChange({ ...draft, deliveryDate: event.target.value })} />
      </Field>
    </div>
    {children}
    <div className="archive-remainder">
      <span><small>Kalan miktar</small><strong>{formatNumber(remainder)} adet</strong></span>
      {remainder > 0 && <div role="radiogroup" aria-label="Kalan miktar işlemi">
        <label>
          <input type="radio" name="remainder-action" checked={draft.remainderAction === "keep"} onChange={() => onChange({ ...draft, remainderAction: "keep" })} />
          <span><strong>Yarı mamulde bırak</strong><small>Sonraki teslimatta kullanılabilir</small></span>
        </label>
        <label className="scrap-choice">
          <input type="radio" name="remainder-action" checked={draft.remainderAction === "scrap"} onChange={() => onChange({ ...draft, remainderAction: "scrap" })} />
          <span><strong>Iskartaya ayır</strong><small>Iskartalar listesinde izlenir</small></span>
        </label>
      </div>}
    </div>
    {error && <p className="archive-export-error" role="alert">{error}</p>}
    <div className="drawer-actions">
      <button className="secondary" onClick={onClose}>Vazgeç</button>
      <button className="primary" disabled={!draft.actualQuantity || !draft.completedDate || draft.deliveredQuantity > draft.actualQuantity || (draft.deliveredQuantity > 0 && !draft.deliveryDate)} onClick={onSave}>
        <CheckCircle size={15} /> Teslimat ayrımını kaydet
      </button>
    </div>
  </section>;
}

