"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";
import { Badge, HelpTip, PageBarSlot } from "@/components/ui/primitives";
import { Metric } from "@/features/planning/shared/controls";

import { useMemo, useState } from "react";
import { ArrowRight, CalendarBlank, CheckCircle, FileXls, Info, MagnifyingGlass, Warning, WarningCircle, X } from "@phosphor-icons/react";
import { useApiFetch } from "@/lib/api";
import { buildDashboardModel, type MachineDashboard } from "@/lib/dashboard";
import { buildGeneralOverviewExportPayload, type GeneralOverviewExportPayload, type GeneralPlanProcess } from "@/lib/general-overview";
import { buildMachineDiagnostics, type MachineDiagnostic } from "@/lib/machine-diagnostics";
import { buildPlanAudit, type AuditFinding, type AuditTarget } from "@/lib/plan-audit";
import { formatExcelDate, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { factoryDateAfterDays, factoryDateInput } from "@/lib/factory-time";
import { formatInteger } from "@/lib/number-format";

type MachineFilter = "all" | "active" | "planned";
type OperationPlan = GeneralOverviewExportPayload["operationPlans"][number];
type OperationResource = OperationPlan["resources"][number];

export function PlanControl({ seed, result, dirty, onNavigate }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; onNavigate: (target: AuditTarget) => void }) {
  const apiFetch = useApiFetch();
  const dashboard = useMemo(() => buildDashboardModel(seed, result), [result, seed]);
  const audit = useMemo(() => buildPlanAudit(seed, result, { dirty }), [dirty, result, seed]);
  const diagnostics = useMemo(() => buildMachineDiagnostics(seed, result, { dirty }), [dirty, result, seed]);
  const overview = useMemo(() => buildGeneralOverviewExportPayload(seed, result, dirty), [dirty, result, seed]);
  const [activeProcess, setActiveProcess] = useState<GeneralPlanProcess>("turning");
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<MachineFilter>("all");
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState("");
  const [exportDialogOpen, setExportDialogOpen] = useState(false);
  const [exportStart, setExportStart] = useState(factoryDateInput());
  const exportEnd = exportStart ? factoryDateAfterDays(14, `${exportStart}T12:00:00`) : "";
  useRaviScreenContext("control", { activeProcess, query, filter, exportDialogOpen, exportStart, exportEnd,
    audit, calculationSource: "buildDashboardModel / buildPlanAudit / buildGeneralOverviewExportPayload" });
  const hasPlan = result.state === "planned";
  const activePlan = overview.operationPlans.find((plan) => plan.process === activeProcess) ?? overview.operationPlans[0];
  const normalizedQuery = query.trim().toLocaleLowerCase("tr-TR");
  const visibleMachines = dashboard.machines.filter((board) => {
    if (filter === "active" && !board.machine.active) return false;
    if (filter === "planned" && board.plannedCount === 0) return false;
    if (!normalizedQuery) return true;
    return `${board.machine.id} ${board.machine.name} ${board.queue.flatMap((item) => [item.product, item.workOrder]).join(" ")}`.toLocaleLowerCase("tr-TR").includes(normalizedQuery);
  });
  const visibleResources = (activePlan?.resources ?? []).filter((resource) => {
    if (filter === "planned" && resource.rows.length === 0) return false;
    if (!normalizedQuery) return true;
    return `${resource.id} ${resource.name} ${resource.rows.flatMap((item) => [item.product, item.workOrder]).join(" ")}`.toLocaleLowerCase("tr-TR").includes(normalizedQuery);
  });

  async function exportOverview() {
    setExporting(true);
    setExportError("");
    try {
      const dayCount = Math.floor((Date.parse(`${exportEnd}T00:00:00Z`) - Date.parse(`${exportStart}T00:00:00Z`)) / 86_400_000) + 1;
      if (activeProcess !== "turning" && (!exportStart || !exportEnd || dayCount !== 15)) throw new Error("Saha planı tarih aralığı 15 gün olmalıdır.");
      const payload = buildGeneralOverviewExportPayload(seed, result, dirty, new Date().toISOString(), activeProcess, activeProcess === "turning" ? { nextJobsOnly: true } : { startDate: exportStart, endDate: exportEnd });
      const response = await apiFetch("/general-overview/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
      if (!response.ok) {
        const body = await response.json().catch(() => ({})) as { detail?: string };
        throw new Error(body.detail || "Genel Bakış Excel’i oluşturulamadı.");
      }
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? (activeProcess === "turning" ? "Torna_Saha_Plani_Siradaki_10_Is.xlsx" : `${activePlan?.label ?? "Operasyon"}_Saha_Plani_${exportStart}_${exportEnd}.xlsx`);
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
      setExportDialogOpen(false);
    } catch (reason) {
      setExportError(reason instanceof Error ? reason.message : "Genel Bakış Excel’i oluşturulamadı.");
    } finally {
      setExporting(false);
    }
  }

  const planState = dirty ? "Girdiler değişti · planı yeniden çalıştırın" : hasPlan ? `Son plan: ${formatTimestamp(result.createdAt)}` : "Plan henüz çalıştırılmadı";

  return (
    <section className="dashboard-layout">
      <PageBarSlot>
        <div className="metrics kpi-strip overview-kpis" role="group" aria-label="Plan özeti">
          <Metric compact label="Sipariş talebi" value={number(result.summary.demand)} detail="adet" description="Seçili üretim alanındaki toplam sipariş talebi (adet)." />
          <Metric compact label="Karşılanan" value={hasPlan ? number(result.summary.planned) : "—"} detail={hasPlan ? `${percent(dashboard.coverage)} karşılama` : "hesaplanmadı"} description="Son çalıştırılan planda üretim kapsamına giren adet." />
          <Metric compact label="Planlı şarj" value={hasPlan ? number(result.summary.plannedBatchCount) : "—"} detail={`${number(dashboard.plannedMachineCount)} tezgaha dağıtıldı`} description="Son planda oluşturulan yeni şarj sayısı." />
          <Metric compact label="Aktif tezgah" value={`${number(dashboard.activeMachineCount)} / ${number(seed.machines.length)}`} detail={`${number(dashboard.machinesWithWorkCount)} tezgah iş gösteriyor`} description="Soldaki sayı planlamaya açık tezgahları, sağdaki sayı tanımlı tüm tezgahları gösterir." />
        </div>
        <span className={`dashboard-plan-state ${dirty ? "stale" : hasPlan ? "ready" : "empty"}`} role="status">
          {dirty ? <Warning size={14} weight="fill" /> : hasPlan ? <CheckCircle size={14} /> : <Info size={14} />}
          {planState}
        </span>
      </PageBarSlot>

      <div className="dashboard-board">
        <GeneralOverviewProcessTabs plans={overview.operationPlans} selected={activeProcess} onSelect={(process) => { setActiveProcess(process); setQuery(""); setFilter("all"); }} />
        <div className="dashboard-toolbar">
          <div className="dashboard-toolbar-title"><strong>{activePlan?.label ?? "Operasyon"} genel planı</strong><span>{activeProcess === "turning" ? `${number(visibleMachines.length)} tezgah` : `${number(visibleResources.length)} istasyon`} · {number(activePlan?.totalJobCount ?? 0)} iş · {number(activePlan?.totalQuantity ?? 0)} adet</span></div>
          <label className="dashboard-search"><MagnifyingGlass size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="İstasyon, ürün veya şarj no ara" aria-label="İstasyon, ürün veya şarj no ara" /></label>
          <div className="dashboard-filters" role="group" aria-label="Plan filtresi">
            <FilterButton active={filter === "all"} onClick={() => setFilter("all")}>Tümü</FilterButton>
            {activeProcess === "turning" && <FilterButton active={filter === "active"} onClick={() => setFilter("active")}>Aktif</FilterButton>}
            <FilterButton active={filter === "planned"} onClick={() => setFilter("planned")}>Planı olan</FilterButton>
          </div>
          <button className="ui-btn dashboard-export" disabled={exporting} onClick={() => { setExportError(""); setExportDialogOpen(true); }} title={activeProcess === "turning" ? "Her torna tezgâhındaki sıradaki 10 işi yazdır" : `Yalnızca ${activePlan?.label ?? "seçili operasyon"} için 15 günlük yazdırılabilir saha planı hazırla`}><FileXls size={15} />{exporting ? "Hazırlanıyor…" : `${activePlan?.label ?? "Operasyon"} saha planı`}</button>
        </div>
        {exportError && <div className="dashboard-export-error" role="alert"><Warning size={14} weight="fill" /><span>{exportError}</span><button className="ui-btn" onClick={() => setExportError("")}>Kapat</button></div>}
        {activeProcess === "turning"
          ? visibleMachines.length ? <div className="machine-dashboard-grid">{visibleMachines.map((board) => <MachinePanel key={board.machine.id} board={board} diagnostic={diagnostics[board.machine.id]} onOpen={() => onNavigate({ view: "machines", machineId: board.machine.id })} />)}</div> : <DashboardNoResults label="tezgah" />
          : visibleResources.length ? <div className="machine-dashboard-grid operation-resource-grid">{visibleResources.map((resource) => <ProcessResourcePanel key={resource.id} resource={resource} process={activeProcess} />)}</div> : <DashboardNoResults label="istasyon" />}
      </div>

      <details className="dashboard-audit">
        <summary>
          <span className="dashboard-audit-title"><strong>Plan kontrolü</strong><small>Miktar, termin, veri ve tezgah kuralları</small><HelpTip align="start" text="Bu bölüm yönetici kararının yerine geçmez. Planı yayınlamadan önce incelenmesi gereken kayıtları ilgili ekrana bağlar." /></span>
          <span className="dashboard-audit-counts"><Badge tone={audit.criticalCount ? "danger" : "neutral"}>{number(audit.criticalCount)} kritik</Badge><Badge tone={audit.warningCount ? "warn" : "neutral"}>{number(audit.warningCount)} uyarı</Badge><Badge>{number(audit.infoCount)} bilgi</Badge></span>
        </summary>
        <div className="dashboard-audit-body">
          <div className="dashboard-finding-list">{audit.findings.length ? audit.findings.map((finding) => <AuditRow key={finding.id} finding={finding} onNavigate={onNavigate} />) : <div className="dashboard-audit-clear"><CheckCircle size={18} weight="fill" /> Temel kontrollerde sorun bulunmadı.</div>}</div>
        </div>
      </details>
      {exportDialogOpen && <ShopFloorExportDialog process={activeProcess} label={activePlan?.label ?? "Operasyon"} start={exportStart} end={exportEnd} omittedJobCount={buildGeneralOverviewExportPayload(seed, result, dirty, new Date().toISOString(), activeProcess, activeProcess === "turning" ? { nextJobsOnly: true } : { startDate: exportStart, endDate: exportEnd }).operationPlans[0]?.omittedJobCount ?? 0} exporting={exporting} error={exportError} onChangeStart={setExportStart} onClose={() => { if (!exporting) setExportDialogOpen(false); }} onExport={() => void exportOverview()} />}
    </section>
  );
}

export function GeneralOverviewProcessTabs({ plans, selected, onSelect }: { plans: OperationPlan[]; selected: GeneralPlanProcess; onSelect: (process: GeneralPlanProcess) => void }) {
  return <div className="dashboard-operation-tabs" role="tablist" aria-label="Genel plan operasyonu">
    {plans.map((plan) => <button key={plan.process} role="tab" aria-selected={selected === plan.process} className={selected === plan.process ? "active" : ""} onClick={() => onSelect(plan.process)}><span><ProcessIcon process={plan.process} /> {plan.label}</span><small>{number(plan.totalJobCount)} iş</small><b>{number(plan.totalQuantity)} adet</b></button>)}
  </div>;
}

function ShopFloorExportDialog({ process, label, start, end, omittedJobCount, exporting, error, onChangeStart, onClose, onExport }: { process: GeneralPlanProcess; label: string; start: string; end: string; omittedJobCount: number; exporting: boolean; error: string; onChangeStart: (value: string) => void; onClose: () => void; onExport: () => void }) {
  const dayCount = start && end ? Math.floor((Date.parse(`${end}T00:00:00Z`) - Date.parse(`${start}T00:00:00Z`)) / 86_400_000) + 1 : 0;
  const valid = process === "turning" || dayCount === 15;
  const layout = process === "turning"
    ? "Sayfa başına 8 tezgâh · tezgâh başına en fazla 10 iş · toplam 2 sayfa"
    : "Seçilen başlangıçtan itibaren 15 takvim günü · tüm işler · gerektiği kadar sayfa";
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog shop-floor-export-dialog" role="dialog" aria-modal="true" aria-label={`${label} saha planını hazırla`}><div className="operational-dialog-head"><span className="dialog-icon shift"><FileXls size={20} /></span><div><span>YAZDIRILABİLİR SAHA PLANI</span><h2>{process === "turning" ? `${label} · sıradaki 10 iş` : `${label} · 15 günlük revizyon`}</h2><p>{process === "turning" ? "Her tezgâh için tarihten bağımsız olarak sıradaki en fazla 10 işi hazırlar." : "Başlangıç günü dahil 15 takvim gününe denk gelen tüm işleri içerir. Bitiş tarihi otomatik belirlenir."}</p></div><button className="delete-button" onClick={onClose} disabled={exporting} aria-label="Saha planı penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form">{process !== "turning" && <div className="dialog-date-range"><label className="field"><span>Başlangıç</span><input type="date" value={start} onChange={(event) => onChangeStart(event.target.value)} /></label><label className="field"><span>Bitiş</span><input type="date" value={end} readOnly /></label></div>}<div className={`shop-floor-range-summary ${valid ? "valid" : "invalid"}`}><CalendarBlank size={18} /><div><strong>{process === "turning" ? "Tarih sınırı yok · sıradaki işler" : valid ? `${dayCount} günlük saha planı` : "Geçerli bir başlangıç tarihi seçin"}</strong><span>{layout}</span></div></div>{process === "turning" && omittedJobCount > 0 && <div className="calendar-impact-note maintenance"><strong>{omittedJobCount} iş yazdırma sınırının dışında</strong><span>Bu işler kaybolmaz; ekranda ve ana planda kalır. Sonraki revizyonda sıraya girer.</span></div>}{error && <p className="form-error" role="alert">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose} disabled={exporting}>Vazgeç</button><button className="primary" onClick={onExport} disabled={!valid || exporting}><FileXls size={15} /> {exporting ? "Hazırlanıyor…" : "Excel saha planını indir"}</button></div></div></section></div>;
}

function DashboardNoResults({ label }: { label: string }) {
  return <div className="dashboard-no-results"><MagnifyingGlass size={24} /><strong>Eşleşen {label} bulunamadı</strong><span>Arama metnini veya filtreyi değiştirin.</span></div>;
}

function ProcessResourcePanel({ resource, process }: { resource: OperationResource; process: GeneralPlanProcess }) {
  const quantity = resource.rows.reduce((sum, row) => sum + row.quantity, 0);
  return (
    <article className={`machine-dashboard-card operation-resource-card ${process}`}>
      <header><div><span><b>{resource.id}</b><strong>{resource.name || resource.id}</strong></span><Badge>{resource.rows.length ? "Planlı" : "Boş"}</Badge></div></header>
      {resource.rows.length ? <div className="machine-dashboard-table"><div className="machine-dashboard-row operation head"><span>Sıra</span><span>Ürün</span><span>Şarj / iş emri</span><span>Adet</span><span>Başlangıç</span><span>Bitiş</span></div>{resource.rows.map((item) => <div key={`${resource.id}-${item.position}-${item.product}-${item.workOrder}`} className={`machine-dashboard-row operation ${item.status}`}><span>{item.status === "current" ? <Badge tone="ok">Üretimde</Badge> : item.position}</span><strong>{item.product}</strong><span className={item.workOrder ? "trace-ready" : ""}>{item.workOrder || "—"}</span><span>{number(item.quantity)}</span><span>{formatPlanDate(item.startDate)}</span><span>{formatPlanDate(item.endDate)}</span></div>)}</div> : <div className="operation-resource-empty"><strong>Planlı iş yok</strong><span>Bu istasyon seçili planda boş.</span></div>}
      <footer><span>{number(resource.rows.length)} iş</span><strong>{number(quantity)} adet</strong></footer>
    </article>
  );
}

function FilterButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return <button className={active ? "active" : ""} aria-pressed={active} onClick={onClick}>{children}</button>;
}

function MachinePanel({ board, diagnostic, onOpen }: { board: MachineDashboard; diagnostic: MachineDiagnostic; onOpen: () => void }) {
  const { machine } = board;
  return (
    <article className={`machine-dashboard-card ${machine.active ? "" : "passive"}`}>
      <header>
        <button onClick={onOpen}><span><b>{machine.id}</b><strong>{machine.name}</strong></span><span className={machine.active ? "active" : "passive"}><Badge>{machine.active ? "Aktif" : "Pasif"}</Badge><ArrowRight size={13} /></span></button>
      </header>
      {board.queue.length ? <div className="machine-dashboard-table">
        <div className="machine-dashboard-row head"><span>Sıra</span><span>Ürün</span><span>Çap</span><span>Adet</span><span>Bitiş</span><span>İş emri</span></div>
        {board.queue.map((item) => <div key={item.id} className={`machine-dashboard-row ${item.kind}`}>
          <span>{item.kind === "current" ? <Badge tone="ok">Üretimde</Badge> : item.position}</span>
          <strong>{item.product}</strong>
          <span>{formatDiameter(item.diameter)}</span>
          <span>{number(item.quantity)}</span>
          <span>{formatExcelDate(item.end, { day: "2-digit", month: "2-digit" })}</span>
          <span className={item.workOrder ? "trace-ready" : ""} title={item.workOrder || "İş emri yok"}>{item.workOrder || "—"}</span>
        </div>)}
      </div> : <button className={`machine-dashboard-empty ${diagnostic.tone}`} onClick={onOpen}><span>{diagnostic.title}</span><small>{diagnostic.detail}</small><ArrowRight size={14} /></button>}
      {board.queue.length > 0 && board.plannedCount === 0 && <button className={`machine-dashboard-diagnostic ${diagnostic.tone}`} onClick={onOpen}><span><strong>{diagnostic.title}</strong><small>{diagnostic.detail}</small></span><ArrowRight size={14} /></button>}
      <footer><span>{number(board.plannedCount)} planlı şarj</span><strong>{number(board.plannedQuantity)} adet</strong></footer>
    </article>
  );
}

function AuditRow({ finding, onNavigate }: { finding: AuditFinding; onNavigate: (target: AuditTarget) => void }) {
  const Icon = finding.severity === "critical" ? WarningCircle : finding.severity === "warning" ? Warning : Info;
  return <article className={`dashboard-finding ${finding.severity}`}><Icon size={17} weight={finding.severity === "info" ? "regular" : "fill"} /><div><strong>{finding.title}</strong><p>{finding.detail}</p></div>{finding.target && <button onClick={() => onNavigate(finding.target!)}>Kaydı aç<ArrowRight size={13} /></button>}</article>;
}

function formatDiameter(value: string): string {
  if (!value || value === "0") return "—";
  return value.includes("Ø") ? value : `Ø ${value}`;
}

function number(value: number): string {
  return formatInteger(value);
}

function percent(value: number): string {
  return new Intl.NumberFormat("tr-TR", { style: "percent", minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(value);
}

function formatTimestamp(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short" }).format(date);
}

function formatPlanDate(value: string): string {
  if (!value) return "—";
  const date = new Date(`${value}T00:00:00`);
  if (Number.isNaN(date.getTime())) return value;
  return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "2-digit", year: "numeric" }).format(date);
}

frontend/components/ProcessCompletionTim.source:
"use client";

import { factoryDateTimeInput } from "@/lib/factory-time";
import { processCompletionTimeInput } from "@/lib/process-completion-time";

export function ProcessCompletionTimeField({ value, readyAt, onChange, plannedReadyAt, confirmedBuffer, onConfirmBuffer }: { value: string; readyAt: number; plannedReadyAt?: number; confirmedBuffer?: boolean; onConfirmBuffer?: (value: boolean) => void; onChange: (value: string) => void }) {
  return <div className="process-completion-time">
    <label className="field"><span>Gerçek tamamlanma tarihi ve saati</span>
      <input type="datetime-local" required step={60} min={processCompletionTimeInput(Math.ceil(readyAt * 1440 - 1e-6) / 1440)} max={factoryDateTimeInput()} value={value} onChange={(event) => onChange(event.target.value)} />
      <small>Türkiye saati. Sahada gerçekleşen zamanı girin; sonraki proses bu kayda göre hazır olur.</small>
    </label>
    {plannedReadyAt !== undefined && value && value < processCompletionTimeInput(plannedReadyAt) && <div className="calendar-impact-note">
      <p>Gerçek tamamlanma, planlanan bekleme bitişinden ({processCompletionTimeInput(plannedReadyAt).replace("T", " ")}) erken. Onay yalnız tamamlanan adet için geçerlidir; kalan miktarın beklemesi korunur.</p>
      <label><input type="checkbox" checked={Boolean(confirmedBuffer)} onChange={event => onConfirmBuffer?.(event.target.checked)} /> İlgili kontrol / yıkama tamamlandı; bu prosesi belirtilen saatte fiilen tamamladım.</label>
    </div>}
    <button type="button" className="secondary" onClick={() => onChange(factoryDateTimeInput())}>Şimdi</button>
  </div>;
}

frontend/components/ProcessIcon.tsx.source:
"use client";

import { Buildings, Cylinder, Drop, Ruler, Sparkle, type IconProps } from "@phosphor-icons/react";
import type { ComponentType } from "react";
import type { ProductionProcess } from "@/lib/planning";

function DrillBit({ size = 16, className }: IconProps) {
  return <svg width={size} height={size} className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false"><path d="M7 3h10v5H7zM9 8v10l3 3 3-3V8M9 11l6-2M9 15l6-2M9 18l6-2" /></svg>;
}

// The only process → icon mapping. Change a process icon here for every screen.
const PROCESS_ICONS: Record<ProductionProcess | "all" | "unknown", ComponentType<IconProps>> = {
  turning: Cylinder,
  drilling: DrillBit,
  deburring: Sparkle,
  washing: Drop,
  gkm: Ruler, gtm: Cylinder, "diameter-grinding": Sparkle, "form-grinding": Sparkle, measuring: Ruler, milling: Cylinder, "final-inspection": Ruler, "filter-visual": Ruler,
  all: Buildings,
  unknown: Buildings,
};

/** Decorative: always pair with a visible process name or an accessible action label.
 * Historical/imported process strings fall back to the work-center icon.
 */
export function ProcessIcon({ process, size = 16, className = "" }: { process: string; size?: number; className?: string }) {
  const key = Object.hasOwn(PROCESS_ICONS, process) ? process as keyof typeof PROCESS_ICONS : "unknown";
  const Icon = PROCESS_ICONS[key];
  return <Icon size={size} weight="bold" className={`process-icon ${className}`.trim()} aria-hidden="true" focusable="false" />;
}

frontend/components/ProcessParametersEdi.source:
"use client";

import type { SaveParameterDraft } from "../features/planning/parameters/ParameterDeactivationDialog";
import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { useMemo, useState } from "react";
import { CaretDown, CaretUp, CheckCircle, MagnifyingGlass, PencilSimple, Plus, Warning, X } from "@phosphor-icons/react";
import { Badge, Drawer, HelpTip, StatusLine, type StatusItem } from "@/components/ui/primitives";
import type { PlanningSeed } from "@/lib/planning";
import {
  processLabel,
  processProductGroup,
  type DownstreamProcess,
  type ProcessPlanningStrategy,
  type ProcessProduct,
  type ProcessResource,
  type ProductProcessParameter,
} from "@/lib/process-master-data";
import { parameterForProcess, validateProcessMasterData } from "@/lib/process-planning";
import { formatInteger } from "@/lib/number-format";

function normalizedGroup(value: string): string {
  return value.trim().toLocaleLowerCase("tr-TR");
}

function strategyLabel(strategy: ProcessPlanningStrategy): string {
  return strategy === "campaign" ? "Aynı tip / setup kampanyası" : "En erken hazır işi al";
}

function familyLabel(family: ProcessProduct["family"]): string {
  return family === "piston" ? "Piston" : "Center Pin";
}

type ProcessParameterDraft = {
  productGroup: string;
  setupKey: string;
  waitWorkdaysBefore: string;
  resourcePriority: string[];
  inactiveResourceIds: string[];
  unitsPerShift: Record<string, string>;
};

function parameterDraft(product: ProcessProduct, parameter: ProductProcessParameter): ProcessParameterDraft {
  return {
    productGroup: processProductGroup(product),
    setupKey: parameter.setupKey,
    waitWorkdaysBefore: String(parameter.waitWorkdaysBefore),
    resourcePriority: [...parameter.resourcePriority],
    inactiveResourceIds: parameter.resourcePriority.filter((id) => parameter.inactiveResourceIds?.includes(id)),
    unitsPerShift: Object.fromEntries(Object.entries(parameter.unitsPerShift).map(([resourceId, units]) => [resourceId, String(units)])),
  };
}

function ProcessParameterRow({ product, parameter, resources, process, updateSeed, onAssignmentChange, onSaveParameterDraft, onClose }: {
  onClose: () => void;
  product: ProcessProduct;
  parameter: ProductProcessParameter;
  resources: ProcessResource[];
  process: DownstreamProcess;
  updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
  onAssignmentChange: (product: string, resourceId: string, active: boolean) => void;
  onSaveParameterDraft?: SaveParameterDraft;
}) {
  const original = parameterDraft(product, parameter);
  const [draft, setDraft] = useState<ProcessParameterDraft>(original);
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState("");
  const [confirmDiscard, setConfirmDiscard] = useState(false);
  const changed = JSON.stringify(draft) !== JSON.stringify(original);
  const wait = Math.max(0, Math.trunc(Number(draft.waitWorkdaysBefore) || 0));
  const invalid = !draft.productGroup.trim() || !draft.setupKey.trim() || !draft.resourcePriority.length || draft.resourcePriority.some((resourceId) => !(Number(draft.unitsPerShift[resourceId]) > 0));

  function change(patch: Partial<ProcessParameterDraft>) {
    setSaved(false);
    setConfirmDiscard(false);
    setDraft((current) => ({ ...current, ...patch }));
  }

  function requestClose() {
    if (changed && !saved && !saving) setConfirmDiscard(true);
    else onClose();
  }

  function moveResource(index: number, direction: -1 | 1) {
    const target = index + direction;
    if (target < 0 || target >= draft.resourcePriority.length) return;
    const resourcePriority = [...draft.resourcePriority];
    [resourcePriority[index], resourcePriority[target]] = [resourcePriority[target], resourcePriority[index]];
    change({ resourcePriority });
  }

  function addResource(resourceId: string) {
    if (draft.resourcePriority.includes(resourceId)) return;
    change({
      resourcePriority: [...draft.resourcePriority, resourceId],
      unitsPerShift: { ...draft.unitsPerShift, [resourceId]: draft.unitsPerShift[resourceId] || "1" },
    });
  }

  function removeResource(resourceId: string) {
    const unitsPerShift = { ...draft.unitsPerShift };
    delete unitsPerShift[resourceId];
    change({ resourcePriority: draft.resourcePriority.filter((id) => id !== resourceId), inactiveResourceIds: draft.inactiveResourceIds.filter((id) => id !== resourceId), unitsPerShift });
  }

  async function save() {
    if (invalid || saving) return;
    setSaving(true); setSaveError("");
    try {
      const normalizedDraft: ProcessParameterDraft = {
        ...draft,
        productGroup: draft.productGroup.trim(),
        setupKey: draft.setupKey.trim(),
        waitWorkdaysBefore: String(wait),
        unitsPerShift: Object.fromEntries(draft.resourcePriority.map((resourceId) => [resourceId, String(Math.max(1, Math.trunc(Number(draft.unitsPerShift[resourceId]) || 1)))])),
      };
      const mutator = (seedDraft: PlanningSeed) => {
        const targetProduct = seedDraft.processMasterData?.products.find((item) => item.product === product.product);
        const targetParameter = targetProduct ? parameterForProcess(targetProduct, process) : undefined;
        if (!targetProduct || !targetParameter) return;
        targetProduct.productGroup = normalizedDraft.productGroup;
        targetParameter.setupKey = normalizedDraft.setupKey;
        targetParameter.waitWorkdaysBefore = Number(normalizedDraft.waitWorkdaysBefore);
        targetParameter.resourcePriority = [...normalizedDraft.resourcePriority];
        targetParameter.inactiveResourceIds = [...normalizedDraft.inactiveResourceIds];
        targetParameter.unitsPerShift = Object.fromEntries(normalizedDraft.resourcePriority.map((resourceId) => [resourceId, Number(normalizedDraft.unitsPerShift[resourceId])]));
      };
      const targets = normalizedDraft.inactiveResourceIds.filter(id => !parameter.inactiveResourceIds?.includes(id)).map(resourceId => ({ process, product: product.product, resourceId }));
      if (product.family !== "cubuk-filtre" && onSaveParameterDraft && targets.length) {
        if (!await onSaveParameterDraft(mutator, targets)) return;
      } else updateSeed(mutator);
      setDraft(normalizedDraft);
      setSaved(true);
    } catch (cause) { setSaveError(cause instanceof Error ? cause.message : "Parametre kaydedilemedi."); }
    finally { setSaving(false); }
  }

  return <Drawer className="params-drawer" width={600} title={product.product} subtitle={`${processLabel(process)} parametreleri · ${familyLabel(product.family)}`} label={`${product.product} ${processLabel(process)} parametreleri`} onClose={requestClose} footer={<>
    {confirmDiscard && <span className="params-discard" role="alert">Kaydedilmemiş değişiklikler var.<button type="button" className="ui-btn" onClick={onClose}>Değişiklikleri at</button></span>}
    <button type="button" className="ui-btn" onClick={requestClose}>Kapat</button>
    <button type="button" className="ui-btn primary parameter-save" disabled={saving || invalid || !changed} onClick={() => void save()}>{saving ? "İnceleme bekleniyor…" : changed ? "Kaydet" : saved ? "Kaydedildi" : "Güncel"}</button>
  </>}>
    <div className={invalid && changed ? "parameter-row params-form invalid" : "parameter-row params-form"}>
      <div className="params-form-grid">
        <label className="ui-field"><span>Ürün grubu</span><input className={`cell-input wide ${!draft.productGroup.trim() ? "invalid" : ""}`} value={draft.productGroup} onChange={(event) => change({ productGroup: event.target.value })} /></label>
        <label className="ui-field"><span>{process === "drilling" ? "Matkap çapı" : "Setup grubu"}</span><input className={`cell-input wide ${!draft.setupKey.trim() ? "invalid" : ""}`} value={draft.setupKey} onChange={(event) => change({ setupKey: event.target.value })} /></label>
      </div>
      <div className="ui-field"><span>Ön bekleme</span>{product.family === "cubuk-filtre" ? <input className="cell-input compact numeric" type="number" min="0" step="1" value={draft.waitWorkdaysBefore} onChange={(event) => change({ waitWorkdaysBefore: event.target.value })} /> : <small className="params-muted">Ayarlar → Akış ve bekleme</small>}</div>
      <div className={`params-priority-field machine-priority-cell process-priority-cell ${!draft.resourcePriority.length ? "invalid" : ""}`}>
        <span className="params-field-label">İş merkezi önceliği ve adet / vardiya <HelpTip align="start" text="Sıra planlama önceliğidir: 1 ana merkezdir. Planlama durumu Pasif olan iş merkezi bu ürün için yeni planda kullanılmaz; eşleşme, öncelik ve Adet / vardiya saklanır." /></span>
        <div className="machine-priority-list">{draft.resourcePriority.map((resourceId, index) => {
          const resource = resources.find((item) => item.id === resourceId);
          return <div className={`machine-priority-item ${draft.inactiveResourceIds.includes(resourceId) ? "passive" : ""}`} key={resourceId}>
            <span className="priority-drag-handle"><b>{index + 1}</b></span>
            <div className="machine-priority-identity"><strong>{resourceId}</strong><small>{resource?.name ?? "Tanımsız iş merkezi"}</small></div>
            <small className="machine-priority-role">{index === 0 ? "Ana merkez" : `${index + 1}. tercih`}</small>
            <span className="params-priority-moves">
              <button type="button" disabled={index === 0} onClick={() => moveResource(index, -1)} aria-label={`${resourceId} önceliğini yükselt`}><CaretUp size={13} /></button>
              <button type="button" disabled={index === draft.resourcePriority.length - 1} onClick={() => moveResource(index, 1)} aria-label={`${resourceId} önceliğini düşür`}><CaretDown size={13} /></button>
              <button type="button" className="remove" onClick={() => removeResource(resourceId)} aria-label={`${resourceId} seçimini kaldır`}><X size={13} /></button>
            </span>
            <label className="parameter-assignment-status"><span>Planlama durumu</span><select aria-label={`${product.product} ${resourceId} planlama durumu`} value={draft.inactiveResourceIds.includes(resourceId) ? "passive" : "active"} onChange={(event) => { const active = event.target.value === "active"; change({ inactiveResourceIds: active ? draft.inactiveResourceIds.filter((id) => id !== resourceId) : [...draft.inactiveResourceIds, resourceId] }); onAssignmentChange(product.product, resourceId, active); }}><option value="active">Aktif</option><option value="passive">Pasif</option></select></label>
            <div className="machine-daily-rate editing"><small>Adet / vardiya</small><span><input type="number" min="1" step="1" aria-label={`${resourceId} adet / vardiya`} value={draft.unitsPerShift[resourceId] ?? ""} onChange={(event) => change({ unitsPerShift: { ...draft.unitsPerShift, [resourceId]: event.target.value } })} /></span></div>
          </div>;
        })}</div>
        <details className="machine-priority-picker"><summary className="ui-btn"><Plus size={13} /> İş merkezi seç</summary><div><p>Seçim sırası planlama önceliğidir. Kodun altında iş merkezinin tam adı gösterilir.</p><div className="machine-option-grid">{resources.map((resource) => {
          const rank = draft.resourcePriority.indexOf(resource.id);
          return <button type="button" key={resource.id} className={rank >= 0 ? "selected" : ""} disabled={rank >= 0} onClick={() => addResource(resource.id)}><span>{rank >= 0 ? rank + 1 : "+"}</span><b><strong>{resource.id}</strong><small>{resource.name}</small></b></button>;
        })}</div></div></details>
      </div>
      {saveError && <p className="params-feedback error" role="alert">{saveError}</p>}
      {(invalid && changed || saved) && <p className="parameter-feedback-row params-feedback">{invalid && changed ? <><span className="error">Eksik parametre</span>Ürün grubu, setup ve en az bir pozitif kapasite girin.</> : <><span className="success">Kaydedildi</span>{product.product} için {processLabel(process).toLocaleLowerCase("tr-TR")} parametreleri güncellendi.</>}</p>}
    </div>
  </Drawer>;
}

/** Read-only row for one product's saved process parameters; editing opens the drawer. */
function ProcessParameterSummaryRow({ product, parameter, process, onEdit }: { product: ProcessProduct; parameter: ProductProcessParameter; process: DownstreamProcess; onEdit: () => void }) {
  const draft = parameterDraft(product, parameter);
  const invalid = !draft.productGroup.trim() || !draft.setupKey.trim() || !draft.resourcePriority.length || draft.resourcePriority.some((resourceId) => !(Number(draft.unitsPerShift[resourceId]) > 0));
  const shown = draft.resourcePriority.slice(0, 4);
  return <tr className="params-row" onClick={(event) => { if (!(event.target as HTMLElement).closest("button")) onEdit(); }}>
    <td><strong>{product.product}</strong><small className="process-product-family">{familyLabel(product.family)}</small></td>
    <td>{draft.productGroup || "—"}</td>
    <td><ol className="params-priority-summary">{shown.map((resourceId, index) => { const passive = draft.inactiveResourceIds.includes(resourceId); return <li key={resourceId} className={passive ? "passive" : ""} title={`${index === 0 ? "Ana merkez" : `${index + 1}. tercih`}${passive ? " · Pasif" : ""}`}><b>{index + 1}</b>{resourceId}<span>{formatInteger(Number(draft.unitsPerShift[resourceId]) || 0)}</span></li>; })}{draft.resourcePriority.length > shown.length && <li className="more">+{draft.resourcePriority.length - shown.length}</li>}{!draft.resourcePriority.length && <li className="empty">İş merkezi seçilmedi</li>}</ol></td>
    <td>{draft.setupKey || "—"}</td>
    <td className="numeric">{product.family === "cubuk-filtre" ? formatInteger(Number(draft.waitWorkdaysBefore) || 0) : <span className="params-muted">Ayarlar</span>}</td>
    <td>{invalid ? <Badge tone="danger" title="Ürün grubu, setup ve en az bir pozitif kapasite girin.">Eksik</Badge> : draft.inactiveResourceIds.length ? <Badge title="Planlama durumu Pasif olan iş merkezi">{draft.inactiveResourceIds.length} pasif</Badge> : <span className="params-muted">Güncel</span>}</td>
    <td className="params-edit-cell"><button type="button" className="ui-icon-btn" onClick={onEdit} aria-label={`${product.product} ${processLabel(process)} parametrelerini düzenle`} title="Düzenle"><PencilSimple size={15} /></button></td>
  </tr>;
}

function DownstreamParameterTable({ seed, updateSeed, process, onSaveParameterDraft }: {
  seed: PlanningSeed;
  updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
  process: DownstreamProcess;
  onSaveParameterDraft?: SaveParameterDraft;
}) {
  const [query, setQuery] = useState("");
  const [groupFilter, setGroupFilter] = useState("");
  const [editingProduct, setEditingProduct] = useState<string | null>(null);
  const [selectedAssignment, setSelectedAssignment] = useState<{ product: string; resourceId: string; draftStatus: "Aktif" | "Pasif" } | null>(null);
  const savedParameter = seed.processMasterData?.products.find((item) => item.product === selectedAssignment?.product)?.processes.find((item) => item.process === process);
  useRaviScreenContext("process-parameters", { query, groupFilter, process, editingProduct, selectedAssignment: selectedAssignment && { ...selectedAssignment, savedStatus: savedParameter?.inactiveResourceIds?.includes(selectedAssignment.resourceId) ? "Pasif" : "Aktif" } });
  const master = seed.processMasterData!;
  const resources = master.resources.filter((resource) => resource.process === process);
  const strategy = master.planningStrategies?.[process] ?? (process === "drilling" ? "campaign" : "earliest-ready");
  const allProducts = master.products.filter((product) => parameterForProcess(product, process));
  const groups = [...new Set(allProducts.map(processProductGroup).filter(Boolean))].sort((left, right) => left.localeCompare(right, "tr"));
  const normalizedQuery = query.trim().toLocaleUpperCase("tr-TR");
  const products = allProducts.filter((product) => (!groupFilter || normalizedGroup(processProductGroup(product)) === normalizedGroup(groupFilter)) && (!normalizedQuery || `${product.product} ${processProductGroup(product)} ${familyLabel(product.family)}`.toLocaleUpperCase("tr-TR").includes(normalizedQuery)));
  const warnings = validateProcessMasterData(master);
  const title = process === "drilling" ? "Ürün, matkap çapı, iş merkezi önceliği ve üretim hızı" : "Ürün, setup, iş merkezi önceliği ve üretim hızı";

  const editedProduct = products.find((product) => product.product === editingProduct) ?? allProducts.find((product) => product.product === editingProduct);
  const editedParameter = editedProduct ? parameterForProcess(editedProduct, process) : undefined;
  const statusItems: StatusItem[] = warnings.length ? [{ id: "master-data", tone: "warn", title: `${formatInteger(warnings.length)} ana veri uyarısı`, detail: warnings[0].message }] : [];

  return <div className="params-process-body downstream-parameter-surface">
    <div className="params-toolbar">
      <div className="params-count"><strong>{products.length === allProducts.length ? formatInteger(allProducts.length) : `${formatInteger(products.length)} / ${formatInteger(allProducts.length)}`} ürün parametresi</strong><HelpTip align="start" text={`${processLabel(process)} parametreleri: ${title.toLocaleLowerCase("tr-TR")}. İş merkezi kodlarının altında tam adları gösterilir. Satırı açıp düzenleyin; değişiklikler yalnızca “Kaydet” ile uygulanır ve öncelik sırası planlama motorunda doğrudan kullanılır.`} /></div>
      <label className="params-search"><MagnifyingGlass size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ürün ara" aria-label="Ürün ara" /></label>
      <label className={`params-filter ${groupFilter ? "active" : ""}`}><span>Ürün grubu</span><select aria-label="Ürün grubuna göre filtrele" value={groupFilter} onChange={(event) => setGroupFilter(event.target.value)}><option value="">Tüm gruplar</option>{groups.map((group) => <option key={group} value={group}>{group === "piston" ? "Piston" : group === "center-pin" ? "Center Pin" : group}</option>)}</select></label>
      <label className="params-filter params-strategy"><span>Planlama yöntemi</span><select aria-label={`${processLabel(process)} planlama yöntemi`} value={strategy} onChange={(event) => updateSeed((draft) => { if (draft.processMasterData) draft.processMasterData.planningStrategies = { ...draft.processMasterData.planningStrategies, [process]: event.target.value as ProcessPlanningStrategy }; })}><option value="campaign">{strategyLabel("campaign")}</option><option value="earliest-ready">{strategyLabel("earliest-ready")}</option></select></label>
    </div>
    <StatusLine items={statusItems} label="Ana veri uyarıları" />
    <div className="table-scroll params-table-scroll"><table className="ui-table params-table downstream-parameter-table"><thead><tr><th>Ürün</th><th>Ürün grubu</th><th>İş merkezi önceliği ve adet / vardiya</th><th>{process === "drilling" ? "Matkap çapı" : "Setup grubu"}</th><th className="numeric">Ön bekleme</th><th>Durum</th><th><span className="params-sr">Düzenle</span></th></tr></thead><tbody>
      {products.map((product) => <ProcessParameterSummaryRow key={`${process}-${product.product}`} product={product} parameter={parameterForProcess(product, process)!} process={process} onEdit={() => setEditingProduct(product.product)} />)}
      {!products.length && <tr className="parameter-empty-row"><td colSpan={7}><strong>Eşleşen ürün bulunamadı</strong><span>Ürün aramasını veya ürün grubu filtresini değiştirin.</span><button className="ui-btn" onClick={() => { setQuery(""); setGroupFilter(""); }}>Filtreleri temizle</button></td></tr>}
    </tbody></table></div>
    {editedProduct && editedParameter && <ProcessParameterRow key={`${process}-${editedProduct.product}`} product={editedProduct} parameter={editedParameter} resources={resources} process={process} updateSeed={updateSeed} onSaveParameterDraft={onSaveParameterDraft} onClose={() => setEditingProduct(null)} onAssignmentChange={(productCode, resourceId, active) => setSelectedAssignment({ product: productCode, resourceId, draftStatus: active ? "Aktif" : "Pasif" })} />}
  </div>;
}

export function ProcessParametersEditor({ seed, updateSeed, process, selectedResourceId, resourcesOnly = false, onSaveParameterDraft }: {
  seed: PlanningSeed;
  updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
  process: DownstreamProcess;
  selectedResourceId?: string;
  resourcesOnly?: boolean;
  onSaveParameterDraft?: SaveParameterDraft;
}) {
  const master = seed.processMasterData;
  const resources = (master?.resources ?? []).filter((resource) => resource.process === process);
  const selectedResource = resources.find((resource) => resource.id === selectedResourceId) ?? resources[0];
  const visibleResources = selectedResourceId ? (selectedResource ? [selectedResource] : []) : resources;
  const groups = useMemo(() => [...new Set((master?.products ?? []).map(processProductGroup).filter(Boolean))].sort((left, right) => left.localeCompare(right, "tr")), [master?.products]);
  const warnings = master ? validateProcessMasterData(master) : [];

  function editResource(resourceId: string, patch: Partial<ProcessResource>) {
    updateSeed((draft) => {
      const resource = draft.processMasterData?.resources.find((item) => item.id === resourceId);
      if (resource) Object.assign(resource, patch);
    });
  }

  function setResourceGroup(resource: ProcessResource, group: string, enabled: boolean) {
    const current = resource.eligibleProductGroups ?? groups;
    const target = normalizedGroup(group);
    const next = enabled ? [...new Set([...current, group])] : current.filter((item) => normalizedGroup(item) !== target);
    editResource(resource.id, { eligibleProductGroups: next });
  }

  if (!master) return <section className="process-parameter-editor embedded missing"><Warning size={18} weight="fill" /><div><strong>Proses ana verisi bulunamadı</strong><span>{processLabel(process)} ayarları yüklenemedi.</span></div></section>;
  if (!resourcesOnly) return <DownstreamParameterTable seed={seed} updateSeed={updateSeed} onSaveParameterDraft={seed.productionArea !== "cubuk-filtre" ? onSaveParameterDraft : undefined} process={process} />;

  return <section className="process-parameter-editor embedded resources-only">
    {warnings.length > 0 && <div className="process-editor-warning"><Warning size={16} weight="fill" /><span>{formatInteger(warnings.length)} ana veri uyarısı · {warnings[0].message}</span></div>}
    <div className="process-resource-editor">
      <div className="process-editor-section-title"><div><span>{selectedResourceId ? "SEÇİLİ TEZGAH" : "İŞ MERKEZLERİ"}</span><strong><ProcessIcon process={process} /> {selectedResourceId ? (selectedResource ? `${selectedResource.id} · ${selectedResource.name}` : `${processLabel(process)} tezgahı bulunamadı`) : "Aktiflik, vardiya ve ürün grubu"}</strong></div><small>{resources.length} tanımlı · {resources.filter((resource) => resource.active && resource.defaultShifts > 0).length} planlamada</small></div>
      <div className="process-resource-cards">{visibleResources.map((resource) => {
        const usable = resource.active && resource.defaultShifts > 0;
        const eligibleGroups = resource.eligibleProductGroups ?? groups;
        return <article key={resource.id} className={usable ? "active" : "passive"}>
          <div className="process-resource-card-head"><span className={`status ${usable ? "on" : "off"}`} /><div><strong>{resource.id}</strong><small>{resource.operationName} · {resource.erpWorkCenterCode}</small></div><label className="switch-label compact"><input type="checkbox" checked={resource.active} onChange={(event) => editResource(resource.id, { active: event.target.checked })} /><span className="switch" /> Aktif</label></div>
          <label>İş merkezi adı<input defaultValue={resource.name} key={`${resource.id}-${resource.name}`} onBlur={(event) => { const name = event.target.value.trim(); if (name && name !== resource.name) editResource(resource.id, { name }); }} /></label>
          <label>Normal vardiya<select value={resource.defaultShifts} onChange={(event) => editResource(resource.id, { defaultShifts: Number(event.target.value) as 0 | 1 | 2 | 3 })}>{[0, 1, 2, 3].map((count) => <option key={count} value={count}>{count} vardiya</option>)}</select></label>
          <fieldset><legend>Uygun ürün grupları</legend><div>{groups.map((group) => <label key={group}><input type="checkbox" checked={eligibleGroups.some((item) => normalizedGroup(item) === normalizedGroup(group))} onChange={(event) => setResourceGroup(resource, group, event.target.checked)} /><span>{group === "piston" ? "Piston" : group === "center-pin" ? "Center Pin" : group}</span></label>)}</div></fieldset>
        </article>;
      })}</div>
    </div>
    <footer><CheckCircle size={15} weight="fill" /><span>Değişiklikler ortak planlama durumuna kaydedilir ve sonraki planlamada doğrudan kullanılır.</span></footer>
  </section>;
}

frontend/components/ProcessPlanningView..source:
"use client";
import { filterProductStyle, filterProductColors } from "@/lib/filter-product-colors";
import { processLeadStageLabel } from "@/lib/process-lead-time";
import { productionProcessOrder } from "@/lib/process-master-data";

import { InterruptionConsent } from "@/features/planning/machines/CurrentJobSwitchDialog";
import { activeLotInterruptions, isProductionInterruption } from "@/lib/production-interruptions";
import { chargeJourneyInterruptions, interruptionsResumedOnTurning } from "@/lib/charge-journey-status";

import { ProcessCompletionTimeField } from "./ProcessCompletionTimeField";
import { ProcessCountCorrection, ProcessRemainderChoice, requireProcessRemainderAction, type ProcessRemainderAction } from "./ProcessRemainderChoice";
import { parseProcessCompletionTime } from "@/lib/process-completion-time";
