  function zoomJourney(direction: -1 | 1) {
    const levels = [7, 14, 28, 42, 70, 112];
    const nearest = levels.reduce((best, value, index) => Math.abs(value - journeyViewDays) < Math.abs(levels[best] - journeyViewDays) ? index : best, 0);
    setJourneyViewDays(levels[Math.max(0, Math.min(levels.length - 1, nearest + direction))]);
  }

  function journeyNote(segmentId: string): ChargeJourneyNote | undefined {
    return selectedJourneyNotes.find((note) => note.segmentId === segmentId);
  }

  function openJourneyNote(kind: "wait" | "delay", operation: ProcessOperation, start: number, end: number) {
    const segmentId = `${operation.recordedProcess ?? operation.process}:${kind}`;
    const existing = journeyNote(segmentId);
    setJourneyNoteEditor({
      chargeKey: selectedChargeKey,
      segmentId,
      kind,
      process: operation.recordedProcess ?? operation.process as ProductionProcess,
      start,
      end,
      label: `${journeyOperationLabel(operation)} ${kind === "delay" ? "gecikmesi" : "beklemesi"}`,
    });
    const reason = existing ? existing.reason ?? "other" : "";
    setJourneyNoteReason(reason);
    setJourneyNoteDraft(reason === "other" ? existing?.note ?? "" : "");
  }

  return <section className="process-workspace">
    <PageBarSlot><div className="process-mode-tabs" role="tablist" aria-label="Proses çalışma alanı">
      <button role="tab" aria-selected={mode === "wip"} className={mode === "wip" ? "active" : ""} onClick={() => setMode("wip")}>Yarı mamül</button>
      <button role="tab" aria-selected={mode === "plan"} className={mode === "plan" ? "active" : ""} onClick={() => setMode("plan")}>Şarj yolculuğu</button>
    </div></PageBarSlot>

    {mode === "wip" ? <>
      <PageBarSlot><div className="process-summary-line journey-kpis" aria-label="Yarı mamül özeti">
        <Metric compact label="Açık yarı mamül" value={formatNumber(wipLots.length)} detail={`${formatNumber(wipLots.filter((lot) => lot.stage === "delivery-ready" && lot.readyAt < todaySerial).length)} teslimata hazır şarj`} description="Teslim edilmemiş ve hurdaya ayrılmamış yarı mamül şarjları." />
        <Metric compact label="Bekleyen adet" value={formatNumber(wipLots.reduce((sum, lot) => sum + lot.availableQuantity, 0))} detail="Açık yarı mamüllerin toplam adedi" description="Sıradaki operasyonu bekleyen toplam yarı mamül adedi." />
        <Metric compact label="Dikkat isteyen" value={formatNumber(wipLots.filter((lot) => lot.stage === "on-hold" || lot.stage === "unclassified").length)} tone={wipLots.some((lot) => lot.stage === "on-hold" || lot.stage === "unclassified") ? "danger" : "default"} detail="Blokeli veya konumu doğrulanmalı" description="Saha doğrulaması gereken yarı mamüller." />
      </div></PageBarSlot>
      <div className="process-parameter-toolbar wip-toolbar">
        <div><strong>Operasyonların iş kaynağı<HelpTip text="Müşteri siparişi değil, sahadaki şarj ve iş emirleri" align="start" /></strong></div>
        <label className="wip-stage-filter"><span>Mevcut operasyon</span><select value={wipStageFilter} onChange={(event) => setWipStageFilter(event.target.value as WipStage | "")}><option value="">Tüm konumlar</option>{WIP_STAGE_OPTIONS.map((stage) => <option key={stage.id} value={stage.id}>{stage.label}</option>)}</select></label>
        <label className="process-search"><MagnifyingGlass size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Şarj, iş emri veya ürün ara" /></label>
      </div>
      {wipLots.length ? <div className="wip-layout">
        <div className="wip-table-wrap">
          <table className="wip-table ui-table">
            <thead><tr><th>Şarj / iş emri</th><th>Ürün</th><th>Yarı mamül</th><th>Konum</th><th>Hazır olma</th><th>Sıradaki operasyon</th></tr></thead>
            <tbody>{visibleWipLots.map((lot) => {
              const ready = lot.readyAt < todaySerial;
              return <tr key={lot.id} className={`${selectedWip?.id === lot.id ? "selected" : ""} ${lot.rolledForwardFrom ? "carried-over" : ""}`} onClick={() => setSelectedWipId(lot.id)}>
                <td><strong>{lot.workOrder || "İş emri yok"}</strong><small>{lot.id}</small></td>
                <td><b>{lot.product}</b><small>{familyLabel(lot.family)}</small></td>
                <td>{formatNumber(lot.availableQuantity)} adet{activeLotInterruptions(seed,lot).length>0 && <small className="interrupted-label">Üretime ara verildi. · Manuel proses</small>}</td>
                <td><span className={`wip-stage ${lot.stage}`}>{wipStageLabel(lot.stage, ready, seed.productionArea)}</span></td>
                <td><strong>{formatExcelDate(lot.readyAt)}</strong>{lot.rolledForwardFrom && <small>Geçmişten devretti · önce {formatExcelDate(lot.rolledForwardFrom)}</small>}</td>
                <td>{lot.nextProcess ? <><ProcessIcon process={lot.nextProcess} size={14} /> {processLabel(lot.nextProcess)}</> : "—"}</td>
              </tr>;
            })}</tbody>
          </table>
          {!visibleWipLots.length && <div className="process-empty compact"><strong>Eşleşen yarı mamül yok</strong><p>Şarj, iş emri veya ürün aramasını değiştirin.</p></div>}
        </div>
        <aside className="wip-inspector">
          {selectedWip ? <>
            <div className="process-inspector-title"><span>YARI MAMÜL DETAYI</span><h3>{selectedWip.workOrder || selectedWip.product}</h3><p>{selectedWip.product} · {formatNumber(selectedWip.availableQuantity)} adet</p></div>
            <dl className="process-operation-detail wip-detail">
              <div><dt>Konum</dt><dd>{wipStageLabel(selectedWip.stage, selectedWip.readyAt < todaySerial, seed.productionArea)}</dd></div>
              <div><dt>Hazır olma</dt><dd>{formatExcelDate(selectedWip.readyAt)}</dd></div>
              {selectedWip.rolledForwardFrom && <div><dt>Devreden iş</dt><dd>Eski hazır tarihi {formatExcelDate(selectedWip.rolledForwardFrom)} · tamamlanmadığı için bugüne taşındı</dd></div>}
              <div><dt>Tamamlanan adım</dt><dd>{selectedWip.completedSteps.map((step) => processLabel(step.process === "washing" ? "gkm" : step.process)).join(" → ")}</dd></div>
            </dl>
            {activeLotInterruptions(seed,selectedWip).length>0 && <div className="calendar-impact-note"><strong>Üretime ara verildi.</strong><span>{activeLotInterruptions(seed,selectedWip).map(item=>item.reason).filter(Boolean).join(" · ")} Sonraki prosese eklemek için Tezgahlar → Manuel şarj seçin.</span></div>}
            {selectedWipOperation && <form className="wip-action-card" onSubmit={(event) => {
              event.preventDefault();
              try {
              setCompletionError("");
              const completedDay = parseProcessCompletionTime(completionDate, wipCompletionEarliestAt(seed, selectedWip));
              const remainderAction = requireProcessRemainderAction(selectedWip.availableQuantity, completionQuantity, completionRemainderAction, completionCountReason);
              const completed = onCompleteWipOperation({
                lotId: selectedWip.id,
                confirmedInterruption:interruptionConfirmed, confirmedBuffer,
                process: selectedWipOperation.process as DownstreamProcess,
                resourceId: selectedWipOperation.resourceId,
                resourceName: selectedWipOperation.resourceName,
                quantity: completionQuantity, countCorrectionReason: completionCountReason,
                remainderAction,
                startedAt: Math.max(wipCompletionEarliestAt(seed, selectedWip), Math.min(selectedWipOperation.start, completedDay)),
                completedAt: completedDay,
                plannedStart: selectedWipOperation.start,
                plannedEnd: selectedWipOperation.end,
              });
              if (!completed) throw new Error("İş tamamlanamadı; ekrandaki uyarıyı kontrol edin.");
              } catch (error) { setCompletionError(error instanceof Error ? error.message : "İş tamamlanamadı."); }
            }}>
              <span>SIRADAKİ OPERASYON</span>
              <strong>{processLabel(selectedWipOperation.process)} · {selectedWipOperation.resourceId}</strong>
              <small>Planlanan {formatExcelDate(selectedWipOperation.start)} – {formatExcelDate(selectedWipOperation.end)}</small>
              <label>Fiili tamamlanan adet<input type="number" min={1} step={1} value={completionQuantity} onChange={(event) => setCompletionQuantity(Number(event.target.value))} /></label>
              <ProcessCountCorrection available={selectedWip.availableQuantity} completed={completionQuantity} reason={completionCountReason} onChange={setCompletionCountReason} />
              <ProcessRemainderChoice available={selectedWip.availableQuantity} completed={completionQuantity} action={completionRemainderAction} onChange={setCompletionRemainderAction} name="wip-process-remainder" />
              <ProcessCompletionTimeField value={completionDate} readyAt={wipCompletionEarliestAt(seed, selectedWip)} plannedReadyAt={wipOperationReadyAt(selectedWip)} confirmedBuffer={confirmedBuffer} onConfirmBuffer={setConfirmedBuffer} onChange={value => { setCompletionDate(value); setConfirmedBuffer(false); }} />
              {activeLotInterruptions(seed,selectedWip).length>0 && <InterruptionConsent checked={interruptionConfirmed} onChange={setInterruptionConfirmed}/>}
              {completionError && <p className="form-error" role="alert">{completionError}</p>}
              <button type="submit" className="ui-btn primary">Operasyonu tamamla</button>
            </form>}
            {!selectedWipOperation && selectedWip.stage !== "delivery-ready" && selectedWip.stage !== "on-hold" && <div className="process-inline-notice danger"><Warning size={16} weight="fill" /><span>Bu şarj için sıradaki operasyon planlanamadı. Konumu ve proses parametrelerini doğrulayın.</span></div>}
            {selectedWip.availableQuantity > 0 && (selectedWip.stage === "delivery-ready" ? <button className="ui-btn primary" onClick={() => setManualAction({ lot: structuredClone(selectedWip), kind: "delivery" })}>Teslimatı tamamla</button> : wipBufferQuestion(selectedWip) && wipOperationReadyAt(selectedWip) > factoryNowSerial() ? <button className="ui-btn" onClick={() => setManualAction({ lot: structuredClone(selectedWip), kind: "buffer" })}>Beklemeyi tamamla</button> : null)}
            <form className="wip-correction" onSubmit={(event) => { event.preventDefault(); onCorrectWipStage(selectedWip.id, stageDraft, inputDateToSerial(stageDate)); }}>
              <span>SAHA DOĞRULAMASI</span>
              <label>Gerçek konum<select value={stageDraft} onChange={(event) => setStageDraft(event.target.value as WipStage)}>{WIP_STAGE_OPTIONS.map((stage) => <option key={stage.id} value={stage.id}>{stage.label}</option>)}</select></label>
              <label>Geçerlilik günü<input type="date" value={stageDate} onChange={(event) => setStageDate(event.target.value)} /></label>
              {selectedWip.stage === "on-hold" ? <button type="button" className="ui-btn" onClick={() => onReleaseWip(selectedWip.id, inputDateToSerial(stageDate))}>Blokeyi kaldır</button> : <button type="submit" className="ui-btn">Konumu doğrula</button>}
            </form>
            <div className="wip-audit"><span>SON HAREKETLER</span>{(seed.wipMovements ?? []).filter((movement) => movement.lotId === selectedWip.id).slice(-4).reverse().map((movement) => <p key={movement.id}><b>{wipStageLabel(movement.toStage, false, seed.productionArea)}</b><small>{formatExcelDate(movement.occurredAt)} · {formatNumber(movement.quantity)} adet</small></p>)}</div>
          </> : <div className="process-empty compact"><strong>Yarı mamül seçin</strong></div>}
        </aside>
      </div> : <div className="process-empty"><strong>Henüz açık yarı mamül yok</strong><p>Bir torna işi tamamlandığında kalite beklemesiyle birlikte burada otomatik açılır.</p></div>}
    </> : <>
      <PageBarSlot><div className="process-summary-line journey-kpis" aria-label="Şarj yolculuğu özeti">
        <Metric compact label="Rotalı şarj" value={formatNumber(journeyJobs.length)} detail={`${formatNumber(activeJobCount)} aktif · ${formatNumber(archivedJobCount)} arşivde · ${formatNumber(plan.jobs.filter((job) => job.source === "current-turning").length)} tornada çalışan · ${formatNumber(plan.operations.filter((operation) => operation.actual).length)} fiili operasyon`} description="Proses rotası hesaplanan tüm şarjlar; sevk edilenler Arşiv sekmesinde listelenir." />
        <Metric compact label="Sahadaki yarı mamül" value={formatNumber(journeyJobs.filter((job) => job.source === "wip" && journeyStatusByJobId.get(job.batchId)?.tone !== "delivered").length)} detail="Tornası bitmiş, sonraki prosesleri süren şarjlar" description="Sevk edilmemiş yarı mamül şarjları." />
        <Metric compact label="Son teslimata hazır" value={plan.deliveryCompletion ? formatExcelDate(plan.deliveryCompletion) : "—"} detail={`${packagingLabel} dahil`} description="Rotalı şarjların en geç teslimata hazır olduğu tarih." />
      </div></PageBarSlot>
      <StatusLine label="Şarj yolculuğu uyarıları" items={[
        ...(dirty ? [{ id: "dirty", tone: "warn", title: "Torna girdileri değişti.", detail: "Proses rotası, ekrandaki son planlı şarjları gösteriyor; yeni torna planından sonra otomatik güncellenir." } satisfies StatusItem] : []),
        ...(plan.warnings.length > 0 ? [{ id: "route-warnings", tone: "danger", title: `${formatNumber(plan.warnings.length)} rota uyarısı var.`, detail: `İlk uyarı: ${plan.warnings[0].message}` } satisfies StatusItem] : []),
        ...(plan.gaps.length > 0 ? [{ id: "gaps", tone: "info", title: `${formatNumber(plan.gaps.length)} açıklanan kapasite boşluğu`, action: <button type="button" className="ui-btn journey-gap-toggle" aria-expanded={gapsOpen} onClick={() => setGapsOpen((open) => !open)}>{gapsOpen ? "Nedenleri gizle" : `${formatNumber(plan.gaps.length)} plan boşluğunun nedenini göster`}</button> } satisfies StatusItem] : []),
      ]} />
      {gapsOpen && plan.gaps.length > 0 && <div className="process-gap-explanations journey-gap-list" aria-label="Plan boşluğu nedenleri"><div>{plan.gaps.map((gap) => <p key={gap.id}><strong>{gap.resourceId} · {formatExcelDate(gap.start, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}–{formatExcelDate(gap.end, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</strong><span>{gap.message}</span></p>)}</div></div>}
      {journeyJobs.length ? <div className="journey-layout">
        <aside className="journey-index">
          <label className="process-search journey-search"><MagnifyingGlass size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Şarj, iş emri veya ürün ara" /></label>
          <div className="journey-list-tabs" role="tablist" aria-label="Şarj yolculuğu kayıtları"><button className={journeyListMode === "active" ? "active" : ""} onClick={() => { setJourneyListMode("active"); setJourneyStateFilter(""); setJourneyProcessFilter(""); }}>Aktif <b>{formatNumber(activeJobCount)}</b></button><button className={journeyListMode === "archive" ? "active" : ""} onClick={() => { setJourneyListMode("archive"); setJourneyStateFilter(""); setJourneyProcessFilter(""); }}><Archive size={13} /> Arşiv <b>{formatNumber(archivedJobCount)}</b></button></div>
          <div className="journey-filters">
            <Menu label={journeyProcessFilter || journeyStateFilter ? "Filtre · açık" : "Filtre"} title="Mevcut proses ve durum filtresi" align="start" className="journey-filter-menu"><div className="journey-filter-fields">
              <label>Mevcut proses<select aria-label="Şarj yolculuğu mevcut proses" value={journeyProcessFilter} onChange={(e) => setJourneyProcessFilter(e.target.value)}><option value="">Tüm prosesler</option>{productionProcessOrder(seed).map(p => <option key={p} value={p}>{processLabel(p)}</option>)}<option value="delivery">Paketleme / Teslimat</option><option value="attention">Blokeli / Konumu belirsiz</option></select></label>
              <label>Durum<select aria-label="Şarj yolculuğu durum" value={journeyStateFilter} onChange={(e) => setJourneyStateFilter(e.target.value)}><option value="">Tüm durumlar</option><option value="waiting">Bekliyor</option><option value="running">Üretimde</option><option value="planned">Planlanan</option><option value="finishing">{packagingLabel}</option><option value="delivered">Sevk edildi</option><option value="attention">Dikkat gerekiyor</option></select></label>
            </div></Menu>
            <div className="journey-filter-count"><strong>{formatNumber(visibleTypes)} tip · {formatNumber(visibleQuantity)} adet</strong><small>{journeyListMode === "archive" ? "Filtrelenen sevk adedi" : "Filtrelenen kalan adet"}</small></div>
          </div>
          <div className="journey-job-list" ref={journeyListRef}>
            {visibleJobs.map((job) => {
              const status = journeyStatusByJobId.get(job.batchId)!;
              return <button key={job.batchId} className={selectedJob?.batchId === job.batchId ? "active" : ""} onClick={() => { setSelectedJobId(job.batchId); setSelectedOperationId(defaultJourneyOperation(job, seed)?.id ?? ""); }}>
                <span className="journey-job-main"><i className="journey-dot" aria-hidden="true" title={filterArea ? job.product : jobDiameter(job) || "Çap bilinmiyor"} style={{ background: filterArea ? filterProductColors(job.product).border : diameterDotColor(jobDiameter(job), diameterHues) ?? "var(--ui-line-strong)" }} /><strong>{job.product}</strong></span>
                <small className="journey-job-meta">{formatNumber(job.quantity)} adet · {job.workOrder || "İş emri yok"} · {job.deliveryReadyAt>0 ? `${formatExcelDate(job.deliveryReadyAt, { day: "2-digit", month: "short" })} ${status.tone === "delivered" ? "sevk" : "hazır"}` : "Teslim tarihi belirlenmedi"}</small>
                <em className={`journey-status-${status.tone}`} title={job.familyKnown===false ? "Rota doğrulanmalı" : familyLabel(job.family)}>{status.label}</em>
              </button>;
            })}
            {!visibleJobs.length && <div className="process-empty compact"><strong>Eşleşen şarj yok</strong><p>Aramayı değiştirin.</p></div>}
          </div>
        </aside>
        <section className="journey-canvas">
          {selectedJob ? <>
            <div className="journey-heading">
              <div title={journeySourceHeading(selectedJob.source, selectedJobDelivered)}><div className="journey-title-row"><h3>{selectedJob.product}</h3><Badge tone={journeyStatusTone(journeyStatusByJobId.get(selectedJob.batchId)?.tone)}>{journeyStatusByJobId.get(selectedJob.batchId)?.label}</Badge></div><p><b className={`process-family ${selectedJob.family}`}>{selectedJob.familyKnown===false ? "Rota doğrulanmalı" : familyLabel(selectedJob.family)}</b> · {formatNumber(selectedJob.quantity)} adet · İş emri {selectedJob.workOrder || "yok"}</p></div>
              <div className="journey-heading-actions">
                {selectedTurningMachine && <button className="journey-complete-action ui-btn primary" onClick={() => setTurningCompletionOpen(true)}><ProcessIcon process="turning" /> Torna prosesini bitir</button>}
                {selectedJourneyOperationCanComplete && selectedOperation && <button className="journey-complete-action ui-btn primary" onClick={openJourneyCompletion}><ProcessIcon process={selectedOperation.recordedProcess ?? selectedOperation.process} /> {processLabel(selectedOperation.process)} prosesini bitir</button>}
                {!selectedJourneyOperationCanComplete && selectedOperation && !selectedOperation.actual && selectedOperation.process !== "turning" && <small className="journey-complete-hint">{selectedJourneyCompletionHint}</small>}
                {selectedJobDelivered && <div className="journey-manual-actions">
                  <button className="ui-btn" onClick={() => onOpenArchive({ entryIds: journeyArchiveEntryIds(seed, selectedJob.batchId, selectedJob.wipLotId), action: "edit" })}>Adet / Teslimat</button>
                  <button className="ui-btn" onClick={() => onOpenArchive({ entryIds: journeyArchiveEntryIds(seed, selectedJob.batchId, selectedJob.wipLotId), action: "restore" })}>Önceki aşamaya geri al</button>
                </div>}
                {selectedJobLot && !selectedJobDelivered && selectedJobLot.availableQuantity > 0 && <div className="journey-manual-actions">{selectedJobLot.stage === "delivery-ready" ? <button className="ui-btn primary" onClick={() => setManualAction({ lot: structuredClone(selectedJobLot), kind: "delivery" })}>Teslimatı tamamla</button> : wipBufferQuestion(selectedJobLot) && wipOperationReadyAt(selectedJobLot) > factoryNowSerial() ? <button className="ui-btn" onClick={() => setManualAction({ lot: structuredClone(selectedJobLot), kind: "buffer" })}>Beklemeyi tamamla</button> : null}</div>}
                <div className="journey-ready"><span>{selectedJobDelivered ? "SEVK EDİLDİ" : selectedDeliveryKnown ? "TESLİMATA HAZIR" : selectedProductionInterrupted ? "ÜRETİME ARA VERİLDİ" : "ROTA EKSİK"}</span><strong>{selectedDeliveryKnown ? formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "long" }) : selectedRemainderQueued ? "Kalan iş kuyrukta" : "Teslim tarihi belirlenmedi"}</strong><small>{selectedJobDelivered ? "Üretim yolculuğu tamamlandı" : selectedDeliveryKnown ? `${packagingLabel} · ${packagingDuration} dahil` : selectedRouteIssue ?? "Eksik operasyon bilgisi kontrol edilmeli"}</small></div>
              </div>
            </div>
            {selectedJob.operations.filter(operation => operation.flowTargetEnd).map(operation => <p key={operation.id} className="journey-history-notice"><strong>{processLabel(operation.process)} bitiş hedefi:</strong> {formatExcelDate(operation.flowTargetEnd!, { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" })} · <strong>Planlanan bitiş:</strong> {formatExcelDate(operation.end, { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" })} · {operation.flowReason ?? "Hedef karşılanıyor; parça beslemesi kontrol edildi."}</p>)}
            {selectedJob.historyIncomplete && <p className="journey-history-notice">Bu eski kayıtta yalnızca kaydedilmiş proses tarihleri gösterilir. Eksik proses geçmişi sonradan hesaplanmaz.</p>}
            <div className="journey-readiness-strip" aria-label="Şarj proses hazırlık tarihleri">{journeyMilestones.map((milestone) => <div key={milestone.id} title={journeyRows.filter((row) => row.operation.process === milestone.id).map((row) => [row.plannedTooltip, row.actualStart > 0 ? row.actualTooltip : ""].filter(Boolean).join("\n\n")).join("\n\n") || milestone.detail} className={`journey-readiness-step ${milestone.id} ${milestone.skipped ? "skipped" : ""}`}><span>{milestone.id === "delivery" ? (filterArea ? "½" : "+1") : <ProcessIcon process={milestone.id} size={13} />}</span><div><small>{milestone.label}</small><strong>{milestone.skipped ? "Atlanır" : milestone.date <= 0 ? "Henüz planlanmadı" : formatExcelDate(milestone.date, { day: "2-digit", month: "long" })}</strong><em>{milestone.detail}</em>{!milestone.skipped && milestone.date > 0 && milestone.id !== "turning" && !selectedJob.operations.some(operation => operation.process === milestone.id && operation.actual) && <b className={milestone.wait > 0 ? "waiting" : "ready"}>{waitLabel(milestone.wait)}</b>}</div></div>)}</div>
            {chargeJourneyInterruptions(selectedJob,seed).length>0 && <section className="journey-interruptions" aria-label="Kısmi üretim ve ara verme kayıtları">{chargeJourneyInterruptions(selectedJob,seed).map(item=><div key={item.id}><strong>{item.kind === "partial-completion" ? "Kısmi üretim tamamlandı." : "Üretime ara verildi."} · {processLabel(item.process==='washing'?'gkm':item.process)} · {item.resourceId}</strong><span>{formatExcelDate(item.occurredAt)} · {formatNumber(item.producedQuantity)} adet üretildi · {formatNumber(item.remainingQuantity)} adet kalan</span><p>{item.reason || 'Üretim yapılmadan iş değiştirildi.'}</p><small>{item.completedAt?'Kalan üretim tamamlandı.':item.resumedAt?'Kalan işe yeniden başlandı.':'Kalan iş tezgah kuyruğunda korunuyor.'}</small></div>)}</section>}
            {journeyIssues.length > 0 && <div className="process-inline-notice danger journey-issue-line" role="status" title={journeyIssues.join(" ")}><Warning size={15} weight="fill" /><span>{journeyIssues.join(" ")}</span></div>}
            <div className="journey-gantt-controls" aria-label="Şarj yolculuğu tarih kontrolleri">
              <button onClick={() => setJourneyViewStart((current) => current - Math.max(1, Math.floor(horizonDays / 2)))} aria-label="Önceki tarihlere git"><CaretLeft size={14} /></button>
              <label><CalendarBlank size={14} /><input type="date" value={serialToInputDate(horizonStart)} onChange={(event) => setJourneyViewStart(inputDateToSerial(event.target.value))} aria-label="Şarj yolculuğu başlangıç tarihi" /></label>
              <button onClick={() => setJourneyViewStart((current) => current + Math.max(1, Math.floor(horizonDays / 2)))} aria-label="Sonraki tarihlere git"><CaretRight size={14} /></button>
              <button className="journey-text-control ui-btn" onClick={() => setJourneyViewStart(todaySerial)}>Bugün</button>
              <button className="journey-text-control ui-btn" onClick={fitJourneyRoute}><CornersOut size={14} /> Rotayı sığdır</button>
              <Menu label="Lejant" title="Şarj yolculuğu lejantı" className="journey-legend-menu"><div className="journey-color-legend">{filterArea ? [...new Set(seed.products.map(product => product.product))].sort().map(product => <span key={product} style={{ "--process-color": filterProductColors(product).border } as React.CSSProperties}>{product}</span>) : productionProcessOrder(seed).map(p => <span key={p} className={p}>{processLabel(p)}</span>)}<span className="waiting">Bekleme</span><span className="actual">Gerçekleşen</span></div></Menu>
              <span className="journey-zoom-control"><button disabled={horizonDays >= 112} onClick={() => zoomJourney(1)} aria-label="Şarj yolculuğunu uzaklaştır"><Minus size={13} /></button><small>{horizonDays} gün</small><button disabled={horizonDays <= 7} onClick={() => zoomJourney(-1)} aria-label="Şarj yolculuğunu yakınlaştır"><Plus size={13} /></button></span>
            </div>
            <div className="journey-gantt journey-comparison-gantt fit-view interval-view" style={{ "--journey-days": horizonDays, "--journey-interval-count": 4 } as React.CSSProperties} aria-label={`${selectedJob.workOrder || selectedJob.product} planlanan ve gerçekleşen şarj yolculuğu`}>
              <div className="journey-axis"><span>PROSES / KAYNAK</span><div className="journey-interval-scale" aria-label={`${formatExcelDate(horizonStart)} ile ${formatExcelDate(horizonEnd)} arasındaki zaman aralıkları`}>{journeyIntervalTicks.map((tick, index) => <small key={`${tick.serial}-${index}`} className={index === 0 ? "first" : index === journeyIntervalTicks.length - 1 ? "last" : ""} style={{ left: `${tick.position}%` }}>{formatExcelDate(tick.serial, { day: "2-digit", month: "short" })}</small>)}</div></div>
              <div className="journey-gantt-row journey-all-flow-row">
                <div className="journey-row-label journey-all-flow-label"><i>Σ</i><span><strong title="Üst sıra kalan planı, alt sıra gerçekleşenleri gösterir. Eski plan tarihleri proses satırlarında karşılaştırılır.">Tüm akış</strong><small>Tüm prosesler</small></span><span className="journey-side-lanes"><em>KALAN PLAN</em><em>GERÇEKLEŞEN</em></span></div>
                <div className="journey-track journey-all-flow-track journey-two-lane-track">
                  {journeyNow >= horizonStart && journeyNow < horizonEnd && <i title="Şimdi" className="journey-today-line" style={{ left: `${ganttPercent(journeyNow, horizonStart, horizonDays)}%` }} />}
                  {journeyRows.flatMap((row) => row.remainingRange ? [<button key={`flow-plan-${row.operation.id}`} title={journeyDateTooltip(`${journeyOperationLabel(row.operation)} · ${row.operation.resourceId} · Kalan plan`, row.remainingRange.start, row.remainingRange.end)} className={`journey-bar journey-flow-bar planned ${row.operation.process}`} style={{ ...rangePosition(row.remainingRange.start, row.remainingRange.end, horizonStart, horizonDays), ...(filterArea ? filterProductStyle(row.operation.product) : {}) }} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{journeyOperationLabel(row.operation)}</strong><small>{row.operation.resourceId}</small></button>] : [])}
                  {journeyRows.filter((row) => row.waitStart > 0).map((row) => <button key={`flow-wait-${row.operation.id}`} className="journey-wait-segment journey-flow-wait" style={rangePosition(row.waitStart, row.waitEnd, horizonStart, horizonDays)} title={journeyDateTooltip(`${journeyOperationLabel(row.operation)} öncesi bekleme`, row.waitStart, row.waitEnd)} onClick={() => openJourneyNote("wait", row.operation, row.waitStart, row.waitEnd)}><strong>{journeyOperationLabel(row.operation)} öncesi</strong></button>)}
                  {journeyRows.filter((row) => row.actualStart && row.actualEnd >= row.actualStart).map((row) => <button key={`flow-actual-${row.operation.id}`} title={row.actualTooltip} className={`journey-bar journey-flow-bar actual ${row.operation.process}`} style={{ ...rangePosition(row.actualStart, row.actualEnd, horizonStart, horizonDays), ...(filterArea ? filterProductStyle(row.operation.product) : {}) }} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{journeyOperationLabel(row.operation)}</strong><small>{row.operation.resourceId}</small></button>)}
                </div>
              </div>
              {journeyRows.map((row, index) => <div className="journey-gantt-row journey-comparison-row" key={row.operation.id}>
                <button title={[row.plannedTooltip, row.actualStart > 0 ? row.actualTooltip : ""].filter(Boolean).join("\n\n")} className={selectedOperation?.id === row.operation.id ? "active" : ""} onClick={() => setSelectedOperationId(row.operation.id)}><ProcessIcon process={row.operation.recordedProcess ?? row.operation.process} className={`journey-process-icon ${row.operation.process}`} /><span><strong>{index + 1}. {journeyOperationLabel(row.operation)}</strong><small>{row.operation.resourceId} · {row.operation.resourceName}</small></span><span className="journey-side-lanes"><em>PLANLANAN</em><em>GERÇEKLEŞEN</em></span></button>
                <div className="journey-track journey-two-lane-track">
                  {journeyNow >= horizonStart && journeyNow < horizonEnd && <i title="Şimdi" className="journey-today-line" style={{ left: `${ganttPercent(journeyNow, horizonStart, horizonDays)}%` }} />}
                  {!row.hasRecordedPlan && <span className="journey-missing-plan">Plan kaydı yok</span>}
                  {row.hasRecordedPlan && <button title={row.plannedTooltip} className={`journey-bar planned ${row.operation.process} ${selectedOperation?.id === row.operation.id ? "selected" : ""}`} style={{ ...rangePosition(row.plannedStart, row.plannedEnd, horizonStart, horizonDays), ...(filterArea ? filterProductStyle(row.operation.product) : {}) }} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{journeyOperationLabel(row.operation)}</strong><small>{formatExcelDate(row.plannedStart, { day: "2-digit", month: "short" })} – {formatExcelDate(row.plannedEnd, { day: "2-digit", month: "short" })}</small></button>}
                  {row.waitStart > 0 && <button className={`journey-wait-segment ${journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:wait`) ? "has-note" : ""}`} style={rangePosition(row.waitStart, row.waitEnd, horizonStart, horizonDays)} onClick={() => openJourneyNote("wait", row.operation, row.waitStart, row.waitEnd)} title={journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:wait`)?.note || "Bekleme nedeni ekle"}><strong>Bekleme</strong><small>{waitLabel(row.waitEnd - row.waitStart)}</small>{journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:wait`) && <NotePencil size={12} weight="fill" />}</button>}
                  {row.actualStart > 0 && <button title={row.actualTooltip} className={`journey-bar actual ${row.operation.process} ${selectedOperation?.id === row.operation.id ? "selected" : ""}`} style={{ ...rangePosition(row.actualStart, row.actualEnd, horizonStart, horizonDays), ...(filterArea ? filterProductStyle(row.operation.product) : {}) }} onClick={() => setSelectedOperationId(row.operation.id)}><strong>{journeyOperationLabel(row.operation)}</strong><small>{formatExcelDate(row.actualStart, { day: "2-digit", month: "short" })} – {row.running ? "devam ediyor" : formatExcelDate(row.actualEnd, { day: "2-digit", month: "short" })}</small></button>}
                  {row.delayStart > 0 && <button className={`journey-delay-segment ${journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:delay`) ? "has-note" : ""}`} style={rangePosition(row.delayStart, row.delayEnd, horizonStart, horizonDays)} onClick={() => openJourneyNote("delay", row.operation, row.delayStart, row.delayEnd)} title={journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:delay`)?.note || journeyDateTooltip("Gecikme · Neden eklemek için seçin", row.delayStart, row.delayEnd)}><strong>{delayLabel(row.delayEnd - row.delayStart)}</strong>{journeyNote(`${row.operation.recordedProcess ?? row.operation.process}:delay`) && <NotePencil size={12} weight="fill" />}</button>}
                </div>
              </div>)}
              <div className="journey-gantt-row journey-comparison-row buffer-row">
                <div className="journey-row-label"><i>{selectedJobDelivered ? "✓" : filterArea ? "½" : "+1"}</i><span><strong>{selectedJobDelivered ? "Paketleme & sevkiyat" : packagingLabel}</strong><small>{selectedJobDelivered ? "Arşivde saklanan son aşama" : packagingDuration}</small></span><span className="journey-side-lanes"><em>PLANLANAN</em><em>GERÇEKLEŞEN</em></span></div>
                <div className="journey-track journey-two-lane-track">{journeyNow >= horizonStart && journeyNow < horizonEnd && <i title="Şimdi" className="journey-today-line" style={{ left: `${ganttPercent(journeyNow, horizonStart, horizonDays)}%` }} />}{!selectedDeliveryKnown && <span className="journey-missing-plan">{selectedRouteIssue ?? "Teslimat tarihi hesaplanamadı; rota ve kapasiteyi kontrol edin"}</span>}{!selectedJobDelivered && selectedDeliveryKnown && <div title={journeyDateTooltip(`${packagingLabel} · Planlanan`, selectedJob.completion, selectedJob.deliveryReadyAt)} className="journey-buffer-bar planned" style={rangePosition(selectedJob.completion, selectedJob.deliveryReadyAt, horizonStart, horizonDays)}><strong>Teslimat</strong><small>{formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "short" })}</small></div>}{selectedJobDelivered && <div title={journeyDateTooltip("Paketleme ve sevkiyat · Gerçekleşen", selectedJob.completion, selectedJob.deliveryReadyAt)} className="journey-buffer-bar actual" style={rangePosition(selectedJob.completion, selectedJob.deliveryReadyAt, horizonStart, horizonDays)}><strong>Sevk edildi</strong><small>{formatExcelDate(selectedJob.deliveryReadyAt, { day: "2-digit", month: "short" })}</small></div>}</div>
              </div>
            </div>
            {selectedOperation && <div className="journey-detail-panel">
              <div><span>SEÇİLİ ADIM</span><strong><ProcessIcon process={selectedOperation.recordedProcess ?? selectedOperation.process} /> {journeyOperationLabel(selectedOperation)} · {selectedOperation.resourceId}</strong><small>{selectedOperation.resourceName}</small></div>
              <dl className="process-operation-detail">
                <div><dt>Durum</dt><dd>{journeyRows.find(row => row.operation.id === selectedOperation.id)?.status ?? "Planlandı"}</dd></div>
                <div><dt>Planlanan başlangıç</dt><dd>{plannedJourneyRange(selectedOperation) ? formatExcelDate(plannedJourneyRange(selectedOperation)!.start) : "Plan kaydı yok"}</dd></div>
                <div><dt>Planlanan bitiş</dt><dd>{plannedJourneyRange(selectedOperation) ? formatExcelDate(plannedJourneyRange(selectedOperation)!.end) : "Plan kaydı yok"}</dd></div>
                <div><dt>Başlangıç</dt><dd>{formatExcelDate(selectedOperation.start, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</dd></div>
                <div><dt>{journeyOperationRunning(selectedOperation) ? "Gerçek bitiş" : selectedOperation.actual ? "Gerçek bitiş" : "Tahmini bitiş"}</dt><dd>{journeyOperationRunning(selectedOperation) ? "Henüz tamamlanmadı" : formatExcelDate(selectedOperation.end, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</dd></div>
                <div><dt>Vardiya kapasitesi</dt><dd>{selectedOperation.actual ? "Fiili kayıt" : selectedOperation.unitsPerShift > 0 ? `${formatNumber(selectedOperation.unitsPerShift)} adet` : "Torna planından"}</dd></div>
                <div><dt>Setup</dt><dd>{formatHours(selectedOperation.setupHours)}</dd></div>
                {selectedOperation.protectedSetupHoursAfter ? <div><dt>D-02 dönüş rezervi</dt><dd>{formatHours(selectedOperation.protectedSetupHoursAfter)}</dd></div> : null}
                <div><dt>Üretim yükü</dt><dd>{formatHours(selectedOperation.runHours)}</dd></div>
                <div><dt>Ön bekleme</dt><dd>{leadDescription(selectedOperation.product, selectedOperation.process) || (selectedOperation.waitWorkdaysBefore ? `${selectedOperation.waitWorkdaysBefore} iş günü` : "Bekleme yok")}</dd></div>
                {selectedOperation.transferBatchQuantity ? <div><dt>Akış partisi</dt><dd>{formatNumber(selectedOperation.transferBatchQuantity)} adet yarı mamül</dd></div> : null}
              </dl>
            </div>}
          </> : <div className="process-empty"><strong>Bir şarj seçin</strong><p>Aramadaki bir kaydı açarak üretim yolculuğunu görün.</p></div>}
        </section>
      </div> : <div className="process-empty"><strong>Henüz rotalı şarj yok</strong><p>Torna planı çalıştırıldığında şarj yolculukları burada oluşur.</p></div>}
    </>}
    {manualAction?.kind === "delivery" && <WipDeliveryAllocationDialog seed={seed} lot={manualAction.lot} onClose={() => setManualAction(null)} onConfirm={onDeliverWip} />}
    {manualAction?.kind === "buffer" && <WipManualActionDialog lot={manualAction.lot} kind="buffer" onClose={() => setManualAction(null)} onConfirm={onCompleteBuffer} />}
    {turningCompletionOpen && selectedTurningMachine && <CompleteJobDialog key={selectedJob?.batchId} machine={selectedTurningMachine} nextBatch={nextTurningBatch} onClose={() => setTurningCompletionOpen(false)} onConfirm={(completedAt, quantity) => { onCompleteCurrentJob(selectedTurningMachine.id, completedAt, quantity); setTurningCompletionOpen(false); }} />}
    {journeyNoteEditor && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog journey-note-dialog" role="dialog" aria-modal="true" aria-label={`${journeyNoteEditor.label} açıklaması`}><button className="delete-button journey-completion-close" onClick={() => setJourneyNoteEditor(null)} aria-label="Açıklama penceresini kapat"><X size={15} /></button><NotePencil size={25} weight="fill" /><span>{journeyNoteEditor.kind === "delay" ? "GECİKME NEDENİ" : "BEKLEME NEDENİ"}</span><h2>{journeyNoteEditor.label}</h2><p><b>{selectedJob?.workOrder || selectedJob?.product}</b> · {formatExcelDate(journeyNoteEditor.start, { day: "2-digit", month: "short" })} – {formatExcelDate(journeyNoteEditor.end, { day: "2-digit", month: "short" })}</p><fieldset className="journey-reason-options"><legend>{journeyNoteEditor.kind === "delay" ? "Gecikme nedeni" : "Bekleme nedeni"}</legend>{CHARGE_JOURNEY_REASONS.map((item) => <label key={item.value} className={journeyNoteReason === item.value ? "selected" : ""}><input type="radio" name="journey-note-reason" value={item.value} checked={journeyNoteReason === item.value} onChange={() => setJourneyNoteReason(item.value)} />{item.label}</label>)}</fieldset>{journeyNoteReason === "other" && <label className="field"><span>Açıklama</span><textarea autoFocus value={journeyNoteDraft} onChange={(event) => setJourneyNoteDraft(event.target.value)} placeholder={journeyNoteEditor.kind === "delay" ? "Örn. Müşteri çizim revizyonu bekleniyor" : "Örn. Kalite onayı beklendi"} /></label>}<small className="journey-note-help">Seçilen neden şarjın arşiv kaydında da korunur. Seçimi kaldırıp kaydederseniz mevcut neden silinir.</small><div className="drawer-actions">{journeyNoteReason && <button className="secondary" onClick={() => { setJourneyNoteReason(""); setJourneyNoteDraft(""); }}>Seçimi kaldır</button>}<button className="secondary" onClick={() => setJourneyNoteEditor(null)}>Vazgeç</button><button className="primary" disabled={journeyNoteReason === "other" && !journeyNoteDraft.trim()} onClick={() => { const { label: _label, ...input } = journeyNoteEditor; onSaveJourneyNote({ ...input, reason: journeyNoteReason || undefined, note: journeyNoteReason === "other" ? journeyNoteDraft : "" }); setJourneyNoteEditor(null); }}><NotePencil size={15} /> Nedeni kaydet</button></div></section></div>}
    {journeyCompletionOpen && selectedOperation && selectedJourneyLot && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label={`${selectedOperation.workOrder || selectedOperation.product} prosesini bitir`}><button className="delete-button journey-completion-close" onClick={() => setJourneyCompletionOpen(false)} aria-label="İş bitir penceresini kapat"><X size={15} /></button><ProcessIcon process={selectedOperation.process} size={25} /><span>{processLabel(selectedOperation.process).toLocaleUpperCase("tr-TR")} TAMAMLAMA</span><h2>{selectedOperation.workOrder || selectedOperation.product}</h2><p>{selectedOperation.product} şarjının bu adımı seçtiğiniz gerçek tarih ve iş merkezinde tamamlanacak, ardından sıradaki prosese geçirilecek.</p><label className="field"><span>Fiili tamamlanan adet</span><input type="number" min={1} step={1} value={journeyCompletionQuantity || ""} onChange={(event) => setJourneyCompletionQuantity(Number(event.target.value))} /></label><label className="field"><span>Fiili iş merkezi</span><select value={journeyCompletionResourceId} onChange={(event) => setJourneyCompletionResourceId(event.target.value)}>{selectedJourneyResources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select><small>Planlanan tezgahtan farklıysa sahada kullanılan iş merkezini seçin.</small></label><ProcessCountCorrection available={selectedJourneyLot.availableQuantity} completed={journeyCompletionQuantity} reason={countCorrectionReason} onChange={setCountCorrectionReason} /><ProcessRemainderChoice available={selectedJourneyLot.availableQuantity} completed={journeyCompletionQuantity} action={journeyRemainderAction} onChange={setJourneyRemainderAction} name="journey-process-remainder" /><ProcessCompletionTimeField value={journeyCompletionDate} readyAt={selectedJourneyRealReadyAt} plannedReadyAt={wipOperationReadyAt(selectedJourneyLot)} confirmedBuffer={confirmedBuffer} onConfirmBuffer={setConfirmedBuffer} onChange={value => { setJourneyCompletionDate(value); setConfirmedBuffer(false); }} />{activeLotInterruptions(seed,selectedJourneyLot).length>0 && <InterruptionConsent checked={interruptionConfirmed} onChange={setInterruptionConfirmed}/>} {journeyCompletionError && <p className="form-error">{journeyCompletionError}</p>}<div className="drawer-actions"><button className="secondary" onClick={() => setJourneyCompletionOpen(false)}>Vazgeç</button><button className="primary" onClick={() => { try { if (!journeyCompletionDate) throw new Error("Tamamlanma tarihi zorunludur."); const actualResource = selectedJourneyResources.find((resource) => resource.id === journeyCompletionResourceId); if (!actualResource) throw new Error("Fiili iş merkezi seçilmelidir."); if (!Number.isInteger(journeyCompletionQuantity) || journeyCompletionQuantity <= 0) throw new Error("Fiili adet açık yarı mamül miktarını aşmayan pozitif tam sayı olmalıdır."); const remainderAction = requireProcessRemainderAction(selectedJourneyLot.availableQuantity, journeyCompletionQuantity, journeyRemainderAction, countCorrectionReason); const completedAt = parseProcessCompletionTime(journeyCompletionDate, selectedJourneyRealReadyAt); const startedAt = Math.max(selectedJourneyRealReadyAt, Math.min(selectedOperation.start, completedAt)); const completed = onCompleteWipOperation({ lotId: selectedJourneyLot.id, confirmedInterruption:interruptionConfirmed, confirmedBuffer, process: selectedOperation.process as DownstreamProcess, resourceId: actualResource.id, resourceName: actualResource.name, quantity: journeyCompletionQuantity, countCorrectionReason, remainderAction, startedAt, completedAt, plannedStart: selectedOperation.start, plannedEnd: selectedOperation.end }); if (completed === false) throw new Error("İş tamamlanamadı; ekrandaki uyarıyı kontrol edin."); setJourneyCompletionOpen(false); } catch (reason) { setJourneyCompletionError(reason instanceof Error ? reason.message : "Proses tamamlanamadı."); } }}><ProcessIcon process={selectedOperation.process} size={15} /> {processLabel(selectedOperation.process)} prosesini bitir</button></div></section></div>}
  </section>;
}

frontend/components/ProcessRemainderChoi.source:
"use client";

import { formatInteger as formatNumber } from "@/lib/number-format";

export type ProcessRemainderAction = "keep" | "scrap";

export function requireProcessRemainderAction(available: number, completed: number, action: ProcessRemainderAction | "", countCorrectionReason?: string): ProcessRemainderAction | undefined {
  if (!Number.isSafeInteger(completed) || completed <= 0 || completed > available && !countCorrectionReason?.trim()) throw new Error("Fiili adet açık yarı mamül miktarını aşmayan pozitif tam sayı olmalıdır.");
  if (completed < available && !action) throw new Error("Kalan miktar için Yarı mamülde bırak veya Iskartaya ayır seçin.");
  return completed < available ? action as ProcessRemainderAction : undefined;
}

export function ProcessRemainderChoice({ available, completed, action, onChange, name }: {
  available: number;
  completed: number;
  action: ProcessRemainderAction | "";
  onChange: (action: ProcessRemainderAction) => void;
  name: string;
}) {
  const remainder = available - completed;
  if (!Number.isInteger(remainder) || remainder <= 0) return null;
  return <div className="archive-remainder process-remainder">
    <span><small>Kalan miktar</small><strong>{formatNumber(remainder)} adet</strong></span>
    <div role="radiogroup" aria-label="Kalan miktar işlemi">
      <label><input type="radio" name={name} checked={action === "keep"} onChange={() => onChange("keep")} /><span><strong>Yarı mamülde bırak</strong><small>Bu proseste bekler; sonra işlenebilir</small></span></label>
      <label className="scrap-choice"><input type="radio" name={name} checked={action === "scrap"} onChange={() => onChange("scrap")} /><span><strong>Iskartaya ayır</strong><small>Üretim kaybı olarak kaydedilir</small></span></label>
    </div>
  </div>;
}

export function ProcessCountCorrection({ available, completed, reason, onChange }: { available: number; completed: number; reason: string; onChange: (value: string) => void }) {
  if (!(completed > available)) return null;
  return <label className="field"><span>Sayım düzeltmesi nedeni</span><input maxLength={500} value={reason} onChange={event => onChange(event.target.value)} /><small>{formatNumber(available)} → {formatNumber(completed)}: +{formatNumber(completed - available)} adet sayım farkı kaydedilir. Önceki proses kayıtları korunur.</small></label>;
}

