"use client";

import { useEffect, useRef, type ReactNode } from "react";

// Lightweight dropdown on top of <details>: closes on outside click, Escape and item click.
export function Menu({ label, icon, title, align = "end", className = "", children }: { label?: ReactNode; icon?: ReactNode; title: string; align?: "start" | "end"; className?: string; children: ReactNode }) {
  const ref = useRef<HTMLDetailsElement>(null);
  useEffect(() => {
    const close = (event: Event) => {
      const menu = ref.current;
      if (!menu?.open) return;
      if (event instanceof KeyboardEvent ? event.key === "Escape" : !menu.contains(event.target as Node)) menu.open = false;
    };
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", close);
    return () => { document.removeEventListener("pointerdown", close); document.removeEventListener("keydown", close); };
  }, []);
  return (
    <details ref={ref} className={`ui-menu ${className}`}>
      <summary className={label ? "ui-btn" : "ui-icon-btn"} title={title} aria-label={label ? undefined : title}>{icon}{label}</summary>
      <div className={`ui-menu-panel ${align}`} role="menu" onClick={(event) => { if ((event.target as HTMLElement).closest("[data-menu-close]") && ref.current) ref.current.open = false; }}>{children}</div>
    </details>
  );
}

export function MenuItem({ icon, children, onClick, disabled, active, hint }: { icon?: ReactNode; children: ReactNode; onClick: () => void; disabled?: boolean; active?: boolean; hint?: string }) {
  return <button type="button" role="menuitem" className={`ui-menu-item ${active ? "active" : ""}`} disabled={disabled} onClick={onClick} title={hint} data-menu-close>{icon}<span>{children}</span></button>;
}

export function MenuDivider() {
  return <span className="ui-menu-divider" role="separator" />;
}

