"use client";

import { useEffect, useState, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { CaretDown, Info, Question, Warning, WarningCircle, X } from "@phosphor-icons/react";

// Shared UI primitives (UI overhaul). Styles live in app/styles/ui.css and use --ui-* tokens.

export type Tone = "neutral" | "accent" | "ok" | "warn" | "danger";

/** Short status label. Outline by default; colour only for warn/danger/accent. */
export function Badge({ tone = "neutral", title, children }: { tone?: Tone; title?: string; children: ReactNode }) {
  return <span className={`ui-badge ${tone}`} title={title}>{children}</span>;
}

/** Icon-only help: the explanation stays available without taking space. */
export function HelpTip({ text, label = "Açıklama", align = "center" }: { text: ReactNode; label?: string; align?: "start" | "center" | "end" }) {
  return <span className={`ui-help ${align}`} tabIndex={0} aria-label={typeof text === "string" ? text : label}><Question size={11} weight="bold" aria-hidden="true" /><span role="tooltip">{text}</span></span>;
}

/** Titled white surface. Use for one coherent block; avoid nesting panels. */
export function Panel({ title, help, actions, children, className = "", id }: { title?: ReactNode; help?: ReactNode; actions?: ReactNode; children: ReactNode; className?: string; id?: string }) {
  return (
    <section className={`ui-panel ${className}`} id={id}>
      {(title || actions) && <header className="ui-panel-head">{title && <h2>{title}{help && <HelpTip text={help} align="start" />}</h2>}{actions && <div className="ui-panel-actions">{actions}</div>}</header>}
      {children}
    </section>
  );
}

export type StatusItem = { id: string; tone: Exclude<Tone, "neutral" | "accent"> | "info"; title: ReactNode; detail?: ReactNode; action?: ReactNode };

const STATUS_RANK = { danger: 0, warn: 1, info: 2, ok: 3 } as const;

/** One line instead of a stack of banners: the most severe item, the rest on demand. */
export function StatusLine({ items, label = "Uyarılar" }: { items: StatusItem[]; label?: string }) {
  const [open, setOpen] = useState(false);
  if (!items.length) return null;
  const sorted = [...items].sort((left, right) => STATUS_RANK[left.tone] - STATUS_RANK[right.tone]);
  const [first, ...rest] = sorted;
  const icon = (tone: StatusItem["tone"]) => tone === "danger" ? <WarningCircle size={15} weight="fill" /> : tone === "warn" ? <Warning size={15} weight="fill" /> : <Info size={15} weight="fill" />;
  return (
    <div className={`ui-status-line ${first.tone}`} role="status" aria-label={label}>
      <div className="ui-status-main">
        {icon(first.tone)}
        <span className="ui-status-text"><strong>{first.title}</strong>{first.detail && <small>{first.detail}</small>}</span>
        {first.action}
        {rest.length > 0 && <button type="button" className="ui-status-more" aria-expanded={open} onClick={() => setOpen((value) => !value)}>{open ? "Gizle" : `${rest.length} uyarı daha`}<CaretDown size={12} /></button>}
      </div>
      {open && <ul className="ui-status-list">{rest.map((item) => <li key={item.id} className={item.tone}>{icon(item.tone)}<span className="ui-status-text"><strong>{item.title}</strong>{item.detail && <small>{item.detail}</small>}</span>{item.action}</li>)}</ul>}
    </div>
  );
}

/** Side drawer shell with backdrop; closes on Escape and backdrop click. */
export function Drawer({ title, subtitle, onClose, children, footer, width = 460, className = "", label }: { title: ReactNode; subtitle?: ReactNode; onClose: () => void; children: ReactNode; footer?: ReactNode; width?: number; className?: string; label?: string }) {
  useEffect(() => {
    const close = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    document.addEventListener("keydown", close);
    return () => document.removeEventListener("keydown", close);
  }, [onClose]);
  return (
    <div className="ui-drawer-backdrop" role="presentation" onClick={(event) => { if (event.target === event.currentTarget) onClose(); }}>
      <aside className={`ui-drawer ${className}`} style={{ width: `min(${width}px, 100vw)` }} role="dialog" aria-modal="true" aria-label={label ?? (typeof title === "string" ? title : undefined)}>
        <header className="ui-drawer-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button type="button" className="ui-icon-btn" onClick={onClose} aria-label="Kapat"><X size={16} /></button></header>
        <div className="ui-drawer-body">{children}</div>
        {footer && <footer className="ui-drawer-foot">{footer}</footer>}
      </aside>
    </div>
  );
}

export const PAGE_BAR_SLOT_ID = "page-bar-slot";

/** Lets a screen put its summary numbers / primary actions into the shared title row. */
export function PageBarSlot({ children }: { children: ReactNode }) {
  const [target, setTarget] = useState<HTMLElement | null>(null);
  useEffect(() => { setTarget(document.getElementById(PAGE_BAR_SLOT_ID)); }, []);
  return target ? createPortal(children, target) : null;
}

