const dismissedAdviceKey = "selsa-planlama-dismissed-advice-v1";

type OperationalSnapshot = { seed: PlanningSeed; result: ScenarioResult; selectedBatchId: string; message: string; dirty: boolean };

type PlanningSyncStatus = "loading" | "saving" | "synced" | "offline" | "conflict";

type PlanningWriteMode = "planning" | "operational";

export function PlanningApplication() {
  const productionArea = useProductionArea();
  const originalSeed = useMemo(() => productionArea === "cubuk-filtre" ? createCubukFiltreSeed() : tornaSeed, [productionArea]);
  const planningStateKey = areaStorageKey(legacyPlanningStateKey, productionArea);
  const planningStateUpdatedAtKey = areaStorageKey(legacyPlanningStateUpdatedAtKey, productionArea);
  const apiFetch = useApiFetch();
  const currentUser = useCurrentUser();
  const isAdmin = currentUser.role === "admin";
  const [seed, setSeed] = useState<PlanningSeed>(() => cloneSeed(originalSeed));
  const [identityReviewOpen, setIdentityReviewOpen] = useState(false);
  const latestSeedRef = useRef(seed);
  latestSeedRef.current = seed;
  const [result, setResult] = useState<ScenarioResult>(() => runOptimizedScenario(cloneSeed(originalSeed)));
  const [selectedBatchId, setSelectedBatchId] = useState<string>("scenario-1");
  const [focusedJourneyJobId, setFocusedJourneyJobId] = useState("");
  const [selectedMachineId, setSelectedMachineId] = useState("C-01");
  const [dirty, setDirty] = useState(false);
  const strategy: ScenarioStrategy = "optimized";
  const [notice, setNotice] = useState("Setup dahil optimize plan yüklendi");
  const { view, setView, changeView, entryPoint } = usePlanningNavigation(isAdmin, setNotice);
  const {
    scenarios, scenarioSummaries, scenarioListTotal, scenarioListLoading, scenarioListError,
    fetchScenarioPage, fetchScenarioDetail, addStoredScenario, replaceScenarioLibrary,
    deleteStoredScenario, updateStoredScenario, importStoredScenarios,
  } = useScenarioLibrary(apiFetch, setNotice);
  const [planningHistory, setPlanningHistory] = useState<PlanningStateRevision[]>([]);
  const [revisions, setRevisions] = useState<OrderRevision[]>([]);
  const [focusedOrderId, setFocusedOrderId] = useState<string | null>(null);
  const [pageGuideOpen, setPageGuideOpen] = useState(false);
  const [tourOpen, setTourOpen] = useState(false);
  const [historyPast, setHistoryPast] = useState<OperationalSnapshot[]>([]);
  const [historyFuture, setHistoryFuture] = useState<OperationalSnapshot[]>([]);
  const [historyMessage, setHistoryMessage] = useState("");
  const planningStateWriteRef = useRef<Promise<void>>(Promise.resolve());
  const planningWriteGuard = useRef(new PlanningWriteGuard());
  const queueIdentityIssue = useMemo(() => turningQueueIdentityIssue(seed), [seed]);
  const remotePlanningStateUpdatedAtRef = useRef("");
  const [planningSyncStatus, setPlanningSyncStatus] = useState<PlanningSyncStatus>("loading");
  const [lastPlanningSyncAt, setLastPlanningSyncAt] = useState("");
  const [planningSyncConflict, setPlanningSyncConflictState] = useState<PlanningStateRecord | null>(null);
  /** Latest known conflicting server record, updated synchronously (async callbacks must not trust a rendered closure). */
  const latestSyncConflictRef = useRef<PlanningStateRecord | null>(null);
  const setPlanningSyncConflict = (value: PlanningStateRecord | null) => { latestSyncConflictRef.current = value; setPlanningSyncConflictState(value); };
  /** Number of recovery copies included in this session's last download; enables the explicit clear. */
  const [recoveryDownloadedCount, setRecoveryDownloadedCount] = useState<number | null>(null);
  /** The browser cannot prove a download finished; the planner must confirm the saved file. */
  const [recoveryExportConfirmed, setRecoveryExportConfirmed] = useState(false);
  /** Why the conflict dialog is open; drives accurate warnings and allowed actions. */
  const [syncRecovery, setSyncRecovery] = useState<{ reason: "save-failed" | "remote-changed" | "missing-base" | "write-conflict"; baseUpdatedAt: string; pendingMode?: "planning" | "operational"; delta: OperationalDelta } | null>(null);
  const [productionSyncInfo, setProductionSyncInfo] = useState<ProductionSyncInfo | null>(null);
  const [productionPullStatus, setProductionPullStatus] = useState<ProductionPullStatus>("idle");
  const [productionPullConfirmOpen, setProductionPullConfirmOpen] = useState(false);
  const [productionPullPreview, setProductionPullPreview] = useState<ProductionSyncPreview | null>(null);
  const [productionPullError, setProductionPullError] = useState("");
  const productionPreviewSeedRef = useRef<PlanningSeed | null>(null);
  const productionPreviewRequestRef = useRef(0);
  const [reportRangeOverride, setReportRange] = useState<DeliveryPlanRange | null>(null);
  const reportRange = reportRangeOverride ?? deliveryPlanSuggestedRange(seed, result);
  const deliveryReport = useMemo(() => buildDeliveryReport({ ...seed, planNeedsRecalculation: Boolean(seed.planNeedsRecalculation || dirty) },
    result, reportRange),
    [seed, result, dirty, reportRange.startDate, reportRange.endDate]);

  const [operationAlert, setOperationAlert] = useState<{ id: number; message: string } | null>(null);
  const [adviceOpen, setAdviceOpen] = useState(false);
  const [adviceOrderId, setAdviceOrderId] = useState<string | null>(null);
  const [adviceMachineId, setAdviceMachineId] = useState<string | null>(null);
  const [dismissedAdviceIds, setDismissedAdviceIds] = useState<string[]>([]);
  const [quickManualProduct, setQuickManualProduct] = useState<string | null>(null);
  const [scenarioSaveOpen, setScenarioSaveOpen] = useState(false);
  const [cancellationRow, setCancellationRow] = useState<CancellableRemainder | null>(null);
  const [parameterReview, setParameterReview] = useState<{
    source: PlanningSeed; sourceResult: ScenarioResult;
    mutator: (draft: PlanningSeed) => void; impacts: DeactivationImpact[];
    resolve: (saved: boolean) => void;
  } | null>(null);
  const [scenarioLoadReport, setScenarioLoadReport] = useState<ScenarioLoadReport | null>(null);
  const [activeFilterScenarioName, setActiveFilterScenarioName] = useState("");
  const activeScenario = useMemo(() => scenarioIdentity(seed), [seed]);
  const activeScenarioName = productionArea === "cubuk-filtre" ? activeFilterScenarioName : activeScenario?.name ?? "";
  const [archiveFocus, setArchiveFocus] = useState<ArchiveFocus | undefined>();
  const [archiveOpen, setArchiveOpen] = useState(false);
  const [routeRequest, setRouteRequest] = useState<RoutePlacementRequest | null>(null);
  const [planRunOpen, setPlanRunOpen] = useState(false);
  const [automaticComparisonOpen, setAutomaticComparisonOpen] = useState(false);

  const raviPlanningContext = useMemo(() => ({
    productionArea, queueIdentityIssue, source: "current-browser", dirty, syncStatus: planningSyncStatus, lastSyncedAt: lastPlanningSyncAt,
    planState: result.state, calculatedAt: result.createdAt, summary: result.summary,
    activeScenario, activeScenarioName, scope: seed.customerDemand?.activeScope ?? seed.activePlanningScope,
    activePlanRun: result.planRun ?? seed.activePlanRun,
    orderSource: seed.customerDemand ? {
      sourceFile: seed.customerDemand.sourceFile, snapshotDate: seed.customerDemand.snapshotDate,
      importedAt: seed.customerDemand.importedAt, calculationModel: seed.customerDemand.calculationModel,
    } : seed.orderImport ?? { source: seed.orderCatalogName ?? "Manuel sipariş girişi" },
    orderCount: seed.orders.length, machineCount: seed.machines.length,
    selectedBatch: view === "planning" ? result.batches.find((batch) => batch.id === selectedBatchId) : undefined,
    openPanels: { routePlacement: Boolean(routeRequest), archive: archiveOpen, advice: adviceOpen, planRun: planRunOpen, scenarioSave: scenarioSaveOpen,
      automaticComparison: automaticComparisonOpen, syncConflict: Boolean(planningSyncConflict) },
    // Browser-side recovery state: reason and bounded counts, never the seed itself.
    syncRecovery: syncRecovery && { reason: syncRecovery.reason, baseUpdatedAt: syncRecovery.baseUpdatedAt, pendingMode: syncRecovery.pendingMode,
      localOperationsMissingOnServer: planningSyncConflict ? describeOperationalDelta(operationalDelta(seed, planningSyncConflict.seed)) : [],
      recoveryCopies: readPlanningRecoveryCopies(productionArea).length, recoveryCopyLimit: MAX_PLANNING_RECOVERY_COPIES },
  }), [seed, result, view, dirty, queueIdentityIssue, planningSyncStatus, lastPlanningSyncAt, activeScenario, activeScenarioName, selectedBatchId,
    routeRequest, archiveOpen, adviceOpen, planRunOpen, scenarioSaveOpen, automaticComparisonOpen, planningSyncConflict, syncRecovery]);

  function navigateFromRavi(id: string) {
    const target = raviTarget(id, isAdmin, productionArea);
    if (!target) return;
    if (target.panel === "archive") setArchiveOpen(true);
    if (target.panel === "advice") openAdvice();
    if (target.view) { setPageGuideOpen(false); changeView(target.view); }
    if (target.focusId) {
      window.requestAnimationFrame(() => {
        const element = document.getElementById(target.focusId!);
        if (element?.getAttribute("role") === "tab") element.click();
        window.requestAnimationFrame(() => {
          element?.scrollIntoView({ block: "center", behavior: "instant" });
          element?.focus({ preventScroll: true });
          element?.classList.add("ravi-highlight");
          window.setTimeout(() => element?.classList.remove("ravi-highlight"), 3500);
        });
      });
    }
  }

  const {
    saveMachineAvailability, replanDownstreamProcess, replaceTurningJob, saveCurrentJob, completeCurrentJob, changeProductionHistoryStatus, restoreProductionDelivery, editProductionHistoryEntry, allocateProductionHistory, finishWipOperation, deliverJourneyWip, releaseJourneyBuffer, beginDownstreamCurrentJob, replaceDownstreamCurrentJob, saveDownstreamCurrentJob, finishDownstreamCurrentJob, changeWipStage, releaseHeldWip, saveJourneyNote
  } = createProductionActions({ seed, result, commitOperationalChange, setOperationAlert, setDirty, dirty });

  const planningAdvice = useMemo(() => buildPlanningAdvice(seed, result, { dirty }), [dirty, result, seed]);
  const assignmentConflicts = useMemo(() => productionArea === "cubuk-filtre" ? [] : inactiveAssignmentConflicts(seed, result), [seed, result, productionArea]);
  const staleChargeAdvice = useMemo(() => productionArea === "cubuk-filtre" ? [] : buildStaleChargeAdvice(seed), [seed, productionArea, adviceOpen]);
  const cancellationReviews = useMemo(() => productionArea === "cubuk-filtre" ? [] : pendingCancellationReviews(seed), [seed, productionArea]);
  const visiblePlanningAdvice = planningAdvice.filter((item) => item.kind === "interrupted" || !dismissedAdviceIds.includes(item.id));
  const automaticComparisonAvailable = !dirty && hasManualPlanChanges(seed.lastAutomaticPlan, result);

  useEffect(() => {
    if (!window.localStorage.getItem("selsa-planlama-tour-seen")) setTourOpen(true);
    try {
      const stored = JSON.parse(window.localStorage.getItem(dismissedAdviceKey) ?? "[]");
      if (Array.isArray(stored)) setDismissedAdviceIds(stored.filter((item): item is string => typeof item === "string"));
    } catch {
      setDismissedAdviceIds([]);
    }
  }, []);

  useEffect(() => {
    void fetchScenarioPage(0, true);
    const localState = readLocalPlanningState(productionArea);
    const localSeed = localState?.seed ?? null;
    if (localSeed) {
      assertProductionArea(localSeed, productionArea);
      const local = cloneSeed(localSeed);
      const restored = restoreManualResult(local);
      setSeed(local);
      setResult(restored ?? createEmptyResult(local));
      setSelectedBatchId(restored?.batches.find((batch) => batch.status === "planned")?.id ?? "");
      setDirty(!restored || planRequiresRecalculation(local));
      setNotice(restored ? "Kaydedilmiş manuel plan geri yüklendi" : "Yerel parametreler yüklendi · planı yeniden çalıştırın");
    }
    Promise.all([
      apiFetch("/orders").then((response) => response.json()),
      apiFetch("/revisions").then((response) => response.json()),
      apiFetch("/planning-state").then((response) => response.ok ? response.json() : null),
      apiFetch("/planning-state/history").then((response) => response.ok ? response.json() : []),
      apiFetch("/production-sync/status").then((response) => response.ok ? response.json() : null).catch(() => null),
    ]).then(([details, storedRevisions, storedState, storedPlanningHistory, storedProductionSyncInfo]) => {
      const detailMap = new Map((details as Array<Partial<Order> & { id: string }>).map((detail) => [detail.id, detail]));
      const remoteState = isPlanningSeed(storedState?.seed)
        ? { seed: storedState.seed, updatedAt: String(storedState.updatedAt ?? "") }
        : null;
      if (remoteState) assertProductionArea(remoteState.seed, productionArea);
      remotePlanningStateUpdatedAtRef.current = remoteState?.updatedAt ?? "";
      setLastPlanningSyncAt(remoteState?.updatedAt ?? "");
      // Recovery rules (lib/planning-recovery.ts): never merge a local copy into
      // newer server operations and never overwrite them automatically.
      const localMeta = readLocalDraftMeta(productionArea);
      let decision = classifyStartup(localState ? { ...localState, meta: localMeta } : null, remoteState, cloneSeed);
      if (decision.kind === "use-remote" && decision.keepRecovery && localState && remoteState && !keepRecoveryCopy(localState.seed, remoteState, decision.reason)) {
        decision = { kind: "review", reason: "remote-changed", delta: decision.delta };
      }
      const showLocal = decision.kind === "local-unsaved" || decision.kind === "review" || decision.kind === "use-local";
      const persistedSeed = showLocal ? localState!.seed : remoteState?.seed ?? null;
      const base = cloneSeed(persistedSeed ?? originalSeed);
      if (!base.customerDemand) {
        base.orders = base.orders.map((order) => ({ ...order, ...(detailMap.get(order.id) ?? {}) }));
      }
      setSeed(base);
      const restored = restoreManualResult(base);
      const loadedResult = restored ?? (persistedSeed ? createEmptyResult(base) : runOptimizedScenario(base));
      setResult(loadedResult);
      setSelectedBatchId(loadedResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
      setDirty(Boolean(persistedSeed && (!restored || planRequiresRecalculation(base))));
      if (decision.kind === "use-remote" && remoteState) storeConfirmedLocalCopy(base, remoteState.updatedAt);
      if ((decision.kind === "local-unsaved" || decision.kind === "review") && remoteState) {
        // Writes stay blocked until the planner chooses in the dialog.
        planningWriteGuard.current.blocked = true;
        setPlanningSyncConflict(remoteState);
        setSyncRecovery({ reason: decision.reason, baseUpdatedAt: localMeta?.baseUpdatedAt ?? "", pendingMode: localMeta?.pendingMode, delta: decision.delta });
      }
      setPlanningSyncStatus(decision.kind === "use-remote" ? "synced" : decision.kind === "use-local" ? "offline" : "conflict");
      setPlanningHistory(storedPlanningHistory as PlanningStateRevision[]);
      setRevisions(storedRevisions as OrderRevision[]);
      setProductionSyncInfo(parseProductionSyncInfo(storedProductionSyncInfo));
      setNotice(decision.kind === "local-unsaved" ? "Kaydedilmemiş yerel değişiklik bulundu · kaydetmeden önce inceleyin"
        : decision.kind === "review" ? "Yerel kopya ortak veriyle uyuşmuyor · hangi sürümle devam edeceğinizi seçin"
        : decision.kind === "use-remote" && decision.keepRecovery ? "Ortak plan yüklendi · önceki yerel kopya kurtarma için saklandı"
        : persistedSeed ? (restored ? "Kaydedilmiş manuel plan geri yüklendi" : "Kaydedilmiş parametreler yüklendi · planı yeniden çalıştırın") : "Backend veritabanı hazır");
    }).catch(() => {
      setPlanningSyncStatus("offline");
      setNotice("Veritabanı açılamadı; uygulama bellekte çalışıyor");
    });
  }, [apiFetch]);

  useEffect(() => {
    function handleHistoryShortcut(event: KeyboardEvent) {
      if (!(event.ctrlKey || event.metaKey)) return;
      const target = event.target;
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement || (target instanceof HTMLElement && target.isContentEditable)) return;
      const key = event.key.toLowerCase();
      if (key === "z" && event.shiftKey) {
        if (!historyFuture.length) return;
        event.preventDefault();
        redoLastOperation();
      } else if (key === "z") {
        if (!historyPast.length) return;
        event.preventDefault();
        undoLastOperation();
      } else if (key === "y") {
        if (!historyFuture.length) return;
        event.preventDefault();
        redoLastOperation();
      }
    }
    window.addEventListener("keydown", handleHistoryShortcut);
    return () => window.removeEventListener("keydown", handleHistoryShortcut);
  }, [historyFuture, historyPast, result, seed, selectedBatchId, dirty]);

  useEffect(() => {
    if (!operationAlert) return;
    const timeout = window.setTimeout(() => setOperationAlert(null), 7_000);
    return () => window.clearTimeout(timeout);
  }, [operationAlert]);

  const selectedBatch = result.batches.find((batch) => batch.id === selectedBatchId)
    ?? result.batches.find((batch) => batch.status === "planned")
    ?? null;

  /** Store a copy that the server has confirmed (or just returned) as this device's base. */
  function storeConfirmedLocalCopy(next: PlanningSeed, updatedAt: string) {
    window.localStorage.setItem(planningStateKey, JSON.stringify(next));
    window.localStorage.setItem(planningStateUpdatedAtKey, updatedAt);
    writeLocalDraftMeta(productionArea, { version: 1, baseUpdatedAt: updatedAt, pending: false, changedAt: new Date().toISOString() });
  }

  /** Keep the current local copy before a server copy replaces it. False = do not replace. */
  function keepRecoveryCopy(local: PlanningSeed, remote: PlanningStateRecord, reason: string): boolean {
    if (sameSeedContent(local, remote.seed)) return true;
    const meta = readLocalDraftMeta(productionArea);
    return writePlanningRecoveryCopy(productionArea, { version: 1, savedAt: new Date().toISOString(), reason,
      localUpdatedAt: window.localStorage.getItem(planningStateUpdatedAtKey) ?? "", baseUpdatedAt: meta?.baseUpdatedAt ?? "", remoteUpdatedAt: remote.updatedAt, seed: local });
  }

  /** Download every retained recovery copy and the current local copy as one JSON file. */
  function downloadLocalCopy() {
    const copies = readPlanningRecoveryCopies(productionArea);
    const payload = { version: 2, exportedAt: new Date().toISOString(), productionArea,
      current: { localUpdatedAt: window.localStorage.getItem(planningStateUpdatedAtKey) ?? "", baseUpdatedAt: readLocalDraftMeta(productionArea)?.baseUpdatedAt ?? "", remoteUpdatedAt: planningSyncConflict?.updatedAt ?? "", seed },
      recoveryCopies: copies };
    const url = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = `selsa-yerel-plan-kopyalari-${new Date().toISOString().slice(0, 19).replace(/:/g, "-")}.json`;
    link.click();
    URL.revokeObjectURL(url);
    setRecoveryDownloadedCount(copies.length);
    setRecoveryExportConfirmed(false);
  }

  /** Explicit clear after download; refuses if copies changed since the download. */
  function clearDownloadedRecoveryCopies() {
    if (recoveryDownloadedCount === null || !recoveryExportConfirmed) return;
    if (!clearPlanningRecoveryCopies(productionArea, recoveryDownloadedCount)) {
      setOperationAlert({ id: Date.now(), message: "Kurtarma kopyaları indirmeden sonra değişti veya silinemedi. Yerel kopyayı indir ile yeniden indirin." });
      return;
    }
    setRecoveryDownloadedCount(null);
    setRecoveryExportConfirmed(false);
    setNotice("İndirilen kurtarma kopyaları bu cihazdan silindi");
  }

  async function writePlanningStateToServer(next: PlanningSeed, options: { force?: boolean; expectedUpdatedAt?: string; mode?: PlanningWriteMode } = {}): Promise<PlanningStateRecord> {
    planningWriteGuard.current.assertCurrent(undefined, options.force);
    // The server validates against the current persisted snapshot, including
    // unchanged pre-existing conflicts. A global strict check would lock unrelated work.
    const expectedUpdatedAt = options.expectedUpdatedAt ?? remotePlanningStateUpdatedAtRef.current;
    const response = await apiFetch("/planning-state", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ seed: next, expectedUpdatedAt, force: options.force ?? false, mode: options.mode ?? "planning", routePlacementVersion: 1, productionSplitVersion: 1, processWaitSettingsVersion: 1, flowSettingsVersion: 1, stockPlanningVersion: 1, monthlyPlanningVersion: 1 }),
    });
    if (response.status === 409) {
      const body = await response.json().catch(() => ({})) as { detail?: { current?: PlanningStateRecord } };
      const current = body.detail?.current;
      if (current && isPlanningSeed(current.seed)) {
        setPlanningSyncConflict(current);
        setSyncRecovery({ reason: "write-conflict", baseUpdatedAt: expectedUpdatedAt, pendingMode: readLocalDraftMeta(productionArea)?.pendingMode, delta: operationalDelta(next, current.seed) });
      }
      planningWriteGuard.current.blocked = true;
      setPlanningSyncStatus("conflict");
      throw new Error("Ortak planlama verisi başka bir oturumda değişti.");
    }
    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      throw new Error(typeof body.detail === "string" ? body.detail : "Planlama durumu ortak veritabanına kaydedilemedi.");
    }
    const saved = await response.json() as PlanningStateRecord & { historyEntry?: PlanningStateRevision };
    const hasNewerLocal = latestSeedRef.current !== next;
    const mergedByServer = JSON.stringify(saved.seed) !== JSON.stringify(next);
    if (mergedByServer) {
      planningWriteGuard.current.retire(hasNewerLocal);
      if (latestSeedRef.current === next) {
        const accepted = cloneSeed(saved.seed);
        const restored = restoreManualResult(accepted);
        latestSeedRef.current = accepted;
        setSeed(accepted);
        setHistoryPast([]);
        setHistoryFuture([]);
        setResult(restored ?? createEmptyResult(accepted));
        setDirty(planRequiresRecalculation(accepted));
        storeConfirmedLocalCopy(accepted, saved.updatedAt);
        setNotice("Canlı üretimle uzlaştırılmış ortak plan yüklendi · planı kontrol edin");
      } else {
        // Newer local edits were prepared against operations the server just
        // reconciled. Keep them pending against the old base so reload reviews them.
        planningWriteGuard.current.blocked = true;
        setPlanningSyncConflict(saved);
        setSyncRecovery({ reason: "write-conflict", baseUpdatedAt: remotePlanningStateUpdatedAtRef.current, pendingMode: readLocalDraftMeta(productionArea)?.pendingMode, delta: operationalDelta(latestSeedRef.current, saved.seed) });
      }
    } else if (!hasNewerLocal) {
      storeConfirmedLocalCopy(next, saved.updatedAt);
    } else {
      const meta = readLocalDraftMeta(productionArea);
      writeLocalDraftMeta(productionArea, { version: 1, baseUpdatedAt: saved.updatedAt, pending: true, pendingMode: meta?.pendingMode, changedAt: meta?.changedAt ?? new Date().toISOString() });
    }
    if (saved.seed.planNeedsRecalculation && latestSeedRef.current === next) setDirty(true);
    remotePlanningStateUpdatedAtRef.current = saved.updatedAt;
    setLastPlanningSyncAt(saved.updatedAt);
    if (!hasNewerLocal) planningWriteGuard.current.blocked = false;
    setPlanningSyncStatus(mergedByServer && hasNewerLocal ? "conflict" : "synced");
    if (saved.historyEntry) setPlanningHistory((current) => [saved.historyEntry!, ...current.filter((entry) => entry.id !== saved.historyEntry!.id)].slice(0, 20));
    return saved;
  }

  function persistPlanningState(next: PlanningSeed, options: { mode?: PlanningWriteMode } = {}) {
    const epoch = planningWriteGuard.current.capture();
    const updatedAt = new Date().toISOString();
    const previous = readLocalDraftMeta(productionArea);
    // A pending operational change stays operational until the server confirms
    // it; a later planning-mode save would otherwise keep the server's records.
    const mode: PlanningWriteMode = previous?.pending && previous.pendingMode === "operational" ? "operational" : options.mode ?? "planning";
    // The pending marker is written first. Without it a reload or a later
    // planning-mode save could drop this change, so refuse before any write or request.
    if (!writeLocalDraftMeta(productionArea, { version: 1, baseUpdatedAt: previous?.pending ? previous.baseUpdatedAt : remotePlanningStateUpdatedAtRef.current || previous?.baseUpdatedAt || "", pending: true, pendingMode: mode === "operational" ? "operational" : "planning", changedAt: updatedAt })) {
      setPlanningSyncStatus("offline");
      const message = "Tarayıcı depolaması bu değişikliği saklayamadı. Değişiklik uygulanmadı ve ortak veritabanına gönderilmedi; tarayıcı depolama alanını boşaltıp işlemi yeniden yapın.";
      setOperationAlert({ id: Date.now(), message });
      throw new Error(message);
    }
    window.localStorage.setItem(planningStateKey, JSON.stringify(next));
    window.localStorage.setItem(planningStateUpdatedAtKey, updatedAt);
    setPlanningSyncStatus("saving");
    planningStateWriteRef.current = planningStateWriteRef.current
      .then(async () => {
        planningWriteGuard.current.assertCurrent(epoch);
        await writePlanningStateToServer(next, { mode });
      })
      .catch((error) => {
        setPlanningSyncStatus((current) => current === "conflict" ? current : "offline");
        setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Plan kaydedilemedi." });
      });
  }

  async function resolveIdentity(request: TurningIdentityRepairInput, expected: PlanningSeed) {
    await planningStateWriteRef.current;
    planningWriteGuard.current.assertCurrent();
    if (expected !== latestSeedRef.current || planningSyncStatus !== "synced") throw new Error("Kayıtlar değişti veya henüz kaydedilmedi. Güncel kayıtlarla incelemeyi tekrarlayın.");
    const response = await apiFetch("/planning-state/identity-resolution", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...request, expectedUpdatedAt: remotePlanningStateUpdatedAtRef.current }),
    });
    const body = await response.json().catch(() => ({}));
    if (response.status === 409) {
      if (body.detail?.current && isPlanningSeed(body.detail.current.seed)) setPlanningSyncConflict(body.detail.current);
      planningWriteGuard.current.blocked = true;
      setPlanningSyncStatus("conflict");
      throw new Error("Ortak kayıt değişti. Güncel kayıtları yükleyip incelemeyi tekrarlayın.");
    }
    if (!response.ok) throw new Error(typeof body.detail === "string" ? body.detail : "Düzeltme kaydedilemedi.");
    const saved = body as PlanningStateRecord & { historyEntry?: PlanningStateRevision };
    if (expected !== latestSeedRef.current) {
      planningWriteGuard.current.retire(true);
      setPlanningSyncConflict(saved); setPlanningSyncStatus("conflict");
      throw new Error("Düzeltme kaydedildi; bu sırada yerel plan değişti. Güncel ortak kaydı yükleyin.");
    }
    planningWriteGuard.current.retire(false);
    const accepted = cloneSeed(saved.seed);
    latestSeedRef.current = accepted;
    remotePlanningStateUpdatedAtRef.current = saved.updatedAt;
    setSeed(accepted); setResult(restoreManualResult(accepted) ?? createEmptyResult(accepted));
    setHistoryPast([]); setHistoryFuture([]); setDirty(planRequiresRecalculation(accepted));
    setLastPlanningSyncAt(saved.updatedAt); setPlanningSyncStatus("synced");
    storeConfirmedLocalCopy(accepted, saved.updatedAt);
    if (saved.historyEntry) setPlanningHistory(current => [saved.historyEntry!, ...current.filter(entry => entry.id !== saved.historyEntry!.id)].slice(0, 20));
    setNotice("Şarj düzeltmesi kaydedildi · üretim ve arşiv kayıtları korundu");
  }

  async function previewProductionState() {
    const requestId = ++productionPreviewRequestRef.current;
    setProductionPullStatus("pulling"); setProductionPullError(""); setProductionPullPreview(null);
    try {
      await planningStateWriteRef.current;
      planningWriteGuard.current.assertCurrent();
      if (readLocalDraftMeta(productionArea)?.pending || latestSyncConflictRef.current || !remotePlanningStateUpdatedAtRef.current) throw new Error("Yerel değişiklikleri önce ortak veriye kaydedin veya çakışmayı çözün.");
      const expectedSeed = latestSeedRef.current;
      const response = await apiFetch("/production-sync/pull", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "preview" }) });
      const payload = await response.json().catch(() => ({}));
      if (requestId !== productionPreviewRequestRef.current) return;
      if (!response.ok) throw new Error(typeof payload.detail === "string" ? payload.detail : "Üretim önizlemesi alınamadı.");
      if (!isProductionSyncPreview(payload)) throw new Error("Üretim önizlemesi eksik; hiçbir seçim uygulanmadı.");
      if (latestSeedRef.current !== expectedSeed || readLocalDraftMeta(productionArea)?.pending || payload.localUpdatedAt !== remotePlanningStateUpdatedAtRef.current) throw new Error("Yerel veya ortak kayıt değişti. Önizlemeyi yenileyin.");
      productionPreviewSeedRef.current = expectedSeed;
      setProductionPullPreview(payload); setProductionPullStatus("idle");
    } catch (reason) {
      if (requestId !== productionPreviewRequestRef.current) return;
      setProductionPullStatus("error"); setProductionPullError(reason instanceof Error ? reason.message : "Önizleme alınamadı.");
    }
  }

  async function pullProductionState(request: ReturnType<typeof buildProductionSyncApply>) {
    setProductionPullStatus("pulling"); setProductionPullError("");
    let requestStarted = false;
    // Reserve the write queue. Writes prepared during this request are retired
    // when the server responds; they cannot overwrite the reviewed replacement.
    const operation = planningStateWriteRef.current.then(async () => {
      planningWriteGuard.current.assertCurrent();
      const expectedSeed = productionPreviewSeedRef.current;
      if (!expectedSeed || latestSeedRef.current !== expectedSeed || readLocalDraftMeta(productionArea)?.pending || request.expected.localUpdatedAt !== remotePlanningStateUpdatedAtRef.current) throw new Error("Yerel kayıt değişti. Önizlemeyi yenileyin.");
      // A lost response cannot prove that the server did not commit. Block old
      // and new ordinary saves before sending the request, until state is known.
      planningWriteGuard.current.retire(true);
      requestStarted = true;
      const response = await apiFetch("/production-sync/pull", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(request) });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(typeof payload.detail === "string" ? payload.detail : payload.detail?.message ?? "Üretim verileri staging’e alınamadı.");
      const saved = payload.planningState;
      if (!saved || !isPlanningSeed(saved.seed) || typeof saved.updatedAt !== "string") throw new Error("İşlem yanıtı eksik. Ortak veriyi yükleyip sonucu kontrol edin.");
      const productionScenarios = importedScenarios(payload.scenarios);
      const hasNewerLocal = latestSeedRef.current !== expectedSeed;
      planningWriteGuard.current.retire(hasNewerLocal);
      if (hasNewerLocal) {
        setPlanningSyncConflict(saved); setPlanningSyncStatus("conflict");
        throw new Error("Seçimler staging’e kaydedildi. Bu sırada yerel plan değişti; yerel kopyayı koruyarak ortak veriyi yükleyin.");
      }
      const next = cloneSeed(saved.seed);
      const restored = restoreManualResult(next);
      latestSeedRef.current = next; setSeed(next); setResult(restored ?? createEmptyResult(next));
      setSelectedBatchId(restored?.batches.find(batch => batch.status === "planned")?.id ?? "");
      setDirty(!restored || planRequiresRecalculation(next)); setHistoryPast([]); setHistoryFuture([]);
      remotePlanningStateUpdatedAtRef.current = saved.updatedAt;
      setLastPlanningSyncAt(saved.updatedAt); setPlanningSyncStatus("synced");
      storeConfirmedLocalCopy(next, saved.updatedAt); replaceScenarioLibrary(productionScenarios);
      if (payload.historyEntry && typeof payload.historyEntry.id === "string" && isPlanningSeed(payload.historyEntry.seed)) setPlanningHistory(current => [payload.historyEntry, ...current.filter(entry => entry.id !== payload.historyEntry.id)].slice(0, 20));
      if (typeof payload.sourceUpdatedAt === "string" && typeof payload.importedAt === "string") setProductionSyncInfo(current => current ? { ...current, lastSync: { sourceUpdatedAt: payload.sourceUpdatedAt, importedAt: payload.importedAt, sourceUrl: typeof payload.sourceUrl === "string" ? payload.sourceUrl : "production" } } : current);
      setProductionPullConfirmOpen(false); setProductionPullPreview(null);
      setNotice(`İncelenen seçimler staging’e kaydedildi · kurtarma kopyası ${payload.backupId ?? "sunucuda"} · ${productionScenarios.length} kayıtlı senaryo`);
    });
    planningStateWriteRef.current = operation.catch(() => {});
    try { await operation; setProductionPullStatus("idle"); }
    catch (reason) {
      setProductionPullStatus("error"); setProductionPullPreview(null);
      setProductionPullError(reason instanceof Error ? reason.message : "İşlem tamamlanamadı. Ortak kaydı kontrol edin.");
      if (requestStarted) {
        planningWriteGuard.current.retire(true); setPlanningSyncStatus("conflict");
        try {
          const response = await apiFetch("/planning-state");
          const current = await response.json();
          if (response.ok && isPlanningSeed(current.seed) && typeof current.updatedAt === "string") {
            setPlanningSyncConflict(current);
            setSyncRecovery({ reason: "write-conflict", baseUpdatedAt: remotePlanningStateUpdatedAtRef.current, delta: operationalDelta(latestSeedRef.current, current.seed) });
          }
        } catch { /* Keep writes blocked until the shared record can be read. */ }
      }
    }
  }

  function acceptRemotePlanningState() {
    if (!planningSyncConflict) return;
    if (!keepRecoveryCopy(seed, planningSyncConflict, syncRecovery?.reason ?? "accept-remote")) {
      setOperationAlert({ id: Date.now(), message: "Yerel kopya kurtarma için saklanamadı: kurtarma kopyası sınırı (5) dolu veya tarayıcı depolaması yetersiz. Hiçbir kopya otomatik silinmez ve ortak veri yüklenmedi. Yerel kopyayı indir ile kopyaları alın; dosyanın kaydedildiğini onaylayıp İndirilen kurtarma kopyalarını sil ile yer açın." });
      return;
    }
    planningWriteGuard.current.retire(false);
    const next = cloneSeed(planningSyncConflict.seed);
    const restored = restoreManualResult(next);
    setSeed(next);
    setResult(restored ?? createEmptyResult(next));
    setSelectedBatchId(restored?.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(!restored || planRequiresRecalculation(next));
    storeConfirmedLocalCopy(next, planningSyncConflict.updatedAt);
    remotePlanningStateUpdatedAtRef.current = planningSyncConflict.updatedAt;
    setLastPlanningSyncAt(planningSyncConflict.updatedAt);
    setPlanningSyncConflict(null);
    setSyncRecovery(null);
    setHistoryPast([]);
    setHistoryFuture([]);
    setPlanningSyncStatus("synced");
    setNotice("Ortak veritabanındaki daha yeni planlama durumu yüklendi");
  }

  async function forceLocalPlanningStateSync() {
    // A forced save is a planning-mode write: the server keeps its own
    // operational records. Never present it as publishing local operations.
    const operationalGap = (record: PlanningStateRecord | null, local: PlanningSeed) => Boolean(record && hasOperationalDelta(operationalDelta(local, record.seed)));
    const shownConflict = latestSyncConflictRef.current ?? planningSyncConflict;
    if (operationalGap(shownConflict, latestSeedRef.current)) {
      setOperationAlert({ id: Date.now(), message: "Bu cihazdaki üretim işlemleri ortak sürümde yok ve yayınlamayla aktarılamaz. Ortak veriyi yükleyin; yerel kopya kurtarma için saklanır." });
      return;
    }
    setPlanningSyncStatus("saving");
    try {
      await planningStateWriteRef.current;
      // Re-read everything after the queue: it may have recorded a newer conflict.
      const latestConflict = latestSyncConflictRef.current ?? planningSyncConflict;
      const latestSeed = latestSeedRef.current;
      if (latestConflict !== shownConflict || operationalGap(latestConflict, latestSeed)) {
        setPlanningSyncStatus("conflict");
        setOperationAlert({ id: Date.now(), message: "Ortak veri bu sırada yeniden değişti. Yayınlama yapılmadı; çakışmayı güncel kayıtla yeniden inceleyin." });
        return;
      }
      // A pending operational change is sent as operational: the server then
      // still checks the base revision even with force, so nothing newer is
      // overwritten and the action never becomes a planning-only success.
      const meta = readLocalDraftMeta(productionArea);
      const mode: PlanningWriteMode = meta?.pending && meta.pendingMode === "operational" ? "operational" : "planning";
      await writePlanningStateToServer(latestSeed, { force: true, mode, expectedUpdatedAt: mode === "operational" ? meta?.baseUpdatedAt || remotePlanningStateUpdatedAtRef.current : undefined });
      if (planningWriteGuard.current.blocked) return;
      setPlanningSyncConflict(null);
      setSyncRecovery(null);
      setNotice("Bu cihazdaki planlama durumu yeni ortak sürüm olarak yayınlandı");
    } catch (reason) {
      setPlanningSyncStatus((current) => current === "conflict" ? current : "offline");
      setOperationAlert({ id: Date.now(), message: reason instanceof Error ? reason.message : "Senkronizasyon tamamlanamadı." });
    }
  }

  /** Failure before commit: save the unchanged local copy against its own base revision. */
  async function retryUnsavedLocalCopy() {
    if (!syncRecovery || syncRecovery.reason !== "save-failed") return;
    const base = syncRecovery.baseUpdatedAt;
    if (!base) return;
    setPlanningSyncStatus("saving");
    try {
      await planningStateWriteRef.current;
      const meta = readLocalDraftMeta(productionArea);
      // Never downgrade an unsent operational action to a planning-only save,
      // and never send without the exact base revision (no force).
      const mode: PlanningWriteMode = meta?.pendingMode === "operational" || syncRecovery.pendingMode !== "planning" ? "operational" : "planning";
      planningWriteGuard.current.retire(false);
      await writePlanningStateToServer(latestSeedRef.current, { expectedUpdatedAt: base, mode });
      if (planningWriteGuard.current.blocked) return;
      setPlanningSyncConflict(null);
      setSyncRecovery(null);
      setNotice("Kaydedilmemiş yerel değişiklik ortak veritabanına kaydedildi");
    } catch (reason) {
      setPlanningSyncStatus((current) => current === "conflict" ? current : "offline");
      setOperationAlert({ id: Date.now(), message: reason instanceof Error ? reason.message : "Yerel değişiklik kaydedilemedi." });
    }
  }

  function syncApiInBackground(path: string, init: RequestInit, label: string) {
    void apiFetch(path, init)
      .then((response) => {
        if (!response.ok) throw new Error(`${label} sunucuya kaydedilemedi.`);
      })
      .catch(() => {
        setNotice("Sunucu bağlantısı yok — uygulama bu cihazdaki verilerle çalışıyor");
        setOperationAlert({ id: Date.now(), message: `${label} bu cihazda korundu; ortak veritabanına aktarmak için backend bağlantısını kontrol edin.` });
      });
  }

  function operationalSeed(current: PlanningSeed, nextResult: ScenarioResult): PlanningSeed {
    const nextSeed = cloneSeed(current);
    nextSeed.manualBatches = nextResult.state === "planned" ? nextResult.batches.map((batch) => ({ ...batch })) : [];
    return nextSeed;
  }

  function commitOperationalChange(nextSeed: PlanningSeed, nextResult: ScenarioResult, successMessage: string, event?: Omit<PlanningEvent, "id" | "createdAt">, undoMessage = "Son işlem geri alınabilir", preserveDirty = false) {
    const before: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: undoMessage };
    const committed = operationalSeed(nextSeed, nextResult);
    assertTurningIdentityTransition({ ...seed, manualBatches: result.batches }, committed);
    committed.planNeedsRecalculation = Boolean(nextSeed.planNeedsRecalculation || (preserveDirty && dirty) || event?.type === "archive-status");
    if (event) appendPlanningEvent(committed, event);
    // Store first: a refused local write rejects before the screen changes.
    persistPlanningState(committed, { mode: "operational" });
    setHistoryPast((current) => [...current, before].slice(-50));
    setHistoryFuture([]);
    setHistoryMessage(undoMessage);
    setSeed(committed);
    setResult(nextResult);
    setSelectedBatchId(nextResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(planRequiresRecalculation(committed));
    setNotice(successMessage);
  }

  function commitCancellationChange(nextSeed: PlanningSeed, nextResult: ScenarioResult, message: string) {
    commitOperationalChange(nextSeed, nextResult, message);
    // Older snapshots lack the durable cancellation or its review decision.
    setHistoryPast([]);
    setHistoryFuture([]);
    setHistoryMessage("İptal ve inceleme kayıtları Geri al ile değiştirilemez. Önceki geri alma geçmişi temizlendi.");
  }

  function createProductType(draft: NewTypeWizardDraft) {
    if (!isAdmin) throw new Error("Hammadde bilgileri yalnızca yöneticiler tarafından kaydedilebilir.");
    const nextSeed = cloneSeed(seed);
    const product = createProductTypeFromWizard(nextSeed, draft);
    nextSeed.planNeedsRecalculation = true;
    nextSeed.lastAutomaticPlan = undefined;
    nextSeed.planRunSequence = undefined;
    commitOperationalChange(nextSeed, result, `${product} oluşturuldu · planı yeniden çalıştırın`);
  }

  function updateSeed(mutator: (draft: PlanningSeed) => void) {
    try {
      const draft = cloneSeed(seed);
      mutator(draft);
      if (productionArea !== "cubuk-filtre") assertParameterTransitionDecided(seed, draft, result.batches);
      draft.planNeedsRecalculation = true;
      draft.lastAutomaticPlan = undefined;
      draft.planRunSequence = undefined;
      assertTurningIdentityTransition(seed, draft);
      persistPlanningState(draft);
      setSeed(draft);
      setDirty(true);
      setNotice("Girdiler değişti — planı yeniden çalıştırın");
      return true;
    } catch (error) { setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Değişiklik uygulanamadı." }); return false; }
  }

  const saveParameterDraft: SaveParameterDraft = async (mutator, targets) => {
    const impacts = targets.map(target => parameterDeactivationImpact(seed, result, target));
    if (!impacts.some(impact => impact.running.length || impact.queued.length)) {
      const next = cloneSeed(seed);
      mutator(next);
      assertParameterTransitionDecided(seed, next, result.batches);
      next.planNeedsRecalculation = true;
      next.lastAutomaticPlan = undefined;
      next.planRunSequence = undefined;
      commitOperationalChange(next, result, "Parametreler kaydedildi · planı yeniden çalıştırın");
      return true;
    }
    return new Promise<boolean>(resolve => setParameterReview({ source: seed, sourceResult: result, mutator, impacts, resolve }));
  };

  async function confirmParameterReview(decisions: DeactivationDecision[]) {
    if (!parameterReview) return;
    if (parameterReview.source !== latestSeedRef.current || parameterReview.sourceResult !== result) {
      throw new Error("Plan değişti; pencereyi kapatıp etkilenen işleri yeniden inceleyin.");
    }
    let next = { seed: cloneSeed(seed), result: cloneResult(result) };
    for (const reviewed of parameterReview.impacts) {
      const impact = parameterDeactivationImpact(next.seed, next.result, reviewed.target);
      if (impact.signature !== reviewed.signature) throw new Error("Seçimler başka bir etkilenen işi değiştirdi. Atamaları ayrı ayrı inceleyin.");
      const keys = new Set(impact.queued.map(job => job.key));
      next = applyParameterDeactivation(next.seed, next.result, reviewed.target, decisions.filter(decision => keys.has(decision.key)), impact.signature);
    }
    next.seed.manualBatches = next.result.batches.map(batch => ({ ...batch }));
    parameterReview.mutator(next.seed);
    assertParameterTransitionDecided(seed, next.seed, next.result.batches);
    next.seed.planNeedsRecalculation = true;
    next.seed.lastAutomaticPlan = undefined;
    next.seed.planRunSequence = undefined;
    commitOperationalChange(next.seed, next.result, "Pasif atamalar kaydedildi · çalışan işler korundu");
    parameterReview.resolve(true);
    setParameterReview(null);
  }

  function updateMaterialSettings(mutator: (draft: PlanningSeed) => void) {
    const nextSeed = cloneSeed(seed);
    mutator(nextSeed);
    commitOperationalChange(nextSeed, result, "Stok ve hammadde bilgileri kaydedildi", undefined, "Stok ve hammadde değişikliği geri alınabilir", true);
  }

  function applyCalendarChange(mutator: (draft: PlanningSeed) => void) {
    const nextSeed = cloneSeed(seed);
    mutator(nextSeed);
    nextSeed.lastAutomaticPlan = undefined;
    if (result.state !== "planned") {
      nextSeed.planNeedsRecalculation = true;
      setSeed(nextSeed);
      persistPlanningState(nextSeed);
      setDirty(true);
      setNotice("Takvim güncellendi — planı çalıştırın");
      return;
    }
    try {
      const previousCompletion = Math.max(0, ...result.batches.filter((batch) => batch.status === "planned").map((batch) => batch.end));
      const nextResult = recalculateManualScenario(nextSeed, result.batches, { allowPlanEndOverflow: true });
      const nextCompletion = Math.max(0, ...nextResult.batches.filter((batch) => batch.status === "planned").map((batch) => batch.end));
      const previousBatches = new Map(result.batches.filter((batch) => batch.status === "planned").map((batch) => [batch.id, batch]));
      const changedBatches = nextResult.batches.filter((batch) => {
        const previous = previousBatches.get(batch.id);
        return batch.status === "planned" && previous && (previous.start !== batch.start || previous.end !== batch.end);
      });
      const changedMachines = [...new Set(changedBatches.map((batch) => batch.machineId))];
      const dayDelta = Math.round((nextCompletion - previousCompletion) * 10) / 10;
      const deltaText = dayDelta === 0 ? "genel bitiş değişmedi" : dayDelta < 0 ? `${Math.abs(dayDelta)} gün erkene geldi` : `${dayDelta} gün ötelendi`;
      const impactText = changedBatches.length ? `${changedBatches.length} şarj · ${changedMachines.join(", ")} güncellendi` : "etkilenen planlı şarj yok";
      commitOperationalChange(nextSeed, nextResult, `Takvim uygulandı · ${impactText} · plan bitişi ${formatExcelDate(nextCompletion)} · ${deltaText}`, undefined, "Takvim değişikliği geri alınabilir");
    } catch (error) {
      nextSeed.planNeedsRecalculation = true;
      setSeed(nextSeed);
      persistPlanningState(nextSeed);
      setDirty(true);
      const message = error instanceof Error ? error.message : "Takvim değişikliği mevcut plana uygulanamadı.";
      setNotice("Takvim kaydedildi — planı yeniden çalıştırın");
      setOperationAlert({ id: Date.now(), message: `Takvim kaydedildi ancak mevcut kuyruk yeniden hesaplanamadı: ${message}` });
    }
  }

  function runScenario(request: PlanRunRequest) {
    const fixedBatches = result.batches.filter((batch) =>
      batch.status === "planned" && (request.appendToExistingPlan || batch.locked || batch.routeCommitted));
    const { prepared, result: next } = executePlanRun(seed, fixedBatches, request);
    const planningSeed = prepared.seed;
    const nextSeed = operationalSeed(planningSeed, next);
    nextSeed.lastAutomaticPlan = createAutomaticPlanSnapshot(next);
    if (productionArea === "cubuk-filtre") setActiveFilterScenarioName("");
    setSeed(nextSeed);
    setResult(next);
    persistPlanningState(nextSeed);
    setSelectedBatchId(next.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(planRequiresRecalculation(nextSeed));
    const completion = Math.max(0, ...next.batches.filter((batch) => batch.status === "planned").map((batch) => batch.end));
    const completionLabel = planningSeed.productionArea === "cubuk-filtre" && planningSeed.monthlyCustomerDemand ? "Torna bitişi" : "bitiş";
    const shortage = Math.max(0, next.summary.demand - next.summary.planned);
    const pendingRangeCount = Math.max(0, (prepared.sequence?.ranges.length ?? 1) - (prepared.sequence?.completedRangeCount ?? 1));
    setNotice(request.appendToExistingPlan
      ? pendingRangeCount > 0
        ? `Yeni aralığın ilki plana eklendi · ${prepared.scopeLabel} · manuel kontrolünüzden sonra ${pendingRangeCount} aralık daha eklenebilir · ${formatNumber(shortage)} eksik üretim`
        : `Planın devamı eklendi · ${prepared.scopeLabel} · mevcut düzen korundu · ${formatNumber(shortage)} eksik üretim · ${completionLabel} ${formatExcelDate(completion)}`
      : pendingRangeCount > 0
        ? `İlk aralık planlandı · ${prepared.scopeLabel} · manuel kontrolünüzden sonra ${pendingRangeCount} aralık daha eklenebilir · ${formatNumber(shortage)} eksik üretim`
        : `Plan tamamlandı · ${optimizationGoalLabel(request.optimizationGoal)} · ${prepared.scopeLabel} · ${next.summary.plannedBatchCount} şarj · ${formatNumber(shortage)} eksik üretim · ${completionLabel} ${formatExcelDate(completion)}`);
    setPlanRunOpen(false);
    setAutomaticComparisonOpen(false);
    setView("planning");
  }

  function previewPlanRuns(request: PlanRunRequest): PlanComparisonRow[] {
    const fixedBatches = result.batches.filter((batch) =>
      batch.status === "planned" && (request.appendToExistingPlan || batch.locked || batch.routeCommitted));
    return comparePlanRuns(seed, fixedBatches, request);
  }

  function runNextPlanRange() {
    try {
      const fixedBatches = result.batches.filter((batch) => batch.status === "planned");
      const next = executeNextPlanStage(seed, fixedBatches);
      next.seed.lastAutomaticPlan = createAutomaticPlanSnapshot(next.result);
      const rangeNumber = next.sequence.completedRangeCount;
      const completion = next.result.summary.completion;
      const completionLabel = next.seed.productionArea === "cubuk-filtre" && next.seed.monthlyCustomerDemand ? "Torna bitişi" : "bitiş";
      const shortage = Math.max(0, next.result.summary.demand - next.result.summary.planned);
      commitOperationalChange(
        next.seed,
        next.result,
        `${rangeNumber}. aralık plana eklendi · ${next.completedRange.label} · ${formatNumber(shortage)} eksik üretim · ${completionLabel} ${formatExcelDate(completion)}`,
        undefined,
        `${rangeNumber}. aralık ekleme işlemi geri alınabilir`,
      );
      setAutomaticComparisonOpen(false);
      setView("planning");
    } catch (error) {
      const message = error instanceof Error ? error.message : "Sıradaki planlama aralığı eklenemedi.";
      setNotice(message);
      setOperationAlert({ id: Date.now(), message });
    }
  }

  function restoreLastAutomaticPlan() {
    const snapshot = seed.lastAutomaticPlan;
    if (!snapshot) {
      setOperationAlert({ id: Date.now(), message: "Geri dönülecek otomatik plan bulunamadı." });
      return;
    }
    let restoredResult: ScenarioResult;
    try { restoredResult = restoreScenarioFromBatches(seed, automaticPlanResult(snapshot).batches); }
    catch (error) { setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Otomatik plan yüklenemedi." }); return; }
    const restoredSeed = cloneSeed(seed);
    restoredSeed.activePlanRun = restoredResult.planRun ?? restoredSeed.activePlanRun;
    commitOperationalChange(
      restoredSeed,
      restoredResult,
      "Son otomatik plan geri yüklendi",
      undefined,
      "Otomatik plana dönüş geri alınabilir",
    );
    setAutomaticComparisonOpen(false);
  }

  function applyCustomerDemandImport(preview: ConfirmedOverviewPreview) {
    const comparison = compareCustomerDemandImport(seed.customerDemand, preview);
    const requestedScope = scopeForDemandReimport(seed.customerDemand, preview);
    const state = buildWeeklyPlanningState(preview, seed.orders, requestedScope, seed.customerOrderOverrides);
    const nextSeed = cloneSeed(seed);
    nextSeed.lastAutomaticPlan = undefined;
    nextSeed.planRunSequence = undefined;
    const planEnd = inputDateToSerial(state.planEndDate);
    nextSeed.orderCatalog = state.orderCatalog;
    nextSeed.orderCatalogName = preview.fileName;
    nextSeed.orders = state.orders;
    nextSeed.customerDemand = state.dataset;
    nextSeed.orderImport = orderImportMetadataForSeed({ customerDemand: state.dataset }) ?? undefined;
    nextSeed.orderImportGrossOrders = undefined;
    nextSeed.openingStock = {};
    nextSeed.demandTargets = undefined;
    for (const machine of nextSeed.machines) machine.planEnd = planEnd;
    if (seed.customerDemand) {
      const previousVersion = demandImportVersion(seed.customerDemand);
      syncApiInBackground("/order-imports/history", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(previousVersion) }, "Önceki sipariş Excel geçmişi");
    }
    const nextVersion = demandImportVersion(state.dataset);
    syncApiInBackground("/order-imports/history", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(nextVersion) }, "Yeni sipariş Excel geçmişi");

    const protectedBatches = protectedBatchesForDemandReimport(result);
    const scopeStart = state.dataset.weeks.find((week) => week.id === state.dataset.activeScope.startWeekId)?.label ?? state.dataset.activeScope.startWeekId;
    const scopeEnd = state.dataset.weeks.find((week) => week.id === state.dataset.activeScope.endWeekId)?.label ?? state.dataset.activeScope.endWeekId;
    const delta = comparison.requirementDelta;
    const deltaLabel = comparison.repeatImport ? ` · talep farkı ${delta > 0 ? "+" : ""}${formatNumber(delta)}` : "";

    if (result.state === "planned") {
      const nextResult = runOptimizedScenario(nextSeed, protectedBatches);
      commitOperationalChange(
        nextSeed,
        nextResult,
        `Müşteri Excel’i uzlaştırıldı · ${scopeStart}–${scopeEnd}${deltaLabel} · ${protectedBatches.length} korunan şarj`,
        undefined,
        "Müşteri Excel’i güncellemesi geri alınabilir",
      );
    } else {
      nextSeed.manualBatches = [];
      setSeed(nextSeed);
      setResult(createEmptyResult(nextSeed));
      setSelectedBatchId("");
      setDirty(true);
      persistPlanningState(nextSeed);
      setNotice(`Müşteri Excel’i uygulandı · ${scopeStart}–${scopeEnd}${deltaLabel} · planı çalıştırın`);
    }
  }

  function clearPlan() {
    try {
      const next = clearPlanKeepingLocks(seed, result);
      const count = next.result.batches.length;
      commitOperationalChange(next.seed, next.result,
        count ? `Plan temizlendi — üretim kaydı bulunan veya üretim durumu belirsiz ${count} şarj korundu` : "Plan temizlendi — girdiler korunuyor",
        undefined, "Plan temizleme işlemi geri alınabilir");
      setDirty(true);
      if (productionArea === "cubuk-filtre") setActiveFilterScenarioName("");
      setView("planning");
    } catch (error) {
      const message = error instanceof Error ? error.message : "Kilitli plan doğrulanamadı.";
      setNotice("Plan temizlenemedi — mevcut işler korundu");
      setOperationAlert({ id: Date.now(), message });
    }
  }

  async function saveScenario(name: string, notes: string) {
    if (result.state !== "planned") {
      setNotice("Kaydetmeden önce planı çalıştırın");
      throw new Error("Kaydetmeden önce planı çalıştırın.");
    }
    const createdAt = new Date().toISOString();
    const scenario: StoredScenario = {
      id: crypto.randomUUID(),
      name: name.trim(),
      createdAt,
      notes: notes.trim(),
      seed: scenarioPlanningSeed(cloneSeed(seed)),
      result,
    };
    await addStoredScenario(scenario);
    if (productionArea === "cubuk-filtre") setActiveFilterScenarioName(scenario.name);
    if (productionArea !== "cubuk-filtre") {
      const identified = identifyScenario(latestSeedRef.current, scenario, false, seed);
      setSeed(identified);
      persistPlanningState(identified);
    }
    await fetchScenarioPage(0, true);
    setNotice(`${scenario.name} veritabanına kaydedildi`);
    setScenarioSaveOpen(false);
  }

  function addManualBatch(product: string, machineId: string, quantity: number, position: number, expectedSignature: string) {
    const next = addBatchManually(seed, result, product, machineId, quantity, position, expectedSignature);
    commitOperationalChange(seed, next, `${product} · ${machineId} · ${position + 1}. sıraya ${formatNumber(quantity)} adet eklendi`,
      { type: "add", machineId, message: `${product}, ${machineId} kuyruğunda ${position + 1}. sıraya ${formatNumber(quantity)} adet manuel eklendi.` }, "Manuel şarj geri alınabilir", true);
  }

  function applyManualChange(action: () => ScenarioResult, successMessage: string, event?: Omit<PlanningEvent, "id" | "createdAt">) {
    try {
      const next = action();
      commitOperationalChange(seed, next, successMessage, event);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Manuel plan değişikliği uygulanamadı";
      setNotice(message);
      setOperationAlert({ id: Date.now(), message });
    }
  }

  function undoLastOperation() {
    const previous = historyPast.at(-1);
    if (!previous) return;
    const current: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: previous.message };
    setHistoryPast((items) => items.slice(0, -1));
    setHistoryFuture((items) => [current, ...items].slice(0, 50));
    setSeed(previous.seed);
    setResult(previous.result);
    persistPlanningState(previous.seed, { mode: "operational" });
    setSelectedBatchId(previous.selectedBatchId || previous.result.batches.find((batch) => batch.status === "planned")?.id || "");
    setDirty(previous.dirty);
    setNotice("Son manuel işlem geri alındı");
    setHistoryMessage(`Geri alındı · ${previous.message}`);
  }

  function redoLastOperation() {
    const next = historyFuture[0];
    if (!next) return;
    const current: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: next.message };
    setHistoryPast((items) => [...items, current].slice(-50));
    setHistoryFuture((items) => items.slice(1));
    setSeed(next.seed);
    setResult(next.result);
    persistPlanningState(next.seed, { mode: "operational" });
    setSelectedBatchId(next.selectedBatchId || next.result.batches.find((batch) => batch.status === "planned")?.id || "");
    setDirty(next.dirty);
    setNotice("Manuel işlem yeniden uygulandı");
    setHistoryMessage(`Yeniden uygulandı · ${next.message}`);
  }

  function lockThrough(batch: PlannedBatch) {
    applyManualChange(() => lockQueueThrough(result, batch.machineId, batch.id), `${batch.machineId} kuyruğu ${queuePosition(batch.planColumn)}. işe kadar kilitlendi`, { type: "lock", machineId: batch.machineId, batchId: batch.id, message: `${batch.machineId} kuyruğu ${queuePosition(batch.planColumn)}. işe kadar kilitlendi.` });
  }

  function unlockQueue(machineId: string) {
    applyManualChange(() => unlockMachineQueue(result, machineId), `${machineId} kuyruk kilidi kaldırıldı`, { type: "unlock", machineId, message: `${machineId} kuyruk kilidi kaldırıldı.` });
  }

  function saveBatchWorkOrder(batch: PlannedBatch, workOrder: string) {
    applyManualChange(() => updateBatchWorkOrder(seed, result, batch.id, workOrder), `${batch.product} iş emri kaydedildi`, { type: "work-order", machineId: batch.machineId, batchId: batch.id, message: `${batch.product} için iş emri ${workOrder || "boş"} olarak güncellendi.` });
  }

  function updateBatchQuantity(batch: PlannedBatch, quantity: number) {
    applyManualChange(() => updateBatchQuantityManually(seed, result, batch.id, quantity), `${batch.product} şarj adedi güncellendi`, { type: "quantity", machineId: batch.machineId, batchId: batch.id, message: `${batch.product} şarjı ${formatNumber(batch.quantity)} → ${formatNumber(quantity)} adet olarak güncellendi.` });
  }

  function loadScenario(scenario: StoredScenario) {
    // Normalize only the saved planning inputs. Inject live factory truth last
    // so loading a scenario can never roll or otherwise edit a current job.
    let scenarioSeed: PlanningSeed;
    let loadedResult: ScenarioResult;
    let overflows: ScenarioPlanOverflow[] = [];
    try {
      scenarioSeed = cloneSeed(mergeScenarioWithLiveOperations(scenario.seed, seed));
      scenarioSeed.lastAutomaticPlan = undefined;
      const rebased = rebaseScenarioPlan(scenarioSeed, scenario.result);
      loadedResult = rebased.result;
      overflows = rebased.overflows;
    } catch (error) {
      const message = error instanceof Error ? error.message : "Senaryo canlı üretim durumuna uygulanamadı.";
      setOperationAlert({ id: Date.now(), message });
      setNotice("Senaryo yüklenmedi · canlı işler korundu");
      return;
    }
    scenarioSeed.manualBatches = loadedResult.batches.map((batch) => ({ ...batch }));
    scenarioSeed = identifyScenario(scenarioSeed, scenario, planRequiresRecalculation(scenarioSeed));
    if (productionArea === "cubuk-filtre") setActiveFilterScenarioName(scenario.name);
    setSeed(scenarioSeed);
    persistPlanningState(scenarioSeed);
    setResult(loadedResult);
    setSelectedBatchId(loadedResult.batches[0]?.id ?? "");
    setDirty(planRequiresRecalculation(scenarioSeed));
    setScenarioLoadReport(overflows.length ? { scenarioName: scenario.name, overflows } : null);
    setNotice(overflows.length ? `${scenario.name} yüklendi · ${overflows.length} iş plan penceresini aşıyor` : `${scenario.name} yüklendi`);
    setView("planning");
  }

  function restorePlanningRevision(revision: PlanningStateRevision) {
    let restoredSeed: PlanningSeed;
    let restoredResult: ScenarioResult;
    try {
      restoredSeed = cloneSeed(mergeScenarioWithLiveOperations(revision.seed, seed));
      restoredResult = restoredSeed.manualBatches?.length ? restoreScenarioFromBatches(restoredSeed, restoredSeed.manualBatches) : createEmptyResult(restoredSeed);
    }
    catch (error) { setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Versiyon yüklenemedi." }); return; }
    const before: OperationalSnapshot = { seed: cloneSeed(seed), result: cloneResult(result), selectedBatchId, dirty, message: "Versiyon geri yükleme işlemi geri alınabilir" };
    setHistoryPast((current) => [...current, before].slice(-50));
    setHistoryFuture([]);
    setSeed(restoredSeed);
    setResult(restoredResult);
    setSelectedBatchId(restoredResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(!restoredSeed.manualBatches?.length || planRequiresRecalculation(restoredSeed));
    persistPlanningState(restoredSeed);
    setNotice(`${formatFactoryDateTime(revision.createdAt)} versiyonu geri yüklendi`);
    setView("planning");
  }

  async function approveOrderRevision(revision: OrderRevision) {
    const revisionSeed = cloneSeed(mergeScenarioWithLiveOperations(revision.seed, seed));
    const revisionResult = restoreScenarioFromBatches(revisionSeed, revision.result.batches);
    const response = await apiFetch("/revisions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(revision) });
    if (!response.ok) throw new Error("Sipariş revizyonu kaydedilemedi.");
    revisionSeed.lastAutomaticPlan = undefined;
    revisionSeed.planRunSequence = undefined;
    revisionSeed.manualBatches = revisionResult.batches.map((batch) => ({ ...batch }));
    setSeed(revisionSeed);
    persistPlanningState(revisionSeed);
    setResult(revisionResult);
    setRevisions((current) => [revision, ...current]);
    setSelectedBatchId(revisionResult.batches.find((batch) => batch.status === "planned")?.id ?? "");
    setDirty(planRequiresRecalculation(revisionSeed));
    setNotice(`${revision.product} revizyonu onaylandı; dondurulmuş işler korundu`);
  }

  function navigateToFinding(target: AuditTarget) {
    if (target.orderId) setFocusedOrderId(target.orderId);
    if (target.machineId) setSelectedMachineId(target.machineId);
    if (target.batchId) setSelectedBatchId(target.batchId);
    setPageGuideOpen(false);
    changeView(target.view);
  }

  function openAdvice(orderId: string | null = null, machineId: string | null = null) {
    setAdviceOrderId(orderId);
    setAdviceMachineId(machineId);
    setAdviceOpen(true);
  }

  function dismissAdvice(id: string) {
    setDismissedAdviceIds((current) => {
      const next = [...new Set([...current, id])];
      window.localStorage.setItem(dismissedAdviceKey, JSON.stringify(next));
      return next;
    });
  }

  function restoreDismissedAdvice() {
    setDismissedAdviceIds([]);
    window.localStorage.removeItem(dismissedAdviceKey);
  }

  function applyAdvice(item: PlanningAdvice) {
    if (item.action.type === "inspect-interruption") { setFocusedJourneyJobId(item.action.chargeId); changeView("processes"); setAdviceOpen(false); return; }
    if (item.action.type === "pull-forward") {
      const action = item.action;
      applyManualChange(
        () => applyPullForwardAdvice(seed, result, action),
        `${item.product}, ${action.sourceWeekLabel} talebinden ${action.machineId} tezgahına öne çekildi`,
        { type: "pull-forward", machineId: action.machineId, message: `${item.product}, ${action.sourceWeekLabel} talebinden ${action.pulledIntoRangeLabel} kapasitesine öne çekildi.` },
      );
      return;
    }
    if (item.action.type === "move") {
      const action = item.action;
      applyManualChange(
        () => moveBatchManually(seed, result, action.batchId, action.toMachineId, action.position),
        `${item.product} tavsiyesi uygulandı · şarj ${action.toMachineId} tezgahına taşındı`,
        { type: "move", machineId: action.toMachineId, batchId: action.batchId, message: `${item.product}, tavsiye ile ${action.fromMachineId} → ${action.toMachineId} taşındı.` },
      );
      return;
    }
    if (item.action.type === "add-charge") {
      const action = item.action;
      applyManualChange(
        () => addBatchManually(seed, result, item.product, action.machineId, action.quantity, action.position),
        `${item.product} için önerilen şarj ${action.machineId} kuyruğuna eklendi`,
        { type: "add", machineId: action.machineId, message: `${item.product}, tavsiye ile ${action.machineId} kuyruğuna eklendi.` },
      );
      return;
    }
    const action = item.action;
    applyCalendarChange((draft) => replaceMachineShiftOverrides(draft, [action.machineId], action.start, action.end, action.shiftCount, `${item.product} termin önerisi`));
  }

  return (
    <RaviContextProvider view={view} planning={raviPlanningContext} entryPoint={entryPoint}><IdentityReviewActionContext.Provider value={() => setIdentityReviewOpen(true)}><main className="app-shell">
      <Header areaSwitchDisabled={planningSyncStatus === "saving" || planningSyncStatus === "loading"} isAdmin={isAdmin} view={view} setView={(next) => { setPageGuideOpen(false); if (next === "processes") setFocusedJourneyJobId(""); changeView(next); window.scrollTo(0, 0); }} notice={notice} adviceCount={visiblePlanningAdvice.length + assignmentConflicts.length + cancellationReviews.length + staleChargeAdvice.length} onOpenAdvice={() => openAdvice()} onOpenArchive={() => setArchiveOpen(true)} productionSyncInfo={productionSyncInfo} productionPullStatus={productionPullStatus} onPullProduction={() => { setProductionPullConfirmOpen(true); void previewProductionState(); }}
        plan={{ visible: view !== "feedback", dirty, scenarioLabel: productionArea === "cubuk-filtre" ? activeScenarioName || null : activeScenario ? `${activeScenario.name} · ${activeScenario.id} · ${activeScenario.modified ? "Kaydedilmiş senaryodan değiştirildi" : "Kaydedilmiş senaryo"}` : null,
          canUndo: historyPast.length > 0, canRedo: historyFuture.length > 0, onRun: () => setPlanRunOpen(true), onClear: clearPlan, onUndo: undoLastOperation, onRedo: redoLastOperation,
          onSaveScenario: () => result.state === "planned" ? setScenarioSaveOpen(true) : setNotice("Kaydetmeden önce planı çalıştırın") }}
        onOpenGuide={() => setPageGuideOpen(true)} onStartTour={() => setTourOpen(true)} />
      <QueueIdentityNotice issue={queueIdentityIssue} inlineError={view === "orders" ? deliveryReport.error : undefined} />
      {view !== "planning" && <section className="page-bar">
        <div className="page-bar-title">
          <h1>{pageTitle(view)}</h1>
          <button className="ui-icon-btn page-help" onClick={() => setPageGuideOpen((open) => !open)} title="Sayfa rehberi" aria-label="Sayfa rehberi" aria-expanded={pageGuideOpen}><Question size={16} /></button>
        </div>
        <div id={PAGE_BAR_SLOT_ID} className="page-bar-slot" />
      </section>}
      {pageGuideOpen && <PageGuidePanel view={view} onClose={() => setPageGuideOpen(false)} />}

      {view === "planning" && (
        <PlanningView report={deliveryReport} reportRange={reportRange} onReportRangeChange={setReportRange}
          seed={seed}
          result={result}
          dirty={dirty}
          selectedBatch={selectedBatch}
          onSelectBatch={setSelectedBatchId}
          onMoveBatch={(batchId, resourceId, position) => setRouteRequest({ kind: "turning", batchId, resourceId, position })}
          onReviewRoute={setRouteRequest}
          onRemoveBatch={(batchId) => { const batch = result.batches.find((item) => item.id === batchId); applyManualChange(() => removeBatchManually(seed, result, batchId), "Şarj plandan çıkarıldı", { type: "remove", machineId: batch?.machineId, batchId, message: `${batch?.product ?? "Şarj"} plandan çıkarıldı.` }); }}
          onLockThrough={lockThrough}
          onUnlockQueue={unlockQueue}
          onSaveWorkOrder={saveBatchWorkOrder}
          onUpdateBatchQuantity={updateBatchQuantity}
          onSaveCurrentJob={saveCurrentJob}
          onCompleteCurrentJob={completeCurrentJob}
          onOperationError={(message) => setOperationAlert({ id: Date.now(), message })}
          advice={visiblePlanningAdvice}
          onApplyAdvice={applyAdvice}
          onOpenMachineAdvice={(machineId) => openAdvice(null, machineId)}
          onOpenManualBatch={() => setQuickManualProduct("")}
          automaticComparisonAvailable={automaticComparisonAvailable}
          onOpenAutomaticComparison={() => setAutomaticComparisonOpen(true)}
          onPlanNextRange={runNextPlanRange}
          onReplanProcess={replanDownstreamProcess}
          updateSeed={applyCalendarChange}
          onOpenJourney={(jobId) => { setFocusedJourneyJobId(jobId); setView("processes"); window.scrollTo(0, 0); }}
        />
      )}
      {view === "processes" && productionArea !== "cubuk-filtre" && <ProductionCancellationHistory records={seed.productionCancellations ?? []} />}
      {view === "processes" && <ProcessPlanningView onOpenArchive={(focus) => { setArchiveFocus(focus); setArchiveOpen(true); }} onDeliverWip={deliverJourneyWip} onCompleteBuffer={releaseJourneyBuffer} seed={seed} result={result} dirty={dirty} focusJobId={focusedJourneyJobId} onCompleteCurrentJob={completeCurrentJob} onCompleteWipOperation={finishWipOperation} onCorrectWipStage={changeWipStage} onReleaseWip={releaseHeldWip} onSaveJourneyNote={saveJourneyNote} />}
      {view === "stocks" && <ProcessStockView seed={seed} result={result} dirty={dirty} canEdit={isAdmin} updateSettings={updateMaterialSettings} onAddProduction={setQuickManualProduct} />}
      {view === "control" && <PlanControl seed={seed} result={result} dirty={dirty} onNavigate={navigateToFinding} />}
      {view === "orders" && <OrdersView savedRevision={lastPlanningSyncAt} synced={planningSyncStatus === "synced"} report={deliveryReport} reportRange={reportRange} onReportRangeChange={setReportRange} seed={seed} result={result} dirty={dirty} activeScenarioName={productionArea === "cubuk-filtre" ? activeScenarioName || scenarioSummaries.find((scenario) => scenario.planRun?.planId && scenario.planRun.planId === (result.planRun ?? seed.activePlanRun)?.planId)?.name || "" : activeScenarioName} activeScenario={activeScenario} revisions={revisions} focusOrderId={focusedOrderId} onApprove={approveOrderRevision} strategy={strategy} updateSeed={updateSeed} onApplyCustomerImport={applyCustomerDemandImport} onOpenAdvice={(orderId) => openAdvice(orderId)} onOpenManualBatch={(product) => setQuickManualProduct(product)} />}
      {view === "machines" && (
        <MachinesView
          onCancelRemaining={(machineId, chargeId) => {
            const row = cancellableRemainders(seed, result).find(item => item.machineId === machineId && item.chargeId === chargeId);
            if (row) setCancellationRow(row);
            else setOperationAlert({ id: Date.now(), message: "İptal edilecek kalan üretim bulunamadı. Kayıtları yeniden inceleyin." });
          }}
          onSaveMachineAvailability={saveMachineAvailability}
          seed={seed}
          result={result}
          dirty={dirty}
          selectedMachineId={selectedMachineId}
          setSelectedMachineId={setSelectedMachineId}
          updateSeed={updateSeed}
          updateCalendar={applyCalendarChange}
          onAddBatch={addManualBatch}
          onMoveBatch={(batchId, resourceId, position) => setRouteRequest({ kind: "turning", batchId, resourceId, position })}
          onReviewRoute={setRouteRequest}
          onRemoveBatch={(batchId) => { const batch = result.batches.find((item) => item.id === batchId); applyManualChange(() => removeBatchManually(seed, result, batchId), "Şarj plandan çıkarıldı", { type: "remove", machineId: batch?.machineId, batchId, message: `${batch?.product ?? "Şarj"} plandan çıkarıldı.` }); }}
          onLockThrough={lockThrough}
          onUnlockQueue={unlockQueue}
          onSaveWorkOrder={saveBatchWorkOrder}
          onUpdateBatchQuantity={updateBatchQuantity}
          onSaveCurrentJob={saveCurrentJob}
          onCompleteCurrentJob={completeCurrentJob}
          onStartProcessCurrentJob={beginDownstreamCurrentJob}
          onReplanProcess={replanDownstreamProcess}
          onReplaceTurningJob={replaceTurningJob}
          onReplaceProcessCurrentJob={replaceDownstreamCurrentJob}
          onSaveProcessCurrentJob={saveDownstreamCurrentJob}
          onCompleteProcessCurrentJob={finishDownstreamCurrentJob}
          onCompleteWipOperation={finishWipOperation}
        />
      )}
      {view === "parameters" && (productionArea === "cubuk-filtre" ? <FilterProductionData seed={seed} updateSeed={updateSeed} canManageMaterials={isAdmin} /> : <ParametersView seed={seed} result={result} onSaveParameterDraft={saveParameterDraft} updateSeed={updateSeed} onCreateType={createProductType} canManageMaterials={isAdmin} />)}
      {view === "settings" && isAdmin && <SettingsView seed={seed} result={result} dirty={dirty} updateMaterials={updateMaterialSettings} updateSeed={applyCalendarChange} updatePlanningInputs={updateSeed} />}
      {view === "scenarios" && <ScenariosView scenarios={scenarioSummaries} loadedScenarios={scenarios} total={scenarioListTotal} loading={scenarioListLoading} error={scenarioListError} planningHistory={planningHistory} onFetchScenario={fetchScenarioDetail} onLoad={loadScenario} onLoadMore={() => fetchScenarioPage(scenarioSummaries.length)} onRetry={() => fetchScenarioPage(0, true)} onRestoreRevision={restorePlanningRevision} onDelete={deleteStoredScenario} onUpdate={updateStoredScenario} onImport={importStoredScenarios} />}
      <FeedbackFeature pagePath={pageTitle(view)} workspace={view === "feedback"} />
      {archiveOpen && <ProductionArchiveDrawer seed={seed} focus={archiveFocus} onRestoreDelivery={restoreProductionDelivery} onClose={() => { setArchiveOpen(false); setArchiveFocus(undefined); }} onStatusChange={changeProductionHistoryStatus} onEdit={editProductionHistoryEntry} onAllocate={allocateProductionHistory} />}
      {parameterReview && <ParameterDeactivationDialog impacts={parameterReview.impacts} onConfirm={confirmParameterReview} onClose={() => { parameterReview.resolve(false); setParameterReview(null); }} />}
      {cancellationRow && <ProductionCancellationDialog row={cancellationRow} onClose={() => setCancellationRow(null)} onConfirm={input => {
        const next = cancelRemainingProduction(seed, result, input);
        commitCancellationChange(next.seed, next.result, "Kalan üretim iptal edildi · yeniden üretim için Tavsiyeler’i inceleyin");
        setCancellationRow(null);
      }} />}
      {adviceOpen && <RecommendationCenter reviewCount={assignmentConflicts.length + cancellationReviews.length + staleChargeAdvice.length} reviewPanel={productionArea !== "cubuk-filtre" ? <><StaleChargePanel seed={seed}
        onSaveThreshold={days => { const next = cloneSeed(seed); next.adviceSettings = validateAdviceSettings({ version: 1, staleChargeDays: days }); commitOperationalChange(next, result, "Hareketsiz şarj eşiği kaydedildi", undefined, "Tavsiye eşiği değişikliği geri alınabilir", true); }}
        onInspect={chargeId => { setFocusedJourneyJobId(chargeId); changeView("processes"); setAdviceOpen(false); }} /><PistonReviewPanel conflicts={assignmentConflicts} cancellations={cancellationReviews}
        onResolveAssignment={impact => { setAdviceOpen(false); setParameterReview({ source: seed, sourceResult: result, mutator: () => {}, impacts: [impact], resolve: () => {} }); }}
        onReviewCancellation={(id, decision) => { const next = reviewProductionCancellation(seed, id, decision); commitCancellationChange(next, result, "İptal sonrası inceleme kaydedildi · planı yeniden çalıştırın"); }} /></> : undefined} advice={visiblePlanningAdvice} allAdviceCount={planningAdvice.length} dismissedCount={dismissedAdviceIds.length} focusedOrderId={adviceOrderId} focusedMachineId={adviceMachineId} focusedProduct={seed.orders.find((order) => order.id === adviceOrderId)?.product ?? ""} currentPlan={result.state === "planned" && !dirty} onClose={() => setAdviceOpen(false)} onShowAll={() => { setAdviceOrderId(null); setAdviceMachineId(null); }} onApply={applyAdvice} onDismiss={dismissAdvice} onRestoreDismissed={restoreDismissedAdvice} onManual={(product) => { setQuickManualProduct(product); setAdviceOpen(false); }} />}
      {quickManualProduct !== null && <ManualBatchDialog key={quickManualProduct || "all"} seed={seed} result={result} dirty={dirty} initialProduct={quickManualProduct} entryPoint={view} onClose={() => setQuickManualProduct(null)} onSave={addManualBatch} />}
      {routeRequest && <RoutePlacementDialog seed={seed} result={result} request={routeRequest} dirty={dirty} onClose={() => setRouteRequest(null)} onApply={preview => {
        if (planningSyncStatus === "conflict" || planningSyncConflict) throw new Error("Kayıt çakışmasını çözün ve önizlemeyi yenileyin.");
        const next = revalidateRoutePlacement(seed, result, preview);
        commitOperationalChange(next.seed, next.result, "Üretim akışı güncellendi", { type: "move", batchId: next.afterJob.batchId, message: `${next.afterJob.workOrder || next.afterJob.product} üretim akışı birlikte güncellendi.` }, "Üretim akışı değişikliği geri alınabilir", true);
        setRouteRequest(null);
      }} />}
      {planRunOpen && <PlanRunDialog seed={seed} batches={result.batches} existingPlanAvailable={result.state === "planned" && (!dirty || (seed.productionArea === "cubuk-filtre" && Boolean(seed.monthlyCustomerDemand)))} existingPlannedBatchCount={result.batches.filter((batch) => batch.status === "planned").length} lockedBatchCount={result.batches.filter((batch) => batch.status === "planned" && batch.locked).length} onClose={() => setPlanRunOpen(false)} onCompare={previewPlanRuns} onRun={runScenario} />}
      {automaticComparisonOpen && seed.lastAutomaticPlan && automaticComparisonAvailable && <AutomaticPlanComparisonDialog seed={seed} snapshot={seed.lastAutomaticPlan} manualResult={result} onClose={() => setAutomaticComparisonOpen(false)} onRestore={restoreLastAutomaticPlan} />}
      {scenarioSaveOpen && <ScenarioSaveDialog sequence={nextScenarioNumber(scenarioSummaries)} onClose={() => setScenarioSaveOpen(false)} onSave={saveScenario} />}
      {scenarioLoadReport && <ScenarioLoadReportDialog report={scenarioLoadReport} onClose={() => setScenarioLoadReport(null)} />}
      {operationAlert && <div key={operationAlert.id} className="operation-alert-toast" role="alert" aria-live="assertive"><Warning size={21} weight="fill" /><div><strong>İşlem uygulanmadı</strong><p>{operationAlert.message}</p></div><button onClick={() => setOperationAlert(null)} aria-label="Operasyon uyarısını kapat"><X size={15} /></button><i /></div>}
      {historyMessage && <div className="operation-undo" role="status"><span><strong>İşlem geçmişi</strong><small>{historyMessage}</small></span><button disabled={!historyPast.length} onClick={undoLastOperation}><ArrowCounterClockwise size={14} /> Geri al</button><button disabled={!historyFuture.length} onClick={redoLastOperation}><ArrowClockwise size={14} /> Yinele</button><button className="operation-undo-close" onClick={() => setHistoryMessage("")} aria-label="İşlem geçmişi bildirimini kapat"><X size={14} /></button></div>}
      {planningSyncConflict && (() => {
        const delta = operationalDelta(seed, planningSyncConflict.seed);
        const missing = describeOperationalDelta(delta);
        const reason = syncRecovery?.reason ?? "write-conflict";
        const unsaved = reason === "save-failed";
        const title = unsaved ? "Kaydedilmemiş yerel değişiklik bulundu" : reason === "missing-base" ? "Yerel kopyanın dayandığı ortak sürüm bilinmiyor" : "Ortak veri başka bir oturumda değişti";
        const intro = unsaved ? "Son kayıt ortak veritabanına ulaşmadı. Ortak veri o zamandan beri değişmedi. Yerel değişiklik kaydedilene kadar diğer kayıtlar durduruldu."
          : reason === "missing-base" ? "Bu kopya eski bir uygulama sürümünden kalmış. Otomatik birleştirme yapılmadı; hangi sürümle devam edeceğinizi seçin."
          : "Daha yeni ortak kayıt sessizce ezilmedi. Yerel kopya birleştirilmedi; hangi sürümle devam edeceğinizi açıkça seçin.";
        return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog sync-conflict-dialog" role="dialog" aria-modal="true" aria-label="Planlama verisi çakışması"><div className="operational-dialog-head"><span className="dialog-icon maintenance"><Warning size={20} weight="fill" /></span><div><span>{unsaved ? "KAYDEDİLMEMİŞ DEĞİŞİKLİK" : "SENKRONİZASYON ÇAKIŞMASI"}</span><h2>{title}</h2><p>{intro}</p></div><button className="delete-button" onClick={() => setPlanningSyncConflictState(null)} aria-label="Senkronizasyon uyarısını kapat"><X size={16} /></button></div><div className="sync-conflict-versions"><span><small>Bu cihazdaki son değişiklik</small><strong>{formatFactoryDateTime(window.localStorage.getItem(planningStateUpdatedAtKey) ?? "")}</strong></span><span><small>Yerel kopyanın dayandığı ortak sürüm</small><strong>{syncRecovery?.baseUpdatedAt ? formatFactoryDateTime(syncRecovery.baseUpdatedAt) : "Bilinmiyor"}</strong></span><span><small>Ortak veritabanındaki sürüm</small><strong>{formatFactoryDateTime(planningSyncConflict.updatedAt)}</strong></span></div>{missing.length > 0 && <div className="sync-conflict-note" role="status"><strong>Ortak sürümde olmayan yerel üretim işlemleri</strong><span>{missing.join(" · ")}</span><span>{unsaved ? "Yerel değişikliği kaydet bu işlemleri aynı ortak sürüme karşı bir kez kaydeder; ortak veri değiştiyse kayıt reddedilir ve hiçbir işlem iki kez yazılmaz." : "Bu işlemler yayınlamayla aktarılamaz. Ortak veriyi yükle seçilirse yerel kopya kurtarma için saklanır; işlemleri güncel ortak veriye yeniden girin."}</span></div>}<div className="sync-conflict-note"><strong>Ortak veriyi yükle</strong><span>Bu cihazdaki kaydedilmemiş değişikliklerin yerine ortak sürüm gelir. Yerel kopya önce kurtarma kopyası olarak saklanır (en çok {MAX_PLANNING_RECOVERY_COPIES}; şu an {readPlanningRecoveryCopies(productionArea).length}). Eski kopyalar otomatik silinmez; Yerel kopyayı indir hepsini ve bu ekrandaki kopyayı tek dosyada verir.</span>{unsaved ? <><strong>Yerel değişikliği kaydet</strong><span>Kaydedilmemiş yerel kopyayı dayandığı ortak sürüme karşı kaydeder.</span></> : <><strong>Bu cihazı yayınla</strong><span>Ortak sürümün planlama girdilerinin üzerine bu ekrandaki planlama yazılır. Ortak üretim kayıtları sunucuda korunur; yerel üretim işlemleri yayınlanmaz.</span></>}</div><div className="drawer-actions"><button className="secondary" onClick={() => setPlanningSyncConflictState(null)}>Şimdilik kapat</button><button className="secondary" onClick={downloadLocalCopy}>Yerel kopyayı indir</button>{recoveryDownloadedCount !== null && recoveryDownloadedCount > 0 && <><label className="switch-label compact"><input type="checkbox" checked={recoveryExportConfirmed} onChange={(event) => setRecoveryExportConfirmed(event.target.checked)} /> İndirilen dosyanın ({recoveryDownloadedCount} kurtarma kopyası) bilgisayara kaydedildiğini ve açılabildiğini kontrol ettim</label><button className="secondary" disabled={!recoveryExportConfirmed} onClick={clearDownloadedRecoveryCopies}>İndirilen kurtarma kopyalarını sil</button></>}<button className="secondary" onClick={acceptRemotePlanningState}>Ortak veriyi yükle</button>{unsaved ? <button className="primary" onClick={() => void retryUnsavedLocalCopy()}>Yerel değişikliği kaydet</button> : <button className="primary" disabled={missing.length > 0} title={missing.length > 0 ? "Yerel üretim işlemleri yayınlamayla aktarılamaz" : undefined} onClick={() => void forceLocalPlanningStateSync()}>Bu cihazı yeni sürüm olarak yayınla</button>}</div></section></div>;
      })()}
      {productionPullConfirmOpen && <ProductionSyncReviewDialog preview={productionPullPreview} busy={productionPullStatus === "pulling"} error={productionPullError} onPreview={previewProductionState} onApply={pullProductionState} onClose={() => { productionPreviewRequestRef.current += 1; setProductionPullConfirmOpen(false); setProductionPullPreview(null); }} />}
      <ProductTour open={tourOpen} onClose={() => setTourOpen(false)} onNavigate={changeView} canManageSettings={isAdmin} />
      <RaviChat view={view} onNavigate={navigateFromRavi} />
    {identityReviewOpen && <TurningIdentityReviewDialog seed={seed} synced={planningSyncStatus === "synced"} onClose={() => setIdentityReviewOpen(false)} onResolve={resolveIdentity} />}
    </main></IdentityReviewActionContext.Provider></RaviContextProvider>
  );
}

frontend/features/planning/ProductionSyn.source:
"use client";

import { useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { buildProductionSyncApply, type ProductionSyncPreview } from "./production-sync-review";
import { formatFactoryDateTime } from "./shared/format";

const choiceLabels: Record<string, string> = {
  "keep-local": "Staging kayıtlarını koru",
  "use-source": "Üretim kayıtlarını kullan",
  combine: "Notları ve olayları birleştir",
};
const statusLabels: Record<string, string> = {
  same: "İki ortam aynı", "source-changed": "Üretimde değişti", "local-changed": "Staging’de değişti",
  "both-changed": "İki ortamda da değişti · seçim gerekli", "no-baseline": "Önceki ortak kopya yok · seçim gerekli",
};
const fieldLabels: Record<string, string> = {
  machines: "Torna tezgâhları", productionHistory: "Üretim arşivi", wipLots: "Yarı mamul", wipMovements: "Üretim hareketleri",
  productionInterruptions: "Üretim araları", productionCancellations: "Kalan üretim iptalleri", processCurrentJobs: "Çalışan proses işleri",
  manualBatches: "Kaydedilmiş plan şarjları", savedBatches: "Kayıtlı şarjlar", processOperationOverrides: "Proses yerleşimleri",
  activePlanRun: "Etkin plan çalışması", lastAutomaticPlan: "Son otomatik plan", planRunSequence: "Plan sıra numarası",
  planNeedsRecalculation: "Yeniden hesaplama durumu", scenarioProvenance: "Planın senaryosu", orders: "Siparişler", customerDemand: "Müşteri talebi",
  customerOrderOverrides: "Sipariş düzeltmeleri", orderImport: "Sipariş dosyası bilgileri", orderImportGrossOrders: "Dosyadan gelen siparişler",
  planningEvents: "Plan olayları", chargeJourneyNotes: "Şarj notları", products: "Torna parametreleri", preferences: "Tezgâh tercihleri",
  processMasterData: "Proses parametreleri", flowSettings: "Akış Ayarı", processWaitSettings: "Proses bekleme süreleri", setupSettings: "SETUP Süreleri",
  materialSettings: "Hammadde Bilgileri", adviceSettings: "Tavsiye ayarları", calendarEvents: "Takvim olayları", holidays: "Tatiller",
  calendar: "Çalışma takvimi", startDate: "Plan başlangıcı", endDate: "Plan sonu", planningStartDate: "Plan başlangıcı", planningEndDate: "Plan sonu",
  activePlanningScope: "Plan kapsamı", orderCatalog: "Sipariş kataloğu", orderCatalogName: "Sipariş kaynağı", productionArea: "Üretim alanı",
};
const settingLabel = (key: string) => fieldLabels[key] ?? "Diğer kayıtlı ayar";
function GroupSummary({ summary }: { summary: unknown }) {
  if (!summary || typeof summary !== "object") return <p>Kayıt sayısı bilgisi yok.</p>;
  const data = summary as { collections?: Record<string, { onlyLocal?: number; onlySource?: number; different?: number; changed?: boolean }>; currentJobMachines?: string[] };
  return <><table><thead><tr><th>Kayıtlar</th><th>Yalnız staging</th><th>Yalnız üretim</th><th>Farklı</th></tr></thead><tbody>{Object.entries(data.collections ?? {}).map(([key, counts]) => <tr key={key}><th>{settingLabel(key)}</th><td>{counts.changed ? "—" : counts.onlyLocal ?? 0}</td><td>{counts.changed ? "—" : counts.onlySource ?? 0}</td><td>{counts.changed ? "Değişti" : counts.different ?? 0}</td></tr>)}</tbody></table>{!Object.keys(data.collections ?? {}).length && <p>Kayıt farkı yok.</p>}{Boolean(data.currentJobMachines?.length) && <p>Çalışan işi farklı olan tezgâhlar: {data.currentJobMachines!.join(", ")}</p>}</>;
}
export function ProductionSyncReviewDialog({ preview, busy, error, onPreview, onApply, onClose }: {
  preview: ProductionSyncPreview | null; busy: boolean; error: string;
  onPreview: () => Promise<void>;
  onApply: (request: ReturnType<typeof buildProductionSyncApply>) => Promise<void>;
  onClose: () => void;
}) {
  const [selected, setSelected] = useState<Record<string, string>>({});
  const [choiceError, setChoiceError] = useState("");
  const complete = preview && preview.groups.every(group => group.allowedChoices.includes((selected[group.id] ?? group.defaultChoice) as never));
  useRaviScreenContext("production-sync-review", { location: "Prod’dan güncelle", source: "production-read-only", target: "staging", preview, selected, busy, error: error || choiceError });
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog production-pull-dialog" role="dialog" aria-modal="true" aria-label="Üretim verilerini staging'e alma incelemesi">
    <div className="operational-dialog-head"><div><span>STAGING VERİ YENİLEME</span><h2>Üretim ve staging kayıtlarını inceleyin</h2><p>Üretim yalnızca okunur. Seçimler staging’e uygulanır. Önceki staging kaydı sunucuda kurtarma için saklanır.</p></div><button className="delete-button" disabled={busy} onClick={onClose} aria-label="Üretim verisi incelemesini kapat">×</button></div>
    {preview ? <>
      <p>Üretim sürümü: {formatFactoryDateTime(preview.sourceUpdatedAt)} · Staging sürümü: {formatFactoryDateTime(preview.localUpdatedAt)}</p>
      <div className="production-sync-groups">{preview.groups.map(group => <fieldset key={group.id} disabled={busy}>
        <legend>{group.label}</legend><p>{statusLabels[group.status] ?? group.status}</p>
        <details><summary>Kayıt farkları</summary><GroupSummary summary={group.summary} /></details>
        {group.id === "physical" && <p>Çalışan işler, üretim geçmişi, yarı mamul, teslimatlar ve plan birlikte seçilir. Tek tek alanlar birleştirilmez.</p>}
        <label>{group.label} için kullanılacak kayıtlar<select value={selected[group.id] ?? group.defaultChoice ?? ""} onChange={event => { setSelected(current => ({ ...current, [group.id]: event.target.value })); setChoiceError(""); }}>
          <option value="" disabled>Bir seçim yapın</option>{group.allowedChoices.map(choice => <option key={choice} value={choice}>{choiceLabels[choice]}</option>)}
        </select></label>
      </fieldset>)}</div>
      <details><summary>Parametreler ve senaryolar</summary><p>Staging’den korunacak ayarlar: {preview.settingsKeys.keptLocal.map(settingLabel).join(", ") || "Yok"}</p><p>Üretimden alınacak ayarlar: {preview.settingsKeys.fromSource.map(settingLabel).join(", ") || "Yok"}</p><p>İki ortamda da değişen ayarlar: {preview.settingsKeys.bothChanged.map(settingLabel).join(", ") || "Yok"}</p><p>Yerelde değişen parametre korunur. Kaynaktaki {preview.scenarios.sourceCount} senaryodan {preview.scenarios.newIds.length} yeni kayıt eklenir. Mevcut staging senaryoları silinmez.</p></details>
    </> : <p>Önizleme ile kayıt farklarını alın. Henüz staging kaydı değiştirilmedi.</p>}
    {(error || choiceError) && <p className="form-error" role="alert">{error || choiceError}</p>}
    <div className="drawer-actions"><button className="secondary" disabled={busy} onClick={onClose}>Vazgeç</button><button className="secondary" disabled={busy} onClick={() => { setSelected({}); setChoiceError(""); void onPreview(); }}>{busy ? "İşlem sürüyor…" : "Önizlemeyi yenile"}</button><button className="primary" disabled={busy || !complete} onClick={() => { if (preview) try { void onApply(buildProductionSyncApply(preview, selected)); } catch (reason) { setChoiceError(reason instanceof Error ? reason.message : "Seçimleri kontrol edin."); } }}>İncelenen seçimleri staging’e uygula</button></div>
  </section></div>;
}

frontend/features/planning/advice/Piston.source:
"use client";

import { useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import type { DeactivationImpact } from "@/lib/parameter-deactivation";
import type { ProductionCancellation, ProductionCancellationReviewStatus } from "@/lib/production-cancellation";

export function pistonReviewContext(conflicts: DeactivationImpact[], cancellations: ProductionCancellation[], selectedId: string, error: string) {
  const pending = cancellations.filter(item => item.review.status === "pending");
  return { selectedId, error: error.slice(0, 500), pendingReviewCount: pending.length, inactiveAssignmentCount: conflicts.length,
    contextRecordLimit: 20,
    cancellationReviews: pending.slice(0, 20).map(item => ({ id: item.id, product: item.product, chargeId: item.chargeId,
      status: item.review.status, cancelledQuantity: item.cancelledQuantity })),
    inactiveAssignments: conflicts.slice(0, 20).map(item => ({ target: item.target, queuedCount: item.queued.length,
      jobs: item.queued.slice(0, 20).map(job => job.key) })) };
}

export function runPistonReviewAction(action: () => void): string {
  try { action(); return ""; }
  catch (cause) { return cause instanceof Error ? cause.message : "İnceleme kaydedilemedi."; }
}

export function PistonReviewPanel({ conflicts, cancellations, onResolveAssignment, onReviewCancellation }: {
  conflicts: DeactivationImpact[];
  cancellations: ProductionCancellation[];
  onResolveAssignment: (impact: DeactivationImpact) => void;
  onReviewCancellation: (id: string, decision: Exclude<ProductionCancellationReviewStatus, "pending">) => void;
}) {
  const [error, setError] = useState("");
  const [selectedId, setSelectedId] = useState("");
  const pending = cancellations.filter(item => item.review.status === "pending");
  useRaviScreenContext("piston-operational-reviews", pistonReviewContext(conflicts, pending, selectedId, error));
  function review(id: string, decision: Exclude<ProductionCancellationReviewStatus, "pending">) {
    setSelectedId(id);
    setError(runPistonReviewAction(() => onReviewCancellation(id, decision)));
  }
  return <>
    {conflicts.map(impact => <article className="advice-item" key={`${impact.target.process}:${impact.target.product}:${impact.target.resourceId}`}>
      <h3>Pasif atamada bekleyen işler</h3><p>{impact.target.product} · {impact.target.resourceId} · {impact.queued.length} bekleyen iş</p>
      <p>Çalışan işler korunur. Her bekleyen iş için bir işlem seçin.</p>
      <button onClick={() => { setSelectedId(`${impact.target.process}:${impact.target.product}:${impact.target.resourceId}`); setError(runPistonReviewAction(() => onResolveAssignment(impact))); }}>Etkilenen işleri incele</button>
    </article>)}
    {pending.map(item => <article className="advice-item" key={item.id}>
      <h3>İptal sonrası inceleme</h3><strong>{item.product} · {item.workOrder || item.chargeId}</strong>
      <p>{item.completedQuantity.toLocaleString("tr-TR")} üretilen · {item.cancelledQuantity.toLocaleString("tr-TR")} iptal edilen adet</p>
      <p>{item.reason}</p><p>Müşteri siparişi değişmedi. Bu talep için yeniden üretim kararınızı bekliyor.</p>
      <p>Bu karar Geri al ile değiştirilemez. Önceki geri alma geçmişi temizlenir.</p>
      <button onClick={() => review(item.id, "replacement-approved")}>Yeniden üretime izin ver</button>{" "}
      <button onClick={() => review(item.id, "replacement-declined")}>Yeniden üretme</button>
    </article>)}
    {error && <p className="form-error" role="alert">{error}</p>}
  </>;
}

frontend/features/planning/advice/Recomm.source:
"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { formatInteger as formatNumber } from "@/lib/number-format";
import { type PlanningAdvice } from "@/lib/planning-advice";
import { CaretDown, CaretRight, CheckCircle, Lightbulb, Lock, Plus, Warning, Wrench, X } from "@phosphor-icons/react";
import { useEffect, useState } from "react";

export function RecommendationCenter({ reviewPanel, reviewCount = 0, advice, allAdviceCount, dismissedCount, focusedOrderId, focusedMachineId, focusedProduct, currentPlan, onClose, onShowAll, onApply, onDismiss, onRestoreDismissed, onManual }: { reviewPanel?: React.ReactNode; reviewCount?: number; advice: PlanningAdvice[]; allAdviceCount: number; dismissedCount: number; focusedOrderId: string | null; focusedMachineId: string | null; focusedProduct: string; currentPlan: boolean; onClose: () => void; onShowAll: () => void; onApply: (item: PlanningAdvice) => void; onDismiss: (id: string) => void; onRestoreDismissed: () => void; onManual: (product: string) => void }) {
  const [kindFilter, setKindFilter] = useState<"all" | PlanningAdvice["kind"]>("all");
  useRaviScreenContext("advice", { kindFilter, focusedOrderId, focusedMachineId, focusedProduct, currentPlan,
    allAdviceCount, dismissedCount, recommendations: advice.slice(0, 8).map(({ id, title, detail, kind }) => ({ id, title, detail, kind })) });
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [onClose]);
  const scopeAdvice = focusedOrderId
    ? advice.filter((item) => item.orderId === focusedOrderId)
    : focusedMachineId
      ? advice.filter((item) => item.machineId === focusedMachineId)
      : advice;
  const visible = kindFilter === "all" ? scopeAdvice : scopeAdvice.filter((item) => item.kind === kindFilter);
  const kindLabel = (kind: PlanningAdvice["kind"]) => kind === "interrupted" ? "YARIM KALAN İŞ" : kind === "move" ? "TEZGAH DEĞİŞİKLİĞİ" : kind === "overtime" ? "MESAİ" : kind === "pull-forward" ? "GELECEK HAFTADAN" : "EK ŞARJ";
  const heading = focusedProduct ? `${focusedProduct} tavsiyeleri` : focusedMachineId ? `${focusedMachineId} tezgah tavsiyeleri` : "Uygulanabilir tavsiyeler";
  return <div className="advice-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="advice-drawer" role="dialog" aria-modal="true" aria-label="Planlama tavsiyeleri"><header><div className="advice-title-icon"><Lightbulb size={19} weight="fill" /></div><div><span>PLANLAMA ASİSTANI</span><h2>{heading}</h2><p>Yarım işler tamamlanana kadar hatırlatılır. Planlama önerileri mevcut plan üzerinde ölçülebilir faydaya göre gösterilir.</p></div><button className="delete-button" onClick={onClose} aria-label="Tavsiyeleri kapat"><X size={16} /></button></header><div className="advice-scope"><span><strong>{visible.length + reviewCount}</strong> açık tavsiye</span><label className="advice-kind-filter"><small>Tavsiye tipi</small><select value={kindFilter} onChange={(event) => setKindFilter(event.target.value as "all" | PlanningAdvice["kind"])}><option value="all">Tüm tipler</option><option value="interrupted">Yarım kalan işler</option><option value="move">Tezgah değişikliği</option><option value="add-charge">Ek şarj</option><option value="pull-forward">Gelecek haftadan</option><option value="overtime">Mesai</option></select></label>{(focusedOrderId || focusedMachineId) && <button onClick={onShowAll}>Tüm tavsiyeleri göster</button>}{dismissedCount > 0 && <button onClick={onRestoreDismissed}>{dismissedCount} göz ardı edileni geri getir</button>}</div><div className="advice-list">{reviewPanel}{reviewCount > 0 && !visible.length ? null : !currentPlan && !visible.length ? <div className="advice-empty"><Lightbulb size={25} /><strong>Güncel plan gerekli</strong><span>Tavsiyeleri hesaplamak için planı çalıştırın.</span></div> : visible.length ? visible.map((item) => <RecommendationAdviceCard key={item.id} item={item} kindLabel={kindLabel} onApply={onApply} onDismiss={onDismiss} />) : <div className="advice-empty"><CheckCircle size={25} weight="fill" /><strong>{scopeAdvice.length && kindFilter !== "all" ? "Bu tavsiye tipinde kayıt yok" : focusedProduct ? "Bu sipariş için açık tavsiye yok" : focusedMachineId ? `${focusedMachineId} için açık tavsiye yok` : "Açık tavsiye yok"}</strong><span>{scopeAdvice.length && kindFilter !== "all" ? "Başka bir tavsiye tipi seçin veya tüm tipleri gösterin." : allAdviceCount && dismissedCount ? "Tavsiyeler göz ardı edilmiş olabilir; üstteki geri getirme bağlantısını kullanabilirsiniz." : "Mevcut plan için ek şarj, taşıma, gelecek haftadan iş çekme veya mesai müdahalesi gerekmiyor."}</span>{scopeAdvice.length && kindFilter !== "all" ? <button className="secondary" onClick={() => setKindFilter("all")}>Tüm tipleri göster</button> : focusedProduct && <button className="secondary" onClick={() => onManual(focusedProduct)}><Plus size={14} /> Yine de manuel şarj aç</button>}</div>}</div>{focusedProduct && currentPlan && visible.length > 0 && <div className="advice-manual-fallback"><span><strong>Farklı bir çözüm mü gerekiyor?</strong><small>Tezgahı ve miktarı kendiniz seçerek manuel şarj açabilirsiniz.</small></span><button onClick={() => onManual(focusedProduct)}><Plus size={13} /> Manuel şarj</button></div>}</aside></div>;
}

function RecommendationAdviceCard({ item, kindLabel, onApply, onDismiss }: { item: PlanningAdvice; kindLabel: (kind: PlanningAdvice["kind"]) => string; onApply: (item: PlanningAdvice) => void; onDismiss: (id: string) => void }) {
  const addAction = item.action.type === "add-charge" ? item.action : null;
  const [pickerOpen, setPickerOpen] = useState(false);
  const [machineId, setMachineId] = useState(addAction?.machineId ?? "");
  const initialMachine = addAction?.machineOptions.find((option) => option.machineId === addAction.machineId);
  const [position, setPosition] = useState(addAction?.position ?? initialMachine?.queueLength ?? 0);
  const selectedMachine = addAction?.machineOptions.find((option) => option.machineId === machineId) ?? initialMachine;
  const allowedPositions = selectedMachine
    ? Array.from({ length: selectedMachine.queueLength - selectedMachine.lockedCount + 1 }, (_, index) => selectedMachine.lockedCount + index)
    : [];
  const selectedMachineId = selectedMachine?.machineId ?? item.machineId;

  useEffect(() => {
    if (selectedMachine && (position < selectedMachine.lockedCount || position > selectedMachine.queueLength)) setPosition(selectedMachine.queueLength);
  }, [position, selectedMachine?.lockedCount, selectedMachine?.queueLength]);

  function chooseMachine(nextMachineId: string) {
    const nextMachine = addAction?.machineOptions.find((option) => option.machineId === nextMachineId);
    setMachineId(nextMachineId);
    setPosition(nextMachine?.queueLength ?? 0);
  }

  function applySelected() {
    if (!addAction || !selectedMachine) {
      onApply(item);
      return;
    }
    onApply({
      ...item,
      machineId: selectedMachine.machineId,
      action: { ...addAction, machineId: selectedMachine.machineId, position },
    });
  }

  return <article className={`advice-item ${item.kind}`}>
    <div className="advice-item-head"><span>{kindLabel(item.kind)}{selectedMachineId ? ` · ${selectedMachineId}` : ""}</span><strong>{item.title}</strong></div>
    <p>{item.detail}</p>
    <div className="advice-benefit"><CheckCircle size={14} weight="fill" /><span>{item.benefit}</span></div>
    {addAction && pickerOpen && <div className="advice-machine-picker">
      <div className="advice-machine-picker-head"><span><strong>Parametrelerde izin verilen tezgahlar</strong><small>Tezgahı ve şarjın kuyrukta ekleneceği sırayı seçin.</small></span><b>{addAction.machineOptions.length} seçenek</b></div>
      <div className="advice-machine-options">{addAction.machineOptions.map((option) => {
        const hasMatchingJob = option.matchingPositions.length > 0;
        return <button key={option.machineId} className={option.machineId === selectedMachine?.machineId ? "selected" : ""} onClick={() => chooseMachine(option.machineId)} aria-pressed={option.machineId === selectedMachine?.machineId}>
          <span><strong>{option.machineId}</strong><small>{option.machineName}</small></span>
          <span className={hasMatchingJob ? "queue-match" : "queue-empty"}>{hasMatchingJob ? <CheckCircle size={12} weight="fill" /> : null}<small>{hasMatchingJob ? `Bu iş kuyrukta · ${option.matchingPositions.map((index) => `${index + 1}.`).join(", ")} sıra` : "Bu iş kuyrukta yok"}</small></span>
          <em>{option.queueLength}/14 şarj</em>
        </button>;
      })}</div>
      {selectedMachine && <label className="advice-position-picker"><span><small>Eklenecek sıra</small><strong>{selectedMachine.machineId} iş kuyruğu</strong></span><select value={position} onChange={(event) => setPosition(Number(event.target.value))}>{allowedPositions.map((queuePosition) => <option key={queuePosition} value={queuePosition}>{adviceQueuePositionLabel(selectedMachine.queue, queuePosition)}</option>)}</select></label>}
      {selectedMachine && selectedMachine.lockedCount > 0 && <p className="advice-locked-note"><Lock size={12} /> İlk {selectedMachine.lockedCount} şarj kilitli olduğu için yeni iş bunların arkasına eklenebilir.</p>}
    </div>}
    <footer>
      {item.kind !== "interrupted" && <button className="advice-dismiss" onClick={() => onDismiss(item.id)}>Göz ardı et</button>}
      {addAction && <button className={`advice-machine-toggle ${pickerOpen ? "open" : ""}`} onClick={() => setPickerOpen((open) => !open)} aria-expanded={pickerOpen}><Wrench size={13} /> Tezgah seç <CaretDown size={11} /></button>}
      <button className="advice-apply" onClick={applySelected}>{item.actionLabel}<CaretRight size={13} /></button>
    </footer>
  </article>;
}

function adviceQueuePositionLabel(queue: Array<{ product: string }>, position: number): string {
  if (position >= queue.length) return `${position + 1}. sıra · Kuyruk sonu`;
  return `${position + 1}. sıra · ${queue[position].product} öncesi`;
}

frontend/features/planning/advice/StaleC.source:
"use client";

import { useState } from "react";
import type { PlanningSeed } from "@/lib/planning";
import { buildStaleChargeAdvice, staleChargeDays, validateAdviceSettings } from "@/lib/stale-charges";
import { useRaviScreenContext } from "@/features/ravi/context";

const PAGE_SIZE = 30;

export function parseStaleChargeThreshold(value: string): number {
  return validateAdviceSettings({ version: 1, staleChargeDays: Number(value) }).staleChargeDays;
}

export function StaleChargePanel({ seed, onSaveThreshold, onInspect }: {
  seed: PlanningSeed;
  onSaveThreshold: (days: number) => void;
  onInspect: (chargeId: string) => void;
}) {
  const threshold = staleChargeDays(seed);
  const [baseline, setBaseline] = useState(threshold);
  const [draft, setDraft] = useState(String(threshold));
  const [error, setError] = useState("");
  const [selectedChargeId, setSelectedChargeId] = useState<string | null>(null);
  const [page, setPage] = useState(0);
  const rows = buildStaleChargeAdvice(seed);
  const lastPage = Math.max(0, Math.ceil(rows.length / PAGE_SIZE) - 1);
  const visiblePage = Math.min(page, lastPage);
  const visible = rows.slice(visiblePage * PAGE_SIZE, (visiblePage + 1) * PAGE_SIZE);
  const stale = baseline !== threshold;
  useRaviScreenContext("stale-charges", {
    thresholdDays: threshold, draftThresholdDays: draft, stale, error, selectedChargeId,
    count: rows.length, page: visiblePage + 1,
    visibleRows: visible.map(row => ({ lotId: row.action.lotId, chargeId: row.action.chargeId, product: row.product, title: row.title, detail: row.detail, unknownAge: row.action.idleDays === undefined, lastMovementAt: row.action.lastMovementAt, idleDays: row.action.idleDays })),
  });
  function save() {
    try {
      if (stale) throw new Error("Kayıtlı eşik değişti. Güncel eşiği yükleyin.");
      const days = parseStaleChargeThreshold(draft);
      onSaveThreshold(days);
      setBaseline(days); setDraft(String(days)); setError("");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Hareketsiz şarj eşiği kaydedilemedi."); }
  }
  return <section className="stale-charge-panel" aria-labelledby="stale-charge-title">
    <h3 id="stale-charge-title">Hareketsiz şarjlar <span>({rows.length})</span></h3>
    <p>Kayıtlı üretim hareketi olmayan şarjları fiziksel olarak kontrol edin. Notlar ve parametre değişiklikleri üretim hareketi sayılmaz.</p>
    <label>Hareketsiz şarj eşiği (gün)<input type="number" min="1" max="365" step="1" value={draft} onChange={event => { setDraft(event.target.value); setError(""); }} /></label>{" "}
    <button disabled={stale || draft === String(threshold)} onClick={save}>Eşiği kaydet</button>
    {stale && <p role="status">Kayıtlı eşik değişti. Güncel eşiği yükleyin.</p>}
    {stale && <button onClick={() => { setDraft(String(threshold)); setBaseline(threshold); setError(""); }}>Güncel eşiği yükle</button>}
    {error && <p role="alert">{error}</p>}
    <p>Kayıtlı eşik: {threshold} gün. Kaydedilmemiş değer listeyi değiştirmez.</p>
    {visible.length ? visible.map(row => <article className="advice-item stale-charge" key={row.id}>
      <div className="advice-item-head"><strong>{row.title}</strong></div><p>{row.detail}</p><p>{row.benefit}</p>
      <footer><button className="advice-apply" onClick={() => { setSelectedChargeId(row.action.chargeId); onInspect(row.action.chargeId); }}>{row.actionLabel}</button></footer>
    </article>) : <p>Bu eşikte incelenecek hareketsiz şarj yok.</p>}
    {lastPage > 0 && <nav aria-label="Hareketsiz şarj sayfaları"><button disabled={visiblePage === 0} onClick={() => setPage(visiblePage - 1)}>Önceki</button><span> {visiblePage + 1} / {lastPage + 1} </span><button disabled={visiblePage === lastPage} onClick={() => setPage(visiblePage + 1)}>Sonraki</button></nav>}
  </section>;
}

frontend/features/planning/archive/Produ.source:
"use client";
import { productionProcessOrder } from "@/lib/process-master-data";

import { DeliveryAllocationForm } from "@/components/DeliveryAllocationForm";

import { archiveEntrySignature } from "@/lib/archive-corrections";
import { productionHistoryLots, type ArchiveFocus } from "@/lib/production-archive";
import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { Field, SetupFamilyBadge } from "@/features/planning/shared/controls";
import { formatInputDate, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { useApiFetch } from "@/lib/api";
import { factoryDateInput, factoryDateTimeInput } from "@/lib/factory-time";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  formatExcelDate,
  type PlanningSeed,
  type ProductionHistoryAllocationInput,
  type ProductionHistoryEntry,
  type ProductionInventoryStatus,
  productSetupFamily,
} from "@/lib/planning";
import { type ProcessKind, processLabel } from "@/lib/process-master-data";
import {
  productionArchiveDateLabel,
  productionArchiveEventDate,
  productionArchiveEventSerial,
  productionArchiveProcessSnapshot,
} from "@/lib/production-archive";
import { type ProductSetupFamily, productSetupFamilyLabel } from "@/lib/setup-families";
import { wipStageLabel } from "@/lib/wip-ledger";
import {
  Archive,
  ArrowCounterClockwise,
  CheckCircle,
  FileXls,
  FloppyDisk,
  MagnifyingGlass,
  PencilSimple,
  Trash,
  Warning,
  X,
} from "@phosphor-icons/react";
import { useEffect, useState } from "react";
import { productionProcessLabel } from "../shared/production";

function deliveryDateDraft(entry: ProductionHistoryEntry): string {
  const value = entry.deliveredAtTime || (entry.deliveredAt ? `${entry.deliveredAt}T00:00:00+03:00` : "");
  return value && Number.isFinite(Date.parse(value)) ? factoryDateTimeInput(value) : "";
}

export type { ArchiveFocus } from "@/lib/production-archive";
type ArchiveProps = {
  seed: PlanningSeed; focus?: ArchiveFocus; onClose: () => void;
  onStatusChange: (entryId: string, status: ProductionInventoryStatus, actionDate?: string, reason?: string) => void;
  onEdit: (entryId: string, actualQuantity: number, completedAt: number, deliveryDate?: string, expected?: string, correctionLotId?: string) => boolean;
  onAllocate: (entryId: string, input: ProductionHistoryAllocationInput, expected?: string, correctionLotId?: string) => boolean;
  onRestoreDelivery: (entryId: string, reason: string, expected?: string) => boolean;
};
export function ProductionArchiveDrawer({ seed, focus, onClose, onStatusChange, onEdit, onAllocate, onRestoreDelivery }: ArchiveProps) {
  const initialEntry = focus?.entryIds.length === 1 ? seed.productionHistory?.find(entry => entry.id === focus.entryIds[0]) ?? null : null;
  const [focusedIds, setFocusedIds] = useState(focus?.entryIds);
  const [correctionLotId, setCorrectionLotId] = useState("");
  const [actionError, setActionError] = useState("");
  function attempt(action: () => void) { try { setActionError(""); action(); } catch (error) { setActionError(error instanceof Error ? error.message : "İşlem kaydedilemedi."); } }
  const apiFetch = useApiFetch();
  const entries = (seed.productionHistory ?? []).filter((entry) => entry.inventoryStatus !== "voided");
  const [activeStatus, setActiveStatus] = useState<Exclude<ProductionInventoryStatus, "voided">>(focus ? "delivered" : "semi-finished");
  const [query, setQuery] = useState("");
  const [machineId, setMachineId] = useState("");
  const [product, setProduct] = useState("");
  const [familyFilter, setFamilyFilter] = useState<ProductSetupFamily | "">("");
  const [operationFilter, setOperationFilter] = useState<ProductionHistoryEntry["process"] | "">("");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [deliveryEntry, setDeliveryEntry] = useState<ProductionHistoryEntry | null>(null);
  const [deliveryDraft, setDeliveryDraft] = useState({ actualQuantity: 0, completedDate: "", deliveredQuantity: 0, deliveryDate: factoryDateTimeInput(), remainderAction: "keep" as "keep" | "scrap" });
  const [confirmedDeliveryBuffer, setConfirmedDeliveryBuffer] = useState(false);
  const [editEntry, setEditEntry] = useState<ProductionHistoryEntry | null>(focus?.action === "edit" ? initialEntry : null);
  const [editDraft, setEditDraft] = useState(() => ({ actualQuantity: initialEntry?.completedQuantity ?? 0, completedDate: initialEntry ? serialToInputDate(initialEntry.completedAt) : "", deliveryDate: initialEntry?.inventoryStatus === "delivered" ? deliveryDateDraft(initialEntry) : "" }));
  const [voidEntry, setVoidEntry] = useState<ProductionHistoryEntry | null>(null);
  const [restoreEntry, setRestoreEntry] = useState<ProductionHistoryEntry | null>(focus?.action === "restore" ? initialEntry : null);
  const [restoreReason, setRestoreReason] = useState("");
  const [restoreDate, setRestoreDate] = useState(factoryDateInput());
  const [exporting, setExporting] = useState(false);
  useRaviScreenContext("archive", { activeStatus, query, machineId, product, familyFilter, operationFilter, start, end,
    deliveryEntry, editEntry, voidEntry, restoreEntry, focusedIds, deliveryDraft, confirmedDeliveryBuffer, editDraft, restoreReason, restoreDate, actionError, correctionLotId });
  const [exportError, setExportError] = useState("");
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      if (voidEntry) setVoidEntry(null);
      else if (restoreEntry) setRestoreEntry(null);
      else if (editEntry) setEditEntry(null);
      else if (deliveryEntry) setDeliveryEntry(null);
      else onClose();
    };
    window.addEventListener("keydown", closeOnEscape);
    return () => window.removeEventListener("keydown", closeOnEscape);
  }, [deliveryEntry, editEntry, onClose, restoreEntry, voidEntry]);
  const archiveToday = inputDateToSerial(factoryDateInput()) + 1;
  const wipContextByEntryId = new Map(entries.map((entry) => {
    const lots = productionHistoryLots(seed, entry).filter(lot => lot.availableQuantity > 0);
    const snapshot = productionArchiveProcessSnapshot(seed, entry, archiveToday);
    const stages = [...new Set(lots.map((lot) => wipStageLabel(lot.stage, lot.readyAt < archiveToday, seed.productionArea)))];
    const currentOperation = snapshot.currentAssignments.map((assignment) => `${processLabel(assignment.process)} · ${assignment.resourceId}`).join(" · ");
    const nextOperation = snapshot.nextProcesses.map((process) => processLabel(process)).join(" · ");
    return [entry.id, {
      stage: stages.join(" · ") || (entry.inventoryStatus === "semi-finished" ? "Yarı mamül · konum kaydı yok" : ""),
      latestCompletedProcess: snapshot.latestCompletedProcess,
      currentOperation,
      nextOperation,
      operationCodes: [...new Set([snapshot.latestCompletedProcess, ...snapshot.currentProcesses, ...snapshot.nextProcesses])],
      lotIds: snapshot.lotIds,
      availableQuantity: snapshot.availableQuantity,
      deliveryReadyQuantity: snapshot.deliveryReadyQuantity,
    }] as const;
  }));
  const machineOptions = [...new Set(entries.map((entry) => entry.machineId))].sort((left, right) => left.localeCompare(right, "tr", { numeric: true }));
  const productOptions = [...new Set(entries.map((entry) => entry.product))].sort((left, right) => left.localeCompare(right));
  const startSerial = inputDateToSerial(start);
  const endSerial = inputDateToSerial(end);
  const normalizedQuery = query.trim().toLocaleLowerCase("tr-TR");
  const filteredEntries = (status: Exclude<ProductionInventoryStatus, "voided">) => entries
    .filter((entry) => (entry.inventoryStatus ?? "semi-finished") === status)
    .filter((entry) => !focusedIds || focusedIds.includes(entry.id))
    .filter((entry) => !machineId || entry.machineId === machineId)
    .filter((entry) => !product || entry.product === product)
    .filter((entry) => !familyFilter || productSetupFamily(seed, entry.product) === familyFilter)
    .filter((entry) => !operationFilter || entry.process === operationFilter || wipContextByEntryId.get(entry.id)?.operationCodes.includes(operationFilter as Exclude<ProcessKind, "turning">))
    .filter((entry) => !startSerial || productionArchiveEventSerial(entry, status) >= startSerial)
    .filter((entry) => !endSerial || productionArchiveEventSerial(entry, status) <= endSerial)
    .filter((entry) => !normalizedQuery || `${entry.id} ${entry.sourceEntryId ?? ""} ${entry.product} ${productSetupFamilyLabel(productSetupFamily(seed, entry.product))} ${entry.workOrder} ${entry.machineId} ${entry.machineName} ${productionProcessLabel(entry.process)} ${wipContextByEntryId.get(entry.id)?.lotIds.join(" ") ?? ""} ${wipContextByEntryId.get(entry.id)?.stage ?? ""} ${wipContextByEntryId.get(entry.id)?.currentOperation ?? ""} ${wipContextByEntryId.get(entry.id)?.nextOperation ?? ""}`.toLocaleLowerCase("tr-TR").includes(normalizedQuery))
    .sort((left, right) => productionArchiveEventSerial(right, status) - productionArchiveEventSerial(left, status) || right.archivedAt.localeCompare(left.archivedAt));
  const statusEntries = entries.filter((entry) => (entry.inventoryStatus ?? "semi-finished") === activeStatus);
  const visible = filteredEntries(activeStatus);
  const totalQuantity = visible.reduce((sum, entry) => sum + (activeStatus === "semi-finished" ? wipContextByEntryId.get(entry.id)?.availableQuantity ?? entry.completedQuantity : entry.completedQuantity), 0);
  const visibleMachineCount = new Set(visible.map((entry) => entry.machineId)).size;
  const filtered = Boolean(focusedIds || query || machineId || product || familyFilter || operationFilter || start || end);
  const statusCount = (status: Exclude<ProductionInventoryStatus, "voided">) => entries.filter((entry) => (entry.inventoryStatus ?? "semi-finished") === status).length;

  function clearFilters() {
    setFocusedIds(undefined);
    setQuery("");
    setMachineId("");
    setProduct("");
    setFamilyFilter("");
    setOperationFilter("");
    setStart("");
    setEnd("");
  }

  function openDelivery(entry: ProductionHistoryEntry) {
    setCorrectionLotId("");
    setActionError("");
    setDeliveryDraft({ actualQuantity: entry.completedQuantity, completedDate: serialToInputDate(entry.completedAt), deliveredQuantity: Math.min(entry.completedQuantity, wipContextByEntryId.get(entry.id)?.deliveryReadyQuantity ?? 0), deliveryDate: factoryDateTimeInput(), remainderAction: "keep" });
    setConfirmedDeliveryBuffer(false); setDeliveryEntry(entry);
  }

  function openEdit(entry: ProductionHistoryEntry) {
    setCorrectionLotId("");
    setActionError("");
    setEditDraft({ actualQuantity: entry.completedQuantity, completedDate: serialToInputDate(entry.completedAt), deliveryDate: entry.inventoryStatus === "delivered" ? deliveryDateDraft(entry) : "" });
    setEditEntry(entry);
  }

  const correctionEntry = editEntry ?? deliveryEntry;
  const correctionLots = correctionEntry?.inventoryStatus === "semi-finished" ? productionHistoryLots(seed, correctionEntry).filter(lot => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped") : [];
  const lotChoice = correctionLots.length > 1 ? <Field label="Adet farkının uygulanacağı şarj"><select value={correctionLotId} onChange={event => setCorrectionLotId(event.target.value)}><option value="">Şarj seçin (yalnız adet değişiyorsa)</option>{correctionLots.map((lot, index) => <option key={lot.id} value={lot.id}>{index + 1}. parça · {wipStageLabel(lot.stage, false, seed.productionArea)} · {formatNumber(lot.availableQuantity)} adet</option>)}</select></Field> : null;

  async function exportArchive() {
    setExporting(true);
    setExportError("");
    try {
      const statuses: Array<Exclude<ProductionInventoryStatus, "voided">> = ["semi-finished", "delivered", "scrapped"];
      const sections = statuses.map((status) => {
        const rows = filteredEntries(status);
        return {
          status,
          eventDateLabel: productionArchiveDateLabel(status),
          totalAvailable: entries.filter((entry) => (entry.inventoryStatus ?? "semi-finished") === status).length,
          rows: rows.map((entry) => ({
            completedAt: productionArchiveEventDate(entry, status),
            archivedAt: entry.archivedAt,
            machineId: entry.machineId,
            machineName: entry.machineName,
            workOrder: entry.workOrder,
            product: entry.product,
            setupFamily: productSetupFamily(seed, entry.product) ?? "",
            process: wipContextByEntryId.get(entry.id)?.latestCompletedProcess ?? entry.process,
            stage: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.stage ?? "" : "",
            currentOperation: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.currentOperation ?? "" : "",
            nextOperation: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.nextOperation ?? "" : "",
            completedQuantity: entry.completedQuantity,
            availableQuantity: status === "semi-finished" ? wipContextByEntryId.get(entry.id)?.availableQuantity ?? entry.completedQuantity : entry.completedQuantity,
            plannedStart: serialToInputDate(entry.start),
            plannedEnd: serialToInputDate(entry.plannedEnd),
            deliveryDate: entry.deliveredAt ?? "",
          })),
        };
      });
      if (!sections.some((section) => section.rows.length)) throw new Error("Excel’e aktarılacak arşiv kaydı bulunamadı.");
      const payload = {
        generatedAt: new Date().toISOString(),
        filtered,
        sections,
      };
      const response = await apiFetch("/production-archive/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
      if (!response.ok) {
        const body = await response.json().catch(() => ({})) as { detail?: string };
        throw new Error(body.detail || "Üretim arşivi Excel’i oluşturulamadı.");
      }
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? `Uretim_Arsivi_${new Date().toISOString().slice(0, 10)}.xlsx`;
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (reason) {
      setExportError(reason instanceof Error ? reason.message : "Üretim arşivi Excel’i oluşturulamadı.");
    } finally {
      setExporting(false);
    }
  }

  return <div className="archive-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="archive-drawer" role="dialog" aria-modal="true" aria-label="Üretim arşivi">
    <header className="archive-head"><div><span>TAMAMLANAN ÜRETİMLER</span><h2>Üretim arşivi</h2><p>Yarı mamulün son tamamlanan, şu anda çalışan ve sıradaki prosesini teslimata kadar izleyin.</p></div><div className="archive-head-actions"><button className="archive-export" disabled={exporting || !entries.length} onClick={() => void exportArchive()}><FileXls size={15} /> {exporting ? "Hazırlanıyor…" : "WIP + teslim + ıskarta Excel"}</button><button onClick={onClose} aria-label="Üretim arşivini kapat"><X size={17} /></button></div></header>
    {focusedIds && <p className="archive-focus-note">Seçili şarjın teslimat kayıtları. {focusedIds.length > 1 ? "Düzenlemek veya geri almak istediğiniz teslimatı aşağıdan seçin." : "İşlem seçili teslimata uygulanır."}</p>}
    <div className="archive-status-tabs" role="tablist" aria-label="Üretim arşivi durumu"><button role="tab" aria-selected={activeStatus === "semi-finished"} className={activeStatus === "semi-finished" ? "selected" : ""} onClick={() => setActiveStatus("semi-finished")}><span>Yarı mamuller</span><b>{statusCount("semi-finished")}</b><small>Siparişlerde mevcut üretime dahil</small></button><button role="tab" aria-selected={activeStatus === "delivered"} className={activeStatus === "delivered" ? "selected" : ""} onClick={() => setActiveStatus("delivered")}><span>Teslim edilenler</span><b>{statusCount("delivered")}</b><small>Planlama hesabının dışında</small></button><button role="tab" aria-selected={activeStatus === "scrapped"} className={activeStatus === "scrapped" ? "selected" : ""} onClick={() => setActiveStatus("scrapped")}><span>Iskartalar</span><b>{statusCount("scrapped")}</b><small>Seçilebilir ve izlenebilir kayıp</small></button></div>
    {exportError && <div className="archive-export-error" role="alert"><Warning size={14} weight="fill" /><span>{exportError}</span><button onClick={() => setExportError("")}>Kapat</button></div>}
    <div className="archive-filters"><label className="archive-search"><MagnifyingGlass size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Şarj no, ürün, proses, aşama veya tezgah ara" /></label><Field label="Tezgah / istasyon"><select value={machineId} onChange={(event) => setMachineId(event.target.value)}><option value="">Tüm tezgahlar</option>{machineOptions.map((id) => <option key={id} value={id}>{id} · {entries.find((entry) => entry.machineId === id)?.machineName || "İsimsiz"}</option>)}</select></Field><Field label="Ürün"><select value={product} onChange={(event) => setProduct(event.target.value)}><option value="">Tüm ürünler</option>{productOptions.map((code) => <option key={code} value={code}>{code} · {productSetupFamilyLabel(productSetupFamily(seed, code))}</option>)}</select></Field><Field label="Ürün ailesi"><select value={familyFilter} onChange={(event) => setFamilyFilter(event.target.value as ProductSetupFamily | "")}><option value="">Tüm aileler</option>{seed.productionArea === "cubuk-filtre" ? <option value="cubuk-filtre">Çubuk Filtre</option> : <><option value="piston">Piston</option><option value="center-pin">Center Pin</option></>}</select></Field><Field label="Operasyon"><select value={operationFilter} onChange={(event) => setOperationFilter(event.target.value as ProductionHistoryEntry["process"] | "")}><option value="">Tüm operasyonlar</option>{productionProcessOrder(seed).map(p => <option key={p} value={p}>{processLabel(p)}</option>)}</select></Field><Field label="Başlangıç"><input type="date" value={start} onChange={(event) => setStart(event.target.value)} /></Field><Field label="Bitiş"><input type="date" min={start} value={end} onChange={(event) => setEnd(event.target.value)} /></Field>{filtered && <button className="archive-clear" onClick={clearFilters}><X size={13} /> Temizle</button>}</div>
    <div className="archive-summary"><span><small>{activeStatus === "semi-finished" ? "Yarı mamul iş" : activeStatus === "delivered" ? "Teslim edilen iş" : "Iskarta kaydı"}</small><strong>{formatNumber(visible.length)}</strong></span><span><small>{activeStatus === "semi-finished" ? "Toplam WIP" : activeStatus === "scrapped" ? "Toplam ıskarta" : "Toplam teslim"}</small><strong>{formatNumber(totalQuantity)} adet</strong></span><span><small>Tezgah</small><strong>{visibleMachineCount}</strong></span><em>{filtered ? `${formatNumber(statusEntries.length)} kaydın içinden filtrelendi` : activeStatus === "semi-finished" ? "Bu miktarlar siparişlerde “mevcut” sayılır" : activeStatus === "scrapped" ? "Bu miktarlar üretim kaybı olarak saklanır" : "Bu miktarlar yeni planı karşılamaz"}</em></div>
    <div className="archive-table"><table><thead><tr><th>{productionArchiveDateLabel(activeStatus)}</th><th>Tezgah</th><th>Şarj / iş emri</th><th>Ürün</th><th>Son tamamlanan</th><th>Güncel proses / aşama</th><th className="numeric">{activeStatus === "scrapped" ? "Iskarta" : activeStatus === "semi-finished" ? "WIP miktarı" : "Teslim edilen"}</th><th>Planlanan başlangıç</th><th>Planlanan bitiş</th><th>İşlem</th></tr></thead><tbody>{visible.map((entry) => { const context = wipContextByEntryId.get(entry.id); return <tr key={entry.id}><td><strong className="archive-key-date">{formatInputDate(productionArchiveEventDate(entry, activeStatus))}</strong>{activeStatus !== "semi-finished" && <small>Üretim {formatExcelDate(entry.completedAt)} tamamlandı</small>}<small>{new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short" }).format(new Date(entry.archivedAt))} arşivlendi</small>{entry.deliveredAt && <small className="archive-delivery-date">{entry.deliveredAtTime ? new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short", timeZone: "Europe/Istanbul" }).format(new Date(entry.deliveredAtTime)) : formatInputDate(entry.deliveredAt)} teslim</small>}{entry.statusChangeReason && <small>{entry.statusChangedBy || "Planlama oturumu"}: {entry.statusChangeReason}</small>}</td><td><b>{entry.machineId}</b><small>{entry.machineName}</small></td><td><strong className="tracking-number">{entry.workOrder || "—"}</strong></td><td><strong>{entry.product}</strong><SetupFamilyBadge family={productSetupFamily(seed, entry.product)} /></td><td><span className="archive-process"><ProcessIcon process={context?.latestCompletedProcess ?? entry.process} size={13} /> {productionProcessLabel(context?.latestCompletedProcess ?? entry.process)}</span></td><td>{activeStatus === "semi-finished" ? <><span className={`archive-wip-stage ${context?.currentOperation ? "running" : ""}`}>{context?.currentOperation || context?.stage || "Konum kaydı yok"}</span>{context?.currentOperation ? <small>Aşama: {context.stage}</small> : context?.nextOperation ? <small>Sıradaki: {context.nextOperation}</small> : null}</> : <span className="archive-wip-stage">—</span>}</td><td className="numeric"><strong className="archive-key-quantity">{formatNumber(activeStatus === "semi-finished" ? context?.availableQuantity ?? entry.completedQuantity : entry.completedQuantity)}</strong></td><td>{formatExcelDate(entry.start)}</td><td>{formatExcelDate(entry.plannedEnd)}</td><td><div className="archive-row-actions">{activeStatus === "semi-finished" ? <button className="archive-deliver"  title={(context?.deliveryReadyQuantity ?? 0) > 0 ? `${formatNumber(context?.deliveryReadyQuantity ?? 0)} adet teslimata hazır` : "Rota ve teslimat tamponu tamamlanmadı"} onClick={() => openDelivery(entry)}><CheckCircle size={13} /> Teslim / parçala</button> : <button className="archive-restore" onClick={() => { setActionError(""); setRestoreEntry(entry); setRestoreReason(""); setRestoreDate(factoryDateInput()); }}><ArrowCounterClockwise size={13} /> {activeStatus === "delivered" ? "Önceki aşamaya geri al" : "Yarı mamule geri al"}</button>}<button className="archive-edit" onClick={() => openEdit(entry)}><PencilSimple size={13} /> Adet / Teslimat</button><button className="archive-delete" onClick={() => { setActionError(""); setVoidEntry(entry); }}><Trash size={13} /> Kaydı sil</button></div></td></tr>; })}</tbody></table>{visible.length === 0 && <div className="archive-empty"><Archive size={28} /><strong>{statusEntries.length ? "Bu filtrelerle kayıt bulunamadı" : activeStatus === "semi-finished" ? "Bekleyen yarı mamul yok" : activeStatus === "scrapped" ? "Henüz ıskarta kaydı yok" : "Henüz teslim edilen kayıt yok"}</strong><span>{statusEntries.length ? "Tarih veya diğer filtreleri değiştirin." : activeStatus === "semi-finished" ? "Tezgah ekranında “İş tamamlandı” işlemi yapıldığında kayıtlar burada birikecek." : activeStatus === "scrapped" ? "Teslimat sırasında kalan miktarı ıskartaya ayırdığınızda burada izlenir." : "Yarı mamul listesindeki teslimat işlemleri burada saklanacak."}</span>{filtered && <button className="secondary" onClick={clearFilters}>Filtreleri temizle</button>}</div>}</div>
  </aside>
    {deliveryEntry && <div className="archive-action-backdrop" role="presentation"><DeliveryAllocationForm product={deliveryEntry.product} draft={deliveryDraft} onChange={draft => { setDeliveryDraft(draft); setConfirmedDeliveryBuffer(false); setActionError(""); }} error={actionError} onClose={() => setDeliveryEntry(null)} onSave={() => attempt(() => { const saved = onAllocate(deliveryEntry.id, { actualQuantity: deliveryDraft.actualQuantity, completedAt: inputDateToSerial(deliveryDraft.completedDate), deliveredQuantity: deliveryDraft.deliveredQuantity, deliveryDate: deliveryDraft.deliveryDate, remainderAction: deliveryDraft.remainderAction, confirmedDeliveryBuffer }, archiveEntrySignature(deliveryEntry), correctionLotId || undefined); if (saved) { setDeliveryEntry(null); setActiveStatus(deliveryDraft.deliveredQuantity > 0 ? "delivered" : deliveryDraft.remainderAction === "scrap" ? "scrapped" : "semi-finished"); } })}>{lotChoice}{deliveryDraft.deliveredQuantity > 0 && <div className="journey-early-delivery"><p>Planlanan paketleme beklemesinden önce gerçek teslimat kaydı için onay verin. Aktif proseslerin seçilen teslim anında tamamlanmış olması gerekir. Onay yalnız teslim edilen adedin beklemesini kaldırır.</p><label><input type="checkbox" checked={confirmedDeliveryBuffer} onChange={event => { setConfirmedDeliveryBuffer(event.target.checked); setActionError(""); }} /> Proses kontrol ve paketleme tamamlandı.</label></div>}</DeliveryAllocationForm></div>}
    {editEntry && <div className="archive-action-backdrop" role="presentation">
      <section className="completion-dialog archive-action-dialog" role="dialog" aria-modal="true" aria-label={`${editEntry.product} adet ve teslimat düzenleme`}>
        <PencilSimple size={24} /><span>ADET / TESLİMAT</span><h2>{editEntry.product}</h2>
        <p>{editEntry.inventoryStatus === "delivered" ? "Yalnız teslim tarihini değiştirmek için adedi aynı bırakın. Teslim adedi azalırsa fark Paketleme / Final Kontrol’e döner. Artış için aynı şarjdan teslimata hazır miktar gerekir." : "Fiili adedi düzeltin. Tamamlanmış prosesler korunur; kalan üretim yeni adede göre hesaplanır."}</p>
        <Field label={editEntry.inventoryStatus === "delivered" ? "Teslim edilen adet" : "Fiili tamamlanan adet"}><input type="number" min="1" step="1" value={editDraft.actualQuantity || ""} onChange={event => setEditDraft({ ...editDraft, actualQuantity: Number(event.target.value) })} /></Field>
        <Field label="Gerçek tamamlanma tarihi"><input type="date" disabled={editEntry.inventoryStatus === "delivered"} value={editDraft.completedDate} onChange={event => setEditDraft({ ...editDraft, completedDate: event.target.value })} /></Field>
        {editEntry.inventoryStatus === "delivered" && <Field label="Teslim tarihi ve saati"><input type="datetime-local" value={editDraft.deliveryDate} onChange={event => { setActionError(""); setEditDraft({ ...editDraft, deliveryDate: event.target.value }); }} /><small>Türkiye saati. Üretimin tamamlanma ve arşivlenme zamanı değişmez.</small></Field>}
        {lotChoice}
        {actionError && <p className="archive-export-error" role="alert">{actionError}</p>}
        <div className="drawer-actions"><button className="secondary" onClick={() => setEditEntry(null)}>Vazgeç</button><button className="primary" disabled={!editDraft.actualQuantity || !editDraft.completedDate || (editEntry.inventoryStatus === "delivered" && !editDraft.deliveryDate)} onClick={() => attempt(() => { if (onEdit(editEntry.id, editDraft.actualQuantity, inputDateToSerial(editDraft.completedDate), editEntry.inventoryStatus === "delivered" ? editDraft.deliveryDate : undefined, archiveEntrySignature(editEntry), correctionLotId || undefined)) setEditEntry(null); })}><FloppyDisk size={15} /> Değişiklikleri kaydet</button></div>
      </section>
    </div>}
    {restoreEntry && <div className="archive-action-backdrop" role="presentation">
      <section className="completion-dialog archive-action-dialog" role="dialog" aria-modal="true" aria-label={`${restoreEntry.product} geri alma onayı`}>
        <ArrowCounterClockwise size={24} /><span>ÖNCEKİ AŞAMAYA GERİ AL</span><h2>{restoreEntry.inventoryStatus === "delivered" ? "Teslimat geri alınsın mı?" : "Yarı mamule geri alınsın mı?"}</h2>
        <p>{restoreEntry.product} · {formatNumber(restoreEntry.completedQuantity)} adet, Paketleme / Final Kontrol’e dönecek. Tamamlanmış operasyonlar korunacak ve geri alma nedeni işlem geçmişine yazılacak.</p>
        {restoreEntry.inventoryStatus !== "delivered" && <Field label="Geçerlilik tarihi"><input type="date" value={restoreDate} onChange={event => setRestoreDate(event.target.value)} /></Field>}
        <Field label="Geri alma nedeni"><textarea value={restoreReason} onChange={event => setRestoreReason(event.target.value)} placeholder="Örn. yanlış şarj teslim edildi olarak işaretlendi" /></Field>
        {actionError && <p className="archive-export-error" role="alert">{actionError}</p>}
        <div className="drawer-actions"><button className="secondary" onClick={() => setRestoreEntry(null)}>Vazgeç</button><button className="primary" disabled={!restoreReason.trim()} onClick={() => attempt(() => { if (restoreEntry.inventoryStatus === "delivered") { if (!onRestoreDelivery(restoreEntry.id, restoreReason, archiveEntrySignature(restoreEntry))) return; } else onStatusChange(restoreEntry.id, "semi-finished", restoreDate, restoreReason); setRestoreEntry(null); setFocusedIds(undefined); setActiveStatus("semi-finished"); })}><ArrowCounterClockwise size={15} /> Onayla ve geri al</button></div>
      </section>
    </div>}
    {voidEntry && <div className="archive-action-backdrop" role="presentation"><section className="reset-dialog archive-action-dialog" role="dialog" aria-modal="true" aria-label={`${voidEntry.product} arşiv kaydını silme onayı`}><Warning size={24} weight="fill" /><span>KAYIT SİLİNECEK</span><h2>Kaydı silmeyi onaylıyor musunuz?</h2><p>{voidEntry.product} · {formatNumber(voidEntry.completedQuantity)} adet kayıt listeden kaldırılacak ve planlama hesabına katılmayacak. İşlem geçmişi güvenlik için korunur.</p>{actionError && <p className="archive-export-error" role="alert">{actionError}</p>}<div className="drawer-actions"><button className="secondary" onClick={() => setVoidEntry(null)}>Vazgeç</button><button className="danger-confirm" onClick={() => attempt(() => { onStatusChange(voidEntry.id, "voided"); setVoidEntry(null); })}><Trash size={15} /> Evet, kaydı sil</button></div></section></div>}
  </div>;
}

frontend/features/planning/board/Automat.source:
"use client";

import { NumberHelp } from "@/features/planning/shared/controls";
import { formatHours, formatInputDate, signedNumber } from "@/features/planning/shared/format";
import { compareWithAutomaticPlan, type PlanOutcomeMetrics } from "@/lib/automatic-plan-comparison";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { formatExcelDate, type AutomaticPlanSnapshot, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { ArrowCounterClockwise, ArrowsLeftRight, CheckCircle, Warning, X } from "@phosphor-icons/react";
import { useMemo, useState } from "react";

export function AutomaticPlanComparisonDialog({ seed, snapshot, manualResult, onClose, onRestore }: { seed: PlanningSeed; snapshot: AutomaticPlanSnapshot; manualResult: ScenarioResult; onClose: () => void; onRestore: () => void }) {
  const comparison = useMemo(() => compareWithAutomaticPlan(seed, snapshot, manualResult), [manualResult, seed, snapshot]);
  const [showAllOrders, setShowAllOrders] = useState(false);
  const [restoreConfirmation, setRestoreConfirmation] = useState(false);
  const visibleOrders = showAllOrders ? comparison.orders : comparison.orders.filter((order) => order.changed);
  const automaticCreatedAt = new Intl.DateTimeFormat("tr-TR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(snapshot.createdAt));
  const metricRows: Array<{ label: string; detail: string; key: keyof PlanOutcomeMetrics; format: (value: number | null, metrics: PlanOutcomeMetrics) => string; direction: "higher" | "lower" | "neutral"; date?: boolean; hours?: boolean }> = [
    { label: "Termin gününe kadar hazır", detail: "Delme, çapak alma, GKM ve korunan +1 iş günü dahil", key: "readyByDue", format: (value) => formatNumber(value ?? 0), direction: "higher" },
    { label: "Eksik üretim", detail: "Planda hiç karşılanmayan adet", key: "shortage", format: (value) => formatNumber(value ?? 0), direction: "lower" },
    { label: "Geciken miktar", detail: "Planlı fakat terminden sonra hazır", key: "lateQuantity", format: (value) => formatNumber(value ?? 0), direction: "lower" },
    { label: "İlk teslimata hazır", detail: "İlk hazır üretim tarihi", key: "firstReadyAt", format: formatComparisonDate, direction: "lower", date: true },
    { label: "Son teslimata hazır", detail: "Son hazır üretim tarihi", key: "lastReadyAt", format: formatComparisonDate, direction: "lower", date: true },
    { label: "En kötü termin sapması", detail: "Siparişler içindeki en geç sonuç", key: "dueDeltaDays", format: (value, metrics) => formatDueTiming(value, metrics.shortage), direction: "lower" },
    { label: "Plan bitişi", detail: "Tezgâhlardaki son üretim bitişi", key: "planCompletion", format: formatComparisonDate, direction: "lower", date: true },
    { label: "Setup saati", detail: "Tüm planlı şarjların toplamı", key: "setupHours", format: (value) => formatHours(value ?? 0), direction: "lower", hours: true },
  ];
  return (
    <div className="confirmation-backdrop automatic-comparison-backdrop" role="presentation">
      <section className="automatic-comparison-dialog" role="dialog" aria-modal="true" aria-label="Otomatik ve manuel plan karşılaştırması">
        <header className="automatic-comparison-head">
          <span className="dialog-icon automatic-comparison-icon"><ArrowsLeftRight size={20} /></span>
          <div>
            <span>MANUEL PLAN ETKİSİ</span>
            <h2>Otomatik planla karşılaştır</h2>
            <p>Manuel plandaki teslimat ve termin sonuçları, {automaticCreatedAt} tarihinde çalıştırılan son otomatik planla karşılaştırılıyor.</p>
          </div>
          <button className="delete-button" onClick={onClose} aria-label="Karşılaştırmayı kapat"><X size={17} /></button>
        </header>

        <div className="automatic-comparison-body">
          <section className="automatic-comparison-summary">
            <div className="automatic-comparison-section-title">
              <div><span>GENEL SONUÇ</span><strong>Manuel değişikliklerin toplam etkisi</strong></div>
              <small>Yeşil iyileşme, kırmızı olumsuz değişim gösterir.</small>
            </div>
            <div className="automatic-summary-table">
              <div className="head"><span>Ölçüt</span><span>Otomatik</span><span>Manuel</span><span>Fark</span></div>
              {metricRows.map((row) => {
                const automatic = comparison.automatic[row.key];
                const manual = comparison.manual[row.key];
                const delta = row.date
                  ? dateDelta(automatic, manual)
                  : automatic === null || manual === null ? null : manual - automatic;
                const description = `${row.label}: ${row.detail}.`;
                return <div className="row" key={row.key}><span><strong>{row.label}</strong><small>{row.detail}</small></span><span><NumberHelp description={description}>{row.format(automatic, comparison.automatic)}</NumberHelp></span><span><NumberHelp description={description}>{row.format(manual, comparison.manual)}</NumberHelp></span><span className={comparisonDeltaTone(delta, row.direction)}><NumberHelp description="Manuel sonuç ile otomatik sonuç arasındaki değişim.">{formatComparisonDelta(delta, row.date, row.hours)}</NumberHelp></span></div>;
              })}
            </div>
          </section>

          <section className="automatic-order-impact">
            <div className="automatic-comparison-section-title">
              <div><span>SİPARİŞ BAZINDA</span><strong>{comparison.changedOrderCount ? `${formatNumber(comparison.changedOrderCount)} siparişin sonucu değişti` : "Sipariş sonucu değişmedi"}</strong></div>
              <div className="comparison-order-filter"><button className={!showAllOrders ? "selected" : ""} onClick={() => setShowAllOrders(false)}>Değişenler · {formatNumber(comparison.changedOrderCount)}</button><button className={showAllOrders ? "selected" : ""} onClick={() => setShowAllOrders(true)}>Tümü · {formatNumber(comparison.orders.length)}</button></div>
            </div>
            {visibleOrders.length ? <div className="automatic-order-table"><table><thead><tr><th>Sipariş</th><th>Termin hazır</th><th>Eksik</th><th>Geciken</th><th>İlk hazır</th><th>Son hazır</th><th>Termin sapması</th></tr></thead><tbody>{visibleOrders.map((order) => <tr key={order.orderId}><td><strong>{order.product}</strong><small>{formatInputDate(order.dueDate)} termin · {formatNumber(order.quantity)} adet</small></td><ComparisonOrderCell automatic={formatNumber(order.automatic.readyByDue)} manual={formatNumber(order.manual.readyByDue)} delta={order.manual.readyByDue - order.automatic.readyByDue} direction="higher" /><ComparisonOrderCell automatic={formatNumber(order.automatic.shortage)} manual={formatNumber(order.manual.shortage)} delta={order.manual.shortage - order.automatic.shortage} direction="lower" /><ComparisonOrderCell automatic={formatNumber(order.automatic.lateQuantity)} manual={formatNumber(order.manual.lateQuantity)} delta={order.manual.lateQuantity - order.automatic.lateQuantity} direction="lower" /><ComparisonOrderCell automatic={formatComparisonDate(order.automatic.firstReadyAt)} manual={formatComparisonDate(order.manual.firstReadyAt)} delta={dateDelta(order.automatic.firstReadyAt, order.manual.firstReadyAt)} direction="lower" date /><ComparisonOrderCell automatic={formatComparisonDate(order.automatic.lastReadyAt)} manual={formatComparisonDate(order.manual.lastReadyAt)} delta={dateDelta(order.automatic.lastReadyAt, order.manual.lastReadyAt)} direction="lower" date /><ComparisonOrderCell automatic={formatDueTiming(order.automatic.dueDeltaDays, order.automatic.shortage)} manual={formatDueTiming(order.manual.dueDeltaDays, order.manual.shortage)} delta={nullableDelta(order.automatic.dueDeltaDays, order.manual.dueDeltaDays)} direction="lower" date /></tr>)}</tbody></table></div> : <div className="automatic-order-empty"><CheckCircle size={18} weight="fill" /><span>Manuel değişiklikler siparişlerin termin, eksik veya geciken miktar sonuçlarını değiştirmedi.</span></div>}
          </section>
        </div>

        <footer className="automatic-comparison-actions">
          {restoreConfirmation ? <div className="automatic-restore-confirmation"><Warning size={17} weight="fill" /><span><strong>Manuel değişiklikler kaldırılsın mı?</strong><small>Son otomatik plan geri yüklenecek. Bu işlem daha sonra “Geri al” ile tersine çevrilebilir.</small></span><button className="secondary" onClick={() => setRestoreConfirmation(false)}>Vazgeç</button><button className="danger-confirm" onClick={onRestore}><ArrowCounterClockwise size={14} /> Otomatik plana dön</button></div> : <><button className="secondary" onClick={onClose}>Kapat</button><button className="automatic-restore-action" onClick={() => setRestoreConfirmation(true)}><ArrowCounterClockwise size={14} /> Otomatik plana dön</button></>}
        </footer>
      </section>
    </div>
  );
}

function ComparisonOrderCell({ automatic, manual, delta, direction, date = false }: { automatic: string; manual: string; delta: number | null; direction: "higher" | "lower" | "neutral"; date?: boolean }) {
  return <td><strong>{manual}</strong><small>Otomatik · {automatic}</small><em className={comparisonDeltaTone(delta, direction)}>{formatComparisonDelta(delta, date)}</em></td>;
}

function formatComparisonDate(value: number | null) { return value ? formatExcelDate(value, { day: "2-digit", month: "short", year: "numeric" }) : "—"; }

function formatDueTiming(value: number | null, shortage: number) {
  if (value === null) return shortage > 0 ? "Tamamlanmıyor" : "—";
  if (value === 0) return "Termin günü";
  return `${Math.abs(value)} gün ${value < 0 ? "erken" : "geç"}`;
}

function nullableDelta(automatic: number | null, manual: number | null) { return automatic === null || manual === null ? null : manual - automatic; }

function dateDelta(automatic: number | null, manual: number | null) { return automatic === null || manual === null ? null : Math.floor(manual) - Math.floor(automatic); }

function formatComparisonDelta(value: number | null, date = false, hours = false) {
  if (value === null) return "—";
  if (Math.abs(value) < 0.000001) return "Değişmedi";
  if (date) return `${Math.abs(Math.round(value))} gün ${value < 0 ? "önce" : "sonra"}`;
  if (hours) return `${value > 0 ? "+" : "−"}${new Intl.NumberFormat("tr-TR", { maximumFractionDigits: 1 }).format(Math.abs(value))} sa`;
  return signedNumber(value);
}

function comparisonDeltaTone(value: number | null, direction: "higher" | "lower" | "neutral") {
  if (value === null || Math.abs(value) < 0.000001 || direction === "neutral") return "neutral";
  const improved = direction === "higher" ? value > 0 : value < 0;
  return improved ? "improved" : "worse";
}

frontend/features/planning/board/Capacit.source:
"use client";

import { ProcessIcon } from "@/components/ProcessIcon";

import { Field, NumberHelp } from "@/features/planning/shared/controls";
import { formatPercent, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { buildCapacityReport, suggestedCapacityRange, type MachineCapacity } from "@/lib/capacity-analytics";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { excelSerialToDate, formatExcelDate, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { processLabel } from "@/lib/process-master-data";
import { Clock, X } from "@phosphor-icons/react";
import { useMemo, useState } from "react";

export function CapacityDrawer({ seed, result, onClose }: { seed: PlanningSeed; result: ScenarioResult; onClose: () => void }) {
  const suggested = useMemo(() => suggestedCapacityRange(seed, result), [result, seed]);
  const planEnd = Math.ceil(Math.max(suggested.end, result.summary.completion || suggested.end));
  const [start, setStart] = useState(suggested.start);
  const [end, setEnd] = useState(suggested.end);
  const report = useMemo(() => buildCapacityReport(seed, result, start, end, { includeDownstream: true }), [end, result, seed, start]);
  const [selectedMachineId, setSelectedMachineId] = useState(report.machines[0]?.machineId ?? "");
  const selected = report.machines.find((machine) => machine.machineId === selectedMachineId) ?? report.machines[0];
  const overtimeMachineCount = report.machines.filter((machine) => machine.overtimeCapacityHours > 0).length;

  function setQuickRange(days: number | "plan") {
    setEnd(days === "plan" ? planEnd : start + days - 1);
  }

  return <div className="capacity-backdrop" role="presentation"><aside className="capacity-drawer" role="dialog" aria-modal="true" aria-label="Tezgah dolulukları">
    <header className="capacity-head"><div><span>KAPASİTE ANALİZİ</span><h2>Tüm proseslerin dolulukları</h2><p>Torna, delme, çapak alma ve GKM iş merkezlerini seçilen tarihlerdeki gerçek vardiya kapasitesiyle karşılaştırır.</p></div><button onClick={onClose} aria-label="Tezgah doluluklarını kapat"><X size={17} /></button></header>
    <div className="capacity-filters">
      <Field label="Başlangıç"><input type="date" value={serialToInputDate(start)} onChange={(event) => { const next = inputDateToSerial(event.target.value); setStart(next); if (next > end) setEnd(next); }} /></Field>
      <Field label="Bitiş"><input type="date" min={serialToInputDate(start)} value={serialToInputDate(end)} onChange={(event) => setEnd(Math.max(start, inputDateToSerial(event.target.value)))} /></Field>
      <div className="capacity-presets"><span>Hızlı aralık</span><div><button onClick={() => setQuickRange(7)}>7 gün</button><button onClick={() => setQuickRange(30)}>30 gün</button><button onClick={() => setQuickRange("plan")}>Tüm plan</button></div></div>
      <div className="capacity-scope"><strong><NumberHelp description="Kapasite analizine dahil edilen toplam takvim günü.">{report.dayCount} gün</NumberHelp></strong><span>{formatExcelDate(report.start)} – {formatExcelDate(report.end)}</span></div>
    </div>
    <div className="capacity-summary">
      <span><small>Genel doluluk</small><strong><NumberHelp description="Planlanan setup ve üretim saatlerinin kullanılabilir toplam vardiya saatlerine oranı.">{formatPercent(report.utilization)}</NumberHelp></strong><em>{formatNumber(report.plannedHours)} / {formatNumber(report.availableHours)} saat</em></span>
      <span><small>Boş kapasite</small><strong><NumberHelp description="Seçili tarihlerde aktif tezgâhlarda henüz kullanılmayan normal çalışma saati.">{formatNumber(report.idleHours)} sa</NumberHelp></strong><em>Seçili aralıkta kullanılabilir</em></span>
      <span className="overtime"><small>Mesai kapasitesi</small><strong><NumberHelp description="Normal vardiyanın üzerine tanımlanmış toplam ek çalışma saati.">{formatNumber(report.overtimeCapacityHours)} sa</NumberHelp></strong><em>{overtimeMachineCount} tezgahta · kullanılan {formatNumber(report.overtimeLoadHours)} sa</em></span>
      <span><small>Kapalı kapasite</small><strong><NumberHelp description="Bakım, tatil veya vardiya azaltımı nedeniyle üretime kapalı toplam saat.">{formatNumber(report.downtimeHours)} sa</NumberHelp></strong><em>Bakım veya vardiya azaltımı</em></span>
    </div>
    <div className="capacity-body">
      <section className="capacity-ranking"><div className="capacity-section-head"><div><strong>Tezgah karşılaştırması</strong><span>Oran, planlanan saatin kullanılabilir saate bölümüdür.</span></div><div className="capacity-legend"><i className="normal" /> Normal yük <i className="overtime" /> Mesai yükü</div></div>
        <div className="capacity-machine-list">{report.machines.map((machine) => <button key={machine.machineId} className={selected?.machineId === machine.machineId ? "selected" : ""} onClick={() => setSelectedMachineId(machine.machineId)}>
          <span className="capacity-machine-name"><strong>{machine.machineId}</strong><small><ProcessIcon process={machine.process} size={13} /> {processLabel(machine.process)} · {machine.machineName}</small></span>
          <span className="capacity-bar" aria-label={`${machine.machineId} doluluk ${formatPercent(machine.utilization)}`}><i className="normal" style={{ width: `${Math.min(100, machine.availableHours ? machine.regularLoadHours / machine.availableHours * 100 : 0)}%` }} /><i className="overtime" style={{ width: `${Math.min(100, machine.availableHours ? machine.overtimeLoadHours / machine.availableHours * 100 : 0)}%` }} /></span>
          <span className="capacity-machine-value"><strong><NumberHelp focusable={false} description="Bu tezgâhtaki planlı saatin kullanılabilir saate oranı.">{formatPercent(machine.utilization)}</NumberHelp></strong><small>{formatNumber(machine.plannedHours)} / {formatNumber(machine.availableHours)} sa</small></span>
          {machine.overtimeCapacityHours > 0 ? <em className="has-overtime">+{formatNumber(machine.overtimeCapacityHours)} sa mesai</em> : <em>{formatNumber(machine.idleHours)} sa boş</em>}
        </button>)}</div>
      </section>
      {selected && <CapacityMachineDetail machine={selected} />}
    </div>
  </aside></div>;
}

function CapacityMachineDetail({ machine }: { machine: MachineCapacity }) {
  return <section className="capacity-detail"><div className="capacity-detail-head"><div><span><ProcessIcon process={machine.process} size={14} /> {processLabel(machine.process).toLocaleUpperCase("tr-TR")} · GÜNLÜK DAĞILIM</span><h3>{machine.machineId} · {machine.machineName}</h3></div><strong><NumberHelp description="Seçili tezgâhtaki planlı saatin kullanılabilir saate oranı.">{formatPercent(machine.utilization)} dolu</NumberHelp></strong></div>
    <div className="capacity-detail-stats"><span><small>Planlanan</small><strong><NumberHelp description="Bu tezgâhta setup ve üretim için ayrılan toplam saat.">{formatNumber(machine.plannedHours)} sa</NumberHelp></strong></span><span><small>Boş</small><strong><NumberHelp description="Bu tezgâhta seçili aralıkta kullanılabilir kalan normal çalışma saati.">{formatNumber(machine.idleHours)} sa</NumberHelp></strong></span><span className="overtime"><small>Mesai kullanımı</small><strong><NumberHelp description="Planın bu tezgâhta normal vardiya dışından kullandığı toplam saat.">{formatNumber(machine.overtimeLoadHours)} sa</NumberHelp></strong></span></div>
    <div className="capacity-day-scroll"><div className="capacity-days">{machine.days.map((day) => {
      const tone = day.availableHours === 0 ? "closed" : day.overtimeCapacityHours > 0 ? "overtime" : day.utilization >= .85 ? "full" : day.utilization > 0 ? "loaded" : "empty";
      return <div key={day.serial} className={`capacity-day ${tone}`} title={`${formatExcelDate(day.serial)} · ${day.label} · ${formatNumber(day.plannedHours)} / ${formatNumber(day.availableHours)} saat`}>
        <span>{new Intl.DateTimeFormat("tr-TR", { weekday: "short" }).format(excelSerialToDate(day.serial)).slice(0, 2)}</span><strong>{excelSerialToDate(day.serial).getUTCDate()}</strong><i style={{ height: `${Math.max(day.plannedHours > 0 ? 8 : 0, Math.min(100, day.utilization * 100))}%` }} />{day.overtimeCapacityHours > 0 && <em>+{formatNumber(day.overtimeCapacityHours)}</em>}
      </div>;
    })}</div></div>
    <div className="capacity-detail-note"><Clock size={15} /><span><strong>Mesai ayrı hesaplanır.</strong> Turuncu günlerde normal vardiyanın üzerindeki kapasite ve bu kapasitede kullanılan saatler ayrıca gösterilir.</span></div>
  </section>;
}

frontend/features/planning/board/Inspect.source:
"use client";

import { productSetupFamilyLabel } from "@/lib/setup-families";
import { ProcessIcon } from "@/components/ProcessIcon";

import { NumberHelp, SetupFamilyBadge } from "@/features/planning/shared/controls";
import { formatHours } from "@/features/planning/shared/format";
import { queuePosition } from "@/features/planning/shared/production";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { formatExcelDate, type Machine, type PlannedBatch, type PlanningSeed, productSetupFamily } from "@/lib/planning";
import { processLabel } from "@/lib/process-master-data";
import { type ProcessOperation, type RoutedProcessJob } from "@/lib/process-planning";
import { plannedBatchDemandOrigin } from "@/lib/weekly-plan-status";
import { ArrowsLeftRight, CheckCircle, Lightbulb, Lock, LockOpen, PencilSimple, Play, Trash, Warning } from "@phosphor-icons/react";
import { useEffect, useState } from "react";
import { BatchQuantityDialog } from "../machines/ProductionDialogs";

export function JourneyInspector({ job, operation, onSelectOperation, onOpenJourney }: { job: RoutedProcessJob; operation: ProcessOperation; onSelectOperation: (operationId: string) => void; onOpenJourney: () => void }) {
  return <aside className="inspector journey-inspector">
    <div className="inspector-kicker">ŞARJ YOLCULUĞU</div>
    <div className="inspector-title"><div><h2>{job.workOrder || job.product}</h2><span>{job.product} · {productSetupFamilyLabel(job.family)} · {formatNumber(job.quantity)} adet</span></div></div>
    <div className={`status-callout journey-${operation.process}`}><span>Seçili adım</span><strong><ProcessIcon process={operation.process} /> {processLabel(operation.process)} · {operation.resourceId}</strong></div>
    <div className="journey-inspector-route" aria-label={`${job.workOrder || job.product} üretim rotası`}>
      {job.operations.map((step, index) => <button key={step.id} className={`${step.process} ${step.id === operation.id ? "active" : ""}`} onClick={() => onSelectOperation(step.id)}>
        <i>{step.actual ? <CheckCircle size={12} weight="fill" /> : index + 1}</i>
        <span><strong><ProcessIcon process={step.process} size={14} /> {processLabel(step.process)}</strong><small>{step.resourceId} · {formatExcelDate(step.start, { day: "2-digit", month: "short" })} – {formatExcelDate(step.end, { day: "2-digit", month: "short" })}</small></span>
      </button>)}
      <div className="journey-inspector-buffer"><i>+1</i><span><strong>Teslimat tamponu</strong><small>{formatExcelDate(job.deliveryReadyAt, { day: "2-digit", month: "short" })} teslimata hazır</small></span></div>
    </div>
    <button className="journey-open-action" onClick={onOpenJourney}>Tam yolculuk Gantt’ını aç <span>→</span></button>
    <dl className="details journey-operation-facts">
      <div><dt>Durum</dt><dd>{operation.actual ? "Fiili tamamlandı" : "Planlandı"}</dd></div>
      <div><dt>Setup</dt><dd>{formatHours(operation.setupHours)}</dd></div>
      {operation.protectedSetupHoursAfter ? <div><dt>D-02 dönüş rezervi</dt><dd>{formatHours(operation.protectedSetupHoursAfter)}</dd></div> : null}
      <div><dt>Üretim yükü</dt><dd>{formatHours(operation.runHours)}</dd></div>
      <div><dt>Vardiya kapasitesi</dt><dd>{operation.actual ? "Fiili kayıt" : operation.unitsPerShift > 0 ? `${formatNumber(operation.unitsPerShift)} adet` : "Torna planından"}</dd></div>
    </dl>
  </aside>;
}

export function BatchInspector({ seed, batch, currentMachine, machines, queueLength, onMove, onRemove, onLockThrough, onUnlockQueue, onSaveWorkOrder, onUpdateBatchQuantity }: { seed: PlanningSeed; batch: PlannedBatch | null; currentMachine: Machine | null; machines: Machine[]; queueLength: number; onMove: (batchId: string, machineId: string, position: number) => void; onRemove: (batchId: string) => void; onLockThrough: PlanningOperations["onLockThrough"]; onUnlockQueue: PlanningOperations["onUnlockQueue"]; onSaveWorkOrder: PlanningOperations["onSaveWorkOrder"]; onUpdateBatchQuantity: PlanningOperations["onUpdateBatchQuantity"] }) {
  const [targetMachine, setTargetMachine] = useState(batch?.machineId ?? "C-01");
  const [targetPosition, setTargetPosition] = useState(Math.max(0, (batch?.planColumn ?? 13) - 13));
  const [workOrder, setWorkOrder] = useState(batch?.workOrder ?? "");
  const [quantityOpen, setQuantityOpen] = useState(false);
  useEffect(() => {
    setTargetMachine(batch?.machineId ?? "C-01");
    setTargetPosition(Math.max(0, (batch?.planColumn ?? 13) - 13));
    setWorkOrder(batch?.workOrder ?? "");
    setQuantityOpen(false);
  }, [batch?.id, batch?.machineId, batch?.planColumn]);
  if (currentMachine) {
    const current = currentMachine.currentJob;
    return <aside className="inspector"><div className="inspector-kicker">SEÇİLİ MEVCUT İŞ</div><div className="inspector-title"><div><h2>{current.product}</h2><span>{currentMachine.id} · {currentMachine.name}</span></div></div><div className="status-callout"><span>Üretimde</span><strong><Play size={12} weight="fill" /> {currentMachine.id}</strong></div><dl className="details"><div><dt>İş emri</dt><dd>{current.workOrder || "—"}</dd></div><div><dt>Ürün ailesi</dt><dd><SetupFamilyBadge family={productSetupFamily(seed, current.product)} /></dd></div><div><dt>Orijinal miktar</dt><dd><NumberHelp description="Şarj tezgâhta başladığında girilen toplam üretim adedi.">{formatNumber(current.originalQuantity ?? current.quantity)}</NumberHelp></dd></div><div><dt>Kalan miktar</dt><dd><NumberHelp description="Seçili kayıt tarihine göre tezgâhta üretilmesi beklenen kalan adet.">{formatNumber(current.remainingQuantity ?? current.quantity)}</NumberHelp></dd></div><div><dt>Başlangıç</dt><dd>{formatExcelDate(current.start)}</dd></div><div><dt>Tahmini bitiş</dt><dd>{formatExcelDate(current.end)}</dd></div><div><dt>Hesaplanan hız</dt><dd><NumberHelp description="Mevcut işin girilen süre ve miktarından hesaplanan günlük üretim kapasitesi.">{formatNumber(current.dailyRate)} / gün</NumberHelp></dd></div><div><dt>Çap</dt><dd><NumberHelp description="Mevcut ürünün parametre kartındaki parça çapı.">{current.diameter || "—"}</NumberHelp></dd></div></dl><div className="explanation"><div className="explanation-head"><span className="spark">●</span><strong>Devam eden üretim</strong></div><p>Bu kayıt tezgahın halen üretimde olan işidir; planlı kuyruktaki yeni bir şarj değildir. Kuyruğun ilk işi bunun tahmini bitişinden sonra başlar.</p></div></aside>;
  }
  if (!batch) return <aside className="inspector empty-state">Plan boş. Girdileri düzenleyip “Planı Çalıştır” düğmesine basın.</aside>;
  const demandOrigin = plannedBatchDemandOrigin(seed, batch);
  const statusLabel = batch.rolledForwardFrom
    ? `${batch.locked ? "Kilitli · " : ""}Gecikmiş plan`
    : batch.locked
      ? "Kilitli plan"
      : batch.pullForward
        ? `${batch.pullForward.sourceWeekLabel}’den öne çekildi`
        : batch.manuallyPlaced
          ? "Manuel plan"
          : "Planlandı";
  return (<>
    <aside className="inspector">
      <div className="inspector-kicker">SEÇİLİ ŞARJ</div>
      <div className="inspector-title"><div><h2>{batch.product}</h2><span>Kuyrukta {queuePosition(batch.planColumn)}. sıra</span></div></div>
      <div className={`status-callout ${batch.locked ? "locked" : ""} ${batch.pullForward ? "pulled-forward" : ""} ${batch.rolledForwardFrom ? "delayed-plan" : ""}`}><span>{statusLabel}</span><strong>{batch.pullForward ? <Lightbulb size={12} weight="fill" /> : batch.locked ? <Lock size={12} weight="fill" /> : null} {batch.machineId}</strong></div>
      <dl className="details">
        <div><dt>Miktar</dt><dd><NumberHelp description="Bu planlı şarjda üretilecek toplam adet.">{formatNumber(batch.quantity)}</NumberHelp></dd></div>
        <div><dt>Ürün ailesi</dt><dd><SetupFamilyBadge family={productSetupFamily(seed, batch.product)} /></dd></div>
        <div><dt>Başlangıç</dt><dd>{formatExcelDate(batch.start)}</dd></div>
        <div><dt>Bitiş</dt><dd>{formatExcelDate(batch.end)}</dd></div>
        <div><dt>Hesaplanan hız</dt><dd><NumberHelp description="Ürün–tezgâh parametresinden gelen günlük üretim kapasitesi.">{formatNumber(batch.dailyRate)} / gün</NumberHelp></dd></div>
        <div><dt>Setup</dt><dd><NumberHelp description="Önceki şarjdan bu şarja geçiş için plana eklenen hazırlık süresi.">{formatHours(batch.setupHours)}</NumberHelp></dd></div>
        <div><dt>Üretim süresi</dt><dd><NumberHelp description="Setup hariç, bu şarjın miktar ve hızına göre hesaplanan çalışma süresi.">{formatHours(batch.runHours)}</NumberHelp></dd></div>
        <div><dt>Çap</dt><dd><NumberHelp description="Planlanan ürünün parametre kartındaki parça çapı.">Ø {batch.diameter}</NumberHelp></dd></div>
        <div><dt>İş emri</dt><dd>{batch.workOrder || "—"}</dd></div>
        <div><dt>Talep haftası / tarihi</dt><dd>{demandOrigin?.label ?? "Talep haftası bağlı değil"}</dd></div>
        {batch.rolledForwardFrom && <div><dt>Plan durumu</dt><dd>Henüz üretime başlamadı · eski plan başlangıcı {formatExcelDate(batch.rolledForwardFrom)}</dd></div>}
        {batch.pullForward && <div><dt>Kaynak aralık</dt><dd>{batch.pullForward.sourceRangeLabel}</dd></div>}
      </dl>
      <div className="explanation"><div className="explanation-head"><span className="spark">✦</span><strong>Neden bu tezgah?</strong></div><p>{batch.explanation}</p><ul><li>Ürün–tezgah kısıtı sağlandı</li><li>Bitiş müsaitlik penceresi içinde</li><li>{batch.pullForward ? "Müşteri termini değişmeden normal boş kapasite kullanıldı" : batch.demandDueDate ? "En erken açık haftalık hedef önceliklendirildi" : "Setup dahil en erken bitiş değerlendirildi"}</li></ul></div>
      {batch.reason && <div className="risk-note"><Warning size={18} weight="fill" /><div><strong>Şarj yuvarlama</strong><p>{batch.reason}</p></div></div>}
      <div className="manual-controls">
        <div><strong>Manuel planlama</strong><span>Taşıma sonrası kapasite ve tarihler yeniden kontrol edilir.</span></div>
        <label>İş emri / izlenebilirlik<div className="inline-save"><input value={workOrder} onChange={(event) => setWorkOrder(event.target.value)} placeholder="320-…" /><button disabled={workOrder.trim() === (batch.workOrder ?? "")} onClick={() => onSaveWorkOrder(batch, workOrder)}>Kaydet</button></div></label>
        <label>Hedef tezgah<select value={targetMachine} onChange={(event) => setTargetMachine(event.target.value)}>{machines.filter((machine) => machine.active).map((machine) => <option key={machine.id} value={machine.id}>{machine.id}</option>)}</select></label>
        <label>Kuyruk sırası<select value={targetPosition} onChange={(event) => setTargetPosition(Number(event.target.value))}>{Array.from({ length: Math.max(1, queueLength) }, (_, index) => <option key={index} value={index}>{index + 1}. sıra</option>)}</select></label>
        <button className="wide-secondary quantity-action" disabled={batch.locked} onClick={() => setQuantityOpen(true)}><PencilSimple size={15} /> Adedi düzenle</button>
        <button className="wide-secondary" disabled={batch.locked} onClick={() => onMove(batch.id, targetMachine, targetPosition)}><ArrowsLeftRight size={15} /> Taşı / yeniden sırala</button>
        {batch.locked ? <button className="wide-secondary lock-action" onClick={() => onUnlockQueue(batch.machineId)}><LockOpen size={15} /> Tezgah kuyruğu kilidini kaldır</button> : <button className="wide-secondary lock-action" onClick={() => onLockThrough(batch)}><Lock size={15} /> Bu sıraya kadar kilitle</button>}
        <button className="danger-button" disabled={batch.locked} onClick={() => onRemove(batch.id)}><Trash size={15} /> Şarjı plandan çıkar</button>
      </div>
    </aside>
    {quantityOpen && <BatchQuantityDialog batch={batch} setupFamily={productSetupFamily(seed, batch.product)} onClose={() => setQuantityOpen(false)} onSave={(quantity) => { onUpdateBatchQuantity(batch, quantity); setQuantityOpen(false); }} />}
  </>);
}

frontend/features/planning/board/PlanBoa.source:
"use client";
import { filterProductStyle, filterProductColors } from "@/lib/filter-product-colors";
import { productionProcessOrder } from "@/lib/process-master-data";

import type { RoutePlacementRequest } from "@/lib/route-placement";

import { useRaviScreenContext } from "@/features/ravi/context";

import { placementDate } from "@/features/planning/shared/ProcessPlacementReview";

import { ProcessIcon } from "@/components/ProcessIcon";
import { Menu } from "@/components/ui/Menu";
import { buildDiameterHues, DIAMETER_HUE_WHEEL } from "@/features/planning/shared/diameter-colors";

import { WeeklyDemandRibbon } from "@/features/planning/board/WeeklyDemandRibbon";
import { ShiftOptions } from "@/features/planning/machines/CalendarDialogs";
import { CompleteJobDialog, CurrentJobEditor } from "@/features/planning/machines/ProductionDialogs";
import { Field, NumberHelp } from "@/features/planning/shared/controls";
import { formatHours, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { clampShiftCount, queuePosition } from "@/features/planning/shared/production";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { buildOvertimeEntries } from "@/lib/capacity-analytics";
import { factoryDateInput } from "@/lib/factory-time";
import { buildGanttCalendar, ganttDropStart, ganttPercent } from "@/lib/gantt-scale";
import { buildMachineDiagnostics } from "@/lib/machine-diagnostics";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { buildOperationWorkloads } from "@/lib/operation-workload";
import { buildOperationalMetrics } from "@/lib/operational-metrics";
import {
  type Machine,
  type PlannedBatch,
  type PlanningSeed,
  type ScenarioResult,
  type ShiftCount,
  diameterNumeric,
  formatExcelDate,
  machineDayCapacity,
  moveBatchManually,
  productSetupFamily,
  removeMachineShiftOverrides,
  replaceMachineShiftOverrides,
} from "@/lib/planning";
import { type PlanningAdvice } from "@/lib/planning-advice";
import { compatibleMachineIdsForBatch, machineMatchesPlanningQuery } from "@/lib/planning-search";
import { type ProcessKind, processLabel } from "@/lib/process-master-data";
import {
  type ProcessOperation,
  buildDownstreamProcessPlan,
  clearProcessOperationReschedule,
  previewProcessOperationReschedule,
} from "@/lib/process-planning";
import { productSetupFamilyLabel } from "@/lib/setup-families";
import { batchSplitInsight, buildWeeklyPlanStatus, plannedBatchDemandOrigin } from "@/lib/weekly-plan-status";
import {
  ArrowCounterClockwise,
  ArrowsLeftRight,
  CalendarBlank,
  CaretDown,
  CaretLeft,
  CaretRight,
  CheckCircle,
  Clock,
  DotsSixVertical,
  Lightbulb,
  Lock,
  LockOpen,
  MagnifyingGlass,
  Minus,
  PencilSimple,
  Play,
  Plus,
  Trash,
  Warning,
  Wrench,
  X,
} from "@phosphor-icons/react";
import { type ReactNode, useEffect, useMemo, useRef, useState } from "react";

const GANTT_PROCESS_TABS: Array<{ id: ProcessKind; label: string }> = [
  { id: "turning", label: "Torna" },
  { id: "drilling", label: "Delme" },
  { id: "deburring", label: "Çapak Alma" },
  { id: "gkm", label: "GKM" },
];

export function PlanBoard({ toolbarActions, onReviewRoute, seed, result, dirty, advice, selectedBatch, selectedCurrentMachineId, selectedProcessOperationId, onSelectProcessOperation, onSelectBatch, onSelectCurrentJob, onMoveBatch, onLockThrough, onUnlockQueue, onApplyAdvice, onOpenMachineAdvice, onSaveCurrentJob, onCompleteCurrentJob, onOperationError, updateSeed, onReplanProcess }: { toolbarActions?: ReactNode; onReviewRoute: (request: RoutePlacementRequest) => void; seed: PlanningSeed; result: ScenarioResult; dirty: boolean; advice: PlanningAdvice[]; selectedBatch: PlannedBatch | null; selectedCurrentMachineId: string | null; selectedProcessOperationId: string; onSelectProcessOperation: (operationId: string) => void; onSelectBatch: (id: string) => void; onSelectCurrentJob: (machineId: string) => void; onMoveBatch: (batchId: string, machineId: string, position: number) => void; onLockThrough: PlanningOperations["onLockThrough"]; onUnlockQueue: PlanningOperations["onUnlockQueue"]; onApplyAdvice: (item: PlanningAdvice) => void; onOpenMachineAdvice: (machineId: string) => void; onSaveCurrentJob: PlanningOperations["onSaveCurrentJob"]; onCompleteCurrentJob: PlanningOperations["onCompleteCurrentJob"]; onOperationError: (message: string) => void; onReplanProcess: (process: "drilling" | "deburring" | "gkm" | "gtm" | "diameter-grinding" | "form-grinding" | "measuring" | "milling" | "final-inspection" | "filter-visual") => boolean; updateSeed: (mutator: (seed: PlanningSeed) => void) => void }) {
  const [query, setQuery] = useState("");
  const [ganttProcess, setGanttProcess] = useState<ProcessKind>("turning");
  const [diagnosticMachineId, setDiagnosticMachineId] = useState<string | null>(null);
  const [draggedBatchId, setDraggedBatchId] = useState<string | null>(null);
  const [dropTarget, setDropTarget] = useState<{ machineId: string; position: number } | null>(null);
  const [lastDropError, setLastDropError] = useState("");
  const [jobEditorMachineId, setJobEditorMachineId] = useState<string | null>(null);
  const [completeMachineId, setCompleteMachineId] = useState<string | null>(null);
  const [calendarSelection, setCalendarSelection] = useState<{ resourceId: string; process: ProcessKind; serial: number } | null>(null);
  const [recentMovedBatchId, setRecentMovedBatchId] = useState<string | null>(null);
  const [recentMovedProcessOperationId, setRecentMovedProcessOperationId] = useState<string | null>(null);
  const [draggedProcessOperationId, setDraggedProcessOperationId] = useState<string | null>(null);
  const [lastAppliedProcessMove, setLastAppliedProcessMove] = useState<ProcessOperation | null>(null);
  const [processMoveSequence, setProcessMoveSequence] = useState(0);
  const [processMoveFeedback, setProcessMoveFeedback] = useState("");
  const movedElementRef = useRef<HTMLButtonElement | null>(null);
  const [processDragOffset, setProcessDragOffset] = useState({ x: 0, y: 0 });
  const [processDropTarget, setProcessDropTarget] = useState<{ resourceId: string; requestedStart: number } | null>(null);
  const todaySerial = inputDateToSerial(factoryDateInput());
  const [viewStart, setViewStart] = useState(todaySerial);
  const [viewDays, setViewDays] = useState(42);
  const turningViewportRef = useRef({ start: todaySerial, days: 42 });
  const gestureRef = useRef<{ batchId: string; startX: number; startY: number; active: boolean; element: HTMLButtonElement } | null>(null);
  const processGestureRef = useRef<{ operationId: string; startX: number; startY: number; active: boolean; grabOffsetDays: number } | null>(null);
  const processDropTargetRef = useRef<{ resourceId: string; requestedStart: number } | null>(null);
  const suppressProcessClickRef = useRef(false);
  const dropTargetRef = useRef<{ machineId: string; position: number } | null>(null);
  const suppressBatchClickRef = useRef(false);
  const plannedBatches = result.batches.filter((batch) => batch.status === "planned");
  const activeMachines = seed.machines.filter((machine) => machine.active);
  const downstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, result), [result, seed]);
  useEffect(() => {
    if (!lastAppliedProcessMove) return;
    const current = downstreamPlan.operations.find((item) => item.id === lastAppliedProcessMove.id);
    if (!current || current.start !== lastAppliedProcessMove.start || current.end !== lastAppliedProcessMove.end || current.resourceId !== lastAppliedProcessMove.resourceId) {
      setProcessMoveFeedback(""); setRecentMovedProcessOperationId(null); setLastAppliedProcessMove(null);
    }
  }, [downstreamPlan, lastAppliedProcessMove]);
  const compatibleDropMachineIds = useMemo(() => {
    if (!draggedBatchId) return new Set<string>();
    const batch = result.batches.find((item) => item.id === draggedBatchId);
    if (!batch) return new Set<string>();
    return compatibleMachineIdsForBatch(seed, batch);
  }, [draggedBatchId, result.batches, seed]);
  const customerDemand = seed.customerDemand;
  const activeDemandScope = customerDemand?.activeScope;
  const demandStartWeek = customerDemand?.weeks.find((week) => week.id === activeDemandScope?.startWeekId);
  const demandEndWeek = customerDemand?.weeks.find((week) => week.id === activeDemandScope?.endWeekId);
  const filterLegendProducts = seed.productionArea === "cubuk-filtre"
    ? [...new Set([...seed.products.map(product => product.product), ...result.batches.map(batch => batch.product)])].sort()
    : [];
  const diameterHues = useMemo(() => buildDiameterHues(seed, result), [result, seed]);
  const operationWorkloads = useMemo(() => buildOperationWorkloads(seed, result), [result, seed]);
  const selectedWorkload = operationWorkloads[ganttProcess];
  useRaviScreenContext("plan-board", { query, ganttProcess, viewStart, viewDays, diagnosticMachineId,
    jobEditorMachineId, completeMachineId, calendarSelection, selectedWorkload, lastDropError });
  useEffect(() => {
    if (!recentMovedBatchId) return;
    const timeout = window.setTimeout(() => setRecentMovedBatchId(null), 900);
    return () => window.clearTimeout(timeout);
  }, [recentMovedBatchId]);
  useEffect(() => {
    if (!recentMovedProcessOperationId) return;
    const timeout = window.setTimeout(() => setRecentMovedProcessOperationId(null), 4500);
    return () => window.clearTimeout(timeout);
  }, [recentMovedProcessOperationId, processMoveSequence]);
  useEffect(() => {
    if (ganttProcess !== "turning") return;
    if (!demandStartWeek || !demandEndWeek) return;
    const start = inputDateToSerial(demandStartWeek.weekStart);
    const end = inputDateToSerial(demandEndWeek.weekEnd);
    setViewStart(start);
    setViewDays(Math.max(14, Math.min(112, end - start + 1)));
  }, [demandEndWeek?.id, demandStartWeek?.id]);
  const diagnostics = useMemo(() => buildMachineDiagnostics(seed, result, { dirty }), [dirty, result, seed]);
  const adviceByMachine = useMemo(() => {
    const map = new Map<string, PlanningAdvice[]>();
    for (const item of advice) {
      if (!item.machineId) continue;
      map.set(item.machineId, [...(map.get(item.machineId) ?? []), item]);
    }
    return map;
  }, [advice]);
  const selectedDiagnostic = diagnosticMachineId ? diagnostics[diagnosticMachineId] : null;
  const selectedDiagnosticMachine = seed.machines.find((machine) => machine.id === diagnosticMachineId);
  const selectedDiagnosticBatches = diagnosticMachineId ? plannedBatches.filter((batch) => batch.machineId === diagnosticMachineId) : [];
  const selectedLastCharge = [...selectedDiagnosticBatches].sort((left, right) => right.end - left.end || right.planColumn - left.planColumn)[0];
  const selectedMachineAdvice = diagnosticMachineId ? adviceByMachine.get(diagnosticMachineId) ?? [] : [];
  const selectedPullForwardAdvice = selectedMachineAdvice.find((item) => item.kind === "pull-forward");
  const downstreamOperations = downstreamPlan.operations.filter((operation) => !operation.actual && operation.process === ganttProcess);
  const processSetupHues = useMemo(() => buildProcessSetupHues(downstreamPlan.operations), [downstreamPlan.operations]);
  const planStart = ganttProcess === "turning"
    ? plannedBatches.length ? Math.min(...plannedBatches.map((batch) => batch.start)) : Math.min(...activeMachines.map((machine) => machine.availableStart))
    : downstreamOperations.length ? Math.min(...downstreamOperations.map((operation) => operation.start)) : todaySerial;
  const planEnd = ganttProcess === "turning"
    ? Math.max(...activeMachines.map((machine) => machine.planEnd), ...plannedBatches.map((batch) => batch.end))
    : downstreamOperations.length ? Math.max(...downstreamOperations.map((operation) => operation.end)) : todaySerial + 14;
  const horizonStart = Math.floor(viewStart);
  const horizon = Math.max(1, Math.ceil(viewDays));
  const horizonEnd = horizonStart + horizon;
  const operationalMetrics = useMemo(() => buildOperationalMetrics(seed, result, { start: horizonStart, end: horizonEnd - 1 }), [horizonEnd, horizonStart, result, seed]);
  const overtimeEntries = useMemo(() => buildOvertimeEntries(seed, horizonStart, horizonEnd - 1), [horizonEnd, horizonStart, seed]);
  const overtimeEntryKeys = useMemo(() => new Set(overtimeEntries.map((entry) => entry.id)), [overtimeEntries]);
  const overtimeMachineIds = useMemo(() => new Set(overtimeEntries.map((entry) => entry.machineId)), [overtimeEntries]);
  const machineBatchesById = useMemo(() => {
    const map = new Map(seed.machines.map((machine) => [machine.id, [] as PlannedBatch[]]));
    for (const batch of plannedBatches) map.get(batch.machineId)?.push(batch);
    return map;
  }, [plannedBatches, seed.machines]);
  const calendarBandsByMachine = useMemo(() => new Map(activeMachines.map((machine) => [
    machine.id,
    Array.from({ length: horizon }, (_, index) => horizonStart + index)
      .map((serial) => ({ serial, capacity: machineDayCapacity(seed, machine, serial) }))
      .filter(({ capacity }) => capacity.kind !== "normal"),
  ])), [activeMachines, horizon, horizonStart, seed]);
  const processCalendarBandsByResource = useMemo(() => new Map(
    (seed.processMasterData?.resources ?? []).filter((resource) => resource.active && resource.process !== "turning").map((resource) => {
      const calendarSeed = resource.id.startsWith("B-01-S")
        ? {
          ...seed,
          calendarEvents: [
            ...(seed.calendarEvents ?? []),
            ...(seed.calendarEvents ?? []).filter((event) => event.machineId === "B-01").map((event) => ({ ...event, id: `${event.id}-${resource.id}`, machineId: resource.id })),
          ],
        }
        : seed;
      return [resource.id, Array.from({ length: horizon }, (_, index) => horizonStart + index)
        .map((serial) => ({ serial, capacity: machineDayCapacity(calendarSeed, { id: resource.id, shiftFactor: resource.defaultShifts }, serial) }))
        .filter(({ capacity }) => capacity.kind !== "normal")] as const;
    }),
  ), [horizon, horizonStart, seed]);
  const selectedProcessCalendarResource = calendarSelection?.process !== "turning"
    ? seed.processMasterData?.resources.find((resource) => resource.id === calendarSelection?.resourceId)
    : undefined;
  const calendarCapacityTarget: Pick<Machine, "id" | "shiftFactor"> | undefined = calendarSelection?.process === "turning"
    ? seed.machines.find((machine) => machine.id === calendarSelection.resourceId)
    : selectedProcessCalendarResource
      ? { id: selectedProcessCalendarResource.id, shiftFactor: selectedProcessCalendarResource.defaultShifts }
      : undefined;
  const visibleMachines = activeMachines.filter((machine) => machineMatchesPlanningQuery(machine, plannedBatches, query));
  const normalizedProcessQuery = query.trim().toLocaleUpperCase("tr-TR");
  const processResources = (seed.processMasterData?.resources ?? [])
    .filter((resource) => resource.active && resource.process === ganttProcess)
    .map((resource) => ({
      resource,
      gaps: normalizedProcessQuery ? [] : downstreamPlan.gaps.filter((gap) => gap.resourceId === resource.id),
      operations: downstreamOperations
        .filter((operation) => operation.resourceId === resource.id)
        .filter((operation) => !normalizedProcessQuery || `${operation.product} ${operation.workOrder} ${operation.batchId}`.toLocaleUpperCase("tr-TR").includes(normalizedProcessQuery))
        .sort((left, right) => left.start - right.start || left.id.localeCompare(right.id)),
    }))
    .filter(({ resource, operations }) => !normalizedProcessQuery || operations.length > 0 || `${resource.id} ${resource.name}`.toLocaleUpperCase("tr-TR").includes(normalizedProcessQuery));
  const selectedProcessOperation = downstreamOperations.find((operation) => operation.id === selectedProcessOperationId);
  const selectedProcessJob = selectedProcessOperation ? downstreamPlan.jobs.find((job) => job.batchId === selectedProcessOperation.batchId) : undefined;
  const ganttCalendar = useMemo(() => buildGanttCalendar(horizonStart, horizon), [horizon, horizonStart]);
  const demandMonthOptions = useMemo(() => {
    if (!customerDemand?.weeks.length) return [];
    const first = new Date(`${customerDemand.weeks[0].weekStart}T00:00:00Z`);
    const last = new Date(`${customerDemand.weeks.at(-1)!.weekEnd}T00:00:00Z`);
    const months: Array<{ id: string; label: string; start: string; dayCount: number }> = [];
    const cursor = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth(), 1));
    while (cursor <= last) {
      const year = cursor.getUTCFullYear();
      const month = cursor.getUTCMonth();
      const start = `${year}-${String(month + 1).padStart(2, "0")}-01`;
      months.push({
        id: start.slice(0, 7),
        label: new Intl.DateTimeFormat("tr-TR", { month: "long", year: "numeric", timeZone: "UTC" }).format(cursor),
        start,
        dayCount: new Date(Date.UTC(year, month + 1, 0)).getUTCDate(),
      });
      cursor.setUTCMonth(cursor.getUTCMonth() + 1);
    }
    return months;
  }, [customerDemand]);
  const visibleMonthId = serialToInputDate(horizonStart).slice(0, 7);
  const holidaySerials = useMemo(() => new Set(seed.holidays.map((holiday) => Math.floor(holiday.serial))), [seed.holidays]);
  const dayWidth = horizon <= 14 ? 44 : horizon <= 28 ? 30 : horizon <= 42 ? 24 : horizon <= 70 ? 18 : 16;
  const timelineStyle = { "--gantt-days": horizon, "--gantt-min-width": `${Math.max(680, horizon * dayWidth)}px` } as React.CSSProperties;
  const dropPreview = useMemo(() => {
    if (!draggedBatchId || !dropTarget) return null;
    try {
      const preview = moveBatchManually(seed, result, draggedBatchId, dropTarget.machineId, dropTarget.position);
      const moved = preview.batches.find((batch) => batch.id === draggedBatchId);
      return moved ? { valid: true as const, moved, result: preview } : { valid: false as const, reason: "Taşıma önizlemesi oluşturulamadı." };
    } catch (error) {
      return { valid: false as const, reason: error instanceof Error ? error.message : "Bu konuma taşınamaz." };
    }
  }, [draggedBatchId, dropTarget, result, seed]);
  const processDropPreview = useMemo(() => {
    if (!draggedProcessOperationId || !processDropTarget) return null;
    try {
      const preview = previewProcessOperationReschedule(seed, result, draggedProcessOperationId, processDropTarget.resourceId, processDropTarget.requestedStart);
      return { valid: true as const, operation: preview.operation, preview };
    } catch (error) {
      return { valid: false as const, reason: error instanceof Error ? error.message : "Bu downstream yerleşimi uygulanamaz." };
    }
  }, [draggedProcessOperationId, processDropTarget, result, seed]);
  useRaviScreenContext("process-placement", { draggedProcessOperationId, processDropTarget, processMoveFeedback, lastDropError, dirty });
  useEffect(() => {
    if (!recentMovedProcessOperationId) return;
    const frame = requestAnimationFrame(() => movedElementRef.current?.scrollIntoView({ block: "center", inline: "center", behavior: "instant" }));
    return () => cancelAnimationFrame(frame);
  }, [recentMovedProcessOperationId, processMoveSequence]);
  useEffect(() => {
    const cancel = (event: KeyboardEvent) => { if (event.key === "Escape") { cancelProcessPointerMove(); } };
    window.addEventListener("keydown", cancel);
    return () => window.removeEventListener("keydown", cancel);
  }, []);
  const evaluatedResult = dropPreview?.valid ? dropPreview.result : result;
  const evaluatedSelectedBatch = selectedBatch ? evaluatedResult.batches.find((batch) => batch.id === selectedBatch.id) ?? selectedBatch : null;
  const evaluatedDownstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, evaluatedResult), [evaluatedResult, seed]);
  const selectedBatchDeliveryReadyAt = evaluatedSelectedBatch
    ? evaluatedDownstreamPlan.jobs.find((job) => job.batchId === evaluatedSelectedBatch.id)?.deliveryReadyAt
    : undefined;
  const weeklyPlanStatus = useMemo(() => buildWeeklyPlanStatus(seed, evaluatedResult).filter((row) => !row.excludedFromPlan), [evaluatedResult, seed]);
  const selectedSplitInsight = useMemo(() => batchSplitInsight(evaluatedResult.batches, evaluatedSelectedBatch), [evaluatedResult.batches, evaluatedSelectedBatch]);

  function setPointerDropTarget(batchId: string, clientX: number, clientY: number) {
    const target = document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(".track[data-machine-id]");
    if (!target) return;
    const machineId = target.dataset.machineId;
    if (!machineId) return;
    const rect = target.getBoundingClientRect();
    const serial = horizonStart + Math.max(0, Math.min(1, (clientX - rect.left) / rect.width)) * horizon;
    const queue = plannedBatches.filter((batch) => batch.machineId === machineId && batch.id !== batchId).sort((left, right) => left.start - right.start);
    const nextTarget = { machineId, position: queue.filter((batch) => batch.start < serial).length };
    dropTargetRef.current = nextTarget;
    setDropTarget(nextTarget);
  }

  function beginPointerMove(event: React.PointerEvent<HTMLButtonElement>, batch: PlannedBatch) {
    if (event.button !== 0 || batch.locked) return;
    gestureRef.current = { batchId: batch.id, startX: event.clientX, startY: event.clientY, active: false, element: event.currentTarget };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continuePointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = gestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) < 6) return;
    gesture.active = true;
    suppressBatchClickRef.current = true;
    setDraggedBatchId(gesture.batchId);
    setLastDropError("");
    setPointerDropTarget(gesture.batchId, event.clientX, event.clientY);
  }

  function endPointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = gestureRef.current;
    if (!gesture) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    if (gesture.active) {
      const target = dropTargetRef.current;
      if (target) {
        try {
          moveBatchManually(seed, result, gesture.batchId, target.machineId, target.position);
          onMoveBatch(gesture.batchId, target.machineId, target.position);
          setLastDropError("");
        } catch (error) {
          const message = error instanceof Error ? error.message : "Bu konuma taşınamaz.";
          setLastDropError(message);
          onOperationError(message);
        }
      } else {
        const message = "Şarjı geçerli bir tezgah zaman çizgisine bırakın.";
        setLastDropError(message);
        onOperationError(message);
      }
    }
    gestureRef.current = null;
    finishDrag();
  }

  function setProcessPointerDropTarget(clientX: number, clientY: number) {
    const target = document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(".process-resource-track[data-process-resource-id]");
    if (!target?.dataset.processResourceId) {
      processDropTargetRef.current = null;
      setProcessDropTarget(null);
      return;
    }
    const resourceId = target.dataset.processResourceId;
    const rect = target.getBoundingClientRect();
    const pointerRatio = (clientX - rect.left) / rect.width;
    const requestedStart = ganttDropStart(pointerRatio, horizonStart, horizon, processGestureRef.current?.grabOffsetDays ?? 0);
    const nextTarget = { resourceId, requestedStart };
    if (processDropTargetRef.current?.resourceId === resourceId && processDropTargetRef.current.requestedStart === requestedStart) return;
    processDropTargetRef.current = nextTarget;
    setProcessDropTarget(nextTarget);
  }

  function beginProcessPointerMove(event: React.PointerEvent<HTMLButtonElement>, operation: ProcessOperation) {
    if (event.button !== 0) return;
    if (operation.actual || operation.current) { setLastDropError("Çalışan ve tamamlanan işler sabittir; yalnızca kuyruktaki planlı işleri taşıyabilirsiniz."); return; }
    processDropTargetRef.current = null;
    setProcessDropTarget(null);
    const track = event.currentTarget.closest<HTMLElement>(".process-resource-track");
    const trackRect = track?.getBoundingClientRect();
    const pointerSerial = trackRect ? horizonStart + (event.clientX - trackRect.left) / trackRect.width * horizon : operation.start;
    processGestureRef.current = {
      operationId: operation.id,
      startX: event.clientX,
      startY: event.clientY,
      active: false,
      grabOffsetDays: Math.max(0, pointerSerial - operation.start),
    };
    setProcessDragOffset({ x: 0, y: 0 });
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continueProcessPointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) < 6) return;
    gesture.active = true;
    suppressProcessClickRef.current = true;
    setDraggedProcessOperationId(gesture.operationId);
    setProcessDragOffset({ x: event.clientX - gesture.startX, y: event.clientY - gesture.startY });
    setLastDropError("");
    setProcessPointerDropTarget(event.clientX, event.clientY);
  }

  function cancelProcessPointerMove() {
    processGestureRef.current = null;
    processDropTargetRef.current = null;
    setDraggedProcessOperationId(null);
    setProcessDropTarget(null);
    setProcessDragOffset({ x: 0, y: 0 });
  }

  function endProcessPointerMove(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processGestureRef.current;
    if (!gesture) return;
    if (gesture.active) {
      // Resolve the actual release location; never reuse a previously hovered row.
      setProcessPointerDropTarget(event.clientX, event.clientY);
      const target = processDropTargetRef.current;
      try {
        if (!target) throw new Error("İşi geçerli bir proses istasyonu zaman çizgisine bırakın. Taşıma uygulanmadı.");
        previewProcessOperationReschedule(seed, result, gesture.operationId, target.resourceId, target.requestedStart);
        onReviewRoute({ kind: "process", operationId: gesture.operationId, ...target });
        setLastDropError("");
      } catch (error) {
        const message = error instanceof Error ? error.message : "Bu yerleşim uygulanamaz.";
        setLastDropError(message);
        onOperationError(message);
      }
    }
    cancelProcessPointerMove();
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
  }

  function zoom(direction: -1 | 1) {
    const levels = [14, 28, 42, 70, 112, 182, 365];
    const current = levels.indexOf(viewDays);
    const next = levels[Math.max(0, Math.min(levels.length - 1, (current < 0 ? 2 : current) + direction))];
    setViewDays(next);
  }

  function selectGanttProcess(process: ProcessKind) {
    if (process !== ganttProcess) {
      if (ganttProcess === "turning") turningViewportRef.current = { start: viewStart, days: viewDays };
      if (process === "turning") {
        setViewStart(turningViewportRef.current.start);
        setViewDays(turningViewportRef.current.days);
      } else {
        setViewDays(14);
      }
    }
    setGanttProcess(process);
    setLastDropError("");
    setProcessMoveFeedback("");
    setQuery("");
    onSelectProcessOperation("");
    setDiagnosticMachineId(null);
  }

  function fitPlan() {
    const start = Math.floor(planStart);
    setViewStart(start);
    setViewDays(Math.max(14, Math.ceil(planEnd - start + 2)));
  }

  function showDemandMonth(monthId: string) {
    const month = demandMonthOptions.find((item) => item.id === monthId);
    if (!month) return;
    setViewStart(inputDateToSerial(month.start));
    setViewDays(month.dayCount);
  }

  function finishDrag() {
    setDraggedBatchId(null);
    setDropTarget(null);
    dropTargetRef.current = null;
  }

  return (
    <div className="board">
      <div className="gantt-process-tabs" role="tablist" aria-label="Gantt prosesleri" title={ganttProcess === "turning" ? "Torna ana planı · Şarjları sürükleyerek düzenleyebilirsiniz." : `${processLabel(ganttProcess)} kapasite planı · Planlanan işleri sürükleyin; bırakınca hesaplanan yerleşimi inceleyin.`}>
        {productionProcessOrder(seed).map(id => ({ id, label: processLabel(id) })).map((tab) => {
          const workload = operationWorkloads[tab.id];
          const resourceCount = tab.id === "turning"
            ? activeMachines.length
            : (seed.processMasterData?.resources ?? []).filter((resource) => resource.active && resource.process === tab.id).length;
          return <button key={tab.id} role="tab" aria-selected={ganttProcess === tab.id} className={ganttProcess === tab.id ? "active" : ""} onClick={() => selectGanttProcess(tab.id)}><span><ProcessIcon process={tab.id} /> {tab.label}</span><small>{formatNumber(resourceCount)} istasyon · {formatNumber(workload.totalQuantity)} adet</small><b>{formatNumber(workload.totalJobCount)} iş</b></button>;
        })}
        <div className="operation-workload-summary" aria-label={`${processLabel(ganttProcess)} miktar bazlı iş yükü`}>
          <span><small>{ganttProcess === "turning" ? "Tezgahta üretimde" : "Operasyonda çalışan"}</small><strong>{formatNumber(selectedWorkload.activeQuantity)} adet</strong><em>{formatNumber(selectedWorkload.activeJobCount)} iş</em></span>
          <span><small>{ganttProcess === "turning" ? "Torna kuyruğunda" : `${processLabel(ganttProcess)} bekleyen / planlı`}</small><strong>{formatNumber(selectedWorkload.waitingQuantity)} adet</strong><em>{formatNumber(selectedWorkload.waitingJobCount)} iş</em></span>
          <span className="total"><small>Toplam operasyon yükü</small><strong><NumberHelp description="Bu sayılar sipariş toplamı değil; seçili operasyon üzerinde çalışan ve sırada bekleyen üretim miktarlarıdır.">{formatNumber(selectedWorkload.totalQuantity)} adet</NumberHelp></strong><em>{formatNumber(selectedWorkload.totalJobCount)} iş</em></span>
        </div>
      </div>
      {ganttProcess !== "turning" && <div className="process-automatic-reset"><span>Seçili prosesin manuel yerleşimleri kaldırılır; Torna ve çalışan işler korunur.</span><button className="secondary" onClick={() => onReplanProcess(ganttProcess)}><ArrowCounterClockwise size={14} /> {processLabel(ganttProcess)} otomatik plana dön</button></div>}
      <div className="board-tools">
        <div className="search"><MagnifyingGlass size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={ganttProcess === "turning" ? "Tezgah, ürün veya şarj no ara" : "İstasyon, ürün veya şarj no ara"} /></div>
        <div className="gantt-time-controls"><button onClick={() => setViewStart((current) => current - Math.max(1, Math.floor(viewDays / 2)))} aria-label="Zamanı geri al"><CaretLeft size={14} /></button><label><CalendarBlank size={14} /><input type="date" value={serialToInputDate(viewStart)} onChange={(event) => setViewStart(inputDateToSerial(event.target.value))} aria-label="Gantt başlangıç tarihi" /></label><button onClick={() => setViewStart((current) => current + Math.max(1, Math.floor(viewDays / 2)))} aria-label="Zamanı ileri al"><CaretRight size={14} /></button>{demandMonthOptions.length > 0 && <label className="gantt-month-filter"><span>Ay görünümü</span><select value={demandMonthOptions.some((month) => month.id === visibleMonthId) ? visibleMonthId : ""} onChange={(event) => showDemandMonth(event.target.value)} aria-label="Gantt ay görünümü"><option value="" disabled>Ay seçin</option>{demandMonthOptions.map((month) => <option key={month.id} value={month.id}>{month.label}</option>)}</select></label>}<button className="text-control" onClick={() => setViewStart(todaySerial)}>Bugün</button><button className="text-control" onClick={fitPlan}>Planı sığdır</button><span className="zoom-control"><button disabled={viewDays >= 365} onClick={() => zoom(1)} aria-label="Gantt uzaklaştır"><Minus size={13} /></button><small>{viewDays} gün</small><button disabled={viewDays <= 14} onClick={() => zoom(-1)} aria-label="Gantt yakınlaştır"><Plus size={13} /></button></span></div>
        <Menu label="Lejant" title="Gantt lejantı" className="legend-menu">{ganttProcess === "turning" ? <div className="legend"><span><i className="dot running" /> Mevcut üretim</span><span><i className="dot planned" /> Süre = genişlik</span><span><i className="diameter-key" /> {seed.productionArea === "cubuk-filtre" ? "Renk = ürün tipi" : "Renk ve kalınlık = çap"}</span><span><i className="calendar-key shutdown" /> Tatil / Pazar · tıklayıp çalıştır</span><span><i className="calendar-key overtime" /> Mesai</span><span><Lock size={11} /> Kilitli</span></div> : <div className="legend process-legend"><span><ProcessIcon process={ganttProcess} size={13} /> {processLabel(ganttProcess)}</span><span><i className="planned-outline" /> Planlanan</span><span><i className="actual-outline" /> Fiili</span><span><i className="calendar-key shutdown" /> Tatil / Pazar · tıklayıp çalıştır</span>{ganttProcess === "drilling" && seed.productionArea !== "cubuk-filtre" ? [...processSetupHues.entries()].slice(0, 8).map(([setupKey, hue]) => <span key={setupKey}><i className="process-setup-key" style={{ backgroundColor: `hsl(${hue} 82% 88%)`, borderColor: `hsl(${hue} 48% 48%)` }} /> {setupKey}</span>) : <span>{seed.productionArea === "cubuk-filtre" && seed.monthlyCustomerDemand ? "Göz Kontrol sonrası 1 iş günü kalite bekleme" : "GKM sonrası +1 iş günü tampon"}</span>}</div>}{filterLegendProducts.length > 0 && <div className="filter-product-legend" aria-label="Ürün renkleri">{filterLegendProducts.map(product => { const colors = filterProductColors(product); return <span key={product}><i className="process-setup-key" style={{ backgroundColor: colors.background, borderColor: colors.border }} />{product}</span>; })}</div>}</Menu>
        {toolbarActions && <div className="board-actions">{toolbarActions}</div>}
      </div>
      {ganttProcess === "turning" && <WeeklyDemandRibbon rows={weeklyPlanStatus} selectedBatch={evaluatedSelectedBatch} selectedReadyAt={selectedBatchDeliveryReadyAt} splitInsight={selectedSplitInsight} previewing={Boolean(dropPreview?.valid)} coarsePlanning={seed.activePlanRun?.optimizationGoal === "coarse"} onFocusWeek={(dueDate) => { const due = inputDateToSerial(dueDate); setViewStart(due - 6); setViewDays(14); }} />}
      {draggedProcessOperationId && <div className={`gantt-drag-preview process-move-notice ${processDropPreview?.valid ? "valid" : "invalid"}`} role="status"><ProcessIcon process={ganttProcess} /><div><strong>{processDropPreview?.valid ? `${processDropTarget?.resourceId} · ${processDropPreview.preview.insertionIndex + 1}. sıra` : "Bu konuma bırakılamaz"}</strong><span>{processDropPreview?.valid ? `İstenen: ${placementDate(processDropTarget!.requestedStart)} · Hesaplanan: ${placementDate(processDropPreview.operation.start)} – ${placementDate(processDropPreview.operation.end)} · ${processDropPreview.preview.affectedOperations.length} diğer adım etkilenir. ${processDropPreview.preview.adjustments.join(" ")} Bırakınca yerleşimi inceleyin.` : processDropPreview?.reason ?? "Geçerli bir istasyon satırının üzerine sürükleyin. İptal: Esc."}</span></div></div>}
      {processMoveFeedback && !lastDropError && !draggedProcessOperationId && <div className="gantt-drag-preview valid process-move-notice" role="status"><CheckCircle size={18} /><div><strong>Yerleşim uygulandı</strong><span>{processMoveFeedback}</span></div><button onClick={() => setProcessMoveFeedback("")} aria-label="Yerleşim bildirimini kapat"><X size={14} /></button></div>}
      {ganttProcess === "turning" && lastDropError && !draggedBatchId && <div className="gantt-drag-preview invalid"><Warning size={16} weight="fill" /><div><strong>Taşıma uygulanmadı</strong><span>{lastDropError}</span></div><button onClick={() => setLastDropError("")} aria-label="Taşıma uyarısını kapat"><X size={14} /></button></div>}
      {ganttProcess !== "turning" && lastDropError && !draggedProcessOperationId && <div className="gantt-drag-preview invalid process-move-notice" role="alert"><Warning size={16} weight="fill" /><div><strong>{processLabel(ganttProcess)} taşıması uygulanmadı</strong><span>{lastDropError}</span></div><button onClick={() => setLastDropError("")} aria-label="Taşıma uyarısını kapat"><X size={14} /></button></div>}
      {ganttProcess === "turning" && selectedDiagnostic && selectedDiagnosticMachine && <div className={`gantt-diagnostic-strip ${selectedDiagnostic.tone}`}>
        <div className="gantt-diagnostic-machine"><span>TEZGAH BİLGİSİ</span><strong>{selectedDiagnosticMachine.id} · {selectedDiagnosticMachine.name}</strong><small>{selectedDiagnosticMachine.active ? "Planlamada aktif" : "Planlama dışında"}</small></div>
        <div className="gantt-diagnostic-content">
          <div className="gantt-machine-facts"><span><small>Mevcut iş</small><strong>{selectedDiagnosticMachine.currentJob.product || "—"}</strong></span><span><small>İş emri</small><strong>{selectedDiagnosticMachine.currentJob.workOrder || "—"}</strong></span><span><small>Mevcut iş bitişi</small><strong>{formatExcelDate(selectedDiagnosticMachine.currentJob.end)}</strong></span><span><small>Son şarj tipi</small><strong>{selectedLastCharge?.product || selectedDiagnosticMachine.currentJob.product || "—"}</strong></span><span><small>Son şarj ailesi</small><strong>{productSetupFamilyLabel(productSetupFamily(seed, selectedLastCharge?.product || selectedDiagnosticMachine.currentJob.product))}</strong></span><span><small>Son şarj çapı</small><strong>{selectedLastCharge?.diameter || selectedDiagnosticMachine.currentJob.diameter || "—"}</strong></span><span><small>Vardiya</small><strong><NumberHelp description="Bu tezgâhın bir günde çalıştığı vardiya sayısı; günlük kapasiteyi belirler.">{selectedDiagnosticMachine.shiftFactor}</NumberHelp></strong></span><span><small>Plan penceresi</small><strong>{formatExcelDate(selectedDiagnosticMachine.availableStart, { day: "2-digit", month: "short" })} – {formatExcelDate(selectedDiagnosticMachine.planEnd, { day: "2-digit", month: "short" })}</strong></span><span><small>Planlı şarj</small><strong><NumberHelp description="Seçili tezgâhın Gantt kuyruğundaki yeni planlı şarj sayısı.">{selectedDiagnosticBatches.length}</NumberHelp></strong></span></div>
          <div className="gantt-diagnostic-copy">
            {selectedPullForwardAdvice
