        </div>
        <div className="gantt-diagnostic-action">
          {selectedPullForwardAdvice && <button className="machine-pull-forward-action" onClick={() => onApplyAdvice(selectedPullForwardAdvice)}><Lightbulb size={13} weight="fill" /> {selectedPullForwardAdvice.actionLabel}</button>}
          {selectedMachineAdvice.length > 1 && <button className="machine-all-advice-action" onClick={() => onOpenMachineAdvice(selectedDiagnosticMachine.id)}>{selectedMachineAdvice.length} tavsiyenin tümü</button>}
          {!selectedPullForwardAdvice && selectedDiagnostic.suggestion && selectedDiagnostic.suggestion.improvementDays > 0 && <><span>{selectedDiagnostic.suggestion.product}</span><small>{selectedDiagnostic.suggestion.fromMachineId} → {selectedDiagnostic.suggestion.toMachineId}</small><button onClick={() => { onMoveBatch(selectedDiagnostic.suggestion!.batchId, selectedDiagnostic.suggestion!.toMachineId, 0); setDiagnosticMachineId(null); }}>Bu alternatifi uygula</button></>}
          <button className="machine-info-action" onClick={() => setJobEditorMachineId(selectedDiagnosticMachine.id)}><PencilSimple size={13} /> Mevcut işi düzenle</button><button className="machine-info-action complete" disabled={!selectedDiagnosticMachine.currentJob.product} onClick={() => setCompleteMachineId(selectedDiagnosticMachine.id)}><ProcessIcon process="turning" size={14} /> Torna prosesini bitir</button>
        </div>
        <button className="gantt-diagnostic-close" onClick={() => setDiagnosticMachineId(null)} aria-label="Tezgah bilgisini kapat">×</button>
      </div>}
      {ganttProcess !== "turning" && <div className="process-gantt-summary">
        <span><small>Görünen iş</small><strong>{downstreamOperations.length}</strong></span>
        <span><small>Görünen istasyon</small><strong>{processResources.length}</strong></span>
        <span><small>Proses bitişi</small><strong>{downstreamOperations.length ? formatExcelDate(Math.max(...downstreamOperations.map((operation) => operation.end))) : "—"}</strong></span>
        <span><small>Rota + tampon bitişi</small><strong>{downstreamPlan.deliveryCompletion ? formatExcelDate(downstreamPlan.deliveryCompletion) : "—"}</strong></span>
        {selectedProcessOperation && selectedProcessJob ? <div className="process-gantt-selection"><button onClick={() => onSelectProcessOperation("")} aria-label="Seçili proses işini kapat"><X size={13} /></button><p><b>{selectedProcessOperation.product}</b><span>{selectedProcessOperation.workOrder || selectedProcessOperation.batchId} · {formatNumber(selectedProcessOperation.quantity)} adet</span></p><p><b><ProcessIcon process={selectedProcessOperation.process} size={14} /> {processLabel(selectedProcessOperation.process)} seçildi{selectedProcessOperation.manualOverride ? " · manuel yerleşim" : ""}</b><span>Rota sağ panelde açıldı · {selectedProcessOperation.resourceId}</span></p><p><b>Teslimata hazır</b><span>{formatExcelDate(selectedProcessJob.deliveryReadyAt)} · {seed.productionArea === "cubuk-filtre" && seed.monthlyCustomerDemand ? "Göz Kontrol sonrası 1 iş günü kalite bekleme" : "GKM sonrası +1 iş günü"}</span></p>{selectedProcessOperation.manualOverride && <button className="process-auto-placement" onClick={() => onReviewRoute({ kind: "edit", batchId: selectedProcessOperation.batchId, process: selectedProcessOperation.process })}><ArrowCounterClockwise size={12} /> Üretim akışını düzenle</button>}</div> : <p className="process-gantt-hint">Bir işe tıklayın; şarjın tam rotası sağ panelde açılır.</p>}
      </div>}
      <div className={`timeline ${ganttProcess === "turning" ? "turning-timeline" : ""} ${recentMovedBatchId || recentMovedProcessOperationId ? "layout-animated" : ""}`} style={timelineStyle}>
        <div className="timeline-head">
          <div className="machine-title">{ganttProcess === "turning" ? "TEZGAH" : "İSTASYON"}</div>
          {ganttProcess === "turning" && <div className="machine-lock-title" title="Tezgah kuyruğunun tamamını kilitle veya aç"><Lock size={12} /></div>}
          <div className="calendar-scale" aria-label={`${formatExcelDate(horizonStart)} ile ${formatExcelDate(horizonEnd - 1)} arasındaki Gantt takvimi`}>
            <div className="month-scale">
              {ganttCalendar.months.map((month) => <span key={month.key} title={month.fullLabel} style={{ gridColumn: `${month.startIndex + 1} / span ${month.dayCount}` }}>{month.label}</span>)}
            </div>
            <div className="week-scale">
              {ganttCalendar.weeks.map((week) => <span key={week.key} title={week.fullLabel} style={{ gridColumn: `${week.startIndex + 1} / span ${week.dayCount}` }}>{week.label}</span>)}
            </div>
            <div className="day-scale">
              {ganttCalendar.days.map((day) => <span key={day.serial} className={`${day.isSunday ? "sunday" : ""} ${holidaySerials.has(day.serial) ? "holiday" : ""} ${day.serial === todaySerial ? "today" : ""}`} title={day.fullLabel}>{day.dayOfMonth}</span>)}
            </div>
          </div>
