                  return <button key={batch.id} className={`batch ${selectedBatch?.id === batch.id ? "selected" : ""} ${batch.locked ? "locked" : ""} ${batch.manuallyPlaced ? "manual" : ""} ${batch.rolledForwardFrom ? "delayed-plan" : ""} ${batch.pullForward ? "pulled-forward" : ""} ${draggedBatchId === batch.id ? "dragging" : ""} ${recentMovedBatchId === batch.id ? "just-moved" : ""}`} style={{ ...position(batch.start, batch.end, horizonStart, horizon), ...(seed.productionArea === "cubuk-filtre" ? filterProductStyle(batch.product) : diameterStyle(batch.diameter, diameterHues)) }} title={`${batch.product} · ${productSetupFamilyLabel(productSetupFamily(seed, batch.product))} · ${batch.diameter} · Setup ${formatHours(batch.setupHours)} · ${formatExcelDate(batch.start)}–${formatExcelDate(batch.end)}${batch.rolledForwardFrom ? ` · üretime başlanmamış eski plan tarihi ${formatExcelDate(batch.rolledForwardFrom)}; güncel kuyruğa yeniden tarihlendi` : ""} · Talep kaynağı: ${demandLabel}${batch.pullForward ? ` · ${batch.pullForward.sourceWeekLabel} talebinden öne çekildi` : ""}`} onClick={() => { if (suppressBatchClickRef.current) { suppressBatchClickRef.current = false; return; } onSelectBatch(batch.id); }} onPointerDown={(event) => beginPointerMove(event, batch)} onPointerMove={continuePointerMove} onPointerUp={endPointerMove} onPointerCancel={endPointerMove}><span>{batch.pullForward ? <Lightbulb size={10} weight="fill" /> : batch.locked ? <Lock size={10} weight="fill" /> : <DotsSixVertical size={10} />}{batch.product}</span><small>{batch.rolledForwardFrom ? "GECİKMİŞ PLAN · " : batch.pullForward ? `${batch.pullForward.sourceWeekLabel}’den · ` : ""}{demandOrigin ? `${demandOrigin.weekLabel} · ${demandOrigin.shortDateLabel} · ` : "HEDEF HAFTA YOK · "}{batch.diameter} · {formatNumber(batch.quantity)} · {queuePosition(batch.planColumn)}. sıra</small></button>;
                })}
              </div>
            </div>
          );
        }) : processResources.map(({ resource, operations, gaps }) => {
          const calendarDays = processCalendarBandsByResource.get(resource.id) ?? [];
          return <div className="machine-row process-resource-row" key={resource.id}>
            <div className="machine-label process-resource-gantt-label"><span className={`status ${resource.defaultShifts > 0 ? "on" : "off"}`} /><strong>{resource.id}</strong><small>{resource.name}</small><em>{operations.length} iş{gaps.length ? ` · ${gaps.length} açıklama` : ""}</em></div>
            <div className={`track process-resource-track ${processDropTarget?.resourceId === resource.id ? processDropPreview?.valid ? "drop-valid" : "drop-invalid" : ""}`} data-process-resource-id={resource.id}>
              <div className="grid-lines" />
              {calendarDays.map(({ serial, capacity }) => {
                const editable = capacity.kind === "sunday" || capacity.kind === "holiday" || capacity.kind === "shift";
                return <button type="button" key={`${resource.id}-${serial}`} className={`calendar-band ${capacity.kind} ${capacity.shifts > 0 ? "working" : "shutdown"} ${editable ? "editable" : ""}`} style={{ left: `${ganttPercent(serial, horizonStart, horizon)}%`, width: `${100 / horizon}%` }} title={`${formatExcelDate(serial)} · ${capacity.label}${editable ? " · vardiyayı değiştirmek için tıklayın" : ""}`} aria-label={`${resource.id} ${formatExcelDate(serial)} ${capacity.label}${editable ? " üretim ayarı" : ""}`} disabled={!editable} onClick={() => editable && setCalendarSelection({ resourceId: resource.id, process: ganttProcess, serial })} />;
              })}
              {todaySerial >= horizonStart && todaySerial < horizonEnd && <i className="today-line" style={{ left: `${ganttPercent(todaySerial, horizonStart, horizon)}%` }} aria-label="Bugün" />}
              {processDropTarget?.resourceId === resource.id && <>
                <i className="process-drop-request" style={{ left: `${ganttPercent(processDropTarget.requestedStart, horizonStart, horizon)}%` }} />
                {processDropPreview?.valid && <div className="process-drop-placement" style={position(processDropPreview.operation.start, processDropPreview.operation.end, horizonStart, horizon)}><span>{processDropPreview.preview.insertionIndex + 1}. sıra · {placementDate(processDropPreview.operation.start)}</span></div>}
              </>}
              {gaps.map((gap) => <span key={gap.id} className={`process-gap ${gap.code}`} style={position(gap.start, gap.end, horizonStart, horizon)} tabIndex={0} aria-label={`${resource.id} boşluk açıklaması: ${gap.message}`}><Warning size={9} weight="fill" /><span className="process-gap-tooltip" role="tooltip"><strong>{resource.id} · Plan boşluğu</strong><small>{gap.message}</small></span></span>)}
              {operations.map((operation) => <button ref={operation.id === recentMovedProcessOperationId ? movedElementRef : undefined} key={operation.id} className={`batch process-gantt-batch ${operation.process} ${operation.process === "drilling" && !operation.setupKey.trim() ? "missing-setup" : ""} ${operation.actual ? "actual" : "planned"} ${operation.manualOverride ? "manual" : ""} ${draggedProcessOperationId === operation.id ? "dragging" : ""} ${recentMovedProcessOperationId === operation.id ? "just-moved" : ""} ${selectedProcessOperation?.id === operation.id ? "selected" : ""}`} style={{ ...position(operation.start, operation.end, horizonStart, horizon), ...(seed.productionArea === "cubuk-filtre" ? filterProductStyle(operation.product) : processOperationStyle(operation, processSetupHues)), ...(draggedProcessOperationId === operation.id ? { "--process-drag-x": `${processDragOffset.x}px`, "--process-drag-y": `${processDragOffset.y}px` } as React.CSSProperties : {}) }} title={`${operation.product} · ${operation.workOrder || operation.batchId} · ${formatNumber(operation.quantity)} adet${operation.process === "drilling" ? ` · Matkap ${operation.setupKey || "EKSİK"}` : ""} · Setup ${formatHours(operation.setupHours)}${operation.manualOverride ? " · Manuel Gantt yerleşimi" : ""}${operation.protectedSetupHoursAfter ? ` · D-02 Center Pin dönüş rezervi ${formatHours(operation.protectedSetupHoursAfter)}` : ""} · ${formatExcelDate(operation.start)}–${formatExcelDate(operation.end)}`} onClick={() => { if (suppressProcessClickRef.current) { suppressProcessClickRef.current = false; return; } onSelectProcessOperation(operation.id); }} onPointerDown={(event) => beginProcessPointerMove(event, operation)} onPointerMove={continueProcessPointerMove} onPointerUp={endProcessPointerMove} onPointerCancel={cancelProcessPointerMove} onLostPointerCapture={cancelProcessPointerMove}><span>{operation.actual ? <CheckCircle size={10} weight="fill" /> : operation.manualOverride ? <DotsSixVertical size={10} /> : <Clock size={10} />}{operation.product}</span><small>{operation.process === "drilling" ? operation.setupKey ? `${operation.setupKey} · ` : "MATKAP EKSİK · " : ""}{operation.workOrder || `${formatNumber(operation.quantity)} adet`}</small></button>)}
              {!operations.length && <span className="process-resource-empty">{resource.defaultShifts <= 0 ? "0 vardiya · kapasite kapalı" : resource.eligibleProductGroups?.length === 0 ? "Uygun ürün grubu tanımlı değil" : downstreamOperations.length === 0 ? "Prosese hazır WIP yok" : "Bu istasyona uygun ürün / hız yok"}</span>}
            </div>
          </div>;
        })}
      </div>
      {ganttProcess === "turning" && <details className="gantt-operational-details">
        <summary><span><strong>Operasyon özeti · görünen tarih aralığı</strong><small>{formatExcelDate(horizonStart)} – {formatExcelDate(horizonEnd - 1)} · Mesai {formatNumber(operationalMetrics.plannedOvertimeHours)} sa · bakım {formatNumber(operationalMetrics.maintenanceHours)} sa · fason {formatNumber(operationalMetrics.outsourcedQuantity)} adet</small></span><CaretDown size={13} /></summary>
        <div className="gantt-operational-caption" aria-label="Plan operasyon özeti">
          <span><Clock size={14} /><small>Planlanan mesai</small><strong><NumberHelp description="Normal çalışma takviminin üzerine eklenen vardiyaların toplam saat karşılığı.">{formatNumber(operationalMetrics.plannedOvertimeHours)} saat</NumberHelp></strong><em>{formatNumber(operationalMetrics.overtimeShiftCount)} ek vardiya × 8 sa</em></span>
          <span><Wrench size={14} /><small>Bakıma ayrılan</small><strong><NumberHelp description="Bakım tarih aralığındaki her tezgâh-günün 24 saat üzerinden toplamı.">{formatNumber(operationalMetrics.maintenanceHours)} saat</NumberHelp></strong><em>{formatNumber(operationalMetrics.maintenanceMachineDays)} tezgah-gün × 24 sa</em></span>
          <span><ArrowsLeftRight size={14} /><small>Fasona planlanan</small><strong><NumberHelp description="Fason tezgâhlar C-16 ve C-17 üzerindeki planlı şarjların toplam üretim adedi.">{formatNumber(operationalMetrics.outsourcedQuantity)} adet</NumberHelp></strong><em>C-16 + C-17</em></span>
        </div>
        <div className="gantt-operational-entry-list"><div><strong>Bu saatler nereden geliyor?</strong><span>Yalnızca yukarıdaki Gantt tarihleriyle kesişen bakım ve ek vardiya kayıtları gösterilir.</span></div>{operationalMetrics.entries.length ? operationalMetrics.entries.map((entry) => <article key={`${entry.kind}-${entry.id}`}><span className={entry.kind}>{entry.kind === "maintenance" ? <Wrench size={14} /> : <Clock size={14} />}</span><div><strong>{entry.machineId} · {entry.name}</strong><small>{formatExcelDate(entry.start)}{entry.end !== entry.start ? ` – ${formatExcelDate(entry.end)}` : ""}</small></div><em>{formatNumber(entry.hours)} saat</em></article>) : <p>Bu tarih aralığında bakım veya ek vardiya kaydı yok.</p>}</div>
      </details>}
      {ganttProcess === "turning" && jobEditorMachineId && <CurrentJobEditor seed={seed} result={result} machine={seed.machines.find((machine) => machine.id === jobEditorMachineId)!} onClose={() => setJobEditorMachineId(null)} onSave={(input, remainingAsOf) => { onSaveCurrentJob(jobEditorMachineId, input, remainingAsOf); setJobEditorMachineId(null); setDiagnosticMachineId(jobEditorMachineId); }} />}
      {ganttProcess === "turning" && completeMachineId && <CompleteJobDialog machine={seed.machines.find((machine) => machine.id === completeMachineId)!} nextBatch={plannedBatches.filter((batch) => batch.machineId === completeMachineId).sort((left, right) => left.planColumn - right.planColumn)[0]} onClose={() => setCompleteMachineId(null)} onConfirm={(completedAt, completedQuantity) => { onCompleteCurrentJob(completeMachineId, completedAt, completedQuantity); setCompleteMachineId(null); setDiagnosticMachineId(completeMachineId); }} />}
      {calendarSelection && calendarCapacityTarget && <GanttCapacityDialog seed={seed} machine={calendarCapacityTarget} serial={calendarSelection.serial} resourceKind={calendarSelection.process === "turning" ? "tezgah" : "istasyon"} allScopeLabel={calendarSelection.process === "turning" ? "Tüm aktif tezgahlar" : `Tüm aktif ${processLabel(calendarSelection.process)} istasyonları`} onClose={() => setCalendarSelection(null)} onSave={(scope, name, start, end, shifts, editingId) => { updateSeed((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); } const resourceIds = scope === "all"
        ? calendarSelection.process === "turning"
          ? draft.machines.filter((machine) => machine.active).map((machine) => machine.id)
          : (draft.processMasterData?.resources ?? []).filter((resource) => resource.active && resource.process === calendarSelection.process).map((resource) => resource.id)
        : [calendarSelection.resourceId];
        replaceMachineShiftOverrides(draft, resourceIds, start, end, shifts, name); }); setCalendarSelection(null); }} onDelete={(eventId) => { updateSeed((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === eventId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); }); setCalendarSelection(null); }} />}
    </div>
  );
}

function GanttCapacityDialog({ seed, machine, serial, resourceKind, allScopeLabel, onClose, onSave, onDelete }: { seed: PlanningSeed; machine: Pick<Machine, "id" | "shiftFactor">; serial: number; resourceKind: "tezgah" | "istasyon"; allScopeLabel: string; onClose: () => void; onSave: (scope: "machine" | "all", name: string, start: number, end: number, shifts: ShiftCount, editingId?: string) => void; onDelete: (eventId: string) => void }) {
  const capacity = machineDayCapacity(seed, machine, serial);
  const existingShift = [...(seed.calendarEvents ?? [])].reverse().find((event) => event.machineId === machine.id && event.kind === "shift" && serial >= Math.floor(event.start) && serial <= Math.floor(event.end));
  const [scope, setScope] = useState<"machine" | "all">("machine");
  const [draft, setDraft] = useState<{ name: string; start: string; end: string; shifts: ShiftCount }>({ name: existingShift?.name ?? `${formatExcelDate(serial)} Gantt vardiya ayarı`, start: serialToInputDate(existingShift?.start ?? serial), end: serialToInputDate(existingShift?.end ?? serial), shifts: capacity.kind === "shift" ? capacity.shifts : capacity.shifts || clampShiftCount(machine.shiftFactor) || 1 });
  const start = inputDateToSerial(draft.start);
  const end = inputDateToSerial(draft.end);
  const valid = Boolean(draft.name.trim() && start && end && end >= start);
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog capacity-dialog" role="dialog" aria-modal="true" aria-label={`${formatExcelDate(serial)} üretim ayarı`}><div className="operational-dialog-head"><span className={`dialog-icon ${capacity.kind}`}><CalendarBlank size={20} /></span><div><span>GANTT KAPASİTE AYARI</span><h2>{existingShift ? "Vardiya kaydını düzenle" : formatExcelDate(serial)}</h2><p>{capacity.label} · {machine.id} {resourceKind} kapasitesi {capacity.shifts} vardiya.</p></div><button className="delete-button" onClick={onClose} aria-label="Kapasite ayarını kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label={`Uygulanacak ${resourceKind}lar`}><select value={scope} onChange={(event) => setScope(event.target.value as "machine" | "all")}><option value="machine">Yalnızca {machine.id}</option><option value="all">{allScopeLabel}</option></select></Field><Field label="Açıklama"><input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></Field><div className="dialog-date-range"><Field label="Başlangıç"><input type="date" value={draft.start} onChange={(event) => setDraft({ ...draft, start: event.target.value, end: event.target.value > draft.end ? event.target.value : draft.end })} /></Field><Field label="Bitiş"><input type="date" min={draft.start} value={draft.end} onChange={(event) => setDraft({ ...draft, end: event.target.value })} /></Field></div><Field label="Çalışılacak vardiya"><select value={draft.shifts} onChange={(event) => setDraft({ ...draft, shifts: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field><div className="calendar-impact-note"><strong>{draft.shifts === 0 ? "Üretim yapılmayacak" : `${draft.shifts} vardiya üretim açılacak`}</strong><span>Kaydettiğinizde mevcut kuyruk korunur ve bütün başlangıç/bitiş tarihleri hemen yeniden hesaplanır.</span></div><div className="drawer-actions">{existingShift && <button className="danger-outline" onClick={() => onDelete(existingShift.id)}><Trash size={14} /> Kaydı kaldır</button>}<button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(scope, draft.name.trim(), start, end, draft.shifts, existingShift?.id)}>{existingShift ? "Değişikliği kaydet" : "Uygula ve hesapla"}</button></div></div></section></div>;
}

function position(start: number, end: number, horizonStart: number, horizon: number): React.CSSProperties {
  const horizonEnd = horizonStart + horizon;
  if (end <= horizonStart || start >= horizonEnd) return { display: "none" };
  const visibleStart = Math.max(start, horizonStart);
  const visibleEnd = Math.min(end, horizonEnd);
  return { left: `${ganttPercent(visibleStart, horizonStart, horizon)}%`, width: `${Math.max(0.8, ganttPercent(visibleEnd, visibleStart, horizon))}%` };
}

function diameterStyle(rawDiameter: string, hues: Map<number, number>): React.CSSProperties {
  const diameter = diameterNumeric(rawDiameter) || 20;
  const ratio = Math.max(0, Math.min(1, (diameter - 14) / 19));
  const height = Math.round(30 + ratio * 16);
  const hue = hues.get(diameter) ?? 24;
  return {
    "--batch-height": `${height}px`,
    "--batch-bg": `hsl(${hue} 82% 93%)`,
    "--batch-border": `hsl(${hue} 48% 50%)`,
    "--batch-ink": `hsl(${hue} 65% 24%)`,
  } as React.CSSProperties;
}

function buildProcessSetupHues(operations: ProcessOperation[]): Map<string, number> {
  const setupKeys = [...new Set(operations
    .filter((operation) => operation.process === "drilling" && operation.setupKey.trim())
    .map((operation) => operation.setupKey.trim()))]
    .sort((left, right) => left.localeCompare(right, "tr", { numeric: true }));
  return new Map(setupKeys.map((setupKey, index) => [setupKey, DIAMETER_HUE_WHEEL[index % DIAMETER_HUE_WHEEL.length]]));
}

function processOperationStyle(operation: ProcessOperation, hues: Map<string, number>): React.CSSProperties {
  if (operation.process !== "drilling" || !operation.setupKey.trim()) return {};
  const hue = hues.get(operation.setupKey.trim()) ?? DIAMETER_HUE_WHEEL[0];
  return {
    "--batch-bg": `hsl(${hue} 82% 93%)`,
    "--batch-border": `hsl(${hue} 48% 50%)`,
    "--batch-ink": `hsl(${hue} 65% 24%)`,
  } as React.CSSProperties;
}

frontend/features/planning/board/PlanRun.source:
"use client";
import { buildFilterMonthlyOrders } from "@/lib/filter-monthly-demand";

import { useRaviScreenContext } from "@/features/ravi/context";

import { Field, NumberHelp } from "@/features/planning/shared/controls";
import { formatFactoryDateTime, formatHours, formatInputDate, formatPercent, formatPlanningWeek } from "@/features/planning/shared/format";
import { type DeliveryDeductionPreview, calculateDeliveryDeduction, orderImportMetadataForSeed } from "@/lib/delivery-deduction";
import { factoryDateTimeInput } from "@/lib/factory-time";
import { deliveryCutoffFromInput, reviewDeliveryCoverage } from "@/lib/delivery-coverage-review";
import { formatDecimal, formatInteger as formatNumber } from "@/lib/number-format";
import { type PlanComparisonRow, type PlanRunRequest, optimizationGoalLabel, defaultPlanRunShortagePolicy, planRunDeliveryHistory } from "@/lib/plan-run";
import { type OptimizationGoal, type PlannedBatch, type PlanningSeed, excelSerialToDate, formatExcelDate } from "@/lib/planning";
import {
  type PlanningWeekRange,
  buildWeeklyPlanningState,
  planningWeekRangesForScope,
  previewFromDataset,
  resolvePlanningWeekRanges,
  weeklyScopeDemandSummary,
} from "@/lib/weekly-demand";
import { ArrowClockwise, CalendarBlank, ChartBar, CheckCircle, FileXls, Lock, Play, Plus, Question, Warning, X } from "@phosphor-icons/react";
import { useEffect, useState } from "react";

type PlanRunSection = "none" | "mode" | "scope" | "goal" | "threshold" | "source" | "warn";

export function PlanRunDialog({ seed, batches, existingPlanAvailable, existingPlannedBatchCount, lockedBatchCount, onClose, onCompare, onRun }: { seed: PlanningSeed; batches: PlannedBatch[]; existingPlanAvailable: boolean; existingPlannedBatchCount: number; lockedBatchCount: number; onClose: () => void; onCompare: (request: PlanRunRequest) => PlanComparisonRow[]; onRun: (request: PlanRunRequest) => void }) {
  const customerDemand = seed.customerDemand;
  const monthlyDemand = seed.productionArea === "cubuk-filtre" && Boolean(seed.monthlyCustomerDemand);
  const defaultShortagePolicy = defaultPlanRunShortagePolicy(seed);
  const availableWeeks = customerDemand?.weeks ?? [];
  const replaceWeekRanges = customerDemand
    ? planningWeekRangesForScope(customerDemand.activeScope)
    : [];
  const activeEndWeekIndex = customerDemand
    ? availableWeeks.findIndex((week) => week.id === customerDemand.activeScope.endWeekId)
    : -1;
  const sequencePending = Boolean(seed.planRunSequence && seed.planRunSequence.completedRangeCount < seed.planRunSequence.ranges.length);
  const continuationWeek = availableWeeks[activeEndWeekIndex + 1];
  const appendAvailable = Boolean(
    ((customerDemand && seed.activePlanRun?.scope.kind === "customer-weeks" && !sequencePending && continuationWeek)
      || (monthlyDemand && seed.activePlanRun?.scope.kind === "production-dates"))
    && existingPlanAvailable,
  );
  const continuationWeekRanges = continuationWeek
    ? [{ startWeekId: continuationWeek.id, endWeekId: continuationWeek.id }]
    : [];
  const completedRangeCount = seed.activePlanRun?.scope.ranges?.length
    ?? (seed.activePlanRun?.scope.kind === "customer-weeks" ? 1 : 0);
  const existingOptimizationGoal = seed.planRunSequence?.optimizationGoal
    ?? seed.activePlanRun?.optimizationGoal
    ?? "earliest-finish";
  const existingIncludePriorBacklog = seed.planRunSequence?.includePriorBacklog
    ?? seed.activePlanRun?.includePriorBacklog
    ?? true;
  const existingAllowProductionBeforeScope = seed.planRunSequence?.allowProductionBeforeScope
    ?? seed.activePlanRun?.allowProductionBeforeScope
    ?? true;
  const existingShortageExtraCharge = monthlyDemand ? defaultShortagePolicy : seed.planRunSequence?.shortageExtraCharge
    ?? seed.activePlanRun?.shortageExtraCharge
    ?? { enabled: true, thresholdPercent: 50 };
  const orderImport = orderImportMetadataForSeed(seed);
  const existingDeliveryFilter = seed.monthlyCustomerDemand && orderImport ? {enabled:true,startAt:orderImport.shipmentsThrough ?? orderImport.importedAt,includeStart:false,endAt:new Date().toISOString()} : seed.planRunSequence?.deliveryDeductionFilter
    ?? seed.activePlanRun?.deliveryDeduction?.filter;
  const activeMachines = seed.machines.filter((machine) => machine.active);
  const initialStart = Math.min(...activeMachines.map((machine) => machine.availableStart).filter((value) => value > 0));
  const initialEnd = Math.max(0, ...activeMachines.map((machine) => machine.planEnd));
  const [appendToExistingPlan, setAppendToExistingPlan] = useState(appendAvailable);
  const [weekRanges, setWeekRanges] = useState<PlanningWeekRange[]>(appendAvailable ? continuationWeekRanges : replaceWeekRanges);
  const [productionStartDate, setProductionStartDate] = useState(seed.monthlyCustomerDemand?.startDate ?? (Number.isFinite(initialStart) ? excelSerialToDate(initialStart).toISOString().slice(0, 10) : ""));
  const [productionEndDate, setProductionEndDate] = useState(seed.monthlyCustomerDemand?.endDate ?? (initialEnd ? excelSerialToDate(initialEnd).toISOString().slice(0, 10) : ""));
  const [optimizationGoal, setOptimizationGoal] = useState<OptimizationGoal>(appendAvailable ? existingOptimizationGoal : "earliest-finish");
  const [includePriorBacklog, setIncludePriorBacklog] = useState(appendAvailable ? existingIncludePriorBacklog : false);
  const [allowProductionBeforeScope, setAllowProductionBeforeScope] = useState(appendAvailable ? existingAllowProductionBeforeScope : false);
  const [addExtraChargeForShortage, setAddExtraChargeForShortage] = useState(appendAvailable ? existingShortageExtraCharge.enabled : defaultShortagePolicy.enabled);
  const [shortageThresholdPercent, setShortageThresholdPercent] = useState(appendAvailable ? existingShortageExtraCharge.thresholdPercent : defaultShortagePolicy.thresholdPercent);
  const [deductDeliveries, setDeductDeliveries] = useState(existingDeliveryFilter?.enabled ?? Boolean(orderImport));
  const [deliveryStartDateTime, setDeliveryStartDateTime] = useState(() => factoryDateTimeInput(existingDeliveryFilter?.startAt ?? orderImport?.shipmentsThrough ?? orderImport?.importedAt ?? new Date()));
  const [deliveryCutoffReference, setDeliveryCutoffReference] = useState<string | undefined>(existingDeliveryFilter?.startAt ?? orderImport?.shipmentsThrough ?? orderImport?.importedAt);
  const [includeDeliveryStart, setIncludeDeliveryStart] = useState(existingDeliveryFilter?.includeStart ?? !orderImport?.shipmentsThrough);
  const [reviewedDeliveryCoverageKey, setReviewedDeliveryCoverageKey] = useState<string | undefined>();
  const [error, setError] = useState("");
  const [comparison, setComparison] = useState<PlanComparisonRow[]>([]);
  const [comparing, setComparing] = useState(false);
  const [openSection, setOpenSection] = useState<PlanRunSection>("none");
  let resolvedWeekRanges: ReturnType<typeof resolvePlanningWeekRanges> = [];
  let rangeValidationError = "";
  if (customerDemand) {
    try {
      resolvedWeekRanges = resolvePlanningWeekRanges(customerDemand.weeks, weekRanges);
    } catch (reason) {
      rangeValidationError = reason instanceof Error ? reason.message : "Hafta aralıklarını kontrol edin.";
    }
  }
  const scopeRangeValid = customerDemand
    ? resolvedWeekRanges.length === weekRanges.length && !rangeValidationError
    : Boolean(productionStartDate && productionEndDate && productionStartDate <= productionEndDate
      && (!monthlyDemand || !appendToExistingPlan || (seed.activePlanRun?.scope.kind === "production-dates"
        && productionEndDate > seed.activePlanRun.scope.endDate
        && Date.parse(productionStartDate) <= Date.parse(seed.activePlanRun.scope.endDate) + 86_400_000)));
  const firstResolvedRange = resolvedWeekRanges[0];
  const deliveryPreviewRange = customerDemand && firstResolvedRange
    ? {
        startWeekId: appendToExistingPlan && seed.activePlanRun?.scope.kind === "customer-weeks"
          ? seed.activePlanRun.scope.startWeekId ?? firstResolvedRange.startWeekId
          : firstResolvedRange.startWeekId,
        endWeekId: firstResolvedRange.endWeekId,
      }
    : null;
  const demandSummary = customerDemand && firstResolvedRange
    ? weeklyScopeDemandSummary(previewFromDataset(customerDemand), {
        startWeekId: firstResolvedRange.startWeekId,
        endWeekId: firstResolvedRange.endWeekId,
      })
    : null;
  let deliveryPreview: DeliveryDeductionPreview | null = null;
  let deliveryPreviewError = "";
  if (orderImport && scopeRangeValid) {
    try {
      const startAt = deliveryCutoffFromInput(deliveryStartDateTime, deliveryCutoffReference);
      if (!startAt) throw new Error("Teslimat başlangıç tarihini ve saatini kontrol edin.");
      const grossOrders = customerDemand && deliveryPreviewRange
        ? buildWeeklyPlanningState(
            previewFromDataset(customerDemand),
            seed.orders,
            deliveryPreviewRange,
            seed.customerOrderOverrides,
            { includePriorBacklog },
          ).orders
        : seed.monthlyCustomerDemand ? buildFilterMonthlyOrders(seed,{...seed.monthlyCustomerDemand,startDate:appendToExistingPlan && seed.activePlanRun?.scope.kind === "production-dates" ? seed.activePlanRun.scope.startDate : productionStartDate,endDate:productionEndDate}).orders : seed.orderImportGrossOrders ?? seed.orders;
      deliveryPreview = calculateDeliveryDeduction({
        orders: grossOrders,
        productionHistory: planRunDeliveryHistory(seed),
        orderImport,
        importProducts: customerDemand?.products.map((product) => product.product) ?? seed.orderCatalog ?? seed.orders.map((order) => order.product),
        filter: {
          enabled: deductDeliveries,
          startAt,
          includeStart: includeDeliveryStart,
          endAt: appendToExistingPlan && !monthlyDemand && existingDeliveryFilter ? existingDeliveryFilter.endAt : new Date().toISOString(),
        },
      });
    } catch (reason) {
      deliveryPreviewError = reason instanceof Error ? reason.message : "Teslimatlar ihtiyaçtan düşülemedi.";
    }
  }
  const shortageThresholdValid = Number.isFinite(shortageThresholdPercent) && shortageThresholdPercent >= 0 && shortageThresholdPercent <= 100;
  const fixedBatches = batches.filter(batch => batch.status === "planned" && (appendToExistingPlan || batch.locked || batch.routeCommitted));
  const deliveryReview = reviewDeliveryCoverage(seed, deliveryPreview, fixedBatches, { enabled: addExtraChargeForShortage, thresholdPercent: shortageThresholdValid ? shortageThresholdPercent : defaultShortagePolicy.thresholdPercent });
  const deliveryReviewPending = Boolean(deliveryReview && deliveryReview.key !== reviewedDeliveryCoverageKey);
  useRaviScreenContext("plan-run-dialog", { appendToExistingPlan, monthlyIncrementalPlanning: monthlyDemand && appendToExistingPlan, weekRanges, productionStartDate, productionEndDate,
    optimizationGoal, includePriorBacklog, allowProductionBeforeScope, addExtraChargeForShortage, shortageThresholdPercent, deductDeliveries, deliveryStartDateTime,
    deliveryCutoffInstant: deliveryCutoffFromInput(deliveryStartDateTime, deliveryCutoffReference),
    includeDeliveryStart, comparison, error, excludedDeliveryProducts: deliveryReview?.products,
    excludedDeliveries: deliveryReview?.items.slice(0, 20), excludedDeliveryCount: deliveryReview?.items.length ?? 0, deliveryReviewPending });
  const dateRangeValid = scopeRangeValid && !deliveryPreviewError;
  const weekRangeSignature = weekRanges.map((range) => `${range.startWeekId}:${range.endWeekId}`).join("|");
  const lastSelectedWeekIndex = customerDemand && weekRanges.length
    ? availableWeeks.findIndex((week) => week.id === weekRanges.at(-1)?.endWeekId)
    : -1;
  const coarsePlanning = optimizationGoal === "coarse";
  const canAddWeekRange = Boolean(customerDemand && lastSelectedWeekIndex >= 0 && lastSelectedWeekIndex < availableWeeks.length - 1);
  const goals: Array<{ id: OptimizationGoal; title: string; detail: string }> = [
    { id: "coarse", title: "Standart planlama", detail: "Her aralığın toplam talebini tek üretim penceresinde ürün ve çap kampanyalarıyla planlar." },
    { id: "balanced", title: "Dengeli planlama", detail: "Aynı ürün ve çap kampanyalarını korurken uygun alternatiflerde kapasite yükünü dengeler." },
    { id: "earliest-finish", title: "En erken bitiş", detail: "Her şarjı setup dahil en erken tamamlayan uygun tezgahı seçer." },
    { id: "minimum-setup", title: "Setup’ı azalt", detail: "Aynı ürün ve çap kampanyalarını koruyarak tezgah değişim süresini azaltır." },
  ];
  useEffect(() => {
    setComparison([]);
    setError("");
  }, [weekRangeSignature, productionStartDate, productionEndDate, includePriorBacklog, allowProductionBeforeScope, addExtraChargeForShortage, shortageThresholdPercent, deductDeliveries, deliveryStartDateTime, includeDeliveryStart]);
  useEffect(() => { setReviewedDeliveryCoverageKey(undefined); }, [deliveryReview?.key]);
  useEffect(() => { if (deliveryReviewPending) setOpenSection("warn"); }, [deliveryReviewPending]);

  function toggleSection(section: PlanRunSection) {
    setOpenSection((current) => (current === section ? "none" : section));
  }

  function selectPlanMode(append: boolean) {
    setAppendToExistingPlan(append);
    setWeekRanges(append ? continuationWeekRanges : replaceWeekRanges);
    setOptimizationGoal(append ? existingOptimizationGoal : "earliest-finish");
    setIncludePriorBacklog(append ? existingIncludePriorBacklog : false);
    setAllowProductionBeforeScope(append ? existingAllowProductionBeforeScope : false);
    setAddExtraChargeForShortage(append ? existingShortageExtraCharge.enabled : defaultShortagePolicy.enabled);
    setShortageThresholdPercent(append ? existingShortageExtraCharge.thresholdPercent : defaultShortagePolicy.thresholdPercent);
    const filter = append ? existingDeliveryFilter : undefined;
    setDeductDeliveries(filter?.enabled ?? Boolean(orderImport));
    setDeliveryStartDateTime(factoryDateTimeInput(filter?.startAt ?? orderImport?.shipmentsThrough ?? orderImport?.importedAt ?? new Date()));
    setDeliveryCutoffReference(filter?.startAt ?? orderImport?.shipmentsThrough ?? orderImport?.importedAt);
    setIncludeDeliveryStart(filter?.includeStart ?? !orderImport?.shipmentsThrough);
    setComparison([]);
    setError("");
  }

  function updateWeekRange(index: number, field: keyof PlanningWeekRange, value: string) {
    setWeekRanges((current) => {
      const next = current.map((range) => ({ ...range }));
      next[index] = { ...next[index], [field]: value };
      const startIndex = availableWeeks.findIndex((week) => week.id === next[index].startWeekId);
      const endIndex = availableWeeks.findIndex((week) => week.id === next[index].endWeekId);
      if (startIndex >= 0 && (endIndex < startIndex || endIndex < 0)) next[index].endWeekId = next[index].startWeekId;
      for (let cursor = index + 1; cursor < next.length; cursor += 1) {
        const previousEnd = availableWeeks.findIndex((week) => week.id === next[cursor - 1].endWeekId);
        const requiredStart = availableWeeks[previousEnd + 1];
        if (!requiredStart) break;
        next[cursor].startWeekId = requiredStart.id;
        const currentEnd = availableWeeks.findIndex((week) => week.id === next[cursor].endWeekId);
        if (currentEnd < previousEnd + 1) next[cursor].endWeekId = requiredStart.id;
      }
      return next;
    });
  }

  function addWeekRange() {
    if (!canAddWeekRange) return;
    const nextWeek = availableWeeks[lastSelectedWeekIndex + 1];
    setWeekRanges((current) => [...current, { startWeekId: nextWeek.id, endWeekId: nextWeek.id }]);
  }

  function selectOptimizationGoal(goal: OptimizationGoal) {
    setOptimizationGoal(goal);
    if (goal === "coarse") setAllowProductionBeforeScope(false);
    setComparison([]);
    setError("");
  }

  function removeWeekRange(index: number) {
    setWeekRanges((current) => {
      const next = current.filter((_, currentIndex) => currentIndex !== index).map((range) => ({ ...range }));
      for (let cursor = Math.max(1, index); cursor < next.length; cursor += 1) {
        const previousEnd = availableWeeks.findIndex((week) => week.id === next[cursor - 1].endWeekId);
        const requiredStart = availableWeeks[previousEnd + 1];
        if (!requiredStart) break;
        next[cursor].startWeekId = requiredStart.id;
        const currentEnd = availableWeeks.findIndex((week) => week.id === next[cursor].endWeekId);
        if (currentEnd < previousEnd + 1) next[cursor].endWeekId = requiredStart.id;
      }
      return next;
    });
  }

  function request(): PlanRunRequest {
    return {
      optimizationGoal,
      appendToExistingPlan: customerDemand || monthlyDemand ? appendToExistingPlan : undefined,
      includePriorBacklog: customerDemand ? includePriorBacklog : undefined,
      allowProductionBeforeScope: customerDemand ? allowProductionBeforeScope : undefined,
      weekRanges: customerDemand ? weekRanges : undefined,
      productionStartDate: customerDemand ? undefined : productionStartDate,
      productionEndDate: customerDemand ? undefined : productionEndDate,
      shortageExtraCharge: { enabled: addExtraChargeForShortage, thresholdPercent: shortageThresholdPercent },
      deliveryDeduction: orderImport ? {
        enabled: deductDeliveries,
        startAt: deliveryCutoffFromInput(deliveryStartDateTime, deliveryCutoffReference),
        includeStart: includeDeliveryStart,
      } : undefined,
      reviewedDeliveryCoverageKey,
    };
  }

  function submit() {
    setError("");
    try {
      if (!dateRangeValid) throw new Error("Geçerli bir planlama kapsamı seçin.");
      if (!Number.isFinite(shortageThresholdPercent) || shortageThresholdPercent < 0 || shortageThresholdPercent > 100) throw new Error("Eksik şarj eşiği 0 ile 100 arasında olmalıdır.");
      if (deliveryReviewPending) throw new Error("Önce dışarıda kalan teslimatları kontrol edin.");
      onRun(request());
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Plan çalıştırılamadı.");
    }
  }

  function runComparison() {
    if (!dateRangeValid) return;
    setComparing(true);
    setError("");
    window.setTimeout(() => {
      try {
        setComparison(onCompare(request()));
      } catch (reason) {
        setError(reason instanceof Error ? reason.message : "Seçenekler karşılaştırılamadı.");
      } finally {
        setComparing(false);
      }
    }, 0);
  }

  const routeCommittedCount = (seed.manualBatches ?? []).filter((batch) => batch.routeCommitted && !batch.locked).length;
  const protectionHeadline = appendToExistingPlan
    ? `${existingPlannedBatchCount} mevcut şarj korunacak`
    : `${lockedBatchCount} kilitli şarj ve ${routeCommittedCount} akış tercihi olan şarj korunacak`;
  const protectionDetail = appendToExistingPlan
    ? "Manuel düzenlemeler ve öne çekilmiş üretimler dahil mevcut Gantt değişmeden kalır; yalnızca kalan ihtiyaç arkasına eklenir."
    : "Mevcut çalışan işler, kilitli kuyruk önekleri ve akış tercihi kaydedilen şarjlar sabit kalır. Akış tercihlerini Üretim akışını düzenle ile kaldırabilirsiniz.";
  const lastResolvedRange = resolvedWeekRanges.at(-1);
  const scopeClause = customerDemand
    ? scopeRangeValid && firstResolvedRange
      ? resolvedWeekRanges.length > 1 ? `${firstResolvedRange.label} +${resolvedWeekRanges.length - 1} aralık` : firstResolvedRange.label
      : "Kapsam seçilemedi"
    : dateRangeValid ? `${formatInputDate(productionStartDate)}–${formatInputDate(productionEndDate)}` : "Tarih seçilmedi";
  const scopeWord = customerDemand ? resolvedWeekRanges.length > 1 ? "aralıklarını" : "aralığını" : "arasında";
  const activeGoalTitle = goals.find((goal) => goal.id === optimizationGoal)?.title ?? optimizationGoalLabel(optimizationGoal);
  const scopeDatesLabel = firstResolvedRange && lastResolvedRange
    ? `${formatInputDate(firstResolvedRange.startDate)}–${formatInputDate(lastResolvedRange.endDate)}`
    : rangeValidationError || "Kapsam seçilemedi";
  const primaryLabel = appendToExistingPlan
    ? weekRanges.length > 1 ? "İlk yeni aralığı ekle" : "Aralığı plana ekle"
    : customerDemand && weekRanges.length > 1 ? "İlk aralığı planla" : "Planı oluştur";
  const alerts: Array<{ id: string; tone: string; label: string }> = [];
  if (!scopeRangeValid) alerts.push({ id: "scope", tone: "block", label: rangeValidationError || (monthlyDemand && appendToExistingPlan ? "Bitişi mevcut kapsamdan sonraya uzatın; kapsamda gün boşluğu bırakmayın" : "Planlama kapsamı seçilemedi") });
  if (!shortageThresholdValid) alerts.push({ id: "threshold", tone: "block", label: "Eksik şarj eşiği 0–100 arasında olmalı" });
  if (deliveryPreviewError) alerts.push({ id: "delivery-error", tone: "block", label: deliveryPreviewError });
  if (deliveryReviewPending) alerts.push({ id: "coverage", tone: "block", label: `${deliveryReview?.items.length ?? 0} teslimat kapsam dışında — onayınız gerekiyor` });
  if (deliveryPreview && deliveryPreview.snapshot.excessDeliveryQuantity > 0) alerts.push({ id: "excess", tone: "warn", label: "İhtiyaçtan fazla teslimat var" });
  if (deliveryPreview && deliveryPreview.unmatchedItems.length > 0) alerts.push({ id: "unmatched", tone: "warn", label: `${deliveryPreview.unmatchedItems.length} teslimat Excel ile eşleşmedi` });
  if (coarsePlanning) alerts.push({ id: "coarse", tone: "warn", label: "Haftalık teslimat kontrolü kapalı" });
  alerts.push({ id: "protection", tone: "info", label: protectionHeadline });

  return (
    <div className="confirmation-backdrop plan-run-backdrop" role="presentation">
      <section className="operational-dialog plan-run-dialog summary-first" role="dialog" aria-modal="true" aria-label="Planı çalıştır">
        <div className="operational-dialog-head">
          <span className="dialog-icon plan-run"><Play size={20} weight="fill" /></span>
          <div>
            <span>PLAN OLUŞTUR</span>
            <h2>Bu plan çalıştırılacak</h2>
            <p>{customerDemand ? `${customerDemand.sourceFile} · talepler ISO hafta Cumartesi terminine göre kapsama alınır.` : seed.monthlyCustomerDemand ? "Aylık ihtiyaç seçilen çalışma günlerine dağıtılır. Yeni üretim, depo/ambalaj hazır olma tarihinden geriye planlanır. Stok ve kayıtlı işler önce ihtiyacı karşılar." : "Siparişler seçilen üretim tarihleri içinde uygun tezgahlara yerleştirilir."} Değiştirmek istediğiniz kısma tıklayın; dokunmadığınız her şey son çalıştırmadaki gibi kalır.</p>
          </div>
          <button className="delete-button" onClick={onClose} aria-label="Plan çalıştırma penceresini kapat"><X size={16} /></button>
        </div>
        <div className="plan-run-flow">
          <p className="plan-run-sentence">
            {appendAvailable && <>
              <button type="button" className={`plan-run-clause ${openSection === "mode" ? "selected" : ""}`} aria-expanded={openSection === "mode"} onClick={() => toggleSection("mode")}>{appendToExistingPlan ? monthlyDemand ? "Kademeli planlama" : "Planın devamına ekle" : "Planı baştan oluştur"}</button>
              <span>,</span>
            </>}
            <button type="button" className={`plan-run-clause ${openSection === "scope" ? "selected" : ""} ${scopeRangeValid ? "" : "invalid"}`} aria-expanded={openSection === "scope"} onClick={() => toggleSection("scope")}>{scopeClause}</button>
            <span>{scopeWord}</span>
            {appendToExistingPlan && <Lock size={12} className="plan-run-clause-lock" />}
            <button type="button" className={`plan-run-clause ${openSection === "goal" ? "selected" : ""} ${appendToExistingPlan ? "muted" : ""}`} aria-expanded={openSection === "goal"} onClick={() => toggleSection("goal")}>{seed.monthlyCustomerDemand ? `${activeGoalTitle} + geriye planlama` : activeGoalTitle}</button>
            <span>hedefiyle planla.</span>
            {appendToExistingPlan && <Lock size={12} className="plan-run-clause-lock" />}
            <button type="button" className={`plan-run-clause ${openSection === "threshold" ? "selected" : ""} ${appendToExistingPlan ? "muted" : ""}`} aria-expanded={openSection === "threshold"} onClick={() => toggleSection("threshold")}>{addExtraChargeForShortage ? `Eksik ≥ %${formatDecimal(shortageThresholdPercent)} ise ek şarj` : "Eksik için ek şarj kapalı"}</button>
            <span>.</span>
            {orderImport && <>
              <button type="button" className={`plan-run-clause ${openSection === "source" ? "selected" : ""}`} aria-expanded={openSection === "source"} onClick={() => toggleSection("source")}>{orderImport.sourceFile}</button>
              <span>{deductDeliveries ? "talebinden teslimatlar düşülsün." : "talebi olduğu gibi planlansın."}</span>
            </>}
          </p>
          <div className="plan-run-stats">
            <span className="planned">
              <small>{seed.monthlyCustomerDemand ? "Karşılanacak sağlam parça ihtiyacı" : "Planlanacak miktar"}</small>
              <strong>{formatNumber(deliveryPreview ? deliveryPreview.snapshot.plannedDemand : demandSummary?.selectedDemand ?? seed.orders.reduce((sum, order) => sum + Math.max(0, order.quantity), 0))}</strong>
              <em>{deliveryPreview ? `${formatNumber(deliveryPreview.snapshot.grossDemand)} Excel ihtiyacı − ${formatNumber(deliveryPreview.snapshot.deductedQuantity)} teslimat` : "Teslimat düşümü uygulanmıyor"}</em>
            </span>
            <span>
              <small>{appendToExistingPlan ? "Korunacak şarj" : "Sabit kalacak şarj"}</small>
              <strong>{formatNumber(appendToExistingPlan ? existingPlannedBatchCount : lockedBatchCount + routeCommittedCount)}</strong>
              <em>{appendToExistingPlan ? "Manuel ve öne çekilmiş dahil" : "Kilitli ve akış tercihli şarjlar"}</em>
            </span>
            {customerDemand
              ? <span>
                  <small><NumberHelp description="Seçilen hafta aralıklarında ilk kez oluşan toplam müşteri talebi; önceki haftaların açığı bu sayıya eklenmez.">Yeni hafta talebi</NumberHelp></small>
                  <strong>{formatNumber(demandSummary?.selectedDemand ?? 0)}</strong>
                  <em>{scopeDatesLabel}</em>
                </span>
              : <span>
                  <small>Aktif tezgah</small>
                  <strong>{activeMachines.length}</strong>
                  <em>{dateRangeValid ? `${formatInputDate(productionStartDate)}–${formatInputDate(productionEndDate)}` : "Kapsam seçilemedi"}</em>
                </span>}
          </div>
          <div className="plan-run-alerts">
            {alerts.map((alert) => <button key={alert.id} type="button" className={`plan-run-alert-chip ${alert.tone} ${openSection === "warn" ? "open" : ""}`} onClick={() => toggleSection("warn")}>
              {alert.tone === "info" ? <Lock size={13} /> : <Warning size={13} weight="fill" />}<strong>{alert.label}</strong>
            </button>)}
          </div>
          <div className="plan-run-panel">
            {openSection === "none" && <div className="plan-run-panel-empty">
              <CheckCircle size={22} />
              <strong>Değiştirilecek bir şey yok</strong>
              <span>Yukarıdaki cümlede turuncu yazılan kısımlardan birine tıklarsanız ayrıntılar burada açılır. Hiçbirine dokunmazsanız plan doğrudan çalışır.</span>
            </div>}

            {openSection === "mode" && appendAvailable && <section className="plan-run-panel-body">
              <div className="plan-run-panel-title"><strong>Başlangıç noktası</strong><span>Yeni ihtiyacı mevcut Gantt’ın devamına ekleyebilir veya planı baştan oluşturabilirsiniz.</span></div>
              <div className="plan-run-mode-actions">
                <button type="button" className={appendToExistingPlan ? "selected" : ""} onClick={() => selectPlanMode(true)}><Plus size={14} /><span><strong>{monthlyDemand ? "Kademeli planlama" : "Planın devamına ekle"}</strong><small>Mevcut, manuel ve öne çekilmiş şarjlar korunur. Hedef mevcut plandan gelir, değiştirilemez.</small></span></button>
                <button type="button" className={!appendToExistingPlan ? "selected replace" : ""} onClick={() => selectPlanMode(false)}><ArrowClockwise size={14} /><span><strong>Planı baştan oluştur</strong><small>Yalnızca kilitli şarjlar korunur. Hedef yeniden seçilebilir ve seçenekler karşılaştırılabilir.</small></span></button>
              </div>
              <div className="plan-run-protection"><Lock size={16} /><span><strong>{protectionHeadline}</strong><small>{protectionDetail}</small></span></div>
            </section>}

            {openSection === "scope" && <section className="plan-run-panel-body">
              <div className="plan-run-panel-title"><CalendarBlank size={15} /><strong>{customerDemand ? appendToExistingPlan ? "Eklenecek planlama aralıkları" : "Planlama aralıkları" : "Üretim tarihleri"}</strong><span>{customerDemand ? appendToExistingPlan ? "İlk yeni aralık mevcut planın hemen arkasından başlar; varsa diğerleri kontrol sonrasında eklenir." : "Önce ilk aralık planlanır; diğerleri manuel kontrolünüzden sonra tek tek eklenir." : monthlyDemand && appendToExistingPlan ? "Bitişi mevcut kapsamdan sonraya uzatın. Önceki kapsam ve şarjlar korunur; yalnız eksik üretim eklenir." : "Tezgahların yeni plan için ortak başlangıç ve bitiş penceresi."}</span></div>
              {customerDemand
                ? <div className="plan-run-week-ranges">
                    {weekRanges.map((range, index) => {
                      const startIndex = availableWeeks.findIndex((week) => week.id === range.startWeekId);
                      const rangeNumber = appendToExistingPlan ? completedRangeCount + index + 1 : index + 1;
                      return <div className="plan-run-week-range" key={`${index}-${range.startWeekId}`}>
                        <div className="plan-run-week-range-head"><strong>{rangeNumber}. Aralık</strong>{index > 0 && <button type="button" onClick={() => removeWeekRange(index)} aria-label={`${rangeNumber}. planlama aralığını kaldır`}><X size={13} /></button>}</div>
                        <div className="plan-run-fields">
                          <Field label="Başlangıç haftası"><select value={range.startWeekId} disabled={appendToExistingPlan || index > 0} onChange={(event) => updateWeekRange(index, "startWeekId", event.target.value)}>{availableWeeks.map((week) => <option key={week.id} value={week.id}>{formatPlanningWeek(week.isoWeek, week.isoYear)}</option>)}</select></Field>
                          <Field label="Bitiş haftası"><select value={range.endWeekId} onChange={(event) => updateWeekRange(index, "endWeekId", event.target.value)}>{availableWeeks.slice(Math.max(0, startIndex)).map((week) => <option key={week.id} value={week.id}>{formatPlanningWeek(week.isoWeek, week.isoYear)}</option>)}</select></Field>
                        </div>
                      </div>;
                    })}
                    <button type="button" className="plan-run-add-range" disabled={!canAddWeekRange} onClick={addWeekRange}><Plus size={14} /> Aralık ekle</button>
                  </div>
                : <div className="plan-run-fields"><Field label="Plan başlangıcı"><input type="date" value={productionStartDate} onChange={(event) => setProductionStartDate(event.target.value)} /></Field><Field label="Plan bitişi"><input type="date" value={productionEndDate} onChange={(event) => setProductionEndDate(event.target.value)} /></Field></div>}
              <div className={`plan-run-scope-preview ${dateRangeValid ? "" : "invalid"}`}>
                {customerDemand && dateRangeValid
                  ? <>{resolvedWeekRanges.map((range, index) => <span className="plan-run-scope-line" key={range.startWeekId}><b>{appendToExistingPlan ? completedRangeCount + index + 1 : index + 1}</b><span><strong>{range.label}</strong><small>{formatInputDate(range.startDate)}–{formatInputDate(range.endDate)}</small></span></span>)}<em><NumberHelp description="Seçilen hafta aralıklarında ilk kez oluşan toplam müşteri talebi; önceki haftaların açığı bu sayıya eklenmez.">{formatNumber(demandSummary?.selectedDemand ?? 0)} adet yeni hafta talebi</NumberHelp>. {coarsePlanning ? weekRanges.length > 1 ? "Şimdi 1. aralık tek toplam olarak planlanır; diğerleri kontrolünüzden sonra sırayla eklenir." : "Seçilen aralığın talebi tek toplam olur ve yalnızca bu tarih penceresine yerleştirilir." : appendToExistingPlan ? weekRanges.length > 1 ? "İlk yeni aralık şimdi eklenir; diğerleri kontrolden sonra planlanır." : "Seçilen aralık mevcut planın arkasına eklenecek." : weekRanges.length > 1 ? "Şimdi yalnızca 1. aralık planlanır; diğerleri kontrolden sonra eklenir." : "Seçilen hafta aralığı planlanır."}</em></>
                  : <><strong>{dateRangeValid ? `${formatInputDate(productionStartDate)}–${formatInputDate(productionEndDate)}` : "Kapsam seçilemedi"}</strong><span>{customerDemand ? rangeValidationError : `${activeMachines.length} aktif tezgah`}</span></>}
              </div>
            </section>}

            {openSection === "goal" && <section className="plan-run-panel-body">
              <div className="plan-run-panel-title"><ChartBar size={15} /><strong>Optimizasyon hedefi</strong><span>{appendToExistingPlan ? "Devam planı, mevcut planla aynı optimizasyon hedefini kullanır. Değiştirmek için başlangıç noktasını “Planı baştan oluştur” yapın." : coarsePlanning ? "Standart planlama haftalık teslimat koruması vermez; her aralığı kendi üretim penceresinde toplu olarak planlar." : "Termin sırası her seçenekte korunur; seçenek tezgah dağılımını değiştirir."}</span></div>
              <div className={`plan-run-goal-list ${appendToExistingPlan ? "fixed" : ""}`}>{goals.map((goal) => <label key={goal.id} className={optimizationGoal === goal.id ? "selected" : ""}><input type="radio" name="optimization-goal" value={goal.id} checked={optimizationGoal === goal.id} disabled={appendToExistingPlan} onChange={() => selectOptimizationGoal(goal.id)} /><span><strong>{goal.title}</strong><small>{goal.detail}</small></span></label>)}</div>
              {coarsePlanning && <div className="coarse-plan-warning"><Warning size={17} weight="fill" /><span><strong>Haftalık teslimat kontrolü kapalı</strong><small>{firstResolvedRange ? `${formatInputDate(firstResolvedRange.startDate)}–${formatInputDate(firstResolvedRange.endDate)} arasında tüm talep tek toplamdır. Aynı ürün ve çaplar daha uzun kampanyalar halinde tutulur; üretim pencere dışına taşamaz.` : "Seçilen aralık tek üretim penceresi olarak kullanılır."}</small></span></div>}
              {comparison.length > 0 && <section className="plan-run-comparison">
                <header><div><span>SEÇENEK ÖNİZLEMESİ</span><strong>{customerDemand && weekRanges.length > 1 ? "Yalnızca ilk aralık için hesaplandı" : "Aynı kapsam ve kilitlerle hesaplandı"}</strong></div><small>Öneri önce eksik ve termin riskini, sonra bitiş ve setup’ı azaltır.</small></header>
                <div className="plan-run-comparison-table">
                  <div className="head"><span>Hedef</span><span>Termin eksiği</span><span>Planlanamayan</span><span>Yük farkı</span><span>Setup</span><span>Bitiş</span></div>
                  {comparison.map((row) => <button key={row.goal} className={`${optimizationGoal === row.goal ? "selected" : ""} ${row.recommended ? "recommended" : ""}`} onClick={() => setOptimizationGoal(row.goal)}>
                    <span><strong>{optimizationGoalLabel(row.goal)}</strong>{row.recommended && <small>Önerilen</small>}</span>
                    <span><NumberHelp focusable={false} description="Seçilen termin günlerine kadar hazır olmayacak toplam adet.">{formatNumber(row.onTimeShortage)}</NumberHelp></span>
                    <span><NumberHelp focusable={false} description="Kapasite veya uygun tezgâh bulunamadığı için plana yerleşemeyen şarj sayısı.">{row.result.summary.unplannedBatchCount}</NumberHelp></span>
                    <span><NumberHelp focusable={false} description="En dolu ve en boş kullanılan tezgâhların yük oranları arasındaki fark; düşük olması daha dengeli dağılım demektir.">{formatPercent(row.loadSpread)}</NumberHelp></span>
                    <span><NumberHelp focusable={false} description="Bu seçenekle oluşan tüm şarj geçişlerinin toplam setup süresi.">{formatHours(row.result.summary.totalSetupHours)}</NumberHelp></span>
                    <span><NumberHelp focusable={false} description="Bu seçenek uygulandığında Gantt üzerindeki son planlı işin bitiş tarihi.">{formatExcelDate(row.result.summary.completion, { day: "2-digit", month: "short" })}</NumberHelp></span>
                  </button>)}
                </div>
              </section>}
            </section>}

            {openSection === "threshold" && <section className="plan-run-panel-body">
              <div className="plan-run-panel-title"><ChartBar size={15} /><strong>Eksik için ek şarj</strong><span>Korunan üretim düşüldükten sonra kalan ihtiyaç, standart şarjın seçilen yüzdesine ulaşıyorsa bir şarj daha açılır. Eşik tam olarak karşılandığında da kural uygulanır.</span></div>
              <div className={`shortage-threshold-control ${addExtraChargeForShortage ? "selected" : ""} ${appendToExistingPlan && !monthlyDemand ? "fixed" : ""}`}>
                <label><input type="checkbox" checked={addExtraChargeForShortage} disabled={appendToExistingPlan && !monthlyDemand} onChange={(event) => setAddExtraChargeForShortage(event.target.checked)} /><span><strong>Eksik eşik değerine ulaşırsa bir ek şarj ekle</strong><small>{addExtraChargeForShortage ? `500’lük şarjda sıfırdan büyük kalan ihtiyaç %${formatDecimal(shortageThresholdPercent)} eşiğine ulaşırsa bir ek şarj açılır.` : "Kapalıyken yalnız tamamlanan tam şarjlar planlanır; kalan miktar Açık kalan olarak görünür."}</small></span></label>
                <Field label="Şarj eşiği (%)"><input type="number" min="0" max="100" step="1" value={shortageThresholdPercent} aria-invalid={!shortageThresholdValid} disabled={(appendToExistingPlan && !monthlyDemand) || !addExtraChargeForShortage} onChange={(event) => setShortageThresholdPercent(Number(event.target.value))} /></Field>
                {appendToExistingPlan && !monthlyDemand && <p><Lock size={13} /> Devam planı mevcut planın %{formatDecimal(shortageThresholdPercent)} eşiğini ve açık/kapalı seçimini korur.</p>}
              </div>
            </section>}

            {openSection === "source" && orderImport && <section className="plan-run-panel-body">
              <div className="plan-run-panel-title"><FileXls size={15} /><strong>Talep kaynağı ve teslimat düşümü</strong><span>Excel ihtiyacından teslim edilmiş adetler düşülür; kalan miktar planlanır.</span></div>
              <div className="plan-run-delivery-deduction">
              <header>
                <div><FileXls size={17} /><span><small>KULLANILAN SİPARİŞ EXCEL’İ</small><strong>{orderImport.sourceFile}</strong><em>{formatFactoryDateTime(orderImport.importedAt)} yüklendi</em></span></div>
                <label className={deductDeliveries ? "selected" : ""}><input type="checkbox" checked={deductDeliveries} disabled={appendToExistingPlan || Boolean(seed.monthlyCustomerDemand)} onChange={(event) => setDeductDeliveries(event.target.checked)} /><span><strong>Teslimatları ihtiyaçtan düş</strong><small>Aynı Excel ile yeniden üretimi engeller</small></span></label>
              </header>
              {seed.monthlyCustomerDemand && <p className="dispatch-plan-note">Aylık kaynakta tamamlanan devirler zaten düşüldü. Kesim anından sonraki kayıtlı teslimatlar bir kez düşülür; bu sınır değiştirilemez.</p>}
              <div className="delivery-deduction-controls">
                <Field label="Teslimat başlangıç tarihi ve saati"><input type="datetime-local" value={deliveryStartDateTime} disabled={appendToExistingPlan || !deductDeliveries || Boolean(seed.monthlyCustomerDemand)} onChange={(event) => { setDeliveryStartDateTime(event.target.value); setDeliveryCutoffReference(undefined); }} /></Field>
                <label className="delivery-boundary-option"><input type="checkbox" checked={includeDeliveryStart} disabled={appendToExistingPlan || !deductDeliveries || Boolean(seed.monthlyCustomerDemand)} onChange={(event) => setIncludeDeliveryStart(event.target.checked)} /><span><strong>Başlangıç anını dahil et</strong><small>{includeDeliveryStart ? "Tam bu anda kaydedilen teslimat hesaba katılır." : "Hesap başlangıç anından hemen sonra başlar."}</small></span></label>
                {appendToExistingPlan && <p><Lock size={13} /> Mevcut planın Excel sürümü ve teslimat filtresi korunuyor.</p>}
              </div>
              {deliveryPreview && <>
                <div className="delivery-deduction-summary">
                  <span><small>Excel ihtiyacı</small><strong>{formatNumber(deliveryPreview.snapshot.grossDemand)}</strong></span>
                  <b>−</b>
                  <span className="deducted"><small>Düşülecek teslimat</small><strong>{formatNumber(deliveryPreview.snapshot.deductedQuantity)}</strong></span>
                  <b>=</b>
                  <span className="planned"><small>{seed.monthlyCustomerDemand ? "Karşılanacak sağlam parça ihtiyacı" : "Planlanacak miktar"}</small><strong>{formatNumber(deliveryPreview.snapshot.plannedDemand)}</strong></span>
                </div>
                <details className="delivery-deduction-details">
                  <summary><Question size={14} /> Ürün ve teslimat hesabını göster <b>{deliveryPreview.snapshot.items.length}</b></summary>
                  <div>
                    <section className="delivery-deduction-products" aria-label="Ürün bazında teslimat hesabı">
                      <header><strong>Ürün bazında hesap</strong><span>Excel ihtiyacı</span><span>Düşülen</span><span>Kalan</span></header>
                      {deliveryPreview.products.map((row) => <article key={row.product}>
                        <strong>{row.product}</strong>
                        <span>{formatNumber(row.grossDemand)}</span>
                        <span>{formatNumber(row.deductedQuantity)}</span>
                        <span>{formatNumber(row.plannedDemand)}</span>
                      </article>)}
                    </section>
                    <section className="delivery-deduction-items" aria-label="Teslimat kayıtları">
                      <header><strong>Teslimat kayıtları</strong><span>{deliveryPreview.snapshot.items.length} kayıt</span></header>
                      {deliveryPreview.snapshot.items.length ? deliveryPreview.snapshot.items.map((item) => <article key={item.entryId} className={item.status}>
                        <span><strong>{item.product}</strong><small>{item.workOrder || "İş emri yok"}</small></span>
                        <span><strong>{formatNumber(item.quantity)} adet</strong><small>{formatFactoryDateTime(item.deliveredAt)}</small></span>
                        <span><strong>{item.status === "unmatched" ? "Eşleşmedi" : item.status === "outside-scope" ? "Bu aralığın dışında" : `${formatNumber(item.deductedQuantity)} düşüldü`}</strong><small>{item.excessQuantity > 0 ? `${formatNumber(item.excessQuantity)} adet fazla` : item.matchedOrderIds.length ? `Talep: ${item.matchedOrderIds.join(", ")}` : "İhtiyaçtan düşülmedi"}</small></span>
                      </article>) : <p>Seçilen zaman aralığında teslimat bulunmuyor.</p>}
                    </section>
                  </div>
                </details>
              </>}
              {deliveryPreviewError && <p className="form-error">{deliveryPreviewError}</p>}
              </div>
            </section>}

            {openSection === "warn" && <section className="plan-run-panel-body">
              <div className="plan-run-panel-title"><Warning size={15} /><strong>Uyarılar ve korumalar</strong><span>Planı çalıştırmadan önce kontrol edilmesi gerekenler.</span></div>
              {deliveryReview && <section className="delivery-coverage-review" aria-label="Dışarıda kalan teslimatlar">
                <strong><Warning size={18} weight="fill" /> Teslim edilmiş ürünler için yeniden şarj açılabilir</strong>
                <p>Excel yüklendikten sonra kaydedilmiş bu teslimatlar seçtiğiniz kapsamın dışında. Mevcut üretim, yarı mamül ve korunan şarjlar sayıldıktan sonra kalan şarj ihtiyacını artırıyorlar. Saatler Türkiye saatidir.</p>
                <div className="delivery-coverage-rows">
                  <header><span>Ürün</span><span>Eksik düşülen adet</span><span>Bu seçimle yeni üretim</span><span>Teslimatlar dahil edilirse</span></header>
                  {deliveryReview.products.map(row => <div key={row.product}>
                    <strong>{row.product}</strong><span>{formatNumber(row.excludedQuantity)} adet</span><span>{formatNumber(row.selectedNewQuantity)} adet</span><span>{formatNumber(row.inclusiveNewQuantity)} adet</span>
                  </div>)}
                </div>
                <small>Yeni üretim miktarları bu çalıştırmadaki Eksik için ek şarj seçimini ve yüzdeyi kullanır; tezgaha yerleşme veya termin garantisi değildir.</small>
                <details><summary>Teslimatları göster ({deliveryReview.items.length})</summary>
                  {deliveryReview.items.map(item => <p key={item.entryId}>{item.product} · {item.workOrder || "İş emri yok"} · {formatNumber(item.quantity)} adet · {formatFactoryDateTime(item.deliveredAt)}</p>)}
                </details>
                {!appendToExistingPlan && orderImport && <button className="secondary" onClick={() => {
                  setDeductDeliveries(true); setIncludeDeliveryStart(!orderImport?.shipmentsThrough);
                  setDeliveryStartDateTime(factoryDateTimeInput(orderImport.shipmentsThrough ?? orderImport.importedAt));
                  setDeliveryCutoffReference(orderImport.shipmentsThrough ?? orderImport.importedAt); setReviewedDeliveryCoverageKey(undefined);
                }}>Excel yükleme anından itibaren teslimatları dahil et</button>}
                {appendToExistingPlan && <p>Devam planı eski teslimat filtresini korur. Başlangıcı değiştirmek için yeni plan seçin; kilitli şarjlar korunur.</p>}
                <label><input type="checkbox" checked={!deliveryReviewPending} onChange={event => setReviewedDeliveryCoverageKey(event.target.checked ? deliveryReview.key : undefined)} />
                  Bu teslimatların Excel ihtiyacına zaten yansıtıldığını doğruladım; seçili kapsamla devam et.
                </label>
              </section>}
              {deliveryPreview && deliveryPreview.snapshot.excessDeliveryQuantity > 0 && <div className="delivery-deduction-alert excess"><Warning size={15} weight="fill" /><span><strong>İhtiyaçtan fazla teslimat var</strong><small>{formatNumber(deliveryPreview.snapshot.excessDeliveryQuantity)} adet ihtiyaçtan düşülmedi; planlanacak miktar sıfırın altına inmedi.</small></span></div>}
              {deliveryPreview && deliveryPreview.unmatchedItems.length > 0 && <div className="delivery-deduction-alert unmatched"><Warning size={15} weight="fill" /><span><strong>{deliveryPreview.unmatchedItems.length} teslimat Excel ile eşleşmedi</strong><small>{deliveryPreview.unmatchedItems.map((item) => `${item.product}${item.workOrder ? ` · ${item.workOrder}` : ""}`).join(" · ")}</small></span></div>}
              {coarsePlanning && <div className="coarse-plan-warning"><Warning size={17} weight="fill" /><span><strong>Haftalık teslimat kontrolü kapalı</strong><small>{firstResolvedRange ? `${formatInputDate(firstResolvedRange.startDate)}–${formatInputDate(firstResolvedRange.endDate)} arasında tüm talep tek toplamdır. Aynı ürün ve çaplar daha uzun kampanyalar halinde tutulur; üretim pencere dışına taşamaz.` : "Seçilen aralık tek üretim penceresi olarak kullanılır."}</small></span></div>}
              <div className="plan-run-protection"><Lock size={16} /><span><strong>{protectionHeadline}</strong><small>{protectionDetail}</small></span></div>
            </section>}
          </div>
          {error && <p className="form-error" role="alert">{error}</p>}
        </div>
        <div className="drawer-actions plan-run-actions">
          <button className="secondary" onClick={onClose}>Vazgeç</button>
          {!appendToExistingPlan && !coarsePlanning && <button className="secondary plan-compare-action" disabled={!dateRangeValid || !shortageThresholdValid || comparing || deliveryReviewPending} onClick={() => { setOpenSection("goal"); runComparison(); }}><ChartBar size={15} /> {comparing ? "Karşılaştırılıyor…" : "Seçenekleri karşılaştır"}</button>}
          <button className="primary" disabled={!dateRangeValid || !shortageThresholdValid || comparing || deliveryReviewPending} onClick={submit}><Play size={15} weight="fill" /> {primaryLabel}</button>
        </div>
      </section>
    </div>
  );
}

frontend/features/planning/board/Plannin.source:
"use client";

import type { RoutePlacementRequest } from "@/lib/route-placement";

import { type DeliverySummaryProps } from "@/features/planning/shared/DeliverySummary";
import { useRaviScreenContext } from "@/features/ravi/context";

import { CapacityDrawer } from "@/features/planning/board/CapacityDrawer";
import { BatchInspector, JourneyInspector } from "@/features/planning/board/Inspectors";
import { PlanBoard } from "@/features/planning/board/PlanBoard";
import { Menu, MenuItem } from "@/components/ui/Menu";
import { Metric, NumberHelp } from "@/features/planning/shared/controls";
import { formatPercent } from "@/features/planning/shared/format";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { buildOrderDeliveryResults } from "@/lib/delivery-readiness";
import { formatDecimal, formatInteger as formatNumber } from "@/lib/number-format";
import { buildPlanCoverageMetrics } from "@/lib/plan-coverage";
import { normalizeShortageExtraChargePolicy, type PlannedBatch, type PlanningSeed, type PlanRunSequence, type ScenarioResult } from "@/lib/planning";
import { type PlanningAdvice } from "@/lib/planning-advice";
import { buildDownstreamProcessPlan } from "@/lib/process-planning";
import {
  ArrowsLeftRight,
  CaretLeft,
  CaretRight,
  ChartBar,
  CheckCircle,
  Clock,
  PencilSimple,
  Play,
  Plus,
  Toolbox,
} from "@phosphor-icons/react";
import { useMemo, useState } from "react";

export function PlanningView({ onReviewRoute, report, reportRange, onReportRangeChange, seed, result, dirty, selectedBatch, onSelectBatch, onMoveBatch, onRemoveBatch, onLockThrough, onUnlockQueue, onSaveWorkOrder, onUpdateBatchQuantity, onSaveCurrentJob, onCompleteCurrentJob, onOperationError, advice, onApplyAdvice, onOpenMachineAdvice, onOpenManualBatch, automaticComparisonAvailable, onOpenAutomaticComparison, onPlanNextRange, updateSeed, onReplanProcess, onOpenJourney }: { onReviewRoute: (request: RoutePlacementRequest) => void; seed: PlanningSeed; result: ScenarioResult; dirty: boolean; selectedBatch: PlannedBatch | null; onSelectBatch: (id: string) => void; onOperationError: (message: string) => void; advice: PlanningAdvice[]; onApplyAdvice: (item: PlanningAdvice) => void; onOpenMachineAdvice: (machineId: string) => void; onOpenManualBatch: () => void; automaticComparisonAvailable: boolean; onOpenAutomaticComparison: () => void; onPlanNextRange: () => void; onReplanProcess: (process: "drilling" | "deburring" | "gkm" | "gtm" | "diameter-grinding" | "form-grinding" | "measuring" | "milling" | "final-inspection" | "filter-visual") => boolean; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; onOpenJourney: (jobId: string) => void } & PlanningOperations & Omit<DeliverySummaryProps, "hasPlan">) {
  const coverage = buildPlanCoverageMetrics({ ...result, orders: buildOrderDeliveryResults(seed, result) });
  const active = seed.machines.filter((machine) => machine.active).length;
  const hasPlan = result.state === "planned";
  const planRun = result.planRun ?? seed.activePlanRun;
  const shortageExtraCharge = hasPlan && planRun ? normalizeShortageExtraChargePolicy(planRun.shortageExtraCharge) : null;
  const stagedSequence = seed.planRunSequence;
  const hasPendingPlanRange = Boolean(
    stagedSequence && stagedSequence.completedRangeCount < stagedSequence.ranges.length,
  );
  const [selectedCurrentMachineId, setSelectedCurrentMachineId] = useState<string | null>(null);
  const [selectedProcessOperationId, setSelectedProcessOperationId] = useState("");
  const [capacityOpen, setCapacityOpen] = useState(false);
  const [inspectorOpen, setInspectorOpen] = useState(false);
  const selectedCurrentMachine = seed.machines.find((machine) => machine.id === selectedCurrentMachineId && machine.currentJob.product) ?? null;
  const downstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, result), [result, seed]);
  const selectedProcessOperation = downstreamPlan.operations.find((operation) => operation.id === selectedProcessOperationId);
  const selectedProcessJob = selectedProcessOperation ? downstreamPlan.jobs.find((job) => job.batchId === selectedProcessOperation.batchId) : undefined;
  useRaviScreenContext("planning", { selectedCurrentMachine, selectedProcessOperation, selectedProcessJob,
    capacityOpen, inspectorOpen, coverage, shortageExtraCharge, deliveryReport: report, reportRange, calculationSource: { coverageRate: "Teslimat Planı Excel", productionMetrics: "buildPlanCoverageMetrics(buildOrderDeliveryResults)" } });
  const selectBatch = (id: string) => { setSelectedCurrentMachineId(null); setSelectedProcessOperationId(""); setInspectorOpen(true); onSelectBatch(id); };
  const selectCurrentJob = (machineId: string) => { setSelectedProcessOperationId(""); setSelectedCurrentMachineId(machineId); setInspectorOpen(true); };
  const selectProcessOperation = (operationId: string) => { setSelectedCurrentMachineId(null); setSelectedProcessOperationId(operationId); if (operationId) setInspectorOpen(true); };
  const boardActions = <>
    {(selectedProcessOperation || selectedBatch) && <button className="ui-btn" onClick={() => onReviewRoute({ kind: "edit", batchId: selectedProcessOperation?.batchId ?? selectedBatch!.id, process: selectedProcessOperation?.process ?? "turning" })}>Üretim akışını düzenle</button>}
    <button id="planning-manual-batch" className="ui-btn" onClick={onOpenManualBatch}><Plus size={15} /> Manuel şarj ekle</button>
    <Menu label="Planlama araçları" icon={<Toolbox size={15} />} title={seed.planRunSequence ? "Aralıklar, doluluk ve karşılaştırma" : "Doluluk ve karşılaştırma"} className="planning-tools-menu">
      {stagedSequence && !hasPendingPlanRange && <PlanRunSequenceBar sequence={stagedSequence} disabled={!hasPlan || dirty} onNext={onPlanNextRange} />}
      {automaticComparisonAvailable && <MenuItem icon={<ArrowsLeftRight size={15} />} onClick={onOpenAutomaticComparison}>Otomatik planla karşılaştır</MenuItem>}
      <MenuItem icon={<ChartBar size={15} />} disabled={!hasPlan || dirty} onClick={() => setCapacityOpen(true)}>Tezgah dolulukları</MenuItem>
    </Menu>
  </>;
  return (
    <>
      <section className="planning-bar" aria-label="Plan summary">
        <h1>Planlama</h1>
        <div className="metrics kpi-strip">
          <Metric compact label="Toplam sipariş" value={formatNumber(result.summary.demand)} detail={`${seed.orders.filter((order) => order.quantity > 0).length} aktif sipariş · ${hasPlan ? `${formatNumber(result.summary.planned)} üretim kapsamında` : "plan bekliyor"}`} description="Seçili planlama kapsamındaki toplam net ihtiyaç. Alt satır planda bulunan toplam üretim miktarını ayrıca gösterir." />
          <Metric compact label="Karşılama oranı" value={report.payload && report.coverage != null ? new Intl.NumberFormat("tr-TR", { style: "percent", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(report.coverage) : "—"} detail={report.payload ? `${reportRange.startDate} – ${reportRange.endDate} · Teslimat Planı` : "Teslimat raporu hesaplanamadı"} tone={report.payload && report.shortage! < 0 ? "warning" : "default"} description="Siparişler ile aynı Teslimat Planı döneminde, ürün bazındaki eksik miktarın sipariş miktarından düşülmesiyle hesaplanır. Ürün fazlaları başka ürünün açığını kapatmaz." />
          <Metric compact label="Termin sonrası" value={hasPlan ? formatNumber(coverage.lateCovered) : "—"} detail={hasPlan ? coverage.lateCovered > 0 ? "Planda var, termininden sonra hazır" : "Geciken planlı miktar yok" : "Plan sonrası hesaplanır"} tone={hasPlan && coverage.lateCovered > 0 ? "warning" : "default"} description="Üretim planında bulunan fakat ilgili sipariş terminine yetişmeyen miktar. Bu miktar kaybolmaz; zamanında karşılama oranına dahil edilmez." />
          <Metric compact label="Açık kalan" value={hasPlan ? formatNumber(coverage.uncovered) : "—"} detail={hasPlan ? coverage.uncovered > 0 ? `${result.summary.unplannedBatchCount} planlanamayan şarj` : "Tüm ihtiyaç planda mevcut" : "Plan sonrası hesaplanır"} tone={hasPlan && coverage.uncovered > 0 ? "danger" : "default"} description="Ne termininde ne de daha sonraki üretim planında karşılığı bulunan ihtiyaç miktarı." />
          <Metric compact label="Aktif tezgah" value={`${formatNumber(active)} / ${formatNumber(seed.machines.length)}`} detail={hasPlan ? `${formatNumber(result.summary.plannedBatchCount)} yeni şarj` : "Plan boş"} description="Soldaki sayı planlamaya açık tezgahları, sağdaki sayı sistemde tanımlı tüm tezgahları gösterir." />
        </div>
        {shortageExtraCharge && <span className={`plan-policy-chip ${shortageExtraCharge.enabled ? "enabled" : "disabled"}`} aria-label="Planda kullanılan eksik kuralı"><NumberHelp description={shortageExtraCharge.enabled ? "Planda kullanılan eksik kuralı: kalan ihtiyaç bu orana ulaştığında bir ek şarj planlanır; daha küçük eksik görünür bırakılır." : "Planda kullanılan eksik kuralı: tam şarjdan küçük kalan ihtiyaç ek üretim açmadan görünür bırakılır."}><small>Eksik kuralı</small><strong>{shortageExtraCharge.enabled ? `Açık · %${formatDecimal(shortageExtraCharge.thresholdPercent)} şarj eşiği` : "Kapalı · yalnız tam şarjlar"}</strong></NumberHelp></span>}
      </section>
      {stagedSequence && hasPendingPlanRange && <PlanRunSequenceBar sequence={stagedSequence} disabled={!hasPlan || dirty} onNext={onPlanNextRange} />}
      <section className={`workspace ${inspectorOpen ? "" : "inspector-collapsed"}`}>
        <PlanBoard toolbarActions={boardActions} onReviewRoute={onReviewRoute} seed={seed} result={result} dirty={dirty} advice={advice} selectedBatch={selectedCurrentMachine ? null : selectedBatch} selectedCurrentMachineId={selectedCurrentMachineId} selectedProcessOperationId={selectedProcessOperationId} onSelectProcessOperation={selectProcessOperation} onSelectBatch={selectBatch} onSelectCurrentJob={selectCurrentJob} onMoveBatch={onMoveBatch} onLockThrough={onLockThrough} onUnlockQueue={onUnlockQueue} onApplyAdvice={onApplyAdvice} onOpenMachineAdvice={onOpenMachineAdvice} onSaveCurrentJob={onSaveCurrentJob} onCompleteCurrentJob={onCompleteCurrentJob} onOperationError={onOperationError} updateSeed={updateSeed} onReplanProcess={onReplanProcess} />
        {inspectorOpen ? <div className="inspector-shell"><button className="inspector-toggle" onClick={() => setInspectorOpen(false)} aria-label="Seçili şarj panelini daralt" title="Paneli daralt"><CaretRight size={15} /></button>{selectedProcessOperation && selectedProcessJob ? <JourneyInspector job={selectedProcessJob} operation={selectedProcessOperation} onSelectOperation={selectProcessOperation} onOpenJourney={() => onOpenJourney(selectedProcessJob.batchId)} /> : <BatchInspector seed={seed} batch={selectedCurrentMachine ? null : selectedBatch} currentMachine={selectedCurrentMachine} machines={seed.machines} queueLength={selectedBatch ? result.batches.filter((batch) => batch.status === "planned" && batch.machineId === selectedBatch.machineId).length : 0} onMove={onMoveBatch} onRemove={onRemoveBatch} onLockThrough={onLockThrough} onUnlockQueue={onUnlockQueue} onSaveWorkOrder={onSaveWorkOrder} onUpdateBatchQuantity={onUpdateBatchQuantity} />}</div> : <button className="inspector-rail" onClick={() => setInspectorOpen(true)} aria-label="Seçili şarj panelini aç" title="Seçili şarj ayrıntılarını aç"><CaretLeft size={15} /><span>{selectedProcessOperation ? "Şarj yolculuğu" : selectedCurrentMachine ? "Mevcut iş" : "Seçili şarj"}</span></button>}
      </section>
      {capacityOpen && <CapacityDrawer seed={seed} result={result} onClose={() => setCapacityOpen(false)} />}
    </>
  );
}

function PlanRunSequenceBar({ sequence, disabled, onNext }: { sequence: PlanRunSequence; disabled: boolean; onNext: () => void }) {
  const completed = Math.min(sequence.completedRangeCount, sequence.ranges.length);
  const nextRange = sequence.ranges[completed];
  const currentRange = sequence.ranges[Math.max(0, completed - 1)];
  const complete = completed >= sequence.ranges.length;
  return (
    <section className={`plan-sequence-bar ${complete ? "complete" : ""}`} aria-label="Aşamalı planlama durumu">
      <div className="plan-sequence-copy">
        <span>{complete ? "ARALIKLAR TAMAMLANDI" : "MANUEL KONTROL ADIMI"}</span>
        <strong>{complete ? `${sequence.ranges.length} aralığın tamamı planlandı` : `${completed}. aralık planlandı · ${currentRange.label}`}</strong>
        <small>{complete ? "Planlanan tüm aralıklar aynı Gantt üzerinde birleşik olarak korunuyor." : `Mevcut planı düzenleyip doğrulayın; hazır olduğunuzda ${nextRange.label} aralığını arkasına ekleyin.`}</small>
      </div>
      <div className="plan-sequence-track">
        {sequence.ranges.map((range, index) => {
          const isReviewing = !complete && index === completed - 1;
          const isCompleted = index < completed && !isReviewing;
          const isNext = index === completed;
          const status = isReviewing ? "Kontrol ediliyor" : isCompleted || complete ? "Tamamlandı" : isNext ? "Sıradaki" : "Bekliyor";
          return <span key={`${range.startWeekId}-${range.endWeekId}`} className={isReviewing ? "reviewing" : isCompleted || complete ? "completed" : isNext ? "next" : "pending"}><i>{isCompleted || complete ? <CheckCircle size={13} weight="fill" /> : isReviewing ? <PencilSimple size={13} /> : <Clock size={13} />}</i><b>{index + 1}. {range.label}</b><small>{status}</small></span>;
        })}
      </div>
      {!complete && <button className="plan-next-range-action" disabled={disabled} onClick={onNext}><Play size={14} weight="fill" /><span>Sıradaki aralığı planla<small>{nextRange.label}</small></span></button>}
    </section>
  );
}

frontend/features/planning/board/WeeklyD.source:
"use client";

import { formatInputDate, serialToInputDate } from "@/features/planning/shared/format";
import { turningDeliveryReadyAt } from "@/lib/delivery-calendar";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { type PlannedBatch, formatExcelDate } from "@/lib/planning";
import { type BatchSplitInsight, type WeeklyPlanStatus, selectedBatchWeeklyStatus } from "@/lib/weekly-plan-status";
import { Question } from "@phosphor-icons/react";

export function WeeklyDemandRibbon({ rows, selectedBatch, selectedReadyAt, splitInsight, previewing, coarsePlanning, onFocusWeek }: { rows: WeeklyPlanStatus[]; selectedBatch: PlannedBatch | null; selectedReadyAt?: number; splitInsight: BatchSplitInsight | null; previewing: boolean; coarsePlanning: boolean; onFocusWeek: (dueDate: string) => void }) {
  const selected = selectedBatchWeeklyStatus(rows, selectedBatch);
  const readyDate = selectedBatch ? serialToInputDate(selectedReadyAt ?? turningDeliveryReadyAt(selectedBatch.end)) : "";
  const selectedOnTime = Boolean(selectedBatch?.demandDueDate && readyDate <= selectedBatch.demandDueDate);
  if (!rows.length) return <section className="weekly-demand-ribbon empty"><div className="weekly-demand-empty-state"><span>HAFTALIK TERMİN</span><strong>Haftalık talep bulunmuyor</strong><small>Müşteri sipariş haftaları içe aktarıldığında termin etkisi burada görünür.</small></div></section>;
  return (
    <section className={`weekly-demand-ribbon ${previewing ? "previewing" : ""}`} aria-label="Haftalık talep ve termin durumu">
      <div className="weekly-demand-context">
        <span className="weekly-demand-kicker">{previewing ? "TAŞIMA ÖNİZLEMESİ" : coarsePlanning ? "STANDART PLANLAMA" : "HAFTALIK TERMİN"}<WeeklyDemandHelp coarsePlanning={coarsePlanning} /></span>
        <strong>{coarsePlanning ? "Tek toplam talep · tek üretim penceresi" : selected ? `${selected.product.product} · ${selected.week.label} hedefi` : "Talep ile plan aynı çizgide"}</strong>
        <small>{coarsePlanning
          ? selected
            ? `Bu şarj tornayı ${formatExcelDate(selectedBatch?.end ?? 0)} tarihinde tamamlar. Haftalık termin yerine pencere sonundaki toplam üretim kontrol edilir.`
            : "Haftalık teslim tarihleri bu deneyde değerlendirilmez; seçili aralığın toplam talebi pencere sonuna kadar tornada tamamlanır."
          : selected
            ? `Bu şarj ${formatInputDate(readyDate)} tarihinde teslimata hazır olur. ${formatNumber(selected.product.ready)} / ${formatNumber(selected.product.required)} adet yetişiyor${selectedOnTime ? "." : `; ${formatNumber(selected.product.shortage)} adet açık kalıyor.`}`
            : "Her hafta yeni talep ile o tarihe kadar teslimata hazır miktarı gösterir. Bir şarjı taşıdığınızda sonuç anında güncellenir."}</small>
        {!coarsePlanning && splitInsight && <em className={splitInsight.justifiedByDeadline ? "justified" : "review"}>{splitInsight.justifiedByDeadline
          ? `Kampanya bölündü: ${splitInsight.interveningProduct}, ${formatInputDate(splitInsight.interveningDueDate)} terminine önce yetişmeli.`
          : `Kampanya bölünmüş; aradaki ${splitInsight.interveningProduct} için daha erken termin görünmüyor. İncelemeye değer.`}</em>}
      </div>
      <div className="weekly-demand-weeks">
        {rows.map((row) => {
          const selectedWeek = selectedBatch?.demandDueDate === row.dueDate;
          return <button key={row.id} className={`${row.excludedFromPlan ? "backlog" : row.shortage > 0 ? "risk" : "ready"} ${selectedWeek ? "selected" : ""}`} onClick={() => onFocusWeek(row.dueDate)} title={`${row.excludedFromPlan ? "Plan dışında · " : `${formatInputDate(row.dueDate)} · `}${formatNumber(row.required)} gerekli · ${formatNumber(row.ready)} hazır`}>
            <span>{row.label}<small>{row.excludedFromPlan ? formatNumber(row.newDemand) : `+${formatNumber(row.newDemand)}`}</small></span>
            <strong>{formatNumber(row.ready)} / {formatNumber(row.required)}</strong>
            <em>{row.excludedFromPlan ? `${formatNumber(row.shortage)} açık · plan dışında` : coarsePlanning ? row.shortage > 0 ? `${formatNumber(row.shortage)} pencereye sığmadı` : "Pencereye sığdı" : row.shortage > 0 ? `${formatNumber(row.shortage)} eksik · ${formatNumber(row.riskProductCount)} tip` : "Termin tamam"}</em>
          </button>;
        })}
      </div>
    </section>
  );
}

function WeeklyDemandHelp({ coarsePlanning }: { coarsePlanning: boolean }) {
  const description = coarsePlanning
    ? "Standart planlama kartlarında yeni talep, pencere içinde tamamlanan miktar, toplam ihtiyaç ve pencereye sığmayan miktar açıklanır."
    : "Haftalık termin kartlarında yeni talep, teslimata hazır miktar, toplam ihtiyaç ve termin eksiği açıklanır.";
  return <span className="number-help-trigger general-help-trigger" tabIndex={0} aria-label={description}><Question size={10} weight="bold" aria-hidden="true" /><span role="tooltip" className="weekly-demand-guide">
    <span className="weekly-demand-guide-eyebrow">KART OKUMA REHBERİ</span>
    <strong>{coarsePlanning ? "Üretim penceresi nasıl okunur?" : "Haftalık termin nasıl okunur?"}</strong>
    <span className="weekly-demand-guide-rows">
      <span><b>+ Yeni talep</b><small>O haftada siparişe eklenen üretim ihtiyacı.</small></span>
      <span><b>{coarsePlanning ? "Tamamlanan" : "Hazır"}</b><small>{coarsePlanning ? "Pencere bitimine kadar üretimi tamamlanan adet; karttaki sol sayı." : "Termin tarihine kadar teslimata hazır olacak adet; karttaki sol sayı."}</small></span>
      <span><b>Toplam ihtiyaç</b><small>{coarsePlanning ? "Seçili pencerenin sonuna kadarki toplam talep; karttaki sağ sayı." : "O termin tarihine kadarki birikmiş ihtiyaç; karttaki sağ sayı."}</small></span>
      <span><b>{coarsePlanning ? "Sığmayan" : "Eksik · tip"}</b><small>{coarsePlanning ? "Pencere bitimine kadar üretilemeyen adet." : "Termine yetişmeyen adet ve bundan etkilenen ürün tipi sayısı."}</small></span>
    </span>
    <span className="weekly-demand-guide-rule"><i />{coarsePlanning ? "Sol sayı sağ sayıdan küçükse üretim pencereye sığmıyor." : "Sol sayı sağ sayıdan küçükse termin riski vardır."}</span>
  </span></span>;
}

frontend/features/planning/machines/Cale.source:
"use client";

import { Field } from "@/features/planning/shared/controls";
import { dateAfterDays, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { clampShiftCount } from "@/features/planning/shared/production";
import { type Machine, type MachineCalendarEvent, type ShiftCount, formatExcelDate } from "@/lib/planning";
import { Clock, PencilSimple, Trash, Wrench, X } from "@phosphor-icons/react";
import { useState } from "react";

export function MachineShiftDialog({ machine, events = [], initialEvent, onClose, onSave, onDelete }: { machine: Machine; events?: MachineCalendarEvent[]; initialEvent?: MachineCalendarEvent; onClose: () => void; onSave: (name: string, start: number, end: number, shifts: ShiftCount, editingId?: string) => void; onDelete?: (eventId: string) => void }) {
  const defaultShifts = clampShiftCount(machine.shiftFactor) || 1;
  const emptyDraft = { name: "Vardiya değişikliği", start: dateAfterDays(1), end: dateAfterDays(1), shifts: defaultShifts };
  const eventDraft = initialEvent ? { name: initialEvent.name, start: serialToInputDate(initialEvent.start), end: serialToInputDate(initialEvent.end), shifts: clampShiftCount(initialEvent.shiftCount) } : emptyDraft;
  const [editingId, setEditingId] = useState<string | undefined>(initialEvent?.id);
  const [draft, setDraft] = useState<{ name: string; start: string; end: string; shifts: ShiftCount }>(eventDraft);
  const start = inputDateToSerial(draft.start);
  const end = inputDateToSerial(draft.end);
  const valid = Boolean(draft.name.trim() && start && end && end >= start);
  const shiftEvents = [...events].filter((event) => event.kind === "shift").sort((left, right) => left.start - right.start);

  function edit(event: MachineCalendarEvent) {
    setEditingId(event.id);
    setDraft({ name: event.name, start: serialToInputDate(event.start), end: serialToInputDate(event.end), shifts: clampShiftCount(event.shiftCount) });
  }

  function reset() {
    setEditingId(undefined);
    setDraft(emptyDraft);
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog shift-manager-dialog machine-dialog" role="dialog" aria-modal="true" aria-label={`${machine.id} günlük vardiya ayarı`}><div className="operational-dialog-head"><span className="dialog-icon shift"><Clock size={20} /></span><div><span>TEZGAH TAKVİMİ</span><h2>{machine.id} için günlük vardiya</h2><p>Yeni bir istisna ekleyin veya daha önce girilmiş vardiya değişikliklerini düzenleyin.</p></div><button className="delete-button" onClick={onClose} aria-label="Günlük vardiya penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Açıklama"><input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></Field><div className="dialog-date-range"><Field label="Başlangıç"><input type="date" value={draft.start} onChange={(event) => setDraft({ ...draft, start: event.target.value, end: event.target.value > draft.end ? event.target.value : draft.end })} /></Field><Field label="Bitiş"><input type="date" min={draft.start} value={draft.end} onChange={(event) => setDraft({ ...draft, end: event.target.value })} /></Field></div><Field label="Çalışılacak vardiya"><select value={draft.shifts} onChange={(event) => setDraft({ ...draft, shifts: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field><div className="calendar-impact-note"><strong>{editingId ? "Kayıt düzenleniyor" : draft.shifts === 0 ? "Bu tarihlerde üretim duracak" : `${draft.shifts} vardiya kapasite uygulanacak`}</strong><span>Kaydettiğinizde mevcut kuyruk korunur ve başlangıç/bitiş tarihleri hemen yeniden hesaplanır.</span></div><div className="drawer-actions">{editingId && <button className="secondary" onClick={reset}>Yeni kayıt</button>}<button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(draft.name.trim(), start, end, draft.shifts, editingId)}>{editingId ? "Değişikliği kaydet" : "Uygula ve hesapla"}</button></div></div>{shiftEvents.length > 0 && <div className="shift-manager-records"><div><span>MEVCUT VARDİYA DEĞİŞİKLİKLERİ</span><small>{shiftEvents.length} kayıt</small></div>{shiftEvents.map((event) => <article key={event.id} className={editingId === event.id ? "editing" : ""}><span><strong>{event.name}</strong><small>{formatExcelDate(event.start)}{event.end !== event.start ? ` – ${formatExcelDate(event.end)}` : ""} · {event.shiftCount} vardiya</small></span><button onClick={() => edit(event)}><PencilSimple size={13} /> Düzenle</button>{onDelete && <button className="delete-button" onClick={() => { onDelete(event.id); if (editingId === event.id) reset(); }} aria-label={`${event.name} vardiya kaydını sil`}><Trash size={14} /></button>}</article>)}</div>}</section></div>;
}

export function MachineMaintenanceDialog({ machine, events = [], initialEvent, onClose, onSave, onDelete }: { machine: Machine; events?: MachineCalendarEvent[]; initialEvent?: MachineCalendarEvent; onClose: () => void; onSave: (name: string, start: number, end: number, editingId?: string) => void; onDelete?: (eventId: string) => void }) {
  const emptyDraft = { name: "Planlı bakım", start: dateAfterDays(1), end: dateAfterDays(1) };
  const [editingId, setEditingId] = useState<string | undefined>(initialEvent?.id);
  const [draft, setDraft] = useState(initialEvent ? { name: initialEvent.name, start: serialToInputDate(initialEvent.start), end: serialToInputDate(initialEvent.end) } : emptyDraft);
  const start = inputDateToSerial(draft.start);
  const end = inputDateToSerial(draft.end);
  const valid = Boolean(draft.name.trim() && start && end && end >= start);
  const maintenanceEvents = [...events].filter((event) => event.kind === "maintenance").sort((left, right) => left.start - right.start);
  function edit(event: MachineCalendarEvent) { setEditingId(event.id); setDraft({ name: event.name, start: serialToInputDate(event.start), end: serialToInputDate(event.end) }); }
  function reset() { setEditingId(undefined); setDraft(emptyDraft); }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog shift-manager-dialog machine-dialog" role="dialog" aria-modal="true" aria-label={`${machine.id} planlı bakım yönetimi`}><div className="operational-dialog-head"><span className="dialog-icon maintenance"><Wrench size={20} /></span><div><span>TEZGAH TAKVİMİ</span><h2>{machine.id} için planlı bakım</h2><p>Yeni bakım ekleyin veya mevcut bakımın tarihlerini revize edin.</p></div><button className="delete-button" onClick={onClose} aria-label="Planlı bakım penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Bakım açıklaması"><input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /></Field><div className="dialog-date-range"><Field label="Başlangıç"><input type="date" value={draft.start} onChange={(event) => setDraft({ ...draft, start: event.target.value, end: event.target.value > draft.end ? event.target.value : draft.end })} /></Field><Field label="Bitiş"><input type="date" min={draft.start} value={draft.end} onChange={(event) => setDraft({ ...draft, end: event.target.value })} /></Field></div><div className="calendar-impact-note maintenance"><strong>{editingId ? "Bakım tarihleri revize ediliyor" : valid ? `${Math.floor(end - start) + 1} takvim günü duruş` : "Tarih aralığını kontrol edin"}</strong><span>Kaydettiğinizde Gantt ve kapasite hesabı yeni tarihlere göre güncellenir.</span></div><div className="drawer-actions">{editingId && <button className="secondary" onClick={reset}>Yeni bakım</button>}<button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(draft.name.trim(), start, end, editingId)}>{editingId ? "Revizyonu kaydet" : "Bakımı takvime ekle"}</button></div></div>{maintenanceEvents.length > 0 && <div className="shift-manager-records"><div><span>MEVCUT BAKIMLAR</span><small>{maintenanceEvents.length} kayıt</small></div>{maintenanceEvents.map((event) => <article key={event.id} className={editingId === event.id ? "editing" : ""}><span><strong>{event.name}</strong><small>{formatExcelDate(event.start)}{event.end !== event.start ? ` – ${formatExcelDate(event.end)}` : ""}</small></span><button onClick={() => edit(event)}><PencilSimple size={13} /> Tarihi revize et</button>{onDelete && <button className="delete-button" onClick={() => { onDelete(event.id); if (editingId === event.id) reset(); }} aria-label={`${event.name} bakım kaydını sil`}><Trash size={14} /></button>}</article>)}</div>}</section></div>;
}

export function ShiftOptions() { return <>{[0, 1, 2, 3].map((value) => <option key={value} value={value}>{value === 0 ? "0 · Üretim yok" : `${value} vardiya`}</option>)}</>; }

frontend/features/planning/machines/Curr.source:
"use client";

import { useEffect, useRef, useState } from 'react';
import { X, Play, ArrowCounterClockwise } from '@phosphor-icons/react';
import { useRaviScreenContext } from '@/features/ravi/context';
import { Field } from '../shared/controls';
import { formatInteger } from '@/lib/number-format';
import { validateProductionInterruption, type ProductionInterruptionInput } from '@/lib/production-interruptions';

export type SwitchJobOption = { id:string; workOrder:string; product:string; quantity:number; requiresInterruptionConfirmation?:boolean };

export function CurrentJobSwitchDialog({resourceId,workOrder,quantity,options,signature,allowPartialCompletion=false,onClose,onSelect}: {allowPartialCompletion?:boolean;signature:string;resourceId:string;workOrder:string;quantity:number;options:SwitchJobOption[];onClose:()=>void;onSelect:(id:string,input:ProductionInterruptionInput,confirmed:boolean)=>void}) {
  const initialControl=useRef<HTMLSelectElement>(null);
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;initialControl.current?.focus();return()=>{if(previous?.isConnected)previous.focus();};},[]);
  const [expectedSignature]=useState(signature);
  const [produced,setProduced]=useState('');
  const [producedQuantity,setProducedQuantity]=useState('');
  const [reason,setReason]=useState('');
  const [kind,setKind]=useState<'partial-completion'|'interruption'>(allowPartialCompletion?'partial-completion':'interruption');
  const [query,setQuery]=useState('');
  const [selectedId,setSelectedId]=useState('');
  const [confirmed,setConfirmed]=useState(false);
  const [error,setError]=useState('');
  const selected=options.find(option=>option.id===selectedId);
  const visible=options.filter(option=>`${option.workOrder} ${option.product}`.toLocaleLowerCase('tr-TR').includes(query.toLocaleLowerCase('tr-TR')));
  useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose();};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[onClose]);
  useRaviScreenContext('current-job-switch',{resourceId,workOrder,quantity,produced,producedQuantity,kind,reason,query,selectedId,confirmed,error});
  function submit(){
    try {
      if(!produced)throw new Error('Üretim oldu mu? Evet veya Hayır seçin.');
      const input={kind,expectedSignature,produced:produced==='yes',quantity:produced==='yes'?Number(producedQuantity):undefined,reason:produced==='yes'?reason:undefined};
      validateProductionInterruption(input,quantity,1,1);
      if(!selected)throw new Error('Yeni mevcut işi seçin.');
      if(selected.requiresInterruptionConfirmation&&!confirmed)throw new Error('Üretim sonlanmadı. Devam etmek için onaylayın.');
      onSelect(selected.id,input,confirmed);
    }catch(caught){setError(caught instanceof Error?caught.message:'İş değiştirilemedi.');}
  }
  return <div className="confirmation-backdrop"><section className="operational-dialog process-current-switcher machine-dialog" role="dialog" aria-modal="true" aria-label={`${resourceId} mevcut işi değiştir`} onKeyDown={trapDialogFocus}>
    <div className="operational-dialog-head"><span className="dialog-icon shift"><ArrowCounterClockwise size={20}/></span><div><span>KONTROLLÜ İŞ DEĞİŞİMİ</span><h2>{resourceId} · Mevcut işi değiştir</h2><p>{workOrder || 'Mevcut şarj'} · {formatInteger(quantity)} adet</p></div><button className="delete-button" onClick={onClose} aria-label="Mevcut iş değiştirme penceresini kapat"><X size={16}/></button></div>
    <div className="process-switcher-body">
      <Field label="Üretim oldu mu?"><select ref={initialControl} aria-label="Üretim oldu mu?" value={produced} onChange={event=>{setProduced(event.target.value);setError('');}}><option value="">Seçin</option><option value="yes">Evet, üretim yapıldı</option><option value="no">Hayır, üretim yapılmadı</option></select></Field>
      {produced==='yes'&&<>{allowPartialCompletion&&<Field label="Üretilen parçalar"><select value={kind} onChange={event=>setKind(event.target.value as typeof kind)}><option value="partial-completion">Sonraki prosese aktar</option><option value="interruption">Manuel proses onayı beklesin</option></select></Field>}<Field label="Üretilen adet"><input type="number" min="1" max={quantity-1} step="1" required value={producedQuantity} onChange={event=>{setProducedQuantity(event.target.value);setError('');}}/></Field><Field label={kind==='partial-completion'?"İş değiştirme nedeni":"İşe ara verme nedeni"}><textarea required maxLength={2000} value={reason} onChange={event=>{setReason(event.target.value);setError('');}} placeholder="Örn. çelik bitti"/></Field><p>{formatInteger(Math.max(0,quantity-Number(producedQuantity)))} adet kalan iş olarak korunacak.</p></>}
      {produced==='no'&&<p>İş, adedi değişmeden kuyruğa döner. Yeni ara verme veya üretim kaydı oluşturulmaz; varsa önceki gerçek yarım üretim kaydı korunur.</p>}
      <Field label="Yeni mevcut iş"><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Şarj veya tip numarası ara"/></Field>
      <div className="process-switcher-list">{visible.map(option=><button key={option.id} className={selectedId===option.id?'selected':''} onClick={()=>{setSelectedId(option.id);setConfirmed(false);setError('');}}><span><strong>{option.workOrder||option.product}</strong><small>{option.product} · {formatInteger(option.quantity)} adet{option.requiresInterruptionConfirmation?' · Yarım üretim':''}</small></span></button>)}{!visible.length&&<p className="empty-copy">Seçilebilecek başka iş yok. Tezgah kuyruğuna Manuel şarj ile iş ekleyin.</p>}</div>
      {selected?.requiresInterruptionConfirmation&&<InterruptionConsent checked={confirmed} onChange={setConfirmed}/>}
      <div className="calendar-impact-note"><strong>{produced==='yes'?(kind==='partial-completion'?'Kısmi üretim tamamlanacak.':'Üretime ara verildi.'):'Kalan iş kuyrukta korunur.'}</strong><span>Kalan şarj aynı tezgahta yeni mevcut işin hemen arkasına eklenir. {kind==='partial-completion'?'Tamamlanan parçalar bekleme ve kapasite kurallarına göre sonraki proseslerde planlanır.':'Üretilen parçalar sonraki proseslere yalnız manuel eklenir.'} İncelenen bir kuyruk değişikliğiyle kalan işi başka sıraya taşıyabilirsiniz.</span></div>
      {error&&<p className="form-error" role="alert">{error}</p>}
      <div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!selected||!produced} onClick={submit}><Play size={14}/> Seçili şarjı mevcut yap</button></div>
    </div>
  </section></div>;
}

export function InterruptionConsent({checked,onChange}:{checked:boolean;onChange:(value:boolean)=>void}) {
  return <label className="interruption-consent"><input type="checkbox" checked={checked} onChange={event=>onChange(event.target.checked)}/><span><strong>Üretim sonlanmadı, yine de üretime alayım mı?</strong><small>Yalnızca fiilen üretilen yarı mamül adedinin bu proseste işlenmesini onaylıyorum.</small></span></label>;
}

export function InterruptedStartDialog({workOrder,onClose,onConfirm}:{workOrder:string;onClose:()=>void;onConfirm:()=>void}) {
 const [error,setError]=useState('');
 useRaviScreenContext('interrupted-production-start',{workOrder,error});
 useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose();};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[onClose]);
 return <div className="confirmation-backdrop"><section className="completion-dialog machine-dialog" role="dialog" aria-modal="true" aria-label="Yarım üretimi başlatma onayı" onKeyDown={trapDialogFocus}><h2>Üretim sonlanmadı, yine de üretime alayım mı?</h2><p>{workOrder} şarjının yalnızca fiilen üretilen yarı mamül adedi bu proseste işlenecek.</p>{error&&<p className="form-error" role="alert">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={()=>{try{onConfirm();}catch(caught){setError(caught instanceof Error?caught.message:'Üretim başlatılamadı.');}}}>Evet, üretime al</button></div></section></div>;
}

function trapDialogFocus(event: React.KeyboardEvent<HTMLElement>) {
 if(event.key!=='Tab')return;
 const controls=Array.from(event.currentTarget.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)'));
 if(event.shiftKey&&document.activeElement===controls[0]){event.preventDefault();controls.at(-1)?.focus();}
 else if(!event.shiftKey&&document.activeElement===controls.at(-1)){event.preventDefault();controls[0]?.focus();}
}

