"use client";
import { Fragment, useMemo, useState } from "react";
import { formGrindingShiftRows } from "@/lib/process-shift-report";
import { factoryDateInput } from "@/lib/factory-time";
import { inputDateToSerial } from "../shared/format";
import { formatInteger } from "@/lib/number-format";
import type { PlanningSeed } from "@/lib/planning";
import type { ProcessOperation } from "@/lib/process-planning";
import { useRaviScreenContext } from "@/features/ravi/context";
import { HelpTip } from "@/components/ui/primitives";
const SHIFT_REPORT_NOTE = "Planlı adetler mevcut çalışma takvimi ve setup süresinden dağıtılır. Fiili sütunu, vardiyada bitirilen şarj adedidir. Vardiya içi üretim sayacı değildir. Excel vardiyaları 23–07 / 07–15 / 15–23 olarak gösterilir. İlk vardiya önceki gün 23:00’da başlar; satır tarihi vardiyanın bittiği gündür. Bu görünüm üretim takvimini değiştirmez.";
export function FormGrindingShiftReport({ seed, operations }: { seed: PlanningSeed; operations: ProcessOperation[] }) {
  const [start, setStart] = useState(factoryDateInput());
  const report = useMemo(() => { try { return { data: formGrindingShiftRows(seed, operations, inputDateToSerial(start), 7), error: "" }; } catch (error) { return { data: undefined, error: error instanceof Error ? error.message : "Vardiyalar hesaplanamadı." }; } }, [seed, operations, start]);
  useRaviScreenContext("form-grinding-shifts", { start, days: 7, error: report.error, warnings: report.data?.warnings, allocation: "existing-planned-working-time", shiftWindows: "previous-day-23:00/07:00/15:00/23:00", actual: "completed-charge-at-finish" });
  const rows = report.data?.rows ?? [];
  const resources = rows[0]?.resources ?? [];
  const totals = resources.map((_, index) => rows.reduce((sum, row) => [sum[0] + row.resources[index].planned, sum[1] + row.resources[index].actual], [0, 0]));
  const dayLabel = (date: string) => `${date.slice(8, 10)}.${date.slice(5, 7)}.${date.slice(0, 4)}`;
  const quantity = (value: number) => value ? formatInteger(value) : "–";
  return <section className="data-surface dispatch-plan shift-report form-grinding-shift-report">
    <div className="surface-toolbar"><div><strong>Form Taşlama · vardiya görünümü</strong><span>7 gün · tezgah başına planlı ve fiili adet<HelpTip text={SHIFT_REPORT_NOTE} align="start" /></span></div><label className="field">Başlangıç <input type="date" value={start} onChange={event => setStart(event.target.value)} /></label></div>
    {report.error ? <p role="alert" className="dispatch-plan-error">{report.error}</p> : report.data && <>
      <div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table">
        <thead>
          <tr><th rowSpan={2} className="day">Gün</th><th rowSpan={2} className="shift">Vardiya / saat</th>{resources.map(resource => <th key={resource.id} colSpan={2} className="product"><b>{resource.id}</b></th>)}</tr>
          <tr>{resources.map(resource => <Fragment key={resource.id}><th className="group-start">Planlı</th><th>Fiili</th></Fragment>)}</tr>
        </thead>
        <tbody>{rows.map((row, index) => { const first = rows[index - 1]?.date !== row.date; return <tr key={`${row.date}:${row.shift}`} className={first ? "day-start" : undefined}>
          {first && <th className="day" rowSpan={rows.filter(item => item.date === row.date).length}><b>{dayLabel(row.date)}</b></th>}
          <td className="shift"><b>{row.shift}</b> {row.fromHour}:00–{row.toHour}:00</td>
          {row.resources.map(resource => <Fragment key={resource.id}><td className={`group-start${resource.planned ? "" : " empty"}`}>{quantity(resource.planned)}</td><td className={resource.actual ? "planned" : "empty"}>{quantity(resource.actual)}</td></Fragment>)}
        </tr>; })}</tbody>
        <tfoot><tr><th className="day"><b>Toplam</b></th><td className="shift">{rows.length} vardiya</td>{totals.map((total, index) => <Fragment key={index}><td className="group-start">{quantity(total[0])}</td><td>{quantity(total[1])}</td></Fragment>)}</tr></tfoot>
      </table></div>
      {report.data.warnings.map(warning => <p key={warning} className="stock-view-status">{warning}</p>)}
    </>}
  </section>;
}

