  CurrentJobEditor,
  ProcessCurrentJobEditor,
} from "@/features/planning/machines/ProductionDialogs";
import { Field, Metric } from "@/features/planning/shared/controls";
import { Menu, MenuDivider, MenuItem } from "@/components/ui/Menu";
import { HelpTip, PageBarSlot } from "@/components/ui/primitives";
import { formatHours, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import {
  actualProcessResources,
  clampShiftCount,
  normalizeMachineId,
  productionProcessLabel,
  queuePosition,
} from "@/features/planning/shared/production";
import { type PlanningOperations } from "@/features/planning/shared/types";
import { buildOvertimeEntries } from "@/lib/capacity-analytics";
import { factoryDateInput, factoryNowSerial } from "@/lib/factory-time";
import { buildMachineDiagnostics } from "@/lib/machine-diagnostics";
import { analyzeMachineDeletion, deleteMachineDefinition } from "@/lib/machine-management";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  formatExcelDate,
  isMachineEligibleForProduct,
  productSetupFamily,
  removeMachineShiftOverrides,
  replaceMachineShiftOverrides,
  type Machine,
  type Order,
  type PlannedBatch,
  type PlanningSeed,
  type Product,
  type ScenarioResult,
  type ShiftCount,
} from "@/lib/planning";
import { activeProcessResourceIds, processLabel, type DownstreamProcess, type ProcessKind, type ProcessResource } from "@/lib/process-master-data";
import {
  buildDownstreamProcessPlan,
  processJobStartAvailability,
  previewProcessQueuePlacement, processPlacementSignature, type ProcessQueuePlacementRequest,
  type ProcessCurrentJobInput,
  type ProcessOperation,
} from "@/lib/process-planning";
import { productSetupFamilyLabel, resolvedProductSetupFamily, type ProductSetupFamily } from "@/lib/setup-families";
import { type WipOperationInput } from "@/lib/wip-ledger";
import {
  Archive,
  ArrowCounterClockwise,
  ArrowsLeftRight,
  CaretDown,
  CaretUp,
  Check,
  CheckCircle,
  Clock,
  DotsSixVertical,
  DotsThree,
  Lock,
  LockOpen,
  MagnifyingGlass,
  PencilSimple,
  Play,
  Plus,
  Trash,
  Warning,
  Wrench,
  X,
  XCircle,
} from "@phosphor-icons/react";
import { useEffect, useLayoutEffect, useMemo, useRef, useState, type ReactNode } from "react";

export function MachinesView({ onCancelRemaining, onSaveMachineAvailability, onReviewRoute, seed, result, dirty, selectedMachineId, setSelectedMachineId, updateSeed, updateCalendar, onAddBatch, onMoveBatch, onRemoveBatch, onLockThrough, onUnlockQueue, onSaveWorkOrder, onUpdateBatchQuantity, onSaveCurrentJob, onReplaceTurningJob, onCompleteCurrentJob, onStartProcessCurrentJob, onReplaceProcessCurrentJob, onSaveProcessCurrentJob, onCompleteProcessCurrentJob, onCompleteWipOperation, onReplanProcess }: { onCancelRemaining?: (machineId: string, chargeId: string) => void; onSaveMachineAvailability: (machineId: string, start: number) => void; onReviewRoute: (request: RoutePlacementRequest) => void; seed: PlanningSeed; result: ScenarioResult; dirty: boolean; selectedMachineId: string; setSelectedMachineId: (id: string) => void; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; updateCalendar: (mutator: (seed: PlanningSeed) => void) => void; onAddBatch: ManualBatchSave; onReplanProcess: (process: DownstreamProcess) => boolean; onReplaceTurningJob: (machineId:string,batchId:string,input:ProductionInterruptionInput)=>void; onStartProcessCurrentJob: (operationId: string, confirmedInterruption?:boolean) => void; onReplaceProcessCurrentJob: (resourceId: string, operationId: string, input:ProductionInterruptionInput, confirmedInterruption?:boolean) => void; onSaveProcessCurrentJob: (resourceId: string, input: ProcessCurrentJobInput) => void; onCompleteProcessCurrentJob: (resourceId: string, completedAt: number, completedQuantity?: number, actualResourceId?: string, remainderAction?: "keep" | "scrap", confirmedBuffer?: boolean, countCorrectionReason?: string) => void; onCompleteWipOperation: (input: WipOperationInput) => boolean } & PlanningOperations) {
  const diameterHues = useMemo(() => buildDiameterHues(seed, result), [result, seed]);
  const machines = seed.machines;
  const products = seed.products;
  const batches = result.batches;
  const [activeProcess, setActiveProcess] = useState<ProcessKind>("turning");
  const [selectedProcessResources, setSelectedProcessResources] = useState<Partial<Record<ProcessKind, string>>>({});
  const selected = machines.find((machine) => machine.id === selectedMachineId) ?? machines[0];
  const downstreamResources = (seed.processMasterData?.resources ?? []).filter((resource) => resource.process === activeProcess);
  const activeResourceId = activeProcess === "turning" ? selected.id : selectedProcessResources[activeProcess] ?? downstreamResources[0]?.id ?? "";
  const selectedDownstreamResource = downstreamResources.find((resource) => resource.id === activeResourceId) ?? downstreamResources[0];
  const downstreamPlan = useMemo(() => buildDownstreamProcessPlan(seed, result), [result, seed]);
  const downstreamOperations = downstreamPlan.operations.filter((operation) => !operation.actual && operation.process === activeProcess);
  const selectedProcessCurrentJob = (seed.processCurrentJobs ?? []).find((job) => job.process === activeProcess && job.resourceId === activeResourceId);
  const selectedProcessSchedule = downstreamOperations.filter((operation) => !operation.current && operation.resourceId === activeResourceId).sort((left, right) => left.start - right.start || left.id.localeCompare(right.id));
  const unscheduledProcessQueue = (downstreamPlan.queueEntries??[]).filter(row=>row.resourceId===activeResourceId&&row.process===activeProcess&&!row.scheduled);
  const [processNow, setProcessNow] = useState(factoryNowSerial);
  useEffect(() => { const timer = window.setInterval(() => setProcessNow(factoryNowSerial()), 30_000); return () => window.clearInterval(timer); }, []);
  const startAvailability = processJobStartAvailability(seed, downstreamPlan, activeResourceId, Math.max(processNow, factoryNowSerial()));
  const processStartCandidate = startAvailability.operation;
  const diagnostics = useMemo(() => buildMachineDiagnostics(seed, result, { dirty }), [dirty, result, seed]);
  const diagnostic = diagnostics[selected.id];
  const schedule = batches.filter((batch) => batch.status === "planned" && batch.machineId === selected.id).sort((left, right) => left.planColumn - right.planColumn);
  const [manualDialogOpen, setManualDialogOpen] = useState(false);
  const [turningSwitcherOpen,setTurningSwitcherOpen]=useState(false);
  const [interruptedStartId,setInterruptedStartId]=useState<string|null>(null);
  const [jobEditorOpen, setJobEditorOpen] = useState(false);
  const [completionOpen, setCompletionOpen] = useState(false);
  const [processJobEditorOpen, setProcessJobEditorOpen] = useState(false);
  const [processJobSwitcherOpen, setProcessJobSwitcherOpen] = useState(false);
  const [processCompletionOpen, setProcessCompletionOpen] = useState(false);
  const [queuedProcessCompletion, setQueuedProcessCompletion] = useState<ProcessOperation | null>(null);
  const [maintenanceDialogOpen, setMaintenanceDialogOpen] = useState(false);
  const [shiftDialogOpen, setShiftDialogOpen] = useState(false);
  const [catalogOpen, setCatalogOpen] = useState(false);
  const [processManualDialogOpen, setProcessManualDialogOpen] = useState(false);
  const [processMaintenanceDialogOpen, setProcessMaintenanceDialogOpen] = useState(false);
  const [processShiftDialogOpen, setProcessShiftDialogOpen] = useState(false);
  const [processCatalogOpen, setProcessCatalogOpen] = useState(false);
  const [editingQuantityBatch, setEditingQuantityBatch] = useState<PlannedBatch | null>(null);
  const [queueDrag, setQueueDrag] = useState<{ batchId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const [processQueueDrag, setProcessQueueDrag] = useState<{ operationId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const [processQueueFeedback, setProcessQueueFeedback] = useState<{ tone: "success" | "error"; message: string } | null>(null);
  const [queueReviewError, setQueueReviewError] = useState("");
  const [lastAppliedQueueMove, setLastAppliedQueueMove] = useState<ProcessOperation | null>(null);
  const appliedQueueDestinationRef = useRef<string | null>(null);
  const processQueueListRef = useRef<HTMLDivElement | null>(null);
  const [processQueueQuery, setProcessQueueQuery] = useState("");
  useRaviScreenContext("machines", { activeProcess, activeResourceId, processQueueQuery,
    unscheduledQueue: unscheduledProcessQueue,
    selectedMachine: activeProcess === "turning" ? selected : undefined,
    startAvailability: activeProcess !== "turning" ? { reason: startAvailability.reason, guidance: startAvailability.guidance, operationId: processStartCandidate?.id, checkedAt: processNow } : undefined,
    diagnostic: activeProcess === "turning" ? diagnostic : undefined,
    dialogs: { turningSwitcherOpen, processJobSwitcherOpen, interruptedStartId, jobEditorOpen, completionOpen, maintenanceDialogOpen, shiftDialogOpen, processJobEditorOpen, processCompletionOpen },
    calculationSource: "buildMachineDiagnostics / buildDownstreamProcessPlan" });
  const [recentProcessOperationId, setRecentProcessOperationId] = useState("");
  const queueListRef = useRef<HTMLDivElement | null>(null);
  const queueRowPositionsRef = useRef<Map<string, number>>(new Map());
  const pendingMovedBatchRef = useRef<string | null>(null);
  const queueGestureRef = useRef<{ batchId: string; sourceIndex: number; startY: number; active: boolean } | null>(null);
  const queueDragRef = useRef<{ batchId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const processQueueGestureRef = useRef<{ operationId: string; sourceIndex: number; startY: number; active: boolean } | null>(null);
  const processQueueDragRef = useRef<{ operationId: string; position: number; targetRowIndex: number; edge: "before" | "after" } | null>(null);
  const queueOrderKey = schedule.map((batch) => `${batch.id}:${batch.planColumn}`).join("|");
  const selectedShiftEvents = (seed.calendarEvents ?? []).filter((event) => event.machineId === selected.id && event.kind === "shift");
  const selectedOvertimeEntries = useMemo(() => {
    if (!selectedShiftEvents.length) return [];
    const start = Math.min(...selectedShiftEvents.map((event) => event.start));
    const end = Math.max(...selectedShiftEvents.map((event) => event.end));
    return buildOvertimeEntries(seed, start, end, selected.id);
  }, [seed, selected.id, selectedShiftEvents.map((event) => `${event.id}:${event.start}:${event.end}:${event.shiftCount}`).join("|")]);
  const selectedProcessCalendarEvents = (seed.calendarEvents ?? []).filter((event) => event.machineId === activeResourceId);
  const manualCandidateOperations = useMemo(()=>buildDownstreamProcessPlan(seed,result,true).operations,[seed,result]);
  const processManualCandidates = selectedDownstreamResource ? [...downstreamOperations, ...manualCandidateOperations.filter(operation=>operation.manualCandidate && operation.process===activeProcess)].filter((operation) => {
    if (operation.current) return false;
    const product = seed.processMasterData?.products.find((item) => item.product === operation.product);
    const parameter = product?.processes.find((item) => item.process === operation.process);
    return Boolean(parameter && activeProcessResourceIds(parameter).includes(selectedDownstreamResource.id) && (parameter.unitsPerShift[selectedDownstreamResource.id] ?? 0) > 0);
  }) : [];
  const processReplacementCandidates = processManualCandidates.filter((operation) => operation.source === "wip" && operation.wipLotId && operation.readyAt <= factoryNowSerial() + 1e-8);
  const normalizedProcessQueueQuery = processQueueQuery.trim().toLocaleUpperCase("tr-TR");
  const visibleProcessSchedule = selectedProcessSchedule.filter((operation) => !normalizedProcessQueueQuery || `${operation.workOrder} ${operation.product} ${operation.batchId}`.toLocaleUpperCase("tr-TR").includes(normalizedProcessQueueQuery));
  const downstreamMachineAdapter: Machine | undefined = selectedDownstreamResource ? (() => {
    const firstStart = selectedDownstreamResource.availableStart ?? selectedProcessCurrentJob?.start ?? selectedProcessSchedule[0]?.start ?? inputDateToSerial(factoryDateInput());
    const lastEnd = Math.max(firstStart, selectedProcessCurrentJob?.end ?? 0, ...selectedProcessSchedule.map((operation) => operation.end));
    return {
      id: selectedDownstreamResource.id,
      name: selectedDownstreamResource.name,
      active: selectedDownstreamResource.active,
      availableStart: firstStart,
      operationalAvailableStart: firstStart,
      planEnd: selectedDownstreamResource.planEnd ?? lastEnd,
      note: processLabel(activeProcess),
      shiftFactor: selectedDownstreamResource.defaultShifts,
      capacityFactor: 1,
      finishOffset: 0,
      rates: {},
      currentJob: {
        workOrder: selectedProcessCurrentJob?.workOrder ?? "",
        product: selectedProcessCurrentJob?.product ?? "",
        quantity: selectedProcessCurrentJob?.remainingQuantity ?? 0,
        originalQuantity: selectedProcessCurrentJob?.originalQuantity ?? 0,
        remainingQuantity: selectedProcessCurrentJob?.remainingQuantity ?? 0,
        start: selectedProcessCurrentJob?.start ?? firstStart,
        end: selectedProcessCurrentJob?.end ?? firstStart,
        dailyRate: (selectedProcessCurrentJob?.unitsPerShift ?? 0) * selectedDownstreamResource.defaultShifts,
        diameter: selectedProcessCurrentJob?.setupKey ?? "",
      },
    };
  })() : undefined;

  useLayoutEffect(() => {
    const rows = queueListRef.current?.querySelectorAll<HTMLElement>(".machine-queue-row[data-batch-id]");
    if (!rows) return;
    const nextPositions = new Map<string, number>();
    rows.forEach((row) => {
      const batchId = row.dataset.batchId;
      if (batchId) nextPositions.set(batchId, row.getBoundingClientRect().top);
    });
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!reduceMotion && queueRowPositionsRef.current.size) {
      rows.forEach((row) => {
        const batchId = row.dataset.batchId;
        if (!batchId) return;
        const previousTop = queueRowPositionsRef.current.get(batchId);
        const nextTop = nextPositions.get(batchId);
        const delta = previousTop == null || nextTop == null ? 0 : previousTop - nextTop;
        if (Math.abs(delta) > 1) {
          row.animate([{ transform: `translateY(${delta}px)` }, { transform: "translateY(0)" }], { duration: batchId === pendingMovedBatchRef.current ? 480 : 360, easing: "cubic-bezier(.2,.8,.2,1)" });
        }
        if (batchId === pendingMovedBatchRef.current) {
          row.animate([{ backgroundColor: "#dff3ec", boxShadow: "inset 3px 0 0 #087a78" }, { backgroundColor: "#eef8f4", boxShadow: "inset 3px 0 0 #087a78", offset: .55 }, { backgroundColor: "transparent", boxShadow: "inset 0 0 0 rgba(8,122,120,0)" }], { duration: 820, easing: "ease-out" });
        }
      });
    }
    queueRowPositionsRef.current = nextPositions;
    pendingMovedBatchRef.current = null;
  }, [queueOrderKey, selected.id]);

  function moveQueueBatch(batchId: string, machineId: string, position: number) {
    pendingMovedBatchRef.current = batchId;
    onMoveBatch(batchId, machineId, position);
    window.setTimeout(() => {
      if (pendingMovedBatchRef.current === batchId) pendingMovedBatchRef.current = null;
    }, 1000);
  }

  useEffect(() => {
    setManualDialogOpen(false);
    setJobEditorOpen(false);
    setCompletionOpen(false);
    setMaintenanceDialogOpen(false);
    setShiftDialogOpen(false);
    setEditingQuantityBatch(null);
    setQueueDrag(null);
    queueGestureRef.current = null;
    queueDragRef.current = null;
    queueRowPositionsRef.current = new Map();
    pendingMovedBatchRef.current = null;
  }, [selected.id]);

  useEffect(() => {
    setProcessQueueDrag(null);
    if (appliedQueueDestinationRef.current !== activeResourceId) {
      setProcessQueueFeedback(null);
      setRecentProcessOperationId("");
    }
    appliedQueueDestinationRef.current = null;
    setProcessJobEditorOpen(false);
    setProcessCompletionOpen(false);
    setQueuedProcessCompletion(null);
    setProcessManualDialogOpen(false);
    setProcessMaintenanceDialogOpen(false);
    setProcessShiftDialogOpen(false);
    setProcessCatalogOpen(false);
    processQueueGestureRef.current = null;
    processQueueDragRef.current = null;
  }, [activeProcess, activeResourceId]);

  function beginQueueDrag(event: React.PointerEvent<HTMLButtonElement>, batch: PlannedBatch, index: number) {
    if (event.button !== 0 || batch.locked) return;
    queueGestureRef.current = { batchId: batch.id, sourceIndex: index, startY: event.clientY, active: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continueQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = queueGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.abs(event.clientY - gesture.startY) < 5) return;
    gesture.active = true;
    const targetRow = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>(".machine-queue-row[data-queue-index]");
    if (!targetRow) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const targetRowIndex = Number(targetRow.dataset.queueIndex);
    if (!Number.isInteger(targetRowIndex)) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const rect = targetRow.getBoundingClientRect();
    const edge = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    const rawInsertion = targetRowIndex + (edge === "after" ? 1 : 0);
    const position = Math.max(0, Math.min(schedule.length - 1, rawInsertion > gesture.sourceIndex ? rawInsertion - 1 : rawInsertion));
    const nextDrag = { batchId: gesture.batchId, position, targetRowIndex, edge } as const;
    queueDragRef.current = nextDrag;
    setQueueDrag(nextDrag);
  }

  function endQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = queueGestureRef.current;
    if (!gesture) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    const drop = queueDragRef.current;
    if (gesture.active && drop && drop.position !== gesture.sourceIndex) moveQueueBatch(gesture.batchId, selected.id, drop.position);
    queueGestureRef.current = null;
    queueDragRef.current = null;
    setQueueDrag(null);
  }

  const queueDragPreview = useMemo<PlacementPreview | null>(() => {
    if (!processQueueDrag || !selectedDownstreamResource) return null;
    try { return { valid: true, preview: previewProcessQueuePlacement(seed, result, { operationId: processQueueDrag.operationId, resourceId: selectedDownstreamResource.id, position: processQueueDrag.position }) }; }
    catch (error) { return { valid: false, reason: error instanceof Error ? error.message : "Bu sıra uygulanamaz." }; }
  }, [processQueueDrag, selectedDownstreamResource, seed, result]);
  useRaviScreenContext("machine-queue-placement", { processQueueDrag, queueDragReason: queueDragPreview?.valid ? queueDragPreview.preview.adjustments : queueDragPreview?.reason,
    processQueueFeedback, queueReviewError, dirty, processManualDialogOpen });
  useEffect(() => {
    if (!lastAppliedQueueMove) return;
    const operation = downstreamPlan.operations.find((item) => item.id === lastAppliedQueueMove.id);
    if (!operation || operation.start !== lastAppliedQueueMove.start || operation.end !== lastAppliedQueueMove.end || operation.resourceId !== lastAppliedQueueMove.resourceId) {
      setProcessQueueFeedback(null); setLastAppliedQueueMove(null); setRecentProcessOperationId("");
    }
  }, [downstreamPlan, lastAppliedQueueMove]);
  useEffect(() => {
    if (!recentProcessOperationId) return;
    const frame = requestAnimationFrame(() => processQueueListRef.current?.querySelector<HTMLElement>(".just-moved")?.scrollIntoView({ block: "center", behavior: "instant" }));
    const timer = window.setTimeout(() => setRecentProcessOperationId(""), 4500);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timer); };
  }, [recentProcessOperationId, lastAppliedQueueMove]);
  useEffect(() => {
    const cancel = (event: KeyboardEvent) => { if (event.key === "Escape") cancelProcessQueueDrag(); };
    window.addEventListener("keydown", cancel);
    return () => window.removeEventListener("keydown", cancel);
  }, []);

  function requestProcessQueueChange(request: ProcessQueuePlacementRequest) {
    try {
      const preview = previewProcessQueuePlacement(seed, result, request);
      if (preview.seed === seed) {
        setProcessQueueFeedback({ tone: "success", message: "İş zaten seçilen kuyruk sırasında; plan değişmedi." });
        setProcessManualDialogOpen(false);
        return;
      }
      onReviewRoute({ kind: "queue", ...request });
      setQueueReviewError("");
      setProcessQueueFeedback(null);
      setProcessManualDialogOpen(false);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Kuyruk değişikliği uygulanamadı.";
      setProcessQueueFeedback({ tone: "error", message });
      // Keep the manual placement dialog open with an inline error.
      if (processManualDialogOpen) throw new Error(message);
    }
  }

  function moveProcessQueueOperation(operation: ProcessOperation, position: number) {
    requestProcessQueueChange({ operationId: operation.id, resourceId: operation.resourceId, position });
  }

  function transferProcessQueueOperation(operation: ProcessOperation, resourceId: string) {
    requestProcessQueueChange({ operationId: operation.id, resourceId, position: "end" });
  }

  function placeProcessOperationManually(operationId: string, position: number) {
    if (!selectedDownstreamResource) return;
    requestProcessQueueChange({ operationId, resourceId: selectedDownstreamResource.id, position });
  }

  function startSelectedProcessJob() {
    if (!processStartCandidate) {
      setProcessQueueFeedback({ tone: "error", message: startAvailability.reason });
      return;
    }
    if (processStartCandidate.requiresInterruptionConfirmation) { setInterruptedStartId(processStartCandidate.id); return; }
    try {
      onStartProcessCurrentJob(processStartCandidate.id);
      setProcessQueueFeedback({ tone: "success", message: `${processStartCandidate.product}, ${processStartCandidate.resourceId} üzerinde mevcut üretime alındı.` });
    } catch (error) {
      setProcessQueueFeedback({ tone: "error", message: error instanceof Error ? error.message : "İş mevcut üretime alınamadı." });
    }
  }

  function replaceSelectedProcessJob(operation: ProcessOperation, input:ProductionInterruptionInput, confirmed:boolean) {
    if (!selectedDownstreamResource || !selectedProcessCurrentJob) return;
    try {
      onReplaceProcessCurrentJob(selectedDownstreamResource.id, operation.id, input, confirmed);
      setProcessJobSwitcherOpen(false);
      setProcessQueueFeedback({ tone: "success", message: `${operation.workOrder || operation.product} mevcut üretime alındı; önceki iş kuyruğun ilk sırasına taşındı.` });
    } catch (error) {
      setProcessQueueFeedback({ tone: "error", message: error instanceof Error ? error.message : "Mevcut iş değiştirilemedi." });
      throw error;
    }
  }

  function resetSelectedProcessQueue() {
    if (activeProcess !== "turning" && onReplanProcess(activeProcess)) setProcessQueueFeedback({ tone: "success", message: `${processLabel(activeProcess)} otomatik planlandı; Torna ve çalışan işler korundu.` });
  }

  function beginProcessQueueDrag(event: React.PointerEvent<HTMLButtonElement>, operation: ProcessOperation, index: number) {
    if (event.button !== 0 || operation.actual || operation.current) return;
    processQueueDragRef.current = null;
    setProcessQueueDrag(null);
    processQueueGestureRef.current = { operationId: operation.id, sourceIndex: index, startY: event.clientY, active: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continueProcessQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processQueueGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.abs(event.clientY - gesture.startY) < 5) return;
    gesture.active = true;
    const targetRow = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>(".process-machine-queue-row[data-process-queue-index]");
    if (!targetRow) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const targetRowIndex = Number(targetRow.dataset.processQueueIndex);
    if (!Number.isInteger(targetRowIndex)) { processQueueDragRef.current = null; setProcessQueueDrag(null); return; }
    const rect = targetRow.getBoundingClientRect();
    const edge = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    const rawInsertion = targetRowIndex + (edge === "after" ? 1 : 0);
    const position = Math.max(0, Math.min(selectedProcessSchedule.length - 1, rawInsertion > gesture.sourceIndex ? rawInsertion - 1 : rawInsertion));
    const nextDrag = { operationId: gesture.operationId, position, targetRowIndex, edge } as const;
    if (processQueueDragRef.current?.targetRowIndex === targetRowIndex && processQueueDragRef.current.edge === edge) return;
    processQueueDragRef.current = nextDrag;
    setProcessQueueDrag(nextDrag);
  }

  function cancelProcessQueueDrag() {
    processQueueGestureRef.current = null;
    processQueueDragRef.current = null;
    setProcessQueueDrag(null);
  }

  function endProcessQueueDrag(event: React.PointerEvent<HTMLButtonElement>) {
    const gesture = processQueueGestureRef.current;
    if (!gesture) return;
    if (gesture.active) {
