          <Metric compact label="Toplam miktar" value={formatNumber(turningQueueQuantity)} detail={`${selected.id} kuyruğundaki adet`} description="Seçili tezgah kuyruğundaki planlı şarjların adet toplamı." />
          <Metric compact label="Son planlı bitiş" value={schedule.length ? formatExcelDate(Math.max(...schedule.map((batch) => batch.end))) : "—"} detail={`${selected.id} kuyruğunun son işi`} description="Seçili tezgah kuyruğundaki son planlı şarjın bitiş tarihi." />
        </> : selectedDownstreamResource ? <>
