          <Field label="Müsait başlangıç"><input type="date" value={serialToInputDate(selected.operationalAvailableStart ?? selected.availableStart)} onChange={(event) => onSaveMachineAvailability(selected.id, inputDateToSerial(event.target.value))} /></Field>
          <Field label="Plan bitişi"><input type="date" value={serialToInputDate(selected.planEnd)} onChange={(event) => updateSeed((draft) => { const machine = draft.machines.find((item) => item.id === selected.id); if (machine) machine.planEnd = inputDateToSerial(event.target.value); })} /></Field>
          <Field label="Vardiya sayısı"><select value={selected.shiftFactor} onChange={(event) => updateSeed((draft) => { const machine = draft.machines.find((item) => item.id === selected.id); if (machine) machine.shiftFactor = Number(event.target.value); })}>{[0, 1, 2, 3].map((value) => <option key={value} value={value}>{value}</option>)}</select></Field>
        </MachineSettingsRow>
        <section className="machine-current-block" aria-label="Mevcut üretim"><div className="current-job"><div><span>Mevcut üretim</span><strong>{selected.currentJob.product || "Mevcut ürün yok"}<small>{selected.currentJob.workOrder || "İş emri yok"}</small></strong></div><div><span>Orijinal</span><strong>{formatNumber(selected.currentJob.originalQuantity ?? selected.currentJob.quantity)}</strong></div><div><span>Kalan</span><strong>{formatNumber(selected.currentJob.remainingQuantity ?? selected.currentJob.quantity)}</strong></div><div><span>Bitiş</span><strong>{formatExcelDate(selected.currentJob.end)}</strong></div><div><span>Çap</span><strong>{selected.currentJob.diameter || "—"}</strong></div></div><div className="machine-current-actions"><button className="ui-btn primary complete" disabled={!selected.currentJob.product} onClick={() => setCompletionOpen(true)}><ProcessIcon process={activeProcess} size={14} /> {processLabel(activeProcess)} prosesini bitir</button><Menu icon={<DotsThree size={18} weight="bold" />} title="Mevcut iş işlemleri" className="current-job-menu"><MenuItem icon={<PencilSimple size={15} />} onClick={() => setJobEditorOpen(true)}>Mevcut işi düzenle</MenuItem><MenuItem icon={<ArrowCounterClockwise size={15} />} disabled={!selected.currentJob.product} onClick={() => setTurningSwitcherOpen(true)}>Mevcut işi değiştir</MenuItem>{seed.productionArea !== "cubuk-filtre" && onCancelRemaining && selected.currentJob.product && <><MenuDivider /><MenuItem icon={<XCircle size={15} />} onClick={() => onCancelRemaining(selected.id, selected.currentJob.batchId ?? `current:${selected.id}`)}>Kalan üretimi iptal et</MenuItem></>}</Menu></div></section>
