        {schedule.length === 0 && <div className={`machine-diagnostic-panel ${diagnostic.tone}`}><Warning size={16} weight={diagnostic.tone === "critical" ? "fill" : "regular"} /><div><strong>{diagnostic.title}</strong><span>{diagnostic.detail}</span></div></div>}
        <section className="machine-queue-panel">
