          <div className="detail-heading"><div><h2>{selectedDownstreamResource.id}</h2><span>{selectedDownstreamResource.name}</span></div><div className="machine-heading-actions"><label className="switch-label"><input type="checkbox" checked={selectedDownstreamResource.active} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) resource.active = event.target.checked; })} /><span className="switch" /> Planlamada aktif</label><button className="ui-btn" disabled={!selectedDownstreamResource.active || !processManualCandidates.length} title={!processManualCandidates.length ? "Bu tezgâha yerleştirilebilecek planlı proses işi yok" : undefined} onClick={() => setProcessManualDialogOpen(true)}><Plus size={15} /> Manuel şarj</button><Menu label="Tezgah işlemleri" icon={<Wrench size={15} />} title="Kuyruğu ve günlük kapasiteyi düzenleyin" className="machine-actions-menu"><span className="ui-menu-label">{selectedProcessCalendarEvents.length} takvim kaydı</span><MenuItem icon={<Clock size={15} />} onClick={() => setProcessShiftDialogOpen(true)}>Günlük vardiya</MenuItem><MenuItem icon={<Wrench size={15} />} onClick={() => setProcessMaintenanceDialogOpen(true)}>Planlı bakım</MenuItem><MenuItem icon={<ArrowCounterClockwise size={15} />} onClick={resetSelectedProcessQueue} hint="Seçili proses otomatik planlanır; Torna ve çalışan işler korunur.">{processLabel(activeProcess)} otomatik plana dön<small className="ui-menu-hint">Torna ve çalışan işler korunur.</small></MenuItem><MenuDivider /><MenuItem icon={<PencilSimple size={15} />} onClick={() => setProcessCatalogOpen(true)}>Tezgahları yönet</MenuItem></Menu></div></div>
          <MachineSettingsRow key={`${activeProcess}:${selectedDownstreamResource.id}`} className="downstream-resource-settings" items={[{ label: "Müsait başlangıç", value: formatExcelDate(selectedDownstreamResource.availableStart ?? downstreamMachineAdapter!.availableStart) }, { label: "Plan bitişi", value: formatExcelDate(selectedDownstreamResource.planEnd ?? downstreamMachineAdapter!.planEnd) }, { label: "Vardiya sayısı", value: String(selectedDownstreamResource.defaultShifts) }]}>
            <Field label="Müsait başlangıç"><input type="date" value={serialToInputDate(selectedDownstreamResource.availableStart ?? downstreamMachineAdapter!.availableStart)} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) { const start = inputDateToSerial(event.target.value); resource.availableStart = start; if (!resource.planEnd || resource.planEnd < start) resource.planEnd = start; } })} /></Field><Field label="Plan bitişi"><input type="date" min={serialToInputDate(selectedDownstreamResource.availableStart ?? downstreamMachineAdapter!.availableStart)} value={serialToInputDate(selectedDownstreamResource.planEnd ?? downstreamMachineAdapter!.planEnd)} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) resource.planEnd = Math.max(resource.availableStart ?? 0, inputDateToSerial(event.target.value)); })} /></Field><Field label="Vardiya sayısı"><select value={selectedDownstreamResource.defaultShifts} onChange={(event) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === selectedDownstreamResource.id); if (resource) resource.defaultShifts = clampShiftCount(Number(event.target.value)); })}>{[0, 1, 2, 3].map((value) => <option key={value} value={value}>{value}</option>)}</select></Field>
          </MachineSettingsRow>
          <section className="machine-current-block downstream-current-block" aria-label="Mevcut üretim"><div className="current-job"><div><span>Mevcut üretim</span><strong>{selectedProcessCurrentJob?.product || "Mevcut ürün yok"}<small>{selectedProcessCurrentJob?.workOrder || "İş emri yok"}</small></strong></div><div><span>Orijinal</span><strong>{formatNumber(selectedProcessCurrentJob?.originalQuantity ?? 0)}</strong></div><div><span>Kalan</span><strong>{formatNumber(selectedProcessCurrentJob?.remainingQuantity ?? 0)}</strong></div><div><span>Bitiş</span><strong>{selectedProcessCurrentJob ? formatExcelDate(selectedProcessCurrentJob.end) : "—"}</strong></div><div><span>{activeProcess === "drilling" ? "Matkap" : "Setup"}</span><strong>{selectedProcessCurrentJob?.setupKey || "—"}</strong></div></div><div className="machine-current-actions">{selectedProcessCurrentJob ? <><button className="ui-btn primary complete" onClick={() => setProcessCompletionOpen(true)}><ProcessIcon process={activeProcess} size={14} /> {processLabel(activeProcess)} prosesini bitir</button><Menu icon={<DotsThree size={18} weight="bold" />} title="Mevcut iş işlemleri" className="current-job-menu"><MenuItem icon={<PencilSimple size={15} />} onClick={() => setProcessJobEditorOpen(true)}>Adedi düzenle</MenuItem><MenuItem icon={<ArrowCounterClockwise size={15} />} disabled={!processReplacementCandidates.length} hint={!processReplacementCandidates.length ? "Bu proseste üretime hazır başka şarj yok" : "Şarj numarasıyla mevcut işi değiştir"} onClick={() => setProcessJobSwitcherOpen(true)}>Mevcut işi değiştir</MenuItem></Menu></> : <button className="ui-btn primary" disabled={!processStartCandidate} aria-describedby={!processStartCandidate ? "process-start-blocker" : undefined} title={!processStartCandidate ? startAvailability.reason : undefined} onClick={startSelectedProcessJob}><Play size={14} weight="fill" /> Sıradaki işi üretime al</button>}</div></section>
          {!selectedProcessCurrentJob && (processStartCandidate ? <p className="process-start-help" role="status">Sıradaki hazır iş: {processStartCandidate.workOrder || processStartCandidate.product} · {processStartCandidate.product}</p> : <div id="process-start-blocker" className="process-start-blocker" role="status"><Warning size={16} /><div><strong>Üretim neden başlatılamıyor?</strong><p>{startAvailability.reason}</p>{startAvailability.guidance && <small>{startAvailability.guidance}</small>}</div></div>)}
          {dirty && <div className="manual-order-note"><Warning size={14} /><span><strong>Torna planı değişti.</strong> Downstream kuyrukları son hesaplanan torna planını gösteriyor; plan yeniden çalıştırıldığında tarihler güncellenir.</span></div>}
          {processQueueFeedback && <div className={`process-queue-feedback ${processQueueFeedback.tone}`} role={processQueueFeedback.tone === "error" ? "alert" : "status"}>{processQueueFeedback.tone === "error" ? <Warning size={15} weight="fill" /> : <CheckCircle size={15} weight="fill" />}<span>{processQueueFeedback.message}</span><button onClick={() => setProcessQueueFeedback(null)} aria-label="Kuyruk bildirimini kapat"><X size={12} /></button></div>}
          <section className="machine-queue-panel">
          <div className="queue-heading process-queue-heading"><h3>Planlanan tezgah kuyruğu<HelpTip text="Sıra kolunu tutup işi yukarı veya aşağı sürükleyin. Başka iş merkezine taşımak için satırdaki taşı simgesini kullanın." align="start" /></h3><label className="process-queue-search"><MagnifyingGlass size={14} /><input value={processQueueQuery} onChange={(event) => setProcessQueueQuery(event.target.value)} placeholder="Şarj no veya ürün ara" /></label></div>
          {unscheduledProcessQueue.filter(row=>!normalizedProcessQueueQuery || `${row.workOrder} ${row.product}`.toLocaleUpperCase("tr-TR").includes(normalizedProcessQueueQuery)).map(row=><div key={row.id} className="process-start-blocker unscheduled-queue-row" role="status"><Warning size={16}/><div><strong>{row.workOrder || row.product} · {row.product} · {formatNumber(row.quantity)} adet</strong><p>Kuyrukta korunuyor · Tarih hesaplanamadı</p><small>{row.reason}</small></div></div>)}
          {visibleProcessSchedule.length > 0 && <div className="queue-columns" aria-hidden="true"><span>Sıra</span><span>Şarj / ürün</span><span>İş emri / izlenebilirlik</span><span /></div>}
          <div ref={processQueueListRef} className="queue-list process-queue-list">{visibleProcessSchedule.length ? visibleProcessSchedule.map((operation) => {
            const index = selectedProcessSchedule.findIndex((item) => item.id === operation.id);
            const masterProduct = seed.processMasterData?.products.find((product) => product.product === operation.product);
            const parameter = masterProduct?.processes.find((item) => item.process === operation.process);
            const eligibleResources = downstreamResources.filter((resource) => resource.active && resource.defaultShifts > 0 && parameter && activeProcessResourceIds(parameter).includes(resource.id) && (parameter.unitsPerShift[resource.id] ?? 0) > 0);
            const wipLot = operation.wipLotId ? (seed.wipLots ?? []).find((lot) => lot.id === operation.wipLotId) : undefined;
            const canComplete = Boolean(wipLot && wipLot.nextProcess === operation.process && wipLot.availableQuantity > 0);
            return <ProcessMachineQueueRow onReviewRoute={() => onReviewRoute({ kind: "edit", batchId: operation.batchId, process: operation.process })} key={operation.id} operation={operation} index={index} count={selectedProcessSchedule.length} resources={eligibleResources} canComplete={canComplete} dragging={processQueueDrag?.operationId === operation.id} dropEdge={processQueueDrag?.targetRowIndex === index ? processQueueDrag.edge : null} recent={recentProcessOperationId === operation.id} onDragStart={(event) => beginProcessQueueDrag(event, operation, index)} onDragMove={continueProcessQueueDrag} onDragEnd={endProcessQueueDrag} onDragCancel={cancelProcessQueueDrag} onMove={(position) => moveProcessQueueOperation(operation, position)} onTransfer={(resourceId) => transferProcessQueueOperation(operation, resourceId)} onComplete={() => setQueuedProcessCompletion(operation)} />;
          }) : <p className="empty-copy">{selectedProcessSchedule.length ? "Bu aramayla eşleşen şarj bulunamadı." : `Bu iş merkezine yerleşen planlı ${processLabel(activeProcess).toLocaleLowerCase("tr-TR")} işi yok.`}</p>}</div>
          </section>
          <details className="machine-history"><summary>Üretim geçmişi ve planlama işlemleri</summary><div>{(seed.wipMovements ?? []).filter((movement) => movement.resourceId === selectedDownstreamResource.id).slice(-5).reverse().map((movement) => <article key={movement.id}><ProcessIcon process={movement.process ?? activeProcess} size={14} /><span><strong>{movement.process ? processLabel(movement.process) : processLabel(activeProcess)} · {formatNumber(movement.quantity)} adet</strong><small>{formatExcelDate(movement.occurredAt)} · {movement.kind === "process-completed" ? "operasyon tamamlandı" : "yarı mamül hareketi"}</small></span></article>)}{(seed.planningEvents ?? []).filter((event) => event.machineId === selectedDownstreamResource.id).slice(0, 8).map((event) => <article key={event.id}><CheckCircle size={14} /><span><strong>{event.message}</strong><small>{new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short" }).format(new Date(event.createdAt))}</small></span></article>)}{!(seed.wipMovements ?? []).some((movement) => movement.resourceId === selectedDownstreamResource.id) && !(seed.planningEvents ?? []).some((event) => event.machineId === selectedDownstreamResource.id) && <p className="empty-copy">Bu iş merkezi için henüz işlem kaydı yok.</p>}</div></details>
        </> : <p className="empty-copy">Bu proses için tanımlı tezgah yok.</p>}
      </div>
      {processJobEditorOpen && selectedProcessCurrentJob && <ProcessCurrentJobEditor seed={seed} job={selectedProcessCurrentJob} onClose={() => setProcessJobEditorOpen(false)} onSave={(input) => { onSaveProcessCurrentJob(selectedProcessCurrentJob.resourceId, input); setProcessJobEditorOpen(false); }} />}
      {processJobSwitcherOpen && selectedDownstreamResource && selectedProcessCurrentJob && <CurrentJobSwitchDialog signature={productionSwitchSignature(seed,result.batches)} resourceId={selectedDownstreamResource.id} workOrder={selectedProcessCurrentJob.workOrder} quantity={selectedProcessCurrentJob.originalQuantity} options={processReplacementCandidates} onClose={()=>setProcessJobSwitcherOpen(false)} onSelect={(id,input,confirmed)=>{const operation=processReplacementCandidates.find(item=>item.id===id);if(operation)replaceSelectedProcessJob(operation,input,confirmed);}}/>}
      {interruptedStartId && <InterruptedStartDialog workOrder={downstreamOperations.find(item=>item.id===interruptedStartId)?.workOrder ?? ''} onClose={()=>setInterruptedStartId(null)} onConfirm={()=>{onStartProcessCurrentJob(interruptedStartId,true);setInterruptedStartId(null);}}/>}
      {processCompletionOpen && selectedProcessCurrentJob && (() => {
        const lot = (seed.wipLots ?? []).find((item) => item.id === selectedProcessCurrentJob.wipLotId);
        const resources = actualProcessResources(seed, selectedProcessCurrentJob.process, selectedProcessCurrentJob.product);
        return lot ? <CompleteProcessCurrentJobDialog seed={seed} job={selectedProcessCurrentJob} lot={lot} resources={resources} nextOperation={selectedProcessSchedule.find((operation) => operation.source === "wip")} onClose={() => setProcessCompletionOpen(false)} onConfirm={(completedAt, completedQuantity, actualResourceId, remainderAction, confirmedBuffer, countCorrectionReason) => { onCompleteProcessCurrentJob(selectedProcessCurrentJob.resourceId, completedAt, completedQuantity, actualResourceId, remainderAction, confirmedBuffer, countCorrectionReason); setProcessCompletionOpen(false); }} /> : null;
      })()}
      {queuedProcessCompletion && queuedProcessCompletion.wipLotId && (() => {
        const lot = (seed.wipLots ?? []).find((item) => item.id === queuedProcessCompletion.wipLotId);
        const resources = actualProcessResources(seed, queuedProcessCompletion.process as DownstreamProcess, queuedProcessCompletion.product);
        return lot ? <CompleteQueuedProcessOperationDialog seed={seed} operation={queuedProcessCompletion} lot={lot} resources={resources} onClose={() => setQueuedProcessCompletion(null)} onConfirm={(input) => { const completed = onCompleteWipOperation(input); if (completed) setQueuedProcessCompletion(null); return completed; }} /> : null;
      })()}
      {processManualDialogOpen && selectedDownstreamResource && <ProcessManualBatchDialog resource={selectedDownstreamResource} operations={processManualCandidates} queueLength={selectedProcessSchedule.length} onClose={() => setProcessManualDialogOpen(false)} onSave={placeProcessOperationManually} />}
      {processShiftDialogOpen && downstreamMachineAdapter && <MachineShiftDialog machine={downstreamMachineAdapter} events={selectedProcessCalendarEvents.filter((event) => event.kind === "shift")} onClose={() => setProcessShiftDialogOpen(false)} onSave={(name, start, end, shifts, editingId) => { updateCalendar((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); } replaceMachineShiftOverrides(draft, [selectedDownstreamResource!.id], start, end, shifts, name); }); setProcessShiftDialogOpen(false); }} onDelete={(eventId) => updateCalendar((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === eventId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); })} />}
      {processMaintenanceDialogOpen && downstreamMachineAdapter && <MachineMaintenanceDialog machine={downstreamMachineAdapter} events={selectedProcessCalendarEvents.filter((event) => event.kind === "maintenance")} onClose={() => setProcessMaintenanceDialogOpen(false)} onSave={(name, start, end, editingId) => { updateCalendar((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) Object.assign(existing, { name, start, end, shiftCount: 0 }); } else draft.calendarEvents = [...(draft.calendarEvents ?? []), { id: `bakim-${Date.now()}`, machineId: selectedDownstreamResource!.id, kind: "maintenance", name, start, end, shiftCount: 0 }]; }); setProcessMaintenanceDialogOpen(false); }} onDelete={(eventId) => updateCalendar((draft) => { draft.calendarEvents = (draft.calendarEvents ?? []).filter((event) => event.id !== eventId); })} />}
      {processCatalogOpen && <ProcessResourceCatalogDialog process={activeProcess as DownstreamProcess} resources={downstreamResources} onClose={() => setProcessCatalogOpen(false)} onSave={(resourceId, name, active, defaultShifts) => updateCalendar((draft) => { const resource = draft.processMasterData?.resources.find((item) => item.id === resourceId); if (resource) Object.assign(resource, { name, active, defaultShifts }); })} />}
    </section>}
    {showFormGrindingReport && <FormGrindingShiftReport seed={seed} operations={downstreamPlan.operations} />}
    </div>
  );
}

function MachineSettingsRow({ items, className = "", children }: { items: { label: string; value: string }[]; className?: string; children: ReactNode }) {
  const [editing, setEditing] = useState(false);
  return <div className={`machine-settings ${editing ? "editing" : ""}`}>
    {editing ? <div className={`form-grid ${className}`}>{children}</div> : <dl>{items.map((item) => <div key={item.label}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl>}
    <button type="button" className="ui-btn" aria-expanded={editing} onClick={() => setEditing((value) => !value)}>{editing ? <><Check size={14} /> Bitti</> : <><PencilSimple size={14} /> Düzenle</>}</button>
  </div>;
}

function MachineCatalogDialog({ seed, result, onClose, onRename, onAdd, onDelete }: { seed: PlanningSeed; result: ScenarioResult; onClose: () => void; onRename: (machineId: string, name: string) => void; onAdd: (machine: Machine) => void; onDelete: (machineId: string, replacementId?: string) => void }) {
  const machines = seed.machines;
  const [names, setNames] = useState<Record<string, string>>(() => Object.fromEntries(machines.map((machine) => [machine.id, machine.name])));
  const nextNumber = Math.max(0, ...machines.map((machine) => Number(machine.id.match(/\d+/)?.[0] ?? 0))) + 1;
  const [newMachine, setNewMachine] = useState({ id: `C-${String(nextNumber).padStart(2, "0")}`, name: "" });
  const [error, setError] = useState("");
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [replacementId, setReplacementId] = useState("");
  const deletion = deletingId ? analyzeMachineDeletion(seed, result, deletingId) : null;

  function saveName(machine: Machine) {
    const name = names[machine.id]?.trim();
    if (!name) return setError(`${machine.id} için tezgah adı zorunludur.`);
    onRename(machine.id, name);
    setError("");
  }

  function addMachine() {
    const id = normalizeMachineId(newMachine.id);
    const name = newMachine.name.trim();
    if (!id) return setError("Tezgah kodunu C-18 biçiminde girin.");
    if (machines.some((machine) => machine.id === id)) return setError(`${id} zaten tanımlı.`);
    if (!name) return setError("Yeni tezgahın adını girin.");
    const start = inputDateToSerial(factoryDateInput());
    onAdd({ id, name, active: false, availableStart: start, planEnd: start + 30, note: "", shiftFactor: 0, capacityFactor: 1, finishOffset: 0, rates: {}, currentJob: { workOrder: "", product: "", quantity: 0, originalQuantity: 0, remainingQuantity: 0, start, end: 0, dailyRate: 0, diameter: "" } });
    setError("");
    onClose();
  }

  function requestDelete(machineId: string) {
    setDeletingId(machineId);
    setReplacementId("");
    setError("");
  }

  function confirmDelete() {
    if (!deletingId || !deletion || deletion.blocked || (deletion.requiresReplacement && !replacementId)) return;
    try {
      onDelete(deletingId, replacementId || undefined);
      setDeletingId(null);
      setReplacementId("");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Tezgah silinemedi.");
    }
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="machine-catalog-dialog machine-dialog" role="dialog" aria-modal="true" aria-label="Tezgahları yönet"><div className="operational-dialog-head"><span className="dialog-icon shift"><ProcessIcon process="turning" size={19} /></span><div><span>TEZGAH ANA VERİSİ</span><h2>Tezgahları yönet</h2><p>Adları güncelleyin, yeni tezgah ekleyin veya bağımlılıkları güvenle aktararak silin.</p></div><button className="delete-button" onClick={onClose} aria-label="Tezgah yönetimini kapat"><X size={16} /></button></div><div className="machine-catalog-list">{machines.map((machine) => { const changed = (names[machine.id] ?? "").trim() !== machine.name; return <div key={machine.id}><strong>{machine.id}</strong><input value={names[machine.id] ?? ""} onChange={(event) => setNames((current) => ({ ...current, [machine.id]: event.target.value }))} aria-label={`${machine.id} tezgah adı`} /><button disabled={!changed || !(names[machine.id] ?? "").trim()} onClick={() => saveName(machine)}>Kaydet</button><button className="delete-button machine-catalog-delete" onClick={() => requestDelete(machine.id)} aria-label={`${machine.id} tezgahını sil`}><Trash size={14} /></button></div>; })}</div>{deletion && <section className={`machine-delete-panel ${deletion.blocked ? "blocked" : ""}`}><div><span>TEZGAH SİLME KONTROLÜ</span><h3>{deletion.machineId} silinsin mi?</h3></div>{deletion.blocked ? <div className="machine-delete-blocker"><Warning size={18} weight="fill" /><span><strong>Tezgah şu anda silinemez.</strong><small>{deletion.currentJobProduct ? `Mevcut üretim: ${deletion.currentJobProduct}. ` : ""}{deletion.plannedBatches.length ? `${deletion.plannedBatches.length} planlı şarj önce tamamlanmalı veya başka tezgaha taşınmalı.` : "Mevcut iş tamamlanmalı."}</small></span></div> : <><div className="machine-delete-impact"><span><b>{deletion.parameterProducts.length}</b><small>ürün parametresi</small></span><span><b>{deletion.savedBatchCount}</b><small>kayıtlı plan işi</small></span><span><b>{deletion.calendarEventCount}</b><small>takvim kaydı silinir</small></span></div>{deletion.requiresReplacement && <Field label="Parametreleri aktar"><select value={replacementId} onChange={(event) => setReplacementId(event.target.value)}><option value="">Alternatif tezgah seçin</option>{machines.filter((machine) => machine.id !== deletion.machineId).map((machine) => <option key={machine.id} value={machine.id}>{machine.id} · {machine.name}</option>)}</select></Field>}<p>{deletion.requiresReplacement ? "Ürün öncelikleri, uygunluk kayıtları ve eksik üretim hızları seçilen tezgaha aktarılır. Mevcut hedef hızlar ezilmez." : "Bu tezgaha bağlı aktif iş veya ürün parametresi bulunmuyor."}</p></>}<div className="drawer-actions"><button className="secondary" onClick={() => { setDeletingId(null); setReplacementId(""); }}>Vazgeç</button><button className="danger-outline" disabled={deletion.blocked || (deletion.requiresReplacement && !replacementId)} onClick={confirmDelete}><Trash size={14} /> Tezgahı sil</button></div></section>}<div className="machine-catalog-add"><div><span>YENİ TEZGAH</span><p>Yeni tezgah pasif ve 0 vardiya ile eklenir. Hız ve ürün öncelikleri Parametreler’den tanımlanır.</p></div><Field label="Tezgah kodu"><input value={newMachine.id} onChange={(event) => setNewMachine({ ...newMachine, id: event.target.value })} /></Field><Field label="Tezgah adı"><input value={newMachine.name} onChange={(event) => setNewMachine({ ...newMachine, name: event.target.value })} placeholder="Makine / model" /></Field><button className="primary" onClick={addMachine}><Plus size={14} /> Tezgah ekle</button></div>{error && <p className="form-error catalog-error">{error}</p>}</section></div>;
}

function ProcessManualBatchDialog({ resource, operations, queueLength, onClose, onSave }: { resource: ProcessResource; operations: ProcessOperation[]; queueLength: number; onClose: () => void; onSave: (operationId: string, position: number) => void }) {
  const first = [...operations].sort((left, right) => left.readyAt - right.readyAt || left.id.localeCompare(right.id))[0];
  const [operationId, setOperationId] = useState(first?.id ?? "");
  const selected = operations.find((operation) => operation.id === operationId) ?? first;
  const positionCount = Math.max(1, queueLength + (selected?.resourceId === resource.id && !selected?.manualCandidate ? 0 : 1));
  const [position, setPosition] = useState(positionCount - 1);
  const [error, setError] = useState("");
  useRaviScreenContext("machine-manual-queue-placement", { resourceId: resource.id, operationId: selected?.id, position: Math.min(position, positionCount - 1), positionBase: 0, readyAt: selected?.readyAt, error });
  function review() {
    if (!selected) return;
    try { setError(""); onSave(selected.id, Math.min(position, positionCount - 1)); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "Yerleşim uygulanamaz."); }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog machine-dialog" role="dialog" aria-modal="true" aria-label={`${resource.id} manuel proses şarjı ekleme`}><div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>MANUEL PLANLAMA</span><h2>{resource.id} kuyruğuna şarj ekle</h2><p>İzlenebilirliği korumak için planlı bir proses işi seçilir; miktar çoğaltılmadan bu tezgâhın kuyruğuna yerleştirilir.</p></div><button className="delete-button" onClick={onClose} aria-label="Manuel şarj penceresini kapat"><X size={16} /></button></div><div className="operational-dialog-form"><Field label="Planlı proses işi"><select aria-label="Planlı proses işi" value={selected?.id ?? ""} onChange={(event) => { const next = operations.find((operation) => operation.id === event.target.value); setError(""); setOperationId(event.target.value); setPosition(Math.max(0, queueLength + (next?.resourceId === resource.id && !next?.manualCandidate ? 0 : 1) - 1)); }}>{[...operations].sort((left, right) => left.readyAt - right.readyAt || left.id.localeCompare(right.id)).map((operation) => <option key={operation.id} value={operation.id}>{operation.product} · {formatNumber(operation.quantity)} adet · {operation.resourceId} · {operation.workOrder || "iş emri yok"}{operation.manualCandidate ? " · Yarım üretim (manuel)" : ""}</option>)}</select></Field><Field label="Kuyruk sırası"><select aria-label="Kuyruk sırası" value={Math.min(position, positionCount - 1)} onChange={(event) => { setError(""); setPosition(Number(event.target.value)); }}>{Array.from({ length: positionCount }, (_, index) => <option key={index} value={index}>{index + 1}. sıra</option>)}</select></Field>{selected && <div className="manual-batch-preview four"><span><small>Ürün</small><strong>{selected.product}</strong></span><span><small>Miktar</small><strong>{formatNumber(selected.quantity)}</strong></span><span><small>Mevcut tezgâh</small><strong>{selected.resourceId}</strong></span><span><small>Hazır olma</small><strong>{formatExcelDate(selected.readyAt)}</strong></span></div>}<div className="calendar-impact-note"><strong>{selected?.resourceId === resource.id ? "Kuyruk sırası değiştirilecek" : `${selected?.resourceId ?? "—"} → ${resource.id} transferi`}</strong><span>Ürünün proses rotası, miktarı ve önceki operasyon bağı korunur; yalnızca uygun tezgâh ve sıra tercihi kaydedilir.</span></div>{error && <p className="form-error" role="alert">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!selected} onClick={review}><Plus size={14} /> Yerleşimi incele</button></div></div></section></div>;
}

function ProcessResourceCatalogDialog({ process, resources, onClose, onSave }: { process: DownstreamProcess; resources: ProcessResource[]; onClose: () => void; onSave: (resourceId: string, name: string, active: boolean, defaultShifts: ShiftCount) => void }) {
  const [drafts, setDrafts] = useState<Record<string, { name: string; active: boolean; defaultShifts: ShiftCount }>>(() => Object.fromEntries(resources.map((resource) => [resource.id, { name: resource.name, active: resource.active, defaultShifts: resource.defaultShifts }])));
  const [savedId, setSavedId] = useState("");
  return <div className="confirmation-backdrop" role="presentation"><section className="machine-catalog-dialog process-resource-catalog-dialog machine-dialog" role="dialog" aria-modal="true" aria-label={`${processLabel(process)} tezgahlarını yönet`}><div className="operational-dialog-head"><span className="dialog-icon shift"><ProcessIcon process={process} size={19} /></span><div><span>TEZGAH ANA VERİSİ</span><h2>{processLabel(process)} tezgahlarını yönet</h2><p>Tezgâh adını, planlama durumunu ve normal vardiya kapasitesini tek yerden güncelleyin.</p></div><button className="delete-button" onClick={onClose} aria-label="Tezgah yönetimini kapat"><X size={16} /></button></div><div className="process-resource-catalog-list"><div className="process-resource-catalog-head"><span>Tezgah</span><span>Tam adı</span><span>Durum</span><span>Normal vardiya</span><span /></div>{resources.map((resource) => { const draft = drafts[resource.id]; const changed = Boolean(draft && (draft.name.trim() !== resource.name || draft.active !== resource.active || draft.defaultShifts !== resource.defaultShifts)); return <div key={resource.id}><strong>{resource.id}</strong><input value={draft?.name ?? ""} onChange={(event) => setDrafts((current) => ({ ...current, [resource.id]: { ...current[resource.id], name: event.target.value } }))} aria-label={`${resource.id} tezgah adı`} /><label className="switch-label compact"><input type="checkbox" checked={draft?.active ?? false} onChange={(event) => setDrafts((current) => ({ ...current, [resource.id]: { ...current[resource.id], active: event.target.checked } }))} /><span className="switch" /> {draft?.active ? "Aktif" : "Pasif"}</label><select value={draft?.defaultShifts ?? 0} onChange={(event) => setDrafts((current) => ({ ...current, [resource.id]: { ...current[resource.id], defaultShifts: clampShiftCount(Number(event.target.value)) } }))} aria-label={`${resource.id} normal vardiya`}><ShiftOptions /></select><button disabled={!changed || !draft?.name.trim()} onClick={() => { if (!draft) return; onSave(resource.id, draft.name.trim(), draft.active, draft.defaultShifts); setSavedId(resource.id); window.setTimeout(() => setSavedId((current) => current === resource.id ? "" : current), 1200); }}>{savedId === resource.id ? "Kaydedildi" : "Kaydet"}</button></div>; })}</div><div className="process-resource-catalog-note"><CheckCircle size={15} weight="fill" /><span><strong>Değişiklikler planı yeniden hesaplar.</strong><small>Yeni tezgâh veya ürün hızı tanımı Parametreler sayfasından eklenir; burası günlük operasyon yönetimi içindir.</small></span></div></section></div>;
}

function MachineQueueRow({ dotColor, onCancelRemaining, batch, interrupted, protectedRemainder, setupFamily, index, count, eligibleMachines, dragging, dropEdge, onDragStart, onDragMove, onDragEnd, onMove, onTransfer, onEditQuantity, onRemove, onLock, onUnlock, onSaveWorkOrder }: { dotColor?: string; onCancelRemaining?: () => void; batch: PlannedBatch; interrupted: boolean; protectedRemainder: boolean; setupFamily?: ProductSetupFamily; index: number; count: number; eligibleMachines: string[]; dragging: boolean; dropEdge: "before" | "after" | null; onDragStart: (event: React.PointerEvent<HTMLButtonElement>) => void; onDragMove: (event: React.PointerEvent<HTMLButtonElement>) => void; onDragEnd: (event: React.PointerEvent<HTMLButtonElement>) => void; onMove: (position: number) => void; onTransfer: (machineId: string) => void; onEditQuantity: () => void; onRemove: () => void; onLock: () => void; onUnlock: () => void; onSaveWorkOrder: (workOrder: string) => void }) {
  const [workOrder, setWorkOrder] = useState(batch.workOrder ?? "");
  const [targetMachine, setTargetMachine] = useState(batch.machineId);
  const [editing, setEditing] = useState(false);
  useEffect(() => setWorkOrder(batch.workOrder ?? ""), [batch.id, batch.workOrder]);
  useEffect(() => setTargetMachine(batch.machineId), [batch.id, batch.machineId]);
  return <div data-queue-index={index} data-batch-id={batch.id} className={`machine-queue-row ${batch.locked ? "locked" : ""} ${editing ? "editing" : ""} ${dragging ? "dragging" : ""} ${dropEdge ? `drop-${dropEdge}` : ""}`}>
    {batch.locked ? <span className="queue-index" title="Kilitli"><Lock size={12} weight="fill" /><b>{queuePosition(batch.planColumn)}</b></span> : <button className="queue-drag-handle" onPointerDown={onDragStart} onPointerMove={onDragMove} onPointerUp={onDragEnd} onPointerCancel={onDragEnd} aria-label={`${batch.product} işini sürükleyerek sırala`} title="Tut ve sırayı değiştir"><DotsSixVertical size={13} /><b>{queuePosition(batch.planColumn)}</b></button>}
    <strong><i className="queue-dot" aria-hidden="true" title={batch.diameter} style={{ background: dotColor ?? "var(--ui-line-strong)" }} />{batch.product}{interrupted && <em className="interrupted-label">Üretime ara verildi.</em>}<small>{productSetupFamilyLabel(setupFamily)} · {batch.diameter} · {formatNumber(batch.quantity)} adet · setup {formatHours(batch.setupHours)} · {formatExcelDate(batch.start)} → {formatExcelDate(batch.end)}</small></strong>
    <span className="queue-work-order-value"><span className="queue-cell-label">İş emri / izlenebilirlik</span><b className="tracking-number">{batch.workOrder || "İş emri yok"}</b></span>
    <div className="queue-row-actions"><button className="ui-icon-btn" disabled={batch.locked || index === 0} onClick={() => onMove(index - 1)} aria-label={`${batch.product} yukarı taşı`}><CaretUp size={14} /></button><button className="ui-icon-btn" disabled={batch.locked || index === count - 1} onClick={() => onMove(index + 1)} aria-label={`${batch.product} aşağı taşı`}><CaretDown size={14} /></button>{batch.locked ? <button className="ui-icon-btn" onClick={onUnlock} aria-label="Kuyruk kilidini kaldır" title="Kuyruk kilidini kaldır"><LockOpen size={14} /></button> : <button className="ui-icon-btn" onClick={onLock} aria-label={`${batch.product} sırasına kadar kilitle`} title="Bu sıraya kadar kilitle"><Lock size={14} /></button>}<button className="ui-icon-btn queue-edit-toggle" aria-expanded={editing} onClick={() => setEditing((value) => !value)} aria-label={`${batch.product} satırını düzenle`} title="Düzenle"><PencilSimple size={14} /></button></div>
    {editing && <div className="queue-row-editor">
      <label className="queue-work-order"><span>İş emri / izlenebilirlik</span><span><input disabled={protectedRemainder} value={workOrder} onChange={(event) => setWorkOrder(event.target.value)} placeholder="320-…" /><button className="ui-btn" disabled={workOrder.trim() === (batch.workOrder ?? "")} onClick={() => onSaveWorkOrder(workOrder)}>Kaydet</button></span></label>
      <label className="queue-transfer"><span>Uygun tezgaha taşı</span><span><select disabled={batch.locked} value={targetMachine} onChange={(event) => setTargetMachine(event.target.value)}>{eligibleMachines.map((machineId) => <option key={machineId} value={machineId}>{machineId}</option>)}</select><button className="ui-btn" disabled={batch.locked || targetMachine === batch.machineId} onClick={() => onTransfer(targetMachine)}>Taşı</button></span></label>
      <div className="queue-row-editor-actions"><button className="ui-btn" disabled={batch.locked || protectedRemainder} onClick={onEditQuantity} aria-label={`${batch.product} adedini düzenle`} title="Adedi düzenle"><PencilSimple size={14} /> Adedi düzenle</button>{onCancelRemaining && <button className="ui-btn" onClick={onCancelRemaining}>Kalan üretimi iptal et</button>}<button className="ui-btn remove" disabled={batch.locked || protectedRemainder} onClick={onRemove} aria-label={`${batch.product} plandan çıkar`}><Trash size={14} /> Plandan çıkar</button><button className="ui-btn queue-editor-close" onClick={() => setEditing(false)}>Kapat</button></div>
    </div>}
  </div>;
}

export function ProcessMachineQueueRow({ onReviewRoute, operation, index, count, resources, canComplete, dragging, dropEdge, recent, onDragStart, onDragMove, onDragEnd, onDragCancel, onMove, onTransfer, onComplete }: {
  operation: ProcessOperation;
  index: number;
  count: number;
  resources: ProcessResource[];
  canComplete: boolean;
  onReviewRoute: () => void;
  dragging: boolean;
  dropEdge: "before" | "after" | null;
  recent: boolean;
