    <button className="queue-drag-handle" onPointerDown={onDragStart} onPointerMove={onDragMove} onPointerUp={onDragEnd} onPointerCancel={onDragCancel} onLostPointerCapture={onDragCancel} aria-label={`${name} işini sürükleyerek sırala`} title="Tut ve sırayı değiştir"><DotsSixVertical size={13} /><b>{index + 1}</b></button>
    <strong><b className="process-queue-charge">{operation.workOrder || "Şarj no yok"}</b>{operation.product}<small>{family} · {formatNumber(operation.quantity)} adet · setup {formatHours(operation.setupHours)} · {formatExcelDate(operation.start)} → {formatExcelDate(operation.end)}</small></strong>
    <span className="queue-work-order-value"><span className="queue-cell-label">İş emri / izlenebilirlik</span><span className="process-queue-work-order"><b>{operation.workOrder || "İş emri yok"}</b><em>{operation.source === "wip" ? "Yarı mamül" : operation.source === "current-turning" ? "Tornada çalışan" : "Torna planı"}</em></span></span>
    <div className="queue-row-actions process-queue-row-actions"><button className="ui-icon-btn" onClick={onReviewRoute} aria-label={`${name} üretim akışını düzenle`} title="Üretim akışını düzenle"><PencilSimple size={14} /></button><button className="ui-icon-btn" disabled={index === 0} onClick={() => onMove(index - 1)} aria-label={`${name} yukarı taşı`}><CaretUp size={14} /></button><button className="ui-icon-btn" disabled={index === count - 1} onClick={() => onMove(index + 1)} aria-label={`${name} aşağı taşı`}><CaretDown size={14} /></button><button className="ui-icon-btn queue-edit-toggle" aria-expanded={transferOpen} onClick={() => setTransferOpen((value) => !value)} aria-label={`${name} uygun iş merkezine taşı`} title="Uygun iş merkezine taşı"><ArrowsLeftRight size={14} /></button><button className="ui-icon-btn complete-queued-process" disabled={!canComplete} onClick={onComplete} aria-label={`${name} · ${processLabel(operation.process)} prosesini bitir`} title={canComplete ? `${processLabel(operation.process)} prosesini sırayı değiştirmeden bitir` : "Yalnız üretime hazır yarı mamül işler tamamlanabilir"}><ProcessIcon process={operation.process} size={14} /></button></div>
    {transferOpen && <div className="queue-row-editor">
      <label className="queue-transfer"><span>Uygun iş merkezine taşı</span><span><select value={targetResource} onChange={(event) => setTargetResource(event.target.value)}>{resources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select><button className="ui-btn" disabled={targetResource === operation.resourceId} onClick={() => onTransfer(targetResource)}>Taşı</button></span></label>
      <div className="queue-row-editor-actions"><button className="ui-btn queue-editor-close" onClick={() => setTransferOpen(false)}>Kapat</button></div>
    </div>}
  </div>;
}

