ndan hesaplanır. Vardiya, tatil ve bakım takvimi kullanılır." : "Kalan adet kaydedildiğinde setup, vardiya, tatil ve bakım takvimi kullanılarak bitiş yeniden hesaplanır."}</p></div>{(error || previewError) && <p className="form-error">{error || previewError}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={Boolean(previewError)} onClick={submit}>Adedi kaydet</button></div></div></aside></div>;
}

export function CompleteProcessCurrentJobDialog({ seed, job, lot, resources, nextOperation, onClose, onConfirm }: { seed: PlanningSeed; job: ProcessCurrentJob; lot: WipLot; resources: ProcessResource[]; nextOperation?: ProcessOperation; onClose: () => void; onConfirm: (completedAt: number, completedQuantity: number, actualResourceId: string, remainderAction?: ProcessRemainderAction, confirmedBuffer?: boolean, countCorrectionReason?: string) => void }) {
  const realReadyAt = wipCompletionEarliestAt(seed, lot);
  const [confirmedBuffer, setConfirmedBuffer] = useState(false);
  const [completedDate, setCompletedDate] = useState(factoryDateTimeInput);
  const [completedQuantity, setCompletedQuantity] = useState(job.originalQuantity);
  const [countCorrectionReason, setCountCorrectionReason] = useState("");
  const [remainderAction, setRemainderAction] = useState<ProcessRemainderAction | "">("");
  const [actualResourceId, setActualResourceId] = useState(resources.some((resource) => resource.id === job.resourceId) ? job.resourceId : resources[0]?.id ?? "");
  const [error, setError] = useState("");
  useRaviScreenContext("process-completion", { lotId: lot.id, completedDate, completedQuantity, availableQuantity: lot.availableQuantity, countCorrectionReason, remainderAction, actualResourceId, realReadyAt, plannedReadyAt: wipOperationReadyAt(lot), confirmedBuffer, error });
  function confirm() {
    try {
      if (!completedDate) throw new Error("Tamamlanma tarihi zorunludur.");
      if (!actualResourceId) throw new Error("Fiili iş merkezi seçilmelidir.");
      if (!Number.isInteger(completedQuantity) || completedQuantity <= 0) throw new Error("Fiili tamamlanan adet sıfırdan büyük tam sayı olmalıdır.");
      const action = requireProcessRemainderAction(lot.availableQuantity, completedQuantity, remainderAction, countCorrectionReason);
      onConfirm(parseProcessCompletionTime(completedDate, realReadyAt), completedQuantity, actualResourceId, action, confirmedBuffer, countCorrectionReason);
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "İş tamamlanamadı.");
