  return <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog machine-dialog" role="dialog" aria-modal="true" aria-label={`${job.resourceId} işi tamamlama onayı`}><ProcessIcon process={job.process} size={24} /><span>{processLabel(job.process).toLocaleUpperCase("tr-TR")} GEÇİŞİ</span><h2>{job.product} işi tamamlandı mı?</h2><p><b className="tracking-number">{job.workOrder || "İş emri yok"}</b> kaydı tamamlanacak ve yarı mamül ürün rotasındaki sonraki operasyona gönderilecek.</p><Field label="Fiili tamamlanan adet"><input type="number" min="1" step="1" value={completedQuantity || ""} onChange={(event) => setCompletedQuantity(Number(event.target.value))} /></Field><ProcessCountCorrection available={lot.availableQuantity} completed={completedQuantity} reason={countCorrectionReason} onChange={setCountCorrectionReason} /><ProcessRemainderChoice available={lot.availableQuantity} completed={completedQuantity} action={remainderAction} onChange={setRemainderAction} name="current-process-remainder" /><Field label="Fiili iş merkezi"><select value={actualResourceId} onChange={(event) => setActualResourceId(event.target.value)}>{resources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select></Field><ProcessCompletionTimeField value={completedDate} readyAt={realReadyAt} plannedReadyAt={wipOperationReadyAt(lot)} confirmedBuffer={confirmedBuffer} onConfirmBuffer={setConfirmedBuffer} onChange={value => { setCompletedDate(value); setConfirmedBuffer(false); }} /><div className="completion-next"><small>Sıradaki hazır iş</small><strong>{nextOperation ? `${nextOperation.product} · ${formatNumber(nextOperation.quantity)} adet` : "Hazır yarı mamül yok"}</strong><span>{nextOperation ? "Uygunsa onaydan sonra mevcut üretime geçirilir." : "İş merkezi boş mevcut iş durumuna geçer."}</span></div>{error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={confirm}><ProcessIcon process={job.process} size={15} /> {processLabel(job.process)} prosesini bitir</button></div></section></div>;
}

export function CompleteQueuedProcessOperationDialog({ seed, operation, lot, resources, onClose, onConfirm }: { seed: PlanningSeed; operation: ProcessOperation; lot: WipLot; resources: ProcessResource[]; onClose: () => void; onConfirm: (input: WipOperationInput) => boolean }) {
  const realReadyAt = wipCompletionEarliestAt(seed, lot);
  const [confirmedBuffer, setConfirmedBuffer] = useState(false);
  const [completedDate, setCompletedDate] = useState(factoryDateTimeInput);
  const [completedQuantity, setCompletedQuantity] = useState(lot.availableQuantity);
  const [countCorrectionReason, setCountCorrectionReason] = useState("");
  const [remainderAction, setRemainderAction] = useState<ProcessRemainderAction | "">("");
  const [actualResourceId, setActualResourceId] = useState(resources.some((resource) => resource.id === operation.resourceId) ? operation.resourceId : resources[0]?.id ?? "");
  const [confirmedInterruption,setConfirmedInterruption]=useState(false);
  const [error, setError] = useState("");
  useRaviScreenContext("process-completion", { lotId: lot.id, completedDate, completedQuantity, availableQuantity: lot.availableQuantity, countCorrectionReason, remainderAction, actualResourceId, realReadyAt, plannedReadyAt: wipOperationReadyAt(lot), confirmedBuffer, confirmedInterruption, error });
  function confirm() {
    try {
      if (!completedDate) throw new Error("Tamamlanma tarihi zorunludur.");
      const actualResource = resources.find((resource) => resource.id === actualResourceId);
      if (!actualResource) throw new Error("Fiili iş merkezi seçilmelidir.");
      if (!Number.isInteger(completedQuantity) || completedQuantity <= 0) throw new Error("Fiili adet açık yarı mamül miktarını aşmayan pozitif tam sayı olmalıdır.");
      const action = requireProcessRemainderAction(lot.availableQuantity, completedQuantity, remainderAction, countCorrectionReason);
      const completedAt = parseProcessCompletionTime(completedDate, realReadyAt);
      if (completedAt < realReadyAt) throw new Error(`Bu proses en erken ${formatExcelDate(realReadyAt)} tarihinde tamamlanabilir.`);
      const completed = onConfirm({
        lotId: lot.id,
        confirmedInterruption,
        confirmedBuffer,
        process: operation.process as DownstreamProcess,
        resourceId: actualResource.id,
        resourceName: actualResource.name,
        quantity: completedQuantity,
        countCorrectionReason,
        remainderAction: action,
        startedAt: Math.max(realReadyAt, Math.min(operation.start, completedAt)),
        completedAt,
        plannedStart: operation.start,
        plannedEnd: operation.end,
      });
      if (!completed) throw new Error("İş tamamlanamadı; ekrandaki uyarıyı kontrol edin.");
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "İş tamamlanamadı.");
    }
  }
  return <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog machine-dialog" role="dialog" aria-modal="true" aria-label={`${operation.workOrder || operation.product} kuyruk işini tamamlama onayı`}><ProcessIcon process={operation.process} size={24} /><span>{processLabel(operation.process).toLocaleUpperCase("tr-TR")} TAMAMLAMA</span><h2>{operation.workOrder || operation.product}</h2><p>Şarjı kuyruğun başına taşımadan {processLabel(operation.process).toLocaleLowerCase("tr-TR")} tamamlanmış olarak kaydedilecek ve sonraki operasyona gönderilecek.</p><Field label="Fiili tamamlanan adet"><input type="number" min="1" step="1" value={completedQuantity || ""} onChange={(event) => setCompletedQuantity(Number(event.target.value))} /></Field><ProcessCountCorrection available={lot.availableQuantity} completed={completedQuantity} reason={countCorrectionReason} onChange={setCountCorrectionReason} /><ProcessRemainderChoice available={lot.availableQuantity} completed={completedQuantity} action={remainderAction} onChange={setRemainderAction} name="queued-process-remainder" /><Field label="Fiili iş merkezi"><select value={actualResourceId} onChange={(event) => setActualResourceId(event.target.value)}>{resources.map((resource) => <option key={resource.id} value={resource.id}>{resource.id} · {resource.name}</option>)}</select></Field><ProcessCompletionTimeField value={completedDate} readyAt={realReadyAt} plannedReadyAt={wipOperationReadyAt(lot)} confirmedBuffer={confirmedBuffer} onConfirmBuffer={setConfirmedBuffer} onChange={value => { setCompletedDate(value); setConfirmedBuffer(false); }} /><div className="completion-next"><small>Planlanan iş merkezi</small><strong>{operation.resourceId} · {operation.resourceName}</strong><span>Fiili kayıt seçtiğiniz iş merkezine yazılır. Mevcut çalışan iş değişmez.</span></div>{operation.requiresInterruptionConfirmation && <InterruptionConsent checked={confirmedInterruption} onChange={setConfirmedInterruption}/>} {error && <p className="form-error">{error}</p>}<div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" onClick={confirm}><ProcessIcon process={operation.process} size={15} /> {processLabel(operation.process)} prosesini bitir</button></div></section></div>;
}
export function BatchQuantityDialog({ batch, setupFamily, onClose, onSave }: { batch: PlannedBatch; setupFamily?: ProductSetupFamily; onClose: () => void; onSave: (quantity: number) => void }) {
  const batchSize = batch.batchSize;
  const [quantity, setQuantity] = useState(batch.quantity);
  const freeQuantity = setupFamily === "center-pin";
  const chargeCount = batchSize > 0 ? quantity / batchSize : 0;
  const validQuantity = Number.isInteger(quantity) && quantity > 0 && (freeQuantity || (batchSize > 0 && Number.isInteger(chargeCount)));
  const valid = validQuantity && quantity !== batch.quantity;
  const difference = quantity - batch.quantity;
  const changeStep = freeQuantity ? 1 : batchSize;
  const changeQuantity = (delta: number) => setQuantity(Math.max(freeQuantity ? 1 : batchSize, quantity + delta * changeStep));
  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog quantity-dialog machine-dialog" role="dialog" aria-modal="true" aria-label={`${batch.product} planlanan adedi düzenle`}>
    <div className="operational-dialog-head"><span className="dialog-icon quantity"><PencilSimple size={20} /></span><div><span>PLANLANAN ŞARJ</span><h2>Üretim adedini düzenle</h2><p>{batch.product} · {batch.machineId} kuyruğunda {queuePosition(batch.planColumn)}. sıra</p></div><button className="delete-button" onClick={onClose} aria-label="Adet düzenlemeyi kapat"><X size={16} /></button></div>
    <div className="quantity-current"><span><small>Mevcut adet</small><strong>{formatNumber(batch.quantity)}</strong></span><span><small>Ürün ailesi</small><strong>{productSetupFamilyLabel(setupFamily)}</strong></span><span><small>{freeQuantity ? "Miktar kuralı" : "Standart şarj"}</small><strong>{freeQuantity ? "Serbest adet" : formatNumber(batchSize)}</strong></span></div>
    <div className="quantity-editor"><button onClick={() => changeQuantity(-1)} disabled={quantity <= (freeQuantity ? 1 : batchSize)}><Minus size={15} /> {freeQuantity ? "1 adet" : "1 şarj"}</button><label><span>Yeni üretim adedi</span><input type="number" min={freeQuantity ? 1 : batchSize} step={freeQuantity ? 1 : batchSize} value={quantity} onChange={(event) => setQuantity(Number(event.target.value))} /></label><button onClick={() => changeQuantity(1)}><Plus size={15} /> {freeQuantity ? "1 adet" : "1 şarj"}</button></div>
    {validQuantity ? <div className={`quantity-preview ${freeQuantity ? "free-quantity" : ""}`}><div><strong>{freeQuantity ? "Center pim için serbest miktar" : `${formatNumber(chargeCount)} tam şarj`}</strong><span>{freeQuantity ? "1980 veya başka bir standart şarj katı aranmaz." : `${formatNumber(chargeCount)} × ${formatNumber(batchSize)} = ${formatNumber(quantity)} adet`}</span></div><em className={difference > 0 ? "increase" : difference < 0 ? "decrease" : ""}>{difference === 0 ? "Değişiklik yok" : `${signedNumber(difference)} adet`}</em></div> : <p className="form-error quantity-error">{freeQuantity ? "Miktar sıfırdan büyük bir tam sayı olmalıdır." : `Miktar ${formatNumber(batchSize)} adetlik standart şarjın tam katı olmalıdır.`}</p>}
    <div className="calendar-impact-note"><strong>Sonraki işler yeniden hesaplanacak</strong><span>Bu şarjın üretim süresi, arkasındaki işlerin tarihleri ve sipariş karşılama durumu güncellenecek. İşlem geri alınabilir.</span></div>
    <div className="drawer-actions quantity-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => onSave(quantity)}>Adedi güncelle</button></div>
  </section></div>;
}

