"use client";
import { Fragment, useMemo, useState } from "react";
import { applyDailyDemandImport, buildDailyDemandOrders, type DailyDemandDataset, type DailyDemandPreview } from "@/lib/daily-demand";
import { factoryDateInput, factoryDateAfterDays } from "@/lib/factory-time";
import { formatInteger } from "@/lib/number-format";
import type { PlanningSeed } from "@/lib/planning";
import { useRaviScreenContext } from "@/features/ravi/context";
import { FileXls, Warning } from "@phosphor-icons/react";
import { HelpTip } from "@/components/ui/primitives";

const weekdays = ["Paz", "Pzt", "Sal", "Çar", "Per", "Cum", "Cmt"];
const dayOf = (date: string) => new Date(`${date}T00:00:00Z`);
const dayLabel = (date: string) => `${date.slice(8, 10)}.${date.slice(5, 7)}.${date.slice(0, 4)}`;
/** ISO week number, the KW label of the workbook. */
function isoWeek(date: string): number {
  const day = dayOf(date);
  day.setUTCDate(day.getUTCDate() + 4 - (day.getUTCDay() || 7));
  return Math.ceil(((day.getTime() - Date.UTC(day.getUTCFullYear(), 0, 1)) / 86400000 + 1) / 7);
}
function daysBetween(start: string, end: string): string[] {
  const days: string[] = [];
  for (let day = dayOf(start); day <= dayOf(end) && days.length < 400; day.setUTCDate(day.getUTCDate() + 1)) days.push(day.toISOString().slice(0, 10));
  return days;
}
const quantity = (value: number) => value ? formatInteger(value) : "–";

export function DailyDemandPanel({ preview, dataset, updateSeed, onClose }: { preview: DailyDemandPreview | null; dataset?: DailyDemandDataset; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; onClose: () => void }) {
  const source = preview ?? dataset!;
  const today = factoryDateInput();
  const [snapshotDate, setSnapshotDate] = useState(dataset?.snapshotDate ?? today);
  // A new file starts counting on the first day of its closing month; a saved file keeps its own choice.
  const [startDate, setStartDate] = useState(preview ? `${today.slice(0, 7)}-01` : dataset?.startDate ?? "");
  const [endDate, setEndDate] = useState(dataset?.endDate ?? source.dailyRows.filter(row => row.ordered > 0).map(row => row.date).sort().at(-1) ?? today);
  const [start, setStart] = useState((preview ? `${today.slice(0, 7)}-01` : dataset?.startDate) || today);
  const [displayEnd, setDisplayEnd] = useState(factoryDateAfterDays(30));
  const state = useMemo(() => {
    try { return { value: buildDailyDemandOrders({ ...source, ...(startDate ? { startDate } : {}), snapshotDate, endDate, importedAt: dataset?.importedAt ?? new Date().toISOString() }), error: "" }; }
    catch (error) { return { value: undefined, error: error instanceof Error ? error.message : "Günlük sipariş hesaplanamadı." }; }
  }, [source, startDate, snapshotDate, endDate, dataset?.importedAt]);
  const products = [...new Set(source.mappings.map(row => row.product))];
  const labels = new Map(source.mappings.map(row => [row.product, row.label.replace(/\s+/g, "")]).reverse() as Array<[string, string]>);
  const dates = start && displayEnd && start <= displayEnd ? daysBetween(start, displayEnd) : [];
  const rows = new Map(state.value?.rows.map(row => [`${row.date}:${row.product}`, row]));
  const netDemand = state.value?.orders.reduce((sum, order) => sum + order.quantity, 0) ?? 0;
  const totals = products.map(product => dates.reduce((sum, date) => {
    const row = rows.get(`${date}:${product}`);
    return [sum[0] + (row?.ordered ?? 0), sum[1] + (row?.delivered ?? 0), sum[2] + (row?.remaining ?? 0)];
  }, [0, 0, 0]));
  useRaviScreenContext("daily-orders", { preview: Boolean(preview), sourceFile: source.fileName, startDate, snapshotDate, endDate, displayStart: start, displayEnd, error: state.error, mappings: source.mappings, netDemand: state.value ? netDemand : undefined });
  return <section className="data-surface dispatch-plan orders-panel" id="ravi-daily-orders">
    <div className="surface-toolbar">
      <div><strong>Sevkiyat Planı<HelpTip align="start" text={`${startDate ? `${dayLabel(startDate)} öncesindeki sipariş ve teslimatlar hesaba katılmaz.` : "Başlangıç tarihi seçilmedi; dosyadaki tüm günler hesaba katılır."} Kesim tarihine kadar olan teslimatlar en eski siparişten başlanarak bir kez düşülür. Gösterim aralığı yalnız tabloyu daraltır.`} /></strong><span><FileXls size={12} /> {source.fileName} · {source.sheetName.trim()} sayfası</span></div>
      <span className={`dispatch-plan-state ${preview ? "preview" : "saved"}`}>{preview ? "İçe aktarma önizlemesi" : "Kayıtlı Excel"}</span>
    </div>
    <div className="dispatch-plan-controls">
      <fieldset disabled={!preview}>
        <legend>Hesap kapsamı{!preview && " · değiştirmek için dosyayı yeniden yükleyin"}</legend>
        <label className="field"><span>Sipariş başlangıcı</span><input type="date" value={startDate} max={endDate} onChange={event => setStartDate(event.target.value)} /></label>
        <label className="field"><span>Dosya kesim tarihi</span><input type="date" value={snapshotDate} onChange={event => setSnapshotDate(event.target.value)} /></label>
        <label className="field"><span>Son sipariş tarihi</span><input type="date" value={endDate} onChange={event => setEndDate(event.target.value)} /></label>
      </fieldset>
      <fieldset>
        <legend>Gösterim aralığı</legend>
        <label className="field"><span>Başlangıç</span><input type="date" value={start} onChange={event => setStart(event.target.value)} /></label>
        <label className="field"><span>Bitiş</span><input type="date" value={displayEnd} onChange={event => setDisplayEnd(event.target.value)} /></label>
      </fieldset>
    </div>
    {state.error ? <p role="alert" className="dispatch-plan-error"><Warning size={15} weight="fill" /> {state.error}</p> : <>
      <div className="dispatch-plan-metrics">
        <div><small>Sipariş</small><strong>{formatInteger(state.value!.ordered)}</strong><span>Başlangıç – son sipariş tarihi</span></div>
        <div><small>Excel teslimatı</small><strong>{formatInteger(state.value!.delivered)}</strong><span>Başlangıç – kesim tarihi</span></div>
        <div className="open"><small>Açık sipariş</small><strong>{formatInteger(netDemand)}</strong><span>{state.value!.orders.length} üründe net ihtiyaç</span></div>
      </div>
      <div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table">
        <thead>
          <tr><th rowSpan={2} className="day">Gün</th>{products.map(product => <th key={product} colSpan={3} className="product"><b>{labels.get(product)}</b><small>{product}</small></th>)}</tr>
          <tr>{products.map(product => ["Sipariş", "Teslimat", "Açık"].map((label, index) => <th key={`${product}:${label}`} className={index === 0 ? "group-start" : undefined}>{label}</th>))}</tr>
        </thead>
        <tbody>{dates.map((date, position) => {
          const weekday = dayOf(date).getUTCDay();
          const newWeek = weekday === 1 || position === 0;
          return <Fragment key={date}>
            {newWeek && <tr className="week"><th colSpan={1 + products.length * 3}>KW{isoWeek(date)}</th></tr>}
            <tr className={[weekday === 0 ? "sunday" : "", date === today ? "today" : "", date > snapshotDate ? "future" : ""].filter(Boolean).join(" ") || undefined}>
              <th className="day"><b>{dayLabel(date)}</b><small>{weekdays[weekday]}{date === today ? " · bugün" : ""}</small></th>
              {products.map(product => { const row = rows.get(`${date}:${product}`); return [row?.ordered ?? 0, row?.delivered ?? 0, row?.remaining ?? 0].map((value, index) => <td key={`${product}:${index}`} className={[index === 0 ? "group-start" : "", index === 2 && value ? "open" : "", value ? "" : "empty"].filter(Boolean).join(" ") || undefined}>{quantity(value)}</td>); })}
            </tr>
          </Fragment>;
        })}</tbody>
        <tfoot><tr><th className="day"><b>Toplam</b><small>{dates.length} gün</small></th>{totals.map((total, product) => total.map((value, index) => <td key={`${product}:${index}`} className={[index === 0 ? "group-start" : "", index === 2 && value ? "open" : ""].filter(Boolean).join(" ") || undefined}>{quantity(value)}</td>))}</tr></tfoot>
      </table></div>
    </>}
    {preview && <div className="dispatch-plan-apply">
      <details><summary>Ürün eşleşmeleri · {source.mappings.length} sütun çifti</summary><ul>{source.mappings.map(row => <li key={row.orderColumn}><code>{row.orderColumn}/{row.deliveryColumn}</code><span>{row.label}</span><b>{row.product}</b></li>)}</ul></details>
      <p>Uygula, sipariş girdilerini değiştirir. Mevcut üretim ve kayıtlı plan korunur; plan yeniden hesaplama bekler. Excel teslimatları üretim arşivine eklenmez.</p>
      <div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={Boolean(state.error)} onClick={() => { updateSeed(seed => applyDailyDemandImport(seed, { ...source, ...(startDate ? { startDate } : {}), snapshotDate, endDate, importedAt: new Date().toISOString() })); onClose(); }}>Günlük siparişleri uygula</button></div>
    </div>}
  </section>;
}

