"use client";
import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { CheckCircle, DownloadSimple, FileXls, WarningCircle, X } from "@phosphor-icons/react";
import { useApiFetch } from "@/lib/api";
import type { DeliveryReport } from "@/lib/delivery-report";
import { deliveryPlanRangeWeekCount, type DeliveryPlanRange } from "@/lib/delivery-plan";
import { useRaviScreenContext } from "@/features/ravi/context";
import { PlanningErrorNotice } from "../shared/PlanningErrorNotice";
import { formatInteger } from "@/lib/number-format";

type Snapshot = { revision: string; digest: string; calculationDate: string; calculatedAt: string; report: Extract<DeliveryReport, { payload: object }> };

export function DeliveryVerifiedExportDialog({ range, revision, synced, localReport, onChange, onClose }: {
  range: DeliveryPlanRange; revision: string; synced: boolean; localReport: DeliveryReport;
  onChange: (range: DeliveryPlanRange) => void; onClose: () => void;
}) {
  const apiFetch = useApiFetch();
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
  const [error, setError] = useState("");
  const [pending, setPending] = useState<"preview" | "download" | null>(null);
  const busy = pending !== null;
  const generation = useRef(0);
  const firstField = useRef<HTMLInputElement>(null);
  const closeButton = useRef<HTMLButtonElement>(null);
  useEffect(() => { if (pending) closeButton.current?.focus(); }, [pending]);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    firstField.current?.focus();
    return () => { if (previous?.isConnected) previous.focus(); };
  }, []);
  useEffect(() => { generation.current++; setSnapshot(null); setError(""); setPending(null); return () => { generation.current++; }; }, [range.startDate, range.endDate, revision, synced, localReport]);
  useRaviScreenContext("delivery-export", { dialog: "Teslimat planı doğrulaması", range, source: snapshot ? "verified-server" : "current-browser", revision: snapshot?.revision ?? revision, synced, complete: snapshot?.report.complete, undatedQuantity: snapshot?.report.undatedQuantity, pending, error });
  async function execute(download: boolean) {
    const current = ++generation.current;
    setPending(download ? "download" : "preview"); setError("");
    try {
      if (!synced || !revision) throw Error("Ortak kayıt tamamlanmalı ve varsa kayıt çakışması çözülmelidir.");
      if (download && !snapshot?.report.complete) throw Error("Önce teslimat önizlemesini doğrulayın.");
      deliveryPlanRangeWeekCount(range);
      const response = await apiFetch(`/delivery-plan/${download ? "export" : "preview"}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ expectedRevision: revision, ...range, ...(download && snapshot ? { digest: snapshot.digest, calculationDate: snapshot.calculationDate } : {}) }) });
      if (!response.ok) { const body = await response.json().catch(() => ({})); throw Error(typeof body.detail === "string" ? body.detail : "Teslimat raporu doğrulanamadı."); }
      if (download) {
        const blob = await response.blob();
        if (current !== generation.current) return;
        if (!blob.size || !blob.type.includes("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")) throw Error("Excel dosyası oluşturulamadı. Önizlemeyi yeniden doğrulayın.");
        const url = URL.createObjectURL(blob); const a = document.createElement("a");
        a.href = url; a.download = `Teslimat_Plani_${range.startDate}_${range.endDate}.xlsx`;
        document.body.appendChild(a); a.click(); a.remove();
        // Let the browser start consuming the download before releasing its URL.
        window.setTimeout(() => URL.revokeObjectURL(url), 60_000);
        onClose();
      } else {
        const next = await response.json() as Snapshot;
        if (current === generation.current) setSnapshot(next);
      }
    } catch (reason) {
      if (current === generation.current) { setError(reason instanceof Error ? reason.message : "Teslimat raporu doğrulanamadı."); setSnapshot(null); }
    } finally { if (current === generation.current) setPending(null); }
  }
  function handleKeys(event: KeyboardEvent<HTMLElement>) {
    if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); onClose(); }
    if (event.key !== "Tab") return;
    const controls = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("button:not(:disabled),input:not(:disabled),[tabindex='0']"));
    if (event.shiftKey && document.activeElement === controls[0]) { event.preventDefault(); controls.at(-1)?.focus(); }
    else if (!event.shiftKey && document.activeElement === controls.at(-1)) { event.preventDefault(); controls[0]?.focus(); }
  }
  return <div className="confirmation-backdrop delivery-export-backdrop"><section className="delivery-export-dialog" role="dialog" aria-modal="true" aria-labelledby="delivery-export-title" aria-describedby="delivery-export-description" onKeyDown={handleKeys}>
    <header className="delivery-export-head">
      <span className="delivery-export-icon"><FileXls size={25} /></span>
      <div><span className="delivery-export-eyebrow">TESLİMAT RAPORU</span><h2 id="delivery-export-title">Teslimat planını indir</h2><p id="delivery-export-description">Tarih aralığını seçin, ortak kayıttaki miktarları doğrulayın ve Excel’i indirin.</p></div>
      <button type="button" className="delivery-export-close" ref={closeButton} onClick={onClose} aria-label="Teslimat planı penceresini kapat"><X size={19} /></button>
    </header>
    <div className="delivery-export-body">
      <section aria-labelledby="delivery-export-range-title"><h3 id="delivery-export-range-title">Tarih aralığı</h3>
        <div className="delivery-export-range"><label>Başlangıç<input ref={firstField} type="date" disabled={busy} value={range.startDate} onChange={e => onChange({ ...range, startDate: e.target.value })} /></label><label>Bitiş<input type="date" disabled={busy} value={range.endDate} onChange={e => onChange({ ...range, endDate: e.target.value })} /></label></div>
      </section>
      {!synced && <div className="delivery-export-notice warning" role="status"><WarningCircle size={20} /><p>Ortak kayıt bekleniyor. Çakışma varsa önce güncel planı yükleyin.</p></div>}
      <section className="delivery-export-preview" aria-labelledby="delivery-export-preview-title" aria-busy={busy} aria-live="polite">
        <div className="delivery-export-section-head"><h3 id="delivery-export-preview-title">Teslimat özeti</h3>{snapshot && <span className="delivery-export-verified"><CheckCircle size={15} /> Ortak kayıt doğrulandı</span>}</div>
        {!snapshot ? <p className="delivery-export-placeholder">{pending === "preview" ? "Güncel işler ve proses bilgileri kontrol ediliyor…" : "Önizlemeyi doğruladığınızda bu aralık için sipariş, gerçekleşen ve planlanan miktarlar burada görünür."}</p> : <>
          <dl className="delivery-export-metrics">
            <div><dt>Sipariş</dt><dd>{formatInteger(snapshot.report.demand ?? 0)}<small>adet</small></dd></div>
            <div><dt>Dönem gerçekleşen</dt><dd>{formatInteger(snapshot.report.rows.reduce((n, row) => n + row.periodActual, 0))}<small>adet</small></dd></div>
            <div><dt>Dönem planı</dt><dd>{formatInteger(snapshot.report.remaining ?? 0)}<small>adet</small></dd></div>
            <div className="total"><dt>Toplam teslimat</dt><dd>{formatInteger(snapshot.report.total ?? 0)}<small>adet</small></dd></div>
          </dl>
          <p className="delivery-export-calculated">Hesaplama tarihi: {snapshot.calculationDate.split("-").reverse().join(".")} · Toplam = dönem gerçekleşen + dönem planı</p>
          {JSON.stringify(snapshot.report.payload) !== JSON.stringify(localReport.payload) && <div className="delivery-export-notice warning" role="status"><WarningCircle size={20} /><p>Ortak kayıt ile yerel önizleme farklı. Excel yukarıdaki doğrulanmış miktarları kullanır.</p></div>}
          {!snapshot.report.complete ? <div className="delivery-export-blockers" role="alert"><strong>Teslim tarihi belirlenemeyen miktar: {formatInteger(snapshot.report.undatedQuantity ?? 0)} adet</strong><p>Tam teslimat planı için aşağıdaki işlerin rota veya yerleşimini inceleyin.</p><ul>{snapshot.report.undated.map(row => <li key={row.id}><div><b>{row.workOrder || row.product}</b><span>{formatInteger(row.quantity)} adet</span></div><p>{[...new Set(row.reasons.map(reason => reason.message))].join("; ")}</p></li>)}</ul></div>
            : <div className="delivery-export-notice ready" role="status"><CheckCircle size={20} /><p>Teslimat tarihleri doğrulandı. Excel indirilmeye hazır.</p></div>}
        </>}
      </section>
      {error && <div className="delivery-export-error"><PlanningErrorNotice message={error} /></div>}
      <p className="delivery-export-note">Bu işlem üretim miktarlarını, kuyruk sırasını veya öncelikleri değiştirmez.</p>
    </div>
    <footer className="delivery-export-actions"><button type="button" className="secondary" onClick={onClose}>Kapat</button><div><button type="button" className={snapshot ? "secondary" : "primary"} disabled={busy || !synced || !revision} onClick={() => void execute(false)}>{pending === "preview" ? "Doğrulanıyor…" : "Önizlemeyi doğrula"}</button>{snapshot && <button type="button" className="primary" disabled={busy || !snapshot.report.complete || !synced} onClick={() => void execute(true)}><DownloadSimple size={17} />{pending === "download" ? "Excel hazırlanıyor…" : "Doğrulanmış Excel’i indir"}</button>}</div></footer>
  </section></div>;
}

frontend/features/planning/orders/Filter.source:
"use client";
import {useState} from 'react';
import type {PlanningSeed} from '@/lib/planning';
import {applyFilterStockReconciliation,previewFilterStockReconciliation,type FilterReviewedStock} from '@/lib/filter-stock-reconciliation';
import {useRaviScreenContext} from '@/features/ravi/context';
import {formatInteger} from '@/lib/number-format';
import {HelpTip} from '@/components/ui/primitives';
const stages=[['delivered','Teslimatı Gerçekleşen'],['visual','GKM önü'],['heat','Isıl işlem'],['milling','Freze Önü'],['grinding','Taşlama Önü']] as const;
export function FilterStockReconciliationPanel({seed,updateSeed}:{seed:PlanningSeed;updateSeed:(mutator:(draft:PlanningSeed)=>void)=>void}) {
  const source=seed.monthlyCustomerDemand!.openingStock!;
  const [blanks,setBlanks]=useState<Record<string,string>>({});
  const [confirmed,setConfirmed]=useState(false);
  const [error,setError]=useState('');
  const done=Boolean(seed.filterInitialStockSetup ?? seed.monthlyCustomerDemand?.stockReconciliation);
  const rows:FilterReviewedStock[]=source.rows.map(row=>({product:row.product,...Object.fromEntries(stages.map(([key])=>[key,blanks[`${row.product}:${key}`] !== undefined ? (blanks[`${row.product}:${key}`].trim() ? Number(blanks[`${row.product}:${key}`]) : 0) : row[key] ?? 0]))} as FilterReviewedStock));
  const preview=(()=>{try{return {value:previewFilterStockReconciliation(seed,rows),error:''};}catch(reason){return {value:undefined,error:reason instanceof Error?reason.message:'Sayımı kontrol edin.'};}})();
  useRaviScreenContext('filter-stock-reconciliation',{cutoffDate:source.cutoffDate,applied:done,confirmed,error:error||preview.error,details:preview.value?.details});
  return <section className={`data-surface dispatch-plan monthly-plan orders-panel${done?' orders-stock-done':''}`} id="ravi-filter-stock-reconciliation"><div className="surface-toolbar"><div><strong>Başlangıç stoklarını uzlaştır{done&&<HelpTip align="start" text="Bu kaynak daha önce uygulandı. Yeniden yükleme, üretim hareketlerini veya stokları geri almaz. Sonraki stok düzeltmeleri için uygulamanın normal stok ve üretim işlemlerini kullanın."/>}</strong><span>{source.cutoffDate} · SİPARİŞ ŞABLONU</span></div><span className={`dispatch-plan-state ${done?'saved':'preview'}`}>{done?'Sayım uygulandı':'Doğrulama gerekli'}</span></div>
    {!done&&<p className="dispatch-plan-note">Sayım, kayıtlı ve çalışan şarjları içerir. Kayıtlı şarjlar bir kez düşülür; yalnız kalan miktar ek stok olur. Bu ilk kurulum yalnız bir kez uygulanır. Boş hücreler 0 olur. Şarj ve üretim geçmişi değişmez. Kesin konumu olmayan ek stoka teslimat tarihi verilmez. Şarj ayrıntıları tamamlanmadan tam teslimat planı indirilemez.</p>}
    {!done&&<><div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th>Ürün</th>{stages.map(([key,label])=><th key={key}>{label} · fiziksel adet</th>)}</tr></thead><tbody>{source.rows.map(row=><tr key={row.product}><th>{row.product}</th>{stages.map(([key,label])=><td key={key}>{<input aria-label={`${row.product} ${label} sayım`} type="number" min="0" step="1" placeholder="Doğrulayın; yoksa 0" value={blanks[`${row.product}:${key}`]??String(row[key]??0)} onChange={e=>{setBlanks({...blanks,[`${row.product}:${key}`]:e.target.value});setConfirmed(false);setError('');}}/>}</td>)}</tr>)}</tbody></table></div>
    {preview.value&&<div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th>Ürün / sayım grubu</th><th>Sayım</th><th>Kayıtlı şarj</th><th>Önceki ek stok</th><th>Yeni ek stok</th><th>Beklenen sağlam adet</th></tr></thead><tbody>{preview.value.details.filter(d=>d.count||d.previous).map(d=><tr key={`${d.product}:${d.groupId}`}><th>{d.product}<small>{d.label}</small></th><td>{formatInteger(d.count)}</td><td title={d.lotIds.join(', ')}>{formatInteger(d.registered)}</td><td>{formatInteger(d.previous)}</td><td>{formatInteger(d.remainder)}</td><td>{formatInteger(d.expectedGood)}</td></tr>)}</tbody></table></div>}
    <label className="dispatch-plan-note"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> Sayım ve şarj kayıtlarını {source.cutoffDate} kesiminde uzlaştırdım. Bu sayılar çalışan şarjları içerir; ayrı fiziksel stok gruplarıdır.</label>
    {(error||preview.error)&&<p role="alert" className="dispatch-plan-error">{error||preview.error}</p>}<div className="drawer-actions"><button className="primary" disabled={!confirmed||!!preview.error} onClick={()=>{try{updateSeed(draft=>applyFilterStockReconciliation(draft,rows,confirmed));}catch(reason){setError(reason instanceof Error?reason.message:'Sayım uygulanamadı.');}}}>Sayımı uygula</button></div></>}

  </section>;
}

