"use client";
import { useState } from "react";
import { applyFilterMonthlyImport, buildFilterMonthlyOrders, recalculateFilterMonthlyRows, FILTER_MONTHLY_RULES, filterDeliveryBaselineFor, mergeFilterMonthlySourceCorrections, type FilterMonthlyDataset, type FilterMonthlyPreview } from "@/lib/filter-monthly-demand";
import { factoryDateInput } from "@/lib/factory-time";
import { formatInteger } from "@/lib/number-format";
import type { PlanningSeed } from "@/lib/planning";
import { useRaviScreenContext } from "@/features/ravi/context";
import { HelpTip } from "@/components/ui/primitives";

export function MonthlyDemandPanel({ seed, preview, dataset, updateSeed, onClose }: {
  seed: PlanningSeed; preview?: FilterMonthlyPreview | null; dataset?: FilterMonthlyDataset;
  updateSeed: (mutator: (seed: PlanningSeed) => void) => void; onClose: () => void;
}) {
  const source = preview ?? dataset!;
  const [rows,setRows] = useState(() => preview ? mergeFilterMonthlySourceCorrections(source,seed.monthlyCustomerDemand).rows : structuredClone(source.rows));
  const [reviewed,setReviewed] = useState(!preview || !seed.monthlyCustomerDemand);
  const [year,setYear] = useState(source.year);
  const updateSource = (product:string,index:number,month:number,value:string) => {
    setRows(current => current.map(row => row.product !== product ? row : {...row,inputs:row.inputs.map((item,i)=>i!==index?item:{...item,quantities:item.quantities.map((n,m)=>m===month?(value.trim()===''?NaN:Number(value)):n)})}));
    setReviewed(false); setApplyError('');
  };
  const calculatedRows = (()=>{try{return {rows:recalculateFilterMonthlyRows(rows),error:''};}catch(error){return {rows,error:error instanceof Error?error.message:'Kaynak miktarlar geçersiz.'};}})();
  const first = `${year}-01-01`, last = `${year}-12-31`;
  const today = factoryDateInput();
  const [startDate, setStartDate] = useState(preview ? today < first ? first : today > last ? last : today : dataset!.startDate);
  const [endDate, setEndDate] = useState(preview ? last : dataset!.endDate);
  const storedBaseline = filterDeliveryBaselineFor(seed,year);
  const [snapshotDate, setSnapshotDate] = useState(preview ? storedBaseline?.snapshotDate ?? source.openingStock?.cutoffDate ?? today : dataset!.snapshotDate);
  const [handovers, setHandovers] = useState<Record<string, string>>(() => Object.fromEntries((preview ? storedBaseline?.handovers ?? (seed.monthlyCustomerDemand?.year===source.year ? seed.monthlyCustomerDemand.handovers : []) : dataset!.handovers).map(row => [`${row.product}:${row.month}`, String(row.quantity)])));
  const [exceptions, setExceptions] = useState(() => (preview ? [] : dataset!.exceptions).map(row => ({ ...row, quantity: String(row.quantity) })));
  const [applyError, setApplyError] = useState("");
  const months = Array.from({ length: 12 }, (_, index) => `${year}-${String(index + 1).padStart(2, "0")}`).filter(month => month >= startDate.slice(0, 7) && month <= endDate.slice(0, 7));
  const selected = calculatedRows.rows.flatMap(row => months.map(month => ({ row, month, key: `${row.product}:${month}` })));
  const stockDelivered = (product: string, month: string) => snapshotDate === source.openingStock?.cutoffDate && month === snapshotDate.slice(0, 7) ? source.openingStock.rows.find(row => row.product === product)?.delivered : null;
  const handoverValue = (product: string, month: string) => {
    const delivered = stockDelivered(product, month);
    return handovers[`${product}:${month}`] ?? (delivered != null ? String(delivered) : "0");
  };
  const unresolved = selected.filter(({ row, month }) => row.quantities[Number(month.slice(5)) - 1] > 0 && handoverValue(row.product, month) === "");
  const input: FilterMonthlyDataset = {
    ...source, year, rows: calculatedRows.rows, originalRows: source.originalRows ?? source.rows, startDate, endDate, snapshotDate, importedAt: new Date().toISOString(),
    handovers: selected.filter(({ row, month }) => handoverValue(row.product, month) !== "").map(({ row, month }) => ({ product: row.product, month, quantity: Number(handoverValue(row.product, month)) })),
    exceptions: exceptions.map(row => ({ ...row, quantity: row.quantity === "" ? NaN : Number(row.quantity) })),
  };
  const state = (() => {
    try {
      // Missing reviewed handovers use zero only in the visible preview. Apply stays blocked.
      const display = { ...input, handovers: selected.map(({ row, month }) => ({ product: row.product, month, quantity: Number(handoverValue(row.product, month) || 0) })) };
      return { value: buildFilterMonthlyOrders(seed, display), error: "" };
    } catch (error) { return { value: undefined, error: error instanceof Error ? error.message : "Aylık ihtiyaç hesaplanamadı." }; }
  })();
  const error = calculatedRows.error || state.error || (unresolved.length ? `${unresolved.length} ürün/ay için tamamlanan teslimatı girin. Teslimat yoksa 0 girin.` : "");
  useRaviScreenContext("filter-monthly-orders", { preview: Boolean(preview), sourceFile: source.fileName, year, startDate, endDate, snapshotDate,
    unresolvedHandovers: unresolved.map(({ row, month }) => ({ product: row.product, month })), exceptions: input.exceptions,
    rows: state.value?.rows, dailyRows: state.value?.dailyRows, error: error || applyError, sourceKind: source.sourceKind, sourceInputs: rows.map(row=>({product:row.product,inputs:row.inputs})), reviewed, stockReconciliationRequired: Boolean(source.openingStock) && !seed.filterInitialStockSetup && !seed.monthlyCustomerDemand?.stockReconciliation });
  const change = () => setApplyError("");
  return <section className="data-surface dispatch-plan monthly-plan orders-panel" id="ravi-filter-monthly-orders">
    <div className="surface-toolbar"><div><strong>Aylık ihtiyaç · {year}<HelpTip align="start" text="Aylık miktar tam ayı kapsar. Kesim tarihine kadar tamamlanan depo/ambalaj devirleri bir kez düşülür. Kalan ihtiyaç, seçilen tarihler arasındaki Çubuk Filtre çalışma günlerine dağıtılır. Yarım günün ağırlığı yarımdır. Termin, depo/ambalaj devrine hazır olma tarihidir." /></strong><span>{source.fileName} · {source.sheetName}</span></div><span className={`dispatch-plan-state ${preview ? "preview" : "saved"}`}>{preview ? "İçe aktarma önizlemesi" : "Kayıtlı aylık ihtiyaç"}</span></div>
    <div className="dispatch-plan-controls"><fieldset><legend>Hesap kapsamı</legend>
      {source.sourceKind==='manual' && <label className="field"><span>Sipariş yılı</span><input aria-label="Sipariş yılı" type="number" min="2000" max="2100" value={year} onChange={e=>{const value=Number(e.target.value);setYear(value);setStartDate(`${value}-01-01`);setEndDate(`${value}-12-31`);const baseline=filterDeliveryBaselineFor(seed,value);setSnapshotDate(baseline?.snapshotDate??today);setHandovers(Object.fromEntries((baseline?.handovers??[]).map(row=>[`${row.product}:${row.month}`,String(row.quantity)])));setExceptions([]);setReviewed(false);change();}}/></label>}
      <label className="field"><span>Planlama başlangıcı</span><input type="date" min={first} max={last} value={startDate} onChange={event => { setStartDate(event.target.value); change(); }} /></label>
      <label className="field"><span>Son ihtiyaç tarihi</span><input type="date" min={first} max={last} value={endDate} onChange={event => { setEndDate(event.target.value); change(); }} /></label>
      <label className="field"><span>Teslimat kesim tarihi</span><input type="date" value={snapshotDate} max={today} readOnly={Boolean(storedBaseline)} onChange={event => { setSnapshotDate(event.target.value); change(); }} /></label>
    </fieldset></div>
    <div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th>Ürün / ay</th><th>Aylık ihtiyaç</th>{preview && seed.monthlyCustomerDemand && <th>Önceki aylık ihtiyaç</th>}<th>Tamamlanan teslimat</th><th>Kalan ihtiyaç</th></tr></thead><tbody>
      {selected.map(({ row, month, key }) => {
        const calculated = state.value?.rows.find(value => value.product === row.product && value.month === month);
        const locked = false;
        return <tr key={key}><th><b>{row.label} · {month}</b><small>{row.product}</small></th><td>{formatInteger(calculatedRows.rows.find(value=>value.product===row.product)!.quantities[Number(month.slice(5)) - 1])}</td>{preview && seed.monthlyCustomerDemand && <td>{seed.monthlyCustomerDemand.year === source.year ? formatInteger(seed.monthlyCustomerDemand.rows.find(previous => previous.product === row.product)?.quantities[Number(month.slice(5)) - 1] ?? 0) : "—"}</td>}
          <td><input aria-label={`${row.label} ${month} tamamlanan teslimat`} type="number" min="0" step="1" value={handoverValue(row.product, month)} readOnly={locked || month > snapshotDate.slice(0, 7)} placeholder="Adet girin; yoksa 0" onChange={event => { setHandovers(value => ({ ...value, [key]: event.target.value })); change(); }} />{locked && <small>Teslimatı Gerçekleşen · kaynak adedi</small>}</td>
          <td>{calculated ? formatInteger(calculated.remaining) : "—"}{calculated && calculated.delivered > calculated.ordered && <small>Teslimat aylık ihtiyacın üzerinde.</small>}</td></tr>;
      })}
    </tbody></table></div>
    <details className="order-import-calculation" open><summary>Kaynak siparişleri düzenle</summary><p className="dispatch-plan-note">Kaynak adetleri ve tamamlanan teslimatları burada düzenleyin. Gri C100-DRS, 002-DRS ve 081-DRS satırları kaynak adetlerden hesaplanır. Kaynak dosya değerleri düzeltmeler ile birlikte saklanır.</p>
      <div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th>Kaynak / ürün</th>{months.map(month=><th key={month}>{month}</th>)}</tr></thead><tbody>{rows.flatMap(row=>[...row.inputs.map((item,index)=><tr key={`${row.product}:${index}`}><th>{item.label}<small>{row.product}</small></th>{months.map(month=>{const m=Number(month.slice(5))-1; const original=(source.originalRows??source.rows).find(r=>r.product===row.product)?.inputs[index]?.quantities[m]; return <td key={month}><input aria-label={`${item.label} ${month} kaynak adet`} type="number" min="0" step="1" value={Number.isNaN(item.quantities[m])?'':item.quantities[m]} onChange={e=>updateSource(row.product,index,m,e.target.value)}/>{original!==item.quantities[m]&&<small>Kaynak: {formatInteger(original??0)} · Kullanıcı düzeltmesi</small>}</td>;})}</tr>),...(FILTER_MONTHLY_RULES.some(rule=>rule.product===row.product)?[<tr key={`${row.product}:calculated`} className="calculated-row"><th>{row.label}<small>{row.rule}</small></th>{months.map(month=><td key={month}><input aria-label={`${row.label} ${month} hesaplanan adet`} readOnly value={calculatedRows.rows.find(r=>r.product===row.product)!.quantities[Number(month.slice(5))-1]}/></td>)}</tr>]:[])])}</tbody></table></div>
    </details>
    <details className="order-import-calculation" open><summary>Tarihli ihtiyaçlar · {exceptions.length}</summary><p className="dispatch-plan-note">Tarihli miktarlar aynı ayın kalan ihtiyacından ayrılır. Ek ihtiyaç oluşturmaz. Ek ihtiyaç için kaynak sipariş adedini artırın.</p>
      {exceptions.map((row, index) => <div className="dispatch-plan-controls" key={index}><label className="field"><span>Ürün</span><select value={row.product} onChange={event => { setExceptions(value => value.map((item, position) => position === index ? { ...item, product: event.target.value } : item)); change(); }}>{source.rows.map(item => <option key={item.product} value={item.product}>{item.label}</option>)}</select></label><label className="field"><span>Tarih</span><input type="date" min={startDate} max={endDate} value={row.date} onChange={event => { setExceptions(value => value.map((item, position) => position === index ? { ...item, date: event.target.value } : item)); change(); }} /></label><label className="field"><span>Adet</span><input type="number" min="0" step="1" value={row.quantity} onChange={event => { setExceptions(value => value.map((item, position) => position === index ? { ...item, quantity: event.target.value } : item)); change(); }} /></label><button className="secondary" onClick={() => { setExceptions(value => value.filter((_, position) => position !== index)); change(); }}>Kaldır</button></div>)}
      <button className="secondary" onClick={() => { setExceptions(value => [...value, { product: source.rows[0].product, date: startDate, quantity: "" }]); change(); }}>Tarihli ihtiyaç ekle</button>
    </details>
    {source.openingStock && <details className="order-import-calculation"><summary>Başlangıç stoku kaynağı · {source.openingStock.cutoffDate}</summary><p role="note" className="dispatch-plan-note">Bu tablo ilk kurulum içindir. Boş stok hücreleri 0 olur. Sayımı uygula ekranında adetleri düzenleyin ve inceleyin. Sonraki sipariş yüklemeleri başlangıç stoklarını tekrar eklemez.</p><div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th>Ürün</th><th>Teslimatı Gerçekleşen</th><th>GKM önü</th><th>Isıl işlem</th><th>Freze Önü</th><th>Taşlama Önü</th></tr></thead><tbody>{source.openingStock.rows.map(row => <tr key={row.product}><th>{row.product}</th>{(["delivered", "visual", "heat", "milling", "grinding"] as const).map(key => <td key={key}>{row[key] === null ? "0" : formatInteger(row[key])}</td>)}</tr>)}</tbody></table></div></details>}
    {state.value && <details className="order-import-calculation"><summary>Günlük ihtiyaç dağılımı · {state.value.dailyRows.length} ürün/gün</summary><div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th>Ürün</th><th>Hazır olma tarihi</th><th>Adet</th></tr></thead><tbody>{state.value.dailyRows.map(row => <tr key={`${row.product}:${row.date}`}><th>{row.product}</th><td>{row.date}</td><td>{formatInteger(row.quantity)}</td></tr>)}</tbody></table></div></details>}
    {preview && seed.monthlyCustomerDemand && <button className="secondary" onClick={()=>{setRows(structuredClone(source.rows));setHandovers({});setReviewed(false);}}>Yeni dosyanın kaynak değerlerini kullan</button>}
    {preview && seed.monthlyCustomerDemand && <label className="dispatch-plan-note"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/> Kayıtlı kullanıcı düzeltmeleri korunur. Önceki aylık ihtiyaç ile yeni kaynak miktarlarını ve tamamlanan teslimatları inceledim. Bu sipariş değişikliğini uygula.</label>}
    {(error || applyError) && <p role="alert" className="dispatch-plan-error">{applyError || error}</p>}
    <div className="dispatch-plan-apply"><p>Uygula, sipariş girdilerini değiştirir. Mevcut üretim, kilitli plan ve tamamlanan kayıtlar korunur. Plan yeniden hesaplama bekler.</p><div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={Boolean(error) || Boolean(preview && seed.monthlyCustomerDemand && !reviewed)} onClick={() => { try { updateSeed(draft => applyFilterMonthlyImport(draft, input)); onClose(); } catch (reason) { setApplyError(reason instanceof Error ? reason.message : "Aylık ihtiyaç uygulanamadı."); } }}>Aylık ihtiyacı uygula</button></div></div>
  </section>;
}

"use client";
import type { FilterMonthlyPlan } from "@/lib/daily-demand";
import { factoryDateInput } from "@/lib/factory-time";
import { formatInteger } from "@/lib/number-format";
import type { Holiday } from "@/lib/planning";
import { useRaviScreenContext } from "@/features/ravi/context";
import { FileXls, X } from "@phosphor-icons/react";
import { HelpTip } from "@/components/ui/primitives";

const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];
const groups = [{ kind: "internal", label: "İç üretim" }, { kind: "external", label: "Dış üretim" }] as const;
const quantity = (value: number) => value ? formatInteger(value) : "–";
const days = (value: number) => value.toLocaleString("tr-TR", { maximumFractionDigits: 1 });

/** Mon–Sat days of each month that the app calendar does not close completely. */
export function calendarWorkingDays(year: number, holidays: Holiday[]): number[] {
  const closed = new Set(holidays.filter(holiday => (holiday.workingShifts ?? 0) === 0).map(holiday => Math.floor(holiday.serial)));
  return months.map((_, month) => {
    let count = 0;
    for (const day = new Date(Date.UTC(year, month, 1)); day.getUTCMonth() === month; day.setUTCDate(day.getUTCDate() + 1)) {
      if (day.getUTCDay() !== 0 && !closed.has((day.getTime() - Date.UTC(1899, 11, 30)) / 86400000)) count += 1;
    }
    return count;
  });
}

export function MonthlyPlanPanel({ plan, sourceFile, preview, holidays, onClose }: { plan: FilterMonthlyPlan; sourceFile: string; preview: boolean; holidays: Holiday[]; onClose?: () => void }) {
  const today = factoryDateInput();
  const currentMonth = Number(today.slice(0, 4)) === plan.year ? Number(today.slice(5, 7)) - 1 : -1;
  const appDays = calendarWorkingDays(plan.year, holidays);
  const sum = (kind?: "internal" | "external") => months.map((_, month) => plan.rows.filter(row => !kind || row.kind === kind).reduce((total, row) => total + row.quantities[month], 0));
  const total = sum();
  const cell = (month: number, extra = "") => [month === currentMonth ? "current" : "", extra].filter(Boolean).join(" ") || undefined;
  useRaviScreenContext("filter-monthly-plan", { preview, sourceFile, year: plan.year, workingDays: plan.workingDays, calendarWorkingDays: appDays,
    rows: plan.rows.map(row => ({ label: row.label, product: row.product, kind: row.kind, yearTotal: row.quantities.reduce((a, b) => a + b, 0) })), monthlyTotal: total });
  return <section className="data-surface dispatch-plan monthly-plan orders-panel" id="ravi-filter-monthly-plan">
    <div className="surface-toolbar">
      <div><strong>Çalışma Günleri · {plan.year}<HelpTip align="start" text="Aylık iş günleri ve aylık adetler Excel’den okunur; sipariş oluşturmaz ve planı değiştirmez. Gri satırlar iç üretim, turuncu satırlar dış üretimdir. Takvim satırı, Ayarlar’daki tatillere göre uygulamanın saydığı Pazartesi–Cumartesi günleridir; fark varsa tatilleri Ayarlar’dan güncelleyin." /></strong><span><FileXls size={12} /> {sourceFile} · {plan.sheetName} sayfası</span></div>
      <span className={`dispatch-plan-state ${preview ? "preview" : "saved"}`}>{preview ? "İçe aktarma önizlemesi" : "Kayıtlı Excel"}</span>
      {onClose && <button className="delete-button" onClick={onClose} aria-label="Çalışma Günleri penceresini kapat"><X size={16} /></button>}
    </div>
    <div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table">
      <thead><tr><th className="day">{plan.year}</th>{months.map((month, index) => <th key={month} className={cell(index)}>{month}</th>)}<th className="group-start">Yıl</th></tr></thead>
      <tbody>
        <tr><th className="day"><b>İş günü</b><small>Excel</small></th>{plan.workingDays.map((value, month) => <td key={month} className={cell(month)}>{days(value)}</td>)}<td className="group-start">{days(plan.workingDays.reduce((a, b) => a + b, 0))}</td></tr>
        <tr><th className="day"><b>İş günü</b><small>Takvim</small></th>{appDays.map((value, month) => <td key={month} className={cell(month, value !== plan.workingDays[month] ? "open" : "empty")}>{days(value)}</td>)}<td className="group-start">{days(appDays.reduce((a, b) => a + b, 0))}</td></tr>
        {groups.map(group => {
          const rows = plan.rows.filter(row => row.kind === group.kind);
          const subtotal = sum(group.kind);
          return rows.length ? [
            <tr key={group.kind} className={`week ${group.kind}`}><th colSpan={14}><i />{group.label}</th></tr>,
            ...rows.map(row => <tr key={row.sourceRow}><th className="day"><b>{row.label.replace(/\s+/g, "")}</b><small>{row.product}</small></th>{row.quantities.map((value, month) => <td key={month} className={cell(month, value ? "" : "empty")}>{quantity(value)}</td>)}<td className="group-start">{quantity(row.quantities.reduce((a, b) => a + b, 0))}</td></tr>),
            <tr key={`${group.kind}-total`} className="subtotal"><th className="day"><b>{group.label} toplamı</b></th>{subtotal.map((value, month) => <td key={month} className={cell(month)}>{quantity(value)}</td>)}<td className="group-start">{quantity(subtotal.reduce((a, b) => a + b, 0))}</td></tr>,
          ] : null;
        })}
      </tbody>
      <tfoot>
        <tr><th className="day"><b>ÇF toplam</b></th>{total.map((value, month) => <td key={month} className={cell(month)}>{quantity(value)}</td>)}<td className="group-start">{quantity(total.reduce((a, b) => a + b, 0))}</td></tr>
        <tr><th className="day"><b>Günlük adet</b><small>toplam ÷ iş günü</small></th>{total.map((value, month) => <td key={month} className={cell(month)}>{plan.workingDays[month] ? formatInteger(Math.round(value / plan.workingDays[month])) : "–"}</td>)}<td className="group-start">–</td></tr>
      </tfoot>
    </table></div>
  </section>;
}

