"use client";
import { useEffect, useMemo, useState } from "react";
import type { PlanningSeed, Product } from "@/lib/planning";
import { processLabel, type ProcessKind, type ProcessPlanningStrategy } from "@/lib/process-master-data";
import { applyFilterCatalogUpdate, previewFilterCatalogUpdate, filterProductIssues } from "@/lib/cubuk-filtre-catalog";
import { CUBUK_FILTRE_SOURCE } from "@/lib/cubuk-filtre";
import { addFilterProduct, applyFilterProductDetails, saveFilterResourceRate, type FilterProductDetails } from "@/lib/cubuk-filtre-parameters";
import { useRaviScreenContext } from "@/features/ravi/context";
import { ProductionProcessTabs } from "@/components/ProductionProcessWorkspace";
import { ProductWeights } from "@/features/planning/settings/ProductWeights";
import { Badge, Drawer, HelpTip, StatusLine } from "@/components/ui/primitives";
import { PencilSimple } from "@phosphor-icons/react";

type Props = { seed: PlanningSeed; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; canManageMaterials: boolean };
const tabs = ["Ürünler", "Prosesler", "Kaynaklar", "Operasyon Rotası"] as const;
export function FilterProductionData({ seed, updateSeed, canManageMaterials }: Props) {
  const [tab, setTab] = useState<typeof tabs[number]>("Ürünler");
  const [product, setProduct] = useState(seed.products[0]?.product ?? "");
  const [process, setProcess] = useState<ProcessKind>("turning");
  const [newCode, setNewCode] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [reviewOpen, setReviewOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<string | null>(null);
  const catalogReview = useMemo(() => previewFilterCatalogUpdate(seed), [seed]);
  const selected = seed.products.find(p => p.product === product);
  useRaviScreenContext("filter-production-data", { tab, product, process, editingProduct, catalogVersion: seed.filterCatalogVersion ?? 1, reviewOpen, catalogChanges: catalogReview.changes.length, preservedEdits: catalogReview.preserved, issues: filterProductIssues(seed, product), strategy: process === "turning" ? undefined : seed.processMasterData?.planningStrategies?.[process] ?? "earliest-ready", newCode, error, notice, source: "01_URUNLER / 02_PROSESLER / 03_KAYNAKLAR / 04_OPERASYON ROTASI" });
  function save(mutator: (seed: PlanningSeed) => void): boolean {
    try { const candidate = structuredClone(seed); mutator(candidate); updateSeed(mutator); setError(""); setNotice("Kaydedildi. Kayıtlı plan korunur; yeni tarihler için planı yeniden çalıştırın."); return true; } catch (e) { setError(e instanceof Error ? e.message : "Kayıt yapılamadı."); return false; }
  }
  const pending = (seed.filterCatalogVersion ?? 1) < 3;
  const editedProduct = seed.products.find(p => p.product === editingProduct);
  const rows = seed.processMasterData?.resources.filter(r => r.process === process) ?? [];
  return <section className="filter-production-data params-page params-filter-page" id="filter-production-data">
    <div className="params-surface">
      <div className="params-source">
        <strong>230 · Çubuk Filtre üretim verileri</strong>
        <HelpTip align="start" text="Kaynak: 230-Çubuk Filtre çalışma kitabı (2) · 15 ürün · 10 ürün için 263 rota satırı. Planlı duruş: 60 dk; Final Kontrol: 30 dk. Şarj ve rota bilgisi eksik ürünler tamamlanmadan güvenilir teslimat tarihi hesaplanamaz." />
        <span className={`dispatch-plan-state ${pending ? "preview" : "saved"}`}><Badge tone={pending ? "warn" : "neutral"}>{pending ? "Güncelleme bekliyor" : "Çalışma kitabı güncel"}</Badge></span>
        {pending ? <button className="ui-btn filter-data-review-action" aria-expanded={reviewOpen} onClick={() => setReviewOpen(!reviewOpen)}>Güncellemeyi incele</button> : <HelpTip align="end" text="Güncel çalışma kitabı işlendi. Elle düzenlenen değerler geçerliliğini korur." />}
      </div>
      {pending && reviewOpen && <div role="region" aria-label="Çubuk Filtre veri güncellemesi" className="filter-data-review params-review">
        <p>{catalogReview.changes.length} alan güncellenecek. {catalogReview.preserved.length} farklı mevcut değer korunacak. Siparişler, stok, kayıtlı plan, kilitler ve gerçek üretim korunur; plan yeniden hesaplama gerektirir.</p>
        <p>Yeni rotalar, CG-02 / ME-02 eşleşmeleri ve Freze / Göz Kontrol bitiş farkı hedefleri alınır. Manuel değişiklikler yeni Excel değerleriyle ezilmez.</p>
        {catalogReview.preserved.length > 0 && <details><summary>Korunan düzenlemeler</summary><ul>{catalogReview.preserved.map((label, i) => <li key={i}>{label}</li>)}</ul></details>}
        <button className="ui-btn primary" onClick={() => { save(applyFilterCatalogUpdate); setReviewOpen(false); }}>Verileri uygula</button>
      </div>}
      <div className="params-tabs"><div className="production-process-tabs params-section-tabs" role="tablist" aria-label="Üretim verileri">{tabs.map(t => <button key={t} role="tab" aria-selected={tab === t} className={tab === t ? "active" : ""} onClick={() => setTab(t)}>{t}</button>)}</div></div>
      {error && !editedProduct && <p role="alert" className="dispatch-plan-error params-inline-error">{error}</p>}
      {notice && <StatusLine label="Kayıt durumu" items={[{ id: "notice", tone: "ok", title: notice }]} />}
      {tab === "Ürünler" && <>
        <form className="filter-data-toolbar params-toolbar" onSubmit={e => { e.preventDefault(); save(d => addFilterProduct(d, newCode)); }}><div className="params-count"><strong>{seed.products.length} ürün</strong><HelpTip align="start" text="Sıfır şarj, planlamacının adet girmesini gerektirir. Sevkiyat Katı 0 ise kat kısıtı yoktur. Iskarta oranları müşteri siparişine veya her proseste miktara tekrar eklenmez. Satırı açıp düzenleyin." /></div><label className="params-filter"><span>Yeni tip</span><input aria-label="Yeni Çubuk Filtre ürün kodu" value={newCode} onChange={e => setNewCode(e.target.value)} placeholder="Mal Kodu" /></label><button className="ui-btn primary">Yeni tip ekle</button></form>
        <div className="table-scroll params-table-scroll"><table className="ui-table params-table"><thead><tr><th>Mal Kodu</th><th>Müşteri Ünvanı</th><th>Hedef Depo</th><th>Çap</th><th className="numeric">Şarj Büyüklüğü</th><th className="numeric">Min. Sevkiyat</th><th className="numeric">Sevkiyat Katı</th><th className="numeric">Ayar Iskartası %</th><th className="numeric">Genel Iskarta %</th><th><span className="params-sr">Düzenle</span></th></tr></thead><tbody>{seed.products.map(p => { const issues = filterProductIssues(seed, p.product); return <tr key={p.product} className="params-row" onClick={event => { if (!(event.target as HTMLElement).closest("button")) setEditingProduct(p.product); }}><td><strong>{p.product}</strong>{issues.length > 0 && <> <Badge tone="warn" title={issues.join(" · ")}>Eksik</Badge></>}</td><td>{p.customer || "—"}</td><td>{p.targetWarehouse || "—"}</td><td>{p.diameter || "—"}</td><td className="numeric">{p.batchSize ?? 0}</td><td className="numeric">{p.moq ?? 0}</td><td className="numeric">{p.shipmentMultiple ?? 0}</td><td className="numeric">{p.setupScrapPercent ?? 0}</td><td className="numeric">{p.productionScrapPercent ?? 0}</td><td className="params-edit-cell"><button type="button" className="ui-icon-btn" onClick={() => setEditingProduct(p.product)} aria-label={`${p.product} ürün bilgilerini düzenle`} title="Düzenle"><PencilSimple size={15} /></button></td></tr>; })}</tbody></table></div>
      </>}
      {tab === "Prosesler" && <>
        <div className="params-toolbar"><div className="params-count"><strong>Makine rotası</strong><HelpTip align="start" text={`Her ürün yalnız tanımlı rotasını izler. L-01 / L-02 çıkışında GTM atlanır. Çalışma kitabı güncellemesiyle Freze için 120 dk, Göz Kontrol için 180 dk önceki prosesle bitiş farkı hedeflenir; uygun parça beslemesi ve kapasite varsa işlemler örtüşebilir. Bu süreler başlangıç beklemesi değildir. Isıl İşlem 48 saat, Fosfat Kaplama 12 saat; yalnız ürün rotasında varsa uygulanır. ${seed.monthlyCustomerDemand ? "Kalite bekleme, Göz Kontrol sonrası bir çalışma günüdür. Termin ambar / ambalaj devrine hazır olma tarihidir." : "Paketleme 12 saattir."} Sabit bekleme, dinamik hedef için atlanmaz. Gerçek yarı mamül ve çalışan iş tarihleri korunur.`} /><HelpTip align="start" label="Ortak hat" text="Fosfat Kaplama, Torna Yıkama ile aynı fiziksel hattı kullanır. Yalnız bekleme süresi modellenir; ortak hattın kapasite ve çakışma çizelgesi henüz tanımlı değildir. Dinamik akış tahmini, fiilen tamamlanmamış parçaları yarı mamül stoğuna eklemez." /></div></div>
        <div className="table-scroll params-table-scroll"><table className="ui-table params-table"><thead><tr><th>Mal Kodu</th><th>Makine rotası</th><th>Tamamlanacak veriler</th></tr></thead><tbody>{seed.products.map(p => <tr key={p.product}><td>{p.product}</td><td>{seed.processMasterData?.products.find(m => m.product === p.product)?.route?.map(processLabel).join(" → ") || "Tanımlı değil"}</td><td className={filterProductIssues(seed, p.product).length ? "filter-data-missing" : "filter-data-complete"}>{filterProductIssues(seed, p.product).join(" · ") || "Rota girdileri tamam"}</td></tr>)}</tbody></table></div>
      </>}
      {(tab === "Kaynaklar" || tab === "Operasyon Rotası") && <div className="params-subtabs"><ProductionProcessTabs seed={seed} value={process} onChange={setProcess} /></div>}
      {tab === "Kaynaklar" && <>
        <div className="params-toolbar"><div className="params-count"><strong>{rows.length} kaynak</strong><HelpTip align="start" text="Kanallar ayrı planlanabilir kaynaklardır. Vardiya, bakım ve tarih ayrıntıları Tezgahlar / Ayarlar ekranlarındadır." /></div></div>
        <div className="table-scroll params-table-scroll"><table className="ui-table params-table"><thead><tr><th>Kaynak Kodu</th><th>İş Merkezi Kodu</th><th>Kaynak Açıklaması</th><th>Planlama</th><th>Vardiya</th><th>Başlangıç verisi</th></tr></thead><tbody>{rows.map(r => {
          const machine = seed.machines.find(m => m.id === r.id); const raw = CUBUK_FILTRE_SOURCE.resources.find(x => x.id === r.id);
          return <tr key={r.id}><td>{r.id}</td><td>{r.erpWorkCenterCode}</td><td>{r.name}</td><td><select aria-label={`${r.id} planlama durumu`} value={(machine?.active ?? r.active) ? "active" : "inactive"} onChange={e => save(d => { const item = d.processMasterData!.resources.find(x => x.id === r.id)!; item.active = e.target.value === "active"; const m = d.machines.find(x => x.id === r.id); if (m) m.active = item.active; })}><option value="active">Aktif</option><option value="inactive">Pasif</option></select></td><td><select aria-label={`${r.id} vardiya`} value={machine?.shiftFactor ?? r.defaultShifts} onChange={e => save(d => { const shifts = Number(e.target.value) as 0 | 1 | 2 | 3; d.processMasterData!.resources.find(x => x.id === r.id)!.defaultShifts = shifts; const m = d.machines.find(x => x.id === r.id); if (m) m.shiftFactor = shifts; })}>{[0, 1, 2, 3].map(n => <option key={n}>{n}</option>)}</select></td><td className="params-muted">{raw ? `8 saat · ${raw.breakMinutes} dk duruş · %${Math.round(raw.oee * 100)} OEE` : "Manuel"}</td></tr>;
        })}</tbody></table></div>
      </>}
      {tab === "Operasyon Rotası" && <>
        <div className="filter-data-toolbar params-toolbar"><div className="params-count"><strong>Operasyon rotası</strong><HelpTip align="start" text="Kaynak başına Adet / vardiya ve Setup / Ayar girilir. İş emri hazırlığı her şarjda uygulanır; setup yalnız ilk hazırlık veya tip değişimindedir. Hazırlık bu ürün/proses için ortak değerdir. Eksik çevrim veya setup sıfır kabul edilmez. Son beş tarihsel ürün için kaynakta rota yoktur." /></div><label className="params-filter"><span>Mal Kodu</span><select aria-label="Operasyon rotası ürünü" value={product} onChange={e => setProduct(e.target.value)}>{seed.products.map(p => <option key={p.product}>{p.product}</option>)}</select></label>{process !== "turning" && <label className="params-filter"><span>Planlama yöntemi</span><select aria-label={`${processLabel(process)} planlama yöntemi`} value={seed.processMasterData?.planningStrategies?.[process] ?? "earliest-ready"} onChange={e => save(d => { d.processMasterData!.planningStrategies = { ...d.processMasterData!.planningStrategies, [process]: e.target.value as ProcessPlanningStrategy }; })}><option value="earliest-ready">En erken hazır işi al</option><option value="campaign">Aynı tip / setup kampanyası</option></select></label>}</div>
        {filterProductIssues(seed, product).length > 0 ? <StatusLine label="Rota uyarıları" items={[{ id: "route-issues", tone: "warn", title: "Rota girdileri eksik", detail: filterProductIssues(seed, product).join(" · ") }]} /> : <p className="dispatch-plan-note params-ok-note">Rota girdileri tamam.</p>}
        <div className="table-scroll params-table-scroll"><table className="ui-table params-table params-rate-table"><thead><tr><th>Kaynak</th><th>Adet / vardiya</th><th>Setup / Ayar (dk)</th><th>İş emri hazırlığı (dk)</th><th></th></tr></thead><tbody>{selected && rows.map(r => { const parameter = seed.processMasterData?.products.find(p => p.product === product)?.processes.find(p => p.process === process); return <RateRow key={`${product}:${r.id}`} name={`${r.id} · ${r.name}`} rate={process === "turning" ? seed.machines.find(m => m.id === r.id)?.rates[product] : parameter?.unitsPerShift[r.id]} setup={process === "turning" ? selected.turningSetupMinutes?.[r.id] : parameter?.setupMinutesByResource?.[r.id]} handling={process === "turning" ? selected.handlingMinutes : parameter?.handlingMinutes} save={(rate, setup, handling) => save(d => saveFilterResourceRate(d, product, process, r.id, rate, setup, handling))} />; })}</tbody></table></div>
      </>}
    </div>
    {tab === "Ürünler" && canManageMaterials && <ProductWeights seed={seed} updateSeed={updateSeed} />}
    {editedProduct && <ProductRow key={editedProduct.product} product={editedProduct} error={error} onClose={() => { setEditingProduct(null); setError(""); }} save={details => { if (save(d => applyFilterProductDetails(d, editedProduct.product, details))) setEditingProduct(null); }} />}
  </section>;
}

const productFields = ["customer", "targetWarehouse", "diameter", "batchSize", "moq", "shipmentMultiple", "setupScrapPercent", "productionScrapPercent"] as const;
const productFieldLabels = { customer: "Müşteri Ünvanı", targetWarehouse: "Hedef Depo", diameter: "Çap", batchSize: "Şarj Büyüklüğü", moq: "Min. Sevkiyat", shipmentMultiple: "Sevkiyat Katı", setupScrapPercent: "Ayar Iskartası %", productionScrapPercent: "Genel Iskarta %" } as const;

/** Edit drawer for one Çubuk Filtre product: same fields, labels and save handler as the former table row. */
function ProductRow({ product, save, error, onClose }: { product: Product; save: (d: FilterProductDetails) => void; error: string; onClose: () => void }) {
  const [draft, setDraft] = useState<FilterProductDetails>(() => ({ diameter: product.diameter, customer: product.customer ?? "", targetWarehouse: product.targetWarehouse ?? "", batchSize: product.batchSize, moq: product.moq, shipmentMultiple: product.shipmentMultiple ?? 0, setupScrapPercent: product.setupScrapPercent ?? 0, productionScrapPercent: product.productionScrapPercent ?? 0 }));
  useEffect(() => setDraft({ diameter: product.diameter, customer: product.customer ?? "", targetWarehouse: product.targetWarehouse ?? "", batchSize: product.batchSize, moq: product.moq, shipmentMultiple: product.shipmentMultiple ?? 0, setupScrapPercent: product.setupScrapPercent ?? 0, productionScrapPercent: product.productionScrapPercent ?? 0 }), [product]);
  useRaviScreenContext(`filter-product-${product.product}`, { product: product.product, draft });
  return <Drawer className="params-drawer" width={520} title={product.product} subtitle="Çubuk Filtre ürün bilgileri" label={`${product.product} ürün bilgileri`} onClose={onClose} footer={<><button type="button" className="ui-btn" onClick={onClose}>Kapat</button><button type="button" className="ui-btn primary" onClick={() => save(draft)}>Kaydet</button></>}>
    <div className="params-form params-form-grid">{productFields.map(key => <label key={key} className="ui-field"><span>{productFieldLabels[key]}</span><input aria-label={`${product.product} ${productFieldLabels[key]}`} type={key === "customer" || key === "targetWarehouse" || key === "diameter" ? "text" : "number"} min="0" step={key.endsWith("Percent") ? "0.1" : "1"} value={draft[key] ?? ""} onChange={e => setDraft({ ...draft, [key]: key === "customer" || key === "targetWarehouse" || key === "diameter" ? e.target.value : Number(e.target.value) })} /></label>)}</div>
    {error && <p className="params-feedback error" role="alert">{error}</p>}
  </Drawer>;
}
function RateRow({ name, rate, setup, handling, save }: { name: string; rate?: number; setup?: number; handling?: number; save: (rate: number, setup: number, handling: number) => void }) {
  const [values, setValues] = useState([rate ? String(rate) : "", setup === undefined ? "" : String(setup), handling === undefined ? "" : String(handling)]);
  useEffect(() => setValues([rate ? String(rate) : "", setup === undefined ? "" : String(setup), handling === undefined ? "" : String(handling)]), [rate, setup, handling]);
  useRaviScreenContext(`filter-rate-${name}`, { resource: name, unitsPerShift: values[0], setupMinutes: values[1], handlingMinutes: values[2] });
  return <tr><td>{name}</td>{values.map((v, i) => <td key={i}><input type="number" min="0" step="any" aria-label={`${name} ${["Adet / vardiya", "Setup / Ayar", "İş emri hazırlığı"][i]}`} placeholder="Eksik" value={v} onChange={e => setValues(values.map((x, j) => j === i ? e.target.value : x))} /></td>)}<td><button className="ui-btn" disabled={values.some(v => !v.trim())} onClick={() => save(Number(values[0]), Number(values[1]), Number(values[2]))}>Kaydet</button></td></tr>;
}

frontend/features/planning/parameters/Fl.source:
"use client";

import { factoryNowSerial } from "@/lib/factory-time";
import { useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { adoptEightHourWashing, effectiveWaitSources, legacyWashingRules, defaultFlowSettings, validateFlowSettings, type FlowRule, type FlowSettings, type FlowSetup } from "@/lib/flow-settings";
import { buildDownstreamProcessPlan } from "@/lib/process-planning";
import { formatExcelDate, getSetupSettings, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { processLabel, type ProcessKind } from "@/lib/process-master-data";
import { flowActivationStatus } from "./flow-activation-status";
import { inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";

export type FlowSettingsSection = "Vardiya ve Mesai Bilgileri" | "Akış Ayarı" | "SETUP Süreleri";
const steps = ["turning", "drilling", "deburring", "gkm", "delivery"] as const;
const label = (step: string) => step === "delivery" ? "Teslimata hazır" : processLabel(step as ProcessKind);
const setupLabels: Record<keyof FlowSetup, string> = { first: "İlk hazırlık", sameProduct: "Aynı ürün", sameKey: "Aynı setup anahtarı", differentKey: "Farklı setup anahtarı", differentFamily: "Farklı ürün ailesi" };

export function FlowSettingsPanel({ seed, result, updateSeed, canEdit, section = "Akış Ayarı", active = true }: { section?: FlowSettingsSection; active?: boolean; seed: PlanningSeed; result: ScenarioResult; updateSeed: (mutator: (seed: PlanningSeed) => void) => void | boolean; canEdit: boolean }) {
  const [draft, setDraft] = useState<FlowSettings>(() => structuredClone(seed.flowSettings ?? defaultFlowSettings()));
  const [turning, setTurning] = useState(() => getSetupSettings(seed));
  const savedSettings = JSON.stringify({ flowSettings: seed.flowSettings ?? defaultFlowSettings(), setupSettings: getSetupSettings(seed) });
  const [baseline, setBaseline] = useState(savedSettings);
  const [reloadRequested, setReloadRequested] = useState(false);
  const [preview, setPreview] = useState<{ source: string; changedSections: string[]; changed: Array<{ product: string; before: number; after: number }>; warnings: string[] } | null>(null);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const stale = baseline !== savedSettings;
  const savedFlow = seed.flowSettings ?? defaultFlowSettings();
  const flowChanged = JSON.stringify(draft) !== JSON.stringify(savedFlow);
  const turningChanged = JSON.stringify(turning) !== JSON.stringify(getSetupSettings(seed));
  const draftChanged = flowChanged || turningChanged;
  const previewStale = !!preview && preview.source !== JSON.stringify(seed);
  function reload() {
    setDraft(structuredClone(seed.flowSettings ?? defaultFlowSettings())); setTurning(getSetupSettings(seed)); setBaseline(savedSettings); setPreview(null); setError(""); setNotice(""); setReloadRequested(false);
  }
  const savedLegacyWashing = legacyWashingRules(seed.flowSettings);
  const draftLegacyWashing = legacyWashingRules(draft);
  const savedActivation = flowActivationStatus(seed);
  useRaviScreenContext("flow-settings", { savedActivation, effectiveWaitSources: effectiveWaitSources(seed), draftEffectiveWaitSources: effectiveWaitSources({ ...seed, flowSettings: draft }), hasLegacyWashing: savedLegacyWashing.length > 0, draftHasLegacyWashing: draftLegacyWashing.length > 0, section, department: "Piston / Center Pin", enabled: seed.flowSettings?.enabled ?? false, draft, draftTurningSetup: turning, stale, previewStale, draftChanged, reloadRequested, preview, readOnly: !canEdit, physicalTransferEnabled: false }, active);
  function change(next: FlowSettings) { setDraft(next); setPreview(null); setNotice(""); setError(""); }
  function adoptWashing() {
    try {
      if (stale) throw new Error("Ortak veri değişti. Güncel ayarları yükleyip taslağı yeniden inceleyin.");
      change(adoptEightHourWashing(draft).settings);
      setNotice("8 çalışma saati taslağa alındı. Değişiklikleri inceleyin ve Ayarları kaydet ile onaylayın.");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Yıkama süresi taslağa alınamadı."); }
  }
  function ruleChange(index: number, patch: Partial<FlowRule>) { change({ ...draft, rules: draft.rules.map((rule, position) => position === index ? { ...rule, ...patch } : rule) }); }
  function review() {
    try {
      if (stale) throw new Error("Ortak veri değişti. Güncel ayarları yükleyip taslağı yeniden inceleyin.");
      if (!Number.isFinite(turning.shiftHours) || turning.shiftHours < 1 || turning.shiftHours > 24 || Object.values(turning).some(value => typeof value === "number" && (!Number.isFinite(value) || value < 0 || value > 168))) throw new Error("Setup süreleri 0–168 saat, vardiya süresi 1–24 saat arasında olmalı.");
      const settings = validateFlowSettings(draft);
      const before = buildDownstreamProcessPlan(seed, result);
      const after = buildDownstreamProcessPlan({ ...seed, flowSettings: settings, setupSettings: turning }, result);
      const changedSections = [
        JSON.stringify({ enabled: draft.enabled, rules: draft.rules }) !== JSON.stringify({ enabled: savedFlow.enabled, rules: savedFlow.rules }) ? "Akış ve bekleme" : "",
        draft.defaultShifts !== savedFlow.defaultShifts || JSON.stringify(draft.shiftOverrides) !== JSON.stringify(savedFlow.shiftOverrides) ? "Bölüm vardiyaları" : "",
        turningChanged || JSON.stringify(draft.setupMinutes) !== JSON.stringify(savedFlow.setupMinutes) ? "Setup süreleri" : "",
      ].filter(Boolean);
      setPreview({ source: JSON.stringify(seed), changedSections, changed: after.jobs.flatMap(job => { const previous = before.jobs.find(item => item.batchId === job.batchId); return previous && Math.abs(previous.deliveryReadyAt - job.deliveryReadyAt) > 1e-7 ? [{ product: job.product, before: previous.deliveryReadyAt, after: job.deliveryReadyAt }] : []; }), warnings: [...new Set(after.warnings.map(item => item.message))] });
      setError("");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Ayarlar incelenemedi."); }
  }
  function save() {
    try {
      if (!canEdit || !preview || stale || previewStale) throw new Error("Güncel taslağı önce inceleyin.");
      if (!Number.isFinite(turning.shiftHours) || turning.shiftHours < 1 || turning.shiftHours > 24 || Object.values(turning).some(value => typeof value === "number" && (!Number.isFinite(value) || value < 0 || value > 168))) throw new Error("Setup süreleri 0–168 saat, vardiya süresi 1–24 saat arasında olmalı.");
      const settings = validateFlowSettings(draft);
      if (!draftChanged) { setPreview(null); setNotice("Kaydedilecek değişiklik yok. Kayıtlı ayarlar korundu."); return; }
      if (updateSeed(next => { if (flowChanged) next.flowSettings = settings; if (turningChanged) next.setupSettings = turning; }) === false) throw new Error("Ayar değişikliği uygulanmadı. Üst çubuktaki uyarıyı kontrol edin.");
      setBaseline(JSON.stringify({ flowSettings: settings, setupSettings: turning })); setDraft(structuredClone(settings));
      setPreview(null); setNotice("Kaydetme isteği gönderildi. Ortak kayıt durumunu üst çubuktan kontrol edin. Mevcut plan korunur; güncel tarihler için planı yeniden çalıştırın.");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Ayarlar kaydedilemedi."); }
  }
  return <section className="data-surface flow-settings-panel">
    <div className="surface-toolbar settings-panel-heading"><div><span className="settings-eyebrow">PİSTON · CENTER PIN</span><h2>{section === "SETUP Süreleri" ? "Setup süreleri" : section === "Vardiya ve Mesai Bilgileri" ? "Bölüm vardiyaları" : "Akış ve bekleme"}</h2><p>{section === "SETUP Süreleri" ? "Torna ve sonraki proseslerin hazırlık sürelerini tek yerden yönetin." : section === "Vardiya ve Mesai Bilgileri" ? "Yıkama ve paketleme beklemelerinde kullanılan çalışma takvimi." : "Proses geçişlerini, bekleme sürelerini ve geçerli kuralları yönetin."}</p></div><button className="secondary" onClick={() => { if (draftChanged) setReloadRequested(true); else reload(); }}>Güncel ayarları yükle</button></div>
    {reloadRequested && <div className="settings-message" role="alert"><strong>Kaydedilmemiş değişiklikler silinecek.</strong><p>Akış, bölüm vardiyaları ve setup taslağı kayıtlı değerlerle değiştirilecek.</p><div className="drawer-actions"><button onClick={() => setReloadRequested(false)}>Vazgeç</button><button onClick={reload}>Taslağı sil ve yükle</button></div></div>}
    {!canEdit && <p className="settings-help">Ayarları görüntüleyebilirsiniz. Ortak ayarları yalnızca yönetici değiştirebilir.</p>}
      <fieldset disabled={!canEdit} className="flow-settings-fields">
        {section === "Akış Ayarı" && <>
          <div className="flow-activation-status" role="status" aria-label="Kayıtlı akış durumu">
            <strong>{savedActivation.label}</strong>
            <span>{savedActivation.savedRuleCount} geçiş kayıtlı saat kurallarını kullanıyor.</span>
            <span>Taslak saat bazlı akış: {draft.enabled ? "Açık" : "Kapalı"}. Tablodaki taslak değerler, Değişiklikleri incele ve Ayarları kaydet tamamlanmadan ortak kuralları değiştirmez.</span>
          </div>
          <details className="settings-disclosure"><summary>Kayıtlı geçerli bekleme kuralları</summary><div className="table-scroll"><table><thead><tr><th>Aile</th><th>Geçiş</th><th>Kaynak</th><th>Süre</th></tr></thead><tbody>{savedActivation.rows.map(row => <tr key={`${row.family}:${row.from}:${row.to}`}><td>{row.family === "piston" ? "Piston" : "Center Pin"}</td><td>{label(row.from)} → {label(row.to)}</td><td>{row.source}</td><td>{row.label}</td></tr>)}</tbody></table></div></details>
          <label className="settings-toggle"><input type="checkbox" checked={draft.enabled} onChange={event => change({ ...draft, enabled: event.target.checked })} /> Saat bazlı akış planlamasını etkinleştir</label>
          <p>Dinamik süre iki prosesin bitiş farkı hedefidir (takvim saati). Statik süre bölümün çalışma saatlerinde ilerler. Kuralı olmayan veya pasif geçişlerde eski iş günü hesabı sürer. Hedef için fiziksel stok oluşturulmaz; gerçek aktarım bu sürümde mevcut tamamlama kayıtlarıyla devam eder.</p>
          {savedLegacyWashing.length > 0 && <div role="status"><p>Kayıtlı yıkama beklemesi 12 çalışma saati. Onaylanan yeni değer 8 çalışma saati.</p><button disabled={stale || draftLegacyWashing.length === 0} onClick={adoptWashing}>8 çalışma saatini uygula</button></div>}
          <div className="table-scroll"><table><thead><tr><th>Ürün grubu</th><th>Önceki proses</th><th>Sonraki proses</th><th>Hesap</th><th>Süre (saat)</th><th>Açıklama</th><th>Aktif</th><th>İşlem</th></tr></thead><tbody>{draft.rules.map((rule, index) => <tr key={rule.id}>
            <td><select aria-label={`Kural ${index + 1} ürün grubu`} value={rule.family} onChange={event => ruleChange(index, { family: event.target.value as FlowRule["family"] })}><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></td>
            <td><select aria-label={`Kural ${index + 1} önceki proses`} value={rule.from} onChange={event => ruleChange(index, { from: event.target.value as ProcessKind })}>{steps.filter(step => step !== "delivery").map(step => <option key={step} value={step}>{label(step)}</option>)}</select></td>
            <td><select aria-label={`Kural ${index + 1} sonraki proses`} value={rule.to} onChange={event => ruleChange(index, { to: event.target.value as FlowRule["to"] })}>{steps.filter(step => step !== "turning").map(step => <option key={step} value={step}>{label(step)}</option>)}</select></td>
            <td><select aria-label={`Kural ${index + 1} hesap`} value={rule.mode} onChange={event => ruleChange(index, { mode: event.target.value as FlowRule["mode"] })}><option value="dynamic">Dinamik</option><option value="static">Statik</option></select></td>
            <td><input aria-label={`Kural ${index + 1} ${rule.mode === "static" ? "çalışma saati" : "bitiş farkı hedefi (saat)"}`} type="number" min="0" max="168" step="0.5" value={rule.minutes / 60} onChange={event => ruleChange(index, { minutes: event.target.value === "" ? NaN : Number(event.target.value) * 60 })} /><small>{rule.mode === "static" ? "çalışma saati" : "bitiş farkı hedefi (saat)"}</small></td>
            <td><input aria-label={`Kural ${index + 1} açıklama`} value={rule.description} onChange={event => ruleChange(index, { description: event.target.value })} /></td>
            <td><input aria-label={`Kural ${index + 1} aktif`} type="checkbox" checked={rule.active} onChange={event => ruleChange(index, { active: event.target.checked })} /></td>
            <td><button onClick={() => change({ ...draft, rules: draft.rules.filter((_, position) => position !== index) })}>Sil</button></td>
          </tr>)}</tbody></table></div>
          <div className="drawer-actions"><button onClick={() => change({ ...draft, rules: [...draft.rules, { id: crypto.randomUUID(), family: "piston", from: "turning", to: "drilling", mode: "dynamic", minutes: 120, active: false, description: "" }] })}>Kural ekle</button><button onClick={() => change({ ...draft, rules: defaultFlowSettings().rules })}>Varsayılan kuralları yükle</button></div>
        </>}
        {section === "Vardiya ve Mesai Bilgileri" && <>
          <p>Yıkama/Fosfat ve Paketleme/Final Kontrol beklemeleri bu bölüm takvimini kullanır. Bir vardiya {turning.shiftHours} saattir; mevcut takvim modelinde çalışma penceresi 00:00’da başlar. Pazar ve kapalı resmi tatiller atlanır; aşağıdaki tarih istisnası mesai açabilir. Makine bakımı bölüm beklemesini kapatmaz.</p>
          <label className="settings-field">Normal gün vardiyası <select aria-label="Bölüm normal gün vardiyası" value={draft.defaultShifts} onChange={event => change({ ...draft, defaultShifts: Number(event.target.value) })}>{[0,1,2,3].map(value => <option key={value}>{value}</option>)}</select></label>
          {draft.shiftOverrides.map((item, index) => <div className="flow-calendar-row" key={index}><input aria-label={`Mesai ${index + 1} tarihi`} type="date" value={serialToInputDate(item.date)} onChange={event => change({ ...draft, shiftOverrides: draft.shiftOverrides.map((row, i) => i === index ? { ...row, date: inputDateToSerial(event.target.value) } : row) })} /><select aria-label={`Mesai ${index + 1} vardiya`} value={item.shifts} onChange={event => change({ ...draft, shiftOverrides: draft.shiftOverrides.map((row, i) => i === index ? { ...row, shifts: Number(event.target.value) } : row) })}>{[0,1,2,3].map(value => <option key={value}>{value}</option>)}</select><button onClick={() => change({ ...draft, shiftOverrides: draft.shiftOverrides.filter((_, i) => i !== index) })}>Sil</button></div>)}
          <button onClick={() => change({ ...draft, shiftOverrides: [...draft.shiftOverrides, { date: Math.floor(factoryNowSerial()), shifts: draft.defaultShifts }] })}>Tarih istisnası ekle</button>
        </>}
        {section === "SETUP Süreleri" && <>
          <p>Süreler saat cinsindedir. Torna mevcut ortak ayarları kullanır; diğer prosesler saat bazlı akış etkinleştirildiğinde bu tabloyu kullanır.</p>
          <div className="flow-setup-grid"><label>Vardiya süresi<input aria-label="Vardiya süresi" type="number" min="1" max="24" step="0.5" value={Number.isNaN(turning.shiftHours) ? "" : turning.shiftHours} onChange={event => { setTurning({ ...turning, shiftHours: event.target.value === "" ? NaN : Number(event.target.value) }); setPreview(null); setNotice(""); }} /><small>saat / vardiya</small></label>{([['sameDiameterHours','Torna · Aynı çap'],['differentDiameterHours','Torna · Farklı çap (eski model)'],['sameFamilyDifferentDiameterHours','Torna · Aynı aile, farklı çap'],['crossFamilyHours','Torna · Farklı aile']] as const).map(([key, title]) => <label key={key}>{title}<input type="number" min="0" max="168" step="0.5" aria-label={title} value={Number.isNaN(turning[key]) ? "" : turning[key]} onChange={event => { setTurning({ ...turning, [key]: event.target.value === "" ? NaN : Number(event.target.value) }); setPreview(null); setNotice(""); }} /></label>)}</div>
          <div className="table-scroll"><table><thead><tr><th>Proses</th>{Object.values(setupLabels).map(title => <th key={title}>{title}</th>)}</tr></thead><tbody>{(["drilling", "deburring", "gkm"] as const).map(process => <tr key={process}><th>{processLabel(process)}</th>{(Object.keys(setupLabels) as Array<keyof FlowSetup>).map(key => <td key={key}><input aria-label={`${processLabel(process)} ${setupLabels[key]}`} type="number" min="0" max="168" step="0.5" value={Number.isNaN(draft.setupMinutes[process][key]) ? "" : draft.setupMinutes[process][key] / 60} onChange={event => change({ ...draft, setupMinutes: { ...draft.setupMinutes, [process]: { ...draft.setupMinutes[process], [key]: event.target.value === "" ? NaN : Number(event.target.value) * 60 } } })} /></td>)}</tr>)}</tbody></table></div>
        </>}
      </fieldset>
      {section === "Vardiya ve Mesai Bilgileri" && <details><summary>Makine vardiyaları, bakımlar ve resmi tatiller (mevcut kayıtlar)</summary><p>Bu kayıtlar makine üretim takvimini gösterir; düzenleme mevcut Tezgahlar / Ayarlar ekranlarından yapılır.</p><ul>{seed.processMasterData?.resources.map(resource => <li key={resource.id}>{resource.name}: {resource.defaultShifts} vardiya</li>)}{seed.holidays.map(day => <li key={day.serial}>{formatExcelDate(day.serial)} · {day.name} · {day.workingShifts ?? 0} vardiya</li>)}{seed.calendarEvents?.map(event => <li key={event.id}>{event.machineId} · {event.name} · {formatExcelDate(event.start)} – {formatExcelDate(event.end)}</li>)}</ul></details>}
      {previewStale && !stale && <p className="settings-message" role="status">Plan girdileri değişti. Taslağınız korunuyor; kaydetmeden önce değişiklikleri yeniden inceleyin.</p>}
      {stale && !notice && <p role="status">Ortak veri değişti; taslağı kaydetmeden önce güncel ayarları yükleyin.</p>}
      {error && <p className="settings-message error" role="alert">{error}</p>}{notice && <p className="settings-message" role="status">{notice}</p>}
      {canEdit && <div className="drawer-actions settings-save-actions"><button className="secondary" disabled={stale} onClick={review}>Değişiklikleri incele</button><button className="primary" disabled={!preview || stale || previewStale} onClick={save}>Ayarları kaydet</button></div>}
      {preview && <div className="flow-review" role="status"><strong>Bu kayıtta değişecek bölümler</strong><p>{preview.changedSections.length ? preview.changedSections.join(" · ") : "Değişiklik yok"}</p><h3>{preview.changed.length} şarjın tahmini teslim tarihi değişiyor</h3><p>Kaydetmek kayıtlı kuyruğu veya gerçekleşen üretimi değiştirmez. Planı yeniden çalıştırmanız gerekir.</p>{preview.changed.slice(0, 20).map((item, index) => <p key={index}>{item.product}: {item.before > 0 ? formatExcelDate(item.before, { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) : "Hesaplanamadı"} → {item.after > 0 ? formatExcelDate(item.after, { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) : "Hesaplanamadı"}</p>)}{preview.warnings.slice(0, 20).map((warning, index) => <p key={index}>{warning}</p>)}</div>}
  </section>;
}

frontend/features/planning/parameters/Ne.source:
"use client";

import { useEffect, useRef, useState } from "react";
import { CaretDown, CaretUp, Plus, Warning, X } from "@phosphor-icons/react";
import { Field } from "@/features/planning/shared/controls";
import { useRaviScreenContext } from "@/features/ravi/context";
import { ProcessIcon } from "@/components/ProcessIcon";
import type { PlanningSeed } from "@/lib/planning";
import { initialNewTypeWizardDraft, NEW_TYPE_STEPS, newTypeRouteLabel, validateNewTypeWizard, type NewTypeWizardDraft } from "@/lib/new-product-type";
import { PRODUCT_PROCESS_ORDER, processLabel, resourceSupportsProcessProduct, type DownstreamProcess } from "@/lib/process-master-data";
import type { ProductSetupFamily } from "@/lib/setup-families";

export function NewProductTypeDialog({ seed, onClose, onSave, canManageMaterials }: { seed: PlanningSeed; onClose: () => void; onSave: (draft: NewTypeWizardDraft) => void; canManageMaterials: boolean }) {
  const [draft, setDraft] = useState(initialNewTypeWizardDraft);
  const [step, setStep] = useState(0);
  const [attempted, setAttempted] = useState(false);
  const [saveError, setSaveError] = useState("");
  const dialogRef = useRef<HTMLElement>(null);
  const validation = validateNewTypeWizard(seed, draft);
  const process = PRODUCT_PROCESS_ORDER[step];
  const downstream = process && process !== "turning" ? draft.processes[process] : undefined;
  const active = step === 0 ? draft.turningEnabled : downstream?.active;
  const errors = saveError ? [saveError] : attempted ? validation.errorsByStep[step] : [];
  useRaviScreenContext("new-product-type", { dialog: "Yeni tip tanımla", step: step + 1, stepLabel: NEW_TYPE_STEPS[step],
    product: draft.product, setupFamily: draft.setupFamily, activeRoute: validation.route, draft, errors, canManageMaterials, productionRateUnit: "adet/vardiya", saved: false });

  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    dialogRef.current?.querySelector<HTMLElement>("input")?.focus();
    const key = (event: KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); onClose(); }
      if (event.key !== "Tab") return;
      const controls = [...(dialogRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), [tabindex="0"]') ?? [])].filter(item => item.getClientRects().length);
      const first = controls[0], last = controls.at(-1);
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
    };
    document.addEventListener("keydown", key);
    return () => { document.removeEventListener("keydown", key); previous?.focus(); };
  }, [onClose]);

  function change(patch: Partial<NewTypeWizardDraft>) { setDraft(current => ({ ...current, ...patch })); setSaveError(""); }
  function changeProcess(patch: Partial<NewTypeWizardDraft["processes"][DownstreamProcess]>) {
    if (!process || process === "turning") return;
    change({ processes: { ...draft.processes, [process]: { ...draft.processes[process], ...patch } } });
  }
  const ids = step === 0 ? draft.machines : downstream?.resources ?? [];
  const rates = step === 0 ? draft.machineShiftRates : downstream?.unitsPerShift ?? {};
  const resources = step === 0 ? seed.machines.filter(item => item.active)
    : (seed.processMasterData?.resources ?? []).filter(item => item.process === process && item.active && item.defaultShifts > 0
      && resourceSupportsProcessProduct(item, { family: draft.setupFamily || "piston" }));
  function setResources(next: string[], nextRates = rates) {
    if (step === 0) change({ machines: next, machineShiftRates: nextRates });
    else changeProcess({ resources: next, unitsPerShift: nextRates });
  }
  function move(index: number, direction: -1 | 1) {
    const next = [...ids]; [next[index], next[index + direction]] = [next[index + direction], next[index]]; setResources(next);
  }
  function go(next: number) { setStep(next); setAttempted(false); setSaveError(""); }
  function advance() {
    setAttempted(true);
    if (validation.errorsByStep[step].length) return;
    if (step < 4) { go(step + 1); return; }
    const firstInvalid = validation.errorsByStep.findIndex(items => items.length);
    if (firstInvalid >= 0) { setStep(firstInvalid); return; }
    if (!canManageMaterials) { setSaveError("Hammadde bilgilerini kaydetmek için yönetici yetkisi gerekir."); return; }
    try { onSave(structuredClone(draft)); } catch (reason) { setSaveError(reason instanceof Error ? reason.message : "Tip kaydedilemedi."); }
  }
  return <div className="confirmation-backdrop" role="presentation"><section ref={dialogRef} className="operational-dialog new-product-dialog new-type-wizard" role="dialog" aria-modal="true" aria-labelledby="new-type-title">
    <div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>ÜRÜN ANA VERİSİ · {step + 1} / 5</span><h2 id="new-type-title">Yeni tip tanımla</h2><p>Prosesleri sırayla tanımlayın. Bu tipte kullanılmayacak prosesleri Pasif seçin.</p></div><button className="delete-button" onClick={onClose} aria-label="Yeni tip penceresini kapat"><X size={16} /></button></div>
    <ol className="new-type-steps" aria-label="Yeni tip adımları">{NEW_TYPE_STEPS.map((label, index) => <li key={label} aria-current={step === index ? "step" : undefined}><span>{index + 1}</span><strong>{label}</strong>{index < 4 && <small>{(index === 0 ? draft.turningEnabled : draft.processes[PRODUCT_PROCESS_ORDER[index] as DownstreamProcess].active) ? "Aktif" : "Pasif"}</small>}</li>)}</ol>
    <div className="operational-dialog-form">
      {!canManageMaterials && <p className="new-type-passive-note" role="status">Hammadde bilgilerini içeren bu tanımı kaydetmek için yönetici yetkisi gerekir. Siparişler → Yeni tip ile parametre bekleyen sipariş tipi ekleyebilirsiniz.</p>}
      <h3 className="new-type-step-heading" tabIndex={-1}>{process && <ProcessIcon process={process} size={20} />} {NEW_TYPE_STEPS[step]}</h3>
      {step === 0 && <div className="new-product-basics">
        <Field label="Tip numarası"><input aria-label="Tip numarası" maxLength={48} value={draft.product} onChange={event => change({ product: event.target.value.toUpperCase() })} placeholder="Örn. R902745180" /></Field>
        <Field label="Ürün ailesi"><select aria-label="Ürün ailesi" value={draft.setupFamily} onChange={event => change({ setupFamily: event.target.value as ProductSetupFamily | "" })}><option value="">Aile seçin</option><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></Field>
        <Field label="Standart şarj büyüklüğü"><input aria-label="Standart şarj büyüklüğü" type="number" min="1" step="1" value={draft.batchSize} onChange={event => change({ batchSize: event.target.value })} placeholder="Adet / şarj" /></Field>
      </div>}
      {step < 4 && <>
        <fieldset className="new-type-activation"><legend>{processLabel(process)} durumu</legend>{[true, false].map(value => <label key={String(value)} className={active === value ? "selected" : ""}><input type="radio" name={`${process}-active`} value={String(value)} checked={active === value} onChange={() => step === 0 ? change({ turningEnabled: value }) : changeProcess({ active: value })} />{value ? "Aktif" : "Pasif"}</label>)}</fieldset>
        {!active ? <p className="new-type-passive-note">{processLabel(process)} bu tipin üretim rotasında atlanır; kapasite bilgisi gerekmez. {step === 0 && "Yeni Torna şarjı planlanmaz. Sonraki prosesler kayıtlı yarı mamul üzerinden ilerler."}</p> : <>
          {downstream && <div className="new-product-basics"><Field label={process === "drilling" ? "Matkap çapı / setup anahtarı" : "Setup anahtarı"}><input aria-label={process === "drilling" ? "Matkap çapı / setup anahtarı" : "Setup anahtarı"} value={downstream.setupKey} onChange={event => changeProcess({ setupKey: event.target.value })} placeholder={process === "drilling" ? "Örn. Ø 6" : "Örn. ürün tipi"} /></Field><p>Bekleme süreleri Ayarlar → Akış ve bekleme üzerinden yönetilir.</p></div>}
          <div className="new-product-machine-section"><div><span>{step === 0 ? "TEZGAH ÖNCELİĞİ VE HIZ" : "İŞ MERKEZİ ÖNCELİĞİ VE HIZ"}</span><small>{step === 0 ? "Üretim hızını bir vardiyadaki adet olarak girin. İlk tezgah ana tercihtir." : "Her iş merkezi için bir vardiyadaki üretim adedini girin. İlk merkez ana tercihtir."}</small></div>
            <div className="new-product-machine-list">{ids.map((id, index) => <article key={id}><span className="new-product-rank">{index + 1}</span><div><strong>{id}</strong><small>{resources.find(item => item.id === id)?.name ?? "Uygunluğu kontrol edin"}</small></div><label><span>{step === 0 ? "Adet / vardiya" : "Adet / vardiya"}</span><input aria-label={`${id} ${step === 0 ? "Adet / vardiya" : "Adet / vardiya"}`} type="number" min={step === 0 ? "0" : "1"} step={step === 0 ? "any" : "1"} value={rates[id] ?? ""} onChange={event => setResources(ids, { ...rates, [id]: event.target.value })} /></label><div className="new-product-machine-actions"><button disabled={index === 0} onClick={() => move(index, -1)} aria-label={`${id} önceliğini yükselt`}><CaretUp size={12} /></button><button disabled={index === ids.length - 1} onClick={() => move(index, 1)} aria-label={`${id} önceliğini düşür`}><CaretDown size={12} /></button><button className="remove" onClick={() => setResources(ids.filter(item => item !== id))} aria-label={`${id} seçimini kaldır`}><X size={12} /></button></div></article>)}</div>
            {!ids.length && <div className="new-product-empty"><strong>{step === 0 ? "Henüz tezgah seçilmedi" : "Henüz iş merkezi seçilmedi"}</strong><span>Aşağıdaki uygun kaynaklardan seçim yapın.</span></div>}
            <div className="new-product-machine-picker">{resources.filter(item => !ids.includes(item.id)).map(item => <button key={item.id} onClick={() => setResources([...ids, item.id])}><Plus size={11} />{item.id}<small>{item.name}</small></button>)}</div>
            {!resources.length && <p role="status">Bu proses ve ürün ailesi için uygun aktif kaynak bulunamadı. İş merkezi ayarlarını kontrol edin.</p>}
          </div>
        </>}
      </>}
      {step === 4 && <>
        <div className="new-product-basics">
          <Field label="Hammadde çapı"><input aria-label="Hammadde çapı" value={draft.diameter} onChange={event => change({ diameter: event.target.value })} placeholder="Örn. Ø 23" /></Field>
          <Field label="Hammadde kodu"><input aria-label="Hammadde kodu" value={draft.materialCode} onChange={event => change({ materialCode: event.target.value.toUpperCase() })} placeholder="Örn. Z170016" /></Field>
          <Field label="Hammadde açıklaması"><input aria-label="Hammadde açıklaması" value={draft.materialName} onChange={event => change({ materialName: event.target.value })} placeholder="Malzeme cinsi ve çapı" /></Field>
          <Field label="Hammadde ağırlığı (g)"><input aria-label="Hammadde ağırlığı (g)" inputMode="decimal" value={draft.grams} onChange={event => change({ grams: event.target.value })} placeholder="Bir adet için gram" /></Field>
          <Field label="Ürün açıklaması (isteğe bağlı)"><input aria-label="Ürün açıklaması (isteğe bağlı)" value={draft.productName} onChange={event => change({ productName: event.target.value })} /></Field>
        </div><p className="new-type-material-note">Ağırlık, bir adet üretim için gereken hammadde miktarıdır. Hammadde ihtiyacında kullanılır; ambar stoğunu değiştirmez.</p>
        <div className="calendar-impact-note"><strong>{draft.product} · Üretim rotası</strong><span>{newTypeRouteLabel(validation.route)} → Paketleme &amp; Final Kontrol</span><span>Tip, aktif proses parametreleri ve hammadde bilgileri birlikte kaydedilir.</span></div>
      </>}
      {errors.length > 0 && <div className="new-product-validation" role="alert"><Warning size={17} weight="fill" /><div><strong>Bilgileri kontrol edin</strong>{errors.map(error => <span key={error}>{error}</span>)}</div></div>}
      <div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button>{step > 0 && <button className="secondary" onClick={() => go(step - 1)}>Geri</button>}<button className="primary" onClick={advance}>{step === 4 ? "Tipi oluştur" : "İleri"}</button></div>
    </div>
  </section></div>;
}

frontend/features/planning/parameters/Pa.source:
"use client";

import { useState } from "react";
import { useRaviScreenContext } from "../../ravi/context";
import type { PlanningSeed } from "../../../lib/planning";
import type { DeactivationDecision, DeactivationImpact, DeactivationTarget } from "../../../lib/parameter-deactivation";

export type SaveParameterDraft = (mutator: (draft: PlanningSeed) => void, targets: DeactivationTarget[]) => Promise<boolean>;

const decisionLabels = { move: "Başka tezgaha taşı", "release-to-automatic": "Otomatik planlamaya bırak", remove: "Plandan çıkar" };

export function ParameterDeactivationDialog({ impacts, onConfirm, onClose }: {
  impacts: DeactivationImpact[];
  onConfirm: (decisions: DeactivationDecision[]) => Promise<void>;
  onClose: () => void;
}) {
  const [decisions, setDecisions] = useState<Record<string, DeactivationDecision>>({});
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const queued = impacts.flatMap(impact => impact.queued);
  const complete = queued.every(job => {
    const decision = decisions[job.key];
    return decision && job.allowedDecisions.includes(decision.kind)
      && (decision.kind !== "move" || job.moveTargets.includes(decision.targetResourceId ?? ""));
  });
  useRaviScreenContext("parameter-deactivation", { targets: impacts.map(impact => impact.target),
    affectedJobKeys: impacts.flatMap(impact => [...impact.running, ...impact.queued].map(job => job.key)),
    decisions: Object.values(decisions), error, saving });

  async function confirm() {
    if (!complete || saving) return;
    setSaving(true); setError("");
    try { await onConfirm(queued.map(job => decisions[job.key])); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Parametre kaydedilemedi. İşleri yeniden inceleyin."); }
    finally { setSaving(false); }
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="confirmation-dialog" role="dialog" aria-modal="true" aria-labelledby="parameter-deactivation-title">
    <h2 id="parameter-deactivation-title">Pasif yapmadan önce etkilenen işler</h2>
    <p>Her bekleyen iş için bir işlem seçin. Onaydan önce parametreler ve işler değiştirilmez.</p>
    <div style={{ maxHeight: "60vh", overflowY: "auto" }}>{impacts.map(impact => <section key={`${impact.target.process}:${impact.target.product}:${impact.target.resourceId}`}>
      <h3>{impact.target.product} · {impact.target.resourceId}</h3>
      {impact.running.map(job => <p key={job.key}><strong>Çalışan iş korunur</strong> · {job.workOrder || job.batchId} · {job.quantity} adet</p>)}
      {impact.queued.map(job => <div key={job.key} className="confirmation-field">
        <p><strong>{job.workOrder || job.batchId}</strong> · {job.batchId} · {job.quantity} adet{job.locked ? " · Kilitli" : ""}{job.protectedRemainder ? " · Üretimden kalan iş korunur" : ""}</p>
        <label>Bekleyen iş için işlem<select aria-label={`${job.workOrder || job.batchId} için işlem`} disabled={saving} value={decisions[job.key]?.kind ?? ""} onChange={event => {
          const kind = event.target.value as DeactivationDecision["kind"];
          setDecisions(current => { const next = { ...current }; if (kind) next[job.key] = { key: job.key, kind }; else delete next[job.key]; return next; });
        }}><option value="">İşlem seçin</option>{job.allowedDecisions.map(kind => <option key={kind} value={kind}>{decisionLabels[kind]}</option>)}</select></label>
        {decisions[job.key]?.kind === "move" && <label>Hedef tezgah<select aria-label={`${job.workOrder || job.batchId} hedef tezgah`} disabled={saving} value={decisions[job.key]?.targetResourceId ?? ""} onChange={event => setDecisions(current => ({ ...current, [job.key]: { key: job.key, kind: "move", targetResourceId: event.target.value } }))}><option value="">Tezgah seçin</option>{job.moveTargets.map(id => <option key={id} value={id}>{id}</option>)}</select></label>}
        {!job.allowedDecisions.length && <p role="alert">Bu iş için uygun işlem yok. Atamayı aktif tutun ve işi inceleyin.</p>}
      </div>)}
    </section>)}</div>
    {error && <p role="alert">{error}</p>}
    <div className="confirmation-actions"><button disabled={saving} onClick={onClose}>Vazgeç</button><button className="primary" disabled={!complete || saving} onClick={() => void confirm()}>{saving ? "Kaydediliyor…" : "Seçimleri uygula ve Pasif yap"}</button></div>
  </section></div>;
}

"use client";

import { canUseCompletePackage, importCompletePackageWithReview, parameterPackageReviewTargets } from "./complete-package-review";
import type { SaveParameterDraft } from "./ParameterDeactivationDialog";
import { useRaviScreenContext } from "@/features/ravi/context";

import { NewProductTypeDialog } from "./NewProductTypeDialog";
import { type NewTypeWizardDraft } from "@/lib/new-product-type";
import { ProcessParametersEditor } from "@/components/ProcessParametersEditor";
import { ProductionProcessTabs } from "@/components/ProductionProcessWorkspace";
import { DataPackageActions } from "@/features/planning/shared/DataPackageActions";
import { completePackage, applyParameterPackage, parameterPackage } from "@/lib/data-packages";
import { formatDecimal, formatInteger } from "@/lib/number-format";
import { Badge, Drawer, HelpTip, PageBarSlot, StatusLine, type StatusItem } from "@/components/ui/primitives";
import { Menu, MenuDivider } from "@/components/ui/Menu";
import { Metric } from "@/features/planning/shared/controls";
import {
  addTurningParametersForExistingProcessProduct,
  applyProductParameterDraft,
  missingTurningParameterProducts,
  parameterDiameterOptions,
  parameterFamilyOptions,
  productMatchesParameterFilters,
  productParameterDraft,
  type ProductParameterDraft,
  validateProductParameterDraft,
} from "@/lib/parameters";
import { diameterNumeric, type PlanningSeed, type ScenarioResult, type Product } from "@/lib/planning";
import { type DownstreamProcess, type ProcessKind } from "@/lib/process-master-data";
import { type ProductSetupFamily, productSetupFamilyLabel } from "@/lib/setup-families";
import { CaretDown, CaretUp, DotsSixVertical, FileXls, MagnifyingGlass, PencilSimple, Plus, X } from "@phosphor-icons/react";
import { useLayoutEffect, useRef, useState } from "react";

export function ParametersView({ seed, result, updateSeed, onCreateType, canManageMaterials, onSaveParameterDraft }: { onSaveParameterDraft?: SaveParameterDraft; result: ScenarioResult; seed: PlanningSeed; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; onCreateType: (draft: NewTypeWizardDraft) => void; canManageMaterials: boolean }) {
  const [activeProcess, setActiveProcess] = useState<ProcessKind>("turning");
  const [query, setQuery] = useState("");
  const [diameterFilter, setDiameterFilter] = useState("");
  const [familyFilter, setFamilyFilter] = useState<ProductSetupFamily | "">("");
  const [onlyMissing, setOnlyMissing] = useState(false);
  const [newProductOpen, setNewProductOpen] = useState(false);
  const [createdProduct, setCreatedProduct] = useState("");
  const [editingProduct, setEditingProduct] = useState<string | null>(null);
  const [selectedAssignment, setSelectedAssignment] = useState<{ product: string; machineId: string; draftStatus: "Aktif" | "Pasif" } | null>(null);
  const missingTurningProducts = missingTurningParameterProducts(seed);
  const missingCodes = new Set(missingTurningProducts.map((item) => item.product));
  const turningProducts = [...seed.products, ...missingTurningProducts];
  const assignmentProduct = seed.products.find((item) => item.product === selectedAssignment?.product);
  useRaviScreenContext("parameters", { activeProcess, query, diameterFilter, familyFilter, onlyMissing, newProductOpen, editingProduct, missingTurningParameterCount: missingTurningProducts.length, productionRateUnit: "adet/vardiya", selectedAssignment: selectedAssignment && { ...selectedAssignment, savedStatus: assignmentProduct?.inactiveMachineIds?.includes(selectedAssignment.machineId) ? "Pasif" : "Aktif" } });
  const diameterOptions = parameterDiameterOptions(turningProducts);
  const familyOptions = parameterFamilyOptions(turningProducts);
  const activeDiameterFilter = diameterOptions.some((option) => option.value === diameterFilter) ? diameterFilter : "";
  const activeFamilyFilter = familyOptions.some((option) => option.value === familyFilter) ? familyFilter : "";
  const showOnlyMissing = onlyMissing && missingTurningProducts.length > 0;
  const visibleProducts = turningProducts.filter((product) => productMatchesParameterFilters(product, query, activeDiameterFilter, activeFamilyFilter) && (!showOnlyMissing || missingCodes.has(product.product)));
  const visibleProductCount = visibleProducts.length;
  const filtersActive = Boolean(query.trim() || activeDiameterFilter || activeFamilyFilter || showOnlyMissing);
  const editedProduct = turningProducts.find((item) => item.product === editingProduct);
  async function importParameters(data: unknown): Promise<boolean> {
    if (seed.productionArea !== "cubuk-filtre" && onSaveParameterDraft) {
      return onSaveParameterDraft(draft => applyParameterPackage(draft, data), parameterPackageReviewTargets(seed, data));
    }
    updateSeed(draft => applyParameterPackage(draft, data));
    return true;
  }
  async function importCompletePackage(data: unknown): Promise<boolean> {
    if (!canUseCompletePackage(seed, canManageMaterials)) throw new Error("Tam yedek yalnız Torna alanında yönetici tarafından uygulanabilir.");
    return importCompletePackageWithReview(seed, data, onSaveParameterDraft);
  }
  async function saveProduct(product: Product, validation: ReturnType<typeof validateProductParameterDraft>): Promise<boolean> {
    const mutator = (draft: PlanningSeed) => {
      if (draft.products.some((item) => item.product === product.product)) applyProductParameterDraft(draft, product.product, validation);
      else addTurningParametersForExistingProcessProduct(draft, product.product, validation);
    };
    const targets = validation.inactiveMachineIds.filter(id => !product.inactiveMachineIds?.includes(id)).map(resourceId => ({ process: "turning" as const, product: product.product, resourceId }));
    if (seed.productionArea !== "cubuk-filtre" && onSaveParameterDraft && targets.length) return onSaveParameterDraft(mutator, targets);
    updateSeed(mutator);
    return true;
  }
  const statusItems: StatusItem[] = [];
  if (createdProduct) statusItems.push({ id: "created", tone: "ok", title: `${createdProduct} kullanıma hazır`, detail: "Tip, aktif prosesleri ve hammadde bilgileriyle kaydedildi. Sipariş adedini girdikten sonra planı yeniden çalıştırın.", action: <button type="button" className="ui-icon-btn" onClick={() => setCreatedProduct("")} aria-label="Yeni tip bildirimini kapat"><X size={13} /></button> });
  if (missingTurningProducts.length > 0) statusItems.push({ id: "missing-turning", tone: "warn", title: `${missingTurningProducts.length} tipin Torna parametresi eksik`, detail: "Diğer proses kayıtları mevcut. Tipi açıp tezgah, vardiyalık üretim, şarj büyüklüğü ve çap bilgilerini girerek Kaydet’e basın.", action: <button type="button" className="ui-btn" aria-pressed={showOnlyMissing} onClick={() => setOnlyMissing((value) => !value)}>{showOnlyMissing ? "Tüm tipler" : "Eksikleri göster"}</button> });
  return (
    <>
    <PageBarSlot>
      <div className="params-bar-metrics">
        <Metric compact label="Tip" value={formatInteger(turningProducts.length)} detail={`${formatInteger(seed.products.length)} tip Torna parametresiyle tanımlı`} description="Parametreler’deki ürün tipleri. Diğer proses sekmeleri kendi ürün parametrelerini listeler." />
        {missingTurningProducts.length > 0 && <Metric compact tone="warning" label="Torna parametresi eksik" value={formatInteger(missingTurningProducts.length)} detail="Delme, Çapak Alma veya GKM kaydı var, Torna ürün parametresi yok" description="Bu tipler parametreler tamamlanana kadar Torna’da planlanamaz." />}
      </div>
      <button id="parameters-new-type" className="ui-btn primary new-product-action" onClick={() => setNewProductOpen(true)}><Plus size={15} /> Yeni tip</button>
    </PageBarSlot>
    <section className="params-page">
      <div className="params-surface">
        <div className="production-process-switcher parameter-process-switcher params-tabs"><ProductionProcessTabs seed={seed} value={activeProcess} onChange={setActiveProcess} /></div>
        {activeProcess === "turning" ? <>
          <div className="params-toolbar">
            <div className="params-count"><strong>{filtersActive ? `${visibleProductCount} / ${turningProducts.length}` : turningProducts.length} tip</strong><HelpTip align="start" text="Torna parametreleri: ürün, tezgah uygunluğu, şarj ve üretim hızı. Üretim hızları adet/vardiya olarak gösterilir ve girilir; eski günlük 900 adet, vardiyalık 300 adettir. Satırı açıp düzenleyin; değişiklikler yalnızca “Kaydet” ile uygulanır. Eksik veya tanımsız tezgah kodları mevcut veriyi silmez." /></div>
            <label className="params-search"><MagnifyingGlass size={15} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ürün ara" aria-label="Ürün ara" /></label>
            <label className={`params-filter ${activeFamilyFilter ? "active" : ""}`}><span>Ürün ailesi</span><select aria-label="Ürün ailesine göre filtrele" value={activeFamilyFilter} onChange={(event) => setFamilyFilter(event.target.value as ProductSetupFamily | "")}><option value="">Tüm aileler</option>{familyOptions.map((option) => <option key={option.value} value={option.value}>{option.label} · {option.productCount} tip</option>)}</select></label>
            <label className={`params-filter ${activeDiameterFilter ? "active" : ""}`}><span>Hammadde çapı</span><select aria-label="Hammadde çapına göre filtrele" value={activeDiameterFilter} onChange={(event) => setDiameterFilter(event.target.value)}><option value="">Tüm çaplar</option>{diameterOptions.map((option) => <option key={option.value} value={option.value}>{option.label} · {option.productCount} tip</option>)}</select></label>
            <Menu className="params-excel" label="Excel" icon={<FileXls size={15} />} title="Parametreler Excel indir / yükle">
              <span className="ui-menu-label">Parametreler</span>
              <DataPackageActions scope="parameters" data={parameterPackage(seed)} onImport={importParameters} />
              {canUseCompletePackage(seed, canManageMaterials) && <><MenuDivider /><span className="ui-menu-label">Tam yedek</span><DataPackageActions scope="complete" data={completePackage(seed)} onImport={importCompletePackage} exportLabel="Tam yedek (Parametreler ve Ayarlar)" importLabel="Tam yedek yükle" /></>}
            </Menu>
          </div>
          <StatusLine items={statusItems} label="Parametre uyarıları" />
          <div className="table-scroll params-table-scroll"><table className="ui-table params-table"><thead><tr><th>Ürün</th><th>Ürün ailesi</th><th>Tezgah önceliği ve vardiyalık üretim</th><th className="numeric">Şarj büyüklüğü</th><th className="numeric">Varsayılan vardiyalık üretim</th><th>Çap</th><th>Kaynak</th><th>Durum</th><th><span className="params-sr">Düzenle</span></th></tr></thead><tbody>
            {visibleProducts.map((product) => seed.processMasterData?.products.find(item => item.product === product.product)?.route?.includes("turning") === false
              ? <tr key={product.product} className="params-row passive"><td><strong>{product.product}</strong></td><td>{productSetupFamilyLabel(product.setupFamily)}</td><td colSpan={3} className="params-muted">Torna pasif · Üretim kayıtlı yarı mamul üzerinden ilerler.</td><td>{product.diameter}</td><td className="params-muted">{product.source}</td><td><Badge>Pasif</Badge></td><td /></tr>
              : <ParameterSummaryRow key={product.product} seed={seed} product={product} missing={missingCodes.has(product.product)} onEdit={() => setEditingProduct(product.product)} />)}
            {visibleProductCount === 0 && <tr className="parameter-empty-row"><td colSpan={9}><strong>Eşleşen tip bulunamadı</strong><span>Ürün aramasını, aile veya hammadde çapı filtresini değiştirin.</span><button className="ui-btn" onClick={() => { setQuery(""); setFamilyFilter(""); setDiameterFilter(""); setOnlyMissing(false); }}>Filtreleri temizle</button></td></tr>}
          </tbody></table></div>
        </> : <ProcessParametersEditor key={activeProcess} seed={seed} updateSeed={updateSeed} onSaveParameterDraft={seed.productionArea !== "cubuk-filtre" ? onSaveParameterDraft : undefined} process={activeProcess as DownstreamProcess} />}
      </div>
    </section>
    {activeProcess === "turning" && editedProduct && <ParameterRow key={editedProduct.product} seed={seed} product={editedProduct} familyLocked={missingCodes.has(editedProduct.product)} onClose={() => setEditingProduct(null)} onAssignmentChange={(machineId, active) => setSelectedAssignment({ product: editedProduct.product, machineId, draftStatus: active ? "Aktif" : "Pasif" })} onSave={(validation) => saveProduct(editedProduct, validation)} />}
    {newProductOpen && <NewProductTypeDialog seed={seed} canManageMaterials={canManageMaterials} onClose={() => setNewProductOpen(false)} onSave={(draft) => {
      onCreateType(draft);
      setActiveProcess("turning");
      setQuery(draft.product.trim().toUpperCase());
      setFamilyFilter(draft.setupFamily ?? "");
      setDiameterFilter(String(diameterNumeric(draft.diameter)));
      setOnlyMissing(false);
      setCreatedProduct(draft.product.trim().toUpperCase());
      setNewProductOpen(false);
    }} />}
    </>
  );
}

/** Read-only summary of one product's saved Torna parameters; editing opens the drawer. */
function ParameterSummaryRow({ seed, product, missing, onEdit }: { seed: PlanningSeed; product: Product; missing: boolean; onEdit: () => void }) {
  const saved = productParameterDraft(seed, product);
  const validation = validateProductParameterDraft(seed, product, saved);
  const passiveCount = saved.machines.filter((machineId) => saved.inactiveMachineIds?.includes(machineId)).length;
  const shown = saved.machines.slice(0, 4);
  return <tr className="params-row" onClick={(event) => { if (!(event.target as HTMLElement).closest("button")) onEdit(); }}>
    <td><strong>{product.product}</strong></td>
    <td>{productSetupFamilyLabel(saved.setupFamily || product.setupFamily)}</td>
    <td><ol className="params-priority-summary">{shown.map((machineId, index) => { const passive = saved.inactiveMachineIds?.includes(machineId); return <li key={machineId} className={passive ? "passive" : ""} title={`${index === 0 ? "Ana tezgah" : `${index + 1}. tercih`} · ${seed.machines.find((machine) => machine.id === machineId)?.name ?? "Tanımsız tezgah"}${passive ? " · Pasif" : ""}`}><b>{index + 1}</b>{machineId}<span>{formatDecimal(Number(saved.machineShiftRates[machineId]) || 0, 6)}</span></li>; })}{saved.machines.length > shown.length && <li className="more">+{saved.machines.length - shown.length}</li>}{!saved.machines.length && <li className="empty">Tezgah seçilmedi</li>}</ol></td>
    <td className="numeric">{saved.batchSize ? formatInteger(Number(saved.batchSize)) : "—"}</td>
    <td className="numeric">{formatDecimal(Number(saved.defaultShiftRate) || 0, 6)} <span className="params-unit">adet/vardiya</span></td>
    <td>{saved.diameter || "—"}</td>
    <td className="params-muted source-cell">{product.source}</td>
    <td>{missing ? <Badge tone="warn" title="Torna parametresi bekliyor">Eksik</Badge> : validation.errors.length ? <Badge tone="danger" title={validation.errors[0]}>Eksik</Badge> : passiveCount ? <Badge title="Planlama durumu Pasif olan tezgah">{passiveCount} pasif</Badge> : <span className="params-muted">Güncel</span>}</td>
    <td className="params-edit-cell"><button type="button" className="ui-icon-btn" onClick={onEdit} aria-label={`${product.product} parametrelerini düzenle`} title="Düzenle"><PencilSimple size={15} /></button></td>
  </tr>;
}

/** Edit drawer for one product: the same fields, validation and save handler the table rows used. */
function ParameterRow({ seed, product, familyLocked = false, onClose, onAssignmentChange, onSave }: { seed: PlanningSeed; product: Product; familyLocked?: boolean; onClose: () => void; onAssignmentChange: (machineId: string, active: boolean) => void; onSave: (validation: ReturnType<typeof validateProductParameterDraft>) => Promise<boolean> }) {
  const initial = productParameterDraft(seed, product);
  const [draft, setDraft] = useState<ProductParameterDraft>(initial);
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState("");
  const [editingRateMachineId, setEditingRateMachineId] = useState<string | null>(null);
  const [editingDefaultRate, setEditingDefaultRate] = useState(false);
  const [confirmDiscard, setConfirmDiscard] = useState(false);
  const [priorityDrag, setPriorityDrag] = useState<{ machineId: string; targetIndex: number; edge: "before" | "after" } | null>(null);
  const priorityListRef = useRef<HTMLDivElement | null>(null);
  const priorityPositionsRef = useRef<Map<string, number>>(new Map());
  const priorityMovedRef = useRef<string | null>(null);
  const priorityGestureRef = useRef<{ machineId: string; sourceIndex: number; startY: number; active: boolean } | null>(null);
  const priorityDropRef = useRef<number | null>(null);
  const priorityOrderKey = draft.machines.join("|");

  useLayoutEffect(() => {
    const rows = priorityListRef.current?.querySelectorAll<HTMLElement>(".machine-priority-item[data-machine-id]");
    if (!rows) return;
    const nextPositions = new Map<string, number>();
    rows.forEach((row) => {
      const machineId = row.dataset.machineId;
      if (machineId) nextPositions.set(machineId, row.getBoundingClientRect().top);
    });
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!reduceMotion && priorityPositionsRef.current.size) {
      rows.forEach((row) => {
        const machineId = row.dataset.machineId;
        if (!machineId) return;
        const previousTop = priorityPositionsRef.current.get(machineId);
        const nextTop = nextPositions.get(machineId);
        const delta = previousTop == null || nextTop == null ? 0 : previousTop - nextTop;
        if (Math.abs(delta) > 1) {
          row.animate([{ transform: `translateY(${delta}px)` }, { transform: "translateY(0)" }], { duration: machineId === priorityMovedRef.current ? 420 : 320, easing: "cubic-bezier(.2,.8,.2,1)" });
        }
        if (machineId === priorityMovedRef.current) {
          row.animate([{ backgroundColor: "var(--ui-accent-soft)", boxShadow: "inset 3px 0 0 var(--ui-accent)" }, { backgroundColor: "var(--ui-surface-2)", boxShadow: "inset 3px 0 0 var(--ui-accent)", offset: .55 }, { backgroundColor: "transparent", boxShadow: "inset 0 0 0 transparent" }], { duration: 760, easing: "ease-out" });
        }
      });
    }
    priorityPositionsRef.current = nextPositions;
    priorityMovedRef.current = null;
  }, [priorityOrderKey]);

  function beginPriorityDrag(event: React.PointerEvent<HTMLSpanElement>, machineId: string, index: number) {
    if (event.button !== 0) return;
    priorityGestureRef.current = { machineId, sourceIndex: index, startY: event.clientY, active: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function continuePriorityDrag(event: React.PointerEvent<HTMLSpanElement>) {
    const gesture = priorityGestureRef.current;
    if (!gesture) return;
    if (!gesture.active && Math.abs(event.clientY - gesture.startY) < 5) return;
    gesture.active = true;
    const row = document.elementFromPoint(event.clientX, event.clientY)?.closest<HTMLElement>(".machine-priority-item[data-priority-index]");
    if (!row || row.closest(".machine-priority-list") !== priorityListRef.current) return;
    const targetIndex = Number(row.dataset.priorityIndex);
    if (!Number.isInteger(targetIndex)) return;
    const rect = row.getBoundingClientRect();
    const edge = event.clientY < rect.top + rect.height / 2 ? "before" : "after";
    const rawInsertion = targetIndex + (edge === "after" ? 1 : 0);
    priorityDropRef.current = Math.max(0, Math.min(draft.machines.length - 1, rawInsertion > gesture.sourceIndex ? rawInsertion - 1 : rawInsertion));
    setPriorityDrag({ machineId: gesture.machineId, targetIndex, edge });
  }

  function endPriorityDrag(event: React.PointerEvent<HTMLSpanElement>) {
    const gesture = priorityGestureRef.current;
    if (!gesture) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    const drop = priorityDropRef.current;
    if (gesture.active && drop != null && drop !== gesture.sourceIndex) {
      const machines = [...draft.machines];
      const [moved] = machines.splice(gesture.sourceIndex, 1);
      machines.splice(drop, 0, moved);
      priorityMovedRef.current = moved;
      change({ machines });
    }
    priorityGestureRef.current = null;
    priorityDropRef.current = null;
    setPriorityDrag(null);
  }
  const validation = validateProductParameterDraft(seed, product, draft);
  const machineInvalid = draft.machines.length === 0 || draft.machines.some((machine) => !seed.machines.some((known) => known.id === machine));
  const batchNumber = Number(draft.batchSize);
  const batchInvalid = !Number.isInteger(batchNumber) || batchNumber <= 0;
  const defaultRateNumber = Number(draft.defaultShiftRate);
  const defaultRateInvalid = !Number.isFinite(defaultRateNumber) || defaultRateNumber <= 0;
  const diameterInvalid = diameterNumeric(draft.diameter.trim()) <= 0;
  const rateSignature = (value: ProductParameterDraft) => value.machines.map((machineId) => `${machineId}:${value.machineShiftRates[machineId] ?? ""}`).join("|");
  const changed = draft.machines.join("|") !== initial.machines.join("|") || draft.inactiveMachineIds?.join("|") !== initial.inactiveMachineIds?.join("|") || rateSignature(draft) !== rateSignature(initial) || draft.defaultShiftRate !== initial.defaultShiftRate || draft.batchSize !== initial.batchSize || draft.diameter.trim() !== initial.diameter.trim() || draft.setupFamily !== initial.setupFamily;
  const message = validation.errors[0] ?? (changed ? validation.warnings[0] : undefined);

  function change(patch: Partial<ProductParameterDraft>) {
    setDraft((current) => ({ ...current, ...patch }));
    setSaved(false);
    setConfirmDiscard(false);
  }

  function requestClose() {
    if (changed && !saving) setConfirmDiscard(true);
    else onClose();
  }

  async function save() {
    if (!changed || validation.errors.length || saving) return;
    setSaving(true); setSaveError("");
    try {
      if (!await onSave(validation)) return;
      setDraft({ machines: [...validation.machines], inactiveMachineIds: [...validation.inactiveMachineIds], machineShiftRates: Object.fromEntries(validation.machines.map((machineId) => [machineId, String(validation.machineShiftRates[machineId])])), defaultShiftRate: String(validation.defaultShiftRate), batchSize: String(validation.batchSize), diameter: validation.diameter, setupFamily: validation.setupFamily });
      setEditingRateMachineId(null);
      setEditingDefaultRate(false);
      setSaved(true);
    } catch (cause) { setSaveError(cause instanceof Error ? cause.message : "Parametre kaydedilemedi."); }
    finally { setSaving(false); }
  }

  function addMachine(machineId: string) {
    if (draft.machines.includes(machineId)) return;
    change({ machines: [...draft.machines, machineId], machineShiftRates: { ...draft.machineShiftRates, [machineId]: draft.defaultShiftRate } });
  }

  function removeMachine(machineId: string) {
    change({ machines: draft.machines.filter((item) => item !== machineId), inactiveMachineIds: draft.inactiveMachineIds?.filter((item) => item !== machineId) });
    if (editingRateMachineId === machineId) setEditingRateMachineId(null);
  }

  function setMachineActive(machineId: string, active: boolean) {
    change({ inactiveMachineIds: active ? draft.inactiveMachineIds?.filter((item) => item !== machineId) ?? [] : [...(draft.inactiveMachineIds ?? []), machineId] });
    onAssignmentChange(machineId, active);
  }

  function moveMachine(index: number, direction: -1 | 1) {
    const target = index + direction;
    if (target < 0 || target >= draft.machines.length) return;
    const machines = [...draft.machines];
    [machines[index], machines[target]] = [machines[target], machines[index]];
    priorityMovedRef.current = machines[target];
    change({ machines });
  }

  const saveLabel = saving ? "İnceleme bekleniyor…" : saved ? "Kaydedildi" : changed ? "Kaydet" : familyLocked ? "Eksik" : "Güncel";
  return <Drawer className="params-drawer" width={600} title={product.product} subtitle={`Torna parametreleri · ${productSetupFamilyLabel(draft.setupFamily || product.setupFamily)} · Kaynak: ${product.source}`} label={`${product.product} Torna parametreleri`} onClose={requestClose} footer={<>
    {confirmDiscard && <span className="params-discard" role="alert">Kaydedilmemiş değişiklikler var.<button type="button" className="ui-btn" onClick={onClose}>Değişiklikleri at</button></span>}
    <button type="button" className="ui-btn" onClick={requestClose}>Kapat</button>
    <button type="button" className="ui-btn primary parameter-save" disabled={saving || !changed || validation.errors.length > 0} onClick={() => void save()}>{saveLabel}</button>
  </>}>
    <div className={validation.errors.length && changed ? "parameter-row params-form invalid" : "parameter-row params-form"}>
      <label className="ui-field"><span>Ürün ailesi</span><select className="product-family-select" aria-label={`${product.product} ürün ailesi`} value={draft.setupFamily ?? ""} disabled={familyLocked} onChange={(event) => change({ setupFamily: event.target.value as ProductSetupFamily | "" })}><option value="">Seçin</option><option value="piston">Piston</option><option value="center-pin">Center Pin</option></select></label>
      <div className="params-form-grid">
        <label className="ui-field"><span>Şarj büyüklüğü</span><input aria-label={`${product.product} şarj büyüklüğü`} className={`cell-input numeric ${batchInvalid && changed ? "invalid" : ""}`} inputMode="numeric" value={draft.batchSize} onChange={(event) => change({ batchSize: event.target.value })} /></label>
        <label className="ui-field"><span>Çap</span><input aria-label={`${product.product} çap`} className={`cell-input compact ${diameterInvalid && changed ? "invalid" : ""}`} value={draft.diameter} onChange={(event) => change({ diameter: event.target.value })} /></label>
      </div>
      <div className={`ui-field default-daily-rate-cell ${defaultRateInvalid && changed ? "invalid" : ""}`}><span>Varsayılan vardiyalık üretim <HelpTip align="start" text="Tezgah seç ile eklenen tezgaha bu adet önerilir. Varsayılanı değiştirmek mevcut tezgaha özel hızları değiştirmez." /></span><div className={`default-daily-rate ${editingDefaultRate ? "editing" : ""}`}>{editingDefaultRate ? <><input aria-label={`${product.product} varsayılan vardiyalık üretim`} type="number" min="0" step="any" value={draft.defaultShiftRate} onChange={(event) => change({ defaultShiftRate: event.target.value })} autoFocus /><button type="button" className="ui-btn" disabled={validation.errors.length > 0} onClick={() => { if (changed) save(); else setEditingDefaultRate(false); }}>{changed ? "Kaydet" : "Kapat"}</button></> : <><strong>{formatDecimal(defaultRateNumber || 0, 6)}</strong><span>adet/vardiya</span><button type="button" className="ui-btn" onClick={() => setEditingDefaultRate(true)}>Değiştir</button></>}</div></div>
      <div className={`params-priority-field machine-priority-cell ${machineInvalid && changed ? "invalid" : ""}`}>
        <span className="params-field-label">Tezgah önceliği ve vardiyalık üretim <HelpTip align="start" text="Sıra planlama önceliğidir: 1 ana tezgahtır. Tutup sürükleyerek veya oklarla sıralayın. Planlama durumu Pasif olan tezgah bu ürün için yeni planda kullanılmaz; eşleşme ve hız saklanır." /></span>
        <div ref={priorityListRef} className="machine-priority-list">{draft.machines.map((machineId, index) => <div key={machineId} data-machine-id={machineId} data-priority-index={index} className={`machine-priority-item ${draft.inactiveMachineIds?.includes(machineId) ? "passive" : ""} ${priorityDrag?.machineId === machineId ? "dragging" : ""} ${priorityDrag && priorityDrag.targetIndex === index && priorityDrag.machineId !== machineId ? `drop-${priorityDrag.edge}` : ""}`}><span className="priority-drag-handle" title="Tutup sürükleyerek sıralayın" onPointerDown={(event) => beginPriorityDrag(event, machineId, index)} onPointerMove={continuePriorityDrag} onPointerUp={endPriorityDrag} onPointerCancel={endPriorityDrag}><DotsSixVertical size={12} /><b>{index + 1}</b></span><div className="machine-priority-identity"><strong>{machineId}</strong><small>{seed.machines.find((machine) => machine.id === machineId)?.name ?? "Tanımsız tezgah"}</small></div><small className="machine-priority-role">{index === 0 ? "Ana tezgah" : `${index + 1}. tercih`}</small><span className="params-priority-moves"><button type="button" disabled={index === 0} onClick={() => moveMachine(index, -1)} aria-label={`${machineId} önceliğini yükselt`}><CaretUp size={13} /></button><button type="button" disabled={index === draft.machines.length - 1} onClick={() => moveMachine(index, 1)} aria-label={`${machineId} önceliğini düşür`}><CaretDown size={13} /></button><button type="button" className="remove" onClick={() => removeMachine(machineId)} aria-label={`${machineId} seçimini kaldır`}><X size={13} /></button></span><label className="parameter-assignment-status"><span>Planlama durumu</span><select aria-label={`${product.product} ${machineId} planlama durumu`} value={draft.inactiveMachineIds?.includes(machineId) ? "passive" : "active"} onChange={(event) => setMachineActive(machineId, event.target.value === "active")}><option value="active">Aktif</option><option value="passive">Pasif</option></select></label><div className={`machine-daily-rate ${editingRateMachineId === machineId ? "editing" : ""}`}><small>Vardiyalık üretim</small>{editingRateMachineId === machineId ? <span><input type="number" min="0" step="any" aria-label={`${machineId} vardiyalık üretim`} value={draft.machineShiftRates[machineId] ?? ""} onChange={(event) => change({ machineShiftRates: { ...draft.machineShiftRates, [machineId]: event.target.value } })} autoFocus /><button type="button" className="ui-btn" disabled={validation.errors.length > 0} onClick={() => { if (changed) save(); else setEditingRateMachineId(null); }}>{changed ? "Kaydet" : "Kapat"}</button></span> : <span><b>{formatDecimal(Number(draft.machineShiftRates[machineId]) || 0, 6)}</b><em>adet/vardiya</em><button type="button" className="ui-btn" onClick={() => setEditingRateMachineId(machineId)}>Değiştir</button></span>}</div></div>)}</div>
        <details className="machine-priority-picker"><summary className="ui-btn"><Plus size={13} /> Tezgah seç</summary><div><p>Seçim sırası planlama önceliğidir. Yeni tezgah ürünün varsayılan vardiyalık üretim adediyle eklenir.</p><div className="machine-option-grid">{seed.machines.map((machine) => { const rank = draft.machines.indexOf(machine.id); return <button type="button" key={machine.id} className={rank >= 0 ? "selected" : ""} disabled={rank >= 0} onClick={() => addMachine(machine.id)}><span>{rank >= 0 ? rank + 1 : "+"}</span><b><strong>{machine.id}</strong><small>{machine.name}</small></b></button>; })}</div></div></details>
      </div>
      {saveError && <p className="params-feedback error" role="alert">{saveError}</p>}
      {(message || saved) && <p className="parameter-feedback-row params-feedback"><span className={validation.errors.length ? "error" : saved ? "success" : "warning"}>{validation.errors.length ? "Kaydedilmedi" : saved ? "Kalıcı olarak kaydedildi" : "Kontrol edin"}</span>{message ?? "Parametreler planlama motoruna uygulandı."}</p>}
    </div>
  </Drawer>;
}

