import { effectiveWaitSources, type EffectiveWaitSource } from "@/lib/flow-settings";
import type { PlanningSeed } from "@/lib/planning";

/** Describe saved rules only. Panel defaults and drafts are not active settings. */
export function flowActivationStatus(seed: Pick<PlanningSeed, "flowSettings" | "processWaitSettings" | "productionArea">): {
  savedEnabled: boolean;
  savedRuleCount: number;
  rows: EffectiveWaitSource[];
  label: string;
} {
  const rows = effectiveWaitSources(seed);
  const savedEnabled = seed.productionArea !== "cubuk-filtre" && Boolean(seed.flowSettings?.enabled);
  return {
    savedEnabled,
    savedRuleCount: rows.filter(row => row.source === "Akış Ayarı").length,
    rows,
    label: `Kayıtlı saat bazlı akış: ${savedEnabled ? "Açık" : "Kapalı"}`,
  };
}

