"use client";

import { formatFactoryDateTime, signedNumber } from "@/features/planning/shared/format";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { planRunMetadataLabel } from "@/lib/plan-run";
import { type StoredScenario, formatExcelDate } from "@/lib/planning";
import type { ScenarioInspection } from "@/lib/scenario-inspection";

export function ScenarioDetails({ first, second, firstInspection, secondInspection }: {
  first: StoredScenario;
  second?: StoredScenario;
  firstInspection: ScenarioInspection;
  secondInspection?: ScenarioInspection;
}) {
  const machineIds = [...new Set([...firstInspection.machines, ...(secondInspection?.machines ?? [])].map((machine) => machine.id))];
  const changedOrders = second ? first.result.orders.map((order) => ({
    product: order.product, a: order, b: second.result.orders.find((item) => item.id === order.id),
  })).filter((row) => row.b && (row.a.planned !== row.b.planned || row.a.assignedMachines.join() !== row.b.assignedMachines.join())) : [];
  const planRun = first.result.planRun ?? first.seed.activePlanRun;

  return <>
    <div className="comparison-heading">
      <div>
        <span>{second ? "SENARYO KARŞILAŞTIRMA" : "SENARYO ÖZETİ"}</span>
        <h2>{first.name}{second && <><br /><em>ve</em> {second.name}</>}</h2>
        {(first.notes || second?.notes) && <small>{second ? <>{first.notes && `${scenarioColumnName(first)}: ${first.notes}`}{first.notes && second.notes ? " · " : ""}{second.notes && `${scenarioColumnName(second)}: ${second.notes}`}</> : first.notes}</small>}
        {!second && planRun && <small>{planRunMetadataLabel(planRun)}</small>}
      </div>
      <p>{second ? <>{scenarioColumnName(first)} bitiş: {formatExcelDate(first.result.summary.completion)}<br />{scenarioColumnName(second)} bitiş: {formatExcelDate(second.result.summary.completion)}<br />Fark = ikinci senaryo − ilk senaryo</> : <>Kayıt: {formatFactoryDateTime(first.createdAt)}<br />Bitiş: {formatExcelDate(first.result.summary.completion)}</>}</p>
    </div>
    <p className="scenario-snapshot-note">Kayıtlı planın sonuçları gösteriliyor.{(first.seed.planNeedsRecalculation || second?.seed.planNeedsRecalculation) ? " Seçili kayıtlarda yeniden hesaplama bekleyen plan var." : ""}</p>
    {!second && <p className="scenario-comparison-hint">Karşılaştırmak için ikinci bir senaryo seçin.</p>}
    <div className={`comparison-grid ${second ? "" : "scenario-details-grid"}`}>
      <div className="comparison-card"><h3>Temel sonuçlar</h3><table><thead><tr><th>Ölçüt</th><th className="numeric">{second ? scenarioColumnName(first) : "Değer"}</th>{second && <><th className="numeric">{scenarioColumnName(second)}</th><th className="numeric">Fark</th></>}</tr></thead><tbody>
        {firstInspection.metrics.map(({ label, value, direction }) => {
          const other = secondInspection?.metrics.find((metric) => metric.label === label)?.value;
          const delta = other === undefined ? 0 : other - value;
          const favorable = direction === "higher" ? delta > 0 : direction === "lower" ? delta < 0 : false;
          const unfavorable = direction === "higher" ? delta < 0 : direction === "lower" ? delta > 0 : false;
          return <tr key={label}><td>{label}</td><td className="numeric">{formatNumber(value)}</td>{second && <><td className="numeric">{other === undefined ? "—" : formatNumber(other)}</td><td className={`numeric variance ${favorable ? "positive" : unfavorable ? "negative" : ""}`}>{other === undefined ? "—" : signedNumber(delta)}</td></>}</tr>;
        })}
      </tbody></table></div>
      <div className="comparison-card"><h3>Tezgah yükü</h3>{machineIds.length ? <table><thead><tr><th>Tezgah</th><th className="numeric">{second ? `${scenarioColumnName(first)} şarj` : "Şarj"}</th>{second && <th className="numeric">{scenarioColumnName(second)} şarj</th>}<th className="numeric">{second ? "Miktar farkı" : "Adet"}</th></tr></thead><tbody>{machineIds.map((id) => {
        const a = firstInspection.machines.find((machine) => machine.id === id);
        const b = secondInspection?.machines.find((machine) => machine.id === id);
        return <tr key={id}><td><strong>{id}</strong></td><td className="numeric">{formatNumber(a?.count ?? 0)}</td>{second && <td className="numeric">{formatNumber(b?.count ?? 0)}</td>}<td className="numeric">{second ? signedNumber((b?.quantity ?? 0) - (a?.quantity ?? 0)) : formatNumber(a?.quantity ?? 0)}</td></tr>;
      })}</tbody></table> : <p className="empty-copy">Planlı tezgah işi yok.</p>}</div>
    </div>
    <div className="comparison-card order-comparison"><h3>{second ? "Değişen sipariş atamaları" : "Sipariş atamaları"}</h3>
      {second ? (changedOrders.length ? <table><thead><tr><th>Ürün</th><th>{scenarioColumnName(first)} plan / tezgah</th><th>{scenarioColumnName(second)} plan / tezgah</th><th className="numeric">Plan farkı</th></tr></thead><tbody>{changedOrders.map((row) => <tr key={row.a.id}><td><strong>{row.product}</strong></td><td>{formatNumber(row.a.planned)} · {row.a.assignedMachines.join(", ") || "—"}</td><td>{formatNumber(row.b?.planned ?? 0)} · {row.b?.assignedMachines.join(", ") || "—"}</td><td className="numeric">{signedNumber((row.b?.planned ?? 0) - row.a.planned)}</td></tr>)}</tbody></table> : <p className="empty-copy">Sipariş planı ve tezgah atamaları aynı.</p>) : (first.result.orders.length ? <table><thead><tr><th>Ürün</th><th className="numeric">Talep</th><th className="numeric">Planlanan</th><th>Tezgah</th></tr></thead><tbody>{first.result.orders.map((order) => <tr key={order.id}><td><strong>{order.product}</strong></td><td className="numeric">{formatNumber(order.quantity)}</td><td className="numeric">{formatNumber(order.planned)}</td><td>{order.assignedMachines.join(", ") || "—"}</td></tr>)}</tbody></table> : <p className="empty-copy">Kayıtlı sipariş yok.</p>)}
    </div>
  </>;
}

function scenarioColumnName(scenario: StoredScenario): string {
  return scenario.name.split("·")[0].trim() || scenario.name;
}

"use client";

import { useRaviScreenContext } from "@/features/ravi/context";

import { Field } from "@/features/planning/shared/controls";
import { DataPackageActions } from "@/features/planning/shared/DataPackageActions";
import { formatFactoryDateTime } from "@/features/planning/shared/format";
import { type PlanningStateRevision, type ScenarioLoadReport } from "@/features/planning/shared/types";
import { scenarioPackage } from "@/lib/data-packages";
import { buildScenarioInspection } from "@/lib/scenario-inspection";
import { ScenarioDetails } from "./ScenarioDetails";
import { planRunMetadataLabel } from "@/lib/plan-run";
import { type StoredScenario, formatExcelDate } from "@/lib/planning";
import { type StoredScenarioSummary } from "@/lib/scenario-list";
import { ArrowClockwise, ChartBar, ClockCounterClockwise, FloppyDisk, Lock, PencilSimple, Trash, Warning, X } from "@phosphor-icons/react";
import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";

type LibraryTab = "scenarios" | "history";

export function ScenariosView({ scenarios, loadedScenarios, total, loading, error, planningHistory, onFetchScenario, onLoad, onLoadMore, onRetry, onRestoreRevision, onDelete, onUpdate, onImport }: { scenarios: StoredScenarioSummary[]; loadedScenarios: StoredScenario[]; total: number; loading: boolean; error: string; planningHistory: PlanningStateRevision[]; onFetchScenario: (id: string) => Promise<StoredScenario>; onLoad: (scenario: StoredScenario) => void; onLoadMore: () => void | Promise<void>; onRetry: () => void | Promise<void>; onRestoreRevision: (revision: PlanningStateRevision) => void; onDelete: (id: string) => Promise<void>; onUpdate: (scenario: StoredScenario) => Promise<void>; onImport: (data: unknown) => Promise<void> }) {
  const [libraryTab, setLibraryTab] = useState<LibraryTab>("scenarios");
  const scenarioTabRef = useRef<HTMLButtonElement>(null);
  const historyTabRef = useRef<HTMLButtonElement>(null);
  const comparisonRef = useRef<HTMLDivElement>(null);
  const visibleHistory = planningHistory.slice(0, 20);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  useEffect(() => { comparisonRef.current?.scrollTo({ top: 0 }); }, [selectedIds]);
  const [editingScenario, setEditingScenario] = useState<StoredScenario | null>(null);
  const [detailLoadingIds, setDetailLoadingIds] = useState<string[]>([]);
  const [detailError, setDetailError] = useState("");
  const selected = selectedIds.map((id) => loadedScenarios.find((scenario) => scenario.id === id)).filter((scenario): scenario is StoredScenario => Boolean(scenario));
  const first = loadedScenarios.find((scenario) => scenario.id === selectedIds[0]);
  const second = loadedScenarios.find((scenario) => scenario.id === selectedIds[1]);
  const firstInspection = useMemo(() => first ? buildScenarioInspection(first) : undefined, [first]);
  const secondInspection = useMemo(() => second ? buildScenarioInspection(second) : undefined, [second]);
  const selectionLoading = selectedIds.some((id) => detailLoadingIds.includes(id));
  const detailMode = first && second ? "comparison" : first ? "single" : selectionLoading ? "loading" : "empty";

  useRaviScreenContext("scenarios", { selectedIds, total, loading, error, libraryTab,
    historyCount: visibleHistory.length,
    visibleHistory: libraryTab === "history" ? visibleHistory.map((revision, index) => ({ id: revision.id, createdAt: revision.createdAt, createdBy: revision.createdBy?.name, current: index === 0 })) : [],
    selected: selected.map((scenario) => ({ id: scenario.id, name: scenario.name, createdAt: scenario.createdAt, notes: scenario.notes,
      planRun: scenario.result.planRun ?? scenario.seed.activePlanRun, summary: scenario.result.summary })),
    firstOperational: firstInspection?.operational, secondOperational: secondInspection?.operational,
    firstMachineLoad: firstInspection?.machines, secondMachineLoad: secondInspection?.machines,
    detailMode, detailLoadingIds, detailError, selectionLoading,
    source: "saved-scenario", selectedStaleIds: selected.filter((scenario) => scenario.seed.planNeedsRecalculation).map((scenario) => scenario.id),
    editingScenarioId: editingScenario?.id });

  function handleLibraryTabKey(event: KeyboardEvent<HTMLButtonElement>) {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    event.preventDefault();
    const next: LibraryTab = event.key === "Home" ? "scenarios" : event.key === "End" ? "history" : libraryTab === "scenarios" ? "history" : "scenarios";
    setLibraryTab(next);
    (next === "scenarios" ? scenarioTabRef : historyTabRef).current?.focus();
  }

  async function requireScenario(id: string): Promise<StoredScenario> {
    const loaded = loadedScenarios.find((scenario) => scenario.id === id);
    if (loaded) return loaded;
    setDetailLoadingIds((current) => [...new Set([...current, id])]);
    setDetailError("");
    try {
      return await onFetchScenario(id);
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : "Senaryo ayrıntısı yüklenemedi.";
      setDetailError(message);
      throw caught;
    } finally {
      setDetailLoadingIds((current) => current.filter((item) => item !== id));
    }
  }

  async function toggle(id: string) {
    setDetailError("");
    if (selectedIds.includes(id)) {
      setSelectedIds((current) => current.filter((item) => item !== id));
      return;
    }
    setSelectedIds((current) => [...current.slice(-1), id]);
    try {
      await requireScenario(id);
    } catch {
      setSelectedIds((current) => current.filter((item) => item !== id));
    }
  }

  async function loadSelected(id: string) {
    try {
      onLoad(await requireScenario(id));
    } catch {
      // The inline error keeps the list usable and offers an immediate retry.
    }
  }

  async function editSelected(id: string) {
    try {
      setEditingScenario(await requireScenario(id));
    } catch {
      // The inline error keeps the list usable and offers an immediate retry.
    }
  }

  return (
    <section className="scenario-layout">
      <div className="scenario-list-panel">
        <div className="scenario-library-tabs" role="tablist" aria-label="Senaryolar ve versiyon geçmişi">
          <button id="scenario-library-tab" ref={scenarioTabRef} role="tab" aria-selected={libraryTab === "scenarios"} aria-controls="scenario-library-panel" tabIndex={libraryTab === "scenarios" ? 0 : -1} onKeyDown={handleLibraryTabKey} onClick={() => setLibraryTab("scenarios")}><ChartBar size={15} /> Senaryolar</button>
          <button id="scenario-history-tab" ref={historyTabRef} role="tab" aria-selected={libraryTab === "history"} aria-controls="scenario-history-panel" tabIndex={libraryTab === "history" ? 0 : -1} onKeyDown={handleLibraryTabKey} onClick={() => setLibraryTab("history")}><ClockCounterClockwise size={15} /> Versiyon geçmişi <b>{visibleHistory.length}</b></button>
        </div>
