linemedi.")); }} aria-label={`${scenario.name} senaryosunu sil`}><Trash size={15} /></button></div></article>; })}</div>{error && <div className="scenario-list-error" role="alert"><Warning size={14} weight="fill" /><span>{error}</span><button onClick={() => void onRetry()}>Yenile</button></div>}{scenarios.length < total && <button className="scenario-load-more" disabled={loading} onClick={() => void onLoadMore()}>{loading ? "Sonraki senaryolar getiriliyor…" : `Daha fazla göster · ${total - scenarios.length} kayıt kaldı`}</button>}</> : <div className="scenario-empty"><FloppyDisk size={25} /><strong>Henüz kayıtlı senaryo yok</strong><span>Planı çalıştırdıktan sonra “Senaryoyu Kaydet” düğmesini kullanın.</span></div>}
