            {visibleHistory.length ? <div className="version-history-panel">{visibleHistory.map((revision, index) => <article key={revision.id}><span><b>{formatFactoryDateTime(revision.createdAt)}</b><small>{revision.createdBy?.name ? `${revision.createdBy.name} · ` : ""}{(revision.seed.wipLots ?? []).filter((lot) => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped").length} açık yarı mamül</small></span><button className="secondary compact-button" disabled={index === 0} onClick={() => onRestoreRevision(revision)}>{index === 0 ? "Güncel" : "Geri yükle"}</button></article>)}</div> : <div className="scenario-empty"><ClockCounterClockwise size={25} /><strong>Henüz versiyon kaydı yok</strong><span>Plan değişiklikleri kaydedildikçe burada görünür.</span></div>}
          </div>
        </div>
