  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  async function submit() {
    if (!name.trim()) return;
    setSaving(true);
    setError("");
    try { await onSave(name, notes); }
