import type { PlanningSeed } from "../../../lib/planning";

type Provenance = { version: 1; id: string; name: string; baseline: string; modifiedOnLoad: boolean };
type IdentifiedSeed = PlanningSeed & { scenarioProvenance?: Provenance };

function canonical(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value)
    .filter(([key, item]) => key !== "scenarioProvenance" && item !== undefined)
    .sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => [key, canonical(item)]));
  return value;
}

// A content comparison token, never an identity or authorization token.
export function scenarioContentSignature(seed: PlanningSeed): string {
  const text = JSON.stringify(canonical(seed));
  const words = [2166136261, 3335557771, 2654435761, 1597334677];
  for (let i = 0; i < text.length; i++) for (let j = 0; j < words.length; j++) {
    words[j] = Math.imul(words[j] ^ text.charCodeAt(i), 16777619 + j * 2) >>> 0;
  }
  return words.map(word => word.toString(16).padStart(8, "0")).join("");
}

export function identifyScenario(seed: PlanningSeed, scenario: { id: string; name: string }, modifiedOnLoad = false, baselineSeed: PlanningSeed = seed): PlanningSeed {
  if (seed.productionArea === "cubuk-filtre") return seed;
  return { ...seed, scenarioProvenance: { version: 1, id: scenario.id, name: scenario.name,
    baseline: scenarioContentSignature(baselineSeed), modifiedOnLoad } } as IdentifiedSeed;
}

export function scenarioIdentity(seed: PlanningSeed): { id: string; name: string; modified: boolean } | null {
  if (seed.productionArea === "cubuk-filtre") return null;
  const value = (seed as IdentifiedSeed).scenarioProvenance;
  if (!value || value.version !== 1 || typeof value.id !== "string" || !value.id.trim()
    || typeof value.name !== "string" || !value.name.trim() || !/^[a-f0-9]{32}$/.test(value.baseline)
    || typeof value.modifiedOnLoad !== "boolean") return null;
  return { id: value.id, name: value.name, modified: value.modifiedOnLoad || value.baseline !== scenarioContentSignature(seed) };
}

