"use client";

import type { ApiFetch } from "@/lib/api";
import { assertProductionArea } from "@/lib/production-area";
import { useProductionArea } from "../shell/ProductionArea";
import { importedScenarios } from "@/lib/data-packages";
import type { StoredScenario } from "@/lib/planning";
import { type StoredScenarioSummary, SCENARIO_PAGE_SIZE, parseScenarioListPage, scenarioSummaryFromStored } from "@/lib/scenario-list";
import { useState } from "react";

export function useScenarioLibrary(apiFetch: ApiFetch, setNotice: (message: string) => void) {
  const area = useProductionArea();
  const [scenarios, setScenarios] = useState<StoredScenario[]>([]);
  const [scenarioSummaries, setScenarioSummaries] = useState<StoredScenarioSummary[]>([]);
  const [scenarioListTotal, setScenarioListTotal] = useState(0);
  const [scenarioListLoading, setScenarioListLoading] = useState(false);
  const [scenarioListError, setScenarioListError] = useState("");

  async function fetchScenarioPage(offset: number, replace = false) {
    setScenarioListLoading(true);
    setScenarioListError("");
    try {
      const response = await apiFetch(`/scenarios/list?limit=${SCENARIO_PAGE_SIZE}&offset=${Math.max(0, offset)}`);
      if (!response.ok) throw new Error("Kayıtlı senaryo listesi alınamadı.");
      const page = parseScenarioListPage(await response.json());
      setScenarioSummaries((current) => {
        const merged = new Map((replace ? [] : current).map((scenario) => [scenario.id, scenario]));
        page.items.forEach((scenario) => merged.set(scenario.id, scenario));
        return [...merged.values()].sort((left, right) => right.createdAt.localeCompare(left.createdAt));
      });
      setScenarioListTotal(page.total);
    } catch (error) {
      setScenarioListError(error instanceof Error ? error.message : "Kayıtlı senaryo listesi alınamadı.");
    } finally {
      setScenarioListLoading(false);
    }
  }

  async function fetchScenarioDetail(id: string): Promise<StoredScenario> {
    const cached = scenarios.find((scenario) => scenario.id === id);
    if (cached) return cached;
    const response = await apiFetch(`/scenarios/${encodeURIComponent(id)}`);
    if (!response.ok) throw new Error(response.status === 404 ? "Senaryo artık bulunmuyor. Listeyi yenileyin." : "Senaryo ayrıntısı yüklenemedi.");
    const scenario = await response.json() as StoredScenario;
    if (!scenario?.id || !scenario.seed || !scenario.result) throw new Error("Senaryo ayrıntısı eksik geldi.");
    setScenarios((current) => [scenario, ...current.filter((item) => item.id !== scenario.id)]);
    return scenario;
  }

  async function deleteStoredScenario(id: string) {
    const response = await apiFetch(`/scenarios/${encodeURIComponent(id)}`, { method: "DELETE" });
    if (!response.ok) throw new Error("Senaryo silinemedi.");
    setScenarios((current) => current.filter((scenario) => scenario.id !== id));
    setScenarioSummaries((current) => current.filter((scenario) => scenario.id !== id));
    setScenarioListTotal((current) => Math.max(0, current - 1));
    setNotice("Senaryo silindi");
  }

  async function updateStoredScenario(scenario: StoredScenario) {
    const response = await apiFetch("/scenarios", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(scenario) });
    if (!response.ok) throw new Error("Senaryo bilgileri kaydedilemedi.");
    setScenarios((current) => current.map((item) => item.id === scenario.id ? scenario : item));
    setScenarioSummaries((current) => current.map((item) => item.id === scenario.id ? scenarioSummaryFromStored(scenario) : item));
    setNotice(`${scenario.name} güncellendi`);
  }

  async function importStoredScenarios(raw: unknown) {
    const imported = importedScenarios(raw);
    imported.forEach(scenario => assertProductionArea(scenario.seed, area));
    const responses = await Promise.all(imported.map((scenario) => apiFetch("/scenarios", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(scenario) })));
    if (responses.some((response) => !response.ok)) throw new Error("Bazı senaryolar veritabanına kaydedilemedi.");
    setScenarios((current) => {
      const merged = new Map(current.map((scenario) => [scenario.id, scenario]));
      imported.forEach((scenario) => merged.set(scenario.id, scenario));
      return [...merged.values()].sort((left, right) => right.createdAt.localeCompare(left.createdAt));
    });
    await fetchScenarioPage(0, true);
    setNotice(`${imported.length} senaryo Excel paketinden yüklendi`);
  }

  async function addStoredScenario(scenario: StoredScenario) {
    const response = await apiFetch("/scenarios", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(scenario) });
    if (!response.ok) {
      setNotice("Senaryo kaydedilemedi");
      throw new Error("Senaryo veritabanına kaydedilemedi.");
    }
    setScenarios((current) => [scenario, ...current]);
  }

  function replaceScenarioLibrary(productionScenarios: StoredScenario[]) {
    setScenarios(productionScenarios);
    setScenarioSummaries(productionScenarios.map(scenarioSummaryFromStored).sort((left, right) => right.createdAt.localeCompare(left.createdAt)));
    setScenarioListTotal(productionScenarios.length);
    setScenarioListError("");
  }

  return {
    scenarios, scenarioSummaries, scenarioListTotal, scenarioListLoading, scenarioListError,
    fetchScenarioPage, fetchScenarioDetail, addStoredScenario, replaceScenarioLibrary,
    deleteStoredScenario, updateStoredScenario, importStoredScenarios,
  };
}

