import { areaStorageKey, type ProductionArea } from "@/lib/production-area";
import { inspectTurningQueue, reconcileTurningSeed } from "@/lib/turning-queue-identity";
import seedJson from "@/data/planning-seed.json";
import { inputDateToSerial } from "@/features/planning/shared/format";
import { clampShiftCount } from "@/features/planning/shared/production";
import { orderImportMetadataForSeed } from "@/lib/delivery-deduction";
import { factoryDateInput } from "@/lib/factory-time";
import {
  type PlanningSeed,
  type ScenarioResult,
  getSetupSettings,
  orderDeliveryMilestones,
  restoreScenarioFromBatches,
  scenarioResultFromBatches,
  rollForwardUnfinishedProduction,
} from "@/lib/planning";
import { type PlanningStateRecord } from "@/lib/planning-persistence";
import type { LocalDraftMeta } from "@/lib/planning-recovery";
import { migratePlanningSeed } from "@/lib/planning-state";
import { buildWeeklyPlanningState, previewFromDataset } from "@/lib/weekly-demand";

export const originalSeed = seedJson as PlanningSeed;

export const planningStateKey = "selsa-planlama-state-v1";

export const planningStateUpdatedAtKey = "selsa-planlama-state-v1-updated-at";

const machineCatalogNames: Record<string, string> = { "C-13": "CİTİZEN 32-2 DS", "C-14": "CİTİZEN 32-1 DS", "C-15": "CİTİZEN 32-3 DS", "C-16": "BENTRO", "C-17": "YALIN OTO" };

export function cloneSeed(seed: PlanningSeed): PlanningSeed {
  // A quarantined snapshot must retain its evidence exactly, including legacy
  // fields and past WIP dates. Even automatic normalization can change identity.
  if (inspectTurningQueue(seed).conflicts.length) return { ...structuredClone(seed), planNeedsRecalculation: true };
  const copy = migratePlanningSeed(seed);
  copy.orders = copy.orders.map((order) => {
    const normalized = { ...order, dueDate: order.dueDate ?? "", allowPartial: order.allowPartial ?? false, partialDeliveryQuantity: order.partialDeliveryQuantity ?? 0, partialDeliveryDate: order.partialDeliveryDate ?? "", deliveryMilestones: order.deliveryMilestones ?? [] };
    const milestones = orderDeliveryMilestones(normalized);
    return { ...normalized, deliveryMilestones: milestones, partialDeliveryQuantity: milestones[0]?.quantity ?? 0, partialDeliveryDate: milestones[0]?.date ?? "", allowPartial: milestones.length > 0 };
  });
  copy.orderCatalog = Array.isArray(copy.orderCatalog) ? [...new Set(copy.orderCatalog.map((product) => String(product).trim().toUpperCase()).filter(Boolean))] : undefined;
  copy.orderCatalogName = copy.orderCatalogName?.trim() || undefined;
  copy.products = copy.products.map((product) => ({ ...product, eligibleMachines: product.eligibleMachines ?? [], alternativeMachines: product.alternativeMachines ?? [] }));
  copy.machines = copy.machines.map((machine) => {
    const normalized = machine.capacityFactor == null && machine.shiftFactor > 0 && machine.shiftFactor < 1 ? { ...machine, capacityFactor: machine.shiftFactor, shiftFactor: 1 } : { ...machine, capacityFactor: machine.capacityFactor ?? 1 };
    const clean = (value: string) => value.trim().toLocaleLowerCase("tr-TR") === "none" ? "" : value;
    return { ...normalized, name: copy.machineCatalogVersion ? normalized.name : (machineCatalogNames[normalized.id] ?? normalized.name), currentJob: { ...normalized.currentJob, workOrder: clean(normalized.currentJob.workOrder), product: clean(normalized.currentJob.product), diameter: normalized.currentJob.diameter === "0" ? "" : normalized.currentJob.diameter, originalQuantity: normalized.currentJob.originalQuantity ?? normalized.currentJob.quantity, remainingQuantity: normalized.currentJob.remainingQuantity ?? normalized.currentJob.quantity } };
  });
  copy.machineCatalogVersion = 1;
  copy.setupSettings = getSetupSettings(copy);
  copy.manualBatches = (copy.manualBatches ?? []).map((batch) => {
    // Torna planı seçilen planlama aralığının kaydıdır. Önceki sürümlerin
    // ekran açılışında eklediği geçici "gecikmiş plan" işaretlerini temizle.
    const { rolledForwardFrom: _rolledForwardFrom, rolledForwardAt: _rolledForwardAt, ...plannedBatch } = batch;
    return { ...plannedBatch, locked: batch.locked ?? false, manuallyPlaced: batch.manuallyPlaced ?? false, workOrder: batch.workOrder ?? "" };
  });
  copy.productionHistory = copy.productionHistory ?? [];
  copy.wipLots = copy.wipLots ?? [];
  copy.wipMovements = copy.wipMovements ?? [];
  copy.chargeJourneyNotes = copy.chargeJourneyNotes ?? [];
  copy.orderImport = orderImportMetadataForSeed(copy) ?? undefined;
  copy.orderImportGrossOrders = copy.orderImport && !copy.customerDemand
    ? (copy.orderImportGrossOrders ?? copy.orders).map((order) => ({ ...order, deliveryMilestones: order.deliveryMilestones?.map((milestone) => ({ ...milestone })) }))
    : undefined;
  copy.planningEvents = copy.planningEvents ?? [];
  copy.holidays = (copy.holidays ?? []).map((holiday) => ({ ...holiday, workingShifts: clampShiftCount(holiday.workingShifts) }));
  copy.calendarEvents = (copy.calendarEvents ?? []).map((event) => ({ ...event, start: Math.floor(event.start), end: Math.max(Math.floor(event.start), Math.floor(event.end)), shiftCount: clampShiftCount(event.shiftCount) }));
  // Delme ve sonraki saha operasyonları canlı olarak bugüne taşınır. Torna
  // makinesi ve kayıtlı Gantt planı ise kullanıcının seçtiği aralıkta kalır.
  rollForwardUnfinishedProduction(copy, inputDateToSerial(factoryDateInput()), { turning: false });
  // A saved/prepared run already owns its net orders, deduction cutoff and
  // coarse/weekly deadline policy. Cloning an operational change must not
  // silently reconstruct gross Excel demand or replace those deadlines.
  if (copy.customerDemand && !copy.activePlanRun) {
    const importedAt = copy.customerDemand.importedAt;
    const demandState = buildWeeklyPlanningState(
      previewFromDataset(copy.customerDemand),
      copy.orders,
      copy.customerDemand.activeScope,
      copy.customerOrderOverrides,
      { includePriorBacklog: true },
    );
    copy.orders = demandState.orders;
    copy.orderCatalog = demandState.orderCatalog;
    copy.customerDemand = { ...demandState.dataset, importedAt };
    copy.openingStock = {};
  }
  try { return reconcileTurningSeed(copy); }
  catch { copy.planNeedsRecalculation = true; return copy; }
}

export function isPlanningSeed(value: unknown): value is PlanningSeed {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<PlanningSeed>;
  return Array.isArray(candidate.orders) && Array.isArray(candidate.products) && Array.isArray(candidate.machines) && Array.isArray(candidate.preferences);
}

/** Base revision and pending-save marker of the local copy (lib/planning-recovery.ts). */
export const planningStateMetaKey = "selsa-planlama-state-v1-meta";
/**
 * Recovery copies of local plans that a server copy replaced. Same key as the
 * former single slot: an old single copy is read as a list of one. Copies are
 * never evicted automatically; when the list is full a new replacement is
 * blocked until the planner downloads and explicitly clears them.
 */
export const planningRecoveryKey = "selsa-planlama-recovery-v1";
export const MAX_PLANNING_RECOVERY_COPIES = 5;

export function readLocalDraftMeta(area: ProductionArea = "torna"): LocalDraftMeta | null {
  try {
    const value = JSON.parse(window.localStorage.getItem(areaStorageKey(planningStateMetaKey, area)) ?? "null") as LocalDraftMeta | null;
    return value && value.version === 1 && typeof value.baseUpdatedAt === "string" && typeof value.pending === "boolean" ? value : null;
  } catch {
    return null;
  }
}

/** False when the browser refuses the write (quota or blocked storage). */
export function writeLocalDraftMeta(area: ProductionArea, meta: LocalDraftMeta): boolean {
  try { window.localStorage.setItem(areaStorageKey(planningStateMetaKey, area), JSON.stringify(meta)); return true; } catch { return false; }
}

export type PlanningRecoveryCopy = { version: 1; savedAt: string; reason: string; localUpdatedAt: string; baseUpdatedAt: string; remoteUpdatedAt: string; seed: PlanningSeed };

/**
 * Add a recovery copy. Returns false when storage refuses it or the bounded
 * list is full; the caller must then not replace the local copy. An identical
 * copy already kept counts as kept. Existing copies are never removed here.
 */
export function writePlanningRecoveryCopy(area: ProductionArea, copy: PlanningRecoveryCopy): boolean {
  try {
    const key = areaStorageKey(planningRecoveryKey, area);
    const raw = JSON.parse(window.localStorage.getItem(key) ?? "null") as unknown;
    const stored = raw && typeof raw === "object" && (raw as { version?: number }).version === 2 && Array.isArray((raw as { copies?: unknown }).copies)
      ? (raw as { copies: PlanningRecoveryCopy[] }).copies
      : raw && typeof raw === "object" && (raw as { version?: number }).version === 1 ? [raw as PlanningRecoveryCopy] : [];
    const seedText = JSON.stringify(copy.seed);
    if (stored.some(item => JSON.stringify(item.seed) === seedText)) return true;
    if (stored.length >= 5) return false; // MAX_PLANNING_RECOVERY_COPIES; no automatic eviction
    window.localStorage.setItem(key, JSON.stringify({ version: 2, copies: [...stored, copy] }));
    return true;
  } catch {
    return false;
  }
}

/** All retained recovery copies, oldest first (legacy single copy included). */
export function readPlanningRecoveryCopies(area: ProductionArea = "torna"): PlanningRecoveryCopy[] {
  try {
    const raw = JSON.parse(window.localStorage.getItem(areaStorageKey(planningRecoveryKey, area)) ?? "null") as unknown;
    const list = raw && typeof raw === "object" && (raw as { version?: number }).version === 2 && Array.isArray((raw as { copies?: unknown }).copies)
      ? (raw as { copies: PlanningRecoveryCopy[] }).copies
      : raw && typeof raw === "object" && (raw as { version?: number }).version === 1 ? [raw as PlanningRecoveryCopy] : [];
    return list.filter(item => item && item.version === 1 && isPlanningSeed(item.seed));
  } catch {
    return [];
  }
}

/** Latest retained copy (compatibility with the former single slot). */
export function readPlanningRecoveryCopy(area: ProductionArea = "torna"): PlanningRecoveryCopy | null {
  try {
    const raw = JSON.parse(window.localStorage.getItem(areaStorageKey(planningRecoveryKey, area)) ?? "null") as unknown;
    const list = raw && typeof raw === "object" && (raw as { version?: number }).version === 2 && Array.isArray((raw as { copies?: unknown }).copies)
      ? (raw as { copies: PlanningRecoveryCopy[] }).copies
      : raw && typeof raw === "object" && (raw as { version?: number }).version === 1 ? [raw as PlanningRecoveryCopy] : [];
    const valid = list.filter(item => item && item.version === 1 && isPlanningSeed(item.seed));
    return valid.at(-1) ?? null;
  } catch {
    return null;
  }
}

/** Explicit planner action after download only. Returns false if storage refused it. */
export function clearPlanningRecoveryCopies(area: ProductionArea, expectedCount: number): boolean {
  try {
    if (readPlanningRecoveryCopies(area).length !== expectedCount) return false; // changed since download
    window.localStorage.removeItem(areaStorageKey(planningRecoveryKey, area));
    return true;
  } catch {
    return false;
  }
}

export function readLocalPlanningState(area: ProductionArea = "torna"): PlanningStateRecord | null {
  try {
    const value = window.localStorage.getItem(areaStorageKey(planningStateKey, area));
    if (!value) return null;
    const parsed: unknown = JSON.parse(value);
    return isPlanningSeed(parsed) ? { seed: parsed, updatedAt: window.localStorage.getItem(areaStorageKey(planningStateUpdatedAtKey, area)) ?? "" } : null;
  } catch {
    return null;
  }
}

export function restoreManualResult(seed: PlanningSeed): ScenarioResult | null {
  if (!seed.manualBatches?.length) return null;
  try {
    return restoreScenarioFromBatches(seed, seed.manualBatches);
  } catch {
    // Keep an invalid saved queue visible for review, never replace it with an
    // empty plan that a later unrelated edit could persist. Writes still validate.
    seed.planNeedsRecalculation = true;
    return scenarioResultFromBatches(seed, seed.manualBatches);
  }
}

export function createEmptyResult(seed: PlanningSeed): ScenarioResult {
  const demand = seed.orders.reduce((sum, order) => sum + order.quantity, 0);
  return {
    state: "empty",
    batches: [],
    orders: seed.orders.map((order) => ({ ...order, planned: 0, difference: 0, existingProduction: 0, newlyPlanned: 0, onTimePlanned: null, onTimeDifference: null, assignedMachines: [] })),
    createdAt: new Date().toISOString(),
    planRun: seed.activePlanRun,
    summary: {
      demand,
      planned: 0,
      shortage: demand,
      overproduction: 0,
      plannedBatchCount: 0,
      unplannedBatchCount: 0,
      totalSetupHours: 0,
      completion: 0,
      machinesUsed: 0,
    },
  };
}

export function cloneResult(result: ScenarioResult): ScenarioResult { return JSON.parse(JSON.stringify(result)) as ScenarioResult; }

