import { replaceTurningCurrentJob } from "@/lib/production-interruption-actions";
import { setMachineAvailability } from "@/lib/machine-management";
import type { ProductionInterruptionInput } from "@/lib/production-interruptions";
import { assertArchiveEntry, correctArchiveRecord, restoreArchiveDelivery } from "@/lib/archive-corrections";
import { completeWipDelivery, assertWipActionSnapshot, type WipManualActionInput, type WipDeliveryActionInput } from "@/lib/wip-manual-actions";
import { type ChargeJourneyNoteInput, saveChargeJourneyNote } from "@/lib/charge-journey-notes";
import { factoryDateInput, factoryNowSerial } from "@/lib/factory-time";
import { processLabel, type DownstreamProcess } from "@/lib/process-master-data";
import { formatInteger as formatNumber } from "@/lib/number-format";
import {
  type CurrentJobInput,
  type PlanningEvent,
  type PlanningSeed,
  type ProductionHistoryAllocationInput,
  type ProductionInventoryStatus,
  type ScenarioResult,
  type WipStage,
  allocateProductionHistoryEntry,
  completeMachineCurrentJob,
  updateMachineCurrentJob,
  updateProductionHistoryStatus,
} from "@/lib/planning";
import {
  type ProcessCurrentJobInput,
  completeProcessCurrentJob,
  replaceProcessCurrentJob,
  startProcessCurrentJob,
  updateProcessCurrentJob,
  resetDownstreamProcessPlan,
  previewProcessQueuePlacement, type ProcessQueuePlacementRequest,
  previewProcessOperationReschedule, processPlacementSignature, type ProcessOperation,
} from "@/lib/process-planning";
import {
  type WipOperationInput,
  applyHistoryAllocationToWip,
  applyHistoryStatusToWip,
  completeWipOperation,
  correctWipStage,
  registerTurningCompletion,
  releaseWipHold,
  releaseWipBuffer,
} from "@/lib/wip-ledger";
import { inputDateToSerial } from "../shared/format";
import { cloneSeed } from "./planning-state";

type ProductionActionContext = {
  seed: PlanningSeed;
  result: ScenarioResult;
  commitOperationalChange: (seed: PlanningSeed, result: ScenarioResult, message: string, event?: Omit<PlanningEvent, "id" | "createdAt">, undoMessage?: string) => void;
  setOperationAlert: (alert: { id: number; message: string }) => void;
  setDirty: (dirty: boolean) => void;
  dirty?: boolean;
};

/** Commands use the current render's state; committing remains the coordinator's responsibility. */
export function createProductionActions({ seed, result, commitOperationalChange: commit, setOperationAlert, setDirty, dirty = false }: ProductionActionContext) {
  const commitOperationalChange: ProductionActionContext["commitOperationalChange"] = (nextSeed, nextResult, message, event, undoMessage) => {
    nextSeed.planNeedsRecalculation = Boolean(nextSeed.planNeedsRecalculation || dirty || event?.type === "archive-status");
    commit(nextSeed, nextResult, message, event, undoMessage);
  };
  function saveMachineAvailability(machineId: string, start: number) {
    try {
      const next = cloneSeed(seed);
      setMachineAvailability(next, machineId, start);
      commitOperationalChange(next, result, `${machineId} müsait başlangıcı kaydedildi · planı yeniden çalıştırın`, undefined, "Müsait başlangıç değişikliği geri alınabilir");
    } catch (error) {
      setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Müsait başlangıç kaydedilemedi." });
    }
  }
  function rescheduleDownstreamOperation(operationId: string, resourceId: string, requestedStart: number, reviewedSignature: string): ProcessOperation {
    const preview = previewProcessOperationReschedule(seed, result, operationId, resourceId, requestedStart);
    if (processPlacementSignature(preview) !== reviewedSignature) throw new Error("Plan değişti. Güncel yerleşimi yeniden inceleyip onaylayın.");
    const moved = preview.operation;
    commitOperationalChange(preview.seed, result, `${processLabel(moved.process)} · ${moved.product} · ${resourceId} yerleşimi uygulandı`,
      { type: "wip", machineId: resourceId, message: `${moved.workOrder || moved.product} · ${processLabel(moved.process)} Gantt yerleşimi güncellendi.` },
      "Proses taşıması geri alınabilir");
    if (dirty) setDirty(true);
    return moved;
  }
  function placeDownstreamQueueOperation(request: ProcessQueuePlacementRequest, reviewedSignature: string): ProcessOperation {
    const preview = previewProcessQueuePlacement(seed, result, request);
    if (processPlacementSignature(preview) !== reviewedSignature) throw new Error("Kuyruk veya plan değişti. Güncel yerleşimi yeniden inceleyip onaylayın.");
    if (preview.seed === seed) return preview.operation;
    const moved = preview.operation;
    commitOperationalChange(preview.seed, result, `${processLabel(moved.process)} · ${moved.workOrder || moved.product} · ${moved.resourceId} kuyruğu güncellendi`,
      { type: "wip", machineId: moved.resourceId, message: `${moved.workOrder || moved.product} · ${processLabel(moved.process)} ${preview.insertionIndex + 1}. sıraya yerleştirildi.` }, "Proses kuyruk değişikliği geri alınabilir");
    if (dirty) setDirty(true);
    return moved;
  }
  function replanDownstreamProcess(process: DownstreamProcess): boolean {
    try {
      const next = resetDownstreamProcessPlan(seed, result, process);
      commitOperationalChange(next.seed, result, `${processLabel(process)} otomatik planı güncellendi · Torna planı korundu`,
        { type: "wip", message: `${processLabel(process)} kuyrukları otomatik planlandı; çalışan işler ve Torna planı korundu.` },
        `${processLabel(process)} planlaması geri alınabilir`);
      if (dirty) setDirty(true);
      return true;
    } catch (error) {
      setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Proses planlanamadı." });
      return false;
    }
  }
  function saveCurrentJob(machineId: string, input: CurrentJobInput, remainingAsOf: number) {
    try {
      const next = updateMachineCurrentJob(seed, result, machineId, input, remainingAsOf);
      next.seed.lastAutomaticPlan = undefined;
      commitOperationalChange(next.seed, next.result, `${machineId} mevcut işi güncellendi`, { type: "current-job", machineId, message: `${machineId} mevcut işi ${input.product} olarak güncellendi.` });
    } catch (error) {
      throw error instanceof Error ? error : new Error("Mevcut iş güncellenemedi.");
    }
  }

  function replaceTurningJob(machineId: string, batchId: string, input: ProductionInterruptionInput) {
    const next = replaceTurningCurrentJob(seed, result, machineId, batchId, input, factoryNowSerial());
    const label = input.produced ? input.kind === "partial-completion" ? "Kısmi üretim tamamlandı." : "Üretime ara verildi." : "İş kuyruğa döndü.";
    commitOperationalChange(next.seed, next.result, `Mevcut iş değiştirildi · ${label}`, {type:"current-job",machineId,message:`${label} ${input.produced ? `${input.quantity} adet üretildi. ${input.reason?.trim()}` : "Üretim yapılmadı."}`}, "Mevcut iş değişikliği geri alınabilir");
    setDirty(true);
  }

  function completeCurrentJob(machineId: string, completedAt: number, completedQuantity?: number) {
    const next = completeMachineCurrentJob(seed, result, machineId, completedAt, completedQuantity);
    const lot = registerTurningCompletion(next.seed, next.archived);
    if (next.archived.interruptionIds?.length && !lot) throw new Error("Kısmi üretimin yarı mamül kaydı oluşturulamadı; ürün rotasını kontrol edin.");
    next.seed.lastAutomaticPlan = undefined;
    const promotion = next.promotedBatch ? `; ${next.promotedBatch.product} üretime alındı` : "; sırada yeni iş yok";
    commitOperationalChange(next.seed, next.result, `${next.archived.product} tamamlandı${promotion}`, { type: "complete", machineId, message: `${next.archived.workOrder || next.archived.product} tamamlandı ve arşive alındı${promotion}.` });
  }

  function changeProductionHistoryStatus(entryId: string, inventoryStatus: ProductionInventoryStatus, actionDate = "", reason = "") {
    const source = (seed.productionHistory ?? []).find((entry) => entry.id === entryId);
    if (!source) {
      throw new Error("Üretim arşivi kaydı bulunamadı.");
    }
    try {
      const changedAt = new Date().toISOString();
      const next = updateProductionHistoryStatus(seed, result, entryId, inventoryStatus, actionDate, changedAt, reason);
      const occurredAt = actionDate ? inputDateToSerial(actionDate.slice(0, 10)) : source.completedAt;
      applyHistoryStatusToWip(next.seed, source, inventoryStatus, occurredAt, changedAt, reason);
      next.seed.lastAutomaticPlan = undefined;
      next.seed.planRunSequence = undefined;
      const action = inventoryStatus === "delivered"
        ? `${source.product} teslim edildi`
        : inventoryStatus === "semi-finished"
            ? `${source.product} yarı mamule geri alındı${reason.trim() ? ` · ${reason.trim()}` : ""}`
          : inventoryStatus === "scrapped"
            ? `${source.product} ıskartaya ayrıldı`
            : `${source.product} arşiv kaydı iptal edildi`;
      commitOperationalChange(
        next.seed,
        next.result,
        `${action} · planı yeniden çalıştırın`,
        { type: "archive-status", machineId: source.machineId, message: `${action}.` },
        "Arşiv durum değişikliği geri alınabilir",
      );
      setDirty(true);
    } catch (error) {
      throw error instanceof Error ? error : new Error("Arşiv durumu güncellenemedi.");
    }
  }

  function restoreProductionDelivery(entryId: string, reason: string, expected?: string): boolean {
    const next = restoreArchiveDelivery(seed, result, entryId, reason, expected);
    commitOperationalChange(next.seed, next.result, "Teslimat geri alındı · Paketleme / Final Kontrol’e döndü · planı yeniden çalıştırın", { type: "archive-status", message: `Teslimat geri alındı: ${reason.trim()}` }, "Teslimatı geri alma işlemi geri alınabilir");
    setDirty(true);
    return true;
  }

  function editProductionHistoryEntry(entryId: string, actualQuantity: number, completedAt: number, deliveryDate?: string, expected?: string, correctionLotId?: string): boolean {
    const source = assertArchiveEntry(seed, entryId, expected);
    const next = correctArchiveRecord(seed, result, entryId, actualQuantity, completedAt, deliveryDate, expected, correctionLotId);
    commitOperationalChange(next.seed, next.result, `${source.product} arşiv kaydı güncellendi · planı yeniden çalıştırın`, { type: "archive-status", machineId: source.machineId, message: `${source.product} · ${formatNumber(actualQuantity)} adet · ${next.entry.statusChangeReason || "Fiili üretim düzeltildi"}.` }, "Arşiv düzenlemesi geri alınabilir");
    setDirty(true);
    return true;
  }

  function allocateProductionHistory(entryId: string, input: ProductionHistoryAllocationInput, expected?: string, correctionLotId?: string): boolean {
    const source = assertArchiveEntry(seed, entryId, expected);
    const corrected = correctArchiveRecord(seed, result, entryId, input.actualQuantity, input.completedAt, undefined, expected, correctionLotId);
    if (input.deliveredQuantity === 0 && input.remainderAction === "keep") return editProductionHistoryEntry(entryId, input.actualQuantity, input.completedAt, undefined, expected, correctionLotId);
    const actualInput = { ...input, completedAt: corrected.entry.completedAt };
    const next = allocateProductionHistoryEntry(corrected.seed, corrected.result, entryId, actualInput, undefined, (nextSeed, entries) => {
      applyHistoryAllocationToWip(nextSeed, corrected.entry, actualInput, undefined, entries.find(entry => entry.inventoryStatus === "delivered")?.id);
    });
    next.seed.lastAutomaticPlan = undefined;
    next.seed.planRunSequence = undefined;
    const remainder = input.actualQuantity - input.deliveredQuantity;
    const detail = remainder > 0 ? `; ${formatNumber(remainder)} adet ${input.remainderAction === "scrap" ? "ıskartaya ayrıldı" : "yarı mamulde kaldı"}` : "";
    commitOperationalChange(next.seed, next.result, `${source.product} teslimatı kaydedildi · planı yeniden çalıştırın`, { type: "archive-status", machineId: source.machineId, message: `${formatNumber(input.deliveredQuantity)} adet teslim edildi${detail}.` }, "Teslimat ayrıştırması geri alınabilir");
    setDirty(true);
    return true;
  }

  function deliverJourneyWip(input: WipDeliveryActionInput): void {
    const now = new Date().toISOString();
    const next = completeWipDelivery(seed, result, input, factoryNowSerial(), now);
    commitOperationalChange(next.seed, next.result, "Teslimat kaydedildi · planı yeniden çalıştırın",
      { type: "archive-status", message: input.allocation ? `${input.allocation.deliveredQuantity} adet teslim edildi; ${input.allocation.actualQuantity - input.allocation.deliveredQuantity} adet ${input.allocation.remainderAction === "scrap" ? "ıskartaya ayrıldı" : "yarı mamulde kaldı"}.` : `${input.quantity} adet teslim edildi; proses kontrol ve paketleme onaylandı.` }, "Teslimat geri alınabilir");
    setDirty(true);
  }

  function releaseJourneyBuffer(input: WipManualActionInput): void {
    assertWipActionSnapshot(seed, input);
    const nextSeed = cloneSeed(seed);
    const lot = releaseWipBuffer(nextSeed, input.lotId, factoryNowSerial(), input.confirmed);
    commitOperationalChange(nextSeed, result, `${lot.workOrder || lot.product} beklemesi tamamlandı`,
      { type: "wip", message: `${lot.workOrder || lot.product} için kontrol onayıyla bekleme tamamlandı.` }, "Bekleme onayı geri alınabilir");
    if (dirty) setDirty(true);
  }

  function finishWipOperation(input: WipOperationInput) {
    try {
      const nextSeed = cloneSeed(seed);
      const current = (nextSeed.processCurrentJobs ?? []).find((job) => job.wipLotId === input.lotId && job.process === input.process);
      const completed = current
        ? (() => {
            completeProcessCurrentJob(nextSeed, result, current.resourceId, input.completedAt, input.quantity, input.resourceId, input.remainderAction, input.confirmedBuffer, input.countCorrectionReason);
            return (nextSeed.wipLots ?? []).find((lot) => lot.id === input.lotId) ?? (nextSeed.wipLots ?? []).find((lot) => lot.parentLotId === input.lotId)!;
          })()
        : completeWipOperation(nextSeed, input).completed;
      if (input.remainderAction === "scrap") nextSeed.planNeedsRecalculation = true;
      commitOperationalChange(
        nextSeed,
        result,
        `${completed.workOrder || completed.product} · ${input.process} tamamlandı`,
        { type: "wip", machineId: input.resourceId, message: `${completed.workOrder || completed.product} için ${formatNumber(input.quantity)} adet ${input.process} tamamlandı.` },
        "Yarı mamül operasyonu geri alınabilir",
      );
      return true;
    } catch (error) {
      setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Yarı mamül operasyonu tamamlanamadı." });
      return false;
    }
  }

  function beginDownstreamCurrentJob(operationId: string, confirmedInterruption = false) {
    try {
      const nextSeed = cloneSeed(seed);
      const current = startProcessCurrentJob(nextSeed, result, operationId, factoryNowSerial(), confirmedInterruption);
      commitOperationalChange(
        nextSeed,
        result,
        `${current.resourceId} · ${current.product} mevcut üretime alındı`,
        { type: "wip", machineId: current.resourceId, message: `${current.workOrder || current.product}, ${current.resourceId} üzerinde mevcut üretime alındı.` },
        "Mevcut işe alma işlemi geri alınabilir",
      );
    } catch (error) {
      throw error instanceof Error ? error : new Error("Downstream işi mevcut üretime alınamadı.");
    }
  }

  function replaceDownstreamCurrentJob(resourceId: string, operationId: string, input: ProductionInterruptionInput, confirmedInterruption = false) {
    try {
      const nextSeed = structuredClone(seed);
      const outcome = replaceProcessCurrentJob(nextSeed, result, resourceId, operationId, factoryNowSerial(), input, confirmedInterruption);
      nextSeed.planNeedsRecalculation = true;
      commitOperationalChange(
        nextSeed,
        result,
        `${resourceId} mevcut işi ${outcome.current.workOrder || outcome.current.product} olarak değiştirildi`,
        { type: "wip", machineId: resourceId, message: `${outcome.current.workOrder || outcome.current.product} mevcut üretime alındı; ${outcome.queued.workOrder || outcome.queued.product} kuyruğun ilk sırasına taşındı.` },
        "Mevcut iş değişikliği geri alınabilir",
      );
    } catch (error) {
      throw error instanceof Error ? error : new Error("Downstream mevcut işi değiştirilemedi.");
    }
  }

  function saveDownstreamCurrentJob(resourceId: string, input: ProcessCurrentJobInput) {
    try {
      const nextSeed = cloneSeed(seed);
      const current = updateProcessCurrentJob(nextSeed, resourceId, input);
      commitOperationalChange(
        nextSeed,
        result,
        `${resourceId} mevcut işi güncellendi`,
        { type: "wip", machineId: resourceId, message: `${current.workOrder || current.product}, ${resourceId} üzerinde güncellendi.` },
        "Mevcut iş düzenlemesi geri alınabilir",
      );
    } catch (error) {
      throw error instanceof Error ? error : new Error("Downstream mevcut işi güncellenemedi.");
    }
  }

  function finishDownstreamCurrentJob(resourceId: string, completedAt: number, completedQuantity?: number, actualResourceId?: string, remainderAction?: "keep" | "scrap", confirmedBuffer = false, countCorrectionReason?: string) {
    try {
      const nextSeed = cloneSeed(seed);
      const outcome = completeProcessCurrentJob(nextSeed, result, resourceId, completedAt, completedQuantity, actualResourceId, remainderAction, confirmedBuffer, countCorrectionReason);
      if (remainderAction === "scrap") nextSeed.planNeedsRecalculation = true;
      const promotion = outcome.promoted ? `; ${outcome.promoted.product} mevcut üretime alındı` : "; sırada hazır yarı mamül yok";
      commitOperationalChange(
        nextSeed,
        result,
        `${resourceId} · ${outcome.completedProduct} tamamlandı${promotion}`,
        { type: "wip", machineId: outcome.completedResourceId, message: `${outcome.completedWorkOrder || outcome.completedProduct}, ${outcome.completedResourceId} üzerinde tamamlandı${promotion}.` },
        "Downstream tamamlama işlemi geri alınabilir",
      );
    } catch (error) {
      throw error instanceof Error ? error : new Error("Downstream mevcut işi tamamlanamadı.");
    }
  }

  function changeWipStage(lotId: string, stage: WipStage, occurredAt: number) {
    try {
      const nextSeed = cloneSeed(seed);
      const lot = stage === "on-hold"
        ? correctWipStage(nextSeed, lotId, stage, occurredAt)
        : correctWipStage(nextSeed, lotId, stage, occurredAt);
      commitOperationalChange(nextSeed, result, `${lot.workOrder || lot.product} yarı mamül konumu güncellendi`, { type: "wip", message: `${lot.workOrder || lot.product} konumu ${stage} olarak güncellendi.` }, "Yarı mamül konum değişikliği geri alınabilir");
    } catch (error) {
      setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Yarı mamül konumu güncellenemedi." });
    }
  }

  function releaseHeldWip(lotId: string, occurredAt: number) {
    try {
      const nextSeed = cloneSeed(seed);
      const lot = releaseWipHold(nextSeed, lotId, occurredAt);
      commitOperationalChange(nextSeed, result, `${lot.workOrder || lot.product} blokesi kaldırıldı`, { type: "wip", message: `${lot.workOrder || lot.product} yarı mamül blokesi kaldırıldı.` }, "Bloke kaldırma işlemi geri alınabilir");
    } catch (error) {
      setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Yarı mamül blokesi kaldırılamadı." });
    }
  }

  function saveJourneyNote(input: ChargeJourneyNoteInput) {
    try {
      const nextSeed = cloneSeed(seed);
      const saved = saveChargeJourneyNote(nextSeed, input);
      commitOperationalChange(
        nextSeed,
        result,
        saved ? "Şarj yolculuğu açıklaması kaydedildi" : "Şarj yolculuğu açıklaması kaldırıldı",
        { type: "wip", message: `${input.chargeKey} · ${input.kind === "delay" ? "gecikme" : "bekleme"} açıklaması ${saved ? "kaydedildi" : "kaldırıldı"}.` },
        "Şarj yolculuğu açıklaması geri alınabilir",
      );
    } catch (error) {
      setOperationAlert({ id: Date.now(), message: error instanceof Error ? error.message : "Şarj yolculuğu açıklaması kaydedilemedi." });
    }
  }

  return {
    saveMachineAvailability,
    rescheduleDownstreamOperation,
    placeDownstreamQueueOperation,
    replanDownstreamProcess,
    replaceTurningJob,
    saveCurrentJob,
    completeCurrentJob,
    changeProductionHistoryStatus,
    editProductionHistoryEntry,
    restoreProductionDelivery,
    allocateProductionHistory,
    finishWipOperation,
    deliverJourneyWip,
    releaseJourneyBuffer,
    beginDownstreamCurrentJob,
    replaceDownstreamCurrentJob,
    saveDownstreamCurrentJob,
    finishDownstreamCurrentJob,
    changeWipStage,
    releaseHeldWip,
    saveJourneyNote,
  };
}

