import type { PlanningSeed } from "@/lib/planning";
import { effectiveWaitSources } from "@/lib/flow-settings";
import { processLabel } from "@/lib/process-master-data";

export function EffectiveWaitSourcesTable({ seed }: { seed: PlanningSeed }) {
  const rows = effectiveWaitSources(seed);
