frontend/features/planning/settings/Proc.source:
"use client";
import { useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import type { PlanningSeed } from "@/lib/planning";
import { processLabel } from "@/lib/process-master-data";
import { defaultProcessWaitSettings, validateProcessWaitSettings, WAIT_PROCESSES } from "@/lib/process-waits";
import { effectiveWaitSources, legacyWashingRules } from "@/lib/flow-settings";
import { ProcessIcon } from "@/components/ProcessIcon";

export function ProcessWaitSettingsPanel({ seed, updatePlanningInputs, active = true }: {
  active?: boolean;
  seed: PlanningSeed; updatePlanningInputs: (mutator: (seed: PlanningSeed) => void) => void | boolean;
}) {
  const saved = JSON.stringify(seed.processWaitSettings ?? defaultProcessWaitSettings());
  const [baseline, setBaseline] = useState(saved);
  const [draft, setDraft] = useState(() => structuredClone(seed.processWaitSettings ?? defaultProcessWaitSettings()));
  const [error, setError] = useState("");
  const stale = baseline !== saved;
  useRaviScreenContext("process-waits", { effectiveWaitSources: effectiveWaitSources(seed), hasLegacyWashing: seed.productionArea !== "cubuk-filtre" && legacyWashingRules(seed.flowSettings).length > 0, section: "Proses bekleme süreleri", saved: seed.processWaitSettings ?? defaultProcessWaitSettings(), draft, stale, error, units: "factory-workdays", appliesAfterProcess: true }, active);
  function reload() {
    setDraft(structuredClone(seed.processWaitSettings ?? defaultProcessWaitSettings()));
    setBaseline(saved); setError("");
  }
  function save() {
    try {
      if (stale) throw Error("Ortak ayarlar değişti. Güncel ayarları yükleyin.");
      const settings = validateProcessWaitSettings(draft);
      if (updatePlanningInputs(next => { next.processWaitSettings = settings; }) === false) throw Error("Bekleme değişikliği uygulanmadı. Üst çubuktaki kayıt durumunu kontrol edin.");
      setBaseline(JSON.stringify(settings)); setError("");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Bekleme süreleri kaydedilemedi."); }
  }
  return <div className="data-surface process-wait-settings" id="ravi-process-waits">
    <h3>Proses bekleme süreleri</h3>
    {seed.productionArea !== "cubuk-filtre" && seed.flowSettings?.enabled && <p>Akış Ayarı açıkken tanımlı geçişte saat kuralı geçerlidir; iş günü beklemesi yalnız kuralı olmayan geçişlerde kullanılır.</p>}
    <p>Bekleme, proses tamamlandıktan sonra başlar. Bekleme yoksa sonraki proses kapasite uygun olduğunda başlayabilir.</p>
    <p>Süreler tam iş günüdür. Pazar ve çalışılmayan tatiller sayılmaz. GKM sonrası süre Paketleme / Final Kontrol içindir.</p>
    <div className="table-scroll"><table><thead><tr><th>Proses sonrası</th><th>Bekleme var</th><th>Bekleme süresi (iş günü)</th></tr></thead><tbody>{WAIT_PROCESSES.map(process => <tr key={process}>
      <th><ProcessIcon process={process} size={16} /> {processLabel(process)}</th>
      <td><input type="checkbox" aria-label={`${processLabel(process)} sonrası bekleme var`} checked={draft[process].enabled} onChange={event => setDraft({ ...draft, [process]: { ...draft[process], enabled: event.target.checked } })} /></td>
      <td><input type="number" min="0" max="365" step="1" disabled={!draft[process].enabled} aria-label={`${processLabel(process)} sonrası bekleme süresi (iş günü)`} value={Number.isNaN(draft[process].workdays) ? "" : draft[process].workdays} onChange={event => setDraft({ ...draft, [process]: { ...draft[process], workdays: event.target.value === "" ? NaN : Number(event.target.value) } })} /></td>
    </tr>)}</tbody></table></div>
    <p>Kayıtlı kuyruk, mevcut üretim ve tamamlanan prosesler korunur. Yeni bekleme süreleri yeni hesaplara ve yeni tamamlanan proseslere uygulanır. Kayıtlı yarı mamulün hazır olma tarihi değişmez. Planı yeniden çalıştırın.</p>
    {stale && <p role="status">Ortak ayarlar değişti. Güncel ayarları yükleyin.</p>}
    {error && <p role="alert">{error}</p>}
    <button className="secondary" onClick={reload}>Güncel ayarları yükle</button>{" "}<button className="primary" disabled={stale || !!seed.processWaitSettings && JSON.stringify(draft) === saved} onClick={save}>Bekleme sürelerini kaydet</button>
  </div>;
}

frontend/features/planning/settings/Prod.source:
"use client";

import { useEffect, useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import type { PlanningSeed } from "@/lib/planning";
import { validateProductWeights, type ProductWeight } from "@/lib/product-weights";
import { initialRawMaterialSettings, validateRawMaterialSettings } from "@/lib/raw-material-settings";

export function ProductWeights({ seed, updateSeed, readOnly = false, productCodes }: { readOnly?: boolean; productCodes?: Set<string>; seed: PlanningSeed; updateSeed: (mutator: (seed: PlanningSeed) => void) => void }) {
  const [query, setQuery] = useState("");
  const [editing, setEditing] = useState<ProductWeight | null>(null);
  const [originalCode, setOriginalCode] = useState<string | null>(null);
  const [amount, setAmount] = useState("");
  const [error, setError] = useState("");
  const settings = seed.rawMaterialSettings ?? initialRawMaterialSettings();
  const [scrap, setScrap] = useState(String(settings.scrapPercent).replace(".", ","));
  const [scrapError, setScrapError] = useState("");
  useEffect(() => setScrap(String(settings.scrapPercent).replace(".", ",")), [settings.scrapPercent]);
  const rows = seed.productWeights ?? [];
  const scopedRows = productCodes ? rows.filter(row => productCodes.has(row.product)) : rows;
  const visible = scopedRows.filter((row) => `${row.product} ${row.productName} ${row.materialCode} ${row.materialName}`.toLocaleLowerCase("tr-TR").includes(query.toLocaleLowerCase("tr-TR")));
  useRaviScreenContext("product-weights", { query, visibleCount: visible.length, totalCount: rows.length, visibleWeights: visible.slice(0, 12), selectedProduct: editing?.product, draftProduct: editing, draftGrams: amount, scrapPercent: settings.scrapPercent, draftScrapPercent: scrap, unit: "g", sourceSheet: seed.productionArea === "cubuk-filtre" ? "01_URUNLER → Brüt Ağırlık gr (adet)" : "ÜRÜN AĞIRLIKLARI" });
  function save() {
    if (!editing || readOnly) return;
    try {
      const grams = amount.trim() ? Number(amount.trim().replace(",", ".")) : null;
      const updated = { ...editing, product: editing.product.trim().toUpperCase(), grams };
      if (originalCode === null && rows.some((row) => row.product === updated.product)) throw new Error("Bu ürün zaten var; mevcut satırdaki Düzenle düğmesini kullanın.");
      const next = rows.some((row) => row.product === updated.product) ? rows.map((row) => row.product === updated.product ? updated : row) : [...rows, updated];
      validateProductWeights(next);
      updateSeed((draft) => { draft.productWeights = next; });
      setEditing(null); setError("");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Ağırlık kaydedilemedi."); }
  }
  return <section className="calendar-section product-weights-section">
    <div className="calendar-section-title"><div><h3>Ürün Ağırlıkları</h3><p>Excel’deki hammadde miktarları, gram cinsinden. Kaynak: {seed.productionArea === "cubuk-filtre" ? "01_URUNLER → Brüt Ağırlık gr (adet)" : "ÜRÜN AĞIRLIKLARI → Miktar / Hm. Birim"}.</p><p>İlk aktarım bir kez yapılır; burada kaydettiğiniz değerler korunur. Ağırlığı bilinmeyen ürünü boş bırakabilirsiniz.</p></div>
      {seed.productionArea !== "cubuk-filtre" && <form className="material-scrap-form" onSubmit={(event) => {
        event.preventDefault();
        if (readOnly) return;
        try {
          if (!scrap.trim()) throw new Error("Iskarta oranını girin.");
          const next = validateRawMaterialSettings({ ...settings, scrapPercent: Number(scrap.replace(",", ".")) });
          updateSeed((draft) => { draft.rawMaterialSettings = next; }); setScrapError("");
        } catch (reason) { setScrapError(reason instanceof Error ? reason.message : "Oran kaydedilemedi."); }
      }}><label className="field"><span>Iskarta Oranı (%)</span><input disabled={readOnly} aria-label="Iskarta Oranı (%)" inputMode="decimal" value={scrap} onChange={(event) => setScrap(event.target.value)} /></label><button disabled={readOnly} className="secondary" type="submit">Oranı kaydet</button><p>Günlük üretim adedine bu oranda ilave hammadde eklenir.</p>{scrapError && <p role="alert" className="form-error">{scrapError}</p>}</form>}
    </div>
    <div className="product-weights-toolbar"><input aria-label="Ürün ağırlıklarında ara" placeholder="Tip no veya hammadde ara…" value={query} onChange={(event) => setQuery(event.target.value)} /><span>{visible.length} / {rows.length} ürün</span><button disabled={readOnly || !!productCodes} className="primary" onClick={() => { setOriginalCode(null); setEditing({ product: "", productName: "", materialCode: "", materialName: "", grams: null }); setAmount(""); setError(""); }}>Ürün ekle</button></div>
    {editing && <form className="product-weight-editor" onSubmit={(event) => { event.preventDefault(); save(); }}>
      <label className="field"><span>Tip no</span><input required value={editing.product} readOnly={originalCode !== null} onChange={(event) => setEditing({ ...editing, product: event.target.value })} /></label>
      <label className="field"><span>Ürün adı</span><input value={editing.productName} onChange={(event) => setEditing({ ...editing, productName: event.target.value })} /></label>
      <label className="field"><span>Hammadde kodu</span><input value={editing.materialCode} onChange={(event) => setEditing({ ...editing, materialCode: event.target.value })} /></label>
      <label className="field"><span>Hammadde ağırlığı (g)</span><input inputMode="decimal" placeholder="Örn. 181 veya 75,13" value={amount} onChange={(event) => setAmount(event.target.value)} /></label>
      <label className="field weight-description"><span>Hammadde açıklaması</span><input value={editing.materialName} onChange={(event) => setEditing({ ...editing, materialName: event.target.value })} /></label>
      <div className="drawer-actions"><button type="button" className="secondary" onClick={() => setEditing(null)}>Vazgeç</button><button type="submit" className="primary">Kaydet</button></div>
      {error && <p role="alert" className="form-error">{error}</p>}
    </form>}
    <div className="product-weights-scroll"><table className="product-weights-table"><thead><tr><th>Tip no</th><th>Ürün adı</th><th>Hammadde kodu</th><th>Hammadde açıklaması</th><th>Ağırlık (g)</th><th>İşlem</th></tr></thead><tbody>{visible.map((row) => <tr key={row.product}><td><strong>{row.product}</strong></td><td>{row.productName || "—"}</td><td>{row.materialCode || "—"}</td><td>{row.materialName || "—"}</td><td>{row.grams === null ? "—" : row.grams.toLocaleString("tr-TR", { maximumFractionDigits: 6 })}</td><td><button disabled={readOnly} className="secondary" aria-label={`${row.product} ağırlığını düzenle`} onClick={() => { setOriginalCode(row.product); setEditing({ ...row }); setAmount(row.grams?.toString().replace(".", ",") ?? ""); setError(""); }}>Düzenle</button></td></tr>)}</tbody></table></div>
    {!visible.length && <p>Aramanızla eşleşen ürün yok.</p>}
  </section>;
}

frontend/features/planning/settings/RawM.source:
"use client";

import { Fragment, useEffect, useMemo, useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { factoryDateInput } from "@/lib/factory-time";
import { formatExcelDate, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { buildRawMaterialConsumption, rawMaterialCatalog } from "@/lib/raw-material-consumption";
import { initialRawMaterialSettings, validateRawMaterialSettings } from "@/lib/raw-material-settings";
import { inputDateToSerial } from "@/features/planning/shared/format";

const kg = (value: number) => value.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 3 });

export function RawMaterialConsumption({ seed, result, dirty, updateSeed }: {
  seed: PlanningSeed; result: ScenarioResult; dirty: boolean; updateSeed: (mutator: (seed: PlanningSeed) => void) => void;
}) {
  const settings = useMemo(() => seed.rawMaterialSettings ?? initialRawMaterialSettings(), [seed.rawMaterialSettings]);
  const catalog = useMemo(() => rawMaterialCatalog(seed), [seed]);
  const [stockDate, setStockDate] = useState(settings.stockDate || factoryDateInput());
  const [stocks, setStocks] = useState<Record<string, string>>({});
  const [query, setQuery] = useState("");
  const [days, setDays] = useState(90);
  const [error, setError] = useState("");
  const [editing, setEditing] = useState(!settings.stockDate);
  const [today, setToday] = useState(factoryDateInput);
  useEffect(() => { const timer = window.setInterval(() => setToday(factoryDateInput()), 60000); return () => clearInterval(timer); }, []);
  useEffect(() => {
    setStockDate(settings.stockDate || factoryDateInput());
    setStocks(Object.fromEntries(settings.stocks.map((row) => [row.materialCode, row.kg === null ? "" : String(row.kg).replace(".", ",")])));
  }, [settings.stockDate, settings.stocks]);
  const report = useMemo(() => settings.stockDate ? buildRawMaterialConsumption(seed, result, inputDateToSerial(settings.stockDate), days, inputDateToSerial(today)) : null,
    [seed, result, settings.stockDate, days, today]);
  const visible = report?.materials.filter((row) => `${row.materialCode} ${row.materialName}`.toLocaleLowerCase("tr-TR").includes(query.toLocaleLowerCase("tr-TR"))) ?? [];
  const dates = report?.materials[0]?.days ?? [];
  useRaviScreenContext("raw-material-consumption", {
    query, days, stockDate: settings.stockDate, scrapPercent: settings.scrapPercent, dirty, planState: result.state,
    source: "current-browser", unit: "kg", editing, draftStockDate: stockDate,
    draftStocks: editing ? Object.entries(stocks).slice(0, 12) : undefined,
    issues: report?.issues.slice(0, 12), unplannedCount: report?.unplannedCount,
    visibleCount: visible.length, materials: visible.slice(0, 12).map((row) => ({ materialCode: row.materialCode, stockKg: row.stockKg,
      exhaustedOn: row.exhaustedOn, shortageOn: row.shortageOn, days: row.days.slice(0, 7) })),
  });
  function save() {
    try {
      if (!stockDate) throw new Error("CPM stoklarının güncelleme tarihini girin.");
      const next = validateRawMaterialSettings({ ...settings, stockDate, stocks: catalog.map((row) => ({ materialCode: row.materialCode,
        kg: stocks[row.materialCode]?.trim() ? Number(stocks[row.materialCode].trim().replace(",", ".")) : null })) });
      updateSeed((draft) => { draft.rawMaterialSettings = next; }); setError(""); setEditing(false);
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Stoklar kaydedilemedi."); }
  }
  return <section className="calendar-section material-consumption-section">
    <div className="calendar-section-title"><div><h3>Hammadde Tüketim Tablosu</h3><p>Torna planına göre günlük çelik ihtiyacı ve kalan ambar stoğu.</p></div>
      <button className="secondary" onClick={() => { setEditing(!editing); setError(""); }}>{editing ? "Girişi kapat" : "Stokları güncelle"}</button></div>
    {editing && <form className="material-stock-editor" onSubmit={(event) => { event.preventDefault(); save(); }}>
      <div className="material-stock-heading"><label className="field"><span>Güncelleme Tarihi</span><input className="material-manual" type="date" required value={stockDate} onChange={(event) => setStockDate(event.target.value)} /></label>
        <p>Sarı alanlara CPM’den aldığınız stokları kg olarak girin. Tarih, bu stokların gün başı bakiyesini belirtir. Boş alan bilinmiyor, 0 ise stok yok demektir.</p></div>
      <div className="material-stock-grid">{catalog.map((row) => <label className="field" key={row.materialCode}><span>{row.materialCode} · {row.diameter}</span><input className="material-manual" aria-label={`${row.materialCode} Ambar stoğu (kg)`} inputMode="decimal" placeholder="Ambar stoğu (kg)" value={stocks[row.materialCode] ?? ""} onChange={(event) => setStocks({ ...stocks, [row.materialCode]: event.target.value })} /></label>)}</div>
      {error && <p className="form-error" role="alert">{error}</p>}<button type="submit" className="primary">Stokları kaydet</button>
    </form>}
    {(dirty || result.state !== "planned") && <p role="status" className="material-warning">{dirty ? "Plan güncel değil. Tüketim mevcut tarihlere göre ön izlemedir; planı yeniden çalıştırın." : "Henüz plan çalıştırılmadı. Yalnız mevcut Torna işlerinin kalan miktarı gösterilir."}</p>}
    {settings.stockDate && settings.stockDate < today && <p className="material-warning">Güncelleme tarihi geçmişte. Tamamlanmış üretimin fiili tüketimi bu tahminde yer almaz; kalan stoğu doğrulamak için CPM bakiyesini güncelleyin.</p>}
    {report && report.unplannedCount > 0 && <p className="material-warning">{report.unplannedCount} planlanamayan şarjın tarihi yok; ihtiyaca dahil edilmedi.</p>}
    {!!report?.issues.length && <div className="material-warning" role="alert"><strong>Hesap eksik</strong><ul>{report.issues.map((issue) => <li key={issue}>{issue}</li>)}</ul></div>}
    <div className="product-weights-toolbar"><input aria-label="Hammadde tüketiminde ara" placeholder="Hammadde kodu veya açıklama ara…" value={query} onChange={(event) => setQuery(event.target.value)} />
      <label className="field"><span>Gösterilen dönem</span><select value={days} onChange={(event) => setDays(Number(event.target.value))}>{[30, 90, 180, 366].map((count) => <option key={count} value={count}>{count} gün</option>)}</select></label>
      <span>Iskarta Oranı: %{settings.scrapPercent.toLocaleString("tr-TR", { minimumFractionDigits: 2 })}</span></div>
    {!settings.stockDate ? <p>Tabloyu görmek için güncelleme tarihini ve ambar stoklarını kaydedin.</p> : <>
      <p className="material-formula">Günlük ihtiyaç (kg) = Torna günlük üretim adedi × (1 + ıskarta oranı / 100) × ağırlık (g) / 1000. Kalan = önceki günün kalanı − günlük ihtiyaç.</p>
      <p className="material-legend"><span>Yeşil: ihtiyaç karşılanıyor</span><span>Kırmızı: stok tükendi veya yetersiz</span><span>—: stok ya da hesap bilgisi eksik</span></p>
      <div className="material-table-scroll" tabIndex={0} aria-label="Günlük hammadde tüketimi, yatay kaydırılabilir"><table className="material-table"><thead>
        <tr><th rowSpan={2}>Ambar stoğu (kg)</th><th rowSpan={2}>Hammadde Kodu / Çap</th><th rowSpan={2}>Stok durumu</th><th rowSpan={2}>Tarih</th>{dates.map((day) => <th key={day.day}>{formatExcelDate(day.day)}</th>)}</tr>
        <tr>{dates.map((day) => <th key={day.day}>{new Date(Date.UTC(1899, 11, 30) + day.day * 86400000).toLocaleDateString("tr-TR", { weekday: "short", timeZone: "UTC" })}</th>)}</tr>
      </thead><tbody>{visible.map((row) => <Fragment key={row.materialCode}>
        <tr><td rowSpan={2}>{row.stockKg === null ? "—" : kg(row.stockKg)}</td><th rowSpan={2} title={row.materialName}>{row.materialCode}<small>{row.diameter}</small></th>
          <td rowSpan={2} className="material-coverage">{row.days.some((day) => day.incomplete) ? "Hesap eksik" : row.stockKg === null ? "Stok girilmedi" : row.exhaustedOn !== null ? <><strong>{formatExcelDate(row.exhaustedOn)}</strong><small>Stok tükeniyor{row.shortageOn !== null ? ` · İlk eksik: ${formatExcelDate(row.shortageOn)}` : " · O günün ihtiyacı karşılanıyor"}</small></> : "Dönem boyunca yeterli"}</td>
          <th>İhtiyaç</th>{row.days.map((day) => <td key={day.day} title={`${day.quantity.toLocaleString("tr-TR")} adet · ${day.incomplete ? "Bilinen ihtiyaç; hesap eksik" : "Iskarta dahil kg"}`}>{day.incomplete ? `${kg(day.requiredKg)}*` : kg(day.requiredKg)}</td>)}</tr>
        <tr><th>Kalan</th>{row.days.map((day) => <td key={day.day} className={day.remainingKg === null ? "" : day.remainingKg <= 0 ? "material-empty" : "material-covered"}>{day.remainingKg === null ? "—" : kg(day.remainingKg)}</td>)}</tr>
      </Fragment>)}</tbody></table></div>
      {!visible.length && <p>Aramanızla eşleşen hammadde yok.</p>}
      <p className="material-footnote">Güncelleme: {settings.stockDate} · Tüm Torna tezgâhları ve tarihli planlı şarjlar. Mevcut işlerde kalan adet kullanılır. Hazırlık süresi, tamamlanan işler ve diğer prosesler tüketilmez. Hesap bir stok tahminidir; CPM’ye kayıt yazmaz. * Bilinen ihtiyaç, eksikler hariç.</p>
    </>}
  </section>;
}

frontend/features/planning/settings/Sett.source:
"use client";
import { productionProcessOrder } from "@/lib/process-master-data";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { useState } from "react";
import { CaretLeft, CaretRight, CalendarBlank, PencilSimple } from "@phosphor-icons/react";
import { settingsCalendarProcessLabel, type SettingsCalendarProcess, settingsMonthDays, settingsEntriesOnDate, shiftCalendarMonth, calendarSerialDate, type SettingsCalendarEntry } from "@/lib/settings-calendar";

const LABELS = { holiday: "Resmi tatil", maintenance: "Bakım", overtime: "Mesai", "shift-change": "Vardiya" };
const entryProcess = (entry: SettingsCalendarEntry) => entry.kind === "holiday" ? "all" : entry.process ?? "unknown";
const entryProcessLabel = (entry: SettingsCalendarEntry) => entry.kind === "holiday" ? "Tüm prosesler" : entry.process ? settingsCalendarProcessLabel(entry.process as SettingsCalendarProcess) : "İş merkezi";

const dateLabel = (date: string) => new Intl.DateTimeFormat("tr-TR", { dateStyle: "long", timeZone: "UTC" }).format(new Date(`${date}T00:00:00Z`));

export function SettingsCalendar({ entries, today, onEdit, processes = productionProcessOrder({}) }: { processes?: SettingsCalendarProcess[]; entries: SettingsCalendarEntry[]; today: string; onEdit: (entry: SettingsCalendarEntry) => void }) {
  const [month, setMonth] = useState(today.slice(0, 7));
  const [selectedDate, setSelectedDate] = useState(today);
  const [kind, setKind] = useState("all");
  const [process, setProcess] = useState("all");
  const [status, setStatus] = useState("all");
  const filtered = entries.filter((entry) => (kind === "all" || entry.kind === kind)
    && (process === "all" || entry.kind === "holiday" || entry.process === process)
    && (status === "all" || (status === "completed" ? entry.completed : !entry.completed)));
  const days = settingsMonthDays(month);
  const selected = settingsEntriesOnDate(filtered, selectedDate);
  useRaviScreenContext("settings-calendar", { month, selectedDate, kind, process, status, selected });
  const monthCount = filtered.filter((entry) => calendarSerialDate(entry.start).slice(0, 7) <= month && calendarSerialDate(entry.end).slice(0, 7) >= month).length;
  function changeMonth(offset: number) {
    const next = shiftCalendarMonth(month, offset);
    setMonth(next);
    setSelectedDate(`${next}-01`);
  }
  return <section className="settings-month-calendar" aria-label="Üretim takvimi">
    <div className="settings-month-heading"><div><span>ÜRETİM TAKVİMİ</span><h3>{new Intl.DateTimeFormat("tr-TR", { month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(`${month}-01T00:00:00Z`))}</h3><p>{monthCount} kayıt · Ayrıntılar için bir gün seçin.</p></div>
      <div className="settings-month-navigation"><button className="secondary" aria-label="Önceki ay" onClick={() => changeMonth(-1)}><CaretLeft size={16} /></button><input type="month" value={month} aria-label="Takvim ayı" onChange={(event) => { if (event.target.value) { setMonth(event.target.value); setSelectedDate(`${event.target.value}-01`); } }} /><button className="secondary" aria-label="Sonraki ay" onClick={() => changeMonth(1)}><CaretRight size={16} /></button><button className="secondary" onClick={() => { setMonth(today.slice(0, 7)); setSelectedDate(today); }}>Bugün</button></div>
    </div>
    <div className="settings-month-filters"><label>Tür<select aria-label="Takvim kayıt türü" value={kind} onChange={(event) => setKind(event.target.value)}><option value="all">Tüm kayıtlar</option>{Object.entries(LABELS).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Proses<select aria-label="Takvim prosesi" value={process} onChange={(event) => setProcess(event.target.value)}><option value="all">Tüm prosesler</option>{processes.map(p => <option key={p} value={p}>{settingsCalendarProcessLabel(p)}</option>)}</select></label><label>Durum<select aria-label="Takvim kayıt durumu" value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">Aktif + geçmiş</option><option value="active">Aktif kayıtlar</option><option value="completed">Geçmiş</option></select></label><p>Resmi tatiller tüm proseslerde gösterilir. Pazar kapasitesi vardiya ayarlarına bağlıdır.</p></div>
    <div className="settings-calendar-legend" aria-label="Takvim renk ve simge açıklamaları"><div className="settings-legend-group"><strong>Kayıt türü</strong>{Object.entries(LABELS).map(([key, label]) => <span key={key} className={`settings-calendar-kind ${key}`}>{label}</span>)}</div><div className="settings-legend-group"><strong>Proses</strong>{[...processes.map(p => [p, settingsCalendarProcessLabel(p)]), ["all", "Tüm prosesler"]].map(([key, label]) => <span className="settings-process-key" key={key}><ProcessIcon process={key} />{label}</span>)}</div><small>Soluk kayıtlar geçmişe aittir.</small></div>
    <div className="settings-month-layout"><div className="settings-month-scroll"><div className="settings-month-grid" role="group" aria-label="Aylık takvim">
      {["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"].map((day) => <div className="settings-weekday" key={day}>{day}</div>)}
      {days.map((date, index) => {
        const events = settingsEntriesOnDate(filtered, date);
        return <button key={date} type="button" aria-label={`${dateLabel(date)}, ${events.length} kayıt`} aria-pressed={date === selectedDate} onClick={() => setSelectedDate(date)} className={`settings-day ${date.startsWith(month) ? "" : "outside"} ${index % 7 === 6 ? "sunday" : ""} ${date === selectedDate ? "selected" : ""}`}>
          <span className={`settings-day-number ${date === today ? "today" : ""}`}>{Number(date.slice(-2))}{date === today && <small>Bugün</small>}</span>
          {events.slice(0, 3).map((entry) => <span key={entry.id} className={`settings-calendar-chip ${entry.kind} ${entry.completed ? "completed" : ""}`} title={`${LABELS[entry.kind]} · ${entryProcessLabel(entry)} · ${entry.resource ? `${entry.resource} · ` : ""}${entry.title}`}><ProcessIcon process={entryProcess(entry)} /><span className="settings-chip-copy"><b>{LABELS[entry.kind]}{entry.resource ? ` · ${entry.resource}` : ""}</b><span>{entry.title}</span></span></span>)}
          {events.length > 3 && <span className="settings-day-more">+{events.length - 3} kayıt daha</span>}
        </button>;
      })}
    </div></div>
    <aside className="settings-day-details" aria-label="Seçili günün kayıtları"><CalendarBlank size={21} /><h4>{dateLabel(selectedDate)}</h4><p>{selected.length} kayıt</p>
      {selected.map((entry) => <article key={entry.id} className={entry.kind}><div><span className={`settings-calendar-kind ${entry.kind}`}>{LABELS[entry.kind]}</span>{entry.completed && <small>Geçmiş</small>}</div><strong>{entry.title}</strong><span className="settings-entry-process"><ProcessIcon process={entryProcess(entry)} />{entryProcessLabel(entry)}</span><span>{entry.resource || "Tüm iş merkezleri"} · {entry.kind === "maintenance" ? "Üretim durur" : `${entry.shifts} vardiya`}</span><small>{dateLabel(calendarSerialDate(entry.start))}{Math.floor(entry.end) !== Math.floor(entry.start) ? ` – ${dateLabel(calendarSerialDate(entry.end))}` : ""}</small>{!entry.completed && <button className="secondary" onClick={() => onEdit(entry)}><PencilSimple size={13} /> Düzenle</button>}</article>)}
      {!selected.length && <div className="settings-day-empty">Bu gün için seçili filtrelerde kayıt yok.<br />Yeni kayıtları ilgili ayar sekmesinden ekleyebilirsiniz.</div>}
    </aside></div>

  </section>;
}

"use client";
import { ProcessStockSettingsPanel } from "../stocks/ProcessStockView";

import { useRaviScreenContext } from "@/features/ravi/context";

import { ProcessIcon } from "@/components/ProcessIcon";

import { effectiveWaitSources, legacyWashingRules } from "@/lib/flow-settings";
import { FlowSettingsPanel } from "../parameters/FlowSettingsPanel";
import { ProcessWaitSettingsPanel } from "./ProcessWaitSettingsPanel";
import { ProductWeights } from "./ProductWeights";
import { RawMaterialConsumption } from "./RawMaterialConsumption";
import { SettingsCalendar } from "./SettingsCalendar";
import { FILTER_QUALITY_RESOURCE, FILTER_DEMAND_RESOURCE, FILTER_QUALITY_CALENDAR_LABEL, FILTER_DEMAND_CALENDAR_LABEL, FILTER_WAIT_CALENDAR_LABEL, settingsCalendarProcesses, settingsCalendarProcessLabel, type SettingsCalendarEntry, type SettingsCalendarProcess } from "@/lib/settings-calendar";
import { FILTER_WAIT_RESOURCE } from "@/lib/process-lead-time";
import { MachineMaintenanceDialog, MachineShiftDialog, ShiftOptions } from "@/features/planning/machines/CalendarDialogs";
import { DataPackageActions } from "@/features/planning/shared/DataPackageActions";
import { Field } from "@/features/planning/shared/controls";
import { dateAfterDays, inputDateToSerial, serialToInputDate } from "@/features/planning/shared/format";
import { clampShiftCount } from "@/features/planning/shared/production";
import { useApiFetch } from "@/lib/api";
import { calendarEventStatus } from "@/lib/calendar-event-status";
import { applySettingsPackage, settingsPackage } from "@/lib/data-packages";
import { factoryDateInput } from "@/lib/factory-time";
import {
  formatExcelDate,
  getSetupSettings,
  removeMachineShiftOverrides,
  replaceMachineShiftOverrides,
  type Machine,
  type MachineCalendarEvent,
  type PlanningSeed,
  type ScenarioResult,
  type ShiftCount,
} from "@/lib/planning";
import { type ProcessKind } from "@/lib/process-master-data";
import {
  ArrowsLeftRight,
  CalendarBlank,
  CheckCircle,
  Clock,
  FileXls,
  PencilSimple,
  Plus,
  Trash,
  Warning,
  Wrench,
} from "@phosphor-icons/react";
import { useEffect, useState, type ReactNode } from "react";

type CalendarDetailType = "maintenance" | "overtime" | "shift-change";
type SettingsSection = "waits" | "stocks" | "weights" | "calendar" | "setup" | "holidays" | "maintenance" | "shifts";
const SETTINGS_SECTIONS: Array<{ id: SettingsSection; label: string }> = [
  { id: "stocks", label: "Stok ayarları" },
  { id: "calendar", label: "Takvim" }, { id: "waits", label: "Proses bekleme süreleri" }, { id: "setup", label: "Setup" }, { id: "holidays", label: "Resmi tatiller" },
  { id: "maintenance", label: "Bakımlar" }, { id: "shifts", label: "Mesai ve vardiya" }, { id: "weights", label: "Hammadde Bilgileri" },
];

export function settingsCalendarMachine(seed: PlanningSeed, resourceId: string): Machine | undefined {
  const machine = seed.machines.find((item) => item.id === resourceId);
  if (machine) return machine;
  const resource = resourceId === FILTER_WAIT_RESOURCE && seed.productionArea === "cubuk-filtre"
    ? { id: FILTER_WAIT_RESOURCE, name: FILTER_WAIT_CALENDAR_LABEL, process: "filter-wait" as const, active: true, defaultShifts: seed.filterWaitShifts ?? 1, availableStart: undefined, planEnd: undefined }
    : resourceId === FILTER_QUALITY_RESOURCE && seed.productionArea === "cubuk-filtre"
      ? { id: FILTER_QUALITY_RESOURCE, name: FILTER_QUALITY_CALENDAR_LABEL, process: "filter-quality" as const, active: true, defaultShifts: seed.filterQualityShifts ?? 1, availableStart: undefined, planEnd: undefined }
      : resourceId === FILTER_DEMAND_RESOURCE && seed.productionArea === "cubuk-filtre"
        ? { id: FILTER_DEMAND_RESOURCE, name: FILTER_DEMAND_CALENDAR_LABEL, process: "filter-demand" as const, active: true, defaultShifts: 2, availableStart: undefined, planEnd: undefined }
    : seed.processMasterData?.resources.find((item) => item.id === resourceId)
    ?? (resourceId === "B-01" ? seed.processMasterData?.resources.find((item) => item.process === "deburring") : undefined);
  if (!resource) return undefined;
  const start = resource.availableStart ?? inputDateToSerial(factoryDateInput());
  return {
    id: resourceId,
    name: resourceId === "B-01" ? "Ortak Çapak Alma" : resource.name,
    active: resource.active,
    availableStart: start,
    operationalAvailableStart: start,
    planEnd: resource.planEnd ?? start + 365,
    note: settingsCalendarProcessLabel(resource.process),
    shiftFactor: resource.defaultShifts,
    capacityFactor: 1,
    finishOffset: 0,
    rates: {},
    currentJob: { workOrder: "", product: "", quantity: 0, originalQuantity: 0, remainingQuantity: 0, start, end: start, dailyRate: 0, diameter: "" },
  };
}

export function SettingsView({ seed, result, dirty, updateMaterials, updateSeed, updatePlanningInputs }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; updateMaterials: (mutator: (seed: PlanningSeed) => void) => void; updateSeed: (mutator: (seed: PlanningSeed) => void) => void; updatePlanningInputs: (mutator: (seed: PlanningSeed) => void) => void }) {
  const apiFetch = useApiFetch();
  const pistonSettings = seed.productionArea !== "cubuk-filtre";
  const [section, setSection] = useState<SettingsSection>("calendar");
  const [materialSection, setMaterialSection] = useState<"weights" | "consumption">("weights");
  const [holidayDraft, setHolidayDraft] = useState({ name: "", date: dateAfterDays(7), workingShifts: 0 as ShiftCount });
  const initialEventDraft = { machineId: seed.machines[0]?.id ?? "", kind: "maintenance" as MachineCalendarEvent["kind"], name: "", start: dateAfterDays(1), end: dateAfterDays(1), shiftCount: 1 as ShiftCount };
  const [eventDrafts, setEventDrafts] = useState({ maintenance: initialEventDraft, shifts: { ...initialEventDraft, kind: "shift" as MachineCalendarEvent["kind"] } });
  const draftSection = section === "shifts" ? "shifts" : "maintenance";
  const eventDraft = eventDrafts[draftSection];
  const setEventDraft = (value: typeof eventDraft | ((current: typeof eventDraft) => typeof eventDraft)) => setEventDrafts((current) => ({ ...current, [draftSection]: typeof value === "function" ? value(current[draftSection]) : value }));
  const [editingHoliday, setEditingHoliday] = useState<{ original: number; name: string; date: string; shifts: ShiftCount } | null>(null);
  const [holidayEditError, setHolidayEditError] = useState("");
  const [editingShiftId, setEditingShiftId] = useState<string | null>(null);
  const [editingMaintenanceId, setEditingMaintenanceId] = useState<string | null>(null);
  const [calendarTypeFilter, setCalendarTypeFilter] = useState<CalendarDetailType | "all">("all");
  const [calendarProcessFilter, setCalendarProcessFilter] = useState<SettingsCalendarProcess | "all">("all");
  const [calendarStatusFilter, setCalendarStatusFilter] = useState<"active" | "completed" | "all">("active");
  const [calendarFilterStart, setCalendarFilterStart] = useState("");
  const [calendarFilterEnd, setCalendarFilterEnd] = useState("");
  const [calendarExporting, setCalendarExporting] = useState(false);
  const [calendarExportError, setCalendarExportError] = useState("");
  const [calendarToday, setCalendarToday] = useState(factoryDateInput);
  const [setupDraft, setSetupDraft] = useState(() => getSetupSettings(seed));
  const setup = getSetupSettings(seed);
  useRaviScreenContext("settings", { effectiveWaitSources: section === "waits" ? effectiveWaitSources(seed) : undefined, hasLegacyWashing: section === "waits" && seed.productionArea !== "cubuk-filtre" ? legacyWashingRules(seed.flowSettings).length > 0 : undefined, section, materialSection: section === "weights" ? materialSection : undefined, calendarTypeFilter, calendarProcessFilter, calendarStatusFilter, calendarFilterStart, calendarFilterEnd, setup, setupDraft, filterWaitShifts: seed.productionArea === "cubuk-filtre" ? seed.filterWaitShifts ?? 1 : undefined, filterQualityShifts: seed.productionArea === "cubuk-filtre" ? seed.filterQualityShifts ?? 1 : undefined, filterDemandResource: seed.productionArea === "cubuk-filtre" ? { id: FILTER_DEMAND_RESOURCE, defaultShifts: 2 } : undefined, eventDraft, editingShiftId, editingMaintenanceId });
  const setupChanged = Object.keys(setup).some((key) => setup[key as keyof typeof setup] !== setupDraft[key as keyof typeof setupDraft]);

  useEffect(() => setSetupDraft(getSetupSettings(seed)), [setup.shiftHours, setup.sameDiameterHours, setup.sameFamilyDifferentDiameterHours, setup.crossFamilyHours, setup.differentDiameterHours]);
  useEffect(() => {
    const refreshFactoryDay = () => setCalendarToday(factoryDateInput());
    const interval = window.setInterval(refreshFactoryDay, 60_000);
    return () => window.clearInterval(interval);
  }, []);

  function saveSetupSettings() {
    const normalized = getSetupSettings({ setupSettings: setupDraft });
    updatePlanningInputs((draft) => { draft.setupSettings = normalized; });
    setSetupDraft(normalized);
  }

  function addHoliday() {
    const serial = inputDateToSerial(holidayDraft.date);
    if (!holidayDraft.name.trim() || !serial) return;
    updateSeed((draft) => {
      const existing = draft.holidays.find((holiday) => Math.floor(holiday.serial) === serial);
      if (existing) Object.assign(existing, { name: holidayDraft.name.trim(), workingShifts: holidayDraft.workingShifts });
      else draft.holidays.push({ name: holidayDraft.name.trim(), serial, workingShifts: holidayDraft.workingShifts });
    });
    setHolidayDraft({ name: "", date: dateAfterDays(7), workingShifts: 0 });
  }

  function addCalendarEvent() {
    const start = inputDateToSerial(eventDraft.start);
    const end = inputDateToSerial(eventDraft.end);
    if (!eventDraft.machineId || !start || !end || end < start) return;
    updateSeed((draft) => {
      if (eventDraft.kind === "shift") {
        replaceMachineShiftOverrides(draft, [eventDraft.machineId], start, end, eventDraft.shiftCount, eventDraft.name.trim() || "Vardiya değişikliği");
        return;
      }
      draft.calendarEvents = [...(draft.calendarEvents ?? []), {
        id: `takvim-${Date.now()}`,
        machineId: eventDraft.machineId,
        kind: eventDraft.kind,
        name: eventDraft.name.trim() || (eventDraft.kind === "maintenance" ? "Planlı bakım" : "Vardiya değişikliği"),
        start,
        end,
        shiftCount: eventDraft.kind === "maintenance" ? 0 : eventDraft.shiftCount,
      }];
    });
    setEventDraft((current) => ({ ...current, name: "" }));
  }

  const sortedHolidays = [...seed.holidays].sort((left, right) => left.serial - right.serial);
  const calendarResources: Array<{ id: string; name: string; process: SettingsCalendarProcess; defaultShifts: number }> = [
    ...seed.machines.map((machine) => ({ id: machine.id, name: machine.name, process: "turning" as ProcessKind, defaultShifts: machine.shiftFactor })),
    ...(seed.processMasterData?.resources ?? []).filter((resource) => resource.process !== "turning").map((resource) => ({ id: resource.id, name: resource.name, process: resource.process, defaultShifts: resource.defaultShifts })),
  ];
  if (seed.productionArea === "cubuk-filtre") calendarResources.push({ id: FILTER_WAIT_RESOURCE, name: FILTER_WAIT_CALENDAR_LABEL, process: "filter-wait", defaultShifts: seed.filterWaitShifts ?? 1 });
  if (seed.productionArea === "cubuk-filtre") calendarResources.push({ id: FILTER_QUALITY_RESOURCE, name: FILTER_QUALITY_CALENDAR_LABEL, process: "filter-quality", defaultShifts: seed.filterQualityShifts ?? 1 }, { id: FILTER_DEMAND_RESOURCE, name: FILTER_DEMAND_CALENDAR_LABEL, process: "filter-demand", defaultShifts: 2 });
  const calendarResourceMap = new Map(calendarResources.map((resource) => [resource.id, resource]));
  const calendarTodaySerial = inputDateToSerial(calendarToday);
  const sortedEvents = [...(seed.calendarEvents ?? [])].sort((left, right) => left.start - right.start || left.machineId.localeCompare(right.machineId));
  const calendarEventDetails = sortedEvents.map((event) => {
    const fallbackProcess: ProcessKind = event.machineId.startsWith("D-") ? "drilling" : event.machineId.startsWith("B-") ? "deburring" : event.machineId.startsWith("V-") ? "gkm" : "turning";
    const resource = calendarResourceMap.get(event.machineId) ?? { id: event.machineId, name: event.machineId === "B-01" ? "Ortak Çapak Alma" : "Tanımsız iş merkezi", process: fallbackProcess, defaultShifts: 3 as ShiftCount };
    const namedOvertime = event.name.toLocaleUpperCase("tr-TR").includes("MESAİ");
    const type: CalendarDetailType = event.kind === "maintenance" ? "maintenance" : namedOvertime || event.shiftCount > resource.defaultShifts ? "overtime" : "shift-change";
    return { event, resource, type, ...calendarEventStatus(event, calendarTodaySerial) };
  });
  const calendarEntries: SettingsCalendarEntry[] = [
    ...sortedHolidays.map((holiday) => ({ id: `holiday:${holiday.serial}`, title: holiday.name, kind: "holiday" as const, start: holiday.serial, end: holiday.serial, shifts: holiday.workingShifts ?? 0, completed: Math.floor(holiday.serial) < calendarTodaySerial })),
    ...calendarEventDetails.map(({ event, resource, type, status }) => ({ id: event.id, title: event.name, kind: type, start: event.start, end: event.end, shifts: event.shiftCount, resource: event.machineId, process: resource.process, completed: status === "completed" })),
  ];
  function editCalendarEntry(entry: SettingsCalendarEntry) {
    if (entry.kind === "holiday") {
      setHolidayEditError("");
      setEditingHoliday({ original: entry.start, name: entry.title, date: serialToInputDate(entry.start), shifts: clampShiftCount(entry.shifts) });
    } else if (entry.kind === "maintenance") setEditingMaintenanceId(entry.id);
    else setEditingShiftId(entry.id);
  }
  const filterStartSerial = inputDateToSerial(calendarFilterStart);
  const filterEndSerial = inputDateToSerial(calendarFilterEnd);
  const filteredCalendarEvents = calendarEventDetails.filter(({ event, resource, type, status }) =>
    (section === "maintenance" ? type === "maintenance" : type !== "maintenance")
    && (section === "maintenance" || calendarTypeFilter === "all" || type === calendarTypeFilter)
    && (calendarProcessFilter === "all" || resource.process === calendarProcessFilter)
    && (calendarStatusFilter === "all" || status === calendarStatusFilter)
    && (!filterStartSerial || event.end >= filterStartSerial)
    && (!filterEndSerial || event.start <= filterEndSerial));
  const editingShift = sortedEvents.find((event) => event.id === editingShiftId && event.kind === "shift");
  const editingShiftMachine = editingShift ? settingsCalendarMachine(seed, editingShift.machineId) : undefined;
  const editingMaintenance = sortedEvents.find((event) => event.id === editingMaintenanceId && event.kind === "maintenance");
  const editingMaintenanceMachine = editingMaintenance ? settingsCalendarMachine(seed, editingMaintenance.machineId) : undefined;

  async function exportCalendarEvents() {
    setCalendarExporting(true);
    setCalendarExportError("");
    try {
      const response = await apiFetch("/calendar-events/export", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          generatedAt: new Date().toISOString(),
          rows: filteredCalendarEvents.map(({ event, resource, type, status, automaticallyCompleted }) => ({
            eventType: type,
            process: resource.process,
            workCenterId: event.machineId,
            workCenterName: resource.name,
            name: event.name,
            startDate: serialToInputDate(event.start),
            endDate: serialToInputDate(event.end),
            shiftCount: event.shiftCount,
            status,
            completedAt: event.completedAt ?? (automaticallyCompleted ? serialToInputDate(event.end) : ""),
          })),
        }),
      });
      if (!response.ok) {
        const body = await response.json().catch(() => ({ detail: "Bakım ve mesai Excel’i oluşturulamadı." }));
        throw new Error(body.detail || "Bakım ve mesai Excel’i oluşturulamadı.");
      }
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? `Bakim_Mesai_Vardiya_Detayi_${factoryDateInput()}.xlsx`;
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (reason) {
      setCalendarExportError(reason instanceof Error ? reason.message : "Bakım ve mesai Excel’i oluşturulamadı.");
    } finally {
      setCalendarExporting(false);
    }
  }

  if (!pistonSettings && section === "stocks") return <section className="settings-page"><button onClick={() => setSection("calendar")}>Ayarlar → Takvim</button><ProcessStockSettingsPanel seed={seed} updateSeed={updateMaterials} /></section>;
  return (
    <><section className={`settings-page ${pistonSettings ? "piston-settings-page" : ""}`}>
      <div className="calendar-heading"><div><span>{pistonSettings ? "AYARLAR" : section === "weights" ? "HAMMADDE BİLGİLERİ" : "ÜRETİM TAKVİMİ"}</span><h2>{pistonSettings ? "Üretim ayarları" : section === "weights" ? "Çelik ihtiyacını ve stok yeterliliğini izleyin" : "Kapasiteyi tarihe göre yönetin"}</h2><p>{pistonSettings ? "Piston ve Center Pin için akış, hazırlık, takvim ve hammadde ayarları." : section === "weights" ? "Ürün ağırlıklarını ve ıskarta oranını güncel tutun; Torna planına göre ambar stoğunuzun hangi güne kadar yettiğini görün." : "Pazar günleri ve vardiya verilmemiş resmi tatiller üretim dışıdır. Değişiklikler mevcut kuyruk korunarak başlangıç ve bitiş tarihlerine hemen yansır."}</p></div><div className="calendar-heading-tools"><div className="calendar-summary" hidden={pistonSettings || section === "weights"}><span><b>{seed.holidays.length}</b> tatil</span><span><b>{calendarEventDetails.filter(({ type, status }) => type === "maintenance" && status === "active").length}</b> açık bakım</span><span><b>{calendarEventDetails.filter(({ status }) => status === "completed").length}</b> geçmiş kayıt</span></div><DataPackageActions scope="settings" data={settingsPackage(seed)} onImport={(data) => updatePlanningInputs((draft) => applySettingsPackage(draft, data))} /></div></div>
      <nav className="settings-tabs" role="tablist" aria-label="Ayar kategorileri">{SETTINGS_SECTIONS.filter(tab => seed.productionArea !== "cubuk-filtre" || (tab.id !== "setup" && tab.id !== "waits")).map((tab) => <button type="button" key={tab.id} id={tab.id === "weights" ? "settings-tab-materials" : tab.id === "waits" ? "settings-tab-waits" : `settings-tab-${tab.id}`} role="tab" aria-selected={section === tab.id} aria-controls={pistonSettings && ["waits", "setup", "shifts"].includes(tab.id) ? "settings-parameter-controls" : tab.id === "maintenance" || tab.id === "shifts" ? "settings-events" : `settings-${tab.id}`} className={section === tab.id ? "active" : ""} onClick={() => setSection(tab.id)}>{pistonSettings && tab.id === "waits" ? "Akış ve bekleme" : tab.label}</button>)}</nav>
      <section id="settings-stocks" role="tabpanel" aria-labelledby="settings-tab-stocks" hidden={section !== "stocks"}>{section === "stocks" && <ProcessStockSettingsPanel seed={seed} updateSeed={updateMaterials} />}</section>
      {pistonSettings && <div id="settings-parameter-controls" role="tabpanel" aria-labelledby={`settings-tab-${["waits", "setup", "shifts"].includes(section) ? section : "waits"}`} hidden={!["waits", "setup", "shifts"].includes(section)}>
        <FlowSettingsPanel seed={seed} result={result} updateSeed={updatePlanningInputs} canEdit={true} section={section === "setup" ? "SETUP Süreleri" : section === "shifts" ? "Vardiya ve Mesai Bilgileri" : "Akış Ayarı"} active={["waits", "setup", "shifts"].includes(section)} />
        <div hidden={section !== "waits"}><details className="settings-disclosure settings-fallback"><summary>İş günü varsayılanları (yedek kurallar)</summary><p className="settings-help">Yalnızca etkin saat kuralı bulunmayan geçişlerde kullanılır. Yukarıdaki kayıtlı kurallar geçerli kaynağı gösterir.</p><ProcessWaitSettingsPanel seed={seed} updatePlanningInputs={updatePlanningInputs} active={section === "waits"} /></details></div>
      </div>}
      <section id="settings-weights" role="tabpanel" aria-labelledby="settings-tab-materials" hidden={section !== "weights"}>
        <nav className="settings-tabs material-subtabs" role="tablist" aria-label="Hammadde Bilgileri">
          <button id="settings-tab-weights" role="tab" aria-selected={materialSection === "weights"} aria-controls="material-weights-panel" className={materialSection === "weights" ? "active" : ""} onClick={() => { setSection("weights"); setMaterialSection("weights"); }}>Ürün Ağırlıkları</button>
          <button id="settings-tab-consumption" role="tab" aria-selected={materialSection === "consumption"} aria-controls="material-consumption-panel" className={materialSection === "consumption" ? "active" : ""} onClick={() => { setSection("weights"); setMaterialSection("consumption"); }}>Hammadde Tüketim Tablosu</button>
        </nav>
        <div id="material-weights-panel" role="tabpanel" aria-labelledby="settings-tab-weights" hidden={materialSection !== "weights"}>{section === "weights" && materialSection === "weights" && <ProductWeights seed={seed} updateSeed={updateMaterials} />}</div>
        <div id="material-consumption-panel" role="tabpanel" aria-labelledby="settings-tab-consumption" hidden={materialSection !== "consumption"}>{section === "weights" && materialSection === "consumption" && <RawMaterialConsumption seed={seed} result={result} dirty={dirty} updateSeed={updateMaterials} />}</div>
      </section>
      {seed.productionArea === "cubuk-filtre" && (section === "calendar" || section === "shifts") && <><FilterQualityCalendarSettings shifts={seed.filterQualityShifts ?? 1} onChange={(shifts) => updateSeed((draft) => { draft.filterQualityShifts = shifts; })} /><FilterWaitCalendarSettings shifts={seed.filterWaitShifts ?? 1} onChange={(shifts) => updateSeed((draft) => { draft.filterWaitShifts = shifts; })} /></>}
      <section id="settings-calendar" role="tabpanel" aria-labelledby="settings-tab-calendar" hidden={section !== "calendar"}><SettingsCalendar processes={settingsCalendarProcesses(seed)} entries={calendarEntries} today={calendarToday} onEdit={editCalendarEntry} /></section>
      {!pistonSettings && <section id="settings-setup" role="tabpanel" aria-labelledby="settings-tab-setup" hidden={section !== "setup"} className="setup-settings"><div className="setup-settings-heading"><span className="dialog-icon shift"><ArrowsLeftRight size={19} /></span><div><span>SETUP VE ÜRÜN AİLESİ</span><h3>Ürün, çap ve aile geçişlerini üretim saatine dahil edin</h3><p>Aynı ürün 0 saattir. Farklı ürün aynı çapta 1 saat, aynı ailede çap değişirse 2 saat, piston ile Center Pin arasında 5 saat uygulanır. Başlangıç ve ailesi tanımsız ürünler mevcut ayrı süreyi kullanır.</p></div></div><div className="setup-settings-grid"><Field label="Vardiya süresi"><span className="number-with-unit"><input type="number" min="1" max="24" step="0.5" value={setupDraft.shiftHours} onChange={(event) => setSetupDraft({ ...setupDraft, shiftHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Farklı ürün · aynı çap"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.sameDiameterHours} onChange={(event) => setSetupDraft({ ...setupDraft, sameDiameterHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Aynı aile · farklı çap"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.sameFamilyDifferentDiameterHours} onChange={(event) => setSetupDraft({ ...setupDraft, sameFamilyDifferentDiameterHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Piston ↔ Center Pin"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.crossFamilyHours} onChange={(event) => setSetupDraft({ ...setupDraft, crossFamilyHours: Number(event.target.value) })} /><em>saat</em></span></Field><Field label="Başlangıç / tanımsız"><span className="number-with-unit"><input type="number" min="0" step="0.5" value={setupDraft.differentDiameterHours} onChange={(event) => setSetupDraft({ ...setupDraft, differentDiameterHours: Number(event.target.value) })} /><em>saat</em></span></Field><button className="primary" disabled={!setupChanged} onClick={saveSetupSettings}>{setupChanged ? "Ayarları kaydet" : "Güncel"}</button></div></section>}
      <div className="settings-canonical-note" hidden={section !== "maintenance" && section !== "shifts"}><Wrench size={17} /><div><strong>Tüm iş merkezlerinin takvim geçmişi tek yerde</strong><span>Seçili üretim alanının bakım, mesai ve vardiya değişikliklerini seçili kategoride filtreleyebilir; tamamlanan bakımları kaydı silmeden geçmişe taşıyabilirsiniz.</span></div></div>
      <SettingsCalendarWorkspace section={section}>
        <section id="settings-holidays" role="tabpanel" aria-labelledby="settings-tab-holidays" hidden={section !== "holidays"} className="calendar-section holiday-section">
          <div className="calendar-section-title"><CalendarBlank size={19} /><div><h3>Resmi tatiller</h3><p>0 vardiya üretimi durdurur; 1–3 vardiya tatilde üretime izin verir.</p></div></div>
          <div className="calendar-add-row holiday-add"><input value={holidayDraft.name} onChange={(event) => setHolidayDraft({ ...holidayDraft, name: event.target.value })} placeholder="Tatil adı" aria-label="Yeni tatil adı" /><input type="date" value={holidayDraft.date} onChange={(event) => setHolidayDraft({ ...holidayDraft, date: event.target.value })} aria-label="Yeni tatil tarihi" /><select value={holidayDraft.workingShifts} onChange={(event) => setHolidayDraft({ ...holidayDraft, workingShifts: clampShiftCount(Number(event.target.value)) })} aria-label="Tatilde vardiya"><ShiftOptions /></select><button className="primary" onClick={addHoliday}><Plus size={14} /> Ekle</button></div>
          <div className="calendar-table-head holiday-grid"><span>Tatil</span><span>Tarih</span><span>Üretim</span><span /></div>
          <div className="calendar-list">{sortedHolidays.map((holiday) => <div className="calendar-row holiday-grid" key={`${holiday.name}-${holiday.serial}`}><input value={holiday.name} onChange={(event) => updateSeed((draft) => { const target = draft.holidays.find((item) => item.serial === holiday.serial); if (target) target.name = event.target.value; })} aria-label={`${holiday.name} adı`} /><input type="date" value={serialToInputDate(holiday.serial)} onChange={(event) => updateSeed((draft) => { const target = draft.holidays.find((item) => item.serial === holiday.serial); if (target) target.serial = inputDateToSerial(event.target.value); })} aria-label={`${holiday.name} tarihi`} /><select value={holiday.workingShifts ?? 0} onChange={(event) => updateSeed((draft) => { const target = draft.holidays.find((item) => item.serial === holiday.serial); if (target) target.workingShifts = clampShiftCount(Number(event.target.value)); })} aria-label={`${holiday.name} vardiyası`}><ShiftOptions /></select><button className="delete-button" onClick={() => updateSeed((draft) => { draft.holidays = draft.holidays.filter((item) => item.serial !== holiday.serial); })} aria-label={`${holiday.name} tatilini sil`}><Trash size={15} /></button></div>)}</div>
        </section>
        <section id="settings-events" role="tabpanel" aria-labelledby={`settings-tab-${section}`} hidden={section === "holidays"} className="calendar-section exception-section">
          <div className="calendar-section-title"><Wrench size={19} /><div><h3>{section === "maintenance" ? "Planlı bakımlar" : "Mesai ve vardiya değişiklikleri"}</h3><p>Tüm iş merkezlerinde planlı bakım, ek mesai ve vardiya değişikliklerini yönetin; aktif kayıtları ve geçmişi aynı yerden izleyin.</p></div></div>
          <div className="calendar-event-form"><Field label="İş merkezi"><select value={eventDraft.machineId} onChange={(event) => setEventDraft({ ...eventDraft, machineId: event.target.value })}>{calendarResources.map((resource) => <option key={resource.id} value={resource.id}>{settingsCalendarProcessLabel(resource.process)} · {resource.id}</option>)}</select></Field><Field label="Başlangıç"><input type="date" value={eventDraft.start} onChange={(event) => setEventDraft({ ...eventDraft, start: event.target.value, end: event.target.value > eventDraft.end ? event.target.value : eventDraft.end })} /></Field><Field label="Bitiş"><input type="date" min={eventDraft.start} value={eventDraft.end} onChange={(event) => setEventDraft({ ...eventDraft, end: event.target.value })} /></Field><Field label="Açıklama"><input value={eventDraft.name} onChange={(event) => setEventDraft({ ...eventDraft, name: event.target.value })} placeholder={eventDraft.kind === "maintenance" ? "Yıllık bakım" : "Hafta sonu mesaisi"} /></Field>{eventDraft.kind === "shift" && <Field label="Vardiya"><select value={eventDraft.shiftCount} onChange={(event) => setEventDraft({ ...eventDraft, shiftCount: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field>}<button className="primary calendar-event-add" onClick={addCalendarEvent}><Plus size={14} /> Takvime ekle</button></div>
          <div className="calendar-detail-toolbar">{section === "shifts" && <label><span>Tür</span><select value={calendarTypeFilter} onChange={(event) => setCalendarTypeFilter(event.target.value as CalendarDetailType | "all")}><option value="all">Tüm kayıtlar</option><option value="overtime">Mesai</option><option value="shift-change">Vardiya değişikliği</option></select></label>}<label><span>Proses</span><select value={calendarProcessFilter} onChange={(event) => setCalendarProcessFilter(event.target.value as SettingsCalendarProcess | "all")}><option value="all">Tüm prosesler</option>{settingsCalendarProcesses(seed).map(p => <option key={p} value={p}>{settingsCalendarProcessLabel(p)}</option>)}</select></label><label><span>Durum</span><select value={calendarStatusFilter} onChange={(event) => setCalendarStatusFilter(event.target.value as "active" | "completed" | "all")}><option value="active">Aktif kayıtlar</option><option value="completed">Geçmiş</option><option value="all">Aktif + geçmiş</option></select></label><label><span>Başlangıç</span><input type="date" value={calendarFilterStart} onChange={(event) => setCalendarFilterStart(event.target.value)} /></label><label><span>Bitiş</span><input type="date" min={calendarFilterStart || undefined} value={calendarFilterEnd} onChange={(event) => setCalendarFilterEnd(event.target.value)} /></label><button className="calendar-excel-export" disabled={calendarExporting} onClick={() => void exportCalendarEvents()}><FileXls size={15} /> {calendarExporting ? "Hazırlanıyor…" : "Excel indir"}</button></div>
          <div className="calendar-detail-summary"><span><strong>{filteredCalendarEvents.length}</strong> kayıt gösteriliyor</span><span>{calendarEventDetails.filter(({ status }) => status === "active").length} aktif</span><span>{calendarEventDetails.filter(({ status }) => status === "completed").length} geçmiş</span></div>
          {calendarExportError && <div className="dashboard-export-error" role="alert"><Warning size={14} weight="fill" /><span>{calendarExportError}</span><button onClick={() => setCalendarExportError("")}>Kapat</button></div>}
          <div className="calendar-event-list detail-list">{filteredCalendarEvents.length ? filteredCalendarEvents.map(({ event, resource, type, status, automaticallyCompleted }) => (
            <article key={event.id} className={`${event.kind} ${status}`}>
              <span className="calendar-event-icon">{event.kind === "maintenance" ? <Wrench size={14} /> : <Clock size={14} />}</span>
              <div><strong>{event.machineId} · {event.name}</strong><small><ProcessIcon process={resource.process} size={13} /> {settingsCalendarProcessLabel(resource.process)} · {resource.name} · {formatExcelDate(event.start)}{event.end !== event.start ? ` – ${formatExcelDate(event.end)}` : ""}{event.completedAt ? ` · tamamlandı ${new Intl.DateTimeFormat("tr-TR", { dateStyle: "short", timeStyle: "short", timeZone: "Europe/Istanbul" }).format(new Date(event.completedAt))}` : automaticallyCompleted ? " · süresi tamamlandı" : ""}</small></div>
              <em>{type === "maintenance" ? "Planlı bakım" : type === "overtime" ? "Mesai" : "Vardiya değişikliği"}</em>
              <div className="calendar-event-actions">
                {event.kind === "maintenance" && <label className="maintenance-complete-toggle"><input type="checkbox" checked={status === "completed"} onChange={(changeEvent) => updateSeed((draft) => { const target = (draft.calendarEvents ?? []).find((item) => item.id === event.id); if (target) target.completedAt = changeEvent.target.checked ? new Date().toISOString() : undefined; })} /><span>Tamamlandı</span></label>}
                {automaticallyCompleted && <span className="calendar-auto-complete"><CheckCircle size={13} weight="fill" /> Tamamlandı</span>}
                {status === "active" && <button className="edit-button" onClick={() => event.kind === "shift" ? setEditingShiftId(event.id) : setEditingMaintenanceId(event.id)} aria-label={`${event.name} ${event.kind === "shift" ? "vardiya" : "bakım"} kaydını düzenle`}><PencilSimple size={14} /></button>}
                <button className="delete-button" onClick={() => updateSeed((draft) => { if (event.kind === "shift") removeMachineShiftOverrides(draft, [event.machineId], event.start, event.end); else draft.calendarEvents = (draft.calendarEvents ?? []).filter((item) => item.id !== event.id); })} aria-label={`${event.name} kaydını sil`}><Trash size={15} /></button>
              </div>
            </article>
          )) : <p className="calendar-empty">Seçili filtrelerle eşleşen bakım, mesai veya vardiya kaydı yok.</p>}</div>
        </section>
      </SettingsCalendarWorkspace>
    </section>{editingHoliday && <div className="confirmation-backdrop" role="presentation"><section className="completion-dialog" role="dialog" aria-modal="true" aria-label="Resmi tatili düzenle"><CalendarBlank size={24} /><h2>Resmi tatili düzenle</h2><Field label="Tatil adı"><input value={editingHoliday.name} onChange={(event) => setEditingHoliday({ ...editingHoliday, name: event.target.value })} /></Field><Field label="Tatil tarihi"><input type="date" value={editingHoliday.date} onChange={(event) => setEditingHoliday({ ...editingHoliday, date: event.target.value })} /></Field><Field label="Tatilde vardiya"><select value={editingHoliday.shifts} onChange={(event) => setEditingHoliday({ ...editingHoliday, shifts: clampShiftCount(Number(event.target.value)) })}><ShiftOptions /></select></Field>{holidayEditError && <p className="form-error">{holidayEditError}</p>}<div className="drawer-actions"><button className="secondary" onClick={() => setEditingHoliday(null)}>Vazgeç</button><button className="primary" onClick={() => {
      const serial = inputDateToSerial(editingHoliday.date);
      if (!editingHoliday.name.trim() || !serial) { setHolidayEditError("Tatil adı ve tarihi zorunludur."); return; }
      if (seed.holidays.some((holiday) => holiday.serial !== editingHoliday.original && Math.floor(holiday.serial) === serial)) { setHolidayEditError("Bu tarihte zaten bir resmi tatil var."); return; }
      updateSeed((draft) => { const holiday = draft.holidays.find((item) => item.serial === editingHoliday.original); if (holiday) Object.assign(holiday, { name: editingHoliday.name.trim(), serial, workingShifts: editingHoliday.shifts }); });
      setEditingHoliday(null);
    }}>Kaydet</button></div></section></div>}{editingShift && editingShiftMachine && <MachineShiftDialog key={editingShift.id} machine={editingShiftMachine} events={sortedEvents.filter((event) => event.machineId === editingShift.machineId && event.kind === "shift")} initialEvent={editingShift} onClose={() => setEditingShiftId(null)} onSave={(name, start, end, shifts, editingId) => { updateSeed((draft) => { if (editingId) { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); } replaceMachineShiftOverrides(draft, [editingShift.machineId], start, end, shifts, name); }); setEditingShiftId(null); }} onDelete={(eventId) => { updateSeed((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === eventId); if (existing) removeMachineShiftOverrides(draft, [existing.machineId], existing.start, existing.end); }); if (eventId === editingShiftId) setEditingShiftId(null); }} />}{editingMaintenance && editingMaintenanceMachine && <MachineMaintenanceDialog key={editingMaintenance.id} machine={editingMaintenanceMachine} events={sortedEvents.filter((event) => event.machineId === editingMaintenance.machineId && event.kind === "maintenance")} initialEvent={editingMaintenance} onClose={() => setEditingMaintenanceId(null)} onSave={(name, start, end, editingId) => { updateSeed((draft) => { const existing = (draft.calendarEvents ?? []).find((event) => event.id === editingId); if (existing) Object.assign(existing, { name, start, end, shiftCount: 0 }); }); setEditingMaintenanceId(null); }} onDelete={(eventId) => { updateSeed((draft) => { draft.calendarEvents = (draft.calendarEvents ?? []).filter((event) => event.id !== eventId); }); if (eventId === editingMaintenanceId) setEditingMaintenanceId(null); }} />}</>
  );
}


export function FilterWaitCalendarSettings({ shifts, onChange }: { shifts: ShiftCount; onChange: (shifts: ShiftCount) => void }) {
  return <section className="calendar-section" aria-label={FILTER_WAIT_CALENDAR_LABEL}>
    <div className="calendar-section-title"><CalendarBlank size={19} /><div><h3>{FILTER_WAIT_CALENDAR_LABEL}</h3><p>Isıl İşlem ve Fosfatlama beklemeleri bu takvimi kullanır. Bu ayar ortak hat kapasitesi ayırmaz. Tarihe özel değişiklikleri Mesai ve vardiya bölümünde bu takvimi seçerek ekleyin.</p></div></div>
    <Field label="Normal günlerde vardiya"><select aria-label="Çubuk Filtre bekleme vardiyası" value={shifts} onChange={(event) => onChange(clampShiftCount(Number(event.target.value)))}><ShiftOptions /></select></Field>
  </section>;
}


export function SettingsCalendarWorkspace({ section, children }: { section: string; children: ReactNode }) {
  if (!["holidays", "maintenance", "shifts"].includes(section)) return null;
  return <div className="calendar-workspace settings-tab-workspace">{children}</div>;
}


export function FilterQualityCalendarSettings({ shifts, onChange }: { shifts: ShiftCount; onChange: (shifts: ShiftCount) => void }) {
  return <section className="calendar-section" aria-label={FILTER_QUALITY_CALENDAR_LABEL}>
    <div className="calendar-section-title"><CalendarBlank size={19} /><div><h3>{FILTER_QUALITY_CALENDAR_LABEL}</h3><p>Göz Kontrol sonrası ve depo/ambalaj devri öncesi 1 iş günü beklenir. Sonraki açık günde aynı saat kullanılır. Vardiya sayısı bu güne 8 saat eklemez. Tarihe özel değişiklikleri Mesai ve vardiya bölümünde Kalite bekleme takviminden yapın.</p></div></div>
    <Field label="Kalite normal gün vardiyası"><select aria-label="Kalite bekleme vardiyası" value={shifts} onChange={event => onChange(clampShiftCount(Number(event.target.value)))}><ShiftOptions /></select></Field>
    <p className="settings-help">Aylık ihtiyaç dağılımı takvimi normal günlerde 2 vardiya kullanır. Yarım gün için Mesai ve vardiya bölümünde bu takvime 1 vardiya verin. 0 vardiya o günü kapatır.</p>
  </section>;
}

frontend/features/planning/shared/DataPa.source:
"use client";

import { useRaviScreenContext } from "../../ravi/context";
import { useApiFetch } from "@/lib/api";
import { type DataPackageScope, dataPackageSummary } from "@/lib/data-packages";
import { FileXls, UploadSimple, X } from "@phosphor-icons/react";
import { useState } from "react";

export function DataPackageActions({ scope, data, onImport, exportDisabled = false, exportLabel = "Excel indir", importLabel = "Excel yükle" }: { scope: DataPackageScope; data: unknown; onImport: (data: unknown) => void | boolean | Promise<void | boolean>; exportDisabled?: boolean; exportLabel?: string; importLabel?: string }) {
  const apiFetch = useApiFetch();
  const [busy, setBusy] = useState<"export" | "import" | "apply" | null>(null);
  const [pending, setPending] = useState<{ fileName: string; data: unknown; summary: string } | null>(null);
  const [error, setError] = useState("");
  const label = scope === "parameters" ? "Parametreler" : scope === "settings" ? "Ayarlar" : scope === "complete" ? "Parametreler ve Ayarlar" : "Senaryolar";

  useRaviScreenContext(`data-package-${scope}`, { scope, busy, fileName: pending?.fileName, summary: pending?.summary, error });

  async function exportPackage() {
    setBusy("export");
    setError("");
    try {
      const response = await apiFetch("/data-packages/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ scope, data }) });
      if (!response.ok) throw new Error(`${label} Excel dosyası hazırlanamadı.`);
      const blob = await response.blob();
      const disposition = response.headers.get("Content-Disposition") ?? "";
      const filename = disposition.match(/filename="([^"]+)"/)?.[1] ?? `Selsa_${label}.xlsx`;
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Excel dosyası hazırlanamadı.");
    } finally {
      setBusy(null);
    }
  }

  async function readPackage(file: File) {
    setBusy("import");
    setError("");
    try {
      const form = new FormData();
      form.append("file", file);
      const response = await apiFetch(`/data-packages/${scope}/import`, { method: "POST", body: form });
      const payload = await response.json() as { fileName?: string; data?: unknown; detail?: string };
      if (!response.ok) throw new Error(payload.detail || "Excel veri paketi okunamadı.");
      setPending({ fileName: payload.fileName || file.name, data: payload.data, summary: dataPackageSummary(scope, payload.data) });
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Excel veri paketi okunamadı.");
    } finally {
      setBusy(null);
    }
  }

  async function applyImport() {
    if (!pending) return;
    setBusy("apply");
    setError("");
    try {
      if (await onImport(pending.data) !== false) setPending(null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Excel verisi uygulanamadı.");
    } finally {
      setBusy(null);
    }
  }

  return <><div className="data-package-actions"><button className="secondary" disabled={Boolean(busy) || exportDisabled} onClick={() => void exportPackage()}><FileXls size={14} /> {busy === "export" ? "Hazırlanıyor…" : exportLabel}</button><label className={`secondary ${busy === "import" ? "loading" : ""}`}><UploadSimple size={14} /> {busy === "import" ? "Okunuyor…" : importLabel}<input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" disabled={Boolean(busy)} onChange={(event) => { const file = event.target.files?.[0]; if (file) void readPackage(file); event.currentTarget.value = ""; }} /></label>{error && !pending && <span className="data-package-error" role="alert">{error}</span>}</div>{pending && <div className="confirmation-backdrop data-package-backdrop" role="presentation"><section className="operational-dialog data-package-dialog" role="dialog" aria-modal="true" aria-label={`${label} Excel içe aktarma onayı`}><div className="operational-dialog-head"><span className="dialog-icon shift"><FileXls size={20} /></span><div><span>EXCEL İÇE AKTARMA</span><h2>{label} verisini güncelle</h2><p>{pending.fileName}</p></div><button className="delete-button" disabled={busy === "apply"} onClick={() => { setPending(null); setError(""); }} aria-label="Excel içe aktarmayı kapat"><X size={16} /></button></div><div className="data-package-preview"><span>Dosyada bulunan</span><strong>{pending.summary}</strong><p>{scope === "complete" ? "Parametreler ve ayarlar birlikte uygulanır. Siparişler ve çalışan işler korunur. Pasif atamadaki bekleyen işler için karar gerekir. Görünür Excel sayfaları bilgi içindir; içe aktarma dosyanın saklı yedek verisini okur." : scope === "scenarios" ? "Aynı kimliğe sahip senaryolar güncellenir; diğer kayıtlar korunur." : "Bu alandaki mevcut değerler Excel paketindeki yedekle değiştirilecek. Siparişler ve geri bildirimler etkilenmez."}</p>{error && <p className="form-error" role="alert">{error}</p>}</div><div className="drawer-actions"><button className="secondary" disabled={busy === "apply"} onClick={() => { setPending(null); setError(""); }}>Vazgeç</button><button className="primary" disabled={busy === "apply"} onClick={() => void applyImport()}>{busy === "apply" ? "Uygulanıyor…" : "İçe aktar ve uygula"}</button></div></section></div>}</>;
}

frontend/features/planning/shared/Delive.source:
"use client";
import type { ReactNode } from "react";
import type { DeliveryReport } from "@/lib/delivery-report";
import type { DeliveryPlanRange } from "@/lib/delivery-plan";
import { formatInteger } from "@/lib/number-format";
import { HelpTip, PageBarSlot, StatusLine, type StatusItem } from "@/components/ui/primitives";
import { Metric } from "./controls";
import { PlanningErrorNotice } from "./PlanningErrorNotice";
import { signedNumber } from "./format";

export type DeliverySummaryProps = {
  report: DeliveryReport; reportRange: DeliveryPlanRange;
  onReportRangeChange: (range: DeliveryPlanRange) => void; dirty: boolean; hasPlan: boolean;
};

const SCOPE_HELP = "Excel ile aynı kapsam · tablo araması ve filtrelerden bağımsız · adet. Başlangıç ve Bitiş, Teslimat Planı Excel’indeki rapor dönemini seçer.";

/**
 * Teslimat Planı summary. The numbers render as one compact row (or in the page title row
 * with `metricsInPageBar`); period, order date and notices stay inline as one scope row and
 * one status line.
 */
export function DeliverySummary({ report, reportRange, onReportRangeChange, dirty, hasPlan, metricsInPageBar = false, aside, extraStatus = [] }: DeliverySummaryProps & { metricsInPageBar?: boolean; aside?: ReactNode; extraStatus?: StatusItem[] }) {
  const reportUnavailable = Boolean(report.error) || !report.payload;
  const coverage = report.coverage == null ? "—" : `%${(report.coverage * 100).toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const metrics = !reportUnavailable ? <div className="delivery-report-metrics compact" aria-label="Teslimat Planı sayıları">
    <Metric compact label="Sipariş miktarı" value={formatInteger(report.demand!)} detail={`${report.types!.listed} tip · ${report.types!.demand} siparişli`} description="Teslimat Planı Excel’indeki Sipariş Adeti toplamı." />
    <Metric compact label="Planlanan teslimat miktarı" value={formatInteger(report.total!)} detail={`${report.types!.total} tip · dönem gerçekleşen + plan`} description={`Teslim edilen miktar ${formatInteger(report.delivered!)} (${report.types!.delivered} tip · sipariş sonrası) + Kalan teslimat miktarı ${formatInteger(report.remaining!)} (${report.types!.remaining} tip · dönem içi plan).`} />
    <Metric compact label="Fark" value={signedNumber(report.difference!)} detail={`${report.types!.covered} tipte karşılandı / fazla`} description="Planlanan teslimat miktarı − Sipariş miktarı. Artı fazla, eksi eksik." tone={report.difference! < 0 ? "danger" : "default"} />
    <Metric compact label="Karşılanamayan miktar" value={signedNumber(report.shortage!)} detail={`${report.types!.shortage} tip`} description="Ürün bazında eksik kalan miktarların toplamı; bir ürünün fazlası başka ürünün eksiğini kapatmaz." tone={report.shortage! !== 0 ? "danger" : "default"} />
    <Metric compact label="Karşılama oranı" value={coverage} detail="Ürün bazında eksik miktara göre" description="Karşılanan sipariş miktarının Sipariş miktarına oranı." />
  </div> : null;
  const status: StatusItem[] = [...extraStatus];
  if (dirty) status.push({ id: "dirty", tone: "info", title: "Plan girdileri değişti.", detail: "Teslimat tahmini kayıtlı işler ve güncel proses bilgileriyle hesaplanır; öncelikler ve üretim adetleri korunur." });
  if (report.undated.length) status.push({ id: "undated", tone: "warn", title: `Teslim tarihi belirlenemeyen miktar: ${formatInteger(report.undatedQuantity!)} adet`,
    detail: "Bu miktarlar haftalık teslimat tahminine dahil değildir. Eksikler çözülmeden tam teslimat planı indirilemez.",
    action: <details className="delivery-undated-details"><summary>Tarihi bekleyen işler</summary><ul>{report.undated.map(row => <li key={row.id}>{row.workOrder || row.product} · {formatInteger(row.quantity)} adet · {[...new Set(row.reasons.map(reason => reason.message))].join("; ")}</li>)}</ul></details> });
  if (!reportUnavailable && !hasPlan && !dirty) status.push({ id: "no-plan", tone: "info", title: "Plan henüz çalıştırılmadı.", detail: "Mevcut üretim ve teslimatlar gösteriliyor." });
  return <section className="delivery-summary sade" aria-label="Teslimat Planı özeti">
    <div className="delivery-report-scope">
      <span className="delivery-report-title"><strong>Teslimat Planı</strong><HelpTip text={SCOPE_HELP} align="start" /></span>
      <label>Başlangıç<input aria-label="Teslimat özeti başlangıç" type="date" value={reportRange.startDate} onChange={(e) => onReportRangeChange({ ...reportRange, startDate: e.target.value })} /></label>
      <label>Bitiş<input aria-label="Teslimat özeti bitiş" type="date" value={reportRange.endDate} onChange={(e) => onReportRangeChange({ ...reportRange, endDate: e.target.value })} /></label>
      <small className="delivery-report-order-date">Sipariş tarihi: {reportUnavailable ? "Hesaplanamadı" : report.payload?.orderDate || "Manuel sipariş"}</small>
      {aside && <div className="delivery-report-aside">{aside}</div>}
    </div>
    {metrics && (metricsInPageBar ? <PageBarSlot>{metrics}</PageBarSlot> : metrics)}
    {status.length > 0 && <StatusLine items={status} label="Siparişler uyarıları" />}
    {reportUnavailable && <PlanningErrorNotice message={report.error || "Teslimat raporu hesaplanamadı."} />}
  </section>;
}

frontend/features/planning/shared/Manual.source:
"use client";

import { useEffect, useState } from "react";
import { Plus, X } from "@phosphor-icons/react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { Field } from "./controls";
import { formatInteger } from "@/lib/number-format";
import { manualBatchMachineChoices, manualBatchPlanSignature, manualBatchProductError, manualBatchProtectedCount, type PlanningSeed, type ScenarioResult } from "@/lib/planning";

export type ManualBatchSave = (product: string, machineId: string, quantity: number, position: number, expectedSignature: string) => void;

export function ManualBatchDialog({ seed, result, dirty, initialProduct = "", initialMachineId = "", entryPoint, onClose, onSave }: {
  seed: PlanningSeed; result: ScenarioResult; dirty: boolean; initialProduct?: string; initialMachineId?: string;
  entryPoint: string; onClose: () => void; onSave: ManualBatchSave;
}) {
  const products = [...seed.products].sort((a, b) => a.product.localeCompare(b.product, "tr"));
  const first = products.find(product => product.product === initialProduct)
    ?? products.find(product => manualBatchMachineChoices(seed, product.product).some(choice => !choice.reason && choice.machine.id === initialMachineId))
    ?? products[0];
  const initialChoices = first ? manualBatchMachineChoices(seed, first.product) : [];
  const [productCode, setProductCode] = useState(first?.product ?? "");
  const [query, setQuery] = useState("");
  const [machineId, setMachineId] = useState(initialChoices.find(choice => !choice.reason && choice.machine.id === initialMachineId)?.machine.id ?? initialChoices.find(choice => !choice.reason)?.machine.id ?? "");
  const [quantity, setQuantity] = useState(first?.batchSize ?? 0);
  const [position, setPosition] = useState(() => result.batches.filter(batch => batch.status === "planned" && batch.machineId === machineId).length);
  const [expectedSignature] = useState(() => manualBatchPlanSignature(seed, result));
  const [error, setError] = useState("");
  const product = products.find(item => item.product === productCode);
  const choices = product ? manualBatchMachineChoices(seed, product.product) : [];
  const selectedChoice = choices.find(choice => choice.machine.id === machineId);
  const visibleProducts = products.filter(item => item.product.toLocaleLowerCase("tr").includes(query.trim().toLocaleLowerCase("tr")));
  const queue = result.batches.filter(batch => batch.status === "planned" && batch.machineId === machineId).sort((a, b) => a.planColumn - b.planColumn);
  const protectedCount = manualBatchProtectedCount(seed, queue);
  const stale = expectedSignature !== manualBatchPlanSignature(seed, result);
  const parameterError = manualBatchProductError(product) ?? (!choices.length ? "Bu tip için Parametreler’de planlanabilir tezgah tanımlayın." : selectedChoice?.reason);
  const validQuantity = Number.isSafeInteger(quantity) && quantity > 0;
  const valid = Boolean(product && selectedChoice && !parameterError && validQuantity && position >= protectedCount && position <= queue.length && !stale);
  const orderQuantity = seed.orders.filter(order => order.product.toUpperCase() === productCode.toUpperCase()).reduce((total, order) => total + Math.max(0, order.quantity), 0);

  useRaviScreenContext("manual-batch", { entryPoint, query, product: productCode, machineId, quantity, standardBatchSize: product?.batchSize,
    position: position + 1, queueLength: queue.length, protectedCount, orderQuantity, dirty, stale, error, parameterError,
    machines: choices.map(choice => ({ id: choice.machine.id, reason: choice.reason })), visibleProducts: visibleProducts.slice(0, 12).map(item => item.product), visibleProductCount: visibleProducts.length });
  useEffect(() => {
    const escape = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    window.addEventListener("keydown", escape);
    return () => window.removeEventListener("keydown", escape);
  }, [onClose]);

  function selectMachine(id: string) {
    setMachineId(id);
    setPosition(result.batches.filter(batch => batch.status === "planned" && batch.machineId === id).length);
    setError("");
  }
  function selectProduct(code: string) {
    const next = products.find(item => item.product === code);
    setProductCode(code); setQuantity(next?.batchSize ?? 0); setError("");
    const nextChoices = next ? manualBatchMachineChoices(seed, code) : [];
    selectMachine(nextChoices.find(choice => !choice.reason && choice.machine.id === machineId)?.machine.id ?? nextChoices.find(choice => !choice.reason)?.machine.id ?? "");
  }

  return <div className="confirmation-backdrop" role="presentation"><section className="operational-dialog quick-manual-dialog" role="dialog" aria-modal="true" aria-label="Manuel şarj ekle">
    <div className="operational-dialog-head"><span className="dialog-icon manual"><Plus size={20} /></span><div><span>MANUEL PLANLAMA</span><h2>Manuel şarj ekle</h2><p>Tipi, parametrelerde tanımlı tezgahı ve kuyruk sırasını seçin.</p></div><button className="delete-button" onClick={onClose} aria-label="Manuel şarj penceresini kapat"><X size={16} /></button></div>
    <div className="operational-dialog-form quick-manual-form">
      <div className="manual-batch-product-search"><Field label="Tip no ara"><input type="search" autoFocus value={query} placeholder="Örn. R902972557" onChange={event => {
        const value = event.target.value; setQuery(value);
        const matches = products.filter(item => item.product.toLocaleLowerCase("tr").includes(value.trim().toLocaleLowerCase("tr")));
        if (!matches.some(item => item.product === productCode)) selectProduct(matches[0]?.product ?? "");
      }} /></Field></div>
      <Field label="Tip no"><select value={productCode} onChange={event => selectProduct(event.target.value)}><option value="" disabled>{visibleProducts.length ? "Tip seçin" : "Aramaya uygun tip yok"}</option>{visibleProducts.map(item => <option key={item.product} value={item.product}>{item.product}</option>)}</select></Field>
      <Field label="Tezgah"><select value={machineId} onChange={event => selectMachine(event.target.value)}><option value="" disabled>Tezgah seçin</option>{choices.map(({ machine, reason }) => <option key={machine.id} value={machine.id} disabled={Boolean(reason)}>{machine.id} · {machine.name}{reason ? ` — ${reason}` : ""}</option>)}</select></Field>
      <Field label="Adet"><input type="number" min={1} step={1} value={quantity || ""} onChange={event => { setQuantity(Number(event.target.value)); setError(""); }} /><small>Standart şarj: {formatInteger(product?.batchSize ?? 0)} adet. İsterseniz değiştirebilirsiniz.</small></Field>
      <Field label="Kuyruk sırası"><select value={position} onChange={event => { setPosition(Number(event.target.value)); setError(""); }}>{Array.from({ length: queue.length + 1 }, (_, index) => <option key={index} value={index} disabled={index < protectedCount}>{index + 1}. sıra{index < protectedCount ? " · Korunan işlerin önüne eklenemez" : index === queue.length ? " · Kuyruğun sonu" : ` · ${queue[index].product} öncesi`}</option>)}</select></Field>
      <div className="manual-batch-preview"><span><small>Standart şarj</small><strong>{formatInteger(product?.batchSize ?? 0)} adet</strong></span><span><small>Eklenecek adet</small><strong>{validQuantity ? formatInteger(quantity) : "—"}</strong></span><span><small>Tezgah kuyruğu</small><strong>{queue.length} planlı şarj</strong></span></div>
      <p className="manual-batch-help">Girilen adet, seçilen sıraya tek bir şarj olarak eklenir. Sonraki kilitsiz işler takvime göre yeniden yerleştirilir.{orderQuantity === 0 && product ? " Bu tip için aktif sipariş yok; manuel ekleme sipariş adedini değiştirmez." : ""}</p>
      {dirty && <p className="manual-batch-help">Plan yeniden hesaplanmayı bekliyor. Manuel eklemeden sonra bu uyarı korunur.</p>}
      {!products.length && <p className="form-error">Henüz tanımlı tip yok. Parametreler’den ürün ekleyin.</p>}
      {parameterError && product && <p className="form-error">{parameterError}</p>}
      {choices.length > 0 && !selectedChoice && <p className="form-error">Ürünün tanımlı tezgahları şu anda kullanılamıyor. Tezgah seçeneklerindeki açıklamaları kontrol edin.</p>}
      {!validQuantity && <p className="form-error">Adet pozitif bir tam sayı olmalıdır.</p>}
      {stale && <p className="form-error" role="alert">Plan veya parametreler değişti. Manuel şarj penceresini yeniden açın.</p>}
      {error && <p className="form-error" role="alert">{error}</p>}
      <div className="drawer-actions"><button className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!valid} onClick={() => {
        try { onSave(productCode, machineId, quantity, position, expectedSignature); onClose(); }
        catch (reason) { setError(reason instanceof Error ? reason.message : "Şarj eklenemedi."); }
      }}><Plus size={14} /> Şarjı kuyruğa ekle</button></div>
    </div>
  </section></div>;
}

frontend/features/planning/shared/Planni.source:
"use client";
import { createContext, useContext } from "react";

export const IdentityReviewActionContext = createContext<(() => void) | undefined>(undefined);

/** Present the existing validation failure; never infer or repair charge identity. */
export function PlanningErrorNotice({ message }: { message: string }) {
  const onReview = useContext(IdentityReviewActionContext);
  const marker = ": mevcut üretim/arşiv ile kuyruktaki şarj kimliği belirsiz.";
  const boundary = message.indexOf(marker);
  if (boundary < 0) return <p role="alert" className="form-error">{message}</p>;
  return <div role="alert" className="planning-identity-notice">
    <strong>Şarj kaydı kontrol edilmeli — {message.slice(0, boundary)}</strong>
    <p>Bu şarjın ayrı bir üretim işi mi, yoksa kuyrukta, mevcut üretimde veya arşivde bulunan aynı işin tekrar kaydı mı olduğu doğrulanamıyor.</p>
    <p><b>Çözülene kadar:</b> Bu şarj ve bağlantılı kayıtları değiştirilemez; bağlantısız üretim işlemleri devam edebilir. Tüm planı yeniden oluşturmak ve tam teslimat raporu indirmek için çakışma çözülmelidir. Mevcut kayıtlar ve kuyruk korunur; belirsiz adetler güvenilir bir teslimat toplamı olarak sunulmaz.</p>
    <p><b>Nasıl giderilir?</b> İncele ve düzelt ile kuyruk, mevcut üretim ve Üretim arşivi kayıtlarını karşılaştırın. İş emrini, ürünü, tezgahı ve ilk şarj adedini doğrulayın. Yanlış iş emrini düzeltin veya aynı fiziksel işin tekrar kaydı olduğunu doğruladığınız kuyruk kaydını kaldırın. Başlamış veya başka proseslere bağlı kayıtlar ayrıca incelenmelidir. Yalnızca planı yeniden çalıştırmak sorunu çözmez.</p>
    {onReview && <button type="button" className="secondary" onClick={onReview}>İncele ve düzelt</button>}
  </div>;
}

/** Keep an unrelated report failure and the global charge warning independently visible. */
export function QueueIdentityNotice({ issue, inlineError }: { issue: string | null; inlineError?: string }) {
  if (!issue || issue === inlineError) return null;
  return <PlanningErrorNotice message={issue} />;
}

frontend/features/planning/shared/Proces.source:
"use client";

import { useEffect, useId, useRef, useState } from "react";
import { ArrowDown, ArrowRight, ArrowUp } from "@phosphor-icons/react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { ProcessIcon } from "@/components/ProcessIcon";
import { processLabel, type ProcessKind } from "@/lib/process-master-data";
import { excelSerialToDate } from "@/lib/planning";
import type { PlacementDeliveryWarning, ProcessGanttPlacementPreview } from "@/lib/process-planning";

export type PlacementPreview = { valid: true; preview: ProcessGanttPlacementPreview } | { valid: false; reason: string };

export function ProcessPlacementReview({ request, preview, process, dirty, error, onClose, onApply }: {
  request: { requestedStart?: number; resourceId: string };
  preview: PlacementPreview | null;
  process: ProcessKind;
  dirty: boolean;
  error: string;
  onClose: () => void;
  onApply: () => void;
}) {
  const deliveryWarnings = preview?.valid && process !== "turning" && preview.preview.seed.productionArea !== "cubuk-filtre" ? preview.preview.deliveryWarnings ?? [] : [];
  const impactListId = useId();
  const impactListRef = useRef<HTMLDivElement | null>(null);
  const impactContentRef = useRef<HTMLDivElement | null>(null);
  const [impactScroll, setImpactScroll] = useState({ overflow: false, moreBelow: false });
  useEffect(() => {
    const list = impactListRef.current;
    const content = impactContentRef.current;
    if (!list || !content) { setImpactScroll({ overflow: false, moreBelow: false }); return; }
    const update = () => {
      const overflow = list.scrollHeight > list.clientHeight + 2;
      const moreBelow = overflow && list.scrollTop + list.clientHeight < list.scrollHeight - 2;
      setImpactScroll((previous) => previous.overflow === overflow && previous.moreBelow === moreBelow ? previous : { overflow, moreBelow });
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(list);
    observer.observe(content);
    list.addEventListener("scroll", update, { passive: true });
    return () => { observer.disconnect(); list.removeEventListener("scroll", update); };
  }, [preview]);
  useRaviScreenContext("placement-review-scroll", { deliveryWarningCount: deliveryWarnings.length, deliveryWarnings: deliveryWarnings.slice(0, 20), impactCount: preview?.valid ? preview.preview.affectedOperations.length : 0, ...impactScroll });
  function scrollImpacts() {
    const list = impactListRef.current;
    if (!list) return;
    const behavior = window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth";
    if (impactScroll.moreBelow) list.scrollBy({ top: Math.max(100, list.clientHeight * 0.8), behavior });
    else list.scrollTo({ top: 0, behavior });
  }
  const cancelRef = useRef<HTMLButtonElement | null>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    cancelRef.current?.focus();
    return () => { if (previous?.isConnected) previous.focus({ preventScroll: true }); };
  }, []);
  return <div className="confirmation-backdrop"><section className="process-placement-dialog" role="dialog" aria-modal="true" aria-label="Proses yerleşimini incele" onKeyDown={(event) => {
        if (event.key === "Escape") { event.stopPropagation(); onClose(); return; }
        if (event.key !== "Tab") return;
        const buttons = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("button:not(:disabled), [tabindex=\"0\"]"));
        const first = buttons[0], last = buttons.at(-1);
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
      }}><ProcessIcon process={process} size={25} /><h2>Proses yerleşimini incele</h2>
        {dirty && <p className="form-error">Plan girdileri değişmiş. Önizleme mevcut Torna planına göre hesaplanır; taşıma bu uyarıyı kaldırmaz.</p>}
        {preview?.valid ? <>
          <p><strong>{preview.preview.operation.workOrder || preview.preview.operation.product}</strong> · {processLabel(process)} · {request.resourceId} · {preview.preview.insertionIndex + 1}. sıra</p>
          <dl><div><dt>İstenen başlangıç</dt><dd>{placementDate(preview.preview.requestedStart)}</dd></div><div><dt>Hesaplanan başlangıç</dt><dd>{placementDate(preview.preview.operation.start)}</dd></div><div><dt>Hesaplanan bitiş</dt><dd>{placementDate(preview.preview.operation.end)}</dd></div></dl>
          <PlacementDeliveryWarnings warnings={deliveryWarnings} />
          {preview.preview.adjustments.map((reason) => <p className="placement-adjustment" key={reason}>{reason}</p>)}
          <p>{preview.preview.affectedOperations.length} diğer proses adımının tarihi/iş merkezi değişir.</p>
          {!!preview.preview.affectedOperations.length && <div className="placement-impact-browser"><div className={`placement-impact-viewport ${impactScroll.moreBelow ? "has-more-below" : ""}`}><div id={impactListId} ref={impactListRef} className="placement-impact-list" tabIndex={0} role="region" aria-label="Etkilenen proses adımları"><div ref={impactContentRef}>{preview.preview.affectedOperations.map(({ before, after }) => <article key={before.id}>
            <strong className="placement-impact-title"><ProcessIcon process={after.process} size={15} /> {after.workOrder || after.product} · {processLabel(after.process)}</strong>
            <div className="placement-comparison">
              <section className="placement-version placement-version-before" aria-label="Önce · Mevcut plan">
                <header><span className="placement-version-label">Önce</span><span>Mevcut plan</span></header>
                <dl className="placement-version-details">
                  <div><dt>Tezgâh</dt><dd>{before.resourceId}</dd></div>
                  <div><dt>Başlangıç</dt><dd>{placementDate(before.start)}</dd></div>
                  <div><dt>Bitiş</dt><dd>{placementDate(before.end)}</dd></div>
                </dl>
              </section>
              <ArrowRight className="placement-comparison-arrow" size={18} aria-hidden="true" />
              <section className="placement-version placement-version-after" aria-label="Sonra · Yeni plan">
                <header><span className="placement-version-label">Sonra</span><span>Yeni plan</span></header>
                <dl className="placement-version-details">
                  <div><dt>Tezgâh</dt><dd className={before.resourceId !== after.resourceId ? "placement-value-changed" : undefined}>{after.resourceId}{before.resourceId !== after.resourceId && <small className="placement-resource-change">Değişti</small>}</dd></div>
                  <div><dt>Başlangıç</dt><dd className={Math.abs(before.start - after.start) > 1e-8 ? "placement-value-changed" : undefined}>{placementDate(after.start)}</dd></div>
                  <div><dt>Bitiş</dt><dd className={Math.abs(before.end - after.end) > 1e-8 ? "placement-value-changed" : undefined}>{placementDate(after.end)}</dd></div>
                </dl>
              </section>
            </div>
          </article>)}</div></div></div>
            {impactScroll.overflow && <div className="placement-scroll-guide">
              <span>{impactScroll.moreBelow ? "Diğer adımlar aşağıda" : "Listenin sonu"} · Toplam {preview.preview.affectedOperations.length} adım</span>
              <button type="button" aria-controls={impactListId} onClick={scrollImpacts}>
                {impactScroll.moreBelow ? <>Devamını gör <ArrowDown size={15} aria-hidden="true" /></> : <>Başa dön <ArrowUp size={15} aria-hidden="true" /></>}
              </button>
            </div>}
          </div>}
        </> : <p role="alert" className="form-error">{preview?.reason}</p>}
        {error && <p role="alert" className="form-error">{error}</p>}
        <div className="drawer-actions"><button ref={cancelRef} className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!preview?.valid} onClick={onApply}>Yerleşimi uygula</button></div>
      </section></div>;
}

export function PlacementDeliveryWarnings({ warnings }: { warnings: PlacementDeliveryWarning[] }) {
  if (!warnings.length) return null;
  return <section className="placement-adjustment" role="status" aria-label="Termin uyarısı">
    <h3>Termin uyarısı</h3><p>Yerleşim uygundur. Termin gecikmesi taşımayı engellemez.</p>
    {warnings.map(item => <p key={`${item.batchId}:${item.dueDate}`}><strong>{item.workOrder || item.batchId} · {item.product}</strong><br />Termin: {item.dueDate} · {item.lateDays} gün gecikme<br />Teslimata hazır · Önce: {item.beforeReadyAt > 0 ? placementDate(item.beforeReadyAt) : "Hesaplanamadı"} · Sonra: {placementDate(item.afterReadyAt)}</p>)}
  </section>;
}

export function placementDate(serial: number): string { return new Intl.DateTimeFormat("tr-TR", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "UTC" }).format(new Date(Math.round(excelSerialToDate(serial).getTime() / 1000) * 1000)); }

frontend/features/planning/shared/RouteP.source:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { ProcessIcon } from "@/components/ProcessIcon";
import { useRaviScreenContext } from "@/features/ravi/context";
import { isMachineEligibleForProduct, excelSerialToDate, type PlanningSeed, type ScenarioResult } from "@/lib/planning";
import { activeProcessResourceIds, processLabel, type DownstreamProcess } from "@/lib/process-master-data";
import { defaultRoutePlacementOptions, previewRoutePlacement, routeInputSignature, routePlacementSubject, type RoutePlacementOptions, type RoutePlacementPreview, type RoutePlacementRequest } from "@/lib/route-placement";
import { PlacementDeliveryWarnings, placementDate } from "./ProcessPlacementReview";

function dateInput(serial: number) { return excelSerialToDate(serial).toISOString().slice(0, 16); }
function dateSerial(value: string) { return (Date.parse(`${value}:00Z`) - Date.UTC(1899, 11, 30)) / 86400000; }

export function RoutePlacementDialog({ seed, result, request, dirty, onClose, onApply }: {
  seed: PlanningSeed; result: ScenarioResult; request: RoutePlacementRequest; dirty: boolean;
  onClose: () => void; onApply: (preview: RoutePlacementPreview) => void;
}) {
  const [snapshot, setSnapshot] = useState(() => ({ seed: structuredClone(seed), result: structuredClone(result) }));
  const [draftRequest, setDraftRequest] = useState(request);
  const subject = useMemo(() => { try { return routePlacementSubject(snapshot.seed, snapshot.result, draftRequest); } catch { return null; } }, [snapshot, draftRequest]);
  const [options, setOptions] = useState<RoutePlacementOptions>(() => { try { return defaultRoutePlacementOptions(seed, result, request); } catch { return { propagate: true, targetDate: "", stages: {} }; } });
  const [error, setError] = useState("");
  const stale = routeInputSignature(seed, result) !== routeInputSignature(snapshot.seed, snapshot.result);
  const calculated = useMemo(() => { try { return { preview: previewRoutePlacement(snapshot.seed, snapshot.result, draftRequest, options), error: "" }; } catch (error) { return { preview: null, error: error instanceof Error ? error.message : "Önizleme hesaplanamadı." }; } }, [snapshot, draftRequest, options]);
  const preview = calculated.preview;
  const deliveryWarnings = snapshot.seed.productionArea !== "cubuk-filtre" && subject?.operation.process !== "turning" ? preview?.deliveryWarnings ?? [] : [];
  const closeRef = useRef<HTMLButtonElement>(null);
  useEffect(() => { const previous = document.activeElement as HTMLElement | null; closeRef.current?.focus(); return () => { if (previous?.isConnected) previous.focus(); }; }, []);
  useRaviScreenContext("route-placement", { deliveryWarningCount: deliveryWarnings.length, deliveryWarnings: deliveryWarnings.slice(0, 20), dialog: "Üretim akışını düzenle", request: draftRequest, options, stale, dirty, selectedBatchId: subject?.job.batchId, beforeDeliveryReadyAt: preview?.beforeJob.deliveryReadyAt, afterDeliveryReadyAt: preview?.afterJob.deliveryReadyAt, targetMet: preview?.targetMet, affectedOperations: preview?.affectedOperations, affectedOrders: preview?.affectedOrders, error: error || calculated.error });
  const selectedParameter = subject && snapshot.seed.processMasterData?.products.find((item) => item.product === subject.job.product)?.processes.find((item) => item.process === subject.operation.process);
  const selectedResources = selectedParameter ? activeProcessResourceIds(selectedParameter) : [];
  const editable = (sequence: number) => !options.release && subject && (draftRequest.kind === "edit" && sequence === subject.operation.sequence || options.propagate && sequence > subject.operation.sequence);
  return <div className="confirmation-backdrop"><section className="process-placement-dialog route-placement-dialog" role="dialog" aria-modal="true" aria-label="Üretim akışını düzenle" onKeyDown={event => {
    if (event.key === "Escape") { event.stopPropagation(); onClose(); }
    if (event.key !== "Tab") return;
    const inputs = Array.from(event.currentTarget.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), [tabindex="0"]'));
    if (event.shiftKey && document.activeElement === inputs[0]) { event.preventDefault(); inputs.at(-1)?.focus(); }
    else if (!event.shiftKey && document.activeElement === inputs.at(-1)) { event.preventDefault(); inputs[0]?.focus(); }
  }}>
    <header><h2>Üretim akışını düzenle</h2><p>{subject?.job.workOrder || subject?.job.product} · {subject?.job.quantity.toLocaleString("tr-TR")} adet · {subject?.job.batchId}</p></header>
    <div className="route-placement-content">
      {draftRequest.kind === "edit" && <label className="route-release-choice"><input type="checkbox" checked={Boolean(options.release)} onChange={event => setOptions({ ...options, release: event.target.checked })} /> Bu şarjın akış tercihlerini kaldır · Otomatik planlamaya dön</label>}
      {options.release && <p className="placement-adjustment">Bu şarjın kaydedilmiş proses yerleşimleri ve Torna planında tutma tercihi kaldırılır. Aşağıdaki sonuç incelendikten sonra uygulanır; çalışan ve tamamlanan işler korunur.</p>}
      {dirty && <p className="placement-adjustment">Plan girdileri değişmiş. Bu işlem mevcut Torna planını kullanır; yeniden hesaplama uyarısı korunur.</p>}
      {stale && <p role="alert" className="form-error">Plan veya girdiler değişti. Uygulamadan önce önizlemeyi yenileyip etkileri tekrar inceleyin. <button className="secondary" onClick={() => { setSnapshot({ seed: structuredClone(seed), result: structuredClone(result) }); setError(""); }}>Önizlemeyi yenile</button></p>}
      <div className="route-placement-options"><label>Değişiklik kapsamı<select disabled={subject?.interrupted} value={options.propagate ? "route" : "single"} onChange={event => setOptions({ ...options, propagate: event.target.value === "route" })}><option value="route">Sonraki proseslerde de öne al</option><option value="single">Yalnız bu prosesi değiştir</option></select></label>
        <label>Hedef teslim tarihi<input disabled={subject?.interrupted} type="date" value={options.targetDate} onChange={event => setOptions({ ...options, targetDate: event.target.value })} /><small>İç planlama hedefi; siparişin Termin bilgisi değişmez.</small></label></div>
      {draftRequest.kind === "edit" && draftRequest.process === "turning" && subject && !options.release && <button className="secondary" onClick={() => setDraftRequest({ kind: "turning", batchId: draftRequest.batchId, resourceId: subject.operation.resourceId, position: snapshot.result.batches.filter(batch => batch.machineId === subject.operation.resourceId && batch.status === "planned").sort((a, b) => a.planColumn - b.planColumn).findIndex(batch => batch.id === draftRequest.batchId) })}>Torna yerleşimini de değiştir</button>}
      {draftRequest.kind === "turning" && <div className="route-placement-options"><label>Torna tezgâhı<select value={draftRequest.resourceId} onChange={event => setDraftRequest({ ...draftRequest, resourceId: event.target.value })}>{snapshot.seed.machines.filter(machine => machine.active && subject && isMachineEligibleForProduct(snapshot.seed, machine.id, subject.job.product)).map(machine => <option key={machine.id} value={machine.id}>{machine.id}</option>)}</select></label><label>Kuyruk sırası<input type="number" min={1} value={draftRequest.position + 1} onChange={event => setDraftRequest({ ...draftRequest, position: Math.max(0, Number(event.target.value) - 1) })} /></label></div>}
      {(draftRequest.kind === "queue" || draftRequest.kind === "process") && subject && <div className="route-placement-options"><label>{processLabel(subject.operation.process)} · İş merkezi<select value={draftRequest.resourceId} onChange={event => setDraftRequest({ ...draftRequest, resourceId: event.target.value })}>{selectedResources.map(id => <option key={id} value={id}>{id}</option>)}</select></label>{draftRequest.kind === "process" ? <label>İstenen başlangıç<input type="datetime-local" value={Number.isFinite(draftRequest.requestedStart) ? dateInput(draftRequest.requestedStart) : ""} onChange={event => setDraftRequest({ ...draftRequest, requestedStart: dateSerial(event.target.value) })} /></label> : <label>Kuyruk sırası<input type="number" min={1} placeholder="En sona" value={draftRequest.position === "end" ? "" : draftRequest.position + 1} onChange={event => setDraftRequest({ ...draftRequest, position: event.target.value ? Math.max(0, Number(event.target.value) - 1) : "end" })} /></label>}</div>}
      {subject?.interrupted && <p className="placement-adjustment">Üretime ara verildi. Yalnız seçili proses yerleştirilir; sonraki prosesler için ayrıca manuel seçim gerekir. Üretime başlarken onay sorulur.</p>}
      <p>Öncelikli adım, hazır olduğu en erken uygun boşluğa yerleşir. Diğer kuyruktaki işler kayabilir. Vardiya, tatil, bakım ve zorunlu beklemeler hesaplanır.</p>
      <div className="route-placement-table" tabIndex={0}><table><thead><tr><th>Proses</th><th>Yerleşim tercihi</th><th>Önce</th><th>Sonra</th></tr></thead><tbody>{subject?.job.operations.map(before => {
        const after = preview?.afterJob.operations.find(item => item.id === before.id);
        const process = before.process as DownstreamProcess;
        const choice = options.stages[process] ?? { mode: "priority" as const, resourceId: before.resourceId, requestedStart: before.start };
        const enabled = before.process !== "turning" && !before.actual && !before.current && editable(before.sequence);
        const parameter = snapshot.seed.processMasterData?.products.find(item => item.product === before.product)?.processes.find(item => item.process === before.process);
        const resources = parameter ? activeProcessResourceIds(parameter) : [];
        return <tr key={before.id}><th><ProcessIcon process={before.process} size={17} /> {processLabel(before.process)}{(before.actual || before.current) && <small>{before.actual ? "Tamamlandı" : "Çalışıyor"} · Sabit</small>}</th><td>{enabled ? <><select aria-label={`${processLabel(process)} yerleşim tercihi`} value={choice.mode} onChange={event => setOptions({ ...options, stages: { ...options.stages, [process]: { ...choice, mode: event.target.value as typeof choice.mode } } })}><option value="priority">Öncelikli planla</option><option value="keep">Mevcut yerleşimi koru</option><option value="manual">Elle yerleştir</option></select>{choice.mode === "manual" && <><select aria-label={`${processLabel(process)} iş merkezi`} value={choice.resourceId ?? before.resourceId} onChange={event => setOptions({ ...options, stages: { ...options.stages, [process]: { ...choice, resourceId: event.target.value } } })}>{resources.map(id => <option key={id} value={id}>{id}</option>)}</select><input aria-label={`${processLabel(process)} istenen başlangıç`} type="datetime-local" value={Number.isFinite(choice.requestedStart ?? before.start) ? dateInput(choice.requestedStart ?? before.start) : ""} onChange={event => setOptions({ ...options, stages: { ...options.stages, [process]: { ...choice, requestedStart: dateSerial(event.target.value) } } })} /></>}</> : before.id === subject.operation.id ? "Seçilen taşıma" : "Mevcut kurallar"}</td><td>{before.resourceId}<small>{placementDate(before.start)}<br />{placementDate(before.end)}</small></td><td>{after ? <>{after.resourceId}<small>{placementDate(after.start)}<br />{placementDate(after.end)}</small></> : "Hesaplanamadı"}</td></tr>;
      })}</tbody></table></div>
      {preview && <>
        <PlacementDeliveryWarnings warnings={deliveryWarnings} />
        <div className="route-delivery-comparison"><strong>Teslimata hazır</strong><span>Önce: {preview.beforeJob.deliveryReadyAt > 0 ? placementDate(preview.beforeJob.deliveryReadyAt) : "Manuel proses bekliyor"}</span><span>Sonra: {preview.afterJob.deliveryReadyAt > 0 ? placementDate(preview.afterJob.deliveryReadyAt) : "Manuel proses bekliyor"}</span></div>
        {preview.targetMet !== null && <p className={preview.targetMet ? "placement-adjustment" : "form-error"}>{preview.targetMet ? "Hedef teslim tarihine yetişiyor." : "Hedef teslim tarihine yetişmiyor. Yukarıdaki yerleşimleri değiştirin veya hesaplanan tarihi kabul edin."}</p>}
        {preview.adjustments.map(text => <p className="placement-adjustment" key={text}>{text}</p>)}
        <details open={preview.affectedOrders.length > 0}><summary>Diğer işlere etkisi · {preview.affectedOperations.filter(item => item.before.batchId !== subject?.job.batchId).length} proses adımı · {preview.affectedOrders.length} sipariş</summary>
          {preview.affectedOrders.map(({ before, after }) => <p key={before.id} className={(after.onTimePlanned ?? 0) < (before.onTimePlanned ?? 0) ? "form-error" : "placement-adjustment"}><strong>{before.product} · Termin {before.dueDate}</strong> · Zamanında karşılanan: {before.onTimePlanned?.toLocaleString("tr-TR")} → {after.onTimePlanned?.toLocaleString("tr-TR")} adet</p>)}
          <div className="route-impact-list" tabIndex={0}>{preview.affectedOperations.filter(item => item.before.batchId !== subject?.job.batchId).map(({ before, after }) => <p key={before.id}><strong>{before.workOrder || before.product} · {before.batchId} · {processLabel(before.process)}</strong><br />Önce: {before.resourceId} · {placementDate(before.start)} – {placementDate(before.end)}<br />Sonra: {after.resourceId} · {placementDate(after.start)} – {placementDate(after.end)}</p>)}</div>
        </details>
      </>}
      {(error || calculated.error) && <p className="form-error" role="alert">{error || calculated.error}</p>}
    </div>
    <div className="drawer-actions"><button ref={closeRef} className="secondary" onClick={onClose}>Vazgeç</button><button className="primary" disabled={!preview || stale} onClick={() => { if (preview) try { onApply(preview); } catch (error) { setError(error instanceof Error ? error.message : "İşlem uygulanamadı."); } }}>Tüm değişiklikleri uygula</button></div>
  </section></div>;
}

frontend/features/planning/shared/Turnin.source:
"use client";

import { useEffect, useMemo, useState } from "react";
import type { PlanningSeed } from "@/lib/planning";
import { inspectTurningQueue, repairTurningIdentity, type TurningIdentityRepairInput } from "@/lib/turning-queue-identity";
import { useRaviScreenContext } from "@/features/ravi/context";
import { formatInteger } from "@/lib/number-format";

export function TurningIdentityReviewDialog({ seed, synced, onClose, onResolve }: {
  seed: PlanningSeed; synced: boolean; onClose: () => void;
  onResolve: (request: TurningIdentityRepairInput, expected: PlanningSeed) => Promise<void>;
}) {
  const conflicts = useMemo(() => inspectTurningQueue(seed).conflicts, [seed]);
  const [batchId, setBatchId] = useState(conflicts[0]?.batchId ?? "");
  const [action, setAction] = useState<TurningIdentityRepairInput["action"]>("work-order");
  const [workOrder, setWorkOrder] = useState("");
  const [reason, setReason] = useState("");
  const [confirmedDuplicate, setConfirmedDuplicate] = useState(false);
  const [preview, setPreview] = useState<{ request: TurningIdentityRepairInput; seed: PlanningSeed } | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const conflict = conflicts.find(item => item.batchId === batchId) ?? conflicts[0];
  useEffect(() => { setPreview(null); setError(""); }, [seed, batchId, action, workOrder, reason, confirmedDuplicate]);
  useRaviScreenContext("turning-identity-review", { dialog: "Çakışan şarj kayıtları", batchId: conflict?.batchId,
    conflicts: conflicts.map(item => ({ batchId: item.batchId, product: item.product, workOrder: item.workOrder, machineId: item.machineId })),
    action, workOrder, reason, confirmedDuplicate, previewReady: Boolean(preview), synced, busy, error, source: "current-browser" });

  function review() {
    if (!conflict) return;
    const request = { batchId: conflict.batchId, action, workOrder: workOrder.trim(), reason: reason.trim(), confirmedDuplicate };
    try { repairTurningIdentity(seed, request); setPreview({ request, seed }); setError(""); }
    catch (e) { setError(e instanceof Error ? e.message : "Düzeltme doğrulanamadı."); }
  }
  async function apply() {
    if (!preview || preview.seed !== seed) return;
    setBusy(true); setError("");
    try { await onResolve(preview.request, preview.seed); onClose(); }
    catch (e) { setError(e instanceof Error ? e.message : "Düzeltme kaydedilemedi."); setPreview(null); }
    finally { setBusy(false); }
  }
  const labels: Record<string, string> = { current: "Mevcut üretim", history: "Üretim arşivi", wip: "Yarı mamul", queue: "Tezgah kuyruğu" };
  const statuses: Record<string, string> = { "semi-finished": "Yarı mamul", delivered: "Teslim edildi", scrapped: "Iskarta", planned: "Planlandı", locked: "Kilitli" };
  return <div className="confirmation-backdrop"><section className="completion-dialog identity-review-dialog" role="dialog" aria-modal="true" aria-label="Çakışan şarj kayıtları">
    <h2>Çakışan şarj kayıtları</h2>
    <p>Bu kayıtların aynı fiziksel işi mi, ayrı işleri mi temsil ettiğini üretim kayıtlarıyla doğrulayın. Karar veremiyorsanız kapatabilirsiniz; iş incelemede kalır ve bağlantısız işlemler devam eder.</p>
    {conflict ? <>
      <label>İncelenecek şarj<select disabled={busy} value={conflict.batchId} onChange={e => { setBatchId(e.target.value); setWorkOrder(""); setReason(""); setConfirmedDuplicate(false); }}>
        {conflicts.map((item, index) => <option key={`${item.batchId}:${index}`} value={item.batchId}>{item.machineId} · {item.workOrder || "İş emri yok"} · {item.product}</option>)}
      </select></label>
      <div className="identity-review-records"><table><caption>Karşılaştırılacak kayıtlar</caption><thead><tr><th>Kayıt</th><th>Tezgah</th><th>Ürün / iş emri</th><th>İlk adet</th><th>Durum</th></tr></thead><tbody>
        {conflict.records.map((record, index) => <tr key={`${record.kind}:${record.id}:${index}`}><td>{labels[record.kind] ?? record.kind}<small>{record.id}</small></td><td>{record.machineId || "—"}</td><td>{record.product}<small>{record.workOrder || "İş emri yok"}</small></td><td>{formatInteger(record.quantity ?? 0)}</td><td>{statuses[record.status ?? ""] ?? record.status ?? "—"}</td></tr>)}
      </tbody></table></div>
      <label>Doğruladığınız düzeltme<select disabled={busy} value={action} onChange={e => setAction(e.target.value as TurningIdentityRepairInput["action"])}><option value="work-order">Kuyruktaki iş emri yanlış</option><option value="remove-duplicate">Kuyruktaki kayıt aynı işin tekrar kaydı</option></select></label>
      {action === "work-order" ? <label>Doğru iş emri<input disabled={busy} value={workOrder} maxLength={100} onChange={e => setWorkOrder(e.target.value)} placeholder="Üretim kaydından doğruladığınız numara" /></label>
        : <label className="identity-review-confirm"><input type="checkbox" disabled={busy} checked={confirmedDuplicate} onChange={e => setConfirmedDuplicate(e.target.checked)} />Kuyruk kaydının yukarıdaki mevcut üretim/arşivdeki aynı işi tekrar ettiğini doğruladım. Kilitli olsa da yalnız bu kuyruk kaydı kaldırılacak.</label>}
      <label>Düzeltme nedeni ve dayanağı<textarea disabled={busy} value={reason} maxLength={2000} onChange={e => setReason(e.target.value)} placeholder="Hangi üretim kaydıyla doğruladınız?" /></label>
      {preview && <div role="status" className="identity-review-preview"><strong>Uygulanacak değişiklik</strong><p>{preview.request.action === "work-order" ? `İş emri: ${conflict.workOrder || "Boş"} → ${preview.request.workOrder}. Adet, tarih, sıra ve kilit değişmez.` : "Yalnız seçilen mükerrer kuyruk kaydı kaldırılır. Bu bir üretim veya teslimat iptali değildir."}</p><p>Üretim, yarı mamul ve teslimat kayıtları korunur. Nedeniniz işlem geçmişine kaydedilir. Kalan çakışmalar varsa görünür kalır; tam teslimat raporu için hepsi çözülmelidir.</p></div>}
      {!synced && <p role="status">İnceleme yapılabilir; uygulamak için ortak kaydın tamamlanması ve varsa kayıt çakışmasının çözülmesi gerekir.</p>}
      {error && <p role="alert" className="form-error">{error}</p>}
    </> : <p role="status">İncelenecek şarj çakışması kalmadı.</p>}
    <div className="drawer-actions"><button className="secondary" disabled={busy} onClick={onClose}>Kapat</button>{conflict && (preview ? <button className="primary" disabled={busy || !synced || preview.seed !== seed} onClick={() => void apply()}>{busy ? "Kaydediliyor…" : "Düzeltmeyi uygula"}</button> : <button className="primary" disabled={busy} onClick={review}>Değişikliği incele</button>)}</div>
  </section></div>;
}

frontend/features/planning/shared/contro.source:
"use client";

import { type ProductSetupFamily, productSetupFamilyDescription, productSetupFamilyLabel } from "@/lib/setup-families";
import { Question } from "@phosphor-icons/react";

export function SetupFamilyBadge({ family }: { family?: ProductSetupFamily }) {
  return <span className={`setup-family-badge ${family ?? "unknown"}`} title={productSetupFamilyDescription(family)}>{productSetupFamilyLabel(family)}</span>;
}

export function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }

export function NumberHelp({ description, children, focusable = true }: { description: string; children: React.ReactNode; focusable?: boolean }) {
  return <span className="number-with-help"><span>{children}</span><span className="number-help-trigger" tabIndex={focusable ? 0 : undefined} aria-label={description}><Question size={10} weight="bold" aria-hidden="true" /><span role="tooltip">{description}</span></span></span>;
}

export function Metric({ label, value, detail, description, tone = "default", compact = false }: { label: string; value: string; detail: string; description: string; tone?: "default" | "good" | "warning" | "danger"; compact?: boolean }) {
  // Compact metrics keep the detail line in the help tooltip so the summary fits on one row.
  if (compact) return <div className={`metric compact ${tone}`}><span>{label}</span><strong><NumberHelp description={`${detail}. ${description}`}>{value}</NumberHelp></strong></div>;
  return <div className={`metric ${tone}`}><span>{label}</span><strong><NumberHelp description={description}>{value}</NumberHelp></strong><small>{detail}</small></div>;
}

function StatusBadge({ difference, empty = false }: { difference: number; empty?: boolean }) { return <span className={`badge ${empty ? "empty" : difference > 0 ? "over" : difference < 0 ? "short" : "exact"}`}>{empty ? "Plan yok" : difference > 0 ? "Fazla" : difference < 0 ? "Eksik" : "Tam"}</span>; }

export function OrderStatusBadge({ difference, onTimeDifference, hasDueDate, empty = false }: { difference: number; onTimeDifference: number | null; hasDueDate: boolean; empty?: boolean }) {
  if (empty) return <span className="badge empty">Plan yok</span>;
  if (hasDueDate && onTimeDifference != null) return <span className={`badge ${onTimeDifference < 0 ? "short" : "exact"}`}>{onTimeDifference < 0 ? "Termin eksiği" : "Termin hazır"}</span>;
  return <StatusBadge difference={difference} />;
}

