import { diameterNumeric, type PlanningSeed, type ScenarioResult } from "@/lib/planning";

// Display colours for raw-material diameters. Planlama's Gantt and the Şarj Yolculuğu
// list share this mapping so the same Ø always has the same colour.
export const DIAMETER_HUE_WHEEL = [24, 205, 130, 275, 46, 340, 178, 90, 240, 0, 310, 160];

/** Diameters in ascending order, each assigned the next hue on the wheel. */
export function buildDiameterHues(seed: PlanningSeed, result: ScenarioResult): Map<number, number> {
  const values = new Set<number>();
  for (const product of seed.products) {
    const numeric = diameterNumeric(product.diameter);
    if (numeric > 0) values.add(numeric);
  }
  for (const batch of result.batches) {
    const numeric = diameterNumeric(batch.diameter);
    if (numeric > 0) values.add(numeric);
  }
  return new Map([...values].sort((left, right) => left - right).map((value, index) => [value, DIAMETER_HUE_WHEEL[index % DIAMETER_HUE_WHEEL.length]]));
}

/** The solid colour Planlama uses for a diameter's bar border; undefined when the diameter is unknown. */
export function diameterDotColor(rawDiameter: string | undefined, hues: Map<number, number>): string | undefined {
  const diameter = diameterNumeric(rawDiameter ?? "");
  if (diameter <= 0) return undefined;
  // Same fallback hue as Planlama's bars for a diameter outside the product list.
  return `hsl(${hues.get(diameter) ?? 24} 48% 50%)`;
}

