"use client";
import { ProductionAreaSelector } from "./ProductionArea";

import { useEffect, useState } from "react";
import { useRaviScreenContext } from "@/features/ravi/context";
import { AppUpdates } from "@/components/AppUpdates";
import { PAGE_GUIDES } from "@/components/ProductGuide";
import { Menu, MenuDivider, MenuItem } from "@/components/ui/Menu";
import { formatFactoryDateTime } from "@/features/planning/shared/format";
import { type View } from "@/features/planning/shared/types";
import { AuthAvatar } from "@/lib/api";
import { formatInteger as formatNumber } from "@/lib/number-format";
import { type ProductionPullStatus, productionSyncAction, type ProductionSyncInfo } from "@/lib/production-sync";
import { Archive, ArrowClockwise, ArrowCounterClockwise, CaretDown, ChatCenteredText, DotsThreeVertical, FloppyDisk, Lightbulb, Play, Question, Trash, X } from "@phosphor-icons/react";

// Navigation groups: every page keeps its label; Geri Bildirimler lives in the header menu.
export const NAV_GROUPS: Array<{ label: string; views: View[] }> = [
  { label: "Plan", views: ["planning", "processes", "control"] },
  { label: "Talep ve stok", views: ["orders", "stocks"] },
  { label: "Kaynaklar", views: ["machines", "parameters", "settings"] },
  { label: "Senaryolar", views: ["scenarios"] },
];

export type HeaderPlanControls = {
  visible: boolean;
  dirty: boolean;
  scenarioLabel: string | null;
  canUndo: boolean;
  canRedo: boolean;
  onRun: () => void;
  onClear: () => void;
  onUndo: () => void;
  onRedo: () => void;
  onSaveScenario: () => void;
};

export function Header({ areaSwitchDisabled, isAdmin, view, setView, notice, adviceCount, onOpenAdvice, onOpenArchive, productionSyncInfo, productionPullStatus, onPullProduction, plan, onOpenGuide, onStartTour }: { areaSwitchDisabled?: boolean; isAdmin: boolean; view: View; setView: (view: View) => void; notice: string; adviceCount: number; onOpenAdvice: () => void; onOpenArchive: () => void; productionSyncInfo: ProductionSyncInfo | null; productionPullStatus: ProductionPullStatus; onPullProduction: () => void; plan: HeaderPlanControls; onOpenGuide: () => void; onStartTour: () => void }) {
  const [visibleNotice, setVisibleNotice] = useState("");
  useEffect(() => {
    setVisibleNotice(notice);
    if (!notice) return;
    const timer = window.setTimeout(() => setVisibleNotice(""), 8000);
    return () => window.clearTimeout(timer);
  }, [notice]);
  useRaviScreenContext("header-status", { notice: visibleNotice, planDirty: plan.dirty, scenario: plan.scenarioLabel });
  const productionAction = productionSyncAction(productionSyncInfo, productionPullStatus);
  const planStatus = plan.dirty ? "Değişiklik var" : plan.scenarioLabel ?? "Senaryo kaydı yok";
  return (
    <>
    <header className="topbar app-header">
      <div className="brand-area"><button className="brand" onClick={() => setView("planning")} aria-label="Selsa Planlama ana sayfa"><span className="selsa-logo-frame"><img src="/selsa-logo.gif" alt="Selsa" /></span></button>
      <ProductionAreaSelector disabled={areaSwitchDisabled} /></div>
      <nav aria-label="Primary navigation" className="app-nav">
        {NAV_GROUPS.map((group) => {
          const items = group.views.filter((id) => isAdmin || id !== "settings");
          return <div key={group.label} className="app-nav-group" role="group" aria-label={group.label}>
            {items.map((id) => <button key={id} className={`nav-item ${view === id ? "active" : ""}`} aria-current={view === id ? "page" : undefined} onClick={() => setView(id)}>{pageTitle(id)}</button>)}
          </div>;
        })}
      </nav>
      {plan.visible && <div className="plan-controls">
        <span className={`plan-status ${plan.dirty ? "dirty" : ""}`} title={`${plan.dirty ? "Değişiklik var · planı çalıştırın. " : ""}Planın senaryosu: ${plan.scenarioLabel ?? "Senaryo kaydı yok"}`}><i aria-hidden="true" /><span>{planStatus}</span></span>
        <div className="ui-split-button">
          <button className={`ui-btn primary ${plan.dirty ? "attention" : ""}`} onClick={plan.onRun} aria-label="Planı Çalıştır"><Play size={14} weight="fill" /><span className="plan-run-label">Planı Çalıştır</span></button>
          <Menu title="Plan işlemleri" icon={<CaretDown size={13} />} className="split-menu">
            <MenuItem icon={<ArrowCounterClockwise size={15} />} disabled={!plan.canUndo} onClick={plan.onUndo} hint="Geri al (Ctrl/Cmd+Z)">Geri al</MenuItem>
            <MenuItem icon={<ArrowClockwise size={15} />} disabled={!plan.canRedo} onClick={plan.onRedo} hint="Yinele (Ctrl/Cmd+Y)">Yinele</MenuItem>
            <MenuItem icon={<FloppyDisk size={15} />} onClick={plan.onSaveScenario}>Senaryoyu Kaydet</MenuItem>
            <MenuDivider />
            <MenuItem icon={<Trash size={15} />} onClick={plan.onClear}>Planı Temizle</MenuItem>
          </Menu>
        </div>
      </div>}
      <div className="top-actions">
        <button className={`ui-icon-btn advice-launch ${adviceCount ? "active" : ""}`} onClick={onOpenAdvice} title="Tavsiyeler" aria-label={`Tavsiyeler · ${formatNumber(adviceCount)}`}><Lightbulb size={16} weight={adviceCount ? "fill" : "regular"} />{adviceCount > 0 && <b>{formatNumber(adviceCount)}</b>}</button>
        <AppUpdates canManage={isAdmin} />
        <span id="feedback-header-action" className="feedback-header-slot" />
        <Menu title="Diğer işlemler" icon={<DotsThreeVertical size={18} weight="bold" />} className="app-more-menu">
          <MenuItem icon={<Archive size={15} />} onClick={onOpenArchive}>Üretim arşivi</MenuItem>
          <MenuItem icon={<ChatCenteredText size={15} />} active={view === "feedback"} onClick={() => setView("feedback")}>{pageTitle("feedback")}</MenuItem>
          {isAdmin && productionAction.visible && <MenuItem icon={<ArrowClockwise size={15} />} disabled={productionAction.disabled} onClick={onPullProduction} hint={productionSyncInfo?.enabled ? "Üretimdeki son verileri staging’e kopyala; üretim hiçbir şekilde değiştirilmez" : "Staging üretim bağlantısı yapılandırılmamış"}>{productionAction.label}<small className="ui-menu-hint">{productionSyncInfo?.enabled && productionSyncInfo.lastSync ? `Son kopya: ${formatFactoryDateTime(productionSyncInfo.lastSync.importedAt)}` : productionAction.detail}</small></MenuItem>}
          <MenuDivider />
          <MenuItem icon={<Question size={15} />} onClick={onOpenGuide}>Sayfa rehberi</MenuItem>
          <MenuItem icon={<Question size={15} />} onClick={onStartTour}>Tanıtımı başlat</MenuItem>
        </Menu>
        <AuthAvatar />
      </div>
    </header>
    {visibleNotice && <div className="planning-status-toast" role="status"><span>{visibleNotice}</span><button onClick={() => setVisibleNotice("")} aria-label="Durum mesajını kapat"><X size={15} /></button></div>}
    </>
  );
}

export function pageTitle(view: View) {
  return PAGE_GUIDES[view].label;
}

