"use client";

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
import { ScopedApiProvider, useCurrentUser } from "@/lib/api";
import { PRODUCTION_AREAS, parseProductionArea, type ProductionArea } from "@/lib/production-area";
import { useRaviScreenContext } from "@/features/ravi/context";

const AreaContext = createContext<ProductionArea>("torna");
export function useProductionArea() { return useContext(AreaContext); }

export function ProductionAreaProvider({ children }: { children: ReactNode }) {
  const [area, setArea] = useState<ProductionArea | null>(null);
  const user = useCurrentUser();
  useEffect(() => { setArea(parseProductionArea(new URLSearchParams(window.location.search).get("area"))); }, []);
  if (!area) return <div className="auth-screen">Üretim alanı hazırlanıyor…</div>;
  return <AreaContext.Provider value={area}><ScopedApiProvider key={`${user.id}:${area}`} area={area}>{children}</ScopedApiProvider></AreaContext.Provider>;
}

export function ProductionAreaSelector({ disabled = false }: { disabled?: boolean }) {
  const area = useProductionArea();
  useRaviScreenContext("production-area", { selectedArea: area, selectedLabel: PRODUCTION_AREAS.find(a => a.id === area)?.label, switchingDisabled: disabled });
  return <label className="production-area-selector" id="production-area-selector"><span>Üretim alanı</span><select aria-label="Üretim alanı" value={area} disabled={disabled} onChange={event => {
    const url = new URL(window.location.href);
    url.searchParams.set("area", event.target.value);
    url.searchParams.delete("view");
    window.location.assign(url);
  }}>{PRODUCTION_AREAS.map(item => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label>;
}

