"use client";
import { useMemo, useState } from "react";
import { buildProcessStockProjection, initialProcessStockSettings, processStockScrap, stockGroups, validateProcessStockSettings, type ProcessStockSettings } from "@/lib/process-stock";
import { factoryDateInput, factoryNowSerial } from "@/lib/factory-time";
import { resolvedProductSetupFamily } from "@/lib/setup-families";
import { formatInteger } from "@/lib/number-format";
import type { PlanningSeed, ScenarioResult } from "@/lib/planning";
import { useRaviScreenContext } from "@/features/ravi/context";
import { Drawer, HelpTip, PageBarSlot, StatusLine, type StatusItem } from "@/components/ui/primitives";
import { GearSix } from "@phosphor-icons/react";

export function ProcessStockView({ seed, result, dirty, canEdit, updateSettings, onAddProduction }: { seed: PlanningSeed; result: ScenarioResult; dirty: boolean; canEdit: boolean; updateSettings: (mutator: (seed: PlanningSeed) => void) => void; onAddProduction: (product: string) => void }) {
  const [weeks, setWeeks] = useState(8);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [product, setProduct] = useState("");
  const snapshot = useMemo(() => {
    try { return { data: buildProcessStockProjection(seed, result, factoryNowSerial(), weeks), error: "" }; }
    catch (error) { return { data: undefined, error: error instanceof Error ? error.message : "Stok hesaplanamadı." }; }
  }, [seed, result, weeks]);
  useRaviScreenContext("process-stock", { weeks, settingsOpen, product, dirty, error: snapshot.error, calculation: "browser", closing: "Saturday", beforeFutureShipments: true, groups: snapshot.data?.weeks[0]?.groups.map(group => ({ id: group.id, actual: group.actual, projected: group.projected, min: group.min, max: group.max, shortage: group.shortage, excess: group.excess })), issues: snapshot.data?.issues });
  const dayLabel = (date: string) => `${date.slice(8, 10)}.${date.slice(5, 7)}`;
  const statusItems: StatusItem[] = dirty ? [{ id: "stale", tone: "warn", title: "Plan yeniden hesaplama bekliyor.", detail: "Tahmin kayıtlı şarjları kullanır." }] : [];
  return <section className="data-surface dispatch-plan process-stock-view" id="process-stock">
    <PageBarSlot>
      <span className="stock-view-subtitle">Mevcut miktar ve cumartesi kapanış tahmini · adet<HelpTip align="start" text="Her şarj yalnız bir stok grubuna girer. “Önünde” önceki prosesleri de kapsar; bütün adetlerin o tezgaha hazır olduğunu göstermez. Min / max ürün başına değil, grup toplamına uygulanır." /></span>
      <div className="stock-view-actions"><label className="ui-field stock-weeks-field"><span>Hafta sayısı</span><input type="number" min={1} max={26} value={weeks} onChange={event => setWeeks(Math.max(1, Math.min(26, Number(event.target.value) || 1)))} /></label>{canEdit && <button className={`ui-btn${settingsOpen ? " active" : ""}`} aria-expanded={settingsOpen} onClick={() => setSettingsOpen(!settingsOpen)}><GearSix size={15} />Stok ayarları</button>}</div>
    </PageBarSlot>
    {settingsOpen && <Drawer title="Stok ayarları" label="Stok ayarları" width={760} className="stock-settings-drawer" onClose={() => setSettingsOpen(false)}><ProcessStockSettingsPanel seed={seed} updateSeed={updateSettings} /></Drawer>}
    <StatusLine items={statusItems} label="Stok uyarıları" />
    {snapshot.error ? <p role="alert" className="dispatch-plan-error">{snapshot.error}</p> : snapshot.data && <>
      {snapshot.data.weeks[0].groups.map((group, groupIndex) => { const state = group.actual < group.min ? "low" : group.actual > group.max ? "high" : "ok"; return <section key={group.id} className="process-stock-group">
        <header><h3>{group.label}</h3><dl><div><dt>Min</dt><dd>{formatInteger(group.min)}</dd></div><div><dt>Max</dt><dd>{formatInteger(group.max)}</dd></div><div className={state}><dt>Mevcut</dt><dd>{formatInteger(group.actual)}</dd></div></dl>
          {groupIndex === 0 && <details className="stock-view-issues"><summary>Hesap kapsamı ve uyarılar ({snapshot.data!.issues.length})</summary><div className="stock-view-issues-pop"><ul>{snapshot.data!.issues.map(issue => <li key={issue}>{issue}</li>)}</ul><p>Iskarta, gruptan çıkan planlı adede eklenir ve yukarı yuvarlanır. Fiili ıskarta tekrar düşülmez. Negatif tahmin, karşılanamayan giriş ihtiyacıdır. Otomatik ek üretim yapılmaz.</p></div></details>}
        </header>
        <div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th className="day">Ürün / kayıt</th><th>Mevcut stok</th>{snapshot.data!.weeks.map(week => <th key={week.endDate} title={week.endDate}>{dayLabel(week.endDate)}<small>Cumartesi kapanışı</small></th>)}</tr></thead><tbody>
          <tr className="stock-total-row"><th className="day"><b>Grup toplamı</b></th><td>{formatInteger(group.actual)}</td>{snapshot.data!.weeks.map(week => { const item = week.groups[groupIndex]; return <td key={week.endDate} className={item.shortage > 0 ? "low" : item.excess > 0 ? "high" : "ok"}><strong>{formatInteger(item.projected)}</strong><small>{item.shortage > 0 ? `Min altı: ${formatInteger(item.shortage)}` : item.excess > 0 ? `Max üstü: ${formatInteger(item.excess)}` : "Aralık içinde"}</small></td>; })}</tr>
          {group.rows.map((row, rowIndex) => <StockProductRows key={row.product} row={row} weeks={snapshot.data!.weeks.map(week => week.groups[groupIndex].rows[rowIndex].projected)} />)}
        </tbody></table></div></section>; })}
      <div className="stock-view-production"><strong>Eksik stok için üretim seçimi<HelpTip align="start" text="Ürün ve adedi planlamacı seçer. Mevcut manuel şarj kontrolleri uygulanır." /></strong><select aria-label="Stok için üretilecek ürün" value={product} onChange={event => setProduct(event.target.value)}><option value="">Ürün seçin</option>{snapshot.data.weeks[0].groups[0].rows.map(row => <option key={row.product}>{row.product}</option>)}</select><button className="ui-btn" disabled={!product} onClick={() => onAddProduction(product)}>Manuel şarj ekle</button></div>
    </>}
  </section>;
}
function StockProductRows({ row, weeks }: { row: { product: string; actual: number; scrapPercent: number }; weeks: number[] }) {
  // One row per product: the scrap rate is constant across weeks, so it is shown once under the product.
  return <tr className="stock-quantity-row"><th className="day"><b>{row.product}</b><small>Iskarta %{row.scrapPercent}</small></th><td>{formatInteger(row.actual)}</td>{weeks.map((quantity, i) => <td key={i} className={quantity < 0 ? "open" : quantity ? undefined : "empty"}>{formatInteger(quantity)}</td>)}</tr>;
}

export function ProcessStockSettingsPanel({ seed, updateSeed }: { seed: PlanningSeed; updateSeed: (mutator: (seed: PlanningSeed) => void) => void }) {
  const [draft, setDraft] = useState<ProcessStockSettings>(() => structuredClone(seed.processStockSettings ?? initialProcessStockSettings(seed.productionArea)));
  const [baseline, setBaseline] = useState(JSON.stringify(seed.processStockSettings));
  const [error, setError] = useState("");
  const [saved, setSaved] = useState(false);
  const [confirmed, setConfirmed] = useState(false);
  const family = seed.productionArea === "cubuk-filtre" ? "cubuk-filtre" : "piston";
  const products = seed.products.filter(product => resolvedProductSetupFamily(product.product, product.setupFamily) === family).map(product => product.product);
  const stale = baseline !== JSON.stringify(seed.processStockSettings);
  const groups = stockGroups(seed.productionArea);
  const change = (mutate: (value: ProcessStockSettings) => void) => { setDraft(previous => { const next = structuredClone(previous); mutate(next); return next; }); setSaved(false); };
  useRaviScreenContext("process-stock-settings", { draft, error, saved, stale, confirmedAdditionalStock: confirmed });
  return <section className="process-stock-settings" id="settings-stocks"><h2>Stok ayarları</h2>
    <p className="stock-settings-note">Başlangıç limitleri: Stok Değerleri → Stok (2), 31.03.2026. Tam adet için min yukarı, max aşağı yuvarlandı. Güncel limitleri burada değiştirin. Çap Taşlama sonundaki sıfır limit satırı ayrı bir ikinci stok olarak sayılmaz.</p>
    <p className="stock-settings-note">Çubuk Filtre ıskarta başlangıcı: %2; 2.433.084.245 için formüllerdeki 1,04 katsayısı nedeniyle %4. Bunlar stok tüketim tahminidir; hammadde oranlarından ayrıdır. Piston için oran girilene kadar %0 kullanılır.</p>
    <label className="field"><span>Ek stok sayım tarihi</span><input type="date" max={factoryDateInput()} value={draft.openingDate} onChange={event => change(next => { next.openingDate = event.target.value; })} /></label>
    <p className="stock-settings-note">Ek stok alanına yalnız kayıtlı şarj, eski açılış stoğu ve müşteri Excel bakiyesi dışında kalan adetleri yazın. Bunlar yeni Torna ihtiyacını azaltır. Kesin proses konumu bilinmediği için teslimat tarihi oluşturmaz. Şarj kaydına aktarılan adetleri bu listeden çıkarın.</p>
    {groups.map(group => <details key={group.id}><summary>{group.label}</summary><div className="stock-settings-limits">{(["min", "max"] as const).map(field => <label className="field" key={field}><span>{field === "min" ? "Min (adet)" : "Max (adet)"}</span><input type="number" min={0} step={1} value={draft.limits.find(row => row.groupId === group.id)?.[field] ?? 0} onChange={event => change(next => { next.limits.find(row => row.groupId === group.id)![field] = Number(event.target.value); })} /></label>)}</div><div className="dispatch-plan-table-wrap"><table className="dispatch-plan-table"><thead><tr><th className="day">Ürün</th><th>Iskarta (%)</th><th>Kayıt dışı ek stok (adet)</th></tr></thead><tbody>{products.map(product => <tr key={product}><th className="day"><b>{product}</b></th><td><input aria-label={`${group.label} ${product} ıskarta`} type="number" min={0} max={100} step={.1} value={processStockScrap(draft, seed.productionArea, group.id, product)} onChange={event => change(next => { next.scrap = [...next.scrap.filter(row => row.groupId !== group.id || row.product !== product), { groupId: group.id, product, percent: Number(event.target.value) }]; })} /></td><td><input aria-label={`${group.label} ${product} ek stok`} type="number" min={0} step={1} value={draft.opening.find(row => row.groupId === group.id && row.product === product)?.quantity ?? 0} onChange={event => change(next => { next.opening = [...next.opening.filter(row => row.groupId !== group.id || row.product !== product), { groupId: group.id, product, quantity: Number(event.target.value) }]; })} /></td></tr>)}</tbody></table></div></details>)}
    <label className="stock-settings-confirm"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} /> Ek stok başka kayıtlarla tekrar sayılmıyor; sayım tarihi ve adetleri kontrol ettim.</label>
    {error && <p role="alert" className="dispatch-plan-error">{error}</p>}{stale && <p role="alert" className="dispatch-plan-error">Stok ayarları değişti. Güncel ayarları yükleyin.</p>}{saved && <p role="status" className="stock-view-status ok">Değişiklik yerel çalışma alanına uygulandı. Üst çubuktaki kayıt durumunu kontrol edin.</p>}
    <div className="drawer-actions"><button className="secondary" onClick={() => { setDraft(structuredClone(seed.processStockSettings ?? initialProcessStockSettings(seed.productionArea))); setBaseline(JSON.stringify(seed.processStockSettings)); setError(""); setSaved(false); setConfirmed(false); }}>Güncel ayarları yükle</button><button className="primary" disabled={stale} onClick={() => { try {
      if (stale) throw new Error("Stok ayarları değişti.");
      const settings = validateProcessStockSettings(draft, seed.productionArea);
      if (settings.opening.some(row => row.quantity > 0) && (!confirmed || settings.openingDate > factoryDateInput())) throw new Error("Ek stok sayımını ve tekrar sayılmadığını doğrulayın.");
      updateSeed(next => { if (JSON.stringify(next.processStockSettings) !== baseline) throw new Error("Stok ayarları değişti; güncel ayarları yükleyin."); next.processStockSettings = settings; next.planNeedsRecalculation = true; });
      setBaseline(JSON.stringify(settings)); setError(""); setSaved(true);
    } catch (reason) { setError(reason instanceof Error ? reason.message : "Stok ayarları kaydedilemedi."); } }}>Stok ayarlarını uygula</button></div>
  </section>;
}

