"use client";

import { createContext, useCallback, useContext, useLayoutEffect, useMemo, useRef, type ReactNode } from "react";
import type { AppView } from "@/components/ProductGuide";
import { boundContextData, type RaviBrowserContext } from "./protocol";

type ContextRegistry = {
  register: (name: string, value: Record<string, unknown>) => () => void;
  read: () => RaviBrowserContext;
};
const Context = createContext<ContextRegistry | null>(null);

export function RaviContextProvider({ view, planning, entryPoint, children }: { view: AppView; planning: Record<string, unknown>; entryPoint?: { view: AppView; source: string } | null; children: ReactNode }) {
  const screens = useRef(new Map<string, { token: symbol; value: Record<string, unknown> }>());
  const navigation = useRef<{ entryView: AppView; entrySource?: string; recentViews: Array<{ view: AppView; at: string }>; lastInteraction?: { view: AppView; label: string; at: string } }>({ entryView: view, recentViews: [] });
  useLayoutEffect(() => {
    const history = navigation.current.recentViews;
    // Ignore the placeholder view while URL/local-storage restoration is pending.
    if (entryPoint === null || (entryPoint && !history.length && view !== entryPoint.view)) return;
    if (history.at(-1)?.view !== view) {
      if (!history.length) { navigation.current.entryView = view; navigation.current.entrySource = entryPoint?.source ?? "default"; }
      navigation.current.recentViews = [...history, { view, at: new Date().toISOString() }].slice(-8);
    }
  }, [view, entryPoint]);
  const register = useCallback((name: string, value: Record<string, unknown>) => {
    const token = Symbol(name);
    screens.current.set(name, { token, value });
    return () => { if (screens.current.get(name)?.token === token) screens.current.delete(name); };
  }, []);
  const read = useCallback((): RaviBrowserContext => ({
    view, capturedAt: new Date().toISOString(),
    navigation: { ...navigation.current, previousView: navigation.current.recentViews.at(-2)?.view ?? null },
    planning: boundContextData(planning) as Record<string, unknown>,
    screens: boundContextData(Object.fromEntries([...screens.current].map(([name, entry]) => [name, entry.value]))) as Record<string, unknown>,
  }), [view, planning]);
  const registry = useMemo(() => ({ register, read }), [register, read]);
  return <Context.Provider value={registry}><div className="ravi-context-root" onClickCapture={(event) => {
    const target = event.target as HTMLElement;
    if (target.closest("[data-ravi-chat]")) return;
    const button = target.closest("button, summary, [role=tab]");
    const label = (button?.getAttribute("aria-label") || button?.textContent || "").trim().slice(0, 160);
    if (label) navigation.current.lastInteraction = { view, label, at: new Date().toISOString() };
  }}>{children}</div></Context.Provider>;
}

/** Register screen-owned values; unmount removes them, so old selections never leak into another screen. */
export function useRaviScreenContext(name: string, data: Record<string, unknown>, enabled = true) {
  const register = useContext(Context)?.register;
  const serialized = JSON.stringify(data);
  useLayoutEffect(() => enabled ? register?.(name, JSON.parse(serialized)) : undefined, [register, name, serialized, enabled]);
}

export function useRaviContext() {
  const registry = useContext(Context);
  if (!registry) throw new Error("Ravi context provider bulunamadı");
  return registry.read;
}

frontend/features/ravi/conversations.ts.source:
import { RAVI_TARGETS, type RaviMessage } from "./protocol";

export type RaviEntry = RaviMessage & { id: string; actions?: Array<{ id: string }> };
export type RaviConversation = { id: string; updatedAt: string; entries: RaviEntry[]; draft: string; trimmed?: boolean };
export type RaviConversations = { version: 1; activeId: string | null; conversations: RaviConversation[] };
export const MAX_CONVERSATIONS = 20;
const MAX_MESSAGES = 100;
const MAX_CONVERSATION_CHARS = 50000;

function registeredActions(value: unknown): Array<{ id: string }> {
  if (!Array.isArray(value)) return [];
  const ids = value.filter((action) => action && typeof action.id === "string" && Object.hasOwn(RAVI_TARGETS, action.id)).map((action) => action.id as string);
  return [...new Set(ids)].slice(0, 6).map((id) => ({ id }));
}

export function conversationStorageKey(userId: string) {
  return `selsa:ravi:conversations:v1:${encodeURIComponent(userId)}`;
}

export function emptyConversations(): RaviConversations {
  return { version: 1, activeId: null, conversations: [] };
}

export function conversationTitle(conversation: RaviConversation) {
  return (conversation.entries.find((entry) => entry.role === "user")?.content || conversation.draft || "Yeni konuşma").replace(/\s+/g, " ").slice(0, 80);
}

export function boundConversation(conversation: RaviConversation): RaviConversation {
  const entries = conversation.entries.slice(-MAX_MESSAGES).map((entry): RaviEntry => ({
    id: entry.id, role: entry.role, content: entry.content.slice(0, 12000),
    ...(entry.role === "assistant" ? { actions: registeredActions(entry.actions) } : {}),
  }));
  let size = entries.reduce((total, entry) => total + entry.content.length, 0);
  while (size > MAX_CONVERSATION_CHARS && entries.length > 1) size -= entries.shift()!.content.length;
  while (entries[0]?.role === "assistant") entries.shift();
  return { ...conversation, entries, trimmed: conversation.trimmed || entries.length < conversation.entries.length };
}

/** Only chat text, drafts and registered action IDs are stored. No context snapshots or tool payloads. */
export function parseConversations(raw: string | null): RaviConversations {
  if (!raw) return emptyConversations();
  const data = JSON.parse(raw);
  if (!data || data.version !== 1 || !Array.isArray(data.conversations)) throw new Error("Invalid conversation store");
  const conversations: RaviConversation[] = [];
  const ids = new Set<string>();
  for (const value of data.conversations.slice(0, MAX_CONVERSATIONS)) {
    if (!value || typeof value.id !== "string" || !value.id || value.id.length > 100 || ids.has(value.id) || !Array.isArray(value.entries)) continue;
    ids.add(value.id);
    const entries: RaviEntry[] = [];
    const messageIds = new Set<string>();
    for (const entry of value.entries.slice(-MAX_MESSAGES)) {
      if (!entry || typeof entry.id !== "string" || !entry.id || entry.id.length > 100 || messageIds.has(entry.id) || !["user", "assistant"].includes(entry.role) || typeof entry.content !== "string") continue;
      messageIds.add(entry.id);
      entries.push({ id: entry.id, role: entry.role, content: entry.content.slice(0, 12000),
        ...(entry.role === "assistant" ? { actions: registeredActions(entry.actions) } : {}) });
    }
    conversations.push(boundConversation({ id: value.id,
      updatedAt: typeof value.updatedAt === "string" && Number.isFinite(Date.parse(value.updatedAt)) ? new Date(value.updatedAt).toISOString() : new Date(0).toISOString(),
      draft: typeof value.draft === "string" ? value.draft.slice(0, 4000) : "", entries,
      trimmed: value.trimmed === true || value.entries.length > entries.length }));
  }
  return { version: 1, activeId: conversations.some((item) => item.id === data.activeId) ? data.activeId : conversations[0]?.id ?? null, conversations };
}

export function updateConversation(store: RaviConversations, id: string, update: (conversation: RaviConversation) => RaviConversation): RaviConversations {
  return { ...store, conversations: store.conversations.map((conversation) => conversation.id === id ? boundConversation(update(conversation)) : conversation) };
}

