import type { AppView } from "@/components/ProductGuide";

export type RaviBrowserContext = {
  view: AppView;
  capturedAt: string;
  navigation: Record<string, unknown>;
  planning: Record<string, unknown>;
  screens: Record<string, unknown>;
};
export type RaviMessage = { role: "user" | "assistant"; content: string };
export type RaviResponse = {
  answer: string;
  actions: Array<{ id: string }>;
  sources: Array<{ path: string; symbol?: string; line?: number }>;
};

export const RAVI_TARGETS: Record<string, { label: string; view?: AppView; focusId?: string; panel?: "archive" | "advice"; adminOnly?: boolean; productionArea?: "torna" | "cubuk-filtre" }> = {
  "production-area": { label: "Üretim alanı seçimi", view: "planning", focusId: "production-area-selector" },
  "filter-production-data": { label: "Çubuk Filtre üretim verileri", view: "parameters", focusId: "filter-production-data", productionArea: "cubuk-filtre" },
  planning: { label: "Planlama", view: "planning" },
  "manual-batch": { label: "Manuel şarj ekle", view: "planning", focusId: "planning-manual-batch" },
  processes: { label: "Şarj Yolculuğu", view: "processes" },
  control: { label: "Genel Bakış", view: "control" },
  stocks: { label: "Stoklar", view: "stocks" },
  orders: { label: "Siparişler", view: "orders" },
  "delivery-export": { label: "Teslimat planını indir", view: "orders", focusId: "ravi-delivery-export" },
  "order-import": { label: "Müşteri Excel’ini yükle", view: "orders", focusId: "ravi-order-import" },
  machines: { label: "Tezgahlar", view: "machines" },
  "flow-settings": { label: "Akış ve bekleme", view: "settings", focusId: "settings-tab-waits", adminOnly: true, productionArea: "torna" },
  parameters: { label: "Parametreler", view: "parameters" },
  "new-product-type": { label: "Yeni tip tanımla", view: "parameters", focusId: "parameters-new-type", adminOnly: true },
  "product-weights": { label: "Ürün Ağırlıkları", view: "settings", focusId: "settings-tab-weights", adminOnly: true },
  "process-waits": { label: "Proses bekleme süreleri", view: "settings", focusId: "settings-tab-waits", adminOnly: true },
  "raw-material-consumption": { label: "Hammadde Tüketim Tablosu", view: "settings", focusId: "settings-tab-consumption", adminOnly: true },
  settings: { label: "Ayarlar", view: "settings", adminOnly: true },
  scenarios: { label: "Senaryolar", view: "scenarios" },
  "scenario-history": { label: "Versiyon geçmişi", view: "scenarios", focusId: "scenario-history-tab" },
  feedback: { label: "Geri Bildirimler", view: "feedback" },
  archive: { label: "Üretim arşivi", panel: "archive" },
  advice: { label: "Tavsiyeler", panel: "advice" },
};

export function raviTarget(id: string, isAdmin: boolean, area: "torna" | "cubuk-filtre" = "torna") {
  const target = Object.hasOwn(RAVI_TARGETS, id) ? RAVI_TARGETS[id] : undefined;
  return target && (!target.productionArea || target.productionArea === area) && (isAdmin || !target.adminOnly) ? target : null;
}

export function raviHistory(messages: RaviMessage[]): RaviMessage[] {
  const selected: RaviMessage[] = [];
  let size = 0;
  for (const message of [...messages].reverse().slice(0, 20)) {
    const content = message.content.slice(0, 6000);
    if (size + content.length > 24000) break;
    selected.unshift({ role: message.role, content });
    size += content.length;
  }
  // Keep a coherent beginning after dropping old turns.
  while (selected[0]?.role === "assistant") selected.shift();
  return selected;
}

export function boundContextData(value: unknown, depth = 0): unknown {
  if (depth > 7) return "[depth limit]";
  if (typeof value === "string") return value.length > 600 ? value.slice(0, 600) + "… [truncated]" : value;
  if (Array.isArray(value)) {
    const items = value.slice(0, 20).map((item) => boundContextData(item, depth + 1));
    return value.length > 20 ? { items, total: value.length, truncated: true } : items;
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value);
    return { ...Object.fromEntries(entries.slice(0, 45).map(([key, item]) => [key, boundContextData(item, depth + 1)])),
      ...(entries.length > 45 ? { _truncatedKeys: entries.length - 45 } : {}) };
  }
  return value;
}

export function parseRaviResponse(value: unknown): RaviResponse {
  if (!value || typeof value !== "object" || !("answer" in value) || typeof value.answer !== "string" || !value.answer.trim()) throw new Error("Ravi'den geçerli bir yanıt alınamadı.");
  const data = value as Record<string, unknown>;
  return {
    answer: value.answer,
    actions: Array.isArray(data.actions) ? data.actions.filter((item): item is { id: string } => Boolean(item) && typeof item.id === "string").slice(0, 6) : [],
    sources: Array.isArray(data.sources) ? data.sources.filter((item): item is RaviResponse["sources"][number] => Boolean(item) && typeof item.path === "string" && /^(frontend|backend)\/[\w./[\]-]+$/.test(item.path) && !item.path.includes("..")).slice(0, 16) : [],
  };
}

