import type { MachineCalendarEvent } from "./planning";

export type CalendarEventStatus = {
  status: "active" | "completed";
  automaticallyCompleted: boolean;
};

export function calendarEventStatus(event: MachineCalendarEvent, todaySerial: number): CalendarEventStatus {
  const automaticallyCompleted = event.kind === "shift"
    && !event.completedAt
    && Math.floor(event.end) < Math.floor(todaySerial);
  return {
    status: event.completedAt || automaticallyCompleted ? "completed" : "active",
    automaticallyCompleted,
  };
}

frontend/lib/capacity-analytics.ts.source:
import {
  excelSerialToDate,
  getSetupSettings,
  machineDayCapacity,
  type Machine,
  type MachineDayCapacity,
  type PlanningSeed,
  type ScenarioResult,
} from "./planning";
import { buildDownstreamProcessPlan, type ProcessOperation } from "./process-planning";
import type { ProcessKind } from "./process-master-data";

export type CapacityDay = {
  serial: number;
  kind: MachineDayCapacity["kind"];
  label: string;
  availableHours: number;
  regularHours: number;
  overtimeCapacityHours: number;
  downtimeHours: number;
  plannedHours: number;
  regularLoadHours: number;
  overtimeLoadHours: number;
  utilization: number;
};

export type MachineCapacity = {
  process: Exclude<ProcessKind, "washing">;
  machineId: string;
  machineName: string;
  availableHours: number;
  plannedHours: number;
  regularLoadHours: number;
  idleHours: number;
  overtimeCapacityHours: number;
  overtimeLoadHours: number;
  downtimeHours: number;
  utilization: number;
  days: CapacityDay[];
};

export type CapacityReport = {
  start: number;
  end: number;
  dayCount: number;
  availableHours: number;
  plannedHours: number;
  idleHours: number;
  overtimeCapacityHours: number;
  overtimeLoadHours: number;
  downtimeHours: number;
  utilization: number;
  machines: MachineCapacity[];
};

export type OvertimeEntry = {
  id: string;
  machineId: string;
  machineName: string;
  serial: number;
  shiftCount: number;
  extraShiftCount: number;
  overtimeHours: number;
  label: string;
  process: Exclude<ProcessKind, "washing">;
};

function clampShifts(value: number | undefined): number {
  return Number.isFinite(value) ? Math.max(0, Math.min(3, Math.trunc(value!))) : 0;
}

export function regularMachineShifts(seed: PlanningSeed, machine: Pick<Machine, "shiftFactor">, serialValue: number): number {
  const serial = Math.floor(serialValue);
  const holiday = seed.holidays.some((item) => Math.floor(item.serial) === serial);
  const sunday = excelSerialToDate(serial).getUTCDay() === 0;
  return holiday || sunday ? 0 : clampShifts(machine.shiftFactor);
}

function range(startValue: number, endValue: number): { start: number; end: number; days: number[] } {
  const start = Math.floor(Math.min(startValue, endValue));
  const end = Math.floor(Math.max(startValue, endValue));
  return { start, end, days: Array.from({ length: Math.max(0, end - start + 1) }, (_, index) => start + index) };
}

function overlapHours(startValue: number, endValue: number, day: number, capacityHours: number): number {
  if (!Number.isFinite(startValue) || !Number.isFinite(endValue) || endValue <= startValue || capacityHours <= 0) return 0;
  const windowEnd = day + capacityHours / 24;
  return Math.max(0, Math.min(endValue, windowEnd) - Math.max(startValue, day)) * 24;
}

function machinePlannedHours(seed: PlanningSeed, result: ScenarioResult, machine: Machine, serial: number, capacityHours: number): number {
  if (capacityHours <= 0) return 0;
  const finishOffset = Number.isFinite(machine.finishOffset) ? machine.finishOffset : 0;
  let hours = 0;
  if (machine.currentJob.product && machine.currentJob.quantity > 0) {
    hours += overlapHours(machine.currentJob.start, Math.max(machine.currentJob.start, machine.currentJob.end - finishOffset), serial, capacityHours);
  }
  for (const batch of result.batches) {
    if (batch.status !== "planned" || batch.machineId !== machine.id) continue;
    hours += overlapHours(batch.start, Math.max(batch.start, batch.end - finishOffset), serial, capacityHours);
  }
  return Math.min(capacityHours, Math.max(0, hours));
}

function processCalendarSeed(seed: PlanningSeed, resourceId: string): PlanningSeed {
  if (!resourceId.startsWith("B-01-S")) return seed;
  return {
    ...seed,
    calendarEvents: [
      ...(seed.calendarEvents ?? []),
      ...(seed.calendarEvents ?? []).filter((event) => event.machineId === "B-01").map((event) => ({ ...event, id: `${event.id}-${resourceId}`, machineId: resourceId })),
    ],
  };
}

function downstreamPlannedHours(operations: ProcessOperation[], resourceId: string, serial: number, capacityHours: number): number {
  if (capacityHours <= 0) return 0;
  const hours = operations
    .filter((operation) => !operation.actual && operation.resourceId === resourceId)
    .reduce((sum, operation) => sum + overlapHours(operation.start, operation.end, serial, capacityHours), 0);
  return Math.min(capacityHours, Math.max(0, hours));
}

function resourceCapacity(
  seed: PlanningSeed,
  selectedRange: ReturnType<typeof range>,
  input: { id: string; name: string; shiftFactor: number; process: Exclude<ProcessKind, "washing">; availableStart?: number; planEnd?: number; plannedHours: (serial: number, capacityHours: number) => number },
): MachineCapacity {
  const shiftHours = getSetupSettings(seed).shiftHours;
  const calendarSeed = processCalendarSeed(seed, input.id);
  const machine = { id: input.id, shiftFactor: input.shiftFactor };
  const days = selectedRange.days.map((serial): CapacityDay => {
    const capacity = machineDayCapacity(calendarSeed, machine, serial);
    const baseRegularHours = regularMachineShifts(calendarSeed, machine, serial) * shiftHours;
    const insidePlanningWindow = (!input.availableStart || serial >= Math.floor(input.availableStart)) && (!input.planEnd || serial <= Math.floor(input.planEnd));
    const regularHours = insidePlanningWindow ? Math.min(capacity.shifts, regularMachineShifts(calendarSeed, machine, serial)) * shiftHours : 0;
    const availableHours = insidePlanningWindow ? capacity.shifts * shiftHours : 0;
    const overtimeCapacityHours = Math.max(0, availableHours - regularHours);
    const downtimeHours = Math.max(0, baseRegularHours - availableHours);
    const plannedHours = input.plannedHours(serial, availableHours);
    const regularLoadHours = Math.min(plannedHours, regularHours);
    const overtimeLoadHours = Math.max(0, plannedHours - regularHours);
    return { serial, kind: capacity.kind, label: insidePlanningWindow ? capacity.label : "Plan penceresi dışında", availableHours, regularHours, overtimeCapacityHours, downtimeHours, plannedHours, regularLoadHours, overtimeLoadHours, utilization: availableHours > 0 ? plannedHours / availableHours : 0 };
  });
  const availableHours = days.reduce((sum, day) => sum + day.availableHours, 0);
  const plannedHours = days.reduce((sum, day) => sum + day.plannedHours, 0);
  const overtimeCapacityHours = days.reduce((sum, day) => sum + day.overtimeCapacityHours, 0);
  const overtimeLoadHours = days.reduce((sum, day) => sum + day.overtimeLoadHours, 0);
  const regularLoadHours = days.reduce((sum, day) => sum + day.regularLoadHours, 0);
  const downtimeHours = days.reduce((sum, day) => sum + day.downtimeHours, 0);
  return { process: input.process, machineId: input.id, machineName: input.name, availableHours, plannedHours, regularLoadHours, idleHours: Math.max(0, availableHours - plannedHours), overtimeCapacityHours, overtimeLoadHours, downtimeHours, utilization: availableHours > 0 ? plannedHours / availableHours : 0, days };
}

export function buildCapacityReport(seed: PlanningSeed, result: ScenarioResult, startValue: number, endValue: number, options: { includeInactive?: boolean; includeDownstream?: boolean } = {}): CapacityReport {
  const selectedRange = range(startValue, endValue);
  const turningMachines = seed.machines
    .filter((machine) => options.includeInactive || machine.active)
    .map((machine) => resourceCapacity(seed, selectedRange, { id: machine.id, name: machine.name, shiftFactor: machine.shiftFactor, process: "turning", plannedHours: (serial, capacityHours) => machinePlannedHours(seed, result, machine, serial, capacityHours) }));
  const downstreamOperations = options.includeDownstream ? buildDownstreamProcessPlan(seed, result).operations : [];
  const downstreamMachines = options.includeDownstream ? (seed.processMasterData?.resources ?? [])
    .filter((resource) => resource.process !== "turning" && (options.includeInactive || resource.active))
    .map((resource) => resourceCapacity(seed, selectedRange, { id: resource.id, name: resource.name, shiftFactor: resource.defaultShifts, process: resource.process, availableStart: resource.availableStart, planEnd: resource.planEnd, plannedHours: (serial, capacityHours) => downstreamPlannedHours(downstreamOperations, resource.id, serial, capacityHours) })) : [];
  const machines = [...turningMachines, ...downstreamMachines]
    .sort((left, right) => left.machineId.localeCompare(right.machineId, "tr", { numeric: true }));

  const availableHours = machines.reduce((sum, machine) => sum + machine.availableHours, 0);
  const plannedHours = machines.reduce((sum, machine) => sum + machine.plannedHours, 0);
  return {
    start: selectedRange.start,
    end: selectedRange.end,
    dayCount: selectedRange.days.length,
    availableHours,
    plannedHours,
    idleHours: Math.max(0, availableHours - plannedHours),
    overtimeCapacityHours: machines.reduce((sum, machine) => sum + machine.overtimeCapacityHours, 0),
    overtimeLoadHours: machines.reduce((sum, machine) => sum + machine.overtimeLoadHours, 0),
    downtimeHours: machines.reduce((sum, machine) => sum + machine.downtimeHours, 0),
    utilization: availableHours > 0 ? plannedHours / availableHours : 0,
    machines,
  };
}

export function buildOvertimeEntries(seed: PlanningSeed, startValue: number, endValue: number, machineId?: string): OvertimeEntry[] {
  const selectedRange = range(startValue, endValue);
  const shiftHours = getSetupSettings(seed).shiftHours;
  const resources = [
    ...seed.machines.filter((machine) => machine.active).map((machine) => ({ id: machine.id, name: machine.name, shiftFactor: machine.shiftFactor, process: "turning" as const })),
    ...(seed.processMasterData?.resources ?? []).filter((resource) => resource.active && resource.process !== "turning").map((resource) => ({ id: resource.id, name: resource.name, shiftFactor: resource.defaultShifts, process: resource.process })),
  ];
  return resources
    .filter((resource) => !machineId || resource.id === machineId)
    .flatMap((resource) => selectedRange.days.flatMap((serial) => {
      const calendarSeed = processCalendarSeed(seed, resource.id);
      const capacity = machineDayCapacity(calendarSeed, { id: resource.id, shiftFactor: resource.shiftFactor }, serial);
      const extraShiftCount = Math.max(0, capacity.shifts - regularMachineShifts(calendarSeed, { shiftFactor: resource.shiftFactor }, serial));
      return extraShiftCount > 0 ? [{
        id: `${resource.id}-${serial}`,
        machineId: resource.id,
        machineName: resource.name,
        serial,
        shiftCount: capacity.shifts,
        extraShiftCount,
        overtimeHours: extraShiftCount * shiftHours,
        label: capacity.label,
        process: resource.process,
      }] : [];
    }))
    .sort((left, right) => left.serial - right.serial || left.machineId.localeCompare(right.machineId, "tr", { numeric: true }));
}

export function suggestedCapacityRange(seed: PlanningSeed, result: ScenarioResult): { start: number; end: number } {
  const activeMachines = seed.machines.filter((machine) => machine.active);
  const planned = result.batches.filter((batch) => batch.status === "planned");
  const starts = [
    ...planned.map((batch) => batch.start),
    ...activeMachines.filter((machine) => machine.currentJob.product).map((machine) => machine.currentJob.start),
  ].filter((value) => Number.isFinite(value) && value > 0);
  const ends = [
    ...planned.map((batch) => batch.end),
    ...activeMachines.filter((machine) => machine.currentJob.product).map((machine) => machine.currentJob.end),
  ].filter((value) => Number.isFinite(value) && value > 0);
  const fallback = Math.floor(Math.min(...activeMachines.map((machine) => machine.availableStart).filter((value) => value > 0)));
  const start = Math.floor(starts.length ? Math.min(...starts) : (Number.isFinite(fallback) ? fallback : Date.now() / 86_400_000 + 25_569));
  const planEnd = Math.ceil(ends.length ? Math.max(...ends) : start + 29);
  return { start, end: Math.max(start, Math.min(planEnd, start + 29)) };
}

