import type { PlanningSeed } from "./planning";
import { createCubukFiltreSeed, CUBUK_FILTRE_SOURCE } from "./cubuk-filtre";
import { processLabel } from "./process-master-data";

export type FilterCatalogReview = { seed: PlanningSeed; changes: string[]; preserved: string[] };
const labels: Record<string, string> = { resourcePriority: "Kaynak önceliği", unitsPerShift: "Adet / vardiya", setupMinutesByResource: "Setup / Ayar", handlingMinutes: "İş emri hazırlığı", finishGapMinutes: "Frekans Beklemesi", leadStages: "Tamamlanma Beklemesi", route: "Rota", generalMachine: "Ana tezgah", eligibleMachines: "Uygun tezgahlar", alternativeMachines: "Alternatif tezgahlar", turningSetupMinutes: "Torna setup", shiftRate: "Adet / vardiya", dailyRate: "Günlük adet", parameterDailyRate: "Günlük adet" };
const equal = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);
const object = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);

/** Three-way source update: only unchanged foundation values may be replaced.
 * Arrays (routes/priorities) are deliberate choices and merge as whole values. */
export function previewFilterCatalogUpdate(seed: PlanningSeed): FilterCatalogReview {
  if (seed.productionArea !== "cubuk-filtre" || !seed.processMasterData) throw new Error("Çubuk Filtre üretim verileri bulunamadı.");
  const result: FilterCatalogReview = { seed: structuredClone(seed), changes: [], preserved: [] };
  if ((seed.filterCatalogVersion ?? 1) >= 3) return result;
  const before = createCubukFiltreSeed("2026-09-30", (seed.filterCatalogVersion ?? 1) >= 2 ? 2 : 1), after = createCubukFiltreSeed("2026-09-30");
  function merge(current: unknown, old: unknown, next: unknown, label: string): unknown {
    if (equal(old, next) || equal(current, next)) return structuredClone(current);
    if (equal(current, old)) { result.changes.push(label); return structuredClone(next); }
    if (object(current) && object(next) && (object(old) || old === undefined)) {
      const merged = structuredClone(current);
      for (const key of Object.keys(next)) merged[key] = merge(current[key], object(old) ? old[key] : undefined, next[key], `${label} / ${labels[key] ?? key}`);
      return merged;
    }
    result.preserved.push(label);
    return structuredClone(current);
  }
  for (const next of after.products) {
    const product = result.seed.products.find(p => p.product === next.product);
    const old = before.products.find(p => p.product === next.product)!;
    if (!product) { result.preserved.push(`${next.product}: mevcut katalogda yok`); continue; }
    Object.assign(product, merge(product, old, next, next.product));
    const currentMaster = result.seed.processMasterData!.products.find(p => p.product === next.product);
    const oldMaster = before.processMasterData!.products.find(p => p.product === next.product)!;
    const nextMaster = after.processMasterData!.products.find(p => p.product === next.product)!;
    if (currentMaster) {
      const hasActual = seed.wipLots?.some(p => p.product === next.product) || seed.productionHistory?.some(p => p.product === next.product) || seed.processCurrentJobs?.some(p => p.product === next.product) || seed.machines.some(m => m.currentJob.product === next.product && (m.currentJob.remainingQuantity ?? m.currentJob.quantity) > 0);
      if (hasActual && !equal(currentMaster.route, nextMaster.route)) {
        result.preserved.push(`${next.product}: gerçek üretim nedeniyle mevcut rota ve prosesler korundu`);
      } else {
        currentMaster.route = merge(currentMaster.route, oldMaster.route, nextMaster.route, `${next.product}: rota`) as typeof currentMaster.route;
        for (const parameter of nextMaster.processes) {
          const currentParameter = currentMaster.processes.find(p => p.process === parameter.process);
          const oldParameter = oldMaster.processes.find(p => p.process === parameter.process);
          const label = `${next.product}: ${processLabel(parameter.process)}`;
          if (currentParameter) Object.assign(currentParameter, merge(currentParameter, oldParameter, parameter, label));
          else if (!oldParameter) { currentMaster.processes.push(structuredClone(parameter)); result.changes.push(label); }
          else result.preserved.push(`${label}: kullanıcı tarafından kaldırılmış`);
        }
      }
    }
    for (const machine of result.seed.machines) {
      const previous = before.machines.find(m => m.id === machine.id), updated = after.machines.find(m => m.id === machine.id);
      if (previous && updated) machine.rates[next.product] = merge(machine.rates[next.product], previous.rates[next.product], updated.rates[next.product], `${next.product}: ${machine.id} adet/vardiya`) as number;
    }
    const preference = result.seed.preferences.find(p => p.key === next.product);
    const nextPreference = after.preferences.find(p => p.key === next.product)!;
    const oldPreference = before.preferences.find(p => p.key === next.product)!;
    if (preference) preference.machines = merge(preference.machines, oldPreference.machines, nextPreference.machines, `${next.product}: tezgah önceliği`) as string[];
  }
  result.seed.filterCatalogVersion = 3;
  result.seed.source = CUBUK_FILTRE_SOURCE.sourceFile;
  result.seed.processMasterData!.source = structuredClone(after.processMasterData!.source);
  if (result.changes.length) result.seed.planNeedsRecalculation = true;
  return result;
}

export function applyFilterCatalogUpdate(seed: PlanningSeed): void {
  const review = previewFilterCatalogUpdate(seed);
  Object.assign(seed, review.seed);
}

/** Readiness reflects the saved parameters, not Excel's incomplete status formulas. */
export function filterProductIssues(seed: PlanningSeed, code: string): string[] {
  const product = seed.products.find(p => p.product === code);
  const master = seed.processMasterData?.products.find(p => p.product === code);
  if (!product || !master?.route?.length) return ["Operasyon rotası yok; üretim verisi bekleniyor"];
  const issues: string[] = [];
  if (!(product.batchSize > 0)) issues.push("Şarj Büyüklüğü girilmeli");
  if (master.route.includes("turning") && !product.eligibleMachines.some(id => (seed.machines.find(m => m.id === id)?.rates[code] ?? 0) > 0 && Number.isFinite(product.turningSetupMinutes?.[id]))) issues.push("Torna: çevrim veya setup eksik");
  for (const stage of master.route.filter(p => p !== "turning")) {
    const parameter = master.processes.find(p => p.process === stage);
    if (!parameter?.resourcePriority.some(id => parameter.unitsPerShift[id] > 0 && Number.isFinite(parameter.setupMinutesByResource?.[id]))) issues.push(`${processLabel(stage)}: çevrim veya setup eksik`);
  }
  return issues;
}

