import type { PlanningSeed, Product } from "./planning";
import { FILTER_PROCESS_ORDER, type ProcessKind, type DownstreamProcess } from "./process-master-data";

export type FilterProductDetails = Pick<Product, "customer" | "targetWarehouse" | "batchSize" | "moq" | "shipmentMultiple" | "setupScrapPercent" | "productionScrapPercent"> & { diameter?: string };
export function applyFilterProductDetails(seed: PlanningSeed, code: string, details: FilterProductDetails) {
  const product = seed.products.find(p => p.product === code);
  if (seed.productionArea !== "cubuk-filtre" || !product) throw new Error("Çubuk Filtre ürünü bulunamadı.");
  for (const value of [details.batchSize, details.moq, details.shipmentMultiple ?? 0]) if (!Number.isSafeInteger(value) || value < 0) throw new Error("Adetler sıfır veya pozitif tam sayı olmalıdır. Sıfır şarjla otomatik üretim planlanamaz.");
  for (const value of [details.setupScrapPercent, details.productionScrapPercent]) if (value === undefined || !Number.isFinite(value) || value < 0 || value > 100) throw new Error("Iskarta oranı 0–100 arasında olmalıdır.");
  if ((details.setupScrapPercent ?? 0) + (details.productionScrapPercent ?? 0) >= 100) throw new Error("Toplam ıskarta %100'den küçük olmalıdır.");
  Object.assign(product, details);
  seed.planNeedsRecalculation = true;
}

export function addFilterProduct(seed: PlanningSeed, rawCode: string) {
  const code = rawCode.trim().toUpperCase();
  if (seed.productionArea !== "cubuk-filtre" || !code || code.length > 100 || seed.products.some(p => p.product === code)) throw new Error("Benzersiz bir ürün kodu girin.");
  seed.products.push({ product: code, setupFamily: "cubuk-filtre", generalMachine: "", eligibleMachines: [], alternativeMachines: [], batchSize: 0, dailyRate: 0, shiftRate: 0, parameterDailyRate: 0, diameter: "", moq: 0, source: "Manuel üretim verisi", turningSetupMinutes: {}, handlingMinutes: 30, setupScrapPercent: 0, productionScrapPercent: 0 });
  seed.processMasterData!.products.push({ product: code, family: "cubuk-filtre", productGroup: "cubuk-filtre", route: [...FILTER_PROCESS_ORDER], processes: [] });
  seed.orderCatalog = [...(seed.orderCatalog ?? []), code];
  seed.planNeedsRecalculation = true;
}

export function saveFilterResourceRate(seed: PlanningSeed, code: string, process: ProcessKind, id: string, rate: number, setupMinutes: number, handlingMinutes: number) {
  const product = seed.products.find(p => p.product === code);
  const master = seed.processMasterData?.products.find(p => p.product === code);
  const resource = seed.processMasterData?.resources.find(r => r.id === id && r.process === process);
  if (seed.productionArea !== "cubuk-filtre" || !product || !master || !resource) throw new Error("Ürün ve kaynak eşleşmesini kontrol edin.");
  if (!Number.isFinite(rate) || rate <= 0 || !Number.isFinite(setupMinutes) || setupMinutes < 0 || !Number.isFinite(handlingMinutes) || handlingMinutes < 0) throw new Error("Vardiyalık üretim pozitif; setup ve hazırlık sıfır veya pozitif olmalıdır.");
  if (process === "turning") {
    const machine = seed.machines.find(m => m.id === id)!;
    machine.rates[code] = rate;
    product.turningSetupMinutes = { ...product.turningSetupMinutes, [id]: setupMinutes };
    product.handlingMinutes = handlingMinutes;
    product.eligibleMachines = [...new Set([...product.eligibleMachines, id])];
    product.alternativeMachines = [...product.eligibleMachines];
    product.generalMachine ||= id;
    product.shiftRate ||= rate;
    product.dailyRate = product.shiftRate * 3;
    product.parameterDailyRate = product.dailyRate;
    const preference = seed.preferences.find(p => p.key === code);
    if (preference) preference.machines = [...product.eligibleMachines];
    else seed.preferences.push({ key: code, machines: [...product.eligibleMachines], ruleType: "Öncelik", description: "Operasyon rotası", source: "Parametreler" });
  } else {
    let parameter = master.processes.find(p => p.process === process);
    if (!parameter) {
      parameter = { process: process as DownstreamProcess, sequence: FILTER_PROCESS_ORDER.indexOf(process), waitWorkdaysBefore: 0, setupKey: code, resourcePriority: [], unitsPerShift: {}, setupMinutesByResource: {}, handlingMinutes };
      master.processes.push(parameter);
    }
    parameter.resourcePriority = [...new Set([...parameter.resourcePriority, id])];
    parameter.unitsPerShift[id] = rate;
    parameter.setupMinutesByResource = { ...parameter.setupMinutesByResource, [id]: setupMinutes };
    parameter.handlingMinutes = handlingMinutes;
  }
  master.route = master.route?.length ? FILTER_PROCESS_ORDER.filter(p => master.route!.includes(p) || p === process) : [...FILTER_PROCESS_ORDER];
  seed.planNeedsRecalculation = true;
}

export function validateFilterShipment(seed: PlanningSeed, code: string, quantity: number) {
  if (seed.productionArea !== "cubuk-filtre") return;
  const product = seed.products.find(p => p.product === code);
  if (!product || product.moq <= 0) throw new Error("Min. Sevkiyat Adedi tanımlanmalı.");
  if (quantity < product.moq || (product.shipmentMultiple ?? 0) > 0 && quantity % product.shipmentMultiple! !== 0) throw new Error("Teslim adedi Min. Sevkiyat Adedi ve Sevkiyat Katı kuralına uymuyor.");
}

