import data from "../data/cubuk-filtre.json";
import legacyData from "../data/cubuk-filtre-v1.json";
import type { PlanningSeed, Product, Machine } from "./planning";
import { FILTER_PROCESS_ORDER, type ProcessKind, type ProcessMasterData, type ProductProcessParameter } from "./process-master-data";
import { factoryDateInput } from "./factory-time";

export const CUBUK_FILTRE_SOURCE = data;
const processIds: Record<string, ProcessKind> = { TORNA: "turning", GTM: "gtm", "ÇAP TAŞLAMA": "diameter-grinding", "FORM TAŞLAMA": "form-grinding", "ÖLÇME": "measuring", FREZE: "milling", "FİNAL KONTROL": "final-inspection", "GÖZ KONTROL": "filter-visual" };
export function filterShiftRate(cycleSeconds: number, shiftHours: number, breakMinutes: number, oee: number): number {
  if (!(cycleSeconds > 0 && shiftHours > 0 && breakMinutes >= 0 && breakMinutes < shiftHours * 60 && oee > 0 && oee <= 1)) throw new Error("Çevrim, vardiya, duruş veya verimlilik geçersiz.");
  return Math.floor((shiftHours * 60 - breakMinutes) * 60 * oee / cycleSeconds);
}
export function createCubukFiltreSeed(day = factoryDateInput(), version: 1 | 2 | 3 = 3): PlanningSeed {
  const source = version === 1 ? legacyData : data;
  const operations = source.operations as Array<{ product: string; process: string; sequence: number; resourceId: string | null; cycleSeconds: number | null; setupMinutes: number | null; handlingMinutes: number; completionMinutes?: number; frequencyMinutes?: number; flowType?: string }>;
  const start = (Date.parse(`${day}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86400000;
  const resources = data.resources.map(r => ({ id: r.id, sourceProgramId: r.id, erpWorkCenterCode: r.workCenterCode, name: r.name.trim(), operationCode: r.id.split("-")[0], operationName: r.process, process: processIds[r.process], active: true, defaultShifts: 1 as const, eligibleProductGroups: ["cubuk-filtre"] }));
  const rates = (product: string, resourceId: string) => {
    const op = operations.find(o => o.product === product && o.resourceId === resourceId);
    const r = data.resources.find(r => r.id === resourceId)!;
    return op?.cycleSeconds ? filterShiftRate(op.cycleSeconds, r.shiftHours, r.breakMinutes, r.oee) : 0;
  };
  const products: Product[] = data.products.map(p => {
    const turning = operations.filter(o => o.product === p.product && o.process === "TORNA");
    const ids = turning.map(o => o.resourceId!).filter(Boolean);
    const rate = ids.length ? rates(p.product, ids[0]) : 0;
    return { product: p.product, setupFamily: "cubuk-filtre", customer: p.customer, targetWarehouse: p.warehouse, shipmentMultiple: p.shipmentMultiple,
      setupScrapPercent: Number((p.setupScrap * 100).toFixed(6)), productionScrapPercent: Number((p.productionScrap * 100).toFixed(6)),
      turningSetupMinutes: Object.fromEntries(turning.filter(o => o.setupMinutes !== null).map(o => [o.resourceId!, o.setupMinutes!])), handlingMinutes: turning[0]?.handlingMinutes ?? 30,
      generalMachine: ids[0] ?? "", eligibleMachines: ids, alternativeMachines: ids, batchSize: p.batchSize,
      moq: p.minimumShipment, diameter: p.diameter, shiftRate: rate, dailyRate: rate * 3, parameterDailyRate: rate * 3,
      source: "01_URUNLER / 04_OPERASYON ROTASI" };
  });
  const master: ProcessMasterData = { version: 1, source: { kind: "one-time-foundation", files: [source.sourceFile], calculatedOnce: version === 1 ? "2026-09-22" : "2026-09-30" }, machineCodeStandard: [], resources,
    products: data.products.map(p => {
      const productOperations = operations.filter(o => o.product === p.product);
      const route = FILTER_PROCESS_ORDER.filter(process => productOperations.some(o => processIds[o.process] === process));
      const processes: ProductProcessParameter[] = route.filter(p => p !== "turning").map(process => {
        const rows = productOperations.filter(o => processIds[o.process] === process);
        const ids = [...new Set(rows.map(o => o.resourceId!).filter(Boolean))];
        const previousSequence = Math.max(0, ...productOperations.filter(o => processIds[o.process] && o.sequence < rows[0].sequence).map(o => o.sequence));
        const leadStages = productOperations.filter(o => !processIds[o.process] && o.sequence > previousSequence && o.sequence < rows[0].sequence && (o.completionMinutes ?? 0) > 0)
          .map(o => ({ label: o.process === "ISIL İŞLEM" ? "Isıl İşlem" : "Fosfat Kaplama / ortak Yıkama hattı", days: version === 3 && o.process === "ISIL İŞLEM" ? 3 : o.completionMinutes! / 1440, ...(version === 3 ? { calendarMode: o.process === "ISIL İŞLEM" ? "workdays" as const : "workhours" as const } : {}) }));
        return { process, sequence: rows[0].sequence, waitWorkdaysBefore: 0, setupKey: p.product, resourcePriority: ids,
          unitsPerShift: Object.fromEntries(ids.map(id => [id, rates(p.product, id)])),
          setupMinutesByResource: Object.fromEntries(rows.filter(o => o.setupMinutes !== null).map(o => [o.resourceId!, o.setupMinutes!])), handlingMinutes: rows[0].handlingMinutes,
          ...(version === 1 ? process === "final-inspection" ? { leadStages: [{ label: "Isıl İşlem", days: 2 }, { label: "Fosfat Kaplama / ortak Yıkama hattı", days: 0.5 }] } : {} : {
            ...(leadStages.length ? { leadStages } : {}),
            ...(rows[0].flowType?.startsWith("Dinamik") ? { finishGapMinutes: rows[0].frequencyMinutes } : {}),
          }) };
      });
      return { product: p.product, family: "cubuk-filtre", productGroup: "cubuk-filtre", route: version === 1 ? [...FILTER_PROCESS_ORDER] : route, processes };
    }) };
  const machines: Machine[] = resources.filter(r => r.process === "turning").map(r => ({ id: r.id, name: r.name, active: true, availableStart: start, operationalAvailableStart: start, planEnd: start + 90, note: "", shiftFactor: 1, capacityFactor: 1, finishOffset: 0,
    rates: Object.fromEntries(products.map(p => [p.product, rates(p.product, r.id)])), currentJob: { workOrder: "", product: "", quantity: 0, remainingQuantity: 0, originalQuantity: 0, start: 0, end: 0, dailyRate: 0, diameter: "" } }));
  return { productionArea: "cubuk-filtre", ...(version >= 2 ? { filterCatalogVersion: version } : {}), source: source.sourceFile, schemaVersion: 20, machineCatalogVersion: 1, products, machines, processMasterData: master,
    orders: [], orderCatalog: products.map(p => p.product), orderCatalogName: "230-Çubuk Filtre", preferences: products.map(p => ({ key: p.product, machines: p.eligibleMachines, ruleType: "Öncelik", description: "Operasyon rotası kaynak sırası", source: "04_OPERASYON ROTASI" })),
    restrictions: [], holidays: [], calendarEvents: [], savedBatches: [], manualBatches: [], productionHistory: [], wipLots: [], wipMovements: [], processCurrentJobs: [], processOperationOverrides: [], productionInterruptions: [],
    setupSettings: { model: "product-family", shiftHours: 8, sameDiameterHours: 1, differentDiameterHours: 3, sameFamilyDifferentDiameterHours: 2, crossFamilyHours: 5 },
    openingStock: {}, rawMaterialSettings: { scrapPercent: 2.4, stockDate: "", stocks: [] },
    productWeights: data.products.map(p => ({ product: p.product, productName: p.name, materialCode: p.materialCode, materialName: p.materialName, grams: p.grams, sourceRow: p.sourceRow })),
    activePlanningScope: { startPeriod: day.slice(0, 7), endPeriod: day.slice(0, 7) }, planNeedsRecalculation: false };
}

