import { promoteFilterMonthlyEvidence } from "./filter-monthly-demand";
import type { Order, PlanningSeed } from "./planning";
import { createOrderImportMetadata } from "./delivery-deduction";

export type DailyDemandRow = { date: string; product: string; ordered: number; delivered: number; sourceCells: string[] };
/** Çalışma Günler sheet: monthly working days and monthly quantities. Grey rows are internal production, orange rows external. */
export type FilterMonthlyPlan = { sheetName: string; year: number; workingDays: number[]; rows: Array<{ label: string; product: string; kind: "internal" | "external"; quantities: number[]; sourceRow: number }> };
export type SavedFilterMonthlyPlan = FilterMonthlyPlan & { sourceFile: string; importedAt: string };
export type DailyDemandPreview = { format: "filter-daily"; fileName: string; sheetName: string; dailyRows: DailyDemandRow[]; mappings: Array<{ label: string; product: string; orderColumn: string; deliveryColumn: string }>; monthlyPlan?: FilterMonthlyPlan };
/** startDate is the first counted day. Earlier Sipariş and Teslimat cells are ignored together; saved datasets without it count every row. */
export type DailyDemandDataset = DailyDemandPreview & { startDate?: string; snapshotDate: string; endDate: string; importedAt: string };
const validDate = (value: string) => typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(`${value}T00:00:00Z`)) && new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value;

/** Shipments in the snapshot cover the oldest orders first, once per product. */
export function buildDailyDemandOrders(dataset: DailyDemandDataset): { orders: Order[]; rows: Array<DailyDemandRow & { remaining: number }>; delivered: number; ordered: number } {
  if (!validDate(dataset.snapshotDate) || !validDate(dataset.endDate)) throw new Error("Dosya kesim tarihi ve son sipariş tarihini kontrol edin.");
  const startDate = dataset.startDate ?? "";
  if (startDate && (!validDate(startDate) || startDate > dataset.endDate)) throw new Error("Sipariş başlangıç tarihi geçerli olmalı ve son sipariş tarihinden sonra olamaz.");
  if (!Array.isArray(dataset.dailyRows) || dataset.dailyRows.length > 12000) throw new Error("Günlük sipariş satırları geçersiz.");
  const seen = new Set<string>();
  for (const row of dataset.dailyRows) {
    if (!validDate(row.date) || !row.product || ![row.ordered, row.delivered].every(n => Number.isSafeInteger(n) && n >= 0) || seen.has(`${row.date}:${row.product}`)) throw new Error("Günlük siparişte tarih, ürün veya adet geçersiz / tekrarlı.");
    if (row.delivered && row.date > dataset.snapshotDate) throw new Error(`${row.date}: Teslimat dosya kesim tarihinden sonra. Kesim tarihini kontrol edin.`);
    seen.add(`${row.date}:${row.product}`);
  }
  const source = dataset.dailyRows.filter(row => row.date >= startDate && row.date <= dataset.endDate).sort((a, b) => a.date.localeCompare(b.date) || a.product.localeCompare(b.product));
  const shipments = new Map<string, number>();
  for (const row of dataset.dailyRows) if (row.date >= startDate && row.date <= dataset.snapshotDate) shipments.set(row.product, (shipments.get(row.product) ?? 0) + row.delivered);
  const delivered = [...shipments.values()].reduce((sum, n) => sum + n, 0);
  const rows = source.map(row => {
    const used = Math.min(row.ordered, shipments.get(row.product) ?? 0);
    shipments.set(row.product, (shipments.get(row.product) ?? 0) - used);
    return { ...row, remaining: row.ordered - used };
  });
  const orders: Order[] = [];
  for (const product of [...new Set(source.map(row => row.product))]) {
    const demand = rows.filter(row => row.product === product && row.remaining > 0);
    if (!demand.length) continue;
    let quantity = 0;
    const milestones = demand.map(row => ({ id: `daily-${product}-${row.date}`, date: row.date, quantity: quantity += row.remaining }));
    orders.push({ id: `daily-${product}`, sourceRow: orders.length + 2, product, quantity, savedPlanned: 0, savedDifference: 0, savedMachines: [],
      dueDate: milestones.at(-1)!.date, allowPartial: true, partialDeliveryQuantity: 0, partialDeliveryDate: "", deliveryMilestones: milestones });
  }
  return { orders, rows, delivered, ordered: source.reduce((sum, row) => sum + row.ordered, 0) };
}

export function assertFilterMonthlyPlan(plan: FilterMonthlyPlan, known: Set<string>): void {
  const twelve = (values: unknown) => Array.isArray(values) && values.length === 12;
  if (!Number.isInteger(plan.year) || plan.year < 2000 || plan.year > 2100 || !twelve(plan.workingDays) || plan.workingDays.some(days => !(days >= 0 && days <= 31) || (days * 2) % 1 !== 0)) throw new Error("Çalışma Günleri: yıl veya aylık iş günü geçersiz.");
  if (!Array.isArray(plan.rows) || !plan.rows.length || plan.rows.length > 60) throw new Error("Çalışma Günleri: ürün satırı bulunamadı.");
  for (const row of plan.rows) {
    if (!known.has(row.product) || !["internal", "external"].includes(row.kind) || !twelve(row.quantities) || row.quantities.some(n => !Number.isSafeInteger(n) || n < 0)) throw new Error(`Çalışma Günleri: ${row.label || "satır"} ürünü, türü veya aylık adedi geçersiz.`);
  }
}

export function applyDailyDemandImport(seed: PlanningSeed, input: DailyDemandDataset): void {
  if (seed.productionArea !== "cubuk-filtre") throw new Error("Günlük Çubuk Filtre dosyası yalnız kendi alanına uygulanabilir.");
  // The monthly sheet is kept beside the daily rows; it is a reference table and never creates orders.
  const { monthlyPlan, ...dataset } = input;
  if (monthlyPlan) assertFilterMonthlyPlan(monthlyPlan, new Set(seed.products.map(product => product.product)));
  const state = buildDailyDemandOrders(dataset);
  if (!Number.isFinite(Date.parse(dataset.importedAt)) || dataset.snapshotDate > new Date(Date.parse(dataset.importedAt) + 3 * 3600000).toISOString().slice(0, 10)) throw new Error("Dosya kesim tarihi yükleme gününden sonra olamaz.");
  const known = new Set(seed.products.map(product => product.product));
  if (dataset.dailyRows.some(row => !known.has(row.product))) throw new Error("Sipariş dosyasındaki ürünler Çubuk Filtre parametrelerinde bulunmalıdır.");
  // An unchanged snapshot cannot include shipments made after its first upload.
  // File names, source cell positions and the displayed demand horizon do not
  // change the shipment facts represented by the complete daily rows.
  const previous = seed.dailyCustomerDemand;
  const snapshotRows = (value: DailyDemandDataset) => JSON.stringify(value.dailyRows
    .map(row => [row.date, row.product, row.ordered, row.delivered])
    .sort((a, b) => String(a[0]).localeCompare(String(b[0])) || String(a[1]).localeCompare(String(b[1]))));
  const sameSnapshot = previous?.snapshotDate === dataset.snapshotDate
    && (previous.startDate ?? "") === (dataset.startDate ?? "")
    && Number.isFinite(Date.parse(previous.importedAt))
    && Date.parse(previous.importedAt) <= Date.parse(dataset.importedAt)
    && snapshotRows(previous) === snapshotRows(dataset);
  const importedAt = sameSnapshot ? previous!.importedAt : dataset.importedAt;
  promoteFilterMonthlyEvidence(seed);
  seed.dailyCustomerDemand = structuredClone({ ...dataset, importedAt });
  if (monthlyPlan) seed.filterMonthlyPlan = structuredClone({ ...monthlyPlan, sourceFile: dataset.fileName, importedAt });
  seed.orders = state.orders;
  seed.orderCatalog = [...new Set(dataset.mappings.map(row => row.product))];
  seed.orderCatalogName = dataset.fileName;
  seed.orderImport = createOrderImportMetadata(dataset.fileName, importedAt);
  // The workbook already includes shipments through its closing day.
  seed.orderImport.shipmentsThrough = new Date(Math.min(Date.parse(`${dataset.snapshotDate}T23:59:59.999+03:00`), Date.parse(importedAt))).toISOString();
  seed.orderImportGrossOrders = structuredClone(state.orders);
  delete seed.monthlyCustomerDemand;
  delete seed.customerDemand;
  seed.customerOrderOverrides = [];
  seed.planNeedsRecalculation = true;
}

frontend/lib/dashboard.ts.source:
import type { Machine, PlannedBatch, PlanningSeed, ScenarioResult } from "./planning";

export type DashboardQueueItem = {
  id: string;
  kind: "current" | "planned";
  position: number;
  product: string;
  quantity: number;
  diameter: string;
  workOrder: string;
  end: number;
};

export type MachineDashboard = {
  machine: Machine;
  queue: DashboardQueueItem[];
  plannedCount: number;
  plannedQuantity: number;
};

export type DashboardModel = {
  machines: MachineDashboard[];
  activeMachineCount: number;
  machinesWithWorkCount: number;
  plannedMachineCount: number;
  coverage: number;
};

function hasCurrentJob(machine: Machine): boolean {
  return machine.currentJob.quantity > 0 && /^R/i.test(machine.currentJob.product);
}

function machineNumber(machine: Machine): number {
  return Number(machine.id.replace(/\D/g, "")) || 0;
}

export function buildDashboardModel(seed: PlanningSeed, result: ScenarioResult): DashboardModel {
  const plannedByMachine = new Map<string, PlannedBatch[]>();
  for (const batch of result.batches.filter((item) => item.status === "planned")) {
    plannedByMachine.set(batch.machineId, [...(plannedByMachine.get(batch.machineId) ?? []), batch]);
  }

  const machines = [...seed.machines]
    .sort((left, right) => machineNumber(left) - machineNumber(right))
    .map((machine): MachineDashboard => {
      const planned = (plannedByMachine.get(machine.id) ?? []).sort((left, right) => left.planColumn - right.planColumn || left.sequence - right.sequence);
      const current: DashboardQueueItem[] = hasCurrentJob(machine) ? [{
        id: `${machine.id}-current`,
        kind: "current",
        position: 0,
        product: machine.currentJob.product,
        quantity: machine.currentJob.quantity,
        diameter: machine.currentJob.diameter,
        workOrder: machine.currentJob.workOrder,
        end: machine.currentJob.end,
      }] : [];
      const queue: DashboardQueueItem[] = [
        ...current,
        ...planned.map((batch, index) => ({
          id: batch.id,
          kind: "planned" as const,
          position: index + 1,
          product: batch.product,
          quantity: batch.quantity,
          diameter: batch.diameter,
          workOrder: batch.workOrder ?? "",
          end: batch.end,
        })),
      ];
      return {
        machine,
        queue,
        plannedCount: planned.length,
        plannedQuantity: planned.reduce((sum, batch) => sum + batch.quantity, 0),
      };
    });

  return {
    machines,
    activeMachineCount: seed.machines.filter((machine) => machine.active).length,
    machinesWithWorkCount: machines.filter((board) => board.queue.length > 0).length,
    plannedMachineCount: machines.filter((board) => board.plannedCount > 0).length,
    coverage: result.summary.demand > 0 ? result.summary.planned / result.summary.demand : 0,
  };
}

