import { validateAdviceSettings } from "./stale-charges";
import { assertParameterTransitionDecided } from "./parameter-deactivation";
import { validateProcessStockSettings } from "./process-stock";
import { validateFlowSettings } from "./flow-settings";
import { assertProductionArea } from "./production-area";
import { validateProcessWaitSettings } from "./process-waits";
import { validateProductWeights } from "./product-weights";
import { validateRawMaterialSettings } from "./raw-material-settings";
import { getSetupSettings, recalculateManualScenario, type Machine, type PlanningSeed, type StoredScenario } from "./planning";
import { resolvedProductSetupFamily } from "./setup-families";

export type DataPackageScope = "parameters" | "settings" | "scenarios" | "complete";

/** One workbook: Parametreler ve Ayarlar. Each section keeps its own contract. */
export type CompletePackage = { version: 1; productionArea?: PlanningSeed["productionArea"]; parameters: ParameterPackage; settings: SettingsPackage };

export type ParameterPackage = {
  filterCatalogVersion?: number;
  productionArea?: PlanningSeed["productionArea"];
  processMasterData?: PlanningSeed["processMasterData"];
  products: PlanningSeed["products"];
  preferences: PlanningSeed["preferences"];
  restrictions: PlanningSeed["restrictions"];
  machineRates: Array<Pick<Machine, "id" | "rates">>;
};

export type SettingsPackage = {
  processWaitSettings?: PlanningSeed["processWaitSettings"];
  processStockSettings?: PlanningSeed["processStockSettings"];
  filterQualityShifts?: PlanningSeed["filterQualityShifts"];
  filterWaitShifts?: PlanningSeed["filterWaitShifts"];
  flowSettings?: PlanningSeed["flowSettings"];
  adviceSettings?: PlanningSeed["adviceSettings"];
  productionArea?: PlanningSeed["productionArea"];
  productWeights?: PlanningSeed["productWeights"];
  rawMaterialSettings?: PlanningSeed["rawMaterialSettings"];
  holidays: PlanningSeed["holidays"];
  calendarEvents: NonNullable<PlanningSeed["calendarEvents"]>;
  setupSettings: NonNullable<PlanningSeed["setupSettings"]>;
  machines: Array<Omit<Machine, "rates" | "currentJob">>;
};

function copy<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function objectValue(value: unknown, label: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(`${label} Excel paketi geçerli değil.`);
  return value as Record<string, unknown>;
}

function arrayValue(value: unknown, label: string): unknown[] {
  if (!Array.isArray(value)) throw new Error(`${label} listesi Excel paketinde bulunamadı.`);
  return value;
}

export function parameterPackage(seed: PlanningSeed): ParameterPackage {
  return copy({
    filterCatalogVersion: seed.filterCatalogVersion,
    productionArea: seed.productionArea,
    processMasterData: seed.processMasterData,
    products: seed.products,
    preferences: seed.preferences,
    restrictions: seed.restrictions,
    machineRates: seed.machines.map((machine) => ({ id: machine.id, rates: machine.rates })),
  });
}

export function settingsPackage(seed: PlanningSeed): SettingsPackage {
  return copy({
    productionArea: seed.productionArea,
    holidays: seed.holidays,
    calendarEvents: seed.calendarEvents ?? [],
    setupSettings: getSetupSettings(seed),
    processWaitSettings: seed.processWaitSettings,
    flowSettings: seed.flowSettings,
    adviceSettings: seed.adviceSettings,
    filterWaitShifts: seed.filterWaitShifts,
    filterQualityShifts: seed.filterQualityShifts,
    processStockSettings: seed.processStockSettings,
    productWeights: seed.productWeights,
    rawMaterialSettings: seed.rawMaterialSettings,
    machines: seed.machines.map(({ rates: _rates, currentJob: _currentJob, ...machine }) => machine),
  });
}

export function applyParameterPackage(seed: PlanningSeed, raw: unknown): void {
  const candidate = copy(seed);
  applyParameterPackageUnchecked(candidate, raw);
  assertParameterTransitionDecided(seed, candidate);
  // Checked on a copy first; the caller's objects are then updated in place.
  applyParameterPackageUnchecked(seed, raw);
}

function applyParameterPackageUnchecked(seed: PlanningSeed, raw: unknown): void {
  const value = objectValue(raw, "Parametre");
  assertProductionArea(value, seed.productionArea ?? "torna");
  const products = arrayValue(value.products, "Ürün parametreleri") as PlanningSeed["products"];
  const preferences = arrayValue(value.preferences, "Tezgah öncelikleri") as PlanningSeed["preferences"];
  const restrictions = arrayValue(value.restrictions, "Tezgah kısıtları") as PlanningSeed["restrictions"];
  const machineRates = arrayValue(value.machineRates, "Tezgah üretim hızları") as ParameterPackage["machineRates"];
  if (!products.every((product) => product && typeof product.product === "string")) throw new Error("Excel paketindeki ürün parametreleri geçerli değil.");
  const machineIds = new Set(seed.machines.map((machine) => machine.id));
  const unknownMachine = machineRates.find((item) => !machineIds.has(item.id))?.id
    ?? preferences.flatMap((item) => item.machines ?? []).find((id) => !machineIds.has(id));
  if (unknownMachine) throw new Error(`${unknownMachine} tezgahı uygulamada yok. Önce aynı yedeğin Ayarlar dosyasını içe aktarın.`);
  seed.products = copy(products).map((product) => {
    const setupFamily = resolvedProductSetupFamily(product.product, product.setupFamily);
    return setupFamily ? { ...product, setupFamily } : { ...product, setupFamily: undefined };
  });
  if (value.processMasterData) seed.processMasterData = copy(value.processMasterData) as PlanningSeed["processMasterData"];
  if (seed.productionArea === "cubuk-filtre" && value.processMasterData) seed.filterCatalogVersion = value.filterCatalogVersion === 3 ? 3 : value.filterCatalogVersion === 2 ? 2 : 1;
  seed.preferences = copy(preferences);
  seed.restrictions = copy(restrictions);
  const rateMap = new Map(machineRates.map((item) => [item.id, item.rates]));
  seed.machines.forEach((machine) => { machine.rates = copy(rateMap.get(machine.id) ?? {}); });
}

export function applySettingsPackage(seed: PlanningSeed, raw: unknown): void {
  const value = objectValue(raw, "Ayarlar");
  assertProductionArea(value, seed.productionArea ?? "torna");
  if (value.filterWaitShifts !== undefined && ![0, 1, 2, 3].includes(value.filterWaitShifts as number)) throw new Error("Bekleme vardiyası 0–3 olmalıdır.");
  if (value.filterQualityShifts !== undefined && ![0,1,2,3].includes(value.filterQualityShifts as number)) throw new Error("Kalite vardiyası 0–3 olmalıdır.");
  const stock = value.processStockSettings === undefined ? undefined : validateProcessStockSettings(value.processStockSettings as NonNullable<PlanningSeed["processStockSettings"]>, seed.productionArea);
  const flow = value.flowSettings === undefined ? undefined : validateFlowSettings(value.flowSettings);
  const waits = value.processWaitSettings === undefined ? undefined : validateProcessWaitSettings(value.processWaitSettings);
  const advice = value.adviceSettings === undefined ? undefined : validateAdviceSettings(value.adviceSettings);
  const materials = value.rawMaterialSettings === undefined ? undefined : validateRawMaterialSettings(value.rawMaterialSettings);
  const weights = value.productWeights === undefined ? undefined : validateProductWeights(value.productWeights);
  const holidays = arrayValue(value.holidays, "Tatil günleri") as PlanningSeed["holidays"];
  const calendarEvents = arrayValue(value.calendarEvents, "Tezgah takvimi") as NonNullable<PlanningSeed["calendarEvents"]>;
  const machines = arrayValue(value.machines, "Tezgah ayarları") as SettingsPackage["machines"];
  const setup = objectValue(value.setupSettings, "Setup ayarları") as unknown as SettingsPackage["setupSettings"];
  if (!machines.every((machine) => machine && typeof machine.id === "string" && typeof machine.name === "string")) throw new Error("Excel paketindeki tezgah ayarları geçerli değil.");
  const existing = new Map(seed.machines.map((machine) => [machine.id, machine]));
  seed.machines = machines.map((machine) => {
    const current = existing.get(machine.id);
    return {
      ...copy(machine),
      rates: copy(current?.rates ?? {}),
      currentJob: copy(current?.currentJob ?? {
        workOrder: "", product: "", quantity: 0, originalQuantity: 0, remainingQuantity: 0,
        start: machine.availableStart, end: 0, dailyRate: 0, diameter: "",
      }),
    };
  });
  seed.holidays = copy(holidays);
  seed.calendarEvents = copy(calendarEvents);
  seed.setupSettings = getSetupSettings({ setupSettings: setup });
  if (stock !== undefined) seed.processStockSettings = stock;
  if (flow !== undefined) seed.flowSettings = flow;
  if (value.filterWaitShifts !== undefined) seed.filterWaitShifts = value.filterWaitShifts as PlanningSeed["filterWaitShifts"];
  if (value.filterQualityShifts !== undefined) seed.filterQualityShifts = value.filterQualityShifts as PlanningSeed["filterQualityShifts"];
  if (waits !== undefined) seed.processWaitSettings = waits;
  if (advice !== undefined) seed.adviceSettings = advice;
  if (weights !== undefined) seed.productWeights = weights;
  if (materials !== undefined) seed.rawMaterialSettings = materials;
}

/**
 * A backup import may change parameters and settings but never invalidate
 * recorded work: a machine with live current production cannot disappear,
 * and a queue that was schedulable before must stay schedulable.
 */
function assertRecordedWorkSurvives(before: PlanningSeed, candidate: PlanningSeed): void {
  const kept = new Set(candidate.machines.map(machine => machine.id));
  const lost = before.machines.filter(machine => machine.currentJob.quantity > 0 && !kept.has(machine.id));
  if (lost.length) throw new Error(`${lost.map(machine => `${machine.id} (${machine.currentJob.workOrder || machine.currentJob.product})`).join(", ")} üzerinde çalışan üretim var; bu tezgah yedekte yok. Yedek uygulanmadı.`);
  const queue = (before.manualBatches ?? []).filter(batch => batch.status === "planned");
  if (!queue.length) return;
  try { recalculateManualScenario(before, queue); } catch { return; } // An existing problem is reported elsewhere.
  try { recalculateManualScenario(candidate, queue); } catch (error) {
    throw new Error(`Yedek kayıtlı kuyruğu geçersiz yapıyor: ${error instanceof Error ? error.message : "kuyruk hesaplanamadı"}. Yedek uygulanmadı.`);
  }
}

export function completePackage(seed: PlanningSeed): CompletePackage {
  return { version: 1, productionArea: seed.productionArea, parameters: parameterPackage(seed), settings: settingsPackage(seed) };
}

/**
 * Apply settings, then parameters, as one change. Any failure (area, shape,
 * undecided Pasif transition) leaves the caller's seed unchanged.
 */
export function applyCompletePackage(seed: PlanningSeed, raw: unknown): void {
  const value = objectValue(raw, "Tam yedek");
  if (value.version !== 1) throw new Error("Tam yedek paketinin sürümü desteklenmiyor.");
  assertProductionArea(value, seed.productionArea ?? "torna");
  const candidate = copy(seed);
  applySettingsPackage(candidate, value.settings);
  applyParameterPackageUnchecked(candidate, value.parameters);
  assertParameterTransitionDecided(seed, candidate);
  assertRecordedWorkSurvives(seed, candidate);
  for (const key of Object.keys(seed) as (keyof PlanningSeed)[]) if (!(key in candidate)) delete seed[key];
  Object.assign(seed, candidate);
}

export function scenarioPackage(scenarios: StoredScenario[]): StoredScenario[] {
  return copy(scenarios);
}

export function importedScenarios(raw: unknown): StoredScenario[] {
  if (!Array.isArray(raw)) throw new Error("Senaryolar Excel paketinde bulunamadı.");
  if (!raw.every((scenario) => scenario && typeof scenario.id === "string" && typeof scenario.name === "string" && scenario.seed && scenario.result)) {
    throw new Error("Excel paketindeki senaryolar geçerli değil.");
  }
  return copy(raw as StoredScenario[]);
}

export function dataPackageSummary(scope: DataPackageScope, raw: unknown): string {
  if (scope === "parameters") {
    const value = objectValue(raw, "Parametre");
    return `${arrayValue(value.products, "Ürün parametreleri").length} ürün ve ${arrayValue(value.machineRates, "Tezgah üretim hızları").length} tezgah hız tablosu`;
  }
  if (scope === "settings") {
    const value = objectValue(raw, "Ayarlar");
  const weights = value.productWeights === undefined ? undefined : validateProductWeights(value.productWeights);
    return `${arrayValue(value.machines, "Tezgah ayarları").length} tezgah, ${arrayValue(value.holidays, "Tatil günleri").length} tatil ve ${arrayValue(value.calendarEvents, "Tezgah takvimi").length} takvim kaydı`;
  }
  if (scope === "complete") {
    const value = objectValue(raw, "Tam yedek");
    return `${dataPackageSummary("parameters", value.parameters)}; ${dataPackageSummary("settings", value.settings)}`;
  }
  return `${importedScenarios(raw).length} kayıtlı senaryo`;
}

