import { filterSupplyGoodPieces } from "./filter-monthly-demand";
import { excelSerialToDate, type PlanningSeed, type ScenarioResult } from "./planning";
import { factoryDateInput } from "./factory-time";
import { buildDeliveryReadinessEvents, type DeliveryReadinessEvent } from "./delivery-readiness";
import { effectiveDeliveryTimestamp } from "./delivery-deduction";
import { activeWipLots } from "./wip-ledger";
import { resolvedProductSetupFamily } from "./setup-families";

export type DeliveryPlanColumnKind = "actual" | "actual-before-order" | "actual-after-order" | "carryover" | "plan";

export type DeliveryPlanPayload = {
  startDate: string;
  endDate: string;
  category: string;
  orderDate: string;
  sourceFile: string;
  demandSource: "customer-snapshot" | "imported-orders" | "manual-orders";
  weeks: { label: string; kind: DeliveryPlanColumnKind }[];
  rows: { product: string; family: string; orderQuantity: number; weeklyQuantities: number[] }[];
};

export type DeliveryPlanRange = { startDate: string; endDate: string };

const DAY_MS = 86_400_000;
const MAX_DELIVERY_PLAN_WEEKS = 53;
// Same ceiling as the Excel builder's column limit.
const MAX_DELIVERY_PLAN_DAY_COLUMNS = 160;
const DAY_NAMES = ["Paz", "Pzt", "Sal", "Çar", "Per", "Cum", "Cmt"];

function serialToIsoDate(serial: number): string {
  return excelSerialToDate(Math.floor(serial)).toISOString().slice(0, 10);
}

function isoDateToSerial(value: string): number {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return Number.NaN;
  const timestamp = Date.parse(`${value}T00:00:00Z`);
  if (!Number.isFinite(timestamp) || new Date(timestamp).toISOString().slice(0, 10) !== value) return Number.NaN;
  return (timestamp - Date.UTC(1899, 11, 30)) / DAY_MS;
}

function isoWeek(serial: number): number {
  const date = excelSerialToDate(Math.floor(serial));
  const day = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date.getTime() - yearStart.getTime()) / DAY_MS) + 1) / 7);
}

function weekStart(serial: number): number {
  const date = excelSerialToDate(Math.floor(serial));
  const day = date.getUTCDay() || 7;
  return Math.floor(serial) - day + 1;
}

export function deliveryPlanDefaultRange(today = factoryDateInput()): DeliveryPlanRange {
  const todaySerial = isoDateToSerial(today);
  const start = weekStart(todaySerial);
  return { startDate: serialToIsoDate(start), endDate: serialToIsoDate(start + 41) };
}

function scheduledCompletionEvents(seed: PlanningSeed, result: ScenarioResult) {
  return buildDeliveryReadinessEvents(seed, result);
}

function rangeIncludingCurrentWeek(range: DeliveryPlanRange, today: string): DeliveryPlanRange {
  const currentWeekStart = weekStart(isoDateToSerial(today));
  const start = Math.min(isoDateToSerial(range.startDate), currentWeekStart);
  const end = Math.max(isoDateToSerial(range.endDate), currentWeekStart + 6);
  return { startDate: serialToIsoDate(start), endDate: serialToIsoDate(end) };
}

export function deliveryPlanSuggestedRange(seed: PlanningSeed, result: ScenarioResult, today = factoryDateInput()): DeliveryPlanRange {
  const activeScope = result.planRun?.scope ?? seed.activePlanRun?.scope;
  if (activeScope?.startDate && activeScope.endDate) {
    return rangeIncludingCurrentWeek({ startDate: activeScope.startDate, endDate: activeScope.endDate }, today);
  }
  const completions = scheduledCompletionEvents(seed, result).filter((completion) => completion.readyAt > 0);
  if (!completions.length) return deliveryPlanDefaultRange(today);
  const start = weekStart(Math.min(...completions.map((completion) => completion.readyAt)));
  const end = weekStart(Math.max(...completions.map((completion) => completion.readyAt))) + 6;
  return rangeIncludingCurrentWeek({ startDate: serialToIsoDate(start), endDate: serialToIsoDate(end) }, today);
}

export function deliveryPlanRangeWeekCount(range: DeliveryPlanRange): number {
  const start = isoDateToSerial(range.startDate);
  const end = isoDateToSerial(range.endDate);
  if (!Number.isFinite(start) || !Number.isFinite(end)) throw new Error("Başlangıç ve bitiş tarihini seçin.");
  if (end < start) throw new Error("Bitiş tarihi başlangıç tarihinden önce olamaz.");
  const weekCount = Math.floor((weekStart(end) - weekStart(start)) / 7) + 1;
  if (weekCount > MAX_DELIVERY_PLAN_WEEKS) throw new Error(`Teslimat planı en fazla ${MAX_DELIVERY_PLAN_WEEKS} takvim haftasını kapsayabilir.`);
  return weekCount;
}

export function buildDeliveryPlanPayload(seed: PlanningSeed, result: ScenarioResult, range: DeliveryPlanRange = deliveryPlanDefaultRange(), today = factoryDateInput(), readiness?: { events: DeliveryReadinessEvent[]; products: string[] }): DeliveryPlanPayload {
  const start = isoDateToSerial(range.startDate);
  const end = isoDateToSerial(range.endDate);
  const weekCount = deliveryPlanRangeWeekCount(range);
  const firstWeek = weekStart(start);
  const currentWeekStart = weekStart(isoDateToSerial(today));
  const customerDemand = seed.customerDemand;
  const dailyDemand = seed.dailyCustomerDemand ?? seed.monthlyCustomerDemand;
  const orderDate = customerDemand?.snapshotDate ?? dailyDemand?.snapshotDate ?? "";
  const cutoff = customerDemand || dailyDemand ? isoDateToSerial(orderDate) : Number.NaN;
  if (customerDemand && !Number.isFinite(cutoff)) throw new Error("Müşteri dosyasının sipariş tarihi geçerli değil. Dosyayı yeniden yükleyin.");
  const calendarWeeks = Array.from({ length: weekCount }, (_, index) => ({ start: firstWeek + index * 7, label: `KW${isoWeek(firstWeek + index * 7)}` }));
  const carryoverLots = activeWipLots(seed);
  const carryoverByProduct = new Map<string, number>();
  for (const lot of carryoverLots) {
    const product = lot.product.trim().toUpperCase();
    carryoverByProduct.set(product, (carryoverByProduct.get(product) ?? 0) + filterSupplyGoodPieces(seed, lot.product, Math.max(0, Math.trunc(lot.availableQuantity)), lot.stage === "delivery-ready"));
  }
  const completions = (readiness?.events ?? scheduledCompletionEvents(seed, result))
    .filter((completion) => completion.readyAt >= start && completion.readyAt < end + 1);
  const seenDeliveries = new Set<string>();
  const delivered = (seed.productionHistory ?? []).flatMap((entry) => {
    if (entry.inventoryStatus !== "delivered" || entry.completedQuantity <= 0) return [];
    if (seenDeliveries.has(entry.id)) return [];
    seenDeliveries.add(entry.id);
    const timestamp = effectiveDeliveryTimestamp(entry);
    const deliveredAt = timestamp ? isoDateToSerial(factoryDateInput(timestamp)) : Number.NaN;
    if (!Number.isFinite(deliveredAt) || deliveredAt < start || deliveredAt >= end + 1) return [];
    return [{ id: entry.id, product: entry.product.trim().toUpperCase(), quantity: Math.max(0, Math.trunc(entry.completedQuantity)), deliveredAt, beforeSnapshot: dailyDemand ? Date.parse(timestamp) <= Date.parse(seed.orderImport?.shipmentsThrough ?? "") : deliveredAt < cutoff }];
  });
  type Column = { start: number; span: number; label: string; kind: DeliveryPlanColumnKind };
  const weekColumns = (): Column[] => calendarWeeks.flatMap((calendarWeek): Column[] => {
    const week = { ...calendarWeek, span: 7 };
    const columns: Column[] = [];
    const hasActual = delivered.some((entry) => weekStart(entry.deliveredAt) === week.start);
    if (customerDemand) {
      if (week.start <= weekStart(cutoff)) columns.push({ ...week, label: `${week.label}\nSipariş öncesi\nGerçekleşen`, kind: "actual-before-order" });
      if (week.start >= weekStart(cutoff) && (week.start <= currentWeekStart || hasActual)) columns.push({ ...week, label: `${week.label}\nSipariş sonrası\nGerçekleşen`, kind: "actual-after-order" });
    } else if (week.start <= currentWeekStart || hasActual) {
      columns.push({ ...week, label: `${week.label}\nGerçekleşen`, kind: "actual" });
    }
    if (week.start === currentWeekStart) columns.push({ ...week, label: `${week.label}'e\nDevreden`, kind: "carryover" });
    if (week.start >= currentWeekStart || completions.some((entry) => weekStart(entry.readyAt) === week.start)) columns.push({ ...week, label: `${week.label}\nPlan`, kind: "plan" });
    return columns;
  });
  // Günlük Sevkiyat Planı siparişlerinde sütunlar gündür. Gerçekleşen sütunu yalnız
  // sevkiyat olan günde, Plan sütunu bugünden itibaren her iş gününde açılır.
  const dayColumns = (): Column[] => {
    const todaySerial = isoDateToSerial(today);
    const columns: Column[] = [];
    for (let day = start; day <= end; day += 1) {
      const date = excelSerialToDate(day);
      const label = `${String(date.getUTCDate()).padStart(2, "0")}.${String(date.getUTCMonth() + 1).padStart(2, "0")} ${DAY_NAMES[date.getUTCDay()]}`;
      const actual = delivered.filter((entry) => entry.deliveredAt === day);
      if (actual.some((entry) => entry.beforeSnapshot)) columns.push({ start: day, span: 1, label: `${label}\nSipariş öncesi\nGerçekleşen`, kind: "actual-before-order" });
      if (actual.some((entry) => !entry.beforeSnapshot)) columns.push({ start: day, span: 1, label: `${label}\nSipariş sonrası\nGerçekleşen`, kind: "actual-after-order" });
      if (day === todaySerial) columns.push({ start: day, span: 1, label: `${label}\nDevreden`, kind: "carryover" });
      const planned = completions.some((entry) => Math.floor(entry.readyAt) === day);
      if (planned || day >= todaySerial && date.getUTCDay() !== 0) columns.push({ start: day, span: 1, label: `${label}\nPlan`, kind: "plan" });
    }
    if (!columns.length) columns.push({ start: end, span: 1, label: `${serialToIsoDate(end).slice(8)}.${serialToIsoDate(end).slice(5, 7)}\nPlan`, kind: "plan" });
    if (columns.length > MAX_DELIVERY_PLAN_DAY_COLUMNS) throw new Error(`Günlük teslimat planı en fazla ${MAX_DELIVERY_PLAN_DAY_COLUMNS} sütun içerebilir. Tarih aralığını kısaltın.`);
    return columns;
  };
  const weeks = dailyDemand ? dayColumns() : weekColumns();
  // Sipariş toplamı, seçilen bitiş gününde kesilmez. Excel'de son sütun olarak
  // gösterilen takvim haftasının müşteri taleplerinin tamamını kapsar.
  const orderHorizonEnd = weekStart(end) + 6;
  const orderQuantityByProduct = new Map<string, number>();
  const familyByProduct = new Map<string, string>();
  if (customerDemand) {
    const selectedWeek = customerDemand.weeks.find((week) => isoDateToSerial(week.weekStart) === weekStart(end));
    if (!selectedWeek) throw new Error("Seçilen bitiş haftası müşteri dosyasında yok. Dosyadaki haftalardan birini seçin veya güncel dosyayı yükleyin.");
    for (const item of customerDemand.products) {
      const product = item.product.trim().toUpperCase();
      const point = item.weeklyDemands.find((week) => week.weekId === selectedWeek.id);
      if (!point || !Number.isFinite(point.balance)) throw new Error(`${product} için seçilen haftanın müşteri ihtiyacı bulunamadı.`);
      const quantity = Math.max(0, Math.trunc(-point.balance));
      if (quantity > 0) orderQuantityByProduct.set(product, quantity);
      familyByProduct.set(product, item.family.trim().toUpperCase());
    }
  } else if (dailyDemand) {
    for (const order of seed.orderImportGrossOrders ?? seed.orders) {
      const milestones = (order.deliveryMilestones ?? []).filter(item => item.date <= range.endDate);
      const quantity = !order.dueDate || order.dueDate <= range.endDate ? order.quantity : Math.min(order.quantity, Math.max(0, ...milestones.map(item => item.quantity)));
      if (quantity > 0) orderQuantityByProduct.set(order.product, (orderQuantityByProduct.get(order.product) ?? 0) + quantity);
    }
  } else for (const order of (seed.orderImportGrossOrders?.length ? seed.orderImportGrossOrders : seed.orders).filter((item) => {
    if (item.quantity <= 0) return false;
    const dueAt = isoDateToSerial(item.dueDate);
    return !Number.isFinite(dueAt) || dueAt < orderHorizonEnd + 1;
  })) {
    const product = order.product.trim().toUpperCase();
    orderQuantityByProduct.set(product, (orderQuantityByProduct.get(product) ?? 0) + Math.max(0, Math.trunc(order.quantity)));
  }
  const products = [...new Set([
    ...orderQuantityByProduct.keys(),
    ...delivered.map((entry) => entry.product),
    ...carryoverByProduct.keys(),
    ...completions.map((completion) => completion.product),
    ...(readiness?.products ?? []),
  ])];

  return {
    startDate: range.startDate,
    endDate: range.endDate,
    category: seed.monthlyCustomerDemand ? "Çubuk Filtre · Sağlam adet" : "Üretim",
    orderDate,
    sourceFile: customerDemand?.sourceFile ?? seed.orderImport?.sourceFile ?? "",
    demandSource: customerDemand ? "customer-snapshot" : seed.orderImport ? "imported-orders" : "manual-orders",
    weeks: weeks.map(({ label, kind }) => ({ label, kind })),
    rows: products.map((product) => ({
      product,
      family: familyByProduct.get(product) || (() => {
        const family = resolvedProductSetupFamily(product, seed.products?.find((item) => item.product === product)?.setupFamily);
        return family === "piston" ? "PISTON" : family === "center-pin" ? "CENTER PIN" : family === "cubuk-filtre" ? "ÇUBUK FİLTRE" : "";
      })(),
      orderQuantity: orderQuantityByProduct.get(product) ?? 0,
      weeklyQuantities: weeks.map((week) => {
        if (week.kind === "carryover") return carryoverByProduct.get(product) ?? 0;
        if (week.kind === "actual" || week.kind === "actual-before-order" || week.kind === "actual-after-order") return delivered
          .filter((entry) => week.kind === "actual" || (week.kind === "actual-before-order" ? entry.beforeSnapshot : !entry.beforeSnapshot))
          .filter((entry) => entry.product === product && entry.deliveredAt >= Math.max(start, week.start) && entry.deliveredAt < Math.min(end + 1, week.start + week.span))
          .reduce((sum, entry) => sum + entry.quantity, 0);
        return completions
          .filter((completion) => completion.product === product && completion.readyAt >= Math.max(start, week.start) && completion.readyAt < Math.min(end + 1, week.start + week.span))
          .reduce((sum, completion) => sum + Math.max(0, Math.trunc(completion.quantity)), 0);
      }),
    })),
  };
}

frontend/lib/delivery-readiness.ts.source:
import { filterSupplyGoodPieces } from "./filter-monthly-demand";
import { hasActiveProductionInterruption } from "./production-interruptions";
import { turningDeliveryReadyAt } from "./delivery-calendar";
import { buildDownstreamProcessPlan } from "./process-planning";
import { processMasterDataForProduct } from "./process-master-data";
import { orderProductionBreakdown, semiFinishedProduction, type Order, type PlanningSeed, type ScenarioResult } from "./planning";

export type DeliveryReadinessEvent = {
  id: string;
  product: string;
  quantity: number;
  readyAt: number;
  source: "routed" | "turning-fallback" | "wip-fallback";
  routeSource?: "current-turning" | "turning-plan" | "wip";
  wipLotId?: string;
};

function datedEvents(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, processPlan: ReturnType<typeof buildDownstreamProcessPlan>): DeliveryReadinessEvent[] {
  const representedBatchIds = new Set([
    ...processPlan.jobs.filter((job) => job.source === "turning-plan" && Boolean(seed.processMasterData)).map((job) => job.batchId),
    ...(seed.wipLots ?? []).map((lot) => lot.sourceBatchId).filter(Boolean),
  ]);
  const representedLotIds = new Set(processPlan.jobs.filter((job) => job.source === "wip" && job.deliveryReadyAt > 0).map((job) => job.batchId));

  const routed: DeliveryReadinessEvent[] = processPlan.jobs
    .filter((job) => {
      const lot = seed.wipLots?.find((item) => item.id === job.wipLotId);
      return !lot || (lot.stage !== "on-hold" && lot.stage !== "unclassified");
    })
    .filter((job) => job.quantity > 0 && job.deliveryReadyAt > 0 && (
      Boolean(processMasterDataForProduct(seed.processMasterData, job.product)?.route)
      || job.operations.some((operation) => operation.process === "gkm")
      || (seed.wipLots ?? []).some((lot) => lot.id === job.wipLotId && lot.stage === "delivery-ready")
    ))
    .map((job) => ({ id: `route:${job.batchId}`, product: job.product.toUpperCase(), quantity: filterSupplyGoodPieces(seed,job.product,job.quantity,Boolean(seed.wipLots?.find(lot=>lot.id===job.wipLotId && lot.stage === "delivery-ready"))), readyAt: job.deliveryReadyAt, source: "routed", routeSource: job.source, wipLotId: job.wipLotId }));
  const fallbackBatches: DeliveryReadinessEvent[] = result.batches
    .filter((batch) => !seed.processMasterData && batch.status === "planned" && !hasActiveProductionInterruption(seed, batch.id, batch.interruptionId) && batch.quantity > 0 && batch.end > 0 && !representedBatchIds.has(batch.id))
    .map((batch) => ({ id: `batch:${batch.id}`, product: batch.product.toUpperCase(), quantity: batch.quantity, readyAt: turningDeliveryReadyAt(batch.end), source: "turning-fallback" }));
  const fallbackReadyWip: DeliveryReadinessEvent[] = (seed.wipLots ?? [])
    .filter((lot) => !seed.processMasterData && lot.stage === "delivery-ready" && lot.availableQuantity > 0 && lot.readyAt > 0 && !representedLotIds.has(lot.id))
    .map((lot) => ({ id: `wip:${lot.id}`, product: lot.product.toUpperCase(), quantity: lot.availableQuantity, readyAt: lot.readyAt, source: "wip-fallback" }));

  return [...routed, ...fallbackBatches, ...fallbackReadyWip]
    .filter((event) => Number.isFinite(event.readyAt) && event.readyAt > 0)
    .sort((left, right) => left.readyAt - right.readyAt || left.id.localeCompare(right.id));
}

export function buildDeliveryReadinessEvents(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">): DeliveryReadinessEvent[] {
  return datedEvents(seed, result, buildDownstreamProcessPlan(seed, result));
}

export type UndatedDelivery = {
  id: string; product: string; quantity: number; workOrder: string;
  source: "current-turning" | "turning-plan" | "wip";
  reasons: Array<{ code: string; message: string; process?: string }>;
};

/** Quantity inventory precedes scheduling: no date is never interpreted as no material. */
export function buildDeliveryReadinessProjection(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">) {
  const plan = buildDownstreamProcessPlan(seed, result);
  const events = datedEvents(seed, result, plan);
  const subjects = new Map<string, Omit<UndatedDelivery, "reasons">>();
  const put = (subject: Omit<UndatedDelivery, "reasons">) => {
    if (!Number.isSafeInteger(subject.quantity) || subject.quantity < 0) throw new Error(`${subject.product} için teslimat miktarı geçersiz.`);
    if (subject.quantity > 0) subjects.set(subject.id, subject);
  };
  for (const job of plan.jobs) put({ id: job.batchId, product: job.product, quantity: job.quantity, workOrder: job.workOrder, source: job.source });
  for (const row of seed.processStockSettings?.opening ?? []) if (row.quantity > 0) put({ id: `stock-count:${row.groupId}:${row.product}`, product: row.product, quantity: row.quantity, workOrder: "Grup sayımı · kesin proses konumu gerekli", source: "wip" });
  const lots = seed.wipLots ?? [];
  for (const lot of lots.filter(lot => lot.availableQuantity > 0 && lot.stage !== "delivered" && lot.stage !== "scrapped")) {
    put({ id: lot.id, product: lot.product, quantity: lot.availableQuantity, workOrder: lot.workOrder ?? "", source: "wip" });
  }
  for (const machine of seed.machines.filter(m => m.currentJob.product && m.currentJob.quantity > 0)) {
    put({ id: `current:${machine.id}`, product: machine.currentJob.product, quantity: machine.currentJob.quantity, workOrder: machine.currentJob.workOrder ?? "", source: "current-turning" });
  }
  for (const batch of result.batches.filter(b => b.status === "planned" && b.quantity > 0)) {
    if (!batch.interruptionId && lots.some(lot => lot.sourceBatchId === batch.id)) continue;
    put({ id: batch.id, product: batch.product, quantity: batch.quantity, workOrder: batch.workOrder ?? "", source: "turning-plan" });
  }
  if(seed.monthlyCustomerDemand) for(const entry of semiFinishedProduction(seed)) {
    const linked=lots.filter(l=>l.sourceHistoryEntryId===entry.id&&l.stage!=="delivered"&&l.stage!=="scrapped").reduce((sum,l)=>sum+l.availableQuantity,0);
    if(entry.completedQuantity>linked) put({id:`history:${entry.id}`,product:entry.product,quantity:entry.completedQuantity-linked,workOrder:entry.workOrder,source:"wip"});
  }
  const datedIds = new Set(events.map(e => e.id.replace(/^(route|batch|wip):/, "")));
  const undated: UndatedDelivery[] = [...subjects.values()].filter(s => !datedIds.has(s.id)).map(subject => {
    const job = plan.jobs.find(j => j.batchId === subject.id) as (typeof plan.jobs[number] & { readinessIssues?: UndatedDelivery["reasons"] }) | undefined;
    const warnings = plan.warnings.filter(w => w.batchId === subject.id || !w.batchId && w.product === subject.product);
    const reasons = subject.id.startsWith("stock-count:") ? [{ code: "stock-position", message: "Grup sayımı miktarı korur; sevkiyat tarihi için kesin proses konumu ve şarj kaydı gerekir." }] : job?.readinessIssues?.length ? job.readinessIssues : warnings.length ? warnings.map(w => ({ code: w.code, message: w.message }))
      : [{ code: "missing-schedule", message: "Rota tamamlanmadı; proses, kabul veya kapasite bekleniyor." }];
    return { ...subject, quantity: filterSupplyGoodPieces(seed, subject.product, subject.quantity, Boolean(lots.find(lot => lot.id === subject.id && lot.stage === "delivery-ready")) || subject.id.startsWith("stock-count:warehouse:")), product: subject.product.trim().toUpperCase(), reasons };
  });
  return { events, undated, undatedQuantity: undated.reduce((sum, row) => sum + row.quantity, 0) };
}

export function deliveryReadyQuantityByDate(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, product: string, serial: number): number {
  return deliveryReadyQuantityFromEvents(seed, buildDeliveryReadinessEvents(seed, result), product, serial);
}

export function deliveryReadyQuantityFromEvents(seed: PlanningSeed, events: DeliveryReadinessEvent[], product: string, serial: number): number {
  const code = product.trim().toUpperCase();
  const dueDay = Math.floor(serial);
  const openingStock = seed.customerDemand ? 0 : Math.max(0, seed.openingStock?.[code] ?? 0);
  return openingStock + events
    .filter((event) => event.product === code && Math.floor(event.readyAt) <= dueDay)
    .reduce((sum, event) => sum + event.quantity, 0);
}

export function orderRoutedOnTimeQuantity(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, order: Pick<Order, "product" | "dueDate">): number | null {
  if (!order.dueDate) return null;
  const due = (Date.parse(`${order.dueDate}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000;
  return deliveryReadyQuantityByDate(seed, result, order.product, due);
}

/** Reporting uses final delivery readiness even when the optimizer targets turning capacity. */
export function buildOrderDeliveryResults(seed: PlanningSeed, result: ScenarioResult, events = buildDeliveryReadinessEvents(seed, result)): ScenarioResult["orders"] {
  const pools = new Map<string, Array<{ readyAt: number; remaining: number }>>();
  for (const event of events) {
    const code = event.product.trim().toUpperCase();
    const pool = pools.get(code) ?? [];
    pool.push({ readyAt: event.readyAt, remaining: event.quantity });
    pools.set(code, pool);
  }
  if (!seed.customerDemand) for (const [product, quantity] of Object.entries(seed.openingStock ?? {})) {
    const code = product.trim().toUpperCase();
    pools.set(code, [{ readyAt: 0, remaining: Math.max(0, quantity) }, ...(pools.get(code) ?? [])]);
  }
  const ordered = [...result.orders].sort((a, b) => (a.dueDate || "9999").localeCompare(b.dueDate || "9999") || a.id.localeCompare(b.id));
  const remainingOrders = new Map<string, number>();
  ordered.forEach((order) => {
    const code = order.product.trim().toUpperCase();
    remainingOrders.set(code, (remainingOrders.get(code) ?? 0) + 1);
  });
  const calculated = new Map<string, ScenarioResult["orders"][number]>();
  for (const order of ordered) {
    const code = order.product.trim().toUpperCase();
    const lastOrder = remainingOrders.get(code) === 1;
    remainingOrders.set(code, remainingOrders.get(code)! - 1);
    const due = order.dueDate ? (Date.parse(`${order.dueDate}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : Number.NaN;
    let needed = Math.max(0, order.quantity);
    let onTime = 0;
    for (const source of pools.get(code) ?? []) {
      // Allocate each unit once; surplus belongs to the final order for this product.
      const quantity = lastOrder ? source.remaining : Math.min(needed, source.remaining);
      if (Math.floor(source.readyAt) <= due) onTime += quantity;
      source.remaining -= quantity;
      needed = Math.max(0, needed - quantity);
    }
    calculated.set(order.id, { ...order, ...orderProductionBreakdown(seed, result.batches, order),
      onTimePlanned: Number.isFinite(due) ? onTime : null,
      onTimeDifference: Number.isFinite(due) ? onTime - order.quantity : null });
  }
  return result.orders.map((order) => calculated.get(order.id)!);
}

