import { buildDeliveryPlanPayload, type DeliveryPlanPayload, type DeliveryPlanRange } from "./delivery-plan";
import { recalculateManualScenario, rollForwardUnfinishedProduction, type PlanningSeed, type ScenarioResult } from "./planning";
import { factoryDateInput } from "./factory-time";
import { buildDeliveryReadinessProjection } from "./delivery-readiness";
import { reconcileTurningQueue } from "./turning-queue-identity";
import { assertPlanInputs } from "./plan-integrity";

export type DeliveryReportRow = {
  product: string; demand: number; delivered: number; periodActual: number;
  remaining: number; total: number; difference: number; shortage: number;
};

/** Mirrors Teslimat Planı D/E/F/G/I and the F+I total; carryover is never added. */
export function summarizeDeliveryPlan(payload: DeliveryPlanPayload) {
  const grouped = new Map<string, DeliveryReportRow>();
  for (const row of payload.rows) {
    const product = row.product.trim().toUpperCase();
    const item = grouped.get(product) ?? { product, demand: 0, delivered: 0, periodActual: 0, remaining: 0, total: 0, difference: 0, shortage: 0 };
    item.demand += row.orderQuantity;
    payload.weeks.forEach((week, index) => {
      const quantity = row.weeklyQuantities[index] ?? 0;
      if (week.kind === "plan") item.remaining += quantity;
      if (week.kind === "actual" || week.kind === "actual-after-order") item.delivered += quantity;
      if (week.kind === "actual" || week.kind === "actual-after-order" || week.kind === "actual-before-order") item.periodActual += quantity;
    });
    grouped.set(product, item);
  }
  const rows = [...grouped.values()].map((row) => ({ ...row,
    total: row.periodActual + row.remaining,
    difference: row.delivered + row.remaining - row.demand,
    shortage: Math.min(0, row.delivered + row.remaining - row.demand),
  }));
  const sum = (key: keyof Omit<DeliveryReportRow, "product">) => rows.reduce((total, row) => total + row[key], 0);
  const demand = sum("demand"), shortage = sum("shortage");
  return { rows, demand, delivered: sum("delivered"), remaining: sum("remaining"), total: sum("total"),
    difference: sum("difference"), shortage, coverage: demand > 0 ? 1 + shortage / demand : null,
    types: { listed: rows.length, demand: rows.filter((r) => r.demand > 0).length,
      delivered: rows.filter((r) => r.delivered > 0).length, remaining: rows.filter((r) => r.remaining > 0).length,
      total: rows.filter((r) => r.total > 0).length, covered: rows.filter((r) => r.difference >= 0).length,
      surplus: rows.filter((r) => r.difference > 0).length, shortage: rows.filter((r) => r.shortage < 0).length },
  };
}

export function buildDeliveryReport(inputSeed: PlanningSeed, result: ScenarioResult, range: DeliveryPlanRange, today = factoryDateInput()) {
  try {
    const seed = structuredClone(inputSeed);
    // Same unfinished-WIP forecast floor as browser restore; fixed clock, no operational writes.
    rollForwardUnfinishedProduction(seed, (Date.parse(`${today}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86400000, { turning: false });
    assertPlanInputs(seed, []);
    for (const records of [result.batches, seed.wipLots ?? []]) {
      const ids = records.map(row => row.id);
      if (ids.some(id => !id) || new Set(ids).size !== ids.length) throw new Error("Teslimat hesabında malzeme kimlikleri eksik veya tekrarlı.");
    }
    for (const batch of result.batches) if (!Number.isSafeInteger(batch.quantity) || batch.quantity < 0) throw new Error(`${batch.product}: şarj adedi geçersiz.`);
    for (const lot of seed.wipLots ?? []) {
      const amounts = [lot.availableQuantity, lot.deliveredQuantity ?? 0, lot.scrappedQuantity ?? 0];
      if (amounts.some(n => !Number.isSafeInteger(n) || n < 0) || lot.originalQuantity != null && amounts.reduce((a,b)=>a+b,0) > lot.originalQuantity)
        throw new Error(`${lot.workOrder || lot.product}: yarı mamül miktarları uzlaşmıyor.`);
    }
    const reconciled = reconcileTurningQueue(seed, result.batches);
    if (reconciled.length !== result.batches.length) throw new Error("Şarj kimlikleri çakışıyor; teslimat raporu doğrulanamadı.");
    let projected = result;
    let turningIssue = "";
    const blockedMachines = new Map<string, string>();
    if (seed.planNeedsRecalculation && result.batches.length) {
      try { projected = recalculateManualScenario(structuredClone(seed), structuredClone(result.batches)); }
      catch {
        // T09: one invalid queue must not remove every other machine's pieces
        // from the dated totals. Recalculate per machine; blank only failures.
        const batches = structuredClone(result.batches);
        for (const machine of seed.machines) {
          const queue = batches.filter(batch => batch.machineId === machine.id && batch.status === "planned");
          if (!queue.length) continue;
          try {
            const recalculated = recalculateManualScenario({ ...structuredClone(seed), machines: [structuredClone(machine)] }, queue);
            for (const next of recalculated.batches) { const index = batches.findIndex(batch => batch.id === next.id); if (index >= 0) batches[index] = next; }
          } catch (machineError) {
            blockedMachines.set(machine.id, machineError instanceof Error ? machineError.message : `${machine.id}: Torna tarihleri hesaplanamadı.`);
            for (const batch of queue) { batch.start = 0; batch.end = 0; }
          }
        }
        projected = { ...result, batches };
      }
    }
    if (projected.batches.length !== result.batches.length) throw new Error("Teslimat hesabında kayıtlı şarjlar korunamadı.");
    for (const original of result.batches) {
      const next = projected.batches.find(b => b.id === original.id);
      if (!next || next.quantity !== original.quantity || next.machineId !== original.machineId || next.product !== original.product)
        throw new Error("Teslimat hesabında şarj kimliği veya miktarı korunamadı.");
      if (blockedMachines.has(original.machineId)) continue;
      if ((original.locked || original.manuallyPlaced) && (Math.abs(next.start - original.start) > 1e-7 || Math.abs(next.end - original.end) > 1e-7))
        blockedMachines.set(original.machineId, `${original.workOrder || original.product}: güncel kapasite korunan yerleşimle uyuşmuyor. Yerleşimi inceleyin.`);
    }
    // Only the affected machine's planned pieces lose their dates.
    if (blockedMachines.size) projected = { ...projected, batches: projected.batches.map(batch => batch.status === "planned" && blockedMachines.has(batch.machineId) ? { ...batch, start: 0, end: 0 } : batch) };
    if (turningIssue) projected = { ...result, batches: result.batches.map(batch => batch.status === "planned" ? { ...batch, start: 0, end: 0 } : batch) };
    else projected = { ...projected, batches: projected.batches.map(batch => batch.status === "planned" && (!Number.isFinite(batch.start) || !Number.isFinite(batch.end) || batch.start <= 0 || batch.end < batch.start) ? { ...batch, start: 0, end: 0 } : batch) };
    const readiness = buildDeliveryReadinessProjection(seed, projected);
    if (turningIssue) for (const row of readiness.undated.filter(row => row.source === "turning-plan")) row.reasons = [{ code: "turning-projection-blocked", message: turningIssue }];
    else if (blockedMachines.size) for (const row of readiness.undated.filter(row => row.source === "turning-plan")) {
      const machineId = result.batches.find(batch => batch.id === row.id)?.machineId;
      const message = machineId ? blockedMachines.get(machineId) : undefined;
      if (message) row.reasons = [{ code: "turning-projection-blocked", message }];
    }
    const payload = buildDeliveryPlanPayload(seed, projected, range, today, { events: readiness.events, products: readiness.undated.map(row => row.product) });
    return { ...summarizeDeliveryPlan(payload), ...readiness, payload, error: "", complete: readiness.undated.length === 0 };
  } catch (error) {
    // Same shape as success; totals are null (unknown), never a false zero.
    return { error: error instanceof Error ? error.message : "Teslimat bilgileri hesaplanamadı.", payload: null, rows: [], events: [], undated: [], undatedQuantity: null, complete: false,
      demand: null, delivered: null, remaining: null, total: null, difference: null, shortage: null, coverage: null, types: null };
  }
}
export type DeliveryReport = ReturnType<typeof buildDeliveryReport>;

frontend/lib/demand-import-history.ts.source:
import type { CustomerDemandDataset } from "./planning";

export type DemandImportVersion = {
  id: string;
  importedAt: string;
  sourceFile: string;
  snapshotDate: string;
  dataset: CustomerDemandDataset;
  summary: {
    productCount: number;
    weekCount: number;
    firstWeek: string;
    lastWeek: string;
    totalDemand: number;
  };
};

function stablePart(value: string): string {
  return value.replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 70);
}

export function demandImportVersion(dataset: CustomerDemandDataset): DemandImportVersion {
  const totalDemand = dataset.products.reduce((sum, product) => sum + product.totalDemand, 0);
  return {
    id: `demand-${stablePart(dataset.snapshotDate)}-${stablePart(dataset.importedAt)}-${stablePart(dataset.sourceFile)}`,
    importedAt: dataset.importedAt,
    sourceFile: dataset.sourceFile,
    snapshotDate: dataset.snapshotDate,
    dataset,
    summary: {
      productCount: dataset.products.length,
      weekCount: dataset.weeks.length,
      firstWeek: dataset.weeks[0]?.id ?? "",
      lastWeek: dataset.weeks.at(-1)?.id ?? "",
      totalDemand,
    },
  };
}

export function isDemandImportVersion(value: unknown): value is DemandImportVersion {
  if (!value || typeof value !== "object") return false;
  const version = value as Partial<DemandImportVersion>;
  return typeof version.id === "string"
    && typeof version.importedAt === "string"
    && typeof version.sourceFile === "string"
    && Boolean(version.dataset)
    && Array.isArray(version.dataset?.weeks)
    && Array.isArray(version.dataset?.products);
}

