import type { CumulativeDemandTarget, PeriodId, PlanningScope } from "./planning";
import { comparePeriods, isPeriodId, normalizePlanningScope } from "./planning-state";

export type { CumulativeDemandTarget } from "./planning";

export type DemandRequirement = {
  id: string;
  targetId: string;
  product: string;
  periodId: PeriodId;
  dueDate?: string;
  rawCumulativeQuantity: number;
  effectiveCumulativeQuantity: number;
  quantity: number;
};

export type ProductionSource = {
  id: string;
  product: string;
  kind: "opening-stock" | "current-production" | "planned-production";
  quantity: number;
  availableAt?: string;
};

export type DemandAllocation = {
  sourceId: string;
  demandId: string;
  product: string;
  quantity: number;
  timing: "on-time" | "late" | "undated";
};

export type DemandAllocationResult = {
  demands: Array<DemandRequirement & {
    allocatedQuantity: number;
    onTimeQuantity: number;
    lateQuantity: number;
    undatedQuantity: number;
    shortageQuantity: number;
  }>;
  allocations: DemandAllocation[];
  surplus: Array<ProductionSource & { remainingQuantity: number }>;
};

function normalizedText(value: string, label: string): string {
  const normalized = value.trim();
  if (!normalized) throw new Error(`${label} boş olamaz.`);
  return normalized;
}

function nonNegativeQuantity(value: number, label: string): number {
  if (!Number.isFinite(value) || value < 0) throw new Error(`${label} sıfır veya pozitif bir sayı olmalı.`);
  return value;
}

function normalizedDate(value: string | undefined, label: string): string | undefined {
  if (value == null || value.trim() === "") return undefined;
  const normalized = value.trim();
  const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})(?:T.*)?$/);
  const parsed = Date.parse(normalized);
  if (!match || !Number.isFinite(parsed)) {
    throw new Error(`${label} geçerli bir tarih olmalı.`);
  }
  const [, yearText, monthText, dayText] = match;
  const validationDate = new Date(Date.UTC(Number(yearText), Number(monthText) - 1, Number(dayText)));
  if (
    validationDate.getUTCFullYear() !== Number(yearText)
    || validationDate.getUTCMonth() !== Number(monthText) - 1
    || validationDate.getUTCDate() !== Number(dayText)
  ) {
    throw new Error(`${label} geçerli bir tarih olmalı.`);
  }
  return normalized;
}

function dateTime(value: string | undefined): number {
  return value ? Date.parse(value) : Number.NEGATIVE_INFINITY;
}

function isAvailableByDueDate(availableAt: string | undefined, dueDate: string): boolean {
  if (!availableAt) return true;
  if (/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) return availableAt.slice(0, 10) <= dueDate;
  return dateTime(availableAt) <= dateTime(dueDate);
}

function compareDemandOrder(
  left: Pick<DemandRequirement, "periodId" | "dueDate" | "id">,
  right: Pick<DemandRequirement, "periodId" | "dueDate" | "id">,
): number {
  const periodComparison = comparePeriods(left.periodId, right.periodId);
  if (periodComparison !== 0) return periodComparison;
  if (left.dueDate && right.dueDate) {
    const dateComparison = dateTime(left.dueDate) - dateTime(right.dueDate);
    if (dateComparison !== 0) return dateComparison;
  } else if (left.dueDate) {
    return -1;
  } else if (right.dueDate) {
    return 1;
  }
  return left.id.localeCompare(right.id, "tr");
}

export function deriveDemandRequirements(
  targets: CumulativeDemandTarget[],
  scope?: PlanningScope,
): DemandRequirement[] {
  const normalizedScope = scope ? normalizePlanningScope(scope) : undefined;
  const targetIds = new Set<string>();
  const normalizedTargets = targets.map((target) => {
    if (!isPeriodId(target.periodId)) throw new Error(`Geçersiz talep dönemi: ${String(target.periodId)}`);
    const id = normalizedText(target.id, "Talep hedefi kimliği");
    if (targetIds.has(id)) throw new Error(`Tekrarlanan talep hedefi kimliği: ${id}`);
    targetIds.add(id);
    return {
      ...target,
      id,
      product: normalizedText(target.product, "Ürün"),
      cumulativeQuantity: nonNegativeQuantity(target.cumulativeQuantity, "Kümülatif sipariş adedi"),
      dueDate: normalizedDate(target.dueDate, "Termin tarihi"),
    };
  });

  const grouped = new Map<string, typeof normalizedTargets>();
  for (const target of normalizedTargets) {
    const items = grouped.get(target.product) ?? [];
    items.push(target);
    grouped.set(target.product, items);
  }

  const requirements: DemandRequirement[] = [];
  for (const [product, productTargets] of grouped) {
    let effectiveCumulativeQuantity = 0;
    for (const target of productTargets.sort((left, right) => compareDemandOrder(
      { periodId: left.periodId, dueDate: left.dueDate, id: left.id },
      { periodId: right.periodId, dueDate: right.dueDate, id: right.id },
    ))) {
      const previousEffective = effectiveCumulativeQuantity;
      effectiveCumulativeQuantity = Math.max(previousEffective, target.cumulativeQuantity);
      const requirement: DemandRequirement = {
        id: `demand:${target.id}`,
        targetId: target.id,
        product,
        periodId: target.periodId,
        dueDate: target.dueDate,
        rawCumulativeQuantity: target.cumulativeQuantity,
        effectiveCumulativeQuantity,
        quantity: effectiveCumulativeQuantity - previousEffective,
      };
      if (
        !normalizedScope
        || (
          comparePeriods(requirement.periodId, normalizedScope.startPeriod) >= 0
          && comparePeriods(requirement.periodId, normalizedScope.endPeriod) <= 0
        )
      ) {
        requirements.push(requirement);
      }
    }
  }

  return requirements.sort(compareDemandOrder);
}

export function allocateProductionOnce(
  requirements: DemandRequirement[],
  sources: ProductionSource[],
): DemandAllocationResult {
  const demandIds = new Set<string>();
  const normalizedDemands = requirements.map((requirement) => {
    if (demandIds.has(requirement.id)) throw new Error(`Tekrarlanan talep kimliği: ${requirement.id}`);
    demandIds.add(requirement.id);
    if (!isPeriodId(requirement.periodId)) throw new Error(`Geçersiz talep dönemi: ${String(requirement.periodId)}`);
    return {
      ...requirement,
      product: normalizedText(requirement.product, "Ürün"),
      quantity: nonNegativeQuantity(requirement.quantity, "Talep adedi"),
      dueDate: normalizedDate(requirement.dueDate, "Termin tarihi"),
    };
  }).sort(compareDemandOrder);

  const sourceIds = new Set<string>();
  const availableSources = sources.map((source, position) => {
    if (sourceIds.has(source.id)) throw new Error(`Tekrarlanan üretim kaynağı kimliği: ${source.id}`);
    sourceIds.add(source.id);
    const availableAt = normalizedDate(source.availableAt, "Üretim hazır tarihi");
    if (source.kind !== "opening-stock" && !availableAt) {
      throw new Error(`${source.kind} kaynağı için üretim hazır tarihi zorunludur.`);
    }
    return {
      ...source,
      product: normalizedText(source.product, "Ürün"),
      quantity: nonNegativeQuantity(source.quantity, "Üretim adedi"),
      availableAt,
      remainingQuantity: nonNegativeQuantity(source.quantity, "Üretim adedi"),
      position,
    };
  }).sort((left, right) => {
    const availabilityComparison = dateTime(left.availableAt) - dateTime(right.availableAt);
    return availabilityComparison || left.position - right.position;
  });

  const allocations: DemandAllocation[] = [];
  const demandResults = normalizedDemands.map((demand) => {
    let remainingDemand = demand.quantity;
    let onTimeQuantity = 0;
    let lateQuantity = 0;
    let undatedQuantity = 0;

    for (const source of availableSources) {
      if (remainingDemand <= 0) break;
      if (source.product !== demand.product || source.remainingQuantity <= 0) continue;
      const quantity = Math.min(remainingDemand, source.remainingQuantity);
      const timing = !demand.dueDate
        ? "undated"
        : isAvailableByDueDate(source.availableAt, demand.dueDate)
          ? "on-time"
          : "late";
      source.remainingQuantity -= quantity;
      remainingDemand -= quantity;
      if (timing === "on-time") onTimeQuantity += quantity;
      else if (timing === "late") lateQuantity += quantity;
      else undatedQuantity += quantity;
      allocations.push({ sourceId: source.id, demandId: demand.id, product: demand.product, quantity, timing });
    }

    return {
      ...demand,
      allocatedQuantity: demand.quantity - remainingDemand,
      onTimeQuantity,
      lateQuantity,
      undatedQuantity,
      shortageQuantity: remainingDemand,
    };
  });

  return {
    demands: demandResults,
    allocations,
    surplus: availableSources.map(({ position: _position, ...source }) => source),
  };
}

