import type {
  CustomerDemandDataset,
  PlannedBatch,
  ScenarioResult,
  WeeklyDemandScope,
} from "./planning";
import {
  planningMonthRangeForScope,
  weekScopeForPlanningMonthRange,
  type ConfirmedOverviewPreview,
} from "./weekly-demand";

export type DemandReimportComparison = {
  repeatImport: boolean;
  snapshotChanged: boolean;
  addedWeekCount: number;
  removedWeekCount: number;
  changedWeekCount: number;
  addedProductCount: number;
  removedProductCount: number;
  changedProductCount: number;
  requirementDelta: number;
  baselineRequirementDelta: number;
};

function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

function productChanged(
  before: ConfirmedOverviewPreview["products"][number],
  after: ConfirmedOverviewPreview["products"][number],
): boolean {
  if (
    before.priorDemand !== after.priorDemand
  ) return true;
  const beforeWeeks = new Map(before.weeklyDemands.map((week) => [week.weekId, week.quantity]));
  const afterWeeks = new Map(after.weeklyDemands.map((week) => [week.weekId, week.quantity]));
  return [...new Set([...beforeWeeks.keys(), ...afterWeeks.keys()])]
    .some((weekId) => (beforeWeeks.get(weekId) ?? 0) !== (afterWeeks.get(weekId) ?? 0));
}

export function compareCustomerDemandImport(
  current: CustomerDemandDataset | undefined,
  next: ConfirmedOverviewPreview,
): DemandReimportComparison {
  if (!current) {
    return {
      repeatImport: false,
      snapshotChanged: false,
      addedWeekCount: next.weeks.length,
      removedWeekCount: 0,
      changedWeekCount: 0,
      addedProductCount: next.products.length,
      removedProductCount: 0,
      changedProductCount: 0,
      requirementDelta: next.summary.totalQuantity,
      baselineRequirementDelta: next.summary.priorDemand,
    };
  }

  const currentWeeks = new Map(current.weeks.map((week) => [week.id, week]));
  const nextWeeks = new Map(next.weeks.map((week) => [week.id, week]));
  const currentProducts = new Map(current.products.map((product) => [product.product.toUpperCase(), product]));
  const nextProducts = new Map(next.products.map((product) => [product.product.toUpperCase(), product]));
  const allWeekIds = new Set([...currentWeeks.keys(), ...nextWeeks.keys()]);
  const changedWeekCount = [...allWeekIds].filter((weekId) => {
    if (!currentWeeks.has(weekId) || !nextWeeks.has(weekId)) return false;
    return [...new Set([...currentProducts.keys(), ...nextProducts.keys()])].some((productCode) => {
      const before = currentProducts.get(productCode)?.weeklyDemands.find((week) => week.weekId === weekId)?.quantity ?? 0;
      const after = nextProducts.get(productCode)?.weeklyDemands.find((week) => week.weekId === weekId)?.quantity ?? 0;
      return before !== after;
    });
  }).length;
  const changedProductCount = [...currentProducts.keys()].filter((productCode) => {
    const before = currentProducts.get(productCode);
    const after = nextProducts.get(productCode);
    return Boolean(before && after && productChanged(before, after));
  }).length;

  return {
    repeatImport: true,
    snapshotChanged: current.snapshotDate !== next.snapshotDate,
    addedWeekCount: [...nextWeeks.keys()].filter((weekId) => !currentWeeks.has(weekId)).length,
    removedWeekCount: [...currentWeeks.keys()].filter((weekId) => !nextWeeks.has(weekId)).length,
    changedWeekCount,
    addedProductCount: [...nextProducts.keys()].filter((productCode) => !currentProducts.has(productCode)).length,
    removedProductCount: [...currentProducts.keys()].filter((productCode) => !nextProducts.has(productCode)).length,
    changedProductCount,
    requirementDelta: next.summary.totalQuantity - sum(current.products.map((product) => product.totalDemand)),
    baselineRequirementDelta: next.summary.priorDemand - sum(current.products.map((product) => product.priorDemand)),
  };
}

export function protectedBatchesForDemandReimport(result: ScenarioResult): PlannedBatch[] {
  return result.batches
    .filter((batch) => batch.status === "planned" && (batch.locked || batch.manuallyPlaced || Boolean(batch.workOrder?.trim())))
    .map((batch) => ({ ...batch, locked: true }));
}

export function scopeForDemandReimport(
  current: CustomerDemandDataset | undefined,
  next: ConfirmedOverviewPreview,
): WeeklyDemandScope | undefined {
  if (!current) return undefined;
  const currentRange = planningMonthRangeForScope(current.weeks, current.activeScope);
  try {
    return weekScopeForPlanningMonthRange(next.weeks, currentRange);
  } catch {
    const activeIds = new Set(
      current.weeks
        .slice(
          current.weeks.findIndex((week) => week.id === current.activeScope.startWeekId),
          current.weeks.findIndex((week) => week.id === current.activeScope.endWeekId) + 1,
        )
        .map((week) => week.id),
    );
    const shared = next.weeks.filter((week) => activeIds.has(week.id));
    return shared.length ? { startWeekId: shared[0].id, endWeekId: shared.at(-1)!.id } : undefined;
  }
}

