import { addMachineCapacityHours, scenarioResultFromBatches, type PlanningSeed, type PlannedBatch, type ScenarioResult } from './planning';
import { buildDownstreamProcessPlan } from './process-planning';
const serial=(s:string)=>(Date.parse(`${s}T00:00:00Z`)-Date.UTC(1899,11,30))/86400000;
/** Move new proposals toward their deadlines using the shared route scheduler.
 * Fixed work is never a search variable. Each accepted step preserves every
 * previously achievable deadline and does not make an already late job later.
 */
export function planFilterBackward(seed:PlanningSeed, baseline:ScenarioResult, fixed:PlannedBatch[]):ScenarioResult {
  if(seed.productionArea!=='cubuk-filtre'||!seed.monthlyCustomerDemand) return baseline;
  const fixedIds=new Set(fixed.map(b=>b.id));
  let batches=baseline.batches.map(b=>({...b}));
  const dueFor=(id:string,product:string)=>{
    const b=batches.find(x=>x.id===id);
    const date=b?.demandDueDate || seed.orders.filter(o=>o.product===product&&o.quantity>0).map(o=>o.dueDate).sort()[0];
    return date ? serial(date)+1-1/86400 : 0;
  };
  let route=buildDownstreamProcessPlan(seed,{batches});
  const candidates=batches.filter(b=>b.status==='planned'&&!fixedIds.has(b.id)&&!b.locked&&!b.manuallyPlaced&&!b.routeCommitted)
    .sort((a,b)=>b.start-a.start||b.sequence-a.sequence);
  for(const batch of candidates) {
    const job=route.jobs.find(j=>j.batchId===batch.id);
    const due=dueFor(batch.id,batch.product);
    if(!job||!due||!job.deliveryReadyAt||job.deliveryReadyAt>due) continue;
    const machine=seed.machines.find(m=>m.id===batch.machineId)!;
    const next=batches.filter(b=>b.status==='planned'&&b.machineId===batch.machineId&&b.planColumn>batch.planColumn).sort((a,b)=>a.planColumn-b.planColumn)[0];
    let low=batch.start, high=Math.min(due, next?.start ?? Math.floor(machine.planEnd)+1);
    if(high-low<1/1440) continue;
    let chosen:PlannedBatch|undefined;
    let chosenRoute=route;
    const originalRoute=route;
    for(let iteration=0;iteration<14&&high-low>1/1440;iteration++) {
      const requested=(low+high)/2;
      const timeline=addMachineCapacityHours(seed,machine,requested,(batch.setupHours??0)+(batch.runHours??0));
      if(timeline.end>Math.min(next?.start??Infinity,Math.floor(machine.planEnd)+1)-1e-8){high=requested;continue;}
      const proposed={...batch,start:timeline.start,end:timeline.end,backwardNotBefore:timeline.start};
      const trial=batches.map(b=>b.id===batch.id?proposed:b);
      const trialRoute=buildDownstreamProcessPlan(seed,{batches:trial});
      const feasible=originalRoute.jobs.every(before=>{
        const after=trialRoute.jobs.find(j=>j.batchId===before.batchId);
        if(!before.deliveryReadyAt) return true;
        if(!after?.deliveryReadyAt) return false;
        // Existing work may not be delayed by a new proposal.
        if(before.source!=='turning-plan'||fixedIds.has(before.batchId)) return after.deliveryReadyAt<=before.deliveryReadyAt+1e-8;
        const deadline=dueFor(before.batchId,before.product);
        return after.deliveryReadyAt<=Math.max(before.deliveryReadyAt,deadline)+1e-8;
      });
      if(feasible){low=requested;chosen=proposed;chosenRoute=trialRoute;}else high=requested;
    }
    if(chosen){batches=batches.map(b=>b.id===batch.id?{...chosen!,explanation:`Ambar / ambalaj hazırlık tarihinden geriye planlandı. ${b.explanation}`}:b);route=chosenRoute;}
  }
  return {...scenarioResultFromBatches(seed,batches),createdAt:baseline.createdAt};
}

