import { type FilterStockReconciliation } from "./filter-stock-reconciliation";
import { machineDayCapacity, type Order, type PlanningSeed, type ProductionHistoryEntry } from './planning';
import { assertFilterMonthlyPlan, type FilterMonthlyPlan } from './daily-demand';
import { createOrderImportMetadata } from './delivery-deduction';

export type FilterStockRow = { product: string; delivered: number | null; visual: number | null; heat: number | null; milling: number | null; grinding: number | null };
export type FilterMonthlyPreview = Omit<FilterMonthlyPlan, 'rows'> & { format: 'filter-monthly'; fileName: string;
  rows: Array<FilterMonthlyPlan['rows'][number] & { rule: string; inputs: Array<{ label: string; quantities: number[]; sourceRow: number }> }>;
  openingStock?: { cutoffDate: string; rows: FilterStockRow[] };
  sourceKind?: 'upload' | 'manual';
  originalRows?: FilterMonthlyPreview['rows'];
};
export type FilterDeliveryBaseline = {year:number;snapshotDate:string;importedAt:string;shipmentsThrough:string;handovers:Array<{product:string;month:string;quantity:number}>};
export type FilterMonthlyDataset = FilterMonthlyPreview & { deliveryBaseline?:FilterDeliveryBaseline; stockReconciliation?: FilterStockReconciliation; startDate: string; endDate: string; snapshotDate: string; importedAt: string;
  handovers: Array<{ product: string; month: string; quantity: number }>;
  exceptions: Array<{ product: string; date: string; quantity: number }>;
};
export const FILTER_315 = 'F.00V.P01.315';
/** Approved upstream forecast only. Actual accepted quantities remain exact. */
const FILTER_EXPECTED_GOOD_PERCENT: Readonly<Record<string, number>> = { 'F.00V.P01.309': 96, [FILTER_315]: 96 };
const integer = (n: number) => Number.isSafeInteger(n) && n >= 0;
const dateValid = (s: string) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && Number.isFinite(Date.parse(s)) && new Date(s).toISOString().slice(0,10) === s;
const serial = (s: string) => (Date.parse(`${s}T00:00:00Z`) - Date.UTC(1899,11,30)) / 86400000;
const iso = (n: number) => new Date(Date.UTC(1899,11,30) + n * 86400000).toISOString().slice(0,10);
export function filterGoodPieces(product: string, physical: number): number {
  if (!integer(physical)) throw new Error('Fiziksel adet geçersiz.');
  const percent = FILTER_EXPECTED_GOOD_PERCENT[product];
  return percent === undefined ? physical : Number(BigInt(physical) * BigInt(percent) / BigInt(100));
}
export function filterRequiredInput(product: string, good: number): number {
  if (!integer(good)) throw new Error('Sağlam parça ihtiyacı geçersiz.');
  const percent = FILTER_EXPECTED_GOOD_PERCENT[product];
  const result = percent === undefined ? good : Number((BigInt(good) * BigInt(100) + BigInt(percent - 1)) / BigInt(percent));
  if (!integer(result)) throw new Error('Gerekli giriş adedi güvenli sınırı aşıyor.');
  return result;
}

export const FILTER_MONTHLY_RULES = [
  { product: 'F.00V.C15.100', label: 'C100-DRS', inputs: ['501-RBTR','003-RBCD'], percent: 103, unit: 15000, output: 15000 },
  { product: 'F.00V.C15.002', label: '002-DRS', inputs: ['001-RBCD','001-NaP','001-CtP'], percent: 104, unit: 1000, output: 1000 },
  { product: '2.433.084.081', label: '081-DRS', inputs: ['481-HoP','481-CtP/NaP','424-HoP/CtP'], percent: 104, unit: 1000, output: 1100 },
] as const;
export function recalculateFilterMonthlyRows(rows: FilterMonthlyPreview['rows']): FilterMonthlyPreview['rows'] {
  return rows.map(row => {
    const rule = FILTER_MONTHLY_RULES.find(rule => rule.product === row.product);
    if (row.inputs.some(input => input.quantities.length !== 12 || input.quantities.some(n => !integer(n)))) throw new Error('Kaynak adet tam sayı ve sıfır veya daha büyük olmalıdır.');
    const quantities = Array.from({length:12}, (_, month) => {
      if (!rule) return row.inputs[0].quantities[month];
      const total = row.inputs.reduce((sum,input) => sum + BigInt(input.quantities[month]), BigInt(0));
      return Number((total * BigInt(rule.percent) + BigInt(100*rule.unit-1)) / BigInt(100*rule.unit) * BigInt(rule.output));
    });
    if (quantities.some(n => !integer(n))) throw new Error('Hesaplanan adet güvenli sınırı aşıyor.');
    return {...row, quantities};
  });
}
/** Keep operator corrections visible during the next source review. */
export function mergeFilterMonthlySourceCorrections(incoming: FilterMonthlyPreview, previous?: FilterMonthlyDataset): FilterMonthlyPreview {
  const result=structuredClone(incoming);
  result.originalRows=structuredClone(incoming.originalRows ?? incoming.rows);
  if (incoming.sourceKind==='manual' || !previous || previous.year!==incoming.year) return result;
  for (const row of result.rows) {
    const prior=previous.rows.find(item=>item.product===row.product);
    const original=previous.originalRows?.find(item=>item.product===row.product);
    if (!prior || !original) continue;
    const labelKey=(label:string)=>label.replace(/\s+/g,'').toLocaleUpperCase('en-US').replace(/İ/g,'I');
    row.inputs.forEach(item=>{
      const edited=prior.inputs.find(input=>labelKey(input.label)===labelKey(item.label)), before=original.inputs.find(input=>labelKey(input.label)===labelKey(item.label));
      if(edited && before) item.quantities=item.quantities.map((n,m)=>edited.quantities[m]!==before.quantities[m]?edited.quantities[m]:n);
    });
  }
  result.rows=recalculateFilterMonthlyRows(result.rows);
  return result;
}

export function createBlankFilterMonthlyPreview(year: number): FilterMonthlyPreview {
  if (!Number.isInteger(year) || year < 2000 || year > 2100) throw new Error('Sipariş yılı geçersiz.');
  const direct = [['F.00V.P01.309','309-RBTR'],['F.00V.P01.315','315-BAP'],['F.00Z.S00.002','002-CtP'],['2.433.084.245','245-CtP']];
  const rows: FilterMonthlyPreview['rows'] = direct.map(([product,label],index) => ({product,label,kind:'external',sourceRow:0,quantities:Array(12).fill(0),rule:'direct',inputs:[{label,sourceRow:0,quantities:Array(12).fill(0)}]}));
  FILTER_MONTHLY_RULES.forEach((rule,index) => rows.push({product:rule.product,label:rule.label,kind:'internal',sourceRow:0,quantities:Array(12).fill(0),rule:`ceil(sum × ${rule.percent}/100 ÷ ${rule.unit}) × ${rule.output}`,inputs:rule.inputs.map((label,i)=>({label,sourceRow:0,quantities:Array(12).fill(0)}))}));
  return {format:'filter-monthly',fileName:'Manuel aylık sipariş',sheetName:'SİPARİŞ ŞABLONU',sourceKind:'manual',year,workingDays:Array(12).fill(0),rows};
}

export function filterDeliveryBaselineFor(seed:PlanningSeed,year:number):FilterDeliveryBaseline|undefined {
  return seed.filterMonthlyDeliveryBaselines?.find(item=>item.year===year) ?? (seed.monthlyCustomerDemand?.year===year ? seed.monthlyCustomerDemand.deliveryBaseline : undefined) ?? (seed.filterInitialStockSetup?.deliveryBaseline?.year===year ? seed.filterInitialStockSetup.deliveryBaseline : undefined);
}

/** Promote saved evidence before an order clear or a legacy scenario can remove its nested copy. */
export function promoteFilterMonthlyEvidence(seed:PlanningSeed):void {
  if(seed.productionArea!=='cubuk-filtre') return;
  const monthly=seed.monthlyCustomerDemand;
  if(!seed.filterInitialStockSetup && monthly?.stockReconciliation) seed.filterInitialStockSetup=structuredClone({...monthly.stockReconciliation,sourceRows:monthly.stockReconciliation.sourceRows??monthly.openingStock?.rows});
  const baseline=monthly?.deliveryBaseline ?? (monthly && seed.orderImport?.shipmentsThrough ? {year:monthly.year,snapshotDate:monthly.snapshotDate,importedAt:monthly.importedAt,shipmentsThrough:seed.orderImport.shipmentsThrough,handovers:monthly.handovers} : seed.filterInitialStockSetup?.deliveryBaseline);
  if(baseline && !seed.filterMonthlyDeliveryBaselines?.some(item=>item.year===baseline.year)) seed.filterMonthlyDeliveryBaselines=[...(seed.filterMonthlyDeliveryBaselines??[]),structuredClone(baseline)];
}

export function buildFilterMonthlyOrders(seed: PlanningSeed, data: FilterMonthlyDataset) {
  if (seed.productionArea !== 'cubuk-filtre' || data.format !== 'filter-monthly') throw new Error('Aylık dosya yalnız Çubuk Filtre alanına uygulanabilir.');
  assertFilterMonthlyPlan(data, new Set(seed.products.map(p => p.product)));
  if (![data.startDate,data.endDate,data.snapshotDate].every(dateValid) || data.startDate > data.endDate || data.startDate.slice(0,4) !== String(data.year) || data.endDate.slice(0,4) !== String(data.year)) throw new Error('Aylık sipariş tarihlerini ve yılı kontrol edin.');
  if (!Array.isArray(data.handovers) || data.handovers.length > 720 || !Array.isArray(data.exceptions) || data.exceptions.length > 1000) throw new Error('Teslimat veya tarihli ihtiyaç listesi geçersiz.');
  const products = new Set(data.rows.map(r => r.product));
  if (products.size !== data.rows.length) throw new Error('Aylık ürün tekrarlı.');
  const handovers = new Map<string,number>();
  for (const h of data.handovers) {
    const key = `${h.product}:${h.month}`;
    if (!products.has(h.product) || !/^\d{4}-(0[1-9]|1[0-2])$/.test(h.month) || h.month.slice(0,4) !== String(data.year) || !integer(h.quantity) || handovers.has(key) || h.quantity > 0 && h.month > data.snapshotDate.slice(0,7)) throw new Error('Teslim edilen adet, ay veya ürün geçersiz / tekrarlı.');
    handovers.set(key,h.quantity);
  }
  if (data.openingStock) {
    if (!dateValid(data.openingStock.cutoffDate) || !Array.isArray(data.openingStock.rows) || data.openingStock.rows.length > 100) throw new Error('Stok kaynağı geçersiz.');
    const seen = new Set<string>();
    for (const row of data.openingStock.rows) {
      if (seen.has(row.product) || !seed.products.some(p=>p.product===row.product) || [row.delivered,row.visual,row.heat,row.milling,row.grinding].some(n=>n!==null&&!integer(n))) throw new Error('Stok kaynağı ürün / adet geçersiz.');
      seen.add(row.product);
    }
  }
  const exceptionKeys = new Set<string>();
  for (const e of data.exceptions) {
    const key = `${e.product}:${e.date}`;
    if (!products.has(e.product) || !dateValid(e.date) || e.date < data.startDate || e.date > data.endDate || !integer(e.quantity) || exceptionKeys.has(key)) throw new Error('Tarihli ihtiyaç geçersiz / tekrarlı.');
    exceptionKeys.add(key);
  }
  const rows: Array<{product:string;month:string;ordered:number;delivered:number;remaining:number}> = [];
  const dailyRows: Array<{product:string;date:string;quantity:number}> = [];
  for (const row of data.rows) for (let m = 0; m < 12; m++) {
    const month = `${data.year}-${String(m+1).padStart(2,'0')}`;
    if (month < data.startDate.slice(0,7) || month > data.endDate.slice(0,7)) continue;
    const ordered = row.quantities[m], key = `${row.product}:${month}`;
    if (ordered > 0 && month <= data.snapshotDate.slice(0,7) && !handovers.has(key)) throw new Error(`${row.label} ${month}: tamamlanan teslimatı girin; yoksa 0 ile doğrulayın.`);
    const delivered = handovers.get(key) ?? 0;
    const remaining = Math.max(0, ordered - delivered);
    rows.push({product:row.product,month,ordered,delivered,remaining});
    const exceptions = data.exceptions.filter(e => e.product === row.product && e.date.startsWith(month));
    const assigned = exceptions.reduce((s,e) => s+e.quantity,0);
    if (!integer(assigned) || assigned > remaining) throw new Error(`${row.label} ${month}: tarihli adet aylık kalan ihtiyacı aşıyor.`);
    dailyRows.push(...exceptions.filter(e=>e.quantity>0));
    const days: Array<{date:string;weight:number}> = [];
    const end = Math.min(serial(data.endDate), serial(new Date(Date.UTC(data.year,m+1,0)).toISOString().slice(0,10)));
    for (let day=Math.max(serial(`${month}-01`),serial(data.startDate)); day<=end;day++) {
      const date=iso(day);
      // Explicit dated allocations own their day. Other demand uses the remaining open dates.
      if (exceptions.some(e=>e.date===date)) continue;
      const weight=machineDayCapacity(seed,{id:'CF-DEMAND',shiftFactor:2},day).shifts;
      if (weight>0) days.push({date,weight});
    }
    const residual=remaining-assigned, total=days.reduce((s,d)=>s+d.weight,0);
    if (residual>0 && total===0) throw new Error(`${row.label} ${month}: kalan ihtiyacı dağıtacak çalışma günü yok.`);
    let cumulativeWeight=0, previous=0;
    for (const day of days) {
      cumulativeWeight+=day.weight;
      const cumulative=Number(BigInt(residual)*BigInt(cumulativeWeight)/BigInt(total));
      const quantity=cumulative-previous; previous=cumulative;
      if (quantity>0) dailyRows.push({product:row.product,date:day.date,quantity});
    }
  }
  dailyRows.sort((a,b)=>a.date.localeCompare(b.date)||a.product.localeCompare(b.product));
  const orders:Order[]=[];
  for (const product of products) {
    const days=dailyRows.filter(r=>r.product===product); if(!days.length) continue;
    let quantity=0;
    const milestones=days.map(d=>({id:`monthly-${product}-${d.date}`,date:d.date,quantity:quantity+=d.quantity}));
    if (!integer(quantity)) throw new Error('Yıllık ihtiyaç güvenli adet sınırını aşıyor.');
    orders.push({id:`monthly-${product}`,product,sourceRow:data.rows.find(r=>r.product===product)!.sourceRow,quantity,
      savedPlanned:0,savedDifference:0,savedMachines:[],dueDate:milestones.at(-1)!.date,allowPartial:true,
      partialDeliveryQuantity:0,partialDeliveryDate:'',deliveryMilestones:milestones});
  }
  return {orders,rows,dailyRows};
}

export function applyFilterMonthlyImport(seed: PlanningSeed, data: FilterMonthlyDataset): void {
  const savedHandovers=filterDeliveryBaselineFor(seed,data.year)?.handovers ?? (seed.monthlyCustomerDemand?.year===data.year ? seed.monthlyCustomerDemand.handovers : []);
  const mergedHandovers=new Map(savedHandovers.filter(row=>data.rows.some(item=>item.product===row.product)).map(row=>[`${row.product}:${row.month}`,row]));
  if(new Set(data.handovers.map(row=>`${row.product}:${row.month}`)).size!==data.handovers.length) throw new Error('Teslimat ürün / ay kaydı tekrarlı.');
  for(const row of data.handovers) mergedHandovers.set(`${row.product}:${row.month}`,row);
  // The panel edits a date scope. Months outside that scope retain their reviewed delivered amounts.
  const handovers=[...mergedHandovers.values()];
  const effective={...data,handovers};
  const state=buildFilterMonthlyOrders(seed,effective);
  data=effective;
  const imported=Date.parse(data.importedAt);
  if (!Number.isFinite(imported) || data.snapshotDate > new Date(imported+3*3600000).toISOString().slice(0,10)) throw new Error('Yükleme / dosya kesim tarihi geçersiz.');
  const canonical=(d:FilterMonthlyDataset)=>JSON.stringify({year:d.year,snapshotDate:d.snapshotDate,
    rows:d.rows.map(r=>[r.product,r.quantities]).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))),
    handovers:[...d.handovers].sort((a,b)=>`${a.product}:${a.month}`.localeCompare(`${b.product}:${b.month}`))});
  const previous=seed.monthlyCustomerDemand;
  const savedBaseline=filterDeliveryBaselineFor(seed,data.year);
  if(savedBaseline && data.snapshotDate!==savedBaseline.snapshotDate) throw new Error('Kayıtlı teslimat kesim tarihi korunur. Tamamlanan teslimat adedini mevcut kesimde düzeltin.');
  const importedAt=previous && canonical(previous)===canonical(data) ? previous.importedAt : data.importedAt;
  const metadata=previous?.year===data.year && seed.orderImport ? {...seed.orderImport,sourceFile:data.fileName,importedAt} : createOrderImportMetadata(data.fileName,importedAt);
  metadata.shipmentsThrough=savedBaseline?.shipmentsThrough ?? (previous?.year===data.year && seed.orderImport?.shipmentsThrough ? seed.orderImport.shipmentsThrough : new Date(Math.min(Date.parse(`${data.snapshotDate}T23:59:59.999+03:00`),Date.parse(importedAt))).toISOString());
  const deliveryBaseline=savedBaseline ? {...savedBaseline,handovers:structuredClone(data.handovers)} : {year:data.year,snapshotDate:data.snapshotDate,importedAt,shipmentsThrough:metadata.shipmentsThrough,handovers:structuredClone(data.handovers)};
  // All validation precedes mutation. Stock rows are source evidence only until reconciled.
  const stockReconciliation=seed.filterInitialStockSetup ?? previous?.stockReconciliation;
  const openingStock=stockReconciliation ? previous?.openingStock ?? data.openingStock : data.openingStock;
  promoteFilterMonthlyEvidence(seed);
  seed.filterMonthlyDeliveryBaselines=[...(seed.filterMonthlyDeliveryBaselines??[]).filter(item=>item.year!==data.year),structuredClone(deliveryBaseline)];
  seed.monthlyCustomerDemand=structuredClone({...data,importedAt,openingStock,stockReconciliation,deliveryBaseline,originalRows:data.originalRows ?? data.rows});
  seed.filterMonthlyPlan=structuredClone({...data,sourceFile:data.fileName,importedAt});
  seed.orders=state.orders;
  seed.orderCatalog=[...new Set(data.rows.map(r=>r.product))];seed.orderCatalogName=data.fileName;
  seed.orderImport=metadata;seed.orderImportGrossOrders=structuredClone(state.orders);
  delete seed.customerDemand;delete seed.dailyCustomerDemand;
  seed.customerOrderOverrides=[]; seed.planNeedsRecalculation=true;
}

/** Only the approved monthly workflow forecasts good-piece coverage. Physical records never shrink. */
export function filterSupplyGoodPieces(seed: Pick<PlanningSeed,'productionArea'|'monthlyCustomerDemand'>, product: string, physical: number, completed = false): number {
  return seed.productionArea === 'cubuk-filtre' && seed.monthlyCustomerDemand && !completed ? filterGoodPieces(product,physical) : physical;
}
export function filterInputForShortage(seed: Pick<PlanningSeed,'productionArea'|'monthlyCustomerDemand'>, product: string, good: number): number {
  return seed.productionArea === 'cubuk-filtre' && seed.monthlyCustomerDemand ? filterRequiredInput(product,good) : good;
}

/** Split lots can contain both accepted final goods and upstream physical pieces. */
export function filterHistoryGoodPieces(seed:PlanningSeed,entry:ProductionHistoryEntry):number {
  if(seed.productionArea!=="cubuk-filtre"||!seed.monthlyCustomerDemand) return entry.completedQuantity;
  const lots=(seed.wipLots??[]).filter(l=>l.sourceHistoryEntryId===entry.id&&l.availableQuantity>0&&!['delivered','scrapped'].includes(l.stage));
  const linked=lots.reduce((s,l)=>s+l.availableQuantity,0);
  if(linked>entry.completedQuantity) throw new Error(`${entry.product}: şarj ve arşiv miktarları uzlaşmıyor.`);
  return lots.reduce((s,l)=>s+filterSupplyGoodPieces(seed,l.product,l.availableQuantity,l.stage==='delivery-ready'),0)+filterSupplyGoodPieces(seed,entry.product,entry.completedQuantity-linked);
}

