import type { CSSProperties } from "react";

/** Product identity alone determines its color across views and reloads. */
export function filterProductColors(product: string) {
  const identity = product.trim().toUpperCase();
  let hash = 2166136261;
  for (const character of identity) hash = Math.imul(hash ^ character.charCodeAt(0), 16777619) >>> 0;
  const hue = hash % 360;
  return { background: `hsl(${hue} 82% 93%)`, border: `hsl(${hue} 48% 50%)`, ink: `hsl(${hue} 65% 24%)` };
}

export function filterProductStyle(product: string): CSSProperties {
  const colors = filterProductColors(product);
  return {
    "--batch-height": "38px", "--batch-bg": colors.background,
    "--batch-border": colors.border, "--batch-ink": colors.ink,
    backgroundColor: colors.background, borderColor: colors.border, color: colors.ink,
  } as CSSProperties;
}

