import { machineDayCapacity, type PlanningSeed } from './planning';
export const FILTER_QUALITY_RESOURCE = 'CF-KALITE';
/** One quality working day, at the same factory time on the next open day. */
export function filterQualityReadyAt(seed: Pick<PlanningSeed,'holidays'|'calendarEvents'|'filterQualityShifts'>, completed: number): number {
  if (!Number.isFinite(completed) || completed <= 0) throw new Error('Kalite bekleme başlangıcı geçersiz.');
  const fraction=completed-Math.floor(completed);
  const resource={id:FILTER_QUALITY_RESOURCE,shiftFactor:seed.filterQualityShifts ?? 1};
  for(let day=Math.floor(completed)+1;day<=Math.floor(completed)+3660;day++) {
    if(machineDayCapacity(seed as PlanningSeed,resource,day).shifts>0) return day+fraction;
  }
  throw new Error('Kalite bekleme takviminde açık çalışma günü bulunamadı.');
}

