import { semiFinishedProduction, type PlanningSeed } from './planning';
import { initialProcessStockSettings, stockGroups } from './process-stock';
import { buildFilterMonthlyOrders, filterGoodPieces, type FilterStockRow } from './filter-monthly-demand';

export type FilterReviewedStock = { product:string; delivered?:number; visual:number; heat:number; milling:number; grinding:number };
export type FilterStockReconciliation = { cutoffDate:string; sourceKey:string; recordedAt:string; rows:FilterReviewedStock[]; sourceRows?:FilterStockRow[]; deliveryBaseline?:import('./filter-monthly-demand').FilterDeliveryBaseline };
export function filterStockSourceKey(source:{cutoffDate:string;rows:FilterStockRow[]}):string {
  return JSON.stringify([source.cutoffDate,source.rows.map(r=>[r.product,r.visual,r.heat,r.milling,r.grinding]).sort((a,b)=>String(a[0]).localeCompare(String(b[0])))]);
}
/** A physical count includes registered charges. Only the unrepresented balance becomes grouped stock. */
export function previewFilterStockReconciliation(seed:PlanningSeed, rows:FilterReviewedStock[]) {
  const source=seed.monthlyCustomerDemand?.openingStock;
  if(seed.productionArea!=='cubuk-filtre'||!source) throw new Error('Aylık stok kaynağı bulunamadı.');
  if(!Array.isArray(rows)||rows.length!==source.rows.length) throw new Error('Her kaynak ürün için sayımı doğrulayın.');
  const seen=new Set<string>();
  for(const row of rows) {
    const original=source.rows.find(r=>r.product===row.product);
    if(!original||seen.has(row.product)) throw new Error('Sayım ürünü eksik veya tekrarlı.');
    seen.add(row.product);
    for(const key of ['visual','heat','milling','grinding'] as const) {
      if(!Number.isSafeInteger(row[key])||row[key]<0) throw new Error(`${row.product}: boş sayımı doğrulayın; yoksa 0 girin.`);
    }
  }
  const activeLots=(seed.wipLots??[]).filter(l=>seen.has(l.product)&&l.availableQuantity>0&&!['delivered','scrapped'].includes(l.stage));
  const histories=semiFinishedProduction(seed).filter(h=>seen.has(h.product)&&h.completedQuantity>0);
  for(const history of histories) {
    const linked=activeLots.filter(l=>l.sourceHistoryEntryId===history.id).reduce((sum,l)=>sum+l.availableQuantity,0);
    if(linked!==history.completedQuantity) throw new Error(`${history.product}: arşiv ve şarj miktarlarını aynı kesimde uzlaştırın.`);
  }
  if(activeLots.some(l=>!histories.some(h=>h.id===l.sourceHistoryEntryId))) throw new Error('Arşiv bağlantısı olmayan şarjları uzlaştırın.');
  if((seed.processCurrentJobs??[]).some(j=>seen.has(j.product)&&j.remainingQuantity>0&&!activeLots.some(l=>l.id===j.wipLotId))) throw new Error('Çalışan prosesin şarj bağlantısını uzlaştırın.');
  const groups=stockGroups('cubuk-filtre');
  const details=rows.flatMap(row=>[
    {product:row.product,groupId:'visual-front',count:row.visual+row.heat,label:'GKM önü + Isıl işlem'},
    {product:row.product,groupId:'mill-front',count:row.milling,label:'Freze Önü'},
    {product:row.product,groupId:'form-front',count:row.grinding,label:'Taşlama Önü'},
  ].map(record=>{
    if(!Number.isSafeInteger(record.count)) throw new Error('Sayım toplamı güvenli sınırı aşıyor.');
    const lots=(seed.wipLots??[]).filter(l=>l.product===row.product&&l.availableQuantity>0&&!['delivered','scrapped','delivery-ready'].includes(l.stage));
    if(lots.some(l=>['on-hold','unclassified'].includes(l.stage)||!l.nextProcess||!groups.some(g=>g.nextProcesses.includes(l.nextProcess!)))) throw new Error(`${row.product}: sayımı uygulamadan önce blokeli / konumu belirsiz şarjları inceleyin.`);
    const matched=lots.filter(l=>groups.find(g=>g.id===record.groupId)!.nextProcesses.includes(l.nextProcess!));
    const registered=matched.reduce((s,l)=>s+l.availableQuantity,0);
    if(registered>record.count) throw new Error(`${row.product} ${record.label}: kayıtlı şarj ${registered}, sayım ${record.count}. Kesim tarihini ve şarjları uzlaştırın.`);
    const previous=(seed.processStockSettings?.opening??[]).filter(r=>r.product===row.product&&r.groupId===record.groupId).reduce((s,r)=>s+r.quantity,0);
    const remainder=record.count-registered;
    return {...record,registered,previous,remainder,expectedGood:filterGoodPieces(row.product,record.count),lotIds:matched.map(l=>l.id)};
  }));
  const preserved=(seed.processStockSettings?.opening??[]).filter(r=>!seen.has(r.product)||r.groupId==='warehouse');
  if(preserved.some(r=>r.quantity>0)&&seed.processStockSettings?.openingDate!==source.cutoffDate) throw new Error('Diğer ek stokların sayım tarihi farklı. Aynı kesim tarihinde uzlaştırın.');
  return {cutoffDate:source.cutoffDate,details,preserved};
}
export function applyFilterStockReconciliation(seed:PlanningSeed,rows:FilterReviewedStock[],confirmed:boolean,recordedAt=new Date().toISOString()):void {
  if(!confirmed) throw new Error('Sayım tarihini ve çalışan şarjların sayım içinde olduğunu doğrulayın.');
  const source=seed.monthlyCustomerDemand?.openingStock;
  if(!source) throw new Error('Stok kaynağı bulunamadı.');
  const sourceKey=filterStockSourceKey(source);
  if(seed.filterInitialStockSetup || seed.monthlyCustomerDemand!.stockReconciliation) return;
  if(!Number.isFinite(Date.parse(recordedAt))) throw new Error('Sayım kayıt tarihi geçersiz.');
  const preview=previewFilterStockReconciliation(seed,rows);
  const data=seed.monthlyCustomerDemand!;
  const handovers=structuredClone(data.handovers);
  for(const row of rows) if(row.delivered !== undefined) {
    if(!Number.isSafeInteger(row.delivered)||row.delivered<0) throw new Error('Tamamlanan teslimat adedi geçersiz.');
    if(!data.rows.some(item=>item.product===row.product)) continue;
    const month=source.cutoffDate.slice(0,7), existing=handovers.find(item=>item.product===row.product&&item.month===month);
    if(existing) existing.quantity=row.delivered; else handovers.push({product:row.product,month,quantity:row.delivered});
  }
  const demand=buildFilterMonthlyOrders(seed,{...data,handovers});
  const settings=structuredClone(seed.processStockSettings??initialProcessStockSettings('cubuk-filtre'));
  settings.openingDate=preview.cutoffDate;
  settings.opening=[...preview.preserved,...preview.details.filter(d=>d.remainder>0).map(d=>({product:d.product,groupId:d.groupId,quantity:d.remainder}))];
  seed.processStockSettings=settings;
  seed.monthlyCustomerDemand!.handovers=handovers;
  if(data.deliveryBaseline) data.deliveryBaseline.handovers=structuredClone(handovers);
  const baseline=seed.filterMonthlyDeliveryBaselines?.find(item=>item.year===data.year);
  if(baseline) baseline.handovers=structuredClone(handovers);
  seed.orders=demand.orders;
  seed.orderImportGrossOrders=structuredClone(demand.orders);
  seed.monthlyCustomerDemand!.stockReconciliation={cutoffDate:source.cutoffDate,sourceKey,recordedAt,rows:structuredClone(rows),sourceRows:structuredClone(source.rows),deliveryBaseline:structuredClone(data.deliveryBaseline)};
  seed.filterInitialStockSetup=structuredClone(seed.monthlyCustomerDemand!.stockReconciliation);
  seed.planNeedsRecalculation=true;
}

