import { excelSerialToDate } from "./planning";

export type GanttDay = {
  serial: number;
  dayOfMonth: number;
  isSunday: boolean;
  monthKey: string;
  fullLabel: string;
};

export type GanttMonth = {
  key: string;
  label: string;
  fullLabel: string;
  startIndex: number;
  dayCount: number;
};

export type GanttWeek = {
  key: string;
  label: string;
  fullLabel: string;
  startIndex: number;
  dayCount: number;
  weekStart: string;
  weekEnd: string;
};

function isoDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}

function isoWeekParts(date: Date): { year: number; week: number; weekStart: Date; weekEnd: Date } {
  const day = date.getUTCDay() || 7;
  const weekStart = new Date(date);
  weekStart.setUTCDate(date.getUTCDate() - day + 1);
  const weekEnd = new Date(weekStart);
  weekEnd.setUTCDate(weekStart.getUTCDate() + 6);
  const thursday = new Date(weekStart);
  thursday.setUTCDate(weekStart.getUTCDate() + 3);
  const year = thursday.getUTCFullYear();
  const firstThursday = new Date(Date.UTC(year, 0, 4));
  const firstDay = firstThursday.getUTCDay() || 7;
  firstThursday.setUTCDate(firstThursday.getUTCDate() - firstDay + 4);
  const week = 1 + Math.round((thursday.getTime() - firstThursday.getTime()) / 604_800_000);
  return { year, week, weekStart, weekEnd };
}

export function buildGanttCalendar(startSerial: number, requestedDays: number): { days: GanttDay[]; months: GanttMonth[]; weeks: GanttWeek[] } {
  const start = Math.floor(startSerial);
  const dayCount = Math.max(1, Math.ceil(requestedDays));
  const monthFormatter = new Intl.DateTimeFormat("tr-TR", { month: "long", timeZone: "UTC" });
  const fullMonthFormatter = new Intl.DateTimeFormat("tr-TR", { month: "long", year: "numeric", timeZone: "UTC" });
  const fullDateFormatter = new Intl.DateTimeFormat("tr-TR", { day: "numeric", month: "long", year: "numeric", weekday: "long", timeZone: "UTC" });
  const days = Array.from({ length: dayCount }, (_, index) => {
    const serial = start + index;
    const date = excelSerialToDate(serial);
    return {
      serial,
      dayOfMonth: date.getUTCDate(),
      isSunday: date.getUTCDay() === 0,
      monthKey: `${date.getUTCFullYear()}-${date.getUTCMonth()}`,
      fullLabel: fullDateFormatter.format(date),
    };
  });
  const months: GanttMonth[] = [];
  for (const [index, day] of days.entries()) {
    const current = months.at(-1);
    if (current?.key === day.monthKey) {
      current.dayCount += 1;
      continue;
    }
    const date = excelSerialToDate(day.serial);
    months.push({
      key: day.monthKey,
      label: monthFormatter.format(date).toLocaleUpperCase("tr-TR"),
      fullLabel: fullMonthFormatter.format(date),
      startIndex: index,
      dayCount: 1,
    });
  }
  const weeks: GanttWeek[] = [];
  for (const [index, day] of days.entries()) {
    const date = excelSerialToDate(day.serial);
    const isoWeek = isoWeekParts(date);
    const key = `${isoWeek.year}-W${String(isoWeek.week).padStart(2, "0")}`;
    const current = weeks.at(-1);
    if (current?.key === key) {
      current.dayCount += 1;
      continue;
    }
    weeks.push({
      key,
      label: `CW ${isoWeek.week}`,
      fullLabel: `${key} · ${isoDate(isoWeek.weekStart)} – ${isoDate(isoWeek.weekEnd)}`,
      startIndex: index,
      dayCount: 1,
      weekStart: isoDate(isoWeek.weekStart),
      weekEnd: isoDate(isoWeek.weekEnd),
    });
  }
  return { days, months, weeks };
}

export function ganttPercent(serial: number, horizonStart: number, horizonDays: number): number {
  return ((serial - horizonStart) / Math.max(1, horizonDays)) * 100;
}

export function ganttDropStart(pointerRatio: number, horizonStart: number, horizonDays: number, grabOffsetDays: number, stepHours = 1): number {
  const clampedRatio = Math.max(0, Math.min(1, pointerRatio));
  const rawStart = horizonStart + clampedRatio * Math.max(1, horizonDays) - Math.max(0, grabOffsetDays);
  const stepsPerDay = Math.max(1, 24 / Math.max(1, stepHours));
  return Math.round(rawStart * stepsPerDay) / stepsPerDay;
}

