import { productionProcessOrder, processLabel } from "./process-master-data";
import { buildDashboardModel } from "./dashboard";
import { buildPlanAudit, type AuditTarget } from "./plan-audit";
import { buildDownstreamProcessPlan } from "./process-planning";
import { excelSerialToDate, type PlanningSeed, type ScenarioResult } from "./planning";
import type { ProcessKind } from "./process-master-data";

export type GeneralPlanProcess = Exclude<ProcessKind, "washing">;

export type GeneralOverviewExportPayload = {
  generatedAt: string;
  createdAt: string;
  planState: ScenarioResult["state"];
  dirty: boolean;
  selectedProcess?: GeneralPlanProcess;
  printRange?: { mode: "date-range" | "next-jobs"; startDate: string; endDate: string; dayCount: number };
  summary: {
    demand: number;
    planned: number;
    plannedBatchCount: number;
    unplannedBatchCount: number;
    activeMachineCount: number;
    machineCount: number;
    machinesWithWorkCount: number;
    plannedMachineCount: number;
  };
  machines: Array<{
    id: string;
    name: string;
    active: boolean;
    plannedCount: number;
    plannedQuantity: number;
    rows: Array<{
      kind: "current" | "planned";
      position: number;
      product: string;
      diameter: string;
      quantity: number;
      endDate: string;
      workOrder: string;
    }>;
  }>;
  operationPlans: Array<{
    scrapPercent: number;
    process: GeneralPlanProcess;
    label: string;
    totalQuantity: number;
    totalJobCount: number;
    omittedJobCount: number;
    resources: Array<{
      id: string;
      name: string;
      rows: Array<{
        status: "current" | "planned";
        position: number;
        product: string;
        workOrder: string;
        quantity: number;
        diameter: string;
        materialCode: string;
        unitWeightGrams: number | null;
        scrapPercent?: number;
        setupKey: string;
        startDate: string;
        endDate: string;
      }>;
    }>;
  }>;
  findings: Array<{ severity: "critical" | "warning" | "info"; title: string; detail: string; target: string }>;
};

function isoDate(serial: number): string {
  if (!serial) return "";
  return excelSerialToDate(Math.floor(serial)).toISOString().slice(0, 10);
}

function dateSerial(value?: string): number {
  return value && /^\d{4}-\d{2}-\d{2}$/.test(value) ? (Date.parse(`${value}T00:00:00Z`) - Date.UTC(1899, 11, 30)) / 86_400_000 : 0;
}

function targetLabel(target?: AuditTarget): string {
  if (!target) return "";
  const page = ({ planning: "Planlama", orders: "Siparişler", machines: "Tezgahlar", parameters: "Parametreler", settings: "Ayarlar" })[target.view];
  return [page, target.machineId, target.orderId].filter(Boolean).join(" · ");
}

export function buildGeneralOverviewExportPayload(seed: PlanningSeed, result: ScenarioResult, dirty: boolean, generatedAt = new Date().toISOString(), selectedProcess?: GeneralPlanProcess, printRange?: { startDate?: string; endDate?: string; nextJobsOnly?: boolean }): GeneralOverviewExportPayload {
  const weights = new Map((seed.productWeights ?? []).map((row) => [row.product.trim().toUpperCase(), row]));
  const dashboard = buildDashboardModel(seed, result);
  const audit = buildPlanAudit(seed, result, { dirty });
  const processPlan = buildDownstreamProcessPlan(seed, result);
  const processDefinitions: Array<{ process: GeneralPlanProcess; label: string }> = productionProcessOrder(seed).map(process => ({ process, label: process === "deburring" ? "Çapak Alma" : processLabel(process) }));
  const rangeStart = dateSerial(printRange?.startDate);
  const rangeEnd = dateSerial(printRange?.endDate);
  const hasDateRange = rangeStart > 0 && rangeEnd >= rangeStart;
  const hasPrintRange = Boolean(printRange?.nextJobsOnly || hasDateRange);
  const operationPlans = processDefinitions.map(({ process, label }) => {
    const operations = processPlan.operations
      .filter((operation) => operation.process === process && !operation.actual)
      .filter((operation) => !hasDateRange || operation.end >= rangeStart && operation.start < rangeEnd + 1);
    const resourceIds = [...new Set([
      ...(process === "turning"
        ? seed.machines.filter((machine) => machine.active).map((machine) => machine.id)
        : (seed.processMasterData?.resources ?? []).filter((resource) => resource.active && resource.process === process).map((resource) => resource.id)),
      ...operations.map((operation) => operation.resourceId),
    ])];
    const resources = resourceIds.map((resourceId) => {
      const resourceOperations = operations
        .filter((operation) => operation.resourceId === resourceId)
        .sort((left, right) => left.start - right.start || left.id.localeCompare(right.id));
      const name = process === "turning"
        ? seed.machines.find((machine) => machine.id === resourceId)?.name ?? ""
        : seed.processMasterData?.resources.find((resource) => resource.id === resourceId)?.name ?? "";
      return {
        id: resourceId,
        name,
        rows: resourceOperations.map((operation, index) => ({
          status: operation.current || operation.source === "current-turning" && process === "turning" ? "current" as const : "planned" as const,
          position: index + 1,
          product: operation.product,
          workOrder: operation.workOrder,
          quantity: Math.max(0, Math.trunc(operation.quantity)),
          diameter: seed.products.find((product) => product.product.toUpperCase() === operation.product.toUpperCase())?.diameter
            || (operation.source === "current-turning" ? seed.machines.find((machine) => machine.id === operation.resourceId)?.currentJob.diameter : result.batches.find((batch) => batch.id === operation.batchId)?.diameter) || "",
          materialCode: weights.get(operation.product.trim().toUpperCase())?.materialCode ?? "",
          ...(seed.productionArea === "cubuk-filtre" ? { scrapPercent: (seed.products.find(p => p.product === operation.product)?.setupScrapPercent ?? 0) + (seed.products.find(p => p.product === operation.product)?.productionScrapPercent ?? 0) } : {}),
          unitWeightGrams: weights.get(operation.product.trim().toUpperCase())?.grams ?? null,
          setupKey: operation.setupKey,
          startDate: isoDate(operation.start),
          endDate: isoDate(operation.end),
        })),
      };
    });
    const sourceJobCount = resources.reduce((sum, resource) => sum + resource.rows.length, 0);
    // Only Torna has a next-jobs print limit. Date-based exports include every
    // matching operation, even when that requires additional printed pages.
    const limitedResources = hasPrintRange && process === "turning"
      ? resources.slice(0, 16).map((resource) => ({ ...resource, rows: resource.rows.slice(0, 10) }))
      : resources;
    const displayedRows = limitedResources.flatMap((resource) => resource.rows);
    return {
      process,
      label,
      scrapPercent: seed.rawMaterialSettings?.scrapPercent ?? 2,
      totalQuantity: displayedRows.reduce((sum, row) => sum + row.quantity, 0),
      totalJobCount: displayedRows.length,
      omittedJobCount: Math.max(0, sourceJobCount - displayedRows.length),
      resources: limitedResources,
    };
  });
  return {
    generatedAt,
    createdAt: result.createdAt,
    planState: result.state,
    dirty,
    selectedProcess,
    printRange: hasPrintRange ? {
      mode: printRange?.nextJobsOnly ? "next-jobs" : "date-range",
      startDate: hasDateRange ? printRange!.startDate! : "",
      endDate: hasDateRange ? printRange!.endDate! : "",
      dayCount: hasDateRange ? Math.floor(rangeEnd - rangeStart) + 1 : 0,
    } : undefined,
    summary: {
      demand: Math.max(0, Math.trunc(result.summary.demand)),
      planned: Math.max(0, Math.trunc(result.summary.planned)),
      plannedBatchCount: Math.max(0, Math.trunc(result.summary.plannedBatchCount)),
      unplannedBatchCount: Math.max(0, Math.trunc(result.summary.unplannedBatchCount)),
      activeMachineCount: dashboard.activeMachineCount,
      machineCount: seed.machines.length,
      machinesWithWorkCount: dashboard.machinesWithWorkCount,
      plannedMachineCount: dashboard.plannedMachineCount,
    },
    machines: dashboard.machines.map((board) => ({
      id: board.machine.id,
      name: board.machine.name,
      active: board.machine.active,
      plannedCount: board.plannedCount,
      plannedQuantity: Math.max(0, Math.trunc(board.plannedQuantity)),
      rows: board.queue.map((item) => ({
        kind: item.kind,
        position: item.position,
        product: item.product,
        diameter: item.diameter,
        quantity: Math.max(0, Math.trunc(item.quantity)),
        endDate: isoDate(item.end),
        workOrder: item.workOrder,
      })),
    })),
    operationPlans: selectedProcess ? operationPlans.filter((plan) => plan.process === selectedProcess) : operationPlans,
    findings: audit.findings.map((finding) => ({
      severity: finding.severity,
      title: finding.title,
      detail: finding.detail,
      target: targetLabel(finding.target),
    })),
  };
}

frontend/lib/machine-diagnostics.ts.source:
import { formatExcelDate, isMachineEligibleForProduct, moveBatchManually, type PlannedBatch, type PlanningSeed, type ScenarioResult } from "./planning";

export type MachineDiagnosticCode = "scheduled" | "inactive" | "stale" | "empty-plan" | "zero-capacity" | "invalid-window" | "no-compatible-order" | "missing-speed" | "parallel-opportunity" | "assigned-by-priority" | "window-limit" | "demand-covered";
export type MachineMoveSuggestion = {
  batchId: string;
  product: string;
  fromMachineId: string;
  toMachineId: string;
  originalCompletion: number;
  alternativeCompletion: number;
  alternativeBatchEnd: number;
  improvementDays: number;
};
export type MachineDiagnostic = {
  code: MachineDiagnosticCode;
  tone: "good" | "neutral" | "warning" | "critical";
  title: string;
  detail: string;
  products: string[];
  suggestion?: MachineMoveSuggestion;
};

export function buildMachineDiagnostics(seed: PlanningSeed, result: ScenarioResult, options: { dirty?: boolean } = {}): Record<string, MachineDiagnostic> {
  const diagnostics: Record<string, MachineDiagnostic> = {};
  const orderedProductCodes = [...new Set(seed.orders.filter((order) => order.quantity > 0).map((order) => order.product.toUpperCase()))];

  for (const machine of seed.machines) {
    const planned = result.batches.filter((batch) => batch.status === "planned" && batch.machineId === machine.id);
    if (!machine.active) {
      diagnostics[machine.id] = diagnostic("inactive", "neutral", "Planlama dışında", "Tezgah pasif olduğu için motor bu tezgaha yeni iş atamadı.");
      continue;
    }
    if (options.dirty) {
      diagnostics[machine.id] = diagnostic("stale", "warning", "Plan yeniden çalıştırılmalı", "Girdiler değiştiği için ekrandaki kuyruk artık güncel planı temsil etmiyor.");
      continue;
    }
    if (planned.length) {
      diagnostics[machine.id] = diagnostic("scheduled", "good", `${planned.length} planlı şarj`, `${planned[0].product} ile başlayan kuyruk ${formatExcelDate(planned.at(-1)?.end ?? 0)} tarihinde tamamlanıyor.`, [...new Set(planned.map((batch) => batch.product))]);
      continue;
    }
    if (result.state === "empty") {
      diagnostics[machine.id] = diagnostic("empty-plan", "neutral", "Plan henüz çalıştırılmadı", "Bu tezgah için uygunluk ve kapasite değerlendirmesi henüz yapılmadı.");
      continue;
    }
    if (machine.shiftFactor <= 0 || machine.capacityFactor <= 0) {
      diagnostics[machine.id] = diagnostic("zero-capacity", "critical", "Kullanılabilir kapasite yok", `Vardiya sayısı ${machine.shiftFactor}, kapasite katsayısı ${machine.capacityFactor}. Bu değerlerle günlük üretim sıfırdır.`);
      continue;
    }
    if (machine.availableStart >= machine.planEnd || machine.currentJob.end >= machine.planEnd) {
      diagnostics[machine.id] = diagnostic("invalid-window", "critical", "Planlama penceresi kapalı", `Tezgahın mevcut iş bitişi veya müsait başlangıcı, ${formatExcelDate(machine.planEnd)} plan bitişine ulaşıyor.`);
      continue;
    }

    const compatible = orderedProductCodes.filter((code) => isMachineEligibleForProduct(seed, machine.id, code));
    if (!compatible.length) {
      diagnostics[machine.id] = diagnostic("no-compatible-order", "warning", "Uygun açık sipariş yok", "Mevcut ürün–tezgah kurallarına göre bu tezgaha atanabilecek sipariş bulunamadı.");
      continue;
    }
    const rated = compatible.filter((code) => (machine.rates[code] ?? 0) > 0);
    if (!rated.length) {
      diagnostics[machine.id] = diagnostic("missing-speed", "critical", "Üretim hızı eksik", `${summarizeProducts(compatible)} bu tezgaha uygun; ancak ürün × tezgah üretim hızı tanımlı değil. Parametreler ekranında ürünün tezgah satırındaki “Değiştir” ile günlük üretimi girip kaydedin, ardından planı yeniden çalıştırın.`, compatible);
      continue;
    }

    const feasibleMoves = result.batches
      .filter((batch) => batch.status === "planned" && batch.machineId !== machine.id && rated.includes(batch.product.toUpperCase()))
      .map((batch) => simulateMove(seed, result, batch, machine.id))
      .filter((suggestion): suggestion is MachineMoveSuggestion => suggestion !== null)
      .sort((left, right) => right.improvementDays - left.improvementDays || left.alternativeCompletion - right.alternativeCompletion);
    const bestMove = feasibleMoves[0];
    if (bestMove?.improvementDays > 0) {
      const preference = seed.preferences.find((rule) => rule.key.toUpperCase() === bestMove.product.toUpperCase());
      const priorityExplanation = preference
        ? `${bestMove.fromMachineId}, tercih sırasında ${machine.id} tezgahından önce geldiği için motor ilk uygun atamada durdu.`
        : "Motor ilk uygun atamada durduğu için alternatif bitiş tarihlerini karşılaştırmadı.";
      diagnostics[machine.id] = {
        ...diagnostic("parallel-opportunity", "warning", "Daha erken bitiş fırsatı var", `${bestMove.product} şarjı ${bestMove.fromMachineId} yerine ${machine.id} tezgahına alınabilir. Ürünün tamamlanması ${formatExcelDate(bestMove.originalCompletion)} yerine ${formatExcelDate(bestMove.alternativeCompletion)} olur (${bestMove.improvementDays} takvim günü erken). ${priorityExplanation}`, [bestMove.product]),
        suggestion: bestMove,
      };
      continue;
    }
    if (bestMove) {
      diagnostics[machine.id] = {
        ...diagnostic("assigned-by-priority", "neutral", "Öncelik sırası başka tezgahı seçti", `${bestMove.product} şarjı teknik olarak ${machine.id} tezgahına sığıyor; ancak tam ürün bitişi ${formatExcelDate(bestMove.originalCompletion)} tarihinden daha erkene gelmiyor. Motor bu nedenle değil, sabit aday sırasındaki ilk uygun tezgahı seçti.`, [bestMove.product]),
        suggestion: bestMove,
      };
      continue;
    }

    const unmet = rated.filter((code) => result.orders.some((order) => order.product.toUpperCase() === code && order.difference < 0)
      || result.batches.some((batch) => batch.status === "unplanned" && batch.product.toUpperCase() === code));
    if (unmet.length) {
      diagnostics[machine.id] = diagnostic("window-limit", "warning", "Uygun iş pencereye sığmadı", `${summarizeProducts(unmet)} üretilebilir; ancak vardiya, mevcut iş bitişi veya plan sonu nedeniyle yeni şarj yerleşmedi.`, unmet);
      continue;
    }

    diagnostics[machine.id] = diagnostic("demand-covered", "neutral", "Talep diğer kuyruklarda karşılandı", `${summarizeProducts(rated)} üretilebilir; mevcut motor talebi diğer uygun tezgahlarda karşıladı. Paralel kullanımın termin kazancı henüz karşılaştırılmıyor.`, rated);
  }
  return diagnostics;
}

function diagnostic(code: MachineDiagnosticCode, tone: MachineDiagnostic["tone"], title: string, detail: string, products: string[] = []): MachineDiagnostic {
  return { code, tone, title, detail, products };
}

function summarizeProducts(products: string[]): string {
  const visible = products.slice(0, 3).join(", ");
  return products.length > 3 ? `${visible} ve ${products.length - 3} ürün daha` : visible;
}

function simulateMove(seed: PlanningSeed, result: ScenarioResult, batch: PlannedBatch, targetMachineId: string): MachineMoveSuggestion | null {
  try {
    const alternative = moveBatchManually(seed, result, batch.id, targetMachineId, 0);
    const originalCompletion = productCompletion(seed, result, batch.product);
    const alternativeCompletion = productCompletion(seed, alternative, batch.product);
    const moved = alternative.batches.find((item) => item.id === batch.id);
    if (!moved) return null;
    return {
      batchId: batch.id,
      product: batch.product,
      fromMachineId: batch.machineId,
      toMachineId: targetMachineId,
      originalCompletion,
      alternativeCompletion,
      alternativeBatchEnd: moved.end,
      improvementDays: Math.max(0, Math.round(originalCompletion - alternativeCompletion)),
    };
  } catch {
    return null;
  }
}

function productCompletion(seed: PlanningSeed, result: ScenarioResult, product: string): number {
  const code = product.toUpperCase();
  return Math.max(
    0,
    ...seed.machines.filter((machine) => machine.currentJob.product.toUpperCase() === code).map((machine) => machine.currentJob.end),
    ...result.batches.filter((batch) => batch.status === "planned" && batch.product.toUpperCase() === code).map((batch) => batch.end),
  );
}

