import type { PlanningSeed, ScenarioResult } from "./planning";

/** Change the operating date without rewriting recorded work or queue dates. */
export function setMachineAvailability(seed: PlanningSeed, machineId: string, start: number): void {
  const machine = seed.machines.find(item => item.id === machineId);
  if (!machine) throw new Error(`${machineId} tezgahı bulunamadı.`);
  if (!Number.isInteger(start) || start <= 0) throw new Error("Geçerli bir müsait başlangıç tarihi girin.");
  machine.availableStart = start;
  machine.operationalAvailableStart = start;
  seed.planNeedsRecalculation = true;
  seed.lastAutomaticPlan = undefined;
  seed.planRunSequence = undefined;
}

export type MachineDeletionAnalysis = {
  machineId: string;
  currentJobProduct: string;
  plannedBatches: Array<{ id: string; product: string }>;
  parameterProducts: string[];
  savedBatchCount: number;
  calendarEventCount: number;
  blocked: boolean;
  requiresReplacement: boolean;
};

function replaceMachine(values: string[], sourceId: string, replacementId: string): string[] {
  return [...new Set(values.map((value) => value === sourceId ? replacementId : value).filter(Boolean))];
}

export function analyzeMachineDeletion(seed: PlanningSeed, result: ScenarioResult, machineId: string): MachineDeletionAnalysis {
  const machine = seed.machines.find((item) => item.id === machineId);
  if (!machine) throw new Error(`${machineId} tezgahı bulunamadı.`);
  const planned = new Map<string, { id: string; product: string }>();
  [...result.batches, ...(seed.manualBatches ?? [])]
    .filter((batch) => batch.status === "planned" && batch.machineId === machineId)
    .forEach((batch) => planned.set(batch.id, { id: batch.id, product: batch.product }));
  const parameterProducts = new Set<string>();
  seed.products.forEach((product) => {
    if (product.generalMachine === machineId || product.eligibleMachines.includes(machineId) || product.alternativeMachines.includes(machineId)) parameterProducts.add(product.product);
  });
  seed.preferences.forEach((rule) => {
    if (rule.machines.includes(machineId)) parameterProducts.add(rule.key);
  });
  Object.keys(machine.rates).filter((product) => machine.rates[product] > 0).forEach((product) => parameterProducts.add(product));
  const savedBatchCount = seed.savedBatches.filter((batch) => batch.machineId === machineId).length;
  const plannedBatches = [...planned.values()];
  return {
    machineId,
    currentJobProduct: machine.currentJob.product,
    plannedBatches,
    parameterProducts: [...parameterProducts].sort(),
    savedBatchCount,
    calendarEventCount: (seed.calendarEvents ?? []).filter((event) => event.machineId === machineId).length,
    blocked: Boolean(machine.currentJob.product || plannedBatches.length),
    requiresReplacement: Boolean(parameterProducts.size || savedBatchCount),
  };
}

export function deleteMachineDefinition(seed: PlanningSeed, result: ScenarioResult, machineId: string, replacementId?: string): MachineDeletionAnalysis {
  const analysis = analyzeMachineDeletion(seed, result, machineId);
  if (analysis.blocked) throw new Error(`${machineId} üzerinde mevcut veya planlı iş var. Önce işi tamamlayın ya da başka tezgaha taşıyın.`);
  if (analysis.requiresReplacement && !replacementId) throw new Error(`${machineId} parametrelerde kullanılıyor. Aktarım için alternatif tezgah seçin.`);
  if (replacementId === machineId) throw new Error("Silinecek tezgah alternatif olarak seçilemez.");
  const replacement = replacementId ? seed.machines.find((machine) => machine.id === replacementId) : undefined;
  if (replacementId && !replacement) throw new Error(`${replacementId} alternatif tezgahı bulunamadı.`);
  const source = seed.machines.find((machine) => machine.id === machineId)!;

  if (replacement) {
    seed.products.forEach((product) => {
      if (product.generalMachine === machineId) product.generalMachine = replacement.id;
      product.eligibleMachines = replaceMachine(product.eligibleMachines, machineId, replacement.id);
      product.alternativeMachines = replaceMachine(product.alternativeMachines, machineId, replacement.id);
      if (product.inactiveMachineIds?.includes(machineId)) product.inactiveMachineIds = replaceMachine(product.inactiveMachineIds, machineId, replacement.id);
    });
    seed.preferences.forEach((rule) => { rule.machines = replaceMachine(rule.machines, machineId, replacement.id); });
    Object.entries(source.rates).forEach(([product, rate]) => {
      if (rate > 0 && !(replacement.rates[product] > 0)) replacement.rates[product] = rate;
    });
    seed.savedBatches.forEach((batch) => { if (batch.machineId === machineId) batch.machineId = replacement.id; });
    seed.orders.forEach((order) => { order.savedMachines = replaceMachine(order.savedMachines, machineId, replacement.id); });
  } else {
    seed.products.forEach((product) => {
      product.eligibleMachines = product.eligibleMachines.filter((id) => id !== machineId);
      product.alternativeMachines = product.alternativeMachines.filter((id) => id !== machineId);
      product.inactiveMachineIds = product.inactiveMachineIds?.filter((id) => id !== machineId);
      if (product.generalMachine === machineId) product.generalMachine = product.eligibleMachines[0] ?? "";
    });
    seed.preferences.forEach((rule) => { rule.machines = rule.machines.filter((id) => id !== machineId); });
    seed.savedBatches = seed.savedBatches.filter((batch) => batch.machineId !== machineId);
    seed.orders.forEach((order) => { order.savedMachines = order.savedMachines.filter((id) => id !== machineId); });
  }

  seed.restrictions = seed.restrictions.filter((restriction) => restriction.machineId !== machineId);
  seed.calendarEvents = (seed.calendarEvents ?? []).filter((event) => event.machineId !== machineId);
  seed.machines = seed.machines.filter((machine) => machine.id !== machineId);
  return analysis;
}

