import { FILTER_PROCESS_ORDER } from "./process-master-data";
import { buildDownstreamProcessPlan } from "./process-planning";
import type { PlanningSeed, ScenarioResult } from "./planning";
import type { ProcessKind } from "./process-master-data";

export type OperationWorkload = {
  process: ProcessKind;
  activeQuantity: number;
  waitingQuantity: number;
  totalQuantity: number;
  activeJobCount: number;
  waitingJobCount: number;
  totalJobCount: number;
};

export function buildOperationWorkloads(seed: PlanningSeed, result: ScenarioResult): Record<ProcessKind, OperationWorkload> {
  const turningActive = seed.machines.filter((machine) => machine.currentJob.product).map((machine) => machine.currentJob);
  const turningWaiting = result.batches.filter((batch) => batch.status === "planned");
  const downstream = buildDownstreamProcessPlan(seed, result).operations;

  const workload = (process: ProcessKind): OperationWorkload => {
    if (process === "turning") {
      const activeQuantity = turningActive.reduce((sum, job) => sum + Math.max(0, job.remainingQuantity ?? job.quantity), 0);
      const waitingQuantity = turningWaiting.reduce((sum, batch) => sum + Math.max(0, batch.quantity), 0);
      return {
        process,
        activeQuantity,
        waitingQuantity,
        totalQuantity: activeQuantity + waitingQuantity,
        activeJobCount: turningActive.length,
        waitingJobCount: turningWaiting.length,
        totalJobCount: turningActive.length + turningWaiting.length,
      };
    }

    const active = downstream.filter((operation) => operation.process === process && !operation.actual && operation.current);
    const waiting = downstream.filter((operation) => operation.process === process && !operation.actual && !operation.current);
    const activeQuantity = active.reduce((sum, operation) => sum + Math.max(0, operation.quantity), 0);
    const waitingQuantity = waiting.reduce((sum, operation) => sum + Math.max(0, operation.quantity), 0);
    return {
      process,
      activeQuantity,
      waitingQuantity,
      totalQuantity: activeQuantity + waitingQuantity,
      activeJobCount: active.length,
      waitingJobCount: waiting.length,
      totalJobCount: active.length + waiting.length,
    };
  };

  return {
    turning: workload("turning"),
    drilling: workload("drilling"),
    deburring: workload("deburring"),
    gkm: workload("gkm"),
    ...Object.fromEntries(FILTER_PROCESS_ORDER.filter(p => p !== "turning").map(p => [p, workload(p)])) as Record<Exclude<ProcessKind, "turning" | "drilling" | "deburring" | "gkm">, OperationWorkload>,
  };
}

