import { excelSerialToDate, machineDayCapacity, type Machine, type PlanningSeed, type ScenarioResult } from "./planning";

export const SHIFT_HOURS = 8;
export const MAINTENANCE_DAY_HOURS = 24;
export const OUTSOURCED_MACHINE_IDS = ["C-16", "C-17"] as const;

export type OperationalMetrics = {
  rangeStart?: number;
  rangeEnd?: number;
  plannedOvertimeHours: number;
  overtimeShiftCount: number;
  maintenanceHours: number;
  maintenanceMachineDays: number;
  outsourcedQuantity: number;
  entries: OperationalMetricEntry[];
};

export type OperationalMetricEntry = {
  id: string;
  kind: "overtime" | "maintenance";
  machineId: string;
  name: string;
  start: number;
  end: number;
  hours: number;
};

function clampShifts(value: number | undefined): number {
  return Number.isFinite(value) ? Math.max(0, Math.min(3, Math.trunc(value!))) : 0;
}

function regularShifts(seed: PlanningSeed, machine: Machine, serial: number): number {
  const isHoliday = seed.holidays.some((holiday) => Math.floor(holiday.serial) === serial);
  const isSunday = excelSerialToDate(serial).getUTCDay() === 0;
  return isHoliday || isSunday ? 0 : clampShifts(machine.shiftFactor);
}

function eventDays(startValue: number, endValue: number): number[] {
  const start = Math.floor(Math.min(startValue, endValue));
  const end = Math.floor(Math.max(startValue, endValue));
  return Array.from({ length: end - start + 1 }, (_, index) => start + index);
}

export function buildOperationalMetrics(seed: PlanningSeed, result: ScenarioResult, selectedRange?: { start: number; end: number }): OperationalMetrics {
  const machines = new Map(seed.machines.map((machine) => [machine.id, machine]));
  const rangeStart = selectedRange ? Math.floor(Math.min(selectedRange.start, selectedRange.end)) : Number.NEGATIVE_INFINITY;
  const rangeEnd = selectedRange ? Math.floor(Math.max(selectedRange.start, selectedRange.end)) : Number.POSITIVE_INFINITY;
  const capacityCandidateDays = new Set<string>();
  const maintenanceDays = new Set<string>();

  for (const holiday of seed.holidays) {
    const serial = Math.floor(holiday.serial);
    if (serial < rangeStart || serial > rangeEnd) continue;
    for (const machine of seed.machines.filter((item) => item.active)) capacityCandidateDays.add(`${machine.id}:${serial}`);
  }
  for (const event of seed.calendarEvents ?? []) {
    for (const serial of eventDays(event.start, event.end)) {
      if (serial < rangeStart || serial > rangeEnd) continue;
      const key = `${event.machineId}:${serial}`;
      capacityCandidateDays.add(key);
      if (event.kind === "maintenance") maintenanceDays.add(key);
    }
  }

  let overtimeShiftCount = 0;
  for (const key of capacityCandidateDays) {
    const separator = key.lastIndexOf(":");
    const machine = machines.get(key.slice(0, separator));
    const serial = Number(key.slice(separator + 1));
    if (!machine?.active || !Number.isFinite(serial)) continue;
    const effective = machineDayCapacity(seed, machine, serial).shifts;
    overtimeShiftCount += Math.max(0, effective - regularShifts(seed, machine, serial));
  }

  const outsourced = new Set<string>(OUTSOURCED_MACHINE_IDS);
  const outsourcedQuantity = result.batches
    .filter((batch) => batch.status === "planned" && outsourced.has(batch.machineId))
    .filter((batch) => !selectedRange || batch.end >= rangeStart && batch.start < rangeEnd + 1)
    .reduce((sum, batch) => sum + batch.quantity, 0);

  const calendarEntries = (seed.calendarEvents ?? []).flatMap<OperationalMetricEntry>((event): OperationalMetricEntry[] => {
    const machine = machines.get(event.machineId);
    if (!machine?.active) return [];
    const start = Math.max(Math.floor(event.start), rangeStart);
    const end = Math.min(Math.floor(event.end), rangeEnd);
    if (end < start) return [];
    if (event.kind === "maintenance") return [{ id: event.id, kind: "maintenance" as const, machineId: event.machineId, name: event.name, start, end, hours: (end - start + 1) * MAINTENANCE_DAY_HOURS }];
    const extraShiftCount = eventDays(start, end).reduce((sum, serial) => {
      const effective = machineDayCapacity(seed, machine, serial).shifts;
      return sum + Math.max(0, effective - regularShifts(seed, machine, serial));
    }, 0);
    return extraShiftCount > 0 ? [{ id: event.id, kind: "overtime" as const, machineId: event.machineId, name: event.name, start, end, hours: extraShiftCount * SHIFT_HOURS }] : [];
  });
  const holidayEntries = seed.holidays.flatMap<OperationalMetricEntry>((holiday): OperationalMetricEntry[] => {
    const serial = Math.floor(holiday.serial);
    if (serial < rangeStart || serial > rangeEnd) return [];
    return seed.machines.filter((machine) => machine.active).flatMap<OperationalMetricEntry>((machine): OperationalMetricEntry[] => {
      const overridden = (seed.calendarEvents ?? []).some((event) => event.machineId === machine.id && event.kind === "shift" && serial >= Math.floor(event.start) && serial <= Math.floor(event.end));
      if (overridden) return [];
      const extraShiftCount = Math.max(0, machineDayCapacity(seed, machine, serial).shifts - regularShifts(seed, machine, serial));
      return extraShiftCount > 0 ? [{ id: `holiday-${machine.id}-${serial}`, kind: "overtime" as const, machineId: machine.id, name: `${holiday.name} çalışma vardiyası`, start: serial, end: serial, hours: extraShiftCount * SHIFT_HOURS }] : [];
    });
  });
  const entries = [...calendarEntries, ...holidayEntries].sort((left, right) => left.start - right.start || left.machineId.localeCompare(right.machineId, "tr", { numeric: true }));

  return {
    rangeStart: selectedRange ? rangeStart : undefined,
    rangeEnd: selectedRange ? rangeEnd : undefined,
    plannedOvertimeHours: overtimeShiftCount * SHIFT_HOURS,
    overtimeShiftCount,
    maintenanceHours: maintenanceDays.size * MAINTENANCE_DAY_HOURS,
    maintenanceMachineDays: maintenanceDays.size,
    outsourcedQuantity,
    entries,
  };
}

