function emptyOrder(product: string, sourceRow: number): Order {
  return {
    id: `manual-${product}`,
    sourceRow,
    product,
    quantity: 0,
    savedPlanned: 0,
    savedDifference: 0,
    savedMachines: [],
    dueDate: "",
    allowPartial: false,
    partialDeliveryQuantity: 0,
    partialDeliveryDate: "",
    deliveryMilestones: [],
  };
}

export function sortOrdersByCatalog(orders: Order[], catalog: string[] = TIPLER_ORDER_TEMPLATE.map((row) => row.product)): Order[] {
  const catalogIndex = new Map(catalog.map((product, index) => [product.toUpperCase(), index]));
  return [...orders].sort((left, right) => {
    const leftIndex = catalogIndex.get(left.product.toUpperCase()) ?? Number.MAX_SAFE_INTEGER;
    const rightIndex = catalogIndex.get(right.product.toUpperCase()) ?? Number.MAX_SAFE_INTEGER;
    return leftIndex - rightIndex || left.sourceRow - right.sourceRow || left.product.localeCompare(right.product);
  });
}

export function upsertManualOrder(orders: Order[], product: string, quantity: number, dueDate: string, catalog: string[] = TIPLER_ORDER_TEMPLATE.map((row) => row.product)): Order[] {
  const normalizedProduct = product.trim().toUpperCase();
  const normalizedQuantity = Math.max(0, Math.trunc(Number(quantity) || 0));
  const existing = orders.find((order) => order.product.toUpperCase() === normalizedProduct);
  if (normalizedQuantity === 0) return sortOrdersByCatalog(orders.filter((order) => order !== existing), catalog);
  if (existing) return sortOrdersByCatalog(orders.map((order) => order === existing ? { ...order, quantity: normalizedQuantity, dueDate } : order), catalog);
  const catalogIndex = catalog.findIndex((item) => item.toUpperCase() === normalizedProduct);
  const sourceRow = (catalogIndex >= 0 ? catalogIndex : catalog.length) + 2;
  return sortOrdersByCatalog([...orders, { ...emptyOrder(normalizedProduct, sourceRow), quantity: normalizedQuantity, dueDate }], catalog);
}

export function applyDueDateToAllOrders(orders: Order[], dueDate: string): Order[] {
  const normalizedDueDate = dueDate.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalizedDueDate) || !Number.isFinite(Date.parse(`${normalizedDueDate}T00:00:00Z`))) {
    throw new Error("Geçerli bir genel termin tarihi girin.");
  }
  return orders.map((order) => ({ ...order, dueDate: normalizedDueDate }));
}

export function ordersFromImportedRows(existingOrders: Order[], rows: OrderTemplateRow[]): Order[] {
  const existingByProduct = new Map(existingOrders.map((order) => [order.product.toUpperCase(), order]));
  return rows.filter((row) => row.quantity > 0).map((row) => {
    const sourceRow = rows.findIndex((candidate) => candidate.product === row.product) + 2;
    const existing = existingByProduct.get(row.product);
    return existing
      ? { ...existing, sourceRow, quantity: row.quantity }
      : { ...emptyOrder(row.product, sourceRow), quantity: row.quantity };
  });
}

export function ordersFromTiplerTemplate(existingOrders: Order[]): Order[] {
  return ordersFromImportedRows(existingOrders, TIPLER_ORDER_TEMPLATE);
}

export function tiplerTemplateSummary() {
  const activeRows = TIPLER_ORDER_TEMPLATE.filter((row) => row.quantity > 0);
  return { productCount: TIPLER_ORDER_TEMPLATE.length, orderCount: activeRows.length, totalQuantity: activeRows.reduce((sum, row) => sum + row.quantity, 0) };
}

