import {
  isMachineEligibleForProduct,
  recalculateManualScenario,
  scenarioResultFromBatches,
  type PlannedBatch,
  type PlanningSeed,
  type ScenarioResult,
} from "./planning";
import { activeProcessResourceIds, processLabel, resourceSupportsProcessProduct, type DownstreamProcess, type ProcessKind } from "./process-master-data";
import { buildDownstreamProcessPlan } from "./process-planning";
import { hasProtectedProductionRemainder } from "./production-interruptions";

/**
 * Product-resource deactivation (Parametreler → Planlama durumu → Pasif).
 * Running work is always retained. Each queued job needs one explicit planner
 * decision before the assignment becomes Pasif; nothing is moved or removed
 * silently.
 */
export type DeactivationTarget = { process: "turning" | DownstreamProcess; product: string; resourceId: string };
export type DeactivationDecisionKind = "move" | "release-to-automatic" | "remove";
export type DeactivationAffectedJob = {
  key: string;
  kind: "running" | "queued";
  process: ProcessKind;
  product: string;
  resourceId: string;
  batchId: string;
  workOrder: string;
  quantity: number;
  start: number;
  end: number;
  locked: boolean;
  protectedRemainder: boolean;
  /** Saved manual placement on this pair (downstream). Optional for older callers. */
  pinned?: boolean;
  allowedDecisions: DeactivationDecisionKind[];
  moveTargets: string[];
};
export type DeactivationDecision = { key: string; kind: DeactivationDecisionKind; targetResourceId?: string };
export type DeactivationImpact = { target: DeactivationTarget; running: DeactivationAffectedJob[]; queued: DeactivationAffectedJob[]; signature: string };

const code = (value: string) => value.trim().toUpperCase();
const clone = <T,>(value: T): T => structuredClone(value);
const label = (target: DeactivationTarget) => `${target.product} × ${target.resourceId} (${target.process === "turning" ? "Torna" : processLabel(target.process)})`;

function downstreamParameter(seed: PlanningSeed, product: string, process: DownstreamProcess) {
  return seed.processMasterData?.products.find(item => code(item.product) === code(product))?.processes.find(item => item.process === process);
}

export function isAssignmentPasif(seed: PlanningSeed, target: DeactivationTarget): boolean {
  if (target.process === "turning") return Boolean(seed.products.find(item => code(item.product) === code(target.product))?.inactiveMachineIds?.includes(target.resourceId));
  return Boolean(downstreamParameter(seed, target.product, target.process)?.inactiveResourceIds?.includes(target.resourceId));
}

function setAssignmentPasif(seed: PlanningSeed, target: DeactivationTarget): void {
  if (target.process === "turning") {
    const product = seed.products.find(item => code(item.product) === code(target.product));
    if (!product) throw new Error(`${target.product} Torna parametresi bulunamadı.`);
    product.inactiveMachineIds = [...new Set([...(product.inactiveMachineIds ?? []), target.resourceId])];
    return;
  }
  const parameter = downstreamParameter(seed, target.product, target.process);
  if (!parameter || !parameter.resourcePriority.includes(target.resourceId)) throw new Error(`${label(target)} ataması Parametreler’de bulunamadı.`);
  parameter.inactiveResourceIds = [...new Set([...(parameter.inactiveResourceIds ?? []), target.resourceId])];
}

function turningMoveTargets(seed: PlanningSeed, target: DeactivationTarget): string[] {
  return seed.machines
    .filter(machine => machine.id !== target.resourceId && machine.active && machine.shiftFactor > 0 && (machine.rates[code(target.product)] ?? 0) > 0 && isMachineEligibleForProduct(seed, machine.id, target.product))
    .map(machine => machine.id);
}

function downstreamMoveTargets(seed: PlanningSeed, target: DeactivationTarget & { process: DownstreamProcess }): string[] {
  const product = seed.processMasterData?.products.find(item => code(item.product) === code(target.product));
  const parameter = downstreamParameter(seed, target.product, target.process);
  if (!product || !parameter) return [];
  return activeProcessResourceIds(parameter).filter(id => {
    const resource = seed.processMasterData?.resources.find(item => item.id === id);
    return id !== target.resourceId && resource?.active && resource.process === target.process && resource.defaultShifts > 0 && resourceSupportsProcessProduct(resource, product) && (parameter.unitsPerShift[id] ?? 0) > 0;
  });
}

function referencedByLaterWork(seed: PlanningSeed, batchId: string): boolean {
  return Boolean(seed.wipLots?.some(lot => lot.sourceBatchId === batchId)
    || seed.processOperationOverrides?.some(item => item.batchId === batchId)
    || seed.processCurrentJobs?.some(item => item.batchId === batchId)
    || seed.productionHistory?.some(item => item.sourceBatchId === batchId));
}

function signatureOf(running: DeactivationAffectedJob[], queued: DeactivationAffectedJob[]): string {
  return JSON.stringify([...running, ...queued].map(job => [job.key, job.resourceId, job.quantity, job.start, job.end, job.locked]));
}

/** Read-only list of running and queued jobs that a Pasif change affects. */
export function parameterDeactivationImpact(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">, target: DeactivationTarget): DeactivationImpact {
  const after = clone(seed);
  if (!isAssignmentPasif(after, target)) setAssignmentPasif(after, target);
  const running: DeactivationAffectedJob[] = [];
  const queued: DeactivationAffectedJob[] = [];
  if (target.process === "turning") {
    const machine = seed.machines.find(item => item.id === target.resourceId);
    if (!machine) throw new Error(`${target.resourceId} tezgahı bulunamadı.`);
    const current = machine.currentJob;
    if (current.quantity > 0 && code(current.product) === code(target.product)) running.push({
      key: `turning:current:${machine.id}`, kind: "running", process: "turning", product: current.product, resourceId: machine.id,
      batchId: current.batchId ?? `current:${machine.id}`, workOrder: current.workOrder, quantity: current.remainingQuantity ?? current.quantity,
      start: current.start, end: current.end, locked: true, protectedRemainder: false, pinned: true, allowedDecisions: [], moveTargets: [],
    });
    const moveTargets = turningMoveTargets(after, target);
    for (const batch of result.batches.filter(item => item.status === "planned" && item.machineId === target.resourceId && code(item.product) === code(target.product)).sort((a, b) => a.planColumn - b.planColumn)) {
      const protectedRemainder = hasProtectedProductionRemainder(seed, batch.id, batch.interruptionId);
      const removable = !batch.locked && !protectedRemainder && !batch.routeCommitted && !referencedByLaterWork(seed, batch.id);
      queued.push({
        key: `turning:${batch.id}`, kind: "queued", process: "turning", product: batch.product, resourceId: batch.machineId, batchId: batch.id,
        workOrder: batch.workOrder?.trim() ?? "", quantity: batch.quantity, start: batch.start, end: batch.end, locked: Boolean(batch.locked),
        protectedRemainder, pinned: true, allowedDecisions: [...(moveTargets.length ? ["move" as const] : []), ...(removable ? ["remove" as const] : [])], moveTargets,
      });
    }
  } else {
    const process = target.process;
    // Build placements with the pair Active so legacy pinned work stays visible.
    const visible = clone(seed);
    const parameter = downstreamParameter(visible, target.product, process);
    if (parameter) parameter.inactiveResourceIds = parameter.inactiveResourceIds?.filter(id => id !== target.resourceId);
    const plan = buildDownstreamProcessPlan(visible, result);
    const moveTargets = downstreamMoveTargets(after, { ...target, process });
    for (const operation of plan.operations.filter(item => item.process === process && item.resourceId === target.resourceId && code(item.product) === code(target.product) && !item.actual)) {
      const pinned = Boolean(seed.processOperationOverrides?.some(item => item.batchId === operation.batchId && item.process === process && item.resourceId === target.resourceId && item.routeMode !== "automatic"));
      const job: DeactivationAffectedJob = {
        key: `${process}:${operation.batchId}`, kind: operation.current ? "running" : "queued", process, product: operation.product, resourceId: operation.resourceId,
        batchId: operation.batchId, workOrder: operation.workOrder, quantity: operation.quantity, start: operation.start, end: operation.end,
        locked: Boolean(operation.current), protectedRemainder: false, pinned,
        allowedDecisions: operation.current ? [] : [...(moveTargets.length ? ["move" as const] : []), "release-to-automatic"], moveTargets: operation.current ? [] : moveTargets,
      };
      (operation.current ? running : queued).push(job);
    }
  }
  return { target, running, queued, signature: signatureOf(running, queued) };
}

/** Apply Pasif with exactly one validated decision for each queued job. */
export function applyParameterDeactivation(
  seed: PlanningSeed,
  result: ScenarioResult,
  target: DeactivationTarget,
  decisions: DeactivationDecision[],
  signature: string,
): { seed: PlanningSeed; result: ScenarioResult; summary: string } {
  const impact = parameterDeactivationImpact(seed, result, target);
  if (impact.signature !== signature) throw new Error("Plan değişti; etkilenen işleri yeniden inceleyin.");
  const byKey = new Map<string, DeactivationDecision>();
  for (const decision of decisions) {
    if (byKey.has(decision.key)) throw new Error(`${label(target)}: ${decision.key} için birden fazla karar var.`);
    byKey.set(decision.key, decision);
  }
  const unknown = decisions.find(decision => !impact.queued.some(job => job.key === decision.key));
  if (unknown) throw new Error(`${label(target)}: ${unknown.key} etkilenen kuyruk işleri arasında değil.`);
  for (const job of impact.queued) {
    const decision = byKey.get(job.key);
    const trace = `${job.product} · ${job.workOrder || job.batchId} · ${job.resourceId}`;
    if (!decision) throw new Error(`Parametreler: ${label(target)} Pasif yapılamadı. ${trace} kuyrukta bekliyor; bu iş için karar seçin.`);
    if (!job.allowedDecisions.includes(decision.kind)) throw new Error(`Parametreler: ${trace} için “${decision.kind}” kararı uygun değil${job.locked ? " (kilitli iş)" : ""}${job.protectedRemainder ? " (yarım kalan iş)" : ""}.`);
    if (decision.kind === "move" && !job.moveTargets.includes(decision.targetResourceId ?? "")) throw new Error(`Parametreler: ${trace} için seçilen hedef ${decision.targetResourceId || "—"} aktif ve uygun değil.`);
  }

  const nextSeed = clone(seed);
  setAssignmentPasif(nextSeed, target);
  let nextResult: ScenarioResult = { ...result, batches: result.batches.map(batch => ({ ...batch })) };
  const updatedAt = new Date().toISOString();
  if (target.process === "turning") {
    let batches = nextResult.batches;
    for (const job of impact.queued) {
      const decision = byKey.get(job.key)!;
      if (decision.kind === "remove") batches = batches.filter(batch => batch.id !== job.batchId);
      if (decision.kind === "move") {
        const tail = Math.max(12, ...batches.filter(batch => batch.status === "planned" && batch.machineId === decision.targetResourceId).map(batch => batch.planColumn));
        batches = batches.map(batch => batch.id === job.batchId ? { ...batch, machineId: decision.targetResourceId!, planColumn: tail + 1 } : batch);
      }
    }
    // Only the source and target machines are recalculated; the shared
    // scheduler keeps all other machine queues byte-for-byte.
    const touched = new Set([target.resourceId, ...[...byKey.values()].map(item => item.targetResourceId).filter(Boolean) as string[]]);
    const recalculated = recalculateManualScenario({ ...nextSeed, machines: nextSeed.machines.filter(machine => touched.has(machine.id)) }, batches.filter(batch => touched.has(batch.machineId) && batch.status === "planned"));
    const byId = new Map(recalculated.batches.map(batch => [batch.id, batch]));
    const merged: PlannedBatch[] = batches.map(batch => byId.get(batch.id) ?? batch);
    nextResult = { ...scenarioResultFromBatches(nextSeed, merged), planRun: result.planRun ?? seed.activePlanRun };
  } else {
    const process = target.process;
    for (const job of impact.queued) {
      const decision = byKey.get(job.key)!;
      nextSeed.processOperationOverrides = (nextSeed.processOperationOverrides ?? []).filter(item => !(item.batchId === job.batchId && item.process === process));
      // "automatic" is the existing route mode that ignores the saved resource;
      // it also records that the planner decided this job.
      nextSeed.processOperationOverrides.push(decision.kind === "move"
        ? { batchId: job.batchId, process, resourceId: decision.targetResourceId!, requestedStart: job.start, routeMode: "manual", sourceProduct: job.product, updatedAt }
        : { batchId: job.batchId, process, resourceId: target.resourceId, requestedStart: job.start, routeMode: "automatic", sourceProduct: job.product, updatedAt });
    }
  }
  nextSeed.planNeedsRecalculation = true;
  const moved = impact.queued.filter(job => byKey.get(job.key)?.kind === "move").length;
  const removed = impact.queued.filter(job => byKey.get(job.key)?.kind === "remove").length;
  const released = impact.queued.length - moved - removed;
  return {
    seed: nextSeed,
    result: nextResult,
    summary: `${label(target)} Pasif · ${impact.running.length} çalışan iş korundu · ${moved} taşındı · ${released} otomatik planlamaya bırakıldı · ${removed} plandan çıkarıldı`,
  };
}

function pasifTargets(seed: PlanningSeed): DeactivationTarget[] {
  const targets: DeactivationTarget[] = [];
  for (const product of seed.products) for (const resourceId of product.inactiveMachineIds ?? []) targets.push({ process: "turning", product: product.product, resourceId });
  for (const product of seed.processMasterData?.products ?? []) for (const parameter of product.processes) {
    for (const resourceId of parameter.inactiveResourceIds ?? []) targets.push({ process: parameter.process as DownstreamProcess, product: product.product, resourceId });
  }
  return targets;
}

const targetKey = (target: DeactivationTarget) => `${target.process}|${code(target.product)}|${target.resourceId}`;

/**
 * Guard for every parameter write path (direct save, Excel/JSON import, old
 * forms). A new Pasif assignment with undecided queued work is rejected.
 * Torna: planned charges that would stay on the Pasif pair. Downstream:
 * saved placements pinned to the Pasif pair, which would otherwise drop out.
 * Legacy Pasif assignments that already existed before the write are allowed.
 */
export function assertParameterTransitionDecided(before: PlanningSeed, after: PlanningSeed, batches: PlannedBatch[] = after.manualBatches ?? []): void {
  const previous = new Set(pasifTargets(before).map(targetKey));
  const problems: string[] = [];
  for (const target of pasifTargets(after).filter(item => !previous.has(targetKey(item)))) {
    if (target.process === "turning") {
      for (const batch of batches.filter(item => item.status === "planned" && item.machineId === target.resourceId && code(item.product) === code(target.product))) {
        problems.push(`${batch.product} · ${batch.workOrder?.trim() || batch.id} · ${batch.machineId} (Torna${batch.locked ? ", kilitli" : ""})`);
      }
    } else {
      // Every queued job that the previous state placed on this pair needs a
      // recorded decision: a move to another resource or an explicit release
      // to automatic planning. Running work is retained without a decision.
      const process = target.process;
      const visible = { ...before, manualBatches: batches };
      const affected = parameterDeactivationImpact(visible, { batches }, target).queued;
      for (const job of affected) {
        const decided = after.processOperationOverrides?.some(item => item.batchId === job.batchId && item.process === process
          && (item.routeMode === "automatic" || item.resourceId !== target.resourceId));
        if (!decided) problems.push(`${job.product} · ${job.workOrder || job.batchId} · ${job.resourceId} (${processLabel(process)}${job.pinned ? ", elle yerleşim" : ""})`);
      }
    }
  }
  if (problems.length) {
    throw new Error(`Parametreler: Pasif yapılan atamada kuyruktaki işler için karar gerekiyor. ${problems.slice(0, 5).join("; ")}${problems.length > 5 ? ` ve ${problems.length - 5} iş daha` : ""}. “Pasif yapmadan önce etkilenen işler” penceresinden her iş için karar verin.`);
  }
}

/** Saved states that already contain queued work on a Pasif pair (legacy evidence is kept). */
export function inactiveAssignmentConflicts(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">): DeactivationImpact[] {
  return pasifTargets(seed)
    .map(target => parameterDeactivationImpact(seed, result, target))
    .filter(impact => impact.target.process === "turning" ? impact.queued.length > 0 : impact.queued.some(job => job.pinned));
}

