import { diameterNumeric, type PlanningSeed } from "./planning";
import { effectiveProductMachines } from "./parameters";
import { activeProcessResourceIds, processLabel, processMasterDataForProduct, productProcessRoute, productionProcessOrder, type ProcessKind } from "./process-master-data";
import { resolvedProductSetupFamily } from "./setup-families";

export type ProductParameterGap = {
  field: string;
  process?: ProcessKind;
  resources: string[];
  requirement: string;
  source: string;
};

/** Read-only data review. Capacity closures and operational records are not missing parameters. */
export function productParameterGaps(seed: PlanningSeed, productCode: string): ProductParameterGap[] {
  const code = productCode.trim().toUpperCase();
  const product = seed.products.find(item => item.product.toUpperCase() === code);
  const master = processMasterDataForProduct(seed.processMasterData, code);
  const filter = seed.productionArea === "cubuk-filtre" || master?.family === "cubuk-filtre";
  const gaps: ProductParameterGap[] = [];
  const add = (field: string, requirement: string, process?: ProcessKind, resources: string[] = []) => gaps.push({ field, requirement, process, resources,
    source: field === "Proses rotası" && filter ? "04_OPERASYON ROTASI" : process ? filter ? "04_OPERASYON ROTASI" : `Parametreler → ${processLabel(process)}` : filter ? "01_URUNLER" : "Parametreler → Torna" });
  if (!product || !resolvedProductSetupFamily(code, product.setupFamily)) add("Ürün ailesi", "Ürün ailesini seçin.");
  if (!product || !Number.isInteger(product.batchSize) || product.batchSize <= 0) add("Şarj büyüklüğü", "Pozitif tam sayı girin · adet.");
  if (!product || diameterNumeric(product.diameter) <= 0) add("Hammadde çapı", "Pozitif hammadde çapı girin · mm.");
  const route = master ? productProcessRoute(master) : [];
  if (!master || !route.length) add("Proses rotası", "Aktif prosesleri ve sıralarını tanımlayın. Her proses için kaynak, adet/vardiya ve Setup / Ayar [dk] bilgilerini girin.");
  else if (route.join("|") !== productionProcessOrder(seed).filter(p => route.includes(p)).join("|")) add("Proses rotası", "Proses sırasını düzeltin; aynı prosesi tekrar etmeyin.");
  const turning = master ? route.includes("turning") : true;
  if (turning) {
    if (!product || !positive(product.dailyRate)) add("Varsayılan vardiyalık üretim", "Pozitif üretim adedi girin · adet/vardiya.", "turning");
    const ids = product ? effectiveProductMachines(seed, product).filter(id => !product.inactiveMachineIds?.includes(id)) : [];
    if (!ids.length) add("Tezgah eşleşmesi", "En az bir tezgah seçin ve ürün için Aktif yapın.", "turning");
    const unknown = ids.filter(id => !seed.machines.some(m => m.id === id));
    if (unknown.length) add("Tezgah eşleşmesi", "Kayıtlı bir tezgah kodu seçin.", "turning", unknown);
    const rates = ids.filter(id => seed.machines.some(m => m.id === id) && !positive(seed.machines.find(m => m.id === id)!.rates[code]));
    if (rates.length) add("Vardiyalık üretim", "Pozitif üretim adedi girin · adet/vardiya.", "turning", rates);
    const setup = filter ? ids.filter(id => !nonnegative(product?.turningSetupMinutes?.[id])) : [];
    if (setup.length) add("Setup / Ayar", "Sıfır veya pozitif süre girin · dk. Setup yoksa 0 girin.", "turning", setup);
  }
  for (const process of route.filter(p => p !== "turning")) {
    const parameter = master?.processes.find(p => p.process === process);
    if (!parameter) { add("Proses kaydı", "Bu aktif prosesin kaynak, hız ve setup bilgilerini tanımlayın.", process); continue; }
    const ids = activeProcessResourceIds(parameter);
    if (!ids.length) add("Kaynak eşleşmesi", "En az bir kaynak seçin ve ürün için Aktif yapın.", process);
    const invalid = ids.filter(id => {
      const resource = seed.processMasterData?.resources.find(r => r.id === id);
      return !resource || resource.process !== process;
    });
    if (invalid.length) add("Kaynak eşleşmesi", "Bu proses için kayıtlı bir kaynak kodu seçin.", process, invalid);
    const rates = ids.filter(id => !positive(parameter.unitsPerShift[id]));
    if (rates.length) add("Vardiyalık üretim", "Pozitif üretim adedi girin · adet/vardiya.", process, rates);
    const setup = filter ? ids.filter(id => !nonnegative(parameter.setupMinutesByResource?.[id])) : [];
    if (setup.length) add("Setup / Ayar", "Sıfır veya pozitif süre girin · dk. Setup yoksa 0 girin.", process, setup);
    if (process === "drilling" && !parameter.setupKey.trim()) add("Matkap çapı", "Matkap çapını tanımlayın.", process);
  }
  return gaps;
}

function positive(value: unknown): boolean { return typeof value === "number" && Number.isFinite(value) && value > 0; }
function nonnegative(value: unknown): boolean { return typeof value === "number" && Number.isFinite(value) && value >= 0; }

