import { isMachineEligibleForProduct, type Machine, type PlannedBatch, type PlanningSeed } from "./planning";

function normalizeSearchValue(value: string): string {
  return value.trim().toLocaleLowerCase("tr-TR");
}

export function machineMatchesPlanningQuery(machine: Machine, plannedBatches: PlannedBatch[], query: string): boolean {
  const needle = normalizeSearchValue(query);
  if (!needle) return true;

  const searchableValues = [
    machine.id,
    machine.name,
    machine.currentJob.product,
    machine.currentJob.workOrder,
    ...plannedBatches
      .filter((batch) => batch.machineId === machine.id)
      .flatMap((batch) => [batch.product, batch.workOrder ?? "", batch.id]),
  ];

  return searchableValues.some((value) => normalizeSearchValue(value).includes(needle));
}

export function compatibleMachineIdsForBatch(seed: PlanningSeed, batch: Pick<PlannedBatch, "product">): Set<string> {
  const product = batch.product.toUpperCase();
  return new Set(seed.machines
    .filter((machine) => machine.active && (machine.rates[product] ?? 0) > 0 && isMachineEligibleForProduct(seed, machine.id, product))
    .map((machine) => machine.id));
}

