import type { PlanningSeed } from './planning';
import type { ProcessOperation } from './process-planning';
import { activeLotInterruptions } from './production-interruptions';
import { activeProcessResourceIds, processMasterDataForProduct, resourceSupportsProcessProduct } from './process-master-data';
import { wipOperationReadyAt } from './wip-ledger';

/** Physical admission shared by direct starts, UI availability and automatic promotion. */
export function actualProcessStartEligibility(seed: PlanningSeed, operation: ProcessOperation, at: number, confirmedInterruption = false): { ok: boolean; reason: string } {
  const denied=(reason:string)=>({ok:false,reason});
  if (!Number.isFinite(at) || at<=0) return denied('Geçerli bir üretim başlangıç tarihi seçin.');
  if (operation.actual || operation.current || operation.process==='turning' || operation.source!=='wip') return denied('Bu iş henüz sahadaki yarı mamül değil; önce önceki operasyon tamamlanmalı.');
  const lot=seed.wipLots?.find(l=>l.id===operation.wipLotId);
  if (!lot || lot.nextProcess!==operation.process || lot.availableQuantity<=0 || lot.stage==='on-hold' || lot.stage==='unclassified') return denied('Önceki proses henüz tamamlanmadı veya yarı mamül serbest bırakılmadı.');
  if (!Number.isInteger(operation.quantity) || operation.quantity<=0 || operation.quantity>lot.availableQuantity) return denied('Üretime alınacak adet yarı mamül bakiyesiyle uyuşmuyor.');
  if (!Number.isFinite(wipOperationReadyAt(lot)) || wipOperationReadyAt(lot)>at+1e-8) return denied('Yarı mamülün gerçek hazır olma tarihi henüz gelmedi.');
  if (activeLotInterruptions(seed,lot).length && !confirmedInterruption) return denied('Üretim sonlanmadı, yine de üretime alayım mı? Devam etmek için onaylayın.');
  if (seed.processCurrentJobs?.some(j=>j.resourceId===operation.resourceId)) return denied(`${operation.resourceId} üzerinde zaten çalışan bir iş var.`);
  const resource=seed.processMasterData?.resources.find(r=>r.id===operation.resourceId);
  const product=processMasterDataForProduct(seed.processMasterData,lot.product);
  const parameter=product?.processes.find(p=>p.process===operation.process);
  if (!resource?.active || resource.process!==operation.process || resource.defaultShifts<=0 || !product || !resourceSupportsProcessProduct(resource,product) || !parameter || !activeProcessResourceIds(parameter).includes(resource.id) || !Number.isFinite(parameter.unitsPerShift[resource.id]) || parameter.unitsPerShift[resource.id]<=0 || product.route && !product.route.includes(operation.process)) return denied('İş merkezi, ürün rotası veya vardiya kapasitesi üretime uygun değil.');
  if ((resource.availableStart??0)>at+1e-8 || resource.planEnd && at>=Math.floor(resource.planEnd)+1) return denied('İş merkezi seçilen tarihte üretime uygun değil.');
  return {ok:true,reason:''};
}

