import { addMachineCapacityHours, getSetupSettings, machineDayCapacity, type PlanningSeed } from "./planning";
import type { ProcessOperation } from "./process-planning";
import type { ProcessResource } from "./process-master-data";

type Segment = { start: number; end: number; before: number; rate: number };
type Curve = { segments: Segment[]; quantity: number; start: number; end: number };

export function curve(seed: PlanningSeed, resource: { id: string; shiftFactor: number }, start: number, end: number, setupHours: number, quantity: number): Curve | undefined {
  const windows: Array<{ start: number; end: number }> = [];
  let setup = setupHours, hours = 0;
  if (end - start > 36600 || end <= start || quantity <= 0) return undefined;
  for (let day = Math.floor(start); day <= Math.floor(end); day += 1) {
    const shifts = machineDayCapacity(seed, resource, day).shifts;
    let left = Math.max(start, day);
    const right = Math.min(end, day + shifts * getSetupSettings(seed).shiftHours / 24);
    const skipped = Math.min(setup, Math.max(0, right - left) * 24);
    setup -= skipped; left += skipped / 24;
    if (right > left) { windows.push({ start: left, end: right }); hours += (right - left) * 24; }
  }
  if (hours <= 1e-8) return undefined;
  let before = 0;
  const rate = quantity / hours * 24;
  const segments = windows.map(window => { const segment = { ...window, before, rate }; before += (window.end - window.start) * rate; return segment; });
  return { segments, quantity, start: windows[0].start, end: windows.at(-1)!.end };
}

export function produced(curve: Curve, time: number): number {
  if (time < curve.start - 1e-10) return 0;
  if (time >= curve.end) return curve.quantity;
  const segment = curve.segments.find(item => time <= item.end) ?? curve.segments.at(-1)!;
  return Math.min(curve.quantity, segment.before + Math.max(0, time - segment.start) * segment.rate);
}

/** Check every slope change, including consumption of the first piece at run start.
 * One-piece lead is conservative for discrete pieces; no transfer stock is created. */
function noStarvation(supply: Curve, demand: Curve): boolean {
  const times = [...supply.segments, ...demand.segments].flatMap(item => [item.start, item.end]);
  for (const time of times) {
    if (time < demand.start - 1e-10 || time > demand.end + 1e-10) continue;
    const needed = Math.min(demand.quantity, produced(demand, time) + Math.min(1, demand.quantity));
    if (produced(supply, time) + 1e-5 < needed) return false;
  }
  // The demand curve changes slope when the last piece has been consumed.
  for (const segment of demand.segments) {
    const time = segment.start + (demand.quantity - Math.min(1, demand.quantity) - segment.before) / segment.rate;
    if (time >= segment.start && time <= segment.end && produced(supply, time) + 1e-5 < demand.quantity) return false;
  }
  return true;
}

export type DynamicFlowTiming = { start: number; end: number; targetEnd: number; reason?: string };

export function dynamicFlowTiming(seed: PlanningSeed, calendarSeed: PlanningSeed, resource: ProcessResource, predecessor: ProcessOperation, requestedStart: number, setupHours: number, runHours: number, quantity: number, targetMinutes: number): DynamicFlowTiming {
  const machine = { id: resource.id, shiftFactor: resource.defaultShifts, finishOffset: 0 };
  const schedule = (start: number) => addMachineCapacityHours(calendarSeed, machine, start, setupHours + runHours);
  const targetEnd = predecessor.end + targetMinutes / 1440;
  const upstream = predecessor.process === "turning"
    ? seed.machines.find(item => item.id === predecessor.resourceId)
    : seed.processMasterData?.resources.find(item => item.id === predecessor.resourceId);
  const upstreamCalendar = predecessor.resourceId.startsWith("B-01-")
    ? { ...seed, calendarEvents: seed.calendarEvents?.map(event => event.machineId === "B-01" ? { ...event, machineId: predecessor.resourceId } : event) } : seed;
  const supply = upstream && !predecessor.current && !(predecessor.process === "turning" && predecessor.source === "current-turning") && !predecessor.actual && predecessor.quantity === quantity
    ? curve(upstreamCalendar, { id: upstream.id, shiftFactor: "shiftFactor" in upstream ? upstream.shiftFactor : upstream.defaultShifts }, predecessor.start, predecessor.end, predecessor.setupHours, quantity) : undefined;
  if (!supply) return { ...schedule(Math.max(requestedStart, predecessor.end)), targetEnd, reason: "Önceki prosesin güvenilir parça çıkış eğrisi yok; kayıtlı bitiş sonrası güvenli başlangıç kullanıldı." };
  const safe = (start: number) => {
    const timing = schedule(start);
    const consumption = curve(calendarSeed, machine, timing.start, timing.end, setupHours, quantity);
    return !!consumption && noStarvation(supply, consumption);
  };
  let left = Math.max(requestedStart, predecessor.start), right = Math.max(left, predecessor.end);
  if (!safe(left)) {
    for (let iteration = 0; iteration < 36; iteration += 1) {
      const middle = (left + right) / 2;
      if (safe(middle)) right = middle; else left = middle;
    }
    left = right;
  }
  const earliest = schedule(left + 1e-8);
  if (earliest.end > targetEnd + 1e-6) return { ...earliest, targetEnd, reason: "Hedef; parça beslemesi, setup, vardiya/bakım veya dolu kuyruk nedeniyle sağlanamıyor. En erken kesintisiz ve güvenli bitiş gösteriliyor." };
  // Delay within available capacity to the requested finish target. This is a
  // per-transition target, not a promise of a globally optimal factory schedule.
  right = Math.max(left, targetEnd);
  for (let iteration = 0; iteration < 36; iteration += 1) {
    const middle = (left + right) / 2;
    if (schedule(middle).end <= targetEnd + 1e-7) left = middle; else right = middle;
  }
  return { ...schedule(left), targetEnd };
}

