import { addMachineCapacityHours, machineDayCapacity, type PlanningSeed } from "./planning";
import type { ProductProcessParameter } from "./process-master-data";

export const FILTER_WAIT_RESOURCE = "CF-BEKLEME";
/** Waiting stages use their own calendar. They do not reserve shared-line capacity. */
export function applyProcessLeadStages(seed: PlanningSeed, start: number, stages: ProductProcessParameter["leadStages"]): number {
  const resource = { id: FILTER_WAIT_RESOURCE, shiftFactor: seed.filterWaitShifts ?? 1, finishOffset: 0 };
  let cursor = start;
  for (const stage of stages ?? []) {
    if (!Number.isFinite(stage.days) || stage.days < 0 || stage.days > 366) throw new Error("Bekleme süresi 0–366 gün arasında olmalıdır.");
    if (stage.days === 0) continue;
    if (stage.calendarMode && resource.shiftFactor === 0 && !seed.calendarEvents?.some(event => event.machineId === FILTER_WAIT_RESOURCE && event.end >= Math.floor(cursor) && (event.shiftCount ?? 0) > 0) && !seed.holidays.some(holiday => holiday.serial >= Math.floor(cursor) && (holiday.workingShifts ?? 0) > 0)) throw new Error("Çubuk Filtre bekleme takviminde çalışma vardiyası yok.");
    if (stage.calendarMode === "workdays") {
      if (!Number.isInteger(stage.days) || stage.days < 0) throw new Error("Bekleme iş günü pozitif tam sayı veya sıfır olmalıdır.");
      const fraction = cursor - Math.floor(cursor);
      let day = Math.floor(cursor), remaining = stage.days, guard = 0;
      while (remaining > 0) {
        day++;
        if (machineDayCapacity(seed, resource, day).shifts > 0) remaining--;
        if (++guard > 36600) throw new Error("Çubuk Filtre bekleme takviminde çalışma günü bulunamadı.");
      }
      cursor = day + fraction;
    } else if (stage.calendarMode === "workhours") {
      cursor = addMachineCapacityHours(seed, resource, cursor, stage.days * 24).end;
    } else cursor += stage.days;
  }
  return cursor;
}

export function processLeadStageLabel(stage: NonNullable<ProductProcessParameter["leadStages"]>[number]): string {
  return `${stage.label}: ${stage.calendarMode === "workdays" ? `${stage.days} iş günü` : `${stage.days * 24} ${stage.calendarMode === "workhours" ? "çalışma saati" : "saat"}`}`;
}

frontend/lib/process-master-data.ts.source:
import masterJson from "../data/process-master-data.json";

export type ProcessKind = "turning" | "drilling" | "deburring" | "gkm" | "gtm" | "diameter-grinding" | "form-grinding" | "measuring" | "milling" | "final-inspection" | "filter-visual";
export type DownstreamProcess = Exclude<ProcessKind, "turning">;
export type ProductFamily = "piston" | "center-pin" | "cubuk-filtre";
export type ProcessPlanningStrategy = "campaign" | "earliest-ready";

export type MachineCodeStandard = {
  processGroup: string;
  prefix: string;
  meaning: string;
  example: string;
};

export type ProcessResource = {
  id: string;
  sourceProgramId: string;
  erpWorkCenterCode: string;
  name: string;
  operationCode: string;
  operationName: string;
  process: ProcessKind;
  active: boolean;
  defaultShifts: 0 | 1 | 2 | 3;
  /** Earliest date this resource may accept newly planned work. */
  availableStart?: number;
  /** Last date in the resource planning window. */
  planEnd?: number;
  /** Product groups this resource may process. Undefined keeps legacy all-product behavior. */
  eligibleProductGroups?: string[];
};

export type ProductProcessParameter = {
  process: DownstreamProcess;
  sequence: number;
  waitWorkdaysBefore: number;
  setupKey: string;
  resourcePriority: string[];
  /** Assigned resources temporarily excluded from new plans for this product. */
  inactiveResourceIds?: string[];
  /** Static production quantity for one shift. */
  unitsPerShift: Record<string, number>;
  /** Workbook resource-specific changeover, plus per-charge handling. */
  setupMinutesByResource?: Record<string, number>;
  handlingMinutes?: number;
  /** Elapsed lead stages (not resource capacity or factory working days). */
  leadStages?: Array<{ label: string; days: number; calendarMode?: "workdays" | "workhours" }>;
  /** Çubuk Filtre forecast finish gap, in elapsed minutes. Never releases actual WIP. */
  finishGapMinutes?: number;

};

export type ProcessProduct = {
  product: string;
  family: ProductFamily;
  /** Explicit active route selected in Yeni tip; absent preserves legacy routes. */
  route?: ProcessKind[];
  /** Planner-managed grouping used for resource capability, especially GKM. */
  productGroup?: string;
  processes: ProductProcessParameter[];
};

export function activeProcessResourceIds(parameter: ProductProcessParameter): string[] {
  return parameter.resourcePriority.filter((id) => !parameter.inactiveResourceIds?.includes(id));
}

export const FILTER_PROCESS_ORDER: ProcessKind[] = ["turning", "gtm", "diameter-grinding", "form-grinding", "measuring", "milling", "final-inspection", "filter-visual"];
export function productionProcessOrder(seed: { productionArea?: string }): ProcessKind[] {
  return seed.productionArea === "cubuk-filtre" ? FILTER_PROCESS_ORDER : PRODUCT_PROCESS_ORDER;
}
export function effectiveProductRoute(product: ProcessProduct, turningResourceId?: string): ProcessKind[] {
  const route = productProcessRoute(product);
  return product.family === "cubuk-filtre" && ["L-01", "L-02"].includes(turningResourceId ?? "") ? route.filter(p => p !== "gtm") : route;
}
export const PRODUCT_PROCESS_ORDER: ProcessKind[] = ["turning", "drilling", "deburring", "gkm"];

export function productProcessRoute(product: ProcessProduct): ProcessKind[] {
  return product.route ?? ["turning", ...product.processes.slice().sort((a, b) => a.sequence - b.sequence).map(item => item.process)];
}

export function turningEnabled(master: ProcessMasterData | undefined, product: string): boolean {
  return processMasterDataForProduct(master, product)?.route?.includes("turning") ?? true;
}

export type ProcessMasterData = {
  version: number;
  source: {
    kind: "one-time-foundation";
    files: string[];
    calculatedOnce: string;
  };
  machineCodeStandard: MachineCodeStandard[];
  resources: ProcessResource[];
  products: ProcessProduct[];
  planningStrategies?: Partial<Record<DownstreamProcess, ProcessPlanningStrategy>>;
  /** Quantity that must be available before a downstream operation may overlap its predecessor. */
  transferBatchQuantities?: Partial<Record<DownstreamProcess, number>>;
};

export const FOUNDATIONAL_PROCESS_MASTER_DATA = masterJson as unknown as ProcessMasterData;

export function cloneFoundationalProcessMasterData(): ProcessMasterData {
  return JSON.parse(JSON.stringify(FOUNDATIONAL_PROCESS_MASTER_DATA)) as ProcessMasterData;
}

export function processMasterDataForProduct(master: ProcessMasterData | undefined, productCode: string): ProcessProduct | undefined {
  const code = productCode.trim().toUpperCase();
  return master?.products.find((product) => product.product.toUpperCase() === code);
}

export function processProductGroup(product: Pick<ProcessProduct, "family" | "productGroup">): string {
  return product.productGroup?.trim() || product.family;
}

export function resourceSupportsProcessProduct(resource: ProcessResource, product: Pick<ProcessProduct, "family" | "productGroup">): boolean {
  if (resource.eligibleProductGroups === undefined) return true;
  const group = processProductGroup(product).toLocaleLowerCase("tr-TR");
  return resource.eligibleProductGroups.some((item) => item.trim().toLocaleLowerCase("tr-TR") === group);
}

export function processLabel(process: ProcessKind): string {
  return ({ turning: "Torna", drilling: "Delme", deburring: "Çapak alma", gkm: "GKM", gtm: "GTM", "diameter-grinding": "Çap Taşlama", "form-grinding": "Form Taşlama", measuring: "Ölçme", milling: "Freze", "final-inspection": "Final Kontrol", "filter-visual": "Göz Kontrol" })[process];
}

