import type { PlanningSeed } from './planning';
import { processMasterDataForProduct, effectiveProductRoute, processLabel, type ProcessKind, type DownstreamProcess } from './process-master-data';
import type { RoutedProcessJob, ProcessOperation, ProcessPlanWarning } from './process-planning';
import { activeLotInterruptions, isProductionInterruption } from './production-interruptions';

export type ProcessRouteState = 'completed' | 'running' | 'scheduled' | 'paused' | 'manual-required' | 'predecessor-pending' | 'capacity-blocked' | 'invalid-route';
export type ProcessReadinessIssue = { code: ProcessRouteState | 'missing-product' | 'missing-schedule' | 'held' | 'unclassified'; message: string; process?: ProcessKind };
export type ProcessRouteStep = { process: ProcessKind; state: ProcessRouteState; quantity: number; operationId?: string; reason?: string; resourceId?: string };
export type ProcessQueueEntry = { id: string; batchId: string; product: string; workOrder: string; quantity: number; process: DownstreamProcess; resourceId: string; scheduled: boolean; operationId?: string; reason?: string; queueOrder: number; resumeAfterCurrent: boolean };

/** Required steps are inventory/route facts, never inferred from successful scheduling. */
export function describeProcessRoute(seed: PlanningSeed, job: RoutedProcessJob, warnings: ProcessPlanWarning[]): { routeSteps: ProcessRouteStep[]; readinessIssues: ProcessReadinessIssue[] } {
  const product = processMasterDataForProduct(seed.processMasterData, job.product);
  if (!product) return { routeSteps: [], readinessIssues: [{code:'missing-product',message:'Ürün rotası bulunamadı; miktar korunuyor.'}] };
  const route = effectiveProductRoute(product, job.turningMachineId);
  const lot = seed.wipLots?.find(l=>l.id===job.wipLotId);
  const chargeId = job.source === 'current-turning' ? seed.machines?.find(m=>m.id===job.turningMachineId)?.currentJob.batchId : job.batchId;
  const pause = seed.productionInterruptions?.find(p=>isProductionInterruption(p)&&!p.completedAt&&p.chargeId===chargeId);
  const partial = activeLotInterruptions(seed,lot).length>0;
  const issues: ProcessReadinessIssue[] = [];
  const routeSteps = route.map((process): ProcessRouteStep => {
    const op = job.operations.find(o=>(o.recordedProcess??o.process)===process);
    const base = {process,quantity:job.quantity,operationId:op?.id,resourceId:op?.resourceId};
    if (op?.actual) return {...base,state:'completed'};
    if (op?.current || job.source === 'current-turning' && process === 'turning' || seed.processCurrentJobs?.some(current => current.batchId === job.batchId && current.process === process)) return {...base,state:'running'};
    if (op) return {...base,state:'scheduled'};
    let state: ProcessRouteState = 'capacity-blocked';
    let message = `${processLabel(process)} için tarih hesaplanamadı; kapasite ve kayıtlı yerleşimi kontrol edin.`;
    let code: ProcessReadinessIssue['code'] = state;
    if (lot?.stage==='on-hold' || lot?.stage==='unclassified') {
      code=lot.stage==='on-hold'?'held':'unclassified';
      state='predecessor-pending'; message=lot.stage==='on-hold'?'Yarı mamül blokeli.':'Yarı mamülün gerçek konumu doğrulanmalı.';
    } else if (pause && route.indexOf(process)>=route.indexOf(pause.process as ProcessKind)) {
      state=process===pause.process?'paused':'predecessor-pending';code=state;
      message=process===pause.process?'Ara verilen iş kuyrukta korunuyor.':'Ara verilen önceki prosesin tamamlanması bekleniyor.';
    } else if (partial) {
      state=process===lot?.nextProcess?'manual-required':'predecessor-pending';code=state;
      message=state==='manual-required'?'Yarım üretim: bu prosesi Manuel şarj ile kuyruğa ekleyin.':'Önceki proses ve manuel üretim onayı bekleniyor.';
    } else if (warnings.some(w => w.product === job.product && (w.code === 'invalid-route' || w.code === 'missing-parameter' && !w.batchId))) {
      state='invalid-route';code=state;message='Ürün rotası veya proses parametreleri eksik.';
    } else if (route.indexOf(process)>0 && !job.operations.some(o=>(o.recordedProcess??o.process)===route[route.indexOf(process)-1])) {
      state='predecessor-pending';code=state;message='Önceki prosesin hazır olma tarihi belirlenemedi.';
    }
    issues.push({code,message,process});return {...base,state,reason:message};
  });
  if (!route.length) issues.push({code:'invalid-route',message:'Aktif ürün rotası bulunamadı.'});
  if (!job.deliveryReadyAt && !issues.length) issues.push({code:'missing-schedule',message:'Teslimata hazır tarih doğrulanamadı.'});
  return {routeSteps,readinessIssues:issues};
}

/** Saved queue intent survives an unavailable date/resource; no new stock or schedule is created. */
export function processQueueEntries(seed: PlanningSeed, jobs: RoutedProcessJob[], operations: ProcessOperation[]): ProcessQueueEntry[] {
  const rows = new Map<string, ProcessQueueEntry>();
  const intents = (seed.processOperationOverrides ?? []).filter(intent => intent.routeMode !== 'automatic');
  for (const pause of seed.productionInterruptions??[]) {
    if (!isProductionInterruption(pause) || pause.completedAt || pause.process==='turning' || pause.process==='washing' || intents.some(i=>i.batchId===pause.chargeId&&i.process===pause.process)) continue;
    intents.push({batchId:pause.chargeId,process:pause.process,resourceId:pause.resourceId,requestedStart:pause.occurredAt,resumeAfterCurrent:true,updatedAt:''});
  }
  for (const intent of intents) {
    const job=jobs.find(j=>j.batchId===intent.batchId); if (!job || job.quantity<=0) continue;
    const step=job.routeSteps?.find(s=>s.process===intent.process);
    if (step?.state==='completed' || step?.state==='running') continue;
    if (seed.processCurrentJobs?.some(c=>c.batchId===job.batchId&&c.process===intent.process)) continue;
    const op=operations.find(o=>o.batchId===job.batchId&&o.process===intent.process&&!o.actual&&!o.current);
    rows.set(`${job.batchId}:${intent.process}`,{id:`${job.batchId}:${intent.process}`,batchId:job.batchId,product:job.product,workOrder:job.workOrder,quantity:job.quantity,process:intent.process,resourceId:intent.resourceId,scheduled:Boolean(op),operationId:op?.id,reason:op?undefined:step?.reason??'Kayıtlı iş için tarih hesaplanamadı; rota ve kapasiteyi kontrol edin.',queueOrder:intent.queueOrder??Number.MAX_SAFE_INTEGER,resumeAfterCurrent:Boolean(intent.resumeAfterCurrent)});
  }
  return [...rows.values()].sort((a,b)=>Number(b.resumeAfterCurrent)-Number(a.resumeAfterCurrent)||a.queueOrder-b.queueOrder||a.id.localeCompare(b.id));
}

