import { curve, produced } from "./process-flow";
import { excelSerialToDate, type PlanningSeed } from "./planning";
import type { ProcessOperation } from "./process-planning";

/** Read-only allocation of existing forecast curves; no new schedule or actual output. */
export function formGrindingShiftRows(seed: PlanningSeed, operations: ProcessOperation[], start: number, days: number) {
  if (!Number.isInteger(days) || days < 1 || days > 31 || !Number.isFinite(start)) throw new Error("Vardiya görünümü 1–31 gün olmalıdır.");
  // The date names the day on which the night shift ends. Report windows do not change capacity.
  const shifts = [{ from: -1, to: 7, fromHour: 23, toHour: 7 }, { from: 7, to: 15, fromHour: 7, toHour: 15 }, { from: 15, to: 23, fromHour: 15, toHour: 23 }];
  const resources = seed.processMasterData?.resources.filter(resource => resource.process === "form-grinding") ?? [];
  const warnings = new Set<string>();
  const prepared = operations.filter(operation => operation.process === "form-grinding").map(operation => {
    const resource = resources.find(item => item.id === operation.resourceId);
    const output = !operation.actual && resource ? curve(seed, { id: resource.id, shiftFactor: resource.defaultShifts }, operation.start, operation.end, operation.setupHours, operation.quantity) : undefined;
    if (!operation.actual && !output) warnings.add(`${operation.resourceId} · ${operation.product}: vardiya dağılımı hesaplanamadı.`);
    return { operation, output };
  });
  const rows = Array.from({ length: days }, (_, day) => shifts.map((window, shift) => {
    const from = Math.floor(start) + day + window.from / 24;
    const to = Math.floor(start) + day + window.to / 24;
    return { date: excelSerialToDate(Math.floor(start) + day).toISOString().slice(0, 10), shift: shift + 1, fromHour: window.fromHour, toHour: window.toHour, resources: resources.map(resource => {
      const items = prepared.filter(item => item.operation.resourceId === resource.id);
      const planned = items.reduce((sum, item) => sum + (item.output ? Math.floor(produced(item.output, to) + 1e-5) - Math.floor(produced(item.output, from) + 1e-5) : 0), 0);
      // A completion belongs to the shift ending at the exact boundary.
      const actual = items.reduce((sum, item) => sum + (item.operation.actual && item.operation.end > from && item.operation.end <= to ? item.operation.quantity : 0), 0);
      return { id: resource.id, planned, actual };
    }) };
  })).flat();
  return { rows, warnings: [...warnings] };
}

