import { buildDownstreamProcessPlan } from "./process-planning";
import { excelSerialToDate, type PlanningSeed, type ScenarioResult } from "./planning";
import { effectiveProductRoute, type ProcessKind } from "./process-master-data";
import { resolvedProductSetupFamily } from "./setup-families";

export type StockGroup = { id: string; label: string; nextProcesses: ProcessKind[]; min: number; max: number };
export type ProcessStockSettings = {
  version: 1; limits: Array<{ groupId: string; min: number; max: number }>;
  scrap: Array<{ groupId: string; product: string; percent: number }>;
  openingDate: string; opening: Array<{ groupId: string; product: string; quantity: number }>;
};
export function stockGroups(area?: string): StockGroup[] {
  return area === "cubuk-filtre" ? [
    { id: "form-front", label: "Form Taşlama önünde · Torna + Çap Taşlama", nextProcesses: ["turning", "gtm", "diameter-grinding", "form-grinding"], min: 102199, max: 199953 },
    { id: "mill-front", label: "Freze önü · Form Taşlama + Ölçme", nextProcesses: ["measuring", "milling"], min: 13331, max: 44434 },
    { id: "visual-front", label: "Isıl İşlem + Göz Kontrolü", nextProcesses: ["final-inspection", "filter-visual"], min: 84425, max: 124415 },
    { id: "warehouse", label: "Ambar + BB", nextProcesses: [], min: 112600, max: 284760 },
  ] : [
    { id: "turning-end", label: "Torna sonu", nextProcesses: ["drilling"], min: 7372, max: 20412 },
    { id: "drilling-end", label: "TBT sonu", nextProcesses: ["deburring"], min: 5671, max: 11340 },
    { id: "visual-front", label: "GK önü", nextProcesses: ["gkm"], min: 5671, max: 14742 },
    { id: "warehouse", label: "Ambar + Konsinye", nextProcesses: [], min: 56702, max: 113402 },
  ];
}
export function initialProcessStockSettings(area?: string): ProcessStockSettings {
  return { version: 1, limits: stockGroups(area).map(({ id, min, max }) => ({ groupId: id, min, max })), scrap: [], openingDate: "", opening: [] };
}
export function validateProcessStockSettings(value: ProcessStockSettings, area?: string): ProcessStockSettings {
  const fail = (): never => { throw new Error("Stok ayarlarını kontrol edin: adetler tam sayı, min ≤ max ve ıskarta %0–100 olmalıdır."); };
  const groups = new Set(stockGroups(area).map(group => group.id));
  if (!value || value.version !== 1 || !Array.isArray(value.limits) || !Array.isArray(value.scrap) || !Array.isArray(value.opening) || value.scrap.length > 1000 || value.opening.length > 1000) return fail();
  const keys = new Set<string>();
  for (const row of value.limits) {
    if (!row || !groups.has(row.groupId) || keys.has(row.groupId) || ![row.min, row.max].every(n => Number.isSafeInteger(n) && n >= 0) || row.min > row.max) return fail();
    keys.add(row.groupId);
  }
  if (keys.size !== groups.size) return fail();
  keys.clear();
  for (const row of value.scrap) {
    if (!row) return fail();
    const key = `${row.groupId}:${row.product}`;
    if (!row || !groups.has(row.groupId) || typeof row.product !== "string" || !/^[A-Z0-9][A-Z0-9._/-]{1,63}$/.test(row.product) || keys.has(key) || !Number.isFinite(row.percent) || row.percent < 0 || row.percent > 100) return fail();
    keys.add(key);
  }
  keys.clear();
  for (const row of value.opening) {
    if (!row) return fail();
    const key = `${row.groupId}:${row.product}`;
    if (!row || !groups.has(row.groupId) || typeof row.product !== "string" || !/^[A-Z0-9][A-Z0-9._/-]{1,63}$/.test(row.product) || keys.has(key) || !Number.isSafeInteger(row.quantity) || row.quantity < 0) return fail();
    keys.add(key);
  }
  if (value.opening.some(row => row.quantity > 0) && (!/^\d{4}-\d{2}-\d{2}$/.test(value.openingDate) || !Number.isFinite(Date.parse(value.openingDate)) || new Date(value.openingDate).toISOString().slice(0, 10) !== value.openingDate)) return fail();
  return structuredClone(value);
}
export function processStockScrap(settings: ProcessStockSettings, area: string | undefined, groupId: string, product: string): number {
  return settings.scrap.find(row => row.groupId === groupId && row.product === product)?.percent
    ?? (area === "cubuk-filtre" && groupId !== "warehouse" ? product === "2.433.084.245" ? 4 : 2 : 0);
}
export function extraProcessStockByProduct(seed: Pick<PlanningSeed, "processStockSettings">): Record<string, number> {
  const output: Record<string, number> = {};
  for (const row of seed.processStockSettings?.opening ?? []) output[row.product] = (output[row.product] ?? 0) + row.quantity;
  return output;
}

/** Disjoint process groups. A group is not proof of readiness at its next machine. */
export function buildProcessStockProjection(seed: PlanningSeed, result: ScenarioResult, now: number, weekCount = 8) {
  if (!Number.isFinite(now) || !Number.isInteger(weekCount) || weekCount < 1 || weekCount > 53) throw new Error("Stok dönemi 1–53 hafta olmalıdır.");
  const settings = validateProcessStockSettings(seed.processStockSettings ?? initialProcessStockSettings(seed.productionArea), seed.productionArea);
  const groups = stockGroups(seed.productionArea).map(group => ({ ...group, ...settings.limits.find(row => row.groupId === group.id)! }));
  const family = seed.productionArea === "cubuk-filtre" ? "cubuk-filtre" : "piston";
  const products = seed.products.filter(product => resolvedProductSetupFamily(product.product, product.setupFamily) === family).map(product => product.product);
  const productSet = new Set(products);
  if ([...settings.opening, ...settings.scrap].some(row => !productSet.has(row.product))) throw new Error("Stok ayarlarında seçili aileye ait olmayan ürün var.");
  const issues = new Set<string>();
  const monthly = seed.productionArea === "cubuk-filtre" && Boolean(seed.monthlyCustomerDemand);
  if(monthly) issues.add("Bu tablo fiziksel adettir. 309 ve 315 sağlam parça tahmini teslimat hesabında %96 verimle bir kez hesaplanır; proses geçişlerinde otomatik ıskarta düşülmez.");
  if (seed.planNeedsRecalculation) issues.add("Kayıtlı plan güncel değil. Tahmin, kayıtlı şarjlarla hesaplandı.");
  issues.add("Tahmin sevkiyat öncesi stoktur. Teslimat Planı hazır olma tarihidir; gelecekteki gerçek sevkiyat olarak stoktan düşülmez.");
  const current = new Map<string, number>();
  const add = (map: Map<string, number>, group: string, product: string, quantity: number) => { const key = `${group}:${product}`; map.set(key, (map.get(key) ?? 0) + quantity); };
  const groupForNext = (process?: ProcessKind) => process ? groups.find(group => group.nextProcesses.includes(process))?.id : "warehouse";
  for (const row of settings.opening) {
    if (!productSet.has(row.product)) { issues.add(`${row.product}: stok grubu için ürün ailesi doğrulanmalı.`); continue; }
    add(current, row.groupId, row.product, row.quantity);
  }
  if (settings.opening.some(row => row.quantity > 0)) issues.add(`Ek stok ${settings.openingDate} sayımıdır. Kayıtlı şarjlar hariçtir; kesin proses konumu bilinmediği için otomatik rota / sevkiyat tarihi verilmez.`);
  for (const lot of seed.wipLots ?? []) {
    if (!productSet.has(lot.product) || lot.availableQuantity <= 0 || ["delivered", "scrapped"].includes(lot.stage)) continue;
    if (["on-hold", "unclassified"].includes(lot.stage)) { issues.add(`${lot.product}: ${lot.availableQuantity} adet konumu doğrulanmamış / blokeli; grup toplamına alınmadı.`); continue; }
    const group = groupForNext(lot.nextProcess);
    if (group) add(current, group, lot.product, lot.availableQuantity);
    else issues.add(`${lot.product}: ${lot.nextProcess} stok grubu eşleşmesi yok.`);
  }
  const plan = buildDownstreamProcessPlan(seed, result);
  const events: Array<{ at: number; group: string; product: string; quantity: number }> = [];
  for (const job of plan.jobs) {
    if (!productSet.has(job.product)) continue;
    const master = seed.processMasterData?.products.find(product => product.product === job.product);
    if (!master) { issues.add(`${job.product}: ürün rotası doğrulanmalı.`); continue; }
    const route = effectiveProductRoute(master, job.turningMachineId);
    for (const operation of job.operations) {
      if (operation.actual) continue;
      const index = route.indexOf(operation.process);
      if (index < 0) continue;
      const from = operation.process === "turning" ? undefined : groupForNext(operation.process);
      const to = groupForNext(route[index + 1]);
      if (!to || from === to) continue;
      if (operation.end < now) { issues.add(`${operation.product}: ${operation.resourceId} plan bitişi geçmişte; fiili durum doğrulanmalı.`); continue; }
      if (from) events.push({ at: operation.end, group: from, product: operation.product, quantity: -Math.ceil(operation.quantity * (1 + (monthly ? 0 : processStockScrap(settings, seed.productionArea, from, operation.product)) / 100) - 1e-8) });
      events.push({ at: operation.end, group: to, product: operation.product, quantity: operation.quantity });
    }
    for (const issue of job.readinessIssues ?? []) issues.add(`${job.product}: ${issue.message}`);
  }
  for (const warning of plan.warnings) if (warning.code !== "flow-target") issues.add(warning.message);
  const day = Math.floor(now), weekday = excelSerialToDate(day).getUTCDay();
  const saturday = day + (6 - weekday + 7) % 7;
  const weeks = Array.from({ length: weekCount }, (_, i) => {
    const close = saturday + i * 7 + 1; // Exclusive Sunday 00:00; Saturday is fully included.
    const balances = new Map(current);
    for (const event of events) if (event.at < close) add(balances, event.group, event.product, event.quantity);
    const endDate = excelSerialToDate(close - 1).toISOString().slice(0, 10);
    return { endDate, groups: groups.map(group => {
      const rows = products.map(product => ({ product, actual: current.get(`${group.id}:${product}`) ?? 0, projected: balances.get(`${group.id}:${product}`) ?? 0, scrapPercent: monthly ? 0 : processStockScrap(settings, seed.productionArea, group.id, product) }));
      const projected = rows.reduce((sum, row) => sum + row.projected, 0);
      return { ...group, rows, actual: rows.reduce((sum, row) => sum + row.actual, 0), projected, shortage: Math.max(0, group.min - projected), excess: Math.max(0, projected - group.max) };
    }) };
  });
  return { weeks, issues: [...issues], settings };
}

