import type { PlanningSeed } from "./planning";
import type { ProcessKind } from "./process-master-data";

export type WaitProcess = "turning" | "drilling" | "deburring" | "gkm";
export type ProcessWaitSettings = Record<WaitProcess, { enabled: boolean; workdays: number }>;
export const WAIT_PROCESSES: WaitProcess[] = ["turning", "drilling", "deburring", "gkm"];

export function defaultProcessWaitSettings(): ProcessWaitSettings {
  return Object.fromEntries(WAIT_PROCESSES.map(process => [process, { enabled: false, workdays: 0 }])) as ProcessWaitSettings;
}

export function validateProcessWaitSettings(value: unknown): ProcessWaitSettings {
  const error = () => { throw new Error("Bekleme süreleri 0–365 tam iş günü olmalı. Her proses için bekleme seçimi gereklidir."); };
  if (!value || typeof value !== "object" || Array.isArray(value)) return error();
  const settings = value as ProcessWaitSettings;
  if (Object.keys(settings).length !== WAIT_PROCESSES.length) return error();
  for (const process of WAIT_PROCESSES) {
    const item = settings[process];
    if (!item || typeof item.enabled !== "boolean" || !Number.isInteger(item.workdays) || item.workdays < 0 || item.workdays > 365) return error();
  }
  return structuredClone(settings);
}

/** Wait after the completed process. Zero keeps its exact end instant. */
export function processWaitWorkdays(seed: Pick<PlanningSeed, "processWaitSettings">, process: ProcessKind): number {
  const item = seed.processWaitSettings?.[process as WaitProcess];
  return item?.enabled ? item.workdays : 0;
}

