import type { PlanningSeed } from "./planning";

function copy<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

/** Saved scenarios are planning alternatives, not production backups. */
export function scenarioSeedWithoutProductionArchive(seed: PlanningSeed): PlanningSeed {
  const scenario = copy(seed);
  scenario.productionHistory = [];
  return scenario;
}

/** Apply old planning inputs without replacing the live production archive. */
export function mergeWithLiveProductionArchive(candidate: PlanningSeed, live: PlanningSeed): PlanningSeed {
  const merged = copy(candidate);
  merged.productionHistory = copy(live.productionHistory ?? []);
  return merged;
}

export function productionArchiveChanged(left: PlanningSeed, right: PlanningSeed): boolean {
  return JSON.stringify(left.productionHistory ?? []) !== JSON.stringify(right.productionHistory ?? []);
}

