frontend/lib/production-cancellation.ts.source:
import {
  completeMachineCurrentJob,
  excelSerialToDate,
  scenarioResultFromBatches,
  type PlanningSeed,
  type ProductionHistoryEntry,
  type ScenarioResult,
  withheldReplacementQuantities,
} from "./planning";
export { withheldReplacementQuantities };
import { registerTurningCompletion } from "./wip-ledger";
import { factoryDateTimeToIso, factoryNowSerial } from "./factory-time";
import { finishProductionInterruptions, isProtectedProductionRemainder } from "./production-interruptions";

/**
 * Explicit cancellation of unmade Torna production (Kalan üretimi iptal et).
 * Example: 1,500 assigned, 500 made, 1,000 cancelled. The 500 real pieces get
 * normal history/WIP through the shared completion path. The 1,000 create no
 * stock, history or WIP. Customer demand is not changed. Until a planner
 * reviews the record, new production for the bound orders is withheld up to
 * the cancelled quantity, so the shortage stays visible instead of silently
 * creating replacement production.
 */
export type ProductionCancellationReviewStatus = "pending" | "replacement-approved" | "replacement-declined";
export type ProductionCancellation = {
  id: string;
  version: 1;
  product: string;
  process: "turning";
  chargeId: string;
  workOrder: string;
  machineId: string;
  assignedQuantity: number;
  completedQuantity: number;
  cancelledQuantity: number;
  reason: string;
  /** ISO time of the planner's cancellation (factory wall clock converted). */
  cancelledAt: string;
  /** Orders of this product at cancellation time; withholding never reaches other orders. */
  orderIds: string[];
  /** Order quantities at cancellation time; a later reduction lowers the withheld amount. */
  orderQuantities: Record<string, number>;
  /** History entry for the made pieces, when this action recorded them. */
  historyEntryId?: string;
  /** Set by the server from the authenticated user. */
  recordedBy?: string;
  recordedById?: string;
  review: { status: ProductionCancellationReviewStatus; reviewedAt?: string; reviewedBy?: string; reviewedById?: string; note?: string };
};

export type CancellableRemainder = {
  kind: "current" | "remainder";
  machineId: string;
  chargeId: string;
  product: string;
  workOrder: string;
  /** Open assigned quantity in this record. */
  assignedQuantity: number;
  /** Pieces already recorded by earlier partial outputs (information only). */
  previouslyProduced: number;
  /** Current job: planner enters made pieces. Remainder: the whole remainder is cancelled. */
  requiresCompletedQuantity: boolean;
  start: number;
  signature: string;
};

export type CancelRemainingInput = {
  machineId: string;
  chargeId: string;
  completedQuantity: number;
  cancelledQuantity: number;
  reason: string;
  /** Factory serial of the cancellation (and of completion of the made pieces). */
  cancelledAt: number;
  expectedSignature: string;
};

const MAX_CLOSED = 200;
const code = (value: string) => value.trim().toUpperCase();
const clone = <T,>(value: T): T => structuredClone(value);

function producedBefore(seed: PlanningSeed, chargeId: string): number {
  return (seed.productionInterruptions ?? [])
    .filter(item => item.process === "turning" && item.chargeId === chargeId && isProtectedProductionRemainder(item))
    .reduce((sum, item) => sum + Math.max(0, item.producedQuantity), 0);
}

/** Torna current jobs and protected Torna remainders that can be cancelled. */
export function cancellableRemainders(seed: PlanningSeed, result: Pick<ScenarioResult, "batches">): CancellableRemainder[] {
  const rows: CancellableRemainder[] = [];
  for (const machine of seed.machines) {
    const current = machine.currentJob;
    if (!current.product || current.quantity <= 0) continue;
    const chargeId = current.batchId ?? `current:${machine.id}`;
    rows.push({
      kind: "current", machineId: machine.id, chargeId, product: current.product, workOrder: current.workOrder,
      assignedQuantity: current.quantity, previouslyProduced: producedBefore(seed, chargeId), requiresCompletedQuantity: true, start: current.start,
      signature: JSON.stringify(["current", machine.id, chargeId, current.product, current.workOrder, current.quantity, current.remainingQuantity ?? current.quantity, current.remainingAsOf ?? null, current.start]),
    });
  }
  const open = new Map((seed.productionInterruptions ?? [])
    .filter(item => item.process === "turning" && isProtectedProductionRemainder(item) && !item.completedAt)
    .map(item => [item.chargeId, item]));
  for (const batch of result.batches.filter(item => item.status === "planned" && open.has(item.id))) {
    if (seed.machines.some(machine => machine.currentJob.batchId === batch.id && machine.currentJob.quantity > 0)) continue;
    rows.push({
      kind: "remainder", machineId: batch.machineId, chargeId: batch.id, product: batch.product, workOrder: batch.workOrder?.trim() ?? "",
      assignedQuantity: batch.quantity, previouslyProduced: producedBefore(seed, batch.id), requiresCompletedQuantity: false, start: batch.start,
      signature: JSON.stringify(["remainder", batch.machineId, batch.id, batch.product, batch.workOrder ?? "", batch.quantity]),
    });
  }
  return rows;
}

/** Record the cancellation atomically. Throws without mutating the input. */
export function cancelRemainingProduction(seed: PlanningSeed, result: ScenarioResult, input: CancelRemainingInput, now = new Date()): { seed: PlanningSeed; result: ScenarioResult; cancellation: ProductionCancellation; archived?: ProductionHistoryEntry } {
  const row = cancellableRemainders(seed, result).find(item => item.machineId === input.machineId && item.chargeId === input.chargeId);
  if (!row) throw new Error("İptal edilecek Torna kalan üretimi bulunamadı. Kayıt değiştiyse pencereyi yeniden açın.");
  if (row.signature !== input.expectedSignature) throw new Error("Mevcut iş değişti; iptal bilgisini yeniden kontrol edin.");
  const reason = input.reason?.trim() ?? "";
  if (!reason) throw new Error("İptal nedeni zorunludur.");
  if (!Number.isSafeInteger(input.completedQuantity) || input.completedQuantity < 0) throw new Error("Üretilen adet sıfır veya pozitif tam sayı olmalıdır.");
  if (!Number.isSafeInteger(input.cancelledQuantity) || input.cancelledQuantity <= 0) throw new Error("İptal edilen adet pozitif tam sayı olmalıdır.");
  if (input.completedQuantity + input.cancelledQuantity !== row.assignedQuantity) throw new Error(`Üretilen + iptal edilen adet ${row.assignedQuantity} olmalıdır.`);
  if (!row.requiresCompletedQuantity && input.completedQuantity !== 0) throw new Error("Yarım kalan şarjda yeni üretim önce Mevcut işi değiştir veya tamamlama ile kaydedilir; iptal yalnız kalan adedi kapsar.");
  const nowSerial = factoryNowSerial(now);
  if (!Number.isFinite(input.cancelledAt) || input.cancelledAt < row.start - 1e-8) throw new Error("İptal zamanı üretim başlangıcından önce olamaz.");
  if (input.cancelledAt > nowSerial + 1 / 1440) throw new Error("İptal zamanı gelecekte olamaz.");

  let nextSeed: PlanningSeed;
  let nextResult: ScenarioResult;
  let archived: ProductionHistoryEntry | undefined;
  if (row.kind === "current" && input.completedQuantity === 0) {
    // Nothing was made: no history, WIP or queue record; the machine becomes free.
    nextSeed = clone(seed);
    const machine = nextSeed.machines.find(item => item.id === row.machineId)!;
    machine.currentJob = { workOrder: "", product: "", quantity: 0, originalQuantity: 0, remainingQuantity: 0, start: input.cancelledAt, end: input.cancelledAt, dailyRate: 0, diameter: "" };
    machine.availableStart = input.cancelledAt;
    machine.operationalAvailableStart = input.cancelledAt;
    nextResult = scenarioResultFromBatches(nextSeed, result.batches.map(batch => ({ ...batch })));
  } else if (row.kind === "current") {
    // Complete exactly the made pieces through the shared path; the unmade
    // remainder never becomes a queue record, stock or history.
    const working = clone(seed);
    const machine = working.machines.find(item => item.id === row.machineId)!;
    machine.currentJob.quantity = input.completedQuantity;
    machine.currentJob.originalQuantity = input.completedQuantity;
    machine.currentJob.remainingQuantity = 0;
    const completed = completeMachineCurrentJob(working, result, row.machineId, input.cancelledAt);
    nextSeed = completed.seed;
    nextResult = completed.result;
    archived = completed.archived;
    archived.statusChangeReason = `Kalan üretim iptal edildi: ${row.assignedQuantity} atanmış, ${input.completedQuantity} üretildi, ${input.cancelledQuantity} iptal. Neden: ${reason}`;
    // Same WIP registration as normal Torna completion; only made pieces enter stock.
    registerTurningCompletion(nextSeed, archived);
  } else {
    nextSeed = clone(seed);
    const batches = result.batches.filter(batch => batch.id !== row.chargeId).map(batch => ({ ...batch }));
    // Other queue dates stay recorded; the plan is marked for recalculation.
    nextResult = { ...scenarioResultFromBatches(nextSeed, batches), state: result.state, planRun: result.planRun };
  }
  finishProductionInterruptions(nextSeed, row.chargeId, "turning", input.cancelledAt);
  const orders = nextSeed.orders.filter(order => code(order.product) === code(row.product));
  const cancellation: ProductionCancellation = {
    id: `cancellation-${crypto.randomUUID()}`,
    version: 1,
    product: row.product,
    process: "turning",
    chargeId: row.chargeId,
    workOrder: row.workOrder,
    machineId: row.machineId,
    assignedQuantity: row.assignedQuantity,
    completedQuantity: input.completedQuantity,
    cancelledQuantity: input.cancelledQuantity,
    reason,
    cancelledAt: factoryDateTimeToIso(excelSerialToDate(input.cancelledAt).toISOString().slice(0, 16)),
    orderIds: orders.map(order => order.id),
    orderQuantities: Object.fromEntries(orders.map(order => [order.id, order.quantity])),
    historyEntryId: archived?.id,
    review: { status: "pending" },
  };
  nextSeed.productionCancellations = boundedCancellations([...(nextSeed.productionCancellations ?? []), cancellation]);
  nextSeed.manualBatches = nextResult.batches.map(batch => ({ ...batch }));
  nextSeed.planNeedsRecalculation = true;
  nextSeed.lastAutomaticPlan = undefined;
  nextSeed.planRunSequence = undefined;
  return { seed: nextSeed, result: nextResult, cancellation, archived };
}

/** Pending and declined records still hold production and are never trimmed; only approved history is bounded. */
export function boundedCancellations(records: ProductionCancellation[]): ProductionCancellation[] {
  const holding = records.filter(item => item.review.status !== "replacement-approved");
  const approved = records.filter(item => item.review.status === "replacement-approved").slice(-MAX_CLOSED);
  return [...holding, ...approved];
}

/** Planner review. The server replaces reviewer identity and time. */
export function reviewProductionCancellation(seed: PlanningSeed, id: string, decision: Exclude<ProductionCancellationReviewStatus, "pending">, note = "", now = new Date()): PlanningSeed {
  const next = clone(seed);
  const record = next.productionCancellations?.find(item => item.id === id);
  if (!record) throw new Error("İptal kaydı bulunamadı.");
  if (record.review.status !== "pending") throw new Error("Bu iptal kaydı zaten incelendi.");
  if (decision !== "replacement-approved" && decision !== "replacement-declined") throw new Error("İnceleme kararı geçersiz.");
  record.review = { status: decision, reviewedAt: now.toISOString(), ...(note.trim() ? { note: note.trim().slice(0, 500) } : {}) };
  next.productionCancellations = boundedCancellations(next.productionCancellations!);
  next.planNeedsRecalculation = true;
  next.lastAutomaticPlan = undefined;
  next.planRunSequence = undefined;
  return next;
}

/** Pieces withheld from new automatic production for one product (see planning.ts). */
export function withheldReplacementQuantity(seed: PlanningSeed, product: string): number {
  return withheldReplacementQuantities(seed).get(code(product)) ?? 0;
}

export function pendingCancellationReviews(seed: PlanningSeed): ProductionCancellation[] {
  return (seed.productionCancellations ?? []).filter(item => item.review.status === "pending");
}

