import type { PlannedBatch, PlanningSeed, ProductionProcess, WipLot } from './planning';

export type ProductionInterruptionInput = { kind?: "partial-completion" | "interruption"; expectedSignature?: string; produced: boolean; quantity?: number; reason?: string };
export type ProductionInterruption = {
  /** Missing kind is a legacy interruption requiring manual review. */
  kind?: "partial-completion" | "interruption";
  id: string;
  chargeId: string;
  process: ProductionProcess;
  resourceId: string;
  product: string;
  workOrder: string;
  producedQuantity: number;
  remainingQuantity: number;
  reason: string;
  occurredAt: number;
  resumedAt?: number;
  completedAt?: number;
  /** Recovery record for the physical remainder, independent of disposable proposals. */
  turningBatch?: PlannedBatch;
};

export function validateProductionInterruption(input: ProductionInterruptionInput, quantity: number, startedAt: number, occurredAt: number): number {
  if (!input || typeof input.produced !== 'boolean') throw new Error('Üretim oldu mu? Evet veya Hayır seçin.');
  if (!Number.isFinite(occurredAt) || occurredAt < startedAt) throw new Error('Ara verme tarihi üretim başlangıcından önce olamaz.');
  if (!Number.isInteger(quantity) || quantity <= 0) throw new Error('Mevcut işin adedi geçersiz.');
  if (input.kind && !['partial-completion', 'interruption'].includes(input.kind)) throw new Error('Üretim aktarım seçimi geçersiz.');
  if (!input.produced) return 0;
  if (!Number.isInteger(input.quantity) || input.quantity! <= 0 || input.quantity! >= quantity) throw new Error('Üretilen adet sıfırdan büyük ve mevcut iş adedinden küçük olmalıdır. İşin tamamı üretildiyse prosesi bitirin.');
  if (!input.reason?.trim()) throw new Error(input.kind === 'partial-completion' ? 'İş değiştirme nedeni zorunludur.' : 'İşe ara verme nedeni zorunludur.');
  if (input.reason.trim().length > 2000) throw new Error('İşe ara verme nedeni en fazla 2000 karakter olabilir.');
  return input.quantity!;
}

export function activeLotInterruptions(seed: PlanningSeed, lot: WipLot | undefined): ProductionInterruption[] {
  return (seed.productionInterruptions ?? []).filter(item => isProductionInterruption(item) && !item.completedAt && lot?.interruptionIds?.includes(item.id));
}

/** Explicit zero output means a mistaken start. Unknown legacy values stay conservative. */
export function isProductionInterruption(item: ProductionInterruption): boolean {
  return item.producedQuantity !== 0 && item.kind !== "partial-completion";
}

/** Any recorded output makes the unfinished remainder a durable production fact. */
export function isProtectedProductionRemainder(item: ProductionInterruption): boolean {
  return item.producedQuantity !== 0;
}

/** Ignore only proven zero-output markers; never release a different real partial output. */
export function hasActiveProductionInterruption(seed: PlanningSeed, chargeId?: string, interruptionId?: string): boolean {
  const records = seed.productionInterruptions ?? [];
  if (records.some(item => isProductionInterruption(item) && !item.completedAt && (
    Boolean(chargeId && item.chargeId === chargeId) || item.id === interruptionId
  ))) return true;
  return Boolean(interruptionId && !records.some(item => item.id === interruptionId));
}

/** Zero-output legacy markers are ordinary queued work; missing records stay conservative. */
export function hasProtectedProductionRemainder(seed: PlanningSeed, chargeId?: string, interruptionId?: string): boolean {
  const records = seed.productionInterruptions ?? [];
  if (records.some(item => isProtectedProductionRemainder(item) && (
    Boolean(chargeId && item.chargeId === chargeId) || item.id === interruptionId
  ))) return true;
  return Boolean(interruptionId && !records.some(item => item.id === interruptionId));
}

export function finishProductionInterruptions(seed: PlanningSeed, chargeId: string | undefined, process: ProductionProcess, completedAt: number): void {
  if (!chargeId) return;
  for (const item of seed.productionInterruptions ?? []) if (item.chargeId === chargeId && item.process === process && !item.completedAt) item.completedAt = completedAt;
}

/** A lock is a planning choice. Physical records and unknown production markers protect work. */
export function hasRecordedTurningProduction(seed: PlanningSeed, batch: PlannedBatch): boolean {
  const key = (value: string | undefined) => (value ?? '').trim().toUpperCase();
  const sameWork = (record: { product: string; workOrder?: string }) => Boolean(key(batch.workOrder))
    && key(record.workOrder) === key(batch.workOrder) && key(record.product) === key(batch.product);
  const events = (seed.productionInterruptions ?? []).filter(item => item.chargeId === batch.id
    || item.id === batch.interruptionId || (!item.chargeId && sameWork(item)));
  const eventIds = new Set(events.map(item => item.id));
  const linkedEvent = (ids: string[] | undefined) => ids?.some(id => eventIds.has(id)) ?? false;
  if (events.some(item => item.producedQuantity !== 0)) return true;
  if (batch.interruptionId && !events.some(item => item.id === batch.interruptionId)) return true;
  if (events.some(item => item.id === batch.interruptionId && item.chargeId !== batch.id)) return true;
  if (seed.machines.some(machine => machine.currentJob.quantity > 0
    && (machine.currentJob.batchId === batch.id || (!machine.currentJob.batchId && sameWork(machine.currentJob))))) return true;
  if ((seed.productionHistory ?? []).some(item => item.inventoryStatus !== 'voided'
    && item.completedQuantity !== 0 && (item.sourceBatchId === batch.id || ((!item.sourceBatchId || item.sourceBatchId === item.id) && sameWork(item)) || linkedEvent(item.interruptionIds)))) return true;
  if ((seed.wipLots ?? []).some(item => item.sourceBatchId === batch.id || ((!item.sourceBatchId || item.sourceBatchId === item.sourceHistoryEntryId) && sameWork(item)) || linkedEvent(item.interruptionIds))) return true;
  return (seed.processCurrentJobs ?? []).some(item => item.batchId === batch.id || (!item.batchId && sameWork(item)));
}

/** Live interrupted work survives clearing, empty demand, old scenarios and unavailable capacity. */
export function protectedInterruptedBatches(seed: PlanningSeed, batches: PlannedBatch[] = []): PlannedBatch[] {
  const latest = new Map<string, ProductionInterruption>();
  for (const item of seed.productionInterruptions ?? []) if (item.process === 'turning' && isProtectedProductionRemainder(item) && !item.completedAt && item.turningBatch) latest.set(item.chargeId, item);
  return [...latest.values()].filter(item => !seed.machines.some(machine => machine.currentJob.batchId === item.chargeId && machine.currentJob.quantity > 0))
    .map(item => {
      const matches = (batch: PlannedBatch) => batch.id === item.chargeId && batch.interruptionId === item.id && batch.quantity === item.remainingQuantity;
      return {...(batches.find(matches) ?? seed.manualBatches?.find(matches) ?? item.turningBatch!)};
    });
}

export function withInterruptedBatches(seed: PlanningSeed, batches: PlannedBatch[]): PlannedBatch[] {
  const live = protectedInterruptedBatches(seed, batches);
  const known = new Set((seed.productionInterruptions ?? []).filter(item => item.process === 'turning' && isProtectedProductionRemainder(item) && item.turningBatch).map(item => item.chargeId));
  const result = batches.filter(batch => !known.has(batch.id)).map(batch => ({...batch}));
  result.push(...live);
  return result;
}

export function productionSwitchSignature(seed: PlanningSeed, batches: PlannedBatch[]): string {
  return JSON.stringify([seed.machines, seed.processCurrentJobs ?? [], seed.wipLots ?? [], seed.productionInterruptions ?? [], seed.processOperationOverrides ?? [], seed.processMasterData, seed.calendarEvents, seed.products, seed.holidays, seed.setupSettings, batches]);
}

export function assertProductionSwitchSnapshot(seed: PlanningSeed, batches: PlannedBatch[], input: ProductionInterruptionInput): void {
  if (input?.expectedSignature && input.expectedSignature !== productionSwitchSignature(seed, batches)) throw new Error('Mevcut iş veya kuyruk değişti. Pencereyi kapatıp güncel kayıtla yeniden açın.');
}

