import { machineCapacityHoursBetween, type PlanningSeed, type ScenarioResult } from "./planning";
import { initialRawMaterialSettings } from "./raw-material-settings";

export type MaterialDay = { day: number; quantity: number; requiredKg: number; remainingKg: number | null; incomplete: boolean };
export type MaterialProjection = {
  materialCode: string; materialName: string; diameter: string; stockKg: number | null;
  days: MaterialDay[]; exhaustedOn: number | null; shortageOn: number | null;
};

export function rawMaterialCatalog(seed: PlanningSeed) {
  // Identity/diameter only from the supplied Hammadde İhtiyaç template. Its
  // historical yellow stock values must never become current opening balances.
  const referenceMaterials = [
    ["Z170004", "Ø17,2"], ["Z170007", "Ø14,2"], ["Z170008", "Ø19,8"], ["Z170009", "Ø20,7"],
    ["Z170010", "Ø25,5"], ["Z170011", "Ø27"], ["Z170012", "Ø30"], ["Z170016", "Ø23"],
    ["Z170018", "Ø33,5"], ["Z170019", "Ø37"],
  ];
  const catalog = new Map<string, { materialCode: string; materialName: string; diameter: string }>((seed.productionArea === "cubuk-filtre" ? [] : referenceMaterials).map(([materialCode, diameter]) => [materialCode, { materialCode, materialName: "", diameter }]));
  for (const weight of seed.productWeights ?? []) {
    const code = weight.materialCode.trim().toUpperCase();
    if (code) catalog.set(code, { materialCode: code, materialName: weight.materialName,
      diameter: weight.materialName.match(/Ø\s*[\d.,]+/i)?.[0] ?? catalog.get(code)?.diameter ?? "—" });
  }
  for (const stock of seed.rawMaterialSettings?.stocks ?? []) {
    if (!catalog.has(stock.materialCode)) catalog.set(stock.materialCode, { materialCode: stock.materialCode, materialName: "", diameter: "—" });
  }
  return [...catalog.values()].sort((a, b) => a.materialCode.localeCompare(b.materialCode));
}

/** Daily warehouse forecast; never mutates stock or adds downstream processes. */
export function buildRawMaterialConsumption(seed: PlanningSeed, result: ScenarioResult, startDay: number, dayCount: number, today: number) {
  const settings = seed.rawMaterialSettings ?? initialRawMaterialSettings();
  if (!Number.isInteger(startDay) || !Number.isInteger(dayCount) || dayCount < 1 || dayCount > 366) throw new Error("Tüketim dönemi 1–366 gün olmalıdır.");
  const endDay = startDay + dayCount;
  const issues = new Set<string>();
  const materials: MaterialProjection[] = rawMaterialCatalog(seed).map((item) => {
    const stockKg = settings.stocks.find((stock) => stock.materialCode === item.materialCode)?.kg ?? null;
    return { ...item, stockKg, exhaustedOn: null, shortageOn: null,
      days: Array.from({ length: dayCount }, (_, index) => ({ day: startDay + index, quantity: 0, requiredKg: 0, remainingKg: stockKg, incomplete: false })) };
  });
  const byMaterial = new Map(materials.map((row) => [row.materialCode, row]));
  const weights = new Map((seed.productWeights ?? []).map((row) => [row.product, row]));
  let unknownMaterial = false;
  let unplannedCount = 0;
  for (const batch of result.batches) if (batch.status !== "planned") unplannedCount++;
  const jobs = [
    ...seed.machines.filter((machine) => machine.currentJob.product && (machine.currentJob.remainingQuantity ?? machine.currentJob.quantity) > 0)
      .map((machine) => ({ product: machine.currentJob.product, machineId: machine.id,
        quantity: machine.currentJob.remainingQuantity ?? machine.currentJob.quantity,
        start: Math.max(machine.currentJob.start, today), end: machine.currentJob.end,
        setupHours: 0, current: true })),
    ...result.batches.filter((batch) => batch.status === "planned").map((batch) => ({ ...batch, current: false })),
  ];
  for (const job of jobs) {
    const machine = seed.machines.find((item) => item.id === job.machineId);
    if (job.quantity <= 0 || job.start >= endDay) continue;
    const weight = weights.get(job.product.trim().toUpperCase());
    const material = byMaterial.get(weight?.materialCode.trim().toUpperCase() ?? "");
    // Expired current jobs are an unresolved production fact, not zero demand.
    if (!machine || !Number.isFinite(job.start) || !Number.isFinite(job.end) || job.end <= job.start || job.end - job.start > 3660) {
      issues.add(`${job.product} / ${job.machineId}: üretim tarihleri veya tezgâh bilgisi eksik; planı güncelleyin.`);
      if (material) material.days.forEach((day) => { day.incomplete = true; }); else unknownMaterial = true;
      continue;
    }
    if (job.end <= startDay) continue;
    if (!material || !weight?.grams) {
      issues.add(`${job.product}: ${material ? "hammadde ağırlığı" : "hammadde eşleşmesi"} eksik.`);
      if (material) material.days.forEach((day) => { if (day.day >= Math.floor(job.start)) day.incomplete = true; }); else unknownMaterial = true;
      continue;
    }
    // Reuse the planner's actual shift/holiday/maintenance windows. Setup consumes
    // capacity before production and finishOffset is not production time.
    const productionEnd = job.end - (machine.finishOffset ?? 0);
    const setup = Math.max(0, job.setupHours ?? 0);
    const duration = machineCapacityHoursBetween(seed, machine, job.start, productionEnd) - setup;
    if (!Number.isFinite(duration) || duration <= 1e-8) {
      issues.add(`${job.product} / ${job.machineId}: çalışılabilir üretim süresi bulunamadı.`);
      material.days.forEach((day) => { day.incomplete = true; });
      continue;
    }
    let capacity = machineCapacityHoursBetween(seed, machine, job.start, Math.min(startDay, productionEnd));
    const producedAtCapacity = () => Math.min(job.quantity, Math.floor(job.quantity * Math.min(1, Math.max(0, capacity - setup) / duration) + 1e-6));
    let previous = producedAtCapacity();
    for (const day of material.days) {
      capacity += machineCapacityHoursBetween(seed, machine, Math.max(job.start, day.day), Math.min(day.day + 1, productionEnd));
      const produced = producedAtCapacity();
      const quantity = Math.max(0, produced - previous);
      previous = produced;
      day.quantity += quantity;
      day.requiredKg += quantity * weight.grams * (1 + (seed.productionArea === "cubuk-filtre" ? (seed.products.find(p => p.product === job.product)?.setupScrapPercent ?? 0) + (seed.products.find(p => p.product === job.product)?.productionScrapPercent ?? 0) : settings.scrapPercent) / 100) / 1000;
    }
  }
  for (const material of materials) {
    let balance = material.stockKg;
    let incomplete = unknownMaterial;
    for (const day of material.days) {
      incomplete ||= day.incomplete;
      day.incomplete = incomplete;
      if (balance !== null) balance -= day.requiredKg;
      if (balance !== null && Math.abs(balance) < 1e-8) balance = 0;
      day.remainingKg = incomplete ? null : balance;
      if (!incomplete && balance !== null) {
        if (balance <= 0 && material.exhaustedOn === null) material.exhaustedOn = day.day;
        if (balance < 0 && material.shortageOn === null) material.shortageOn = day.day;
      }
    }
  }
  return { materials, issues: [...issues], unplannedCount, unknownMaterial };
}

