import { hasProtectedProductionRemainder, isProtectedProductionRemainder, withInterruptedBatches } from "./production-interruptions";
import type { PlannedBatch, PlanningSeed } from './planning';

/** Only physical Torna identity is compared. Product codes alone never identify a charge. */
export function reconcileTurningQueue(seed: PlanningSeed, batches: PlannedBatch[]): PlannedBatch[] {
  const inspected = inspectTurningQueue(seed, batches);
  if (inspected.conflicts.length) throw new Error(inspected.conflicts[0].message);
  return inspected.reconciledBatches;
}

function recoveredTurningBatches(seed: PlanningSeed): PlannedBatch[] {
  const original = seed.manualBatches ?? [];
  const positions = new Map(original.map((batch, index) => [batch.id, index]));
  return withInterruptedBatches(seed, original).sort((a, b) => (positions.get(a.id) ?? original.length) - (positions.get(b.id) ?? original.length));
}

/** Clone at restore boundaries; never alter current work, archive, dates or locks. */
export function reconcileTurningSeed(seed: PlanningSeed): PlanningSeed {
  const original = seed.manualBatches ?? [];
  const batches = reconcileTurningQueue(seed, recoveredTurningBatches(seed));
  if (JSON.stringify(batches) === JSON.stringify(original)) return seed;
  return { ...seed, manualBatches: batches, lastAutomaticPlan: undefined, planNeedsRecalculation: true };
}

export function turningQueueIdentityIssue(seed: PlanningSeed): string | null {
  try { reconcileTurningQueue(seed, seed.manualBatches ?? []); return null; }
  catch (error) { return error instanceof Error ? error.message : 'Şarj kimliği kontrol edilemedi.'; }
}

export type TurningIdentityRecord = { kind: "current" | "history" | "wip" | "queue"; id: string; machineId: string; product: string; workOrder: string; quantity: number; status?: string };
export type TurningIdentityConflict = { batchId: string; machineId: string; product: string; workOrder: string; message: string; reason: "duplicate-queue-id" | "product-mismatch" | "legacy-ambiguous"; records: TurningIdentityRecord[] };
export type TurningIdentityScope = { products: string[]; machineIds: string[]; batchIds: string[]; lotIds: string[]; historyIds: string[] };
export type TurningIdentityRepair = { batchId: string; action: "work-order" | "remove-duplicate"; workOrder?: string; reason: string; confirmedDuplicate?: boolean };
export type TurningIdentityRepairInput = TurningIdentityRepair;
const identityKey = (value: unknown) => String(value ?? "").trim().toUpperCase();
const identityMessage = (batch: PlannedBatch) => `${batch.machineId} · ${batch.workOrder || batch.product}: mevcut üretim/arşiv ile kuyruktaki şarj kimliği belirsiz. İş emri ve şarj kayıtlarını kontrol edin; işlem uygulanmadı.`;

/** Display evidence without guessing whether two historical records are one physical charge. */
export function inspectTurningQueue(seed: PlanningSeed, batches = seed.manualBatches ?? []): { conflicts: TurningIdentityConflict[]; reconciledBatches: PlannedBatch[] } {
  const records: Array<TurningIdentityRecord & { chargeId?: string }> = [
    ...seed.machines.filter(m => m.currentJob.quantity > 0).map(m => ({kind: "current" as const, id: m.id, chargeId: m.currentJob.batchId, machineId: m.id, product: m.currentJob.product, workOrder: m.currentJob.workOrder, quantity: m.currentJob.originalQuantity ?? m.currentJob.quantity})),
    ...(seed.productionHistory ?? []).filter(h => (!h.process || h.process === "turning") && h.inventoryStatus !== "voided" && !h.interruptionIds?.length).map(h => ({kind: "history" as const, id: h.id, chargeId: h.sourceBatchId === h.id ? undefined : h.sourceBatchId, machineId: h.machineId, product: h.product, workOrder: h.workOrder, quantity: h.originalQuantity, status: h.inventoryStatus})),
    ...(seed.wipLots ?? []).filter(l => l.sourceBatchId && l.sourceBatchId !== l.sourceHistoryEntryId && !seed.productionHistory?.some(h => h.id === l.sourceHistoryEntryId && h.inventoryStatus === "voided")).map(l => ({kind: "wip" as const, id: l.id, chargeId: l.sourceBatchId, machineId: "", product: l.product, workOrder: l.workOrder, quantity: l.originalQuantity, status: l.stage})),
  ];
  const conflicts: TurningIdentityConflict[] = [];
  const reconciledBatches = batches.filter(batch => {
    const duplicates = batches.filter(b => b.id === batch.id);
    const exact = records.filter(r => r.chargeId && r.chargeId === batch.id);
    const legacy = records.filter(r => !r.chargeId && identityKey(r.workOrder) && identityKey(r.workOrder) === identityKey(batch.workOrder) && identityKey(r.product) === identityKey(batch.product));
    let reason: TurningIdentityConflict["reason"] | undefined;
    let evidence: TurningIdentityRecord[] = [];
    if (duplicates.length > 1) { reason = "duplicate-queue-id"; evidence = duplicates.map(b => ({kind: "queue", id: b.id, machineId: b.machineId, product: b.product, workOrder: b.workOrder ?? "", quantity: b.quantity})); }
    else if (exact.length) { if (exact.some(r => identityKey(r.product) !== identityKey(batch.product))) { reason = "product-mismatch"; evidence = exact; } else return false; }
    else if (!hasProtectedProductionRemainder(seed, batch.id, batch.interruptionId) && legacy.length) {
      const candidates = batches.filter(b => identityKey(b.workOrder) === identityKey(batch.workOrder) && identityKey(b.product) === identityKey(batch.product));
      if (legacy.length !== 1 || candidates.length !== 1 || legacy[0].quantity !== batch.quantity || legacy[0].machineId !== batch.machineId) { reason = "legacy-ambiguous"; evidence = legacy; } else return false;
    }
    if (reason && reason !== "duplicate-queue-id") evidence.push({kind:"queue",id:batch.id,machineId:batch.machineId,product:batch.product,workOrder:batch.workOrder ?? "",quantity:batch.quantity,status:batch.locked ? "locked" : batch.status});
    if (reason) conflicts.push({batchId: batch.id, machineId: batch.machineId, product: batch.product, workOrder: batch.workOrder ?? "", message: identityMessage(batch), reason, records: evidence.map(r => ({kind:r.kind,id:r.id,machineId:r.machineId,product:r.product,workOrder:r.workOrder,quantity:r.quantity,...(r.status ? {status:r.status}: {})}))});
    return true;
  });
  return {conflicts, reconciledBatches};
}

/** Conservative closure: ambiguous products and machines, then all linked physical descendants. */
export function turningIdentityScope(seed: PlanningSeed, batches = seed.manualBatches ?? []): TurningIdentityScope {
  const conflicts = inspectTurningQueue(seed, batches).conflicts;
  const products = new Set(conflicts.flatMap(c => [c.product, ...c.records.map(r => r.product)]).map(identityKey).filter(Boolean));
  const machineIds = new Set(conflicts.flatMap(c => [c.machineId, ...c.records.map(r => r.machineId)]).filter(Boolean));
  const batchIds = new Set(conflicts.map(c => c.batchId)); const lotIds = new Set<string>(); const historyIds = new Set<string>();
  const add = (set: Set<string>, value: string | undefined) => { if (value) set.add(value); };
  const related = (product: string | undefined) => products.has(identityKey(product));
  let size = -1;
  while (size !== machineIds.size + batchIds.size + lotIds.size + historyIds.size) {
    size = machineIds.size + batchIds.size + lotIds.size + historyIds.size;
    for (const b of batches) if (related(b.product) || batchIds.has(b.id) || machineIds.has(b.machineId)) { add(machineIds, b.machineId); add(batchIds, b.id); }
    for (const m of seed.machines) if (related(m.currentJob.product) || batchIds.has(m.currentJob.batchId ?? "") || machineIds.has(m.id)) { add(machineIds, m.id); add(batchIds, m.currentJob.batchId); add(batchIds, `current:${m.id}`); }
    for (const h of seed.productionHistory ?? []) if (related(h.product) || historyIds.has(h.id) || historyIds.has(h.sourceEntryId ?? "") || batchIds.has(h.sourceBatchId ?? "") || h.wipAllocations?.some(a => lotIds.has(a.lotId))) { add(historyIds, h.id); add(historyIds, h.sourceEntryId); add(batchIds, h.sourceBatchId); for (const a of h.wipAllocations ?? []) add(lotIds, a.lotId); }
    for (const l of seed.wipLots ?? []) if (related(l.product) || lotIds.has(l.id) || lotIds.has(l.parentLotId ?? "") || historyIds.has(l.sourceHistoryEntryId) || batchIds.has(l.sourceBatchId ?? "")) { add(lotIds, l.id); add(lotIds, l.parentLotId); add(historyIds, l.sourceHistoryEntryId); add(batchIds, l.sourceBatchId); }
    for (const j of seed.processCurrentJobs ?? []) if (related(j.product) || batchIds.has(j.batchId) || lotIds.has(j.wipLotId)) { add(batchIds, j.batchId); add(lotIds, j.wipLotId); }
    for (const i of seed.productionInterruptions ?? []) if (related(i.product) || batchIds.has(i.chargeId)) { add(batchIds, i.chargeId); if (i.process === "turning") add(machineIds, i.resourceId); }
  }
  return {products:[...products].sort(), machineIds:[...machineIds].sort(), batchIds:[...batchIds].sort(), lotIds:[...lotIds].sort(), historyIds:[...historyIds].sort()};
}

// Canonical object keys, ordered arrays: repeated queue IDs never collapse into a map.
function structural(value: unknown): string {
  return JSON.stringify(value, (_key, item) => item && typeof item === "object" && !Array.isArray(item) ? Object.fromEntries(Object.keys(item).sort().filter(k => item[k] !== undefined).map(k => [k, item[k]])) : item);
}
const frozenConfiguration = ["products", "preferences", "restrictions", "holidays", "calendarEvents", "setupSettings", "processWaitSettings", "processMasterData", "savedBatches", "activePlanningScope", "customerDemand", "openingStock", "demandTargets", "orderImport", "orderImportGrossOrders", "customerOrderOverrides"] as const;
function protectedIdentitySnapshot(seed: PlanningSeed, scope: TurningIdentityScope) {
  const p = (value: string | undefined) => scope.products.includes(identityKey(value));
  const b = (value: string | undefined) => Boolean(value && scope.batchIds.includes(value));
  const l = (value: string | undefined) => Boolean(value && scope.lotIds.includes(value));
  const h = (value: string | undefined) => Boolean(value && scope.historyIds.includes(value));
  return {
    configuration: Object.fromEntries(frozenConfiguration.map(k => [k, seed[k] ?? null])),
    machines: seed.machines.filter(m => scope.machineIds.includes(m.id) || p(m.currentJob.product) || b(m.currentJob.batchId)),
    manualBatches: (seed.manualBatches ?? []).filter(r => p(r.product) || b(r.id) || scope.machineIds.includes(r.machineId)),
    productionHistory: (seed.productionHistory ?? []).filter(r => p(r.product) || h(r.id) || h(r.sourceEntryId) || b(r.sourceBatchId) || r.wipAllocations?.some(a => l(a.lotId))),
    wipLots: (seed.wipLots ?? []).filter(r => p(r.product) || l(r.id) || l(r.parentLotId) || h(r.sourceHistoryEntryId) || b(r.sourceBatchId)),
    wipMovements: (seed.wipMovements ?? []).filter(r => l(r.lotId)),
    productionInterruptions: (seed.productionInterruptions ?? []).filter(r => p(r.product) || b(r.chargeId) || r.process === "turning" && scope.machineIds.includes(r.resourceId)),
    processCurrentJobs: (seed.processCurrentJobs ?? []).filter(r => p(r.product) || b(r.batchId) || l(r.wipLotId)),
    processOperationOverrides: (seed.processOperationOverrides ?? []).filter(r => b(r.batchId) || l(r.batchId)),
    orders: seed.orders.filter(r => p(r.product)),
  };
}
function assertNoReconciledDuplicates(seed: PlanningSeed) {
  const checked = reconcileTurningSeed(seed);
  if (structural(checked.manualBatches ?? []) !== structural(seed.manualBatches ?? [])) throw new Error("Mevcut veya tamamlanmış şarj kuyrukta tekrar bulunuyor. Ortak veriyi yükleyin.");
}

/** Unrelated operations may proceed; only a reviewed repair may alter conflict evidence. */
export function assertTurningIdentityTransition(before: PlanningSeed, next: PlanningSeed): void {
  const previous = inspectTurningQueue(before).conflicts;
  if (!previous.length) { assertNoReconciledDuplicates(next); return; }
  const scope = turningIdentityScope(before);
  if (structural(protectedIdentitySnapshot(before, scope)) !== structural(protectedIdentitySnapshot(next, scope))) throw new Error("Bu işlem inceleme bekleyen şarjı veya bağlı kayıtlarını değiştiriyor. Önce İncele ve düzelt ile şarj kaydını doğrulayın.");
  if (structural(recoveredTurningBatches(next)) !== structural(next.manualBatches ?? [])) throw new Error("Yarım kalan şarjın kuyruk kaydı korunmalıdır. Ortak veriyi yükleyin.");
  const inspected = inspectTurningQueue(next);
  if (structural(previous) !== structural(inspected.conflicts)) throw new Error("İşlem yeni bir şarj kimliği çakışması oluşturuyor. İncele ve düzelt ile kayıtları doğrulayın.");
  if (inspected.reconciledBatches.length !== (next.manualBatches ?? []).length) throw new Error("Mevcut veya tamamlanmış şarj kuyrukta tekrar bulunuyor. Ortak veriyi yükleyin.");
}

/** A narrowly constrained human correction, never an archive/WIP deletion or quantity mutation. */
export function repairTurningIdentity(seed: PlanningSeed, input: TurningIdentityRepair): PlanningSeed {
  if (!input.reason?.trim() || input.reason.trim().length > 2000) throw new Error("Düzeltme nedeni zorunludur ve en fazla 2000 karakter olabilir.");
  const rows = (seed.manualBatches ?? []).filter(b => b.id === input.batchId);
  const before = inspectTurningQueue(seed);
  const target = before.conflicts.find(c => c.batchId === input.batchId);
  if (rows.length !== 1 || !target || target.reason === "duplicate-queue-id") throw new Error("Şarj tek bir kuyruk kaydı olarak doğrulanamıyor. Kayıtları sistem yöneticisiyle inceleyin.");
  const row = rows[0];
  if (hasProtectedProductionRemainder(seed, row.id, row.interruptionId) || (seed.productionInterruptions ?? []).some(i => i.chargeId === row.id && isProtectedProductionRemainder(i)) || seed.machines.some(m => m.currentJob.batchId === row.id && m.currentJob.quantity > 0) || (seed.wipLots ?? []).some(l => l.sourceBatchId === row.id) || (seed.processCurrentJobs ?? []).some(j => j.batchId === row.id) || (seed.processOperationOverrides ?? []).some(o => o.batchId === row.id) || (seed.productionHistory ?? []).some(h => h.sourceBatchId === row.id && h.sourceBatchId !== h.id)) throw new Error("Başlamış, yarım kalmış veya başka proseslere bağlı şarj bu pencereden düzeltilemez.");
  const next = structuredClone(seed);
  if (input.action === "work-order") {
    const workOrder = input.workOrder?.trim();
    if (!workOrder || workOrder.length > 100 || identityKey(workOrder) === identityKey(row.workOrder)) throw new Error("Farklı ve geçerli bir iş emri girin.");
    next.manualBatches!.find(b => b.id === row.id)!.workOrder = workOrder;
  } else if (input.action === "remove-duplicate") {
    if (input.confirmedDuplicate !== true || !target.records.some(r => (r.kind === "current" || r.kind === "history") && identityKey(r.product) === identityKey(row.product) && identityKey(r.workOrder) === identityKey(row.workOrder))) throw new Error("Mevcut üretim/arşiv kaydıyla aynı fiziksel iş olduğunu doğrulayın.");
    next.manualBatches = next.manualBatches!.filter(b => b.id !== row.id);
  } else throw new Error("Geçersiz şarj düzeltmesi.");
  const after = inspectTurningQueue(next);
  const remaining = before.conflicts.filter(c => c.batchId !== row.id);
  if (structural(after.conflicts) !== structural(remaining) || after.reconciledBatches.length !== (next.manualBatches ?? []).length) throw new Error("Bu düzeltme çakışmayı güvenle çözmüyor veya başka şarjı etkiliyor. Kayıtları yeniden inceleyin.");
  next.planNeedsRecalculation = true;
  next.lastAutomaticPlan = undefined;
  return next;
}

