import { readFileSync } from "node:fs";
import { migratePlanningSeed } from "../lib/planning-state";
import type { PlannedBatch, PlanningSeed } from "../lib/planning";
import { buildDownstreamProcessPlan } from "../lib/process-planning";

/**
 * Readable scenario plans (T17). Fixed, stdin-only entrypoint: no database,
 * file paths or executable input. Input is the server's stored scenario
 * records; the shared route engine computes the downstream plan. Nothing is
 * activated (no flow settings added) and no physical facts are invented.
 *
 * stdin:  { scenarios: [{ id, name, createdAt, seed, result }] }
 * stdout: { version: 1, scenarios: [{ id, name, createdAt, status, error?, rows: { turning, drilling, deburring, gkm }, warnings }] }
 */
const MAX_SCENARIOS = 50;
const MAX_ROWS = 20_000;

type PlanRow = {
  id: string; workOrder: string; product: string; quantity: number; resourceId: string;
  start: number | null; end: number | null; readyAt: number | null; setupHours: number | null;
  wait: string; source: string; status: "Planlandı" | "Çalışıyor" | "Fiili" | "Planlanamadı" | "Tarihsiz"; note: string;
};
type Output = { id: string; name: string; createdAt: string; status: "ok" | "invalid"; error?: string; rows: Record<"turning" | "drilling" | "deburring" | "gkm", PlanRow[]>; warnings: Array<{ code: string; product: string; batchId: string; message: string }> };

const finite = (value: unknown): number | null => typeof value === "number" && Number.isFinite(value) && value > 0 ? value : null;
const text = (value: unknown): string => typeof value === "string" ? value.slice(0, 500) : value == null ? "" : String(value).slice(0, 500);
const SOURCE_LABEL: Record<string, string> = { wip: "Yarı mamul", "current-turning": "Mevcut Torna işi", "turning-plan": "Torna planı" };

function planScenario(record: { id: unknown; name: unknown; createdAt: unknown; seed: unknown; result: unknown }): Output {
  const output: Output = { id: text(record.id), name: text(record.name), createdAt: text(record.createdAt), status: "ok", rows: { turning: [], drilling: [], deburring: [], gkm: [] }, warnings: [] };
  try {
    const raw = record.seed as PlanningSeed;
    if (!raw || ![raw.orders, raw.products, raw.machines, raw.preferences].every(Array.isArray)) throw Error("Senaryo girdisi geçersiz.");
    if (raw.productionArea === "cubuk-filtre") throw Error("Çubuk Filtre senaryoları bu plan sayfalarına alınmaz.");
    const batches = (record.result as { batches?: unknown })?.batches;
    if (!Array.isArray(batches) || batches.length > MAX_ROWS) throw Error("Senaryo sonucu geçersiz veya çok büyük.");
    // Same migration as loading the scenario in the app; any change to the
    // stored process data is reported, never hidden.
    const seed = migratePlanningSeed(structuredClone(raw));
    if (JSON.stringify(raw.processMasterData ?? null) !== JSON.stringify(seed.processMasterData ?? null)) {
      output.warnings.push({ code: "migrated-process-data", product: "", batchId: "", message: "Senaryo eski veri şemasında; Delme/Çapak Alma/GKM ana verisi uygulamada yükleme sırasındaki gibi güncellenerek hesaplandı." });
    }
    for (const batch of batches as PlannedBatch[]) {
      const planned = batch.status === "planned";
      const start = planned ? finite(batch.start) : null, end = planned ? finite(batch.end) : null;
      output.rows.turning.push({
        id: text(batch.id), workOrder: text(batch.workOrder), product: text(batch.product), quantity: Number(batch.quantity) || 0, resourceId: text(batch.machineId),
        start, end, readyAt: null, setupHours: typeof batch.setupHours === "number" ? batch.setupHours : null, wait: "Bekleme yok", source: "Torna planı",
        status: !planned ? "Planlanamadı" : start === null || end === null ? "Tarihsiz" : "Planlandı",
        note: [batch.locked ? "Kilitli" : "", batch.routeCommitted ? "Rota onaylı" : "", !planned ? text(batch.reason) : ""].filter(Boolean).join(" · "),
      });
    }
    // Recorded Torna work stored in the scenario seed: current jobs (Çalışıyor)
    // and real completed steps (Fiili). Split child lots share their parent's
    // steps, so only root lots count; history without a lot is listed once.
    for (const machine of seed.machines ?? []) {
      const current = machine.currentJob;
      if (!current || !(current.quantity > 0) || !current.product) continue;
      output.rows.turning.push({ id: text(current.batchId ?? `current:${machine.id}`), workOrder: text(current.workOrder), product: text(current.product), quantity: current.quantity,
        resourceId: text(machine.id), start: finite(current.start), end: finite(current.end), readyAt: null, setupHours: null, wait: "Çalışan iş · kayıtlı başlangıç", source: "Mevcut Torna işi",
        status: "Çalışıyor", note: current.remainingQuantity != null && current.remainingQuantity !== current.quantity ? `Kalan ${current.remainingQuantity}` : "" });
    }
    const lotHistory = new Set<string>();
    for (const lot of seed.wipLots ?? []) {
      if (lot.parentLotId) continue;
      if (lot.sourceHistoryEntryId) lotHistory.add(lot.sourceHistoryEntryId);
      for (const step of lot.completedSteps ?? []) if (step.process === "turning") output.rows.turning.push({
        id: text(lot.sourceBatchId ?? lot.id), workOrder: text(lot.workOrder), product: text(lot.product), quantity: step.quantity, resourceId: text(step.resourceId),
        start: finite(step.start), end: finite(step.end), readyAt: null, setupHours: null, wait: "Fiili kayıt · kayıtlı başlangıç ve bitiş", source: "Yarı mamul", status: "Fiili", note: "" });
    }
    for (const entry of seed.productionHistory ?? []) {
      if ((entry.process ?? "turning") !== "turning" || lotHistory.has(entry.id) || !(entry.completedQuantity > 0)) continue;
      output.rows.turning.push({ id: text(entry.sourceBatchId ?? entry.id), workOrder: text(entry.workOrder), product: text(entry.product), quantity: entry.completedQuantity,
        resourceId: text(entry.machineId), start: finite(entry.start), end: finite(entry.completedAt), readyAt: null, setupHours: null, wait: "Fiili kayıt · kayıtlı başlangıç ve bitiş", source: "Üretim arşivi", status: "Fiili", note: text(entry.inventoryStatus) });
    }
    const plan = buildDownstreamProcessPlan(seed, { batches: batches as PlannedBatch[] });
    for (const operation of plan.operations) {
      if (operation.process !== "drilling" && operation.process !== "deburring" && operation.process !== "gkm") continue;
      const start = finite(operation.start), end = finite(operation.end);
      output.rows[operation.process].push({
        id: text(operation.batchId), workOrder: text(operation.workOrder), product: text(operation.product), quantity: operation.quantity, resourceId: text(operation.resourceId),
        start, end, readyAt: finite(operation.readyAt), setupHours: operation.setupHours,
        // The rule label from scheduleStage is the only wait text (no second legacy wait);
        // plans built before the label existed fall back to the workday value.
        wait: operation.waitRuleLabel ? text(operation.waitRuleLabel) : operation.waitWorkdaysBefore ? `${operation.waitWorkdaysBefore} iş günü` : "Bekleme yok",
        source: SOURCE_LABEL[operation.source] ?? operation.source,
        status: operation.actual ? "Fiili" : operation.current ? "Çalışıyor" : start === null || end === null ? "Tarihsiz" : "Planlandı",
        note: [operation.manualOverride ? "Elle yerleşim" : "", operation.flowReason ? text(operation.flowReason) : ""].filter(Boolean).join(" · "),
      });
    }
    for (const warning of plan.warnings) output.warnings.push({ code: warning.code, product: text(warning.product), batchId: text(warning.batchId), message: text(warning.message) });
    for (const job of plan.jobs) if (!job.deliveryReadyAt && job.source !== "wip") output.warnings.push({ code: "undated", product: text(job.product), batchId: text(job.batchId), message: "Teslimata hazır tarihi hesaplanamadı (eksik veya geçersiz rota)." });
    const total = Object.values(output.rows).reduce((sum, rows) => sum + rows.length, 0);
    if (total > MAX_ROWS * 4) throw Error("Senaryo planı satır sınırını aşıyor.");
  } catch (error) {
    output.status = "invalid";
    output.error = error instanceof Error ? error.message.slice(0, 300) : "Senaryo planı hesaplanamadı.";
    output.rows = { turning: [], drilling: [], deburring: [], gkm: [] };
    output.warnings = [];
  }
  return output;
}

try {
  const request = JSON.parse(readFileSync(0, "utf8"));
  if (!request || !Array.isArray(request.scenarios) || request.scenarios.length > MAX_SCENARIOS) throw Error("Senaryo listesi geçersiz.");
  process.stdout.write(JSON.stringify({ version: 1, scenarios: request.scenarios.map(planScenario) }));
} catch {
  process.stdout.write(JSON.stringify({ version: 1, error: "Senaryo planları hesaplanamadı.", scenarios: [] }));
}
